CREATE OR REPLACE FUNCTION "public"."_acotar_pagina"("p_pedido" integer, "p_defecto" integer, "p_maximo" integer) RETURNS integer
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
