    "titulo" "text" NOT NULL,
    "descripcion" "text",
    "vence_en" timestamp with time zone,
    "estado" "public"."estado_agenda" DEFAULT 'pendiente'::"public"."estado_agenda" NOT NULL,
    "responsable_id" "uuid" NOT NULL,
    "creado_por" "uuid" NOT NULL,
    "lead_id" "uuid",
    "vehiculo_id" "uuid",
    "cotizacion_id" "uuid",
    "completada_en" timestamp with time zone,
    "eliminado_en" timestamp with time zone,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "conversacion_id" "uuid"
);


ALTER TABLE "public"."tareas" OWNER TO "postgres";


COMMENT ON TABLE "public"."tareas" IS 'Tarea con responsable y vencimiento. Se escribe sólo por RPC (`tarea_crear`, `tarea_guardar`, `tarea_completar`, `tarea_eliminar`, `reasignar_tarea`). Dar una tarea exige agenda.tareas.asignar; recibirla, agenda.tareas.recibir.';



COMMENT ON COLUMN "public"."tareas"."conversacion_id" IS 'La conversación donde nació la tarea (`/tarea` del chat); la fija `tarea_crear` y no cambia. Sus miembros la leen.';



CREATE OR REPLACE FUNCTION "public"."_agenda_tarea_datos"("p_actual" "public"."tareas", "p_datos" "jsonb") RETURNS "public"."tareas"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare v public.tareas := p_actual; v_k text;
begin
  if p_datos is null or jsonb_typeof(p_datos) <> 'object' then
    raise exception 'Los datos de una tarea tienen que ser un objeto.' using errcode = '22023';
  end if;
  for v_k in select jsonb_object_keys(p_datos) loop
    if v_k not in ('titulo', 'descripcion', 'vence_en', 'responsable_id', 'lead_id', 'vehiculo_id', 'cotizacion_id') then
      raise exception 'El dato «%» no es de una tarea.', v_k using errcode = '22023', hint = v_k;
    end if;
  end loop;
  if p_datos ? 'titulo' then v.titulo := btrim(p_datos ->> 'titulo'); end if;
  if v.titulo is null or char_length(v.titulo) not between 1 and 120 then
    raise exception 'Escribe un título de hasta 120 caracteres.' using errcode = '22023', hint = 'titulo';
  end if;
  if p_datos ? 'descripcion' then v.descripcion := nullif(btrim(p_datos ->> 'descripcion'), ''); end if;
  if char_length(v.descripcion) > 2000 then
    raise exception 'La descripción admite hasta 2.000 caracteres.' using errcode = '22023', hint = 'descripcion';
  end if;
  if p_datos ? 'vence_en' then
    v.vence_en := public._agenda_fecha(p_datos -> 'vence_en', 'vence_en');
    if v.vence_en is distinct from p_actual.vence_en and v.vence_en < now() then
      raise exception 'El vencimiento no puede quedar en el pasado.' using errcode = '23514', hint = 'vence_en';
    end if;
  end if;
  if p_datos ? 'responsable_id' then v.responsable_id := public._uuid_de(p_datos -> 'responsable_id', 'responsable_id'); end if;
  if p_datos ? 'lead_id' then v.lead_id := public._uuid_de(p_datos -> 'lead_id', 'lead_id'); end if;
  if p_datos ? 'vehiculo_id' then
    v.vehiculo_id := public._uuid_de(p_datos -> 'vehiculo_id', 'vehiculo_id');
    if v.vehiculo_id is distinct from p_actual.vehiculo_id then
      perform public._vehiculo_para_nota(v.vehiculo_id, 'vehiculo_id');
    end if;
  end if;
  if p_datos ? 'cotizacion_id' then
    v.cotizacion_id := public._uuid_de(p_datos -> 'cotizacion_id', 'cotizacion_id');
    if v.cotizacion_id is distinct from p_actual.cotizacion_id then
      perform public._agenda_cotizacion(v.cotizacion_id, 'cotizacion_id');
    end if;
  end if;
  return v;
end;
$$;


ALTER FUNCTION "public"."_agenda_tarea_datos"("p_actual" "public"."tareas", "p_datos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_agenda_tarea_tomar"("p_tarea" "uuid") RETURNS "public"."tareas"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare r public.tareas; yo uuid := (select auth.uid());
begin
  perform public.assert_activo();
  select * into r from public.tareas x where x.id = p_tarea for update;
  if not found or r.eliminado_en is not null
     or not coalesce(r.responsable_id = yo or r.creado_por = yo or public.tiene_permiso('agenda.ver_todo')
                     or (r.conversacion_id is not null and public.es_miembro(r.conversacion_id)), false) then
    raise exception 'No encontramos esta tarea.' using errcode = '42501';
  end if;
  return r;
end;
$$;


ALTER FUNCTION "public"."_agenda_tarea_tomar"("p_tarea" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_alcance_de_usuario"("p_usuario" "uuid", "p_clave" "text", "p_origen" "uuid") RETURNS "public"."alcance_permiso"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case when p_origen is null then null
              when bool_or(rp.alcance = 'todos') then 'todos'::public.alcance_permiso
              when bool_or(true) then 'propios'::public.alcance_permiso
         end
  from public.usuarios_roles ur
  join public.roles_permisos rp on rp.rol_id = ur.rol_id
  join public.perfiles p on p.id = ur.usuario_id
  where ur.usuario_id = p_usuario
    and p.activo and not p.bloqueado
    and rp.permiso_clave = p_clave
    and (rp.origen_id is null or rp.origen_id = p_origen);
$$;


ALTER FUNCTION "public"."_alcance_de_usuario"("p_usuario" "uuid", "p_clave" "text", "p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_alerta_demora_avisar"("p_vehiculo" "uuid", "p_titulo" "text", "p_fase" "uuid", "p_fase_nombre" "text", "p_fase_desde" timestamp with time zone, "p_dias" integer, "p_horas" integer, "p_usuario" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_titulo text := 'Vehículo demorado en «' || p_fase_nombre || '»';
  v_cuerpo text := p_titulo || ' lleva ' || floor(extract(epoch from now() - p_fase_desde) / 86400)::int || ' días en la fase (el límite es '
                   || p_dias || ')';
begin
  if exists (select 1 from public.notificaciones n
              where n.referencia_id = p_vehiculo and n.tipo = 'demora_fase' and n.usuario_id = p_usuario
                and n.creado_en > greatest(p_fase_desde, now() - make_interval(hours => p_horas))) then
    return 0;
  end if;
  update public.notificaciones n
     set leida_en = null, creado_en = now(), titulo = v_titulo, cuerpo = v_cuerpo
   where n.referencia_id = p_vehiculo and n.tipo = 'demora_fase' and n.usuario_id = p_usuario and n.accionada_en is null
     and exists (select 1 from public.vehiculos v
                  where v.id = p_vehiculo and v.fase_id = p_fase and v.fase_desde = p_fase_desde and v.eliminado_en is null);
  if found then
    return 1;
  end if;
  perform public.notificar(p_usuario, 'demora_fase', v_titulo, v_cuerpo, 'vehiculo', p_vehiculo, '/logistica/vehiculo/' || p_vehiculo, true)
     from public.vehiculos v
    where v.id = p_vehiculo and v.fase_id = p_fase and v.fase_desde = p_fase_desde and v.eliminado_en is null;
  return case when found then 1 else 0 end;
end;
$$;


ALTER FUNCTION "public"."_alerta_demora_avisar"("p_vehiculo" "uuid", "p_titulo" "text", "p_fase" "uuid", "p_fase_nombre" "text", "p_fase_desde" timestamp with time zone, "p_dias" integer, "p_horas" integer, "p_usuario" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_alertas_destinatarios"("p_clave" "text", "p_origen" "uuid") RETURNS TABLE("usuario_id" "uuid", "todos" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select x.u, x.c = 'todos' and x.l = 'todos' and x.v = 'todos'
    from (
      select c.u,
             public._alcance_de_usuario(c.u, p_clave, p_origen) as c,
             public._alcance_de_usuario(c.u, 'logistica.ver', p_origen) as l,
             public._alcance_de_usuario(c.u, 'vehiculos.ver', p_origen) as v
        from (select distinct ur.usuario_id as u
                from public.usuarios_roles ur
                join public.roles_permisos rp on rp.rol_id = ur.rol_id
               where rp.permiso_clave = p_clave and (rp.origen_id is null or rp.origen_id = p_origen)) c
    ) x
   where p_origen is not null and x.c is not null and x.l is not null and x.v is not null;
$$;


ALTER FUNCTION "public"."_alertas_destinatarios"("p_clave" "text", "p_origen" "uuid") OWNER TO "postgres";


