COMMENT ON FUNCTION "public"."_borrador_formula_empezado_por"("p_creado_por" "uuid") IS 'Interna: quién empezó un borrador de la fórmula, para el PT409 de guardarlo sin su versión. docs/COTIZADOR.md › «Versiones (4.20-1)».';



CREATE OR REPLACE FUNCTION "public"."_buscador_interpretar"("p_texto" "text", OUT "numero" bigint, OUT "texto" "text") RETURNS "record"
    LANGUAGE "plpgsql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $_$
declare
  v_recortado constant text := btrim(coalesce(p_texto, ''));
  v_limpio constant text := btrim(regexp_replace(v_recortado, '^#', ''));
  v_solo_numero boolean;
begin
  if v_limpio = '' or length(v_recortado) > 100 then
    return;
  end if;
  if v_limpio ~ '^[0-9]{1,15}$' then
    numero := v_limpio::bigint;
  end if;
  v_solo_numero := numero is not null and (v_recortado like '#%' or length(v_limpio) < 3);
  if not v_solo_numero and v_limpio ~ '[[:alnum:]]{3}' then
    texto := v_limpio;
  end if;
end $_$;


ALTER FUNCTION "public"."_buscador_interpretar"("p_texto" "text", OUT "numero" bigint, OUT "texto" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_buscador_interpretar"("p_texto" "text", OUT "numero" bigint, OUT "texto" "text") IS 'Qué busca un texto del buscador (7.12): numero (1 a 15 dígitos, con o sin #) y texto (3 letras o dígitos seguidos, salvo «sólo número»). Espejo de interpretarBusqueda() con MINIMO_DE_BUSQUEDA. Puro; lo llaman buscador_leads, buscador_vehiculos y buscador_cotizaciones.';



CREATE OR REPLACE FUNCTION "public"."_campo_impacto"("p_valores" "jsonb"[], "p_tipo" "public"."tipo_campo") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v_total int := coalesce(cardinality(p_valores), 0); v_con int; v_por jsonb := '{}'::jsonb;
begin
  select count(*)::int into v_con from unnest(p_valores) v where public._campo_tiene_valor(v);
  if p_tipo = 'opcion' then
    select coalesce(jsonb_object_agg(t.valor, t.n), '{}'::jsonb) into v_por from (
      select v #>> '{}' as valor, count(*)::int as n from unnest(p_valores) v
      where v is not null and v not in ('null'::jsonb, '""'::jsonb) group by 1) t;
  elsif p_tipo = 'multi_opcion' then
    select coalesce(jsonb_object_agg(t.valor, t.n), '{}'::jsonb) into v_por from (
      select e.valor, count(*)::int as n from unnest(p_valores) v
      cross join lateral jsonb_array_elements_text(case when jsonb_typeof(v) = 'array' then v else '[]'::jsonb end) as e (valor)
      where v is not null group by 1) t;
  end if;
  return jsonb_build_object('total', v_total, 'con_valor', v_con, 'sin_valor', v_total - v_con, 'por_opcion', v_por);
end;
$$;


ALTER FUNCTION "public"."_campo_impacto"("p_valores" "jsonb"[], "p_tipo" "public"."tipo_campo") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_campo_limite"("p_cambios" "jsonb", "p_clave" "text", "p_vigente" numeric) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if p_cambios is null or not p_cambios ? p_clave then return p_vigente; end if;
  if p_cambios -> p_clave = 'null'::jsonb then return null; end if;
  if jsonb_typeof(p_cambios -> p_clave) <> 'number' then
    raise exception 'El % tiene que ser un número.', case when p_clave = 'minimo' then 'mínimo' else 'máximo' end
      using errcode = '22023', hint = p_clave;
  end if;
  return (p_cambios ->> p_clave)::numeric;
end;
$$;


ALTER FUNCTION "public"."_campo_limite"("p_cambios" "jsonb", "p_clave" "text", "p_vigente" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_campo_nombre_valido"("p_texto" "text", "p_que" "text", "p_largo" integer) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v text := btrim(coalesce(p_texto, ''));
begin
  if v = '' then raise exception 'Falta %.', p_que; end if;
  if length(v) > p_largo then raise exception 'Máximo % caracteres para %.', p_largo, p_que; end if;
  return v;
end;
$$;


ALTER FUNCTION "public"."_campo_nombre_valido"("p_texto" "text", "p_que" "text", "p_largo" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_campo_opciones_validas"("p_opciones" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare v_item jsonb; v_claves text[] := '{}'; v_clave text;
begin
  if p_opciones is null or jsonb_typeof(p_opciones) <> 'array' then
    raise exception 'Las opciones tienen que ser una lista.';
  end if;
  for v_item in select * from jsonb_array_elements(p_opciones) loop
    if jsonb_typeof(v_item) <> 'object' then
      raise exception 'Cada opción necesita una clave y una etiqueta.';
    end if;
    v_clave := v_item ->> 'clave';
    if v_clave is null or v_clave !~ '^[a-z0-9][a-z0-9_]{0,40}$' then
      raise exception 'La clave de una opción usa minúsculas, números y guion bajo.';
    end if;
    if nullif(btrim(v_item ->> 'etiqueta'), '') is null then
      raise exception 'Cada opción necesita una etiqueta.';
    end if;
    if v_clave = any (v_claves) then
      raise exception 'Hay dos opciones con la clave «%».', v_clave;
    end if;
    v_claves := v_claves || v_clave;
  end loop;
end;
$_$;


ALTER FUNCTION "public"."_campo_opciones_validas"("p_opciones" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_campo_rango"("p_tipo" "public"."tipo_campo", "p_minimo" numeric, "p_maximo" numeric, "p_defecto" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if p_minimo is null and p_maximo is null then return; end if;
  if p_tipo not in ('numero', 'moneda') then
    raise exception 'Sólo un número o un monto lleva mínimo y máximo.' using errcode = '22023', hint = 'minimo';
  end if;
  if abs(p_minimo) > 1000000000000 then
    raise exception 'El mínimo es demasiado grande.' using errcode = '22023', hint = 'minimo';
  end if;
  if abs(p_maximo) > 1000000000000 then
    raise exception 'El máximo es demasiado grande.' using errcode = '22023', hint = 'maximo';
  end if;
  if p_minimo > p_maximo then
    raise exception 'El mínimo no puede ser mayor que el máximo.' using errcode = '22023', hint = 'maximo';
  end if;
  if public._valor_fuera_de_rango(p_defecto, p_minimo, p_maximo) then
    raise exception 'El valor por defecto queda fuera del rango.' using errcode = '22023', hint = 'valor_defecto';
  end if;
end;
$$;


ALTER FUNCTION "public"."_campo_rango"("p_tipo" "public"."tipo_campo", "p_minimo" numeric, "p_maximo" numeric, "p_defecto" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_campo_tiene_valor"("p_valor" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select p_valor is not null and p_valor not in ('null'::jsonb, '""'::jsonb, '[]'::jsonb);
$$;


ALTER FUNCTION "public"."_campo_tiene_valor"("p_valor" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_campo_valor_defecto"("p_tipo" "public"."tipo_campo", "p_opciones" "jsonb", "p_valor" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v_claves text[];
begin
  if p_valor is null or p_valor in ('null'::jsonb, '""'::jsonb, '[]'::jsonb) then return null; end if;
  select coalesce(array_agg(o ->> 'clave'), '{}') into v_claves from jsonb_array_elements(coalesce(p_opciones, '[]'::jsonb)) o;
  case
    when p_tipo in ('texto', 'texto_largo') then
      if jsonb_typeof(p_valor) <> 'string' or char_length(p_valor #>> '{}') > 500 then
        raise exception 'El valor por defecto tiene que ser un texto de hasta 500 caracteres.' using errcode = '22023';
      end if;
    when p_tipo in ('numero', 'moneda') then
      if jsonb_typeof(p_valor) <> 'number' then
        raise exception 'El valor por defecto tiene que ser un número.' using errcode = '22023';
      end if;
    when p_tipo = 'booleano' then
      if jsonb_typeof(p_valor) <> 'boolean' then
        raise exception 'El valor por defecto tiene que ser sí o no.' using errcode = '22023';
      end if;
    when p_tipo = 'opcion' then
      if jsonb_typeof(p_valor) <> 'string' or not ((p_valor #>> '{}') = any (v_claves)) then
        raise exception 'El valor por defecto tiene que ser una de las opciones.' using errcode = '22023';
      end if;
    when p_tipo = 'multi_opcion' then
      if jsonb_typeof(p_valor) <> 'array'
         or exists (select 1 from jsonb_array_elements(p_valor) e where jsonb_typeof(e) <> 'string' or not ((e #>> '{}') = any (v_claves))) then
        raise exception 'El valor por defecto tiene que ser una lista de las opciones.' using errcode = '22023';
      end if;
    else
      raise exception 'Un campo de ese tipo no lleva valor por defecto.' using errcode = '22023';
  end case;
  return p_valor;
end;
$$;


ALTER FUNCTION "public"."_campo_valor_defecto"("p_tipo" "public"."tipo_campo", "p_opciones" "jsonb", "p_valor" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_campos_renumerar"("p_filas" "jsonb") RETURNS TABLE("campo_id" "uuid", "orden_nuevo" smallint)
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select (f ->> 'id')::uuid, (row_number() over (order by (f ->> 'orden')::numeric, f ->> 'clave') * 10)::smallint
  from jsonb_array_elements(coalesce(p_filas, '[]'::jsonb)) f;
$$;


ALTER FUNCTION "public"."_campos_renumerar"("p_filas" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_campos_reordenar"("p_filas" "jsonb", "p_campo" "uuid", "p_despues_de" "uuid") RETURNS TABLE("campo_id" "uuid", "orden_nuevo" smallint)
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select q.id, (row_number() over (order by q.posicion, q.clave) * 10)::smallint
  from (
    select (f ->> 'id')::uuid as id, f ->> 'clave' as clave,
      case
        when (f ->> 'id')::uuid = p_campo then
          case when p_despues_de is null then -1.0
               else (select (g ->> 'orden')::numeric from jsonb_array_elements(p_filas) g where (g ->> 'id')::uuid = p_despues_de) + 0.5 end
        else (f ->> 'orden')::numeric
      end as posicion
    from jsonb_array_elements(p_filas) f
  ) q;
$$;


ALTER FUNCTION "public"."_campos_reordenar"("p_filas" "jsonb", "p_campo" "uuid", "p_despues_de" "uuid") OWNER TO "postgres";


