    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from public.perfiles pf where pf.id = p_usuario and pf.activo and not pf.bloqueado)
     and public.usuario_tiene_permiso(p_usuario, 'chat.participar');
$$;


