    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select 40
$$;


ALTER FUNCTION "public"."_diseno_maximo_de_items"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_diseno_modos"("p_modos" "jsonb", "p_buckets" "jsonb", "p_nb" integer, "p_total_en" "text", "p_pos" "jsonb", "p_tipos" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_dup boolean[];
  v_m jsonb;
  v_clave text;
  v_regla text;
  v_ref text;
  v_total text;
begin
  -- Un modo repite la clave de uno anterior.
  select coalesce(array_agg(d.rn > 1 order by d.ord), '{}')
    into v_dup
    from (select x.ord, row_number() over (partition by x.value ->> 'clave' order by x.ord) as rn
            from jsonb_array_elements(p_modos) with ordinality as x(value, ord)) d;
  for i in 1 .. coalesce(array_length(v_dup, 1), 0) loop
    v_m := p_modos -> (i - 1);
    v_clave := v_m ->> 'clave';
    if v_dup[i] then
      perform public._formula_rechazar('modo_duplicado', v_clave,
        format('Hay dos modos de tipo de cambio con la clave «%s».', v_clave));
    end if;
    if p_total_en is null then
      perform public._formula_rechazar('modo_sin_total_en', v_clave,
        format('El modo «%s» trae su propio «total_en», y la fórmula no tiene uno: con un modo el total cambiaría de cuenta.', v_clave));
    end if;
    -- La primera entrada que falla, y qué le pasa: bucket inexistente, repetido o un nodo que no es un tipo de cambio.
    select q.regla, q.ref
      into v_regla, v_ref
      from (select case when not coalesce(p_buckets ? e.bucket, false) then 'modo_bucket_inexistente'
                        when e.rep then 'modo_bucket_repetido'
                        when p_tipos[(p_pos ->> e.nodo)::int] is distinct from 'tipo_cambio' then 'modo_tipo_de_cambio_inexistente'
                   end as regla,
                   case when not coalesce(p_buckets ? e.bucket, false) or e.rep then e.bucket else e.nodo end as ref,
                   e.ord
              from (select x.ord, x.value ->> 'bucket' as bucket, x.value ->> 'nodo' as nodo,
                           row_number() over (partition by x.value ->> 'bucket' order by x.ord) > 1 as rep
                      from jsonb_array_elements(v_m -> 'buckets') with ordinality as x(value, ord)) e) q
     where q.regla is not null
     order by q.ord
     limit 1;
    if v_regla = 'modo_bucket_inexistente' then
      perform public._formula_rechazar('modo_bucket_inexistente', v_clave,
        format('El modo «%s» usa el bucket «%s», que la fórmula no tiene.', v_clave, v_ref));
    elsif v_regla = 'modo_bucket_repetido' then
      perform public._formula_rechazar('modo_bucket_repetido', v_clave,
        format('El modo «%s» llena dos veces el bucket «%s».', v_clave, v_ref));
    elsif v_regla = 'modo_tipo_de_cambio_inexistente' then
      perform public._formula_rechazar('modo_tipo_de_cambio_inexistente', v_clave,
        format('El modo «%s» nombra «%s», que no es un tipo de cambio de la fórmula.', v_clave, v_ref));
    end if;
    v_total := v_m ->> 'total_en';
    if p_tipos[(p_pos ->> v_total)::int] is distinct from 'tipo_cambio' then
      perform public._formula_rechazar('modo_tipo_de_cambio_inexistente', v_clave,
        format('El modo «%s» nombra «%s», que no es un tipo de cambio de la fórmula.', v_clave, v_total));
    end if;
    -- Cada bucket del modo existe en la fórmula y no se repite: llena todos si tiene tantos como ella.
    if jsonb_array_length(v_m -> 'buckets') < p_nb then
      perform public._formula_rechazar('modo_incompleto', v_clave,
        format('El modo «%s» tiene que llenar todos los buckets de la fórmula y le falta alguno.', v_clave));
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."_diseno_modos"("p_modos" "jsonb", "p_buckets" "jsonb", "p_nb" integer, "p_total_en" "text", "p_pos" "jsonb", "p_tipos" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_diseno_nivel"("p_nivel" "text", "p_donde" "text", "p_niveles" "jsonb", "p_retirados" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
begin
  if p_nivel is null or p_nivel = 'todos' then return; end if;
  if not coalesce(p_niveles ? p_nivel, false) then
    perform public._formula_rechazar('nivel_inexistente', p_donde,
      format('«%s» usa el nivel «%s», que no existe.', p_donde, p_nivel));
  end if;
  if coalesce(p_retirados ? p_nivel, false) then
    perform public._formula_rechazar('nivel_retirado', p_donde,
      format('«%s» usa el nivel «%s», que está retirado: elige otro para esta celda o sección.', p_donde, p_nivel));
  end if;
end;
$$;


ALTER FUNCTION "public"."_diseno_nivel"("p_nivel" "text", "p_donde" "text", "p_niveles" "jsonb", "p_retirados" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_diseno_secciones"("p_secs" "jsonb", "p_tarjeta" "jsonb", "p_ids" "text"[], "p_tipos" "text"[], "p_ops" "text"[], "p_salidas" "text"[], "p_sobres" boolean[], "p_pcts" "text"[], "p_pos" "jsonb", "p_cond" "jsonb", "p_req" "jsonb", "p_niveles" "jsonb", "p_retirados" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_n int := coalesce(array_length(p_ids, 1), 0);
  v_aver text[] := array_fill(null::text, array[v_n]);     -- con qué nivel de ver se dibuja el nodo (nulo: no se dibuja)
  v_aedit text[] := array_fill(null::text, array[v_n]);    -- con qué nivel de editar
  v_atajo boolean[] := array_fill(false, array[v_n]);      -- ya tiene unos atajos
  v_visto boolean[] := array_fill(false, array[v_n]);      -- ya es un secundario de la tarjeta
  v_a_nodo int[] := '{}'::int[];                           -- los atajos, en el orden del diseño: nodo, niveles de su sección
  v_a_ver text[] := '{}'::text[];
  v_a_edit text[] := '{}'::text[];
  v_dup boolean[];
  v_s jsonb;
  v_its jsonb;
  v_it jsonb;
  v_sid text;
  v_hver text;
  v_hedit text;
  v_ver text;
  v_edit text;
  v_tipo text;
  v_nodo text;
  v_ntipo text;
  v_efecto text;
  v_pct text;
  v_esp boolean;
  j int;
  l int;
begin
  -- §2 las secciones, en orden. Una sección repite el id de una anterior.
  select coalesce(array_agg(d.rn > 1 order by d.ord), '{}')
    into v_dup
    from (select x.ord, row_number() over (partition by x.value ->> 'id' order by x.ord) as rn
            from jsonb_array_elements(p_secs) with ordinality as x(value, ord)) d;
  for i in 1 .. coalesce(array_length(v_dup, 1), 0) loop
    v_s := p_secs -> (i - 1);
    v_sid := v_s ->> 'id';
    if v_dup[i] then
      perform public._formula_rechazar('seccion_duplicada', v_sid, format('Hay dos secciones con el id «%s».', v_sid));
    end if;
    perform public._diseno_nivel(v_s ->> 'nivel_ver', v_sid, p_niveles, p_retirados);
    perform public._diseno_nivel(v_s ->> 'nivel_editar', v_sid, p_niveles, p_retirados);
    v_hver := coalesce(v_s ->> 'nivel_ver', 'todos');
    v_hedit := coalesce(v_s ->> 'nivel_editar', 'todos');
    -- Lo lo que no se ve no se edita: ver restringido con editar abierto se rechaza (ver abierto con editar restringido vale).
    if v_hver <> 'todos' and v_hedit = 'todos' then
      perform public._formula_rechazar('editar_sin_ver', v_sid, format('«%s» se ve sólo con un nivel y se edita sin él: lo que no se ve no se edita. Ponle también un nivel de edición.', v_sid));
    end if;
    v_its := v_s -> 'items';

    for k in 0 .. jsonb_array_length(v_its) - 1 loop
      v_it := v_its -> k;
      v_tipo := v_it ->> 'tipo';
      v_nodo := v_it ->> 'nodo';
      j := (p_pos ->> v_nodo)::int;
      if j is null then
        perform public._formula_rechazar('nodo_inexistente', v_nodo,
          format('El diseño nombra «%s», que no es un nodo de la fórmula.', v_nodo));
      end if;
      v_ntipo := p_tipos[j];
      v_esp := v_ntipo = 'calculo' and p_ops[j] = 'porcentaje_de';
      v_ver := v_hver;
      v_edit := v_hedit;

      if v_tipo = 'celda' then
        if v_ntipo in ('opcion', 'bandera') then
          perform public._formula_rechazar('celda_no_es_valor', v_nodo,
            format('«%s» no se dibuja como celda: la variante va como chips y una bandera como interruptor.', v_nodo));
        end if;
        if v_it ? 'secundario' and not v_esp then
          perform public._formula_rechazar('secundario_sin_porcentaje', v_nodo,
            format('«%s» lleva un secundario y no es un porcentaje de otro monto.', v_nodo));
        end if;
        if v_esp and p_sobres[j] and not (v_it ? 'secundario') then
          perform public._formula_rechazar('par_sin_secundario', v_nodo,
            format('«%s» es un monto con su porcentaje y se sobrescribe: el par es una sola celda con su secundario.', v_nodo));
        end if;
        perform public._diseno_nivel(v_it ->> 'nivel_ver', v_nodo, p_niveles, p_retirados);
        perform public._diseno_nivel(v_it ->> 'nivel_editar', v_nodo, p_niveles, p_retirados);
        v_ver := coalesce(v_it ->> 'nivel_ver', v_hver);
        v_edit := coalesce(v_it ->> 'nivel_editar', v_hedit);
      elsif v_tipo = 'atajos' then
        if v_ntipo <> 'tabla' then
          perform public._formula_rechazar('atajos_no_es_tabla', v_nodo,
            format('Los atajos de «%s» van sobre un nodo de tabla, y ese nodo no lo es.', v_nodo));
        end if;
        if not p_sobres[j] then
          perform public._formula_rechazar('atajos_no_sobrescribible', v_nodo,
            format('Los atajos de «%s» eligen una fila y dejan su valor como sugerido: la tabla tiene que poder sobrescribirse.', v_nodo));
        end if;
      elsif v_tipo = 'variante' then
        if v_ntipo <> 'opcion' then
          perform public._formula_rechazar('variante_no_es_opcion', v_nodo,
            format('«%s» no es la variante de la fórmula.', v_nodo));
        end if;
      elsif v_tipo = 'interruptor' then
        if v_ntipo <> 'bandera' then
          perform public._formula_rechazar('interruptor_no_es_bandera', v_nodo,
            format('«%s» no es una bandera: un interruptor la enciende.', v_nodo));
        end if;
        -- «Habilita» apaga lo que la bandera condiciona o pide; «muestra», sólo lo que condiciona.
        v_efecto := v_it ->> 'efecto';
        if not (p_cond ? v_nodo) and not (v_efecto = 'habilita' and p_req ? v_nodo) then
          perform public._formula_rechazar('interruptor_sin_efecto', v_nodo,
            format('La bandera «%s» no condiciona ningún nodo: su interruptor no haría nada.', v_nodo));
        end if;
      elsif v_tipo = 'subtotal' then
        if v_ntipo <> 'calculo' then
          perform public._formula_rechazar('subtotal_no_es_calculo', v_nodo,
            format('«%s» no es un cálculo: un subtotal se dibuja desde uno.', v_nodo));
        end if;
      end if;

      -- El total, lo que va aparte y la variante los recibe todo el mundo (D7). «Lo que va aparte» incluye el porcentaje que muestra una celda con
      -- secundario y la bandera de un interruptor (4-9): se dibujan con el nivel de su ítem y la base los manda igual.
      if v_ver <> 'todos'
         and (v_tipo = 'variante' or (v_tipo in ('celda', 'subtotal') and p_salidas[j] in ('total', 'aparte'))) then
        perform public._formula_rechazar('nivel_no_admitido', v_nodo,
          format('«%s» se muestra a todos: el total, lo que va aparte y la variante no se pueden restringir a un nivel.', v_nodo));
      end if;
      if v_ver <> 'todos' and v_tipo = 'celda' and v_it ? 'secundario' and p_salidas[(p_pos ->> p_pcts[j])::int] in ('total', 'aparte') then
        perform public._formula_rechazar('nivel_no_admitido', p_pcts[j],
          format('«%s» se muestra a todos: el total, lo que va aparte y la variante no se pueden restringir a un nivel.', p_pcts[j]));
      end if;
      if v_ver <> 'todos' and v_tipo = 'interruptor' and p_salidas[j] in ('total', 'aparte') then
        perform public._formula_rechazar('nivel_no_admitido', v_nodo,
          format('«%s» se muestra a todos: el total, lo que va aparte y la variante no se pueden restringir a un nivel.', v_nodo));
      end if;
      -- Una celda con su nivel de ver restringido y el de editar abierto (la sección ya revisada no lo tiene: sólo lo rompe el nivel propio de la celda).
      if v_tipo = 'celda' and v_ver <> 'todos' and v_edit = 'todos' then
        perform public._formula_rechazar('editar_sin_ver', v_nodo, format('«%s» se ve sólo con un nivel y se edita sin él: lo que no se ve no se edita. Ponle también un nivel de edición.', v_nodo));
      end if;

      -- Dónde se dibuja el valor del nodo (y el del porcentaje de un par); un segundo dibujo es `nodo_repetido`.
      if v_tipo = 'atajos' then
        if v_atajo[j] then
          perform public._formula_rechazar('nodo_repetido', v_nodo, format('«%s» aparece dos veces en el diseño.', v_nodo));
        end if;
        v_atajo[j] := true;
        v_a_nodo := array_append(v_a_nodo, j);
        v_a_ver := array_append(v_a_ver, v_hver);
        v_a_edit := array_append(v_a_edit, v_hedit);
      else
        if v_aver[j] is not null then
          perform public._formula_rechazar('nodo_repetido', v_nodo, format('«%s» aparece dos veces en el diseño.', v_nodo));
        end if;
        v_aver[j] := v_ver;
        v_aedit[j] := v_edit;
        if v_tipo = 'celda' and v_it ? 'secundario' then
          v_pct := p_pcts[j];
          l := (p_pos ->> v_pct)::int;
          if v_aver[l] is not null then
            perform public._formula_rechazar('nodo_repetido', v_pct, format('«%s» aparece dos veces en el diseño.', v_pct));
          end if;
          v_aver[l] := v_ver;
          v_aedit[l] := v_edit;
        end if;
      end if;
    end loop;
  end loop;

  -- §3 la tarjeta: el total y sus secundarios (la garantía), que repiten lo que la hoja ya dibuja.
  v_nodo := p_tarjeta ->> 'nodo';
  j := (p_pos ->> v_nodo)::int;
  if j is null then
    perform public._formula_rechazar('nodo_inexistente', v_nodo,
      format('El diseño nombra «%s», que no es un nodo de la fórmula.', v_nodo));
  end if;
  if p_salidas[j] is distinct from 'total' then
    perform public._formula_rechazar('tarjeta_no_es_el_total', v_nodo,
      format('La tarjeta nombra «%s», que no es el total de la fórmula.', v_nodo));
  end if;
  v_its := p_tarjeta -> 'secundarios';
  for k in 0 .. jsonb_array_length(v_its) - 1 loop
    v_nodo := v_its ->> k;
    j := (p_pos ->> v_nodo)::int;
    if j is null then
      perform public._formula_rechazar('nodo_inexistente', v_nodo,
        format('El diseño nombra «%s», que no es un nodo de la fórmula.', v_nodo));
    end if;
    if p_salidas[j] is distinct from 'aparte' then
      perform public._formula_rechazar('tarjeta_secundario_no_es_aparte', v_nodo,
        format('«%s» es un secundario de la tarjeta y no es una salida «aparte».', v_nodo));
    end if;
    if v_visto[j] then
      perform public._formula_rechazar('nodo_repetido', v_nodo, format('«%s» aparece dos veces en el diseño.', v_nodo));
    end if;
    v_visto[j] := true;
  end loop;

  -- §4 un atajos va sobre la celda de su nodo (o el porcentaje que ella muestra) y con sus mismos niveles.
  for i in 1 .. coalesce(array_length(v_a_nodo, 1), 0) loop
    j := v_a_nodo[i];
    if v_aver[j] is null then
      perform public._formula_rechazar('atajos_sin_celda', p_ids[j],
        format('Los atajos de «%s» necesitan la celda de ese nodo en el diseño.', p_ids[j]));
    end if;
    if v_aver[j] <> v_a_ver[i] or v_aedit[j] <> v_a_edit[i] then
      perform public._formula_rechazar('nodo_con_dos_niveles', p_ids[j],
        format('Los atajos de «%s» y su celda tienen niveles distintos: tienen que ser los mismos.', p_ids[j]));
    end if;
  end loop;

  -- §5 lo que la hoja tiene que dibujar sí o sí, en el orden de la fórmula: todo input y constante, la variante y las banderas que
  -- condicionan algo o piden un dato.
  for n in 1 .. v_n loop
    if v_aver[n] is null
       and (p_tipos[n] in ('input', 'constante', 'opcion')
            or (p_tipos[n] = 'bandera' and (p_cond ? p_ids[n] or p_req ? p_ids[n]))) then
      perform public._formula_rechazar('nodo_sin_seccion', p_ids[n],
        format('«%s» no está en ninguna sección del diseño.', p_ids[n]));
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."_diseno_secciones"("p_secs" "jsonb", "p_tarjeta" "jsonb", "p_ids" "text"[], "p_tipos" "text"[], "p_ops" "text"[], "p_salidas" "text"[], "p_sobres" boolean[], "p_pcts" "text"[], "p_pos" "jsonb", "p_cond" "jsonb", "p_req" "jsonb", "p_niveles" "jsonb", "p_retirados" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_documento_fecha"("p_cambios" "jsonb", "p_clave" "text") RETURNS "date"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
begin
  if jsonb_typeof(p_cambios -> p_clave) = 'null' then
    return null;
  end if;
  if jsonb_typeof(p_cambios -> p_clave) <> 'string' or (p_cambios ->> p_clave) !~ '^\d{4}-\d{2}-\d{2}$' then
    raise exception 'Esa fecha no es válida.' using errcode = '22023', hint = p_clave;
  end if;
  return (p_cambios ->> p_clave)::date;
exception when datetime_field_overflow or invalid_datetime_format then
  raise exception 'Esa fecha no es válida.' using errcode = '22023', hint = p_clave;
end;
$_$;


ALTER FUNCTION "public"."_documento_fecha"("p_cambios" "jsonb", "p_clave" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_documento_fecha"("p_cambios" "jsonb", "p_clave" "text") IS 'documento_editar: la fecha de esa clave (null o AAAA-MM-DD), o 22023 con la clave como hint. 6.05.';



CREATE OR REPLACE FUNCTION "public"."_documento_puede_tocar"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_subido_por" "uuid", "p_estado" "public"."estado_documento") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select public.puede_unidad(p_vehiculo, p_repuesto, 'logistica.documentos.aprobar', 'repuestos.documentos.aprobar')
      or (p_subido_por = (select auth.uid()) and p_estado = 'subido'
          and public.puede_unidad(p_vehiculo, p_repuesto, 'logistica.documentos.subir', 'repuestos.documentos.subir'));
$$;


ALTER FUNCTION "public"."_documento_puede_tocar"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_subido_por" "uuid", "p_estado" "public"."estado_documento") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_documento_puede_tocar"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_subido_por" "uuid", "p_estado" "public"."estado_documento") IS 'documento_editar y documento_eliminar: quien aprueba en la unidad, o quien lo subió mientras siga «subido» y conserve la clave de subir (6.05 D9). 6.05.';



CREATE TABLE IF NOT EXISTS "public"."tipos_documento" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "flujo_id" "uuid",
    "nombre" "text" NOT NULL,
    "descripcion" "text",
    "activo" boolean DEFAULT true NOT NULL,
    "orden" smallint DEFAULT 0 NOT NULL,
    "visible_portal_permitido" boolean DEFAULT false NOT NULL,
    "proposito" "text",
    "modo_vencimiento" "public"."modo_vencimiento" DEFAULT 'ninguno'::"public"."modo_vencimiento" NOT NULL,
    "vigencia_dias" integer,
    "aviso_dias" integer,
    "formatos" "text"[] DEFAULT '{application/pdf,image/jpeg,image/png,image/webp}'::"text"[] NOT NULL,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "tipos_documento_aviso_dias_check" CHECK ((("aviso_dias" IS NULL) OR ("aviso_dias" >= 0))),
    CONSTRAINT "tipos_documento_vigencia_dias_check" CHECK ((("vigencia_dias" IS NULL) OR ("vigencia_dias" > 0)))
);


ALTER TABLE "public"."tipos_documento" OWNER TO "postgres";


COMMENT ON TABLE "public"."tipos_documento" IS 'Catálogo de documentos del ciclo (título, BL, DUI, factura, evidencia…). Global (flujo_id NULL) o propio de un flujo. Un tipo en uso no se borra: se desactiva. Se escribe sólo por tipo_documento_crear, tipo_documento_guardar, tipo_documento_mover y tipo_documento_eliminar; tipos_documento_con_uso cuenta su uso.';



COMMENT ON COLUMN "public"."tipos_documento"."proposito" IS 'Clave interna de la semilla (titulo, bl…); no se edita en la pantalla.';



COMMENT ON COLUMN "public"."tipos_documento"."modo_vencimiento" IS 'ninguno = no vence; solicitar = quien sube el documento escribe su fecha de vencimiento; renovar = vence solo a los vigencia_dias de subido. Lo hace cumplir la Fase 6 en documentos.vence_el.';



COMMENT ON COLUMN "public"."tipos_documento"."vigencia_dias" IS 'Sólo con renovar: días desde que se sube hasta que vence.';



COMMENT ON COLUMN "public"."tipos_documento"."aviso_dias" IS 'Cuántos días antes de vence_el se avisa; nulo = no avisa. Con renovar, no más que vigencia_dias.';



CREATE OR REPLACE FUNCTION "public"."_documento_tipo_de"("p_vehiculos" "uuid"[], "p_repuesto" "uuid", "p_tipo" "uuid") RETURNS "public"."tipos_documento"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare td public.tipos_documento;
begin
  select * into td from public.tipos_documento t where t.id = p_tipo and t.activo;
  if not found
     or (td.flujo_id is not null and p_repuesto is not null
         and not exists (select 1 from public.flujos f where f.id = td.flujo_id and f.ambito = 'repuestos'))
     or (td.flujo_id is not null and p_repuesto is null
         and exists (select 1 from unnest(p_vehiculos) u join public.vehiculos v on v.id = u
                     where not exists (select 1 from public.flujos f where f.id = td.flujo_id and f.origen_id = v.origen_id))) then
    raise exception 'Ese tipo de documento no existe o no es de este flujo.' using errcode = '22023', hint = 'tipo';
  end if;
  return td;
end;
$$;


ALTER FUNCTION "public"."_documento_tipo_de"("p_vehiculos" "uuid"[], "p_repuesto" "uuid", "p_tipo" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_documento_tipo_de"("p_vehiculos" "uuid"[], "p_repuesto" "uuid", "p_tipo" "uuid") IS 'documento_registrar: el tipo activo, global o del flujo de cada unidad (22023/tipo). 6.05.';



CREATE OR REPLACE FUNCTION "public"."_documento_validar_archivo"("p_ruta" "text", "p_unidades" "uuid"[], "p_nombre" "text", "p_mime" "text", "p_bytes" integer, "p_formatos" "text"[], OUT "o_mime" "text", OUT "o_bytes" integer) RETURNS "record"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $_$
declare v_meta jsonb; v_bytes bigint;
begin
  if p_ruta is null or p_ruta !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{64}\.[a-z0-9]{1,5}$'
     or not (split_part(p_ruta, '/', 1) = any (array(select u::text from unnest(p_unidades) u))) then
    raise exception 'El archivo no está en la carpeta de una de estas unidades.' using errcode = '22023', hint = 'ruta';
  end if;
  if btrim(p_nombre) is null or char_length(btrim(p_nombre)) not between 1 and 200 or p_nombre ~ '[/\\]' then
    raise exception 'Ponle un nombre al archivo (hasta 200 caracteres, sin barras).' using errcode = '22023', hint = 'nombre';
  end if;
  -- Con el candado del objeto y fuera de la cola de limpieza antes de mirarlo (C1.8).
  perform public.storage_gc_rescatar('documentos', p_ruta);
  select o.metadata into v_meta from storage.objects o where o.bucket_id = 'documentos' and o.name = p_ruta;
  if not found then
    raise exception 'El archivo no terminó de subir. Vuelve a intentarlo.' using errcode = '22023', hint = 'ruta';
  end if;
  o_mime := coalesce(v_meta ->> 'mimetype', p_mime);
  v_bytes := coalesce((v_meta ->> 'size')::bigint, p_bytes);
  if o_mime is null or not (o_mime = any (p_formatos)) then
    raise exception 'Ese formato no se admite para este tipo de documento.' using errcode = '22023', hint = 'mime';
  end if;
  if v_bytes is null or v_bytes not between 1 and 26214400 then
    raise exception 'El archivo está vacío o pesa más de 25 MB.' using errcode = '22023', hint = 'bytes';
  end if;
  o_bytes := v_bytes::integer;
end;
$_$;


ALTER FUNCTION "public"."_documento_validar_archivo"("p_ruta" "text", "p_unidades" "uuid"[], "p_nombre" "text", "p_mime" "text", "p_bytes" integer, "p_formatos" "text"[], OUT "o_mime" "text", OUT "o_bytes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_documento_validar_archivo"("p_ruta" "text", "p_unidades" "uuid"[], "p_nombre" "text", "p_mime" "text", "p_bytes" integer, "p_formatos" "text"[], OUT "o_mime" "text", OUT "o_bytes" integer) IS 'documento_registrar: la ruta <unidad>/<sha256>.<ext> en la carpeta de una unidad de la llamada, el nombre (1 a 200, sin barras), el objeto en storage (rescatado de la cola de limpieza), el mime en los formatos del tipo y de 1 byte a 25 MB, con mime y tamaño de la metadata si están (22023 con hint). 6.05.';



CREATE OR REPLACE FUNCTION "public"."_documento_validar_unidades"("p_vehiculos" "uuid"[], "p_repuesto" "uuid") RETURNS "uuid"[]
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare v_n int := coalesce(cardinality(p_vehiculos), 0);
begin
  if (p_repuesto is null) = (v_n = 0) or array_position(p_vehiculos, null) is not null then
    raise exception 'Elige los vehículos o el repuesto del documento.' using errcode = '22023', hint = 'unidad';
  end if;
  if v_n > 100 or v_n <> cardinality(array(select distinct u from unnest(p_vehiculos) u)) then
    raise exception 'Hasta 100 vehículos distintos por documento.' using errcode = '22023', hint = 'vehiculos';
  end if;
  if p_repuesto is not null then
    if not public.puede_repuesto(p_repuesto, 'repuestos.documentos.subir') then
      raise exception 'No puedes subir documentos a este repuesto.' using errcode = '42501';
    end if;
    return array[p_repuesto];
  end if;
  if exists (select 1 from unnest(p_vehiculos) u where not public.puede_vehiculo(u, 'logistica.documentos.subir')) then
    raise exception 'No puedes subir documentos a una de estas unidades.' using errcode = '42501';
  end if;
  return p_vehiculos;
end;
$$;


ALTER FUNCTION "public"."_documento_validar_unidades"("p_vehiculos" "uuid"[], "p_repuesto" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_documento_validar_unidades"("p_vehiculos" "uuid"[], "p_repuesto" "uuid") IS 'documento_registrar: vehículos (1 a 100, sin nulos ni repetidos) o un repuesto (22023/unidad, 22023/vehiculos), con logistica.documentos.subir en cada vehículo o repuestos.documentos.subir en el repuesto (42501). Devuelve las unidades. 6.05.';



CREATE OR REPLACE FUNCTION "public"."_documento_vence"("p_modo" "public"."modo_vencimiento", "p_vigencia" integer, "p_emitido" "date", "p_vence" "date", "p_subido" "date") RETURNS "date"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare v_vence date := p_vence;
begin
  if p_modo = 'ninguno' and v_vence is not null then
    raise exception 'Este tipo de documento no vence: no lleva fecha de vencimiento.' using errcode = '22023', hint = 'vence_el';
  elsif p_modo = 'solicitar' and v_vence is null then
    raise exception 'Este tipo de documento pide la fecha de vencimiento.' using errcode = '22023', hint = 'vence_el';
  elsif p_modo = 'renovar' and v_vence is null and p_vigencia is not null then
    v_vence := coalesce(p_emitido, p_subido) + p_vigencia;
  end if;
  if v_vence is not null and p_emitido is not null and v_vence < p_emitido then
    raise exception 'El vencimiento no puede ser antes de la emisión.' using errcode = '22023', hint = 'vence_el';
  end if;
  return v_vence;
end;
$$;


ALTER FUNCTION "public"."_documento_vence"("p_modo" "public"."modo_vencimiento", "p_vigencia" integer, "p_emitido" "date", "p_vence" "date", "p_subido" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_documento_vence"("p_modo" "public"."modo_vencimiento", "p_vigencia" integer, "p_emitido" "date", "p_vence" "date", "p_subido" "date") IS 'El vencimiento de un documento según el modo de su tipo (6.05 D7): ninguno con fecha, solicitar sin fecha o vence antes de emitir dan 22023/vence_el; renovar sin fecha la calcula desde la emisión (o la subida) más la vigencia. 6.05.';



CREATE OR REPLACE FUNCTION "public"."_documento_vencimiento_avisar"("p_documento" "uuid", "p_vehiculo" "uuid", "p_titulo" "text", "p_cuerpo" "text", "p_desde" timestamp with time zone, "p_usuario" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (select 1 from public.notificaciones n
              where n.referencia_id = p_documento and n.tipo = 'documento_por_vencer' and n.usuario_id = p_usuario and n.creado_en >= p_desde) then
    return 0;
  end if;
  update public.notificaciones n
     set leida_en = null, creado_en = now(), titulo = p_titulo, cuerpo = p_cuerpo
   where n.referencia_id = p_documento and n.tipo = 'documento_por_vencer' and n.usuario_id = p_usuario and n.accionada_en is null;
  if found then
    return 1;
  end if;
  perform public.notificar(p_usuario, 'documento_por_vencer', p_titulo, p_cuerpo, 'documento', p_documento, '/logistica/vehiculo/' || p_vehiculo, true);
  return 1;
end;
$$;


ALTER FUNCTION "public"."_documento_vencimiento_avisar"("p_documento" "uuid", "p_vehiculo" "uuid", "p_titulo" "text", "p_cuerpo" "text", "p_desde" timestamp with time zone, "p_usuario" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_documento_ya_registrado"("p_ids" "uuid"[], "p_ruta" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if exists (select 1 from unnest(p_ids) i
             where not exists (select 1 from public.documentos d
                               where d.id = i and d.ruta = p_ruta and d.subido_por = (select auth.uid()) and d.eliminado_en is null)) then
    raise exception 'Ese registro ya existe con otros datos. Recarga e intenta de nuevo.' using errcode = '23505', hint = 'id';
  end if;
  return public._documentos_de(p_ids);
end;
$$;


ALTER FUNCTION "public"."_documento_ya_registrado"("p_ids" "uuid"[], "p_ruta" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_documento_ya_registrado"("p_ids" "uuid"[], "p_ruta" "text") IS 'documento_registrar idempotente: con los N ids derivados vivos, la misma ruta y de quien llama devuelve sus filas; si no, 23505/id. 6.05.';



CREATE OR REPLACE FUNCTION "public"."_documentos_de"("p_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'vehiculo_id', d.vehiculo_id, 'repuesto_id', d.repuesto_id,
                                               'actualizado_en', d.actualizado_en) order by d.id), '[]'::jsonb)
  from public.documentos d where d.id = any (p_ids);
$$;


ALTER FUNCTION "public"."_documentos_de"("p_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_documentos_de"("p_ids" "uuid"[]) IS 'documento_registrar: [{id, vehiculo_id, repuesto_id, actualizado_en}] de esos ids, por id. 6.05.';



