COMMENT ON TABLE "public"."embudos" IS 'Embudos de oportunidades de cada persona: sólo los ve y los toca su dueña, y se escriben sólo por RPC (embudo_*). El de por defecto lo crea embudo_por_defecto() la primera vez que hace falta.';



CREATE OR REPLACE FUNCTION "public"."_embudo_mio"("p_embudo" "uuid") RETURNS "public"."embudos"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare e public.embudos;
begin
  select * into e from public.embudos x where x.id = p_embudo and x.usuario_id = (select auth.uid()) for update;
  if not found then
    raise exception 'No encontramos este embudo. Recarga para ver los tuyos.' using errcode = '42501';
  end if;
  return e;
end;
$$;


