CREATE OR REPLACE FUNCTION "public"."_embudo_nombre_libre"("p_usuario" "uuid", "p_nombre" "text", "p_excepto" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
