    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if p_color is null or not (p_color = any (public._etiquetas_paleta())) then
    raise exception 'Elige un color de la paleta.' using errcode = '22023', hint = 'color';
  end if;
  return p_color;
end;
