    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if p_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  if p_actual is distinct from p_esperado then
    raise exception '%', p_mensaje using errcode = 'PT409';
  end if;
end;
$$;


