CREATE OR REPLACE FUNCTION "public"."_fase_aplicar"("p_fila" "public"."fases", "p_datos" "jsonb") RETURNS "public"."fases"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_populate_record(p_fila, coalesce((
    select jsonb_object_agg(key, case
      when key in ('descripcion', 'icono', 'alias_portal', 'descripcion_portal') then coalesce(to_jsonb(nullif(btrim(value #>> '{}'), '')), 'null'::jsonb)
      when key in ('nombre', 'color') then to_jsonb(btrim(value #>> '{}'))
      else value end)
    from jsonb_each(p_datos)), '{}'::jsonb));
$$;


ALTER FUNCTION "public"."_fase_aplicar"("p_fila" "public"."fases", "p_datos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_fase_conflicto"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_actual" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_usuario uuid; v_cuando timestamptz; v_fase text; v_nombre text;
begin
  if p_actual is not null then
    if p_vehiculo is not null then
      select h.usuario_id, h.creado_en into v_usuario, v_cuando from public.historial_fases h
       where h.vehiculo_id = p_vehiculo order by h.creado_en desc, h.id desc limit 1;
    else
      select h.usuario_id, h.creado_en into v_usuario, v_cuando from public.historial_fases h
       where h.repuesto_id = p_repuesto order by h.creado_en desc, h.id desc limit 1;
    end if;
    select f.nombre into v_fase from public.fases f where f.id = p_actual;
  end if;
  if v_cuando is null or v_fase is null then
    raise exception 'Esta unidad ya no está en esa fase.' using errcode = 'PT409', hint = 'conflicto';
  end if;
  if v_usuario is not null and v_usuario = (select auth.uid()) then
    raise exception 'La moviste a «%» % desde otra ventana.', v_fase, public._hace(v_cuando) using errcode = 'PT409', hint = 'conflicto';
  end if;
  if v_usuario is not null then
    select nullif(btrim(p.nombre), '') into v_nombre from public.perfiles p where p.id = v_usuario;
  end if;
  raise exception '% la movió a «%» %.', coalesce(v_nombre, 'Otra persona'), v_fase, public._hace(v_cuando) using errcode = 'PT409', hint = 'conflicto';
end;
$$;


ALTER FUNCTION "public"."_fase_conflicto"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_actual" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_fase_forma"("p_datos" "jsonb", "p_vacio_vale" boolean) RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_clave text;
  v_tipo text;
  v_valor jsonb;
  v_booleanos constant text[] := array['es_inicial', 'es_final', 'es_logistica', 'nota_obligatoria', 'permite_contenedor', 'permite_aduana',
    'cuenta_llegada_repuestos', 'publica_web', 'visible_portal'];
  v_enteros constant text[] := array['demora_dias', 'alerta_cada_horas'];
  v_textos_obligatorios constant text[] := array['nombre', 'color'];
  v_textos constant text[] := array['descripcion', 'icono', 'alias_portal', 'descripcion_portal'];
  v_bien boolean;
begin
  if p_datos is null or jsonb_typeof(p_datos) <> 'object' then
    raise exception 'Faltan los datos de la fase.' using errcode = '22023';
  end if;
  if not p_vacio_vale and p_datos = '{}'::jsonb then
    raise exception 'No hay cambios para guardar.' using errcode = '22023';
  end if;
  for v_clave, v_valor in select key, value from jsonb_each(p_datos) loop
    v_tipo := jsonb_typeof(v_valor);
    if v_clave = any (v_booleanos) then
      v_bien := v_tipo = 'boolean';
    elsif v_clave = any (v_enteros) then
      v_bien := v_tipo = 'null'
        or (v_tipo = 'number' and (v_valor #>> '{}') ~ '^-?[0-9]+$'
            and (v_valor #>> '{}')::numeric between -2147483648 and 2147483647);
    elsif v_clave = any (v_textos_obligatorios) then
      v_bien := v_tipo = 'string';
    elsif v_clave = any (v_textos) then
      v_bien := v_tipo in ('string', 'null');
    else
      raise exception 'El dato «%» no se cambia desde una fase.', v_clave using errcode = '22023', hint = v_clave;
    end if;
    if not v_bien then
      raise exception 'El dato «%» no tiene el formato esperado.', v_clave using errcode = '22023', hint = v_clave;
    end if;
  end loop;
end $_$;


ALTER FUNCTION "public"."_fase_forma"("p_datos" "jsonb", "p_vacio_vale" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_fase_unico"("p_restriccion" "text", "p_nombre" "text") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if p_restriccion = 'fases_flujo_id_nombre_key' then
    raise exception 'Ya hay una fase «%» en este flujo.', p_nombre using errcode = '23505', hint = 'nombre';
  elsif p_restriccion = 'fases_llegada_repuestos_unica' then
    raise exception 'Otra fase de este flujo ya cuenta la llegada de repuestos.' using errcode = '23505', hint = 'cuenta_llegada_repuestos';
  elsif p_restriccion = 'fases_pkey' then
    raise exception 'Esa fase ya existe.' using errcode = '23505', hint = 'id';
  end if;
end $$;


ALTER FUNCTION "public"."_fase_unico"("p_restriccion" "text", "p_nombre" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_fase_uso"("p_fase" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v public.fases;
  v_tope constant int := 50;
  v_paradas int;
  v_historial boolean;
  v_esperas int;
  v_unica_inicial boolean;
  v_accion text;
  v_motivo text;
begin
  select * into v from public.fases where id = p_fase;
  if not found then
    return null;
  end if;
  -- vehiculos_fase_id_idx y repuestos_items_fase_id_idx, cada lado con su tope; la suma, acotada.
  v_paradas := least(v_tope + 1,
    (select count(*) from (select 1 from public.vehiculos x where x.fase_id = p_fase limit v_tope + 1) q)
    + (select count(*) from (select 1 from public.repuestos_items x where x.fase_id = p_fase limit v_tope + 1) q))::int;
  -- historial_fases_a_fase_id_idx y historial_fases_de_fase_id_idx.
  v_historial := exists (select 1 from public.historial_fases h where h.a_fase_id = p_fase)
    or exists (select 1 from public.historial_fases h where h.de_fase_id = p_fase);
  -- fases_requisitos_espera_fase_id_idx.
  v_esperas := (select count(*) from (select 1 from public.fases_requisitos r where r.espera_fase_id = p_fase limit v_tope + 1) q)::int;
  -- Una inicial jubilada no sostiene el flujo: sólo cuenta si está activa.
  v_unica_inicial := v.activa and v.es_inicial
    and not exists (select 1 from public.fases o where o.flujo_id = v.flujo_id and o.id <> p_fase and o.es_inicial and o.activa);

  if not v.activa and (v_paradas > 0 or v_historial) then
    v_accion := 'bloqueada'; v_motivo := 'ya_jubilada';
  elsif v_paradas > 0 then
    v_accion := 'jubilar'; v_motivo := 'paradas';
  elsif v_historial then
    v_accion := 'jubilar'; v_motivo := 'historial';
  elsif v_esperas > 0 then
    v_accion := 'bloqueada'; v_motivo := 'esperas';
  elsif v_unica_inicial then
    v_accion := 'bloqueada'; v_motivo := 'unica_inicial';
  else
    v_accion := 'eliminar'; v_motivo := null;
  end if;

  return jsonb_build_object('accion', v_accion, 'motivo', v_motivo, 'paradas', v_paradas, 'hay_historial', v_historial,
    'esperas', v_esperas, 'unica_inicial', v_unica_inicial);
end $$;


ALTER FUNCTION "public"."_fase_uso"("p_fase" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_fase_uso"("p_fase" "uuid") IS 'Lo que usa una fase y qué haría eliminarla: {accion: jubilar|eliminar|bloqueada, motivo, paradas, hay_historial, esperas, unica_inicial}. Conteos con tope 50 (lee 51). Regla única de fase_impacto y fase_eliminar; sin EXECUTE para authenticated.';



CREATE OR REPLACE FUNCTION "public"."_fase_validar"("p_fila" "public"."fases", "p_claves" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
begin
  if coalesce(p_fila.nombre, '') = '' then
    raise exception 'La fase necesita un nombre.' using errcode = '22023', hint = 'nombre';
  end if;
  if 'nombre' = any (p_claves) and char_length(p_fila.nombre) > 60 then
    raise exception 'El nombre de la fase tiene hasta 60 caracteres.' using errcode = '22023', hint = 'nombre';
  end if;
  if 'descripcion' = any (p_claves) and char_length(p_fila.descripcion) > 500 then
    raise exception 'La descripción tiene hasta 500 caracteres.' using errcode = '22023', hint = 'descripcion';
  end if;
  if 'descripcion_portal' = any (p_claves) and char_length(p_fila.descripcion_portal) > 500 then
    raise exception 'La descripción tiene hasta 500 caracteres.' using errcode = '22023', hint = 'descripcion_portal';
  end if;
  if 'alias_portal' = any (p_claves) and char_length(p_fila.alias_portal) > 60 then
    raise exception 'El nombre para el cliente tiene hasta 60 caracteres.' using errcode = '22023', hint = 'alias_portal';
  end if;
  if p_fila.color is null or p_fila.color !~ '^#[0-9a-fA-F]{6}$' then
    raise exception 'El color va como #rrggbb.' using errcode = '22023', hint = 'color';
  end if;
  if 'icono' = any (p_claves) and p_fila.icono !~ '^[a-z0-9-]{1,40}$' then
    raise exception 'El ícono no tiene el formato esperado.' using errcode = '22023', hint = 'icono';
  end if;
  if p_fila.demora_dias < 0 then
    raise exception 'La demora va en días enteros, desde 0.' using errcode = '22023', hint = 'demora_dias';
  end if;
  if p_fila.alerta_cada_horas not between 1 and 720 then
    raise exception 'La alerta se repite cada 1 a 720 horas.' using errcode = '22023', hint = 'alerta_cada_horas';
  end if;
  if p_fila.es_inicial and p_fila.es_final then
    raise exception 'Una fase no puede ser inicial y final a la vez.' using errcode = '22023', hint = 'es_final';
  end if;
  if p_fila.visible_portal and p_fila.alias_portal is null then
    raise exception 'Para mostrarla en el portal escribe su nombre para el cliente.' using errcode = '22023', hint = 'alias_portal';
  end if;
  if p_fila.publica_web and not public.flujo_regla_activa(p_fila.flujo_id, 'vitrina_web') then
    raise exception 'La vitrina web está apagada en este flujo.' using errcode = '23514', hint = 'publica_web';
  end if;
  if p_fila.visible_portal and not public.flujo_regla_activa(p_fila.flujo_id, 'portal_cliente') then
    raise exception 'El portal del cliente está apagado en este flujo.' using errcode = '23514', hint = 'visible_portal';
  end if;
  if p_fila.permite_aduana and not public.flujo_regla_activa(p_fila.flujo_id, 'aduana') then
    raise exception 'La aduana está apagada en este flujo.' using errcode = '23514', hint = 'permite_aduana';
  end if;
  if p_fila.es_logistica and not public.flujo_regla_activa(p_fila.flujo_id, 'logistica') then
    raise exception 'La logística está apagada en este flujo.' using errcode = '23514', hint = 'es_logistica';
  end if;
end $_$;


ALTER FUNCTION "public"."_fase_validar"("p_fila" "public"."fases", "p_claves" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_final_aplicar"("c" "public"."cotizaciones", "p_tomadas" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_ids uuid[]; v_lote uuid; v_n int := 0; v_lead uuid; v_es_cliente boolean; v_tipo uuid; v_a_cliente boolean := false;
begin
  -- 0. (4.26-1, P7 a) Una tomada con un comprobante vigente no se reemplaza: hay que anularlo antes. Quien llama ya tomó esas filas y emitir toma la misma
  --    fila de la cotización, así que no se cuela un comprobante entre esta mirada y los `update`. El texto no dice cuál (su serie y su número): el
  --    inventario del número global de los leads tomaría a esta ayudante, y a quienes la llaman, por una fuente. La pantalla lo muestra en «Comprobantes».
  if exists (select 1 from public.comprobantes cp where cp.cotizacion_id = any (p_tomadas) and cp.cotizacion_id <> c.id and cp.anulado_en is null) then
    raise exception 'La final actual tiene un comprobante vigente: anúlalo antes de marcar otra final.' using errcode = '23514';
  end if;
  -- 1. La final anterior baja a preventa sólo si se tomó en la pasada: por id, nunca por el vehículo (una final que se confirmó después da 23505 en el paso 2).
  update public.cotizaciones x set clase = 'preventa'
   where x.id = any (p_tomadas) and x.id <> c.id and x.clase = 'final' and x.eliminado_en is null;
  -- 2. La cotización, final (una que ya lo es no se toca).
  update public.cotizaciones x set clase = 'final' where x.id = c.id and x.clase <> 'final';
  -- 3. Las preventas tomadas (con la que bajó), a un lote de la papelera de quien marca, como `_cotizacion_a_papelera`. Una con comprobante (sólo anulados, por
  --    el paso 0) baja y queda viva: ninguna cotización con comprobante entra a la papelera (4.26-1, P7 a).
  v_ids := array(select x.id from public.cotizaciones x
                  where x.id = any (p_tomadas) and x.id <> c.id and x.clase = 'preventa' and x.eliminado_en is null
                    and not exists (select 1 from public.comprobantes cp where cp.cotizacion_id = x.id)
                  order by x.id);
  v_n := coalesce(array_length(v_ids, 1), 0);
  if v_n > 0 then
    insert into public.lotes_papelera (tipo, creado_por) values ('cotizaciones', (select auth.uid())) returning id into v_lote;
    update public.cotizaciones x set eliminado_en = now(), eliminado_por = (select auth.uid()), lote_papelera_id = v_lote where x.id = any (v_ids);
    update public.lotes_papelera l set resumen = jsonb_build_object('cantidad', v_n, 'restaurados', 0, 'purgados', 0) where l.id = v_lote;
    perform public._lote_papelera_tocar(v_lote);
    perform public.registrar_actividad('papelera.enviado', 'lotes_papelera', v_lote::text, null, jsonb_build_object('tipo', 'cotizaciones', 'cantidad', v_n));
  end if;
  -- 4. El vínculo (el historial lo escribe su trigger). Cinturón: si ya es de otro lead, el 23514 de P4 a; si ya es de éste, no se escribe.
  update public.vehiculos v set lead_id = c.lead_id where v.id = c.vehiculo_id and v.lead_id is null;
  if not found then
    select v.lead_id into v_lead from public.vehiculos v where v.id = c.vehiculo_id;
    if v_lead is distinct from c.lead_id then
      raise exception 'Este vehículo está vinculado a otro lead. Desvincúlalo antes de marcar la final.' using errcode = '23514';
    end if;
  end if;
  -- 5. El lead, a cliente: al primer tipo activo de esa clase por orden y nombre (el orden de `_tipo_lead_por_defecto`), si no era de esa clase.
  select t.clase = 'cliente' into v_es_cliente from public.leads l join public.tipos_lead t on t.id = l.tipo_lead_id where l.id = c.lead_id;
  if not coalesce(v_es_cliente, false) then
    select t.id into v_tipo from public.tipos_lead t where t.clase = 'cliente' and t.activo order by t.orden, t.nombre limit 1;
    if v_tipo is null then
      raise exception 'No hay un tipo de lead activo de la clase cliente.' using errcode = '23514';
    end if;
    update public.leads l set tipo_lead_id = v_tipo where l.id = c.lead_id;
    v_a_cliente := true;
  end if;
  -- 6. La actividad.
  perform public.registrar_actividad('cotizacion.final', 'cotizaciones', c.id::text, null,
    jsonb_build_object('vehiculo', c.vehiculo_id, 'preventas_a_papelera', v_n, 'lead_a_cliente', v_a_cliente));
end;
$$;


ALTER FUNCTION "public"."_final_aplicar"("c" "public"."cotizaciones", "p_tomadas" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_final_aplicar"("c" "public"."cotizaciones", "p_tomadas" "uuid"[]) IS 'Los efectos de marcar final, llamado con todo tomado (el lead, el vehículo y las cotizaciones p_tomadas): si otra tomada tiene un comprobante vigente, 23514 (4.26-1); la final anterior tomada baja a preventa, c pasa a final, las preventas tomadas sin comprobante van a un lote de la papelera de quien llama (con uno anulado bajan y quedan vivas), el vehículo sin lead queda con el de c (con otro lead, 23514), el lead pasa al primer tipo activo de la clase cliente y la actividad. No toma candados y escribe cotizaciones sólo por id. De nadie: lo llama cotizacion_marcar_final (y el 4.25-1b, cotizacion_crear).';



CREATE OR REPLACE FUNCTION "public"."_final_crear_mirar"("p_vehiculo" "uuid", "p_lead" "uuid", "p_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_hay_final boolean; v_no_puede boolean; v_lead uuid;
begin
  -- P7 a: otra final activa entre las vivas del vehículo (el predicado del índice `cotizaciones_final_por_vehiculo`).
  v_hay_final := exists (select 1 from public.cotizaciones z
                          where z.id = any (p_ids) and z.clase = 'final' and z.estado = 'activa' and z.eliminado_en is null);
  if v_hay_final then
    raise exception 'Este vehículo ya tiene una cotización final activa.' using errcode = '23505', hint = 'vehiculo';
  end if;
  -- P3 a: lo que pide `_cotizacion_a_papelera` para quien crea, sobre cada viva del vehículo (la regla de marcar).
  v_no_puede := exists (select 1 from public.cotizaciones z
                         where z.id = any (p_ids) and z.eliminado_en is null
                           and not (public.puede_cotizacion(z.id, 'cotizaciones.ver')
                                    and case when z.clase = 'final' then public.tiene_permiso('cotizaciones.final.gestionar', z.origen_id)
                                             else public.puede_cotizacion(z.id, 'cotizaciones.editar') or public.tiene_permiso('cotizaciones.moderar') end));
  if v_no_puede then
    raise exception 'Este vehículo tiene preventas que no puedes mandar a la papelera. Pídeselo a quien las cotizó o a quien modera.' using errcode = '42501';
  end if;
  -- P4 a: el vínculo, leído en esta sentencia.
  select v.lead_id into v_lead from public.vehiculos v where v.id = p_vehiculo;
  if v_lead is not null and v_lead <> p_lead then
    raise exception 'Este vehículo está vinculado a otro lead. Desvincúlalo antes de crear la final.' using errcode = '23514', hint = 'vehiculo';
  end if;
end;
$$;


ALTER FUNCTION "public"."_final_crear_mirar"("p_vehiculo" "uuid", "p_lead" "uuid", "p_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_final_crear_mirar"("p_vehiculo" "uuid", "p_lead" "uuid", "p_ids" "uuid"[]) IS 'Lo que crear una final mira sobre su vehículo (4.25-1b), sin tomar candados: otra final activa entre p_ids (23505, P7 a), una viva de p_ids que quien llama no puede mandar a la papelera (42501, P3 a) y el vehículo de otro lead (23514, P4 a). De nadie: la llama cotizacion_crear antes del primer candado y con todo tomado.';



CREATE TABLE IF NOT EXISTS "public"."flujos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "ambito" "public"."ambito_flujo" NOT NULL,
    "origen_id" "uuid",
    "nombre" "text" NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "flujos_check" CHECK ((("ambito" = 'vehiculos'::"public"."ambito_flujo") = ("origen_id" IS NOT NULL)))
);


ALTER TABLE "public"."flujos" OWNER TO "postgres";


COMMENT ON TABLE "public"."flujos" IS 'Un flujo por origen de vehículos y uno para repuestos. Es la unidad de configuración: fases, transiciones, requisitos, reglas y tipos de documento cuelgan de acá.';



CREATE OR REPLACE FUNCTION "public"."_flujo_para_editar"("p_flujo" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "public"."flujos"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v public.flujos;
begin
  if p_flujo is null or not exists (select 1 from public.flujos where id = p_flujo) then
    raise exception 'Este flujo ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  -- El permiso antes del candado: quien no puede no espera ni hace esperar (el ámbito y el origen de un flujo no se editan).
  if not public.puede_configurar_flujo(p_flujo) then
    raise exception 'No tienes permiso para configurar este flujo.' using errcode = '42501';
  end if;
  select * into v from public.flujos where id = p_flujo for no key update;
  if not found then
    raise exception 'Este flujo ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  perform public._exigir_version(v.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este flujo mientras lo editabas.');
  return v;
end $$;


ALTER FUNCTION "public"."_flujo_para_editar"("p_flujo" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_flujo_para_editar"("p_flujo" "uuid", "p_actualizado_en_esperado" timestamp with time zone) IS 'Contrato de la configuración de un flujo (5.01). Orden: inexistente → PT409; sin puede_configurar_flujo → 42501 (antes del candado); for no key update de la fila de flujos (no frena el key share de las FK de historial_fases ni de vehiculos); _exigir_version contra flujos.actualizado_en → PT409. Devuelve la fila bloqueada. Sólo para RPC security definer.';



CREATE OR REPLACE FUNCTION "public"."_flujo_regla_admitida"("p_ambito" "public"."ambito_flujo", "p_regla" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(
    p_regla = any (array['logistica', 'alerta_demora', 'vitrina_web', 'portal_cliente', 'transporte', 'contenedor', 'aduana', 'gastos', 'pagos', 'esperas'])
    and not (p_ambito = 'repuestos' and p_regla in ('vitrina_web', 'portal_cliente', 'aduana')),
    false);
$$;


ALTER FUNCTION "public"."_flujo_regla_admitida"("p_ambito" "public"."ambito_flujo", "p_regla" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_flujo_regla_admitida"("p_ambito" "public"."ambito_flujo", "p_regla" "text") IS 'Si una regla existe en el catálogo de un ámbito (las 10 claves; repuestos sin vitrina_web, portal_cliente ni aduana). Nula = false. Sin EXECUTE para authenticated.';



CREATE OR REPLACE FUNCTION "public"."_flujo_regla_uso"("p_flujo" "uuid", "p_regla" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_tope constant int := 50;
  v_fases jsonb := '[]'::jsonb;
  v_requisitos jsonb := '[]'::jsonb;
begin
  if p_regla in ('vitrina_web', 'portal_cliente', 'aduana', 'logistica') then
    -- fases_flujo_id_nombre_key (por flujo_id): decenas de fases por flujo.
    v_fases := coalesce((
      select jsonb_agg(jsonb_build_object('id', q.id, 'nombre', q.nombre) order by q.orden, q.nombre, q.id)
      from (
        select f.id, f.nombre, f.orden
        from public.fases f
        where f.flujo_id = p_flujo
          and case p_regla
                when 'vitrina_web' then f.publica_web
                when 'portal_cliente' then f.visible_portal
                when 'aduana' then f.permite_aduana
                else f.es_logistica
              end
        order by f.orden, f.nombre, f.id
        limit v_tope + 1
      ) q), '[]'::jsonb);
  elsif p_regla = 'esperas' then
    -- fases_flujo_id_nombre_key y fases_requisitos_fase_id_idx. Los requisitos no tienen borrado lógico: todos están vivos.
    v_requisitos := coalesce((
      select jsonb_agg(jsonb_build_object('id', q.id, 'fase', q.fase, 'fase_nombre', q.fase_nombre)
               order by q.fase_orden, q.fase_nombre, q.orden, q.id)
      from (
        select r.id, f.id as fase, f.nombre as fase_nombre, f.orden as fase_orden, r.orden
        from public.fases f
        join public.fases_requisitos r on r.fase_id = f.id
        where f.flujo_id = p_flujo and r.tipo = 'espera'
        order by f.orden, f.nombre, r.orden, r.id
        limit v_tope + 1
      ) q), '[]'::jsonb);
  end if;
  return jsonb_build_object('bloquea', v_fases <> '[]'::jsonb or v_requisitos <> '[]'::jsonb, 'fases', v_fases, 'requisitos', v_requisitos);
end $$;


ALTER FUNCTION "public"."_flujo_regla_uso"("p_flujo" "uuid", "p_regla" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_flujo_regla_uso"("p_flujo" "uuid", "p_regla" "text") IS 'Lo que usa una regla de un flujo: {bloquea, fases: [{id, nombre}], requisitos: [{id, fase, fase_nombre}]}. Fases (activas y jubiladas) que la marcan; en esperas, los requisitos de espera de sus fases. Listas con tope 50 (lee 51). Regla única de flujo_regla_impacto, flujo_regla_cambiar y flujo_regla_apagar_validar; sin EXECUTE para authenticated.';



CREATE OR REPLACE FUNCTION "public"."_flujo_tocar"("p_flujo" "uuid") RETURNS timestamp with time zone
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  update public.flujos set actualizado_en = actualizado_en where id = p_flujo returning actualizado_en;
$$;


ALTER FUNCTION "public"."_flujo_tocar"("p_flujo" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_flujo_tocar"("p_flujo" "uuid") IS 'Contrato de la configuración de un flujo (5.01): mueve flujos.actualizado_en y devuelve la versión nueva; toda RPC de configuración la devuelve.';



CREATE OR REPLACE FUNCTION "public"."_formula_cambio_y_grupos"("p_nodos" "jsonb", "p_pos" "jsonb", "p_ids" "text"[], "p_tipos" "text"[], "p_formatos" "text"[], "p_total" integer, "p_buckets" "jsonb", "p_total_en" "jsonb", "p_grupos" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_n int := jsonb_array_length(p_nodos);
  v_nodo jsonb;
  v_x jsonb;
  v_id text;
  v_otro text;
  v_clave text;
  v_bucket text;
  v_ref text;
  v_grupo text;
  v_leido text;
  v_reparte boolean;
  v_lugar jsonb;            -- id de grupo → su lugar (1..g): uno por id, en el orden de su primera aparición (el Map de TS)
  v_grupo_ids text[];
  v_visto boolean[] := '{}';
  v_miembros int[];
  v_marcado boolean[] := '{}';  -- por la posición canónica de cada id (la de `p_pos`): un conjunto de ids, como el Set de TS
  i int;
  j int;
  k int;
  g int;
begin
  -- Una clave de tipo de cambio, un solo nodo.
  select t.id, t.primero, t.clave into v_id, v_otro, v_clave
    from (select x.value ->> 'id' as id, x.value ->> 'clave' as clave, x.pos,
                 first_value(x.value ->> 'id') over (partition by x.value ->> 'clave' order by x.pos) as primero,
                 min(x.pos) over (partition by x.value ->> 'clave') as primera
            from jsonb_array_elements(p_nodos) with ordinality as x(value, pos)
           where x.value ->> 'tipo' = 'tipo_cambio') t
   where t.pos > t.primera
   order by t.pos
   limit 1;
  if v_id is not null then
    perform public._formula_rechazar('tipo_de_cambio_repetido', v_id,
      format('«%s» y «%s» son el mismo tipo de cambio («%s»).', v_otro, v_id, v_clave));
  end if;
  -- `buckets` (en el orden de jsonb) y `total_en` nombran nodos `tipo_cambio`.
  for v_bucket, v_ref in select b.key, b.value from jsonb_each_text(coalesce(p_buckets, '{}'::jsonb)) b loop
    j := (p_pos ->> v_ref)::int;
    if j is null or p_tipos[j] <> 'tipo_cambio' then
      perform public._formula_rechazar('tipo_de_cambio_inexistente', 'buckets.' || v_bucket,
        format('%s nombra «%s», que no es un tipo de cambio de la fórmula.', 'buckets.' || v_bucket, v_ref));
    end if;
  end loop;
  if p_total_en is not null then
    v_ref := p_total_en #>> '{}';
    j := (p_pos ->> v_ref)::int;
    if j is null or p_tipos[j] <> 'tipo_cambio' then
      perform public._formula_rechazar('tipo_de_cambio_inexistente', 'total_en',
        format('%s nombra «%s», que no es un tipo de cambio de la fórmula.', 'total_en', v_ref));
    end if;
  end if;

  if jsonb_array_length(coalesce(p_grupos, '[]'::jsonb)) > 0 then
    -- Con grupos (revisarGrupos).
    if p_total_en is null then
      perform public._formula_rechazar('grupos_sin_total_en', null,
        'Con grupos, la fórmula necesita «total_en»: el tipo de cambio que divide el total en Bs.');
    end if;
    select coalesce(jsonb_object_agg(u.id, u.lugar), '{}'::jsonb), array_agg(u.id order by u.lugar)
      into v_lugar, v_grupo_ids
      from (select f.id, row_number() over (order by f.primera) as lugar
              from (select x.value ->> 'id' as id, min(x.pos) as primera
                      from jsonb_array_elements(p_grupos) with ordinality as x(value, pos)
                     group by x.value ->> 'id') f) u;
    v_miembros := array_fill(0, array[coalesce(array_length(v_grupo_ids, 1), 0)]);
    for k in 0 .. jsonb_array_length(p_grupos) - 1 loop
      v_x := p_grupos -> k;
      v_grupo := v_x ->> 'id';
      g := (v_lugar ->> v_grupo)::int;
      if v_visto[g] then
        perform public._formula_rechazar('grupo_duplicado', v_grupo, format('Hay dos grupos con el id «%s».', v_grupo));
      end if;
      v_visto[g] := true;
      if not coalesce(p_buckets ? (v_x ->> 'bucket'), false) then
        perform public._formula_rechazar('bucket_inexistente', v_grupo,
          format('«%s» usa el bucket «%s», que no está en buckets.', v_grupo, v_x ->> 'bucket'));
      end if;
    end loop;
    -- Los miembros (revisarMiembros).
    for i in 1 .. v_n loop
      v_nodo := p_nodos -> (i - 1);
      v_bucket := v_nodo ->> 'bucket';
      if v_bucket is not null and v_bucket <> 'ninguno' then
        perform public._formula_rechazar('bucket_con_grupos', p_ids[i],
          format('«%s» declara su bucket, y con grupos el tipo de cambio es del grupo.', p_ids[i]));
      end if;
      continue when not v_nodo ? 'grupo';
      v_grupo := v_nodo ->> 'grupo';
      g := (v_lugar ->> v_grupo)::int;
      if g is null then
        perform public._formula_rechazar('grupo_inexistente', p_ids[i],
          format('«%s» está en el grupo «%s», que no existe.', p_ids[i], v_grupo));
      else
        v_miembros[g] := v_miembros[g] + 1;
      end if;
      -- Sólo lo que da un monto, con formato usd o moneda, es miembro de un grupo.
      if p_tipos[i] not in ('input', 'constante', 'tabla', 'tramo', 'calculo') or p_formatos[i] not in ('usd', 'moneda') then
        perform public._formula_rechazar('miembro_no_es_monto', p_ids[i],
          format('«%s» está en el grupo «%s» y no es un monto: un miembro es un input, una constante, una tabla, un tramo o un cálculo, con formato usd o moneda.', p_ids[i], v_grupo));
      end if;
      if v_nodo ? 'salida' then
        perform public._formula_rechazar('miembro_con_salida', p_ids[i],
          format('«%s» es una salida y no puede sumar al grupo «%s».', p_ids[i], v_grupo));
      end if;
    end loop;
    -- Doble conteo (revisarDobleConteo): una pasada hacia adelante marca lo que acumula un miembro (el miembro, un cálculo que no
    -- es `porcentaje_de` y lee algo marcado, un `sugerido_de` de algo marcado).
    for i in 1 .. v_n loop
      v_nodo := p_nodos -> (i - 1);
      v_leido := null;
      if p_tipos[i] = 'calculo' and v_nodo ->> 'op' <> 'porcentaje_de' then
        v_x := v_nodo -> 'de';
        for k in 0 .. jsonb_array_length(v_x) - 1 loop
          j := (p_pos ->> (v_x ->> k))::int;
          if j is not null and v_marcado[j] then
            v_leido := v_x ->> k;
            exit;
          end if;
        end loop;
      elsif p_tipos[i] = 'input' and v_nodo ? 'sugerido_de' then
        j := (p_pos ->> (v_nodo ->> 'sugerido_de'))::int;
        if j is not null and v_marcado[j] then
          v_leido := v_nodo ->> 'sugerido_de';
        end if;
      end if;
      if v_nodo ? 'grupo' and v_leido is not null then
        perform public._formula_rechazar('doble_conteo', p_ids[i],
          format('«%s» está en el grupo «%s» y suma «%s», que ya cuenta en un grupo: se contaría dos veces.', p_ids[i], v_nodo ->> 'grupo', v_leido));
      end if;
      if v_nodo ? 'grupo' or v_leido is not null then
        v_marcado[(p_pos ->> p_ids[i])::int] := true;
      end if;
    end loop;
    for g in 1 .. coalesce(array_length(v_grupo_ids, 1), 0) loop
      if v_miembros[g] = 0 then
        perform public._formula_rechazar('grupo_vacio', v_grupo_ids[g], format('El grupo «%s» no tiene nodos.', v_grupo_ids[g]));
      end if;
    end loop;
  else
    -- La forma de la Fase 0 (revisarSinGrupos): el bucket va en el nodo y el total se reparte.
    for i in 1 .. v_n loop
      v_bucket := p_nodos -> (i - 1) ->> 'bucket';
      if v_bucket is not null and v_bucket <> 'ninguno' and not coalesce(p_buckets ? v_bucket, false) then
        perform public._formula_rechazar('bucket_inexistente', p_ids[i],
          format('«%s» usa el bucket «%s», que no está en buckets.', p_ids[i], v_bucket));
      end if;
    end loop;
    -- El total tiene bucket, o es una suma y cada término directo tiene el suyo.
    if p_total is not null then
      v_nodo := p_nodos -> (p_total - 1);
      v_bucket := v_nodo ->> 'bucket';
      if v_bucket is null or v_bucket = 'ninguno' then
        v_reparte := p_tipos[p_total] = 'calculo' and v_nodo ->> 'op' = 'suma';
        if v_reparte then
          v_x := v_nodo -> 'de';
          for k in 0 .. jsonb_array_length(v_x) - 1 loop
            j := (p_pos ->> (v_x ->> k))::int;
            v_bucket := case when j is not null then p_nodos -> (j - 1) ->> 'bucket' end;
            if v_bucket is null or v_bucket = 'ninguno' then
              v_reparte := false;
              exit;
            end if;
          end loop;
        end if;
        if not v_reparte then
          perform public._formula_rechazar('total_sin_tipo_de_cambio', p_ids[p_total],
            format('Sin grupos, el total «%s» necesita un bucket, o ser una suma de nodos que lo tengan.', p_ids[p_total]));
        end if;
      end if;
    end if;
  end if;
end;
$$;


ALTER FUNCTION "public"."_formula_cambio_y_grupos"("p_nodos" "jsonb", "p_pos" "jsonb", "p_ids" "text"[], "p_tipos" "text"[], "p_formatos" "text"[], "p_total" integer, "p_buckets" "jsonb", "p_total_en" "jsonb", "p_grupos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_formula_campos"("p_nodos" "jsonb", "p_tipos" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_id text;
  v_campo text;
begin
  for i in 1 .. jsonb_array_length(p_nodos) loop
    v_id := p_nodos -> (i - 1) ->> 'id';
    v_campo := null;
    if p_tipos[i] = 'campo_vehiculo' then
      v_campo := p_nodos -> (i - 1) ->> 'campo';
      if strpos(v_campo, '.') = 0 then v_campo := null; end if;
    elsif p_tipos[i] = 'tabla' then
      -- Un valor del `match` con punto no puede ser un nodo (un id no lleva puntos): nombra un campo del vehículo.
      select m.value #>> '{}' into v_campo
        from jsonb_each(p_nodos -> (i - 1) -> 'match') m
       where strpos(m.value #>> '{}', '.') > 0
       limit 1;
    end if;
    if v_campo is not null then
      perform public._formula_rechazar('campo_con_punto', v_id,
        format('«%s» nombra el campo «%s»: un campo del vehículo es una columna o la clave de un campo del origen, sin puntos (escribe, por ejemplo, «cilindrada»).', v_id, v_campo));
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."_formula_campos"("p_nodos" "jsonb", "p_tipos" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_formula_forma"("p_def" "jsonb", "p_params" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  c_id constant text := '^[a-z][a-z0-9_]{0,40}$';
  c_forma constant text := 'La fórmula no tiene la forma esperada en «%s».';
  -- Donde JS lee un número como Infinity (y Zod lo rechaza): 2^1024 − 2^970, con el empate hacia Infinity.
  c_infinito constant numeric := power(2::numeric, 1024) - power(2::numeric, 970);
  v_nodos jsonb;
  v_buckets jsonb;
  v_grupos jsonb;
  v_tablas jsonb;
  v_x jsonb;
  v_campo text;
  v_clave text;
  v_donde text;
  i int;
begin
  if jsonb_typeof(p_def) is distinct from 'object' then
    /*F50*/ perform public._formula_rechazar('forma', null, format(c_forma, 'definicion'));
  end if;
  v_nodos := p_def -> 'nodos';
  if jsonb_typeof(v_nodos) is distinct from 'array' then
    /*F51*/ perform public._formula_rechazar('forma', null, format(c_forma, 'definicion.nodos'));
  end if;
  for i in 0 .. jsonb_array_length(v_nodos) - 1 loop
    v_x := v_nodos -> i;
    v_campo := public._formula_forma_nodo(v_x);
    if v_campo is not null then
      /*F52*/ perform public._formula_rechazar('forma', case when jsonb_typeof(v_x -> 'id') = 'string' then v_x ->> 'id' end,
                                               format(c_forma, 'definicion.nodos.' || i || v_campo));
    end if;
  end loop;

  -- bucket → id de un nodo `tipo_cambio`. `ninguno` quiere decir «sin bucket»: no puede ser el nombre de uno.
  if p_def ? 'buckets' then
    v_buckets := p_def -> 'buckets';
    if jsonb_typeof(v_buckets) is distinct from 'object' then
      /*F53*/ perform public._formula_rechazar('forma', null, format(c_forma, 'definicion.buckets'));
    end if;
    for v_clave, v_x in select b.key, b.value from jsonb_each(v_buckets) b loop
      if (v_clave ~ c_id and v_clave <> 'ninguno' and jsonb_typeof(v_x) = 'string' and (v_x #>> '{}') ~ c_id) is not true then
        /*F54*/ perform public._formula_rechazar('forma', null, format(c_forma, 'definicion.buckets.' || v_clave));
      end if;
    end loop;
  end if;
  if p_def ? 'total_en' and (jsonb_typeof(p_def -> 'total_en') = 'string' and (p_def ->> 'total_en') ~ c_id) is not true then
    /*F55*/ perform public._formula_rechazar('forma', null, format(c_forma, 'definicion.total_en'));
  end if;

  -- Los grupos de la hoja: estrictos, con su plazo, su tono y su bucket.
  if p_def ? 'grupos' then
    v_grupos := p_def -> 'grupos';
    if jsonb_typeof(v_grupos) is distinct from 'array' then
      /*F56*/ perform public._formula_rechazar('forma', null, format(c_forma, 'definicion.grupos'));
    end if;
    for i in 0 .. jsonb_array_length(v_grupos) - 1 loop
      v_x := v_grupos -> i;
      v_donde := case when jsonb_typeof(v_x -> 'id') = 'string' then v_x ->> 'id' end;
      if jsonb_typeof(v_x) is distinct from 'object' or (v_x - array['id', 'etiqueta', 'plazo', 'tono', 'bucket']) <> '{}'::jsonb then
        /*F57*/ perform public._formula_rechazar('forma', v_donde, format(c_forma, 'definicion.grupos.' || i));
      end if;
      if (jsonb_typeof(v_x -> 'id') = 'string' and (v_x ->> 'id') ~ c_id) is not true then
        /*F58*/ perform public._formula_rechazar('forma', v_donde, format(c_forma, 'definicion.grupos.' || i || '.id'));
      end if;
      if (jsonb_typeof(v_x -> 'etiqueta') = 'string' and char_length(v_x ->> 'etiqueta') between 1 and 60) is not true then
        /*F59*/ perform public._formula_rechazar('forma', v_donde, format(c_forma, 'definicion.grupos.' || i || '.etiqueta'));
      end if;
      if v_x ? 'plazo' and (jsonb_typeof(v_x -> 'plazo') = 'string' and char_length(v_x ->> 'plazo') between 1 and 40) is not true then
        /*F60*/ perform public._formula_rechazar('forma', v_donde, format(c_forma, 'definicion.grupos.' || i || '.plazo'));
      end if;
      if (jsonb_typeof(v_x -> 'tono') = 'string' and (v_x ->> 'tono') ~ c_id) is not true then
        /*F61*/ perform public._formula_rechazar('forma', v_donde, format(c_forma, 'definicion.grupos.' || i || '.tono'));
      end if;
      if (jsonb_typeof(v_x -> 'bucket') = 'string' and (v_x ->> 'bucket') ~ c_id) is not true then
        /*F62*/ perform public._formula_rechazar('forma', v_donde, format(c_forma, 'definicion.grupos.' || i || '.bucket'));
      end if;
    end loop;
  end if;
  if (p_def - array['nodos', 'buckets', 'total_en', 'grupos']) <> '{}'::jsonb then
    /*F63*/ perform public._formula_rechazar('forma', null, format(c_forma, 'definicion'));
  end if;

  -- params: `{constante: número, …, tablas?: {clave: [filas]}}`. `tablas` va primero (es la clave declarada del Zod).
  if jsonb_typeof(p_params) is distinct from 'object' then
    /*F64*/ perform public._formula_rechazar('forma', null, format(c_forma, 'params'));
  end if;
  if p_params ? 'tablas' then
    v_tablas := p_params -> 'tablas';
    if jsonb_typeof(v_tablas) is distinct from 'object' then
      /*F65*/ perform public._formula_rechazar('forma', 'tablas', format(c_forma, 'params.tablas'));
    end if;
    if exists (select 1 from jsonb_each(v_tablas) t where (t.key ~ c_id and jsonb_typeof(t.value) = 'array') is not true) then
      /*F66*/ perform public._formula_rechazar('forma', 'tablas', format(c_forma, 'params.tablas'));
    end if;
    if exists (
      select 1 from jsonb_each(v_tablas) t cross join lateral jsonb_array_elements(t.value) f(fila)
       where jsonb_typeof(f.fila) is distinct from 'object'
    ) then
      /*F67*/ perform public._formula_rechazar('forma', 'tablas', format(c_forma, 'params.tablas'));
    end if;
    -- Una celda es un número, un texto de hasta 200 o null.
    if exists (
      select 1 from jsonb_each(v_tablas) t cross join lateral jsonb_array_elements(t.value) f(fila)
       cross join lateral jsonb_each(f.fila) c
       where (c.key ~ c_id
              and (jsonb_typeof(c.value) = 'null'
                   or (jsonb_typeof(c.value) = 'string' and char_length(c.value #>> '{}') <= 200)
                   or (jsonb_typeof(c.value) = 'number' and abs(c.value::numeric) < c_infinito))) is not true
    ) then
      /*F68*/ perform public._formula_rechazar('forma', 'tablas', format(c_forma, 'params.tablas'));
    end if;
  end if;
  for v_clave, v_x in select p.key, p.value from jsonb_each(p_params) p loop
    continue when v_clave = 'tablas';
    if (jsonb_typeof(v_x) = 'number' and abs(v_x::numeric) < c_infinito) is not true then
      /*F69*/ perform public._formula_rechazar('forma', v_clave, format(c_forma, 'params.' || v_clave));
    end if;
  end loop;
end;
$_$;


ALTER FUNCTION "public"."_formula_forma"("p_def" "jsonb", "p_params" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_formula_forma_nodo"("p_n" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  c_id constant text := '^[a-z][a-z0-9_]{0,40}$';
  c_campo constant text := '^[a-z][a-z0-9_]*(\.[a-z0-9_]+)*$';
  c_base constant text[] := array['id', 'etiqueta', 'formato', 'descripcion', 'seccion', 'color', 'salida', 'bucket', 'grupo', 'tipo'];
  v_tipo text;
  v_op text;
  v_permitidas text[];
  v_x jsonb;
  v_o jsonb;
  v_min int;
  v_max int;
  v_num numeric;
  v_f float8;
  k int;
begin
  if jsonb_typeof(p_n) is distinct from 'object' then /*F01*/ return ''; end if;
  v_tipo := case when jsonb_typeof(p_n -> 'tipo') = 'string' then p_n ->> 'tipo' end;
  v_permitidas := case v_tipo
    when 'input' then c_base || array['solo_en', 'condicion', 'sugerido_de', 'requerido_si']
    when 'constante' then c_base || array['solo_en', 'condicion', 'texto']
    when 'tipo_cambio' then c_base || array['clave']
    when 'campo_vehiculo' then c_base || array['solo_en', 'campo']
    when 'bandera' then c_base || array['solo_en']
    when 'opcion' then c_base || array['opciones', 'por_defecto']
    when 'tabla' then c_base || array['solo_en', 'condicion', 'sobrescribible', 'tabla', 'match', 'columna']
    when 'tramo' then c_base || array['solo_en', 'condicion', 'sobrescribible', 'tabla', 'sobre', 'columna']
    when 'calculo' then c_base || array['solo_en', 'condicion', 'sobrescribible', 'texto', 'op', 'de']
  end;
  if v_permitidas is null then /*F02*/ return '.tipo'; end if;
  if v_tipo = 'calculo' then
    v_op := case when jsonb_typeof(p_n -> 'op') = 'string' then p_n ->> 'op' end;
    if (v_op in ('suma', 'porcentaje_de', 'multiplicar', 'restar', 'dividir', 'si', 'depreciar', 'redondear')) is not true then
      /*F03*/ return '.op';
    end if;
    v_permitidas := v_permitidas || case v_op
      when 'porcentaje_de' then array['pct']
      when 'depreciar' then array['tabla', 'sobre', 'columna']
      when 'redondear' then array['n']
      else '{}'::text[]
    end;
  end if;
  -- Una clave que el tipo no lleva (también una mal escrita) es un error, no se ignora.
  if (p_n - v_permitidas) <> '{}'::jsonb then /*F04*/ return ''; end if;

  -- Lo común a todo nodo.
  if (jsonb_typeof(p_n -> 'id') = 'string' and (p_n ->> 'id') ~ c_id) is not true then /*F05*/ return '.id'; end if;
  -- `tablas` es la clave de params donde van las filas congeladas (D5): ninguna constante se llama así.
  if v_tipo = 'constante' and p_n ->> 'id' = 'tablas' then /*F06*/ return '.id'; end if;
  if (jsonb_typeof(p_n -> 'etiqueta') = 'string' and char_length(p_n ->> 'etiqueta') between 1 and 80) is not true then
    /*F07*/ return '.etiqueta';
  end if;
  if p_n ? 'formato' and (jsonb_typeof(p_n -> 'formato') = 'string' and (p_n ->> 'formato') in ('usd', 'pct', 'raw', 'moneda')) is not true then
    /*F08*/ return '.formato';
  end if;
  if p_n ? 'descripcion' and (jsonb_typeof(p_n -> 'descripcion') = 'string' and char_length(p_n ->> 'descripcion') <= 300) is not true then
    /*F09*/ return '.descripcion';
  end if;
  if p_n ? 'seccion' and (jsonb_typeof(p_n -> 'seccion') = 'string' and char_length(p_n ->> 'seccion') between 1 and 60) is not true then
    /*F10*/ return '.seccion';
  end if;
  if p_n ? 'color' and (jsonb_typeof(p_n -> 'color') = 'string' and (p_n ->> 'color') in ('amarillo', 'verde', 'naranja')) is not true then
    /*F11*/ return '.color';
  end if;
  if p_n ? 'salida' and (jsonb_typeof(p_n -> 'salida') = 'string' and (p_n ->> 'salida') in ('total', 'base_imponible', 'aparte')) is not true then
    /*F12*/ return '.salida';
  end if;
  if p_n ? 'bucket' and (jsonb_typeof(p_n -> 'bucket') = 'string' and (p_n ->> 'bucket') ~ c_id) is not true then /*F13*/ return '.bucket'; end if;
  if p_n ? 'grupo' and (jsonb_typeof(p_n -> 'grupo') = 'string' and (p_n ->> 'grupo') ~ c_id) is not true then /*F14*/ return '.grupo'; end if;
  -- Lo que un nodo de valor suma (el tipo ya dijo si lo admite).
  if p_n ? 'solo_en' then
    v_x := p_n -> 'solo_en';
    if (jsonb_typeof(v_x) = 'array' and jsonb_array_length(v_x) >= 1) is not true then /*F15*/ return '.solo_en'; end if;
    for k in 0 .. jsonb_array_length(v_x) - 1 loop
      if (jsonb_typeof(v_x -> k) = 'string' and (v_x ->> k) ~ c_id) is not true then /*F16*/ return '.solo_en.' || k; end if;
    end loop;
  end if;
  if (p_n ? 'condicion' or v_op = 'si')
     and (jsonb_typeof(p_n -> 'condicion') = 'string' and (p_n ->> 'condicion') ~ c_id) is not true then
    /*F17*/ return '.condicion';
  end if;
  if p_n ? 'sobrescribible' and jsonb_typeof(p_n -> 'sobrescribible') is distinct from 'boolean' then /*F18*/ return '.sobrescribible'; end if;
  -- El texto con que se escribió la fila (la raíz de `compilarExpresion()`): una `constante` o un `calculo`, de 1 a 2.000 caracteres.
  if p_n ? 'texto' and (jsonb_typeof(p_n -> 'texto') = 'string' and char_length(p_n ->> 'texto') between 1 and 2000) is not true then
    /*F70*/ return '.texto';
  end if;

  -- Lo propio de cada tipo.
  if v_tipo = 'input' then
    if p_n ? 'sugerido_de' and (jsonb_typeof(p_n -> 'sugerido_de') = 'string' and (p_n ->> 'sugerido_de') ~ c_id) is not true then
      /*F19*/ return '.sugerido_de';
    end if;
    if p_n ? 'requerido_si' and (jsonb_typeof(p_n -> 'requerido_si') = 'string' and (p_n ->> 'requerido_si') ~ c_id) is not true then
      /*F20*/ return '.requerido_si';
    end if;
  elsif v_tipo = 'tipo_cambio' then
    if (jsonb_typeof(p_n -> 'clave') = 'string' and (p_n ->> 'clave') ~ c_id) is not true then /*F21*/ return '.clave'; end if;
  elsif v_tipo = 'campo_vehiculo' then
    if (jsonb_typeof(p_n -> 'campo') = 'string' and char_length(p_n ->> 'campo') <= 80 and (p_n ->> 'campo') ~ c_campo) is not true then
      /*F22*/ return '.campo';
    end if;
  elsif v_tipo = 'opcion' then
    v_x := p_n -> 'opciones';
    if (jsonb_typeof(v_x) = 'array' and jsonb_array_length(v_x) >= 2) is not true then /*F23*/ return '.opciones'; end if;
    for k in 0 .. jsonb_array_length(v_x) - 1 loop
      v_o := v_x -> k;
      if (jsonb_typeof(v_o) = 'object' and (v_o - array['clave', 'etiqueta', 'titulo']) = '{}'::jsonb
          and jsonb_typeof(v_o -> 'clave') = 'string' and (v_o ->> 'clave') ~ c_id
          and jsonb_typeof(v_o -> 'etiqueta') = 'string' and char_length(v_o ->> 'etiqueta') between 1 and 60
          and jsonb_typeof(v_o -> 'titulo') = 'string' and char_length(v_o ->> 'titulo') between 1 and 120) is not true then
        /*F24*/ return '.opciones.' || k;
      end if;
    end loop;
    if p_n ? 'por_defecto' and (jsonb_typeof(p_n -> 'por_defecto') = 'string' and (p_n ->> 'por_defecto') ~ c_id) is not true then
      /*F25*/ return '.por_defecto';
    end if;
  elsif v_tipo = 'tabla' then
    if (jsonb_typeof(p_n -> 'tabla') = 'string' and (p_n ->> 'tabla') ~ c_id) is not true then /*F26*/ return '.tabla'; end if;
    if jsonb_typeof(p_n -> 'match') is distinct from 'object' then /*F27*/ return '.match'; end if;
    -- columna de la tabla → un nodo anterior o un campo del vehículo.
    if exists (
      select 1 from jsonb_each(p_n -> 'match') m
       where (m.key ~ c_id and jsonb_typeof(m.value) = 'string' and char_length(m.value #>> '{}') <= 80
              and (m.value #>> '{}') ~ c_campo) is not true
    ) then
      /*F28*/ return '.match';
    end if;
    if (jsonb_typeof(p_n -> 'columna') = 'string' and (p_n ->> 'columna') ~ c_id) is not true then /*F29*/ return '.columna'; end if;
  elsif v_tipo = 'tramo' then
    if (jsonb_typeof(p_n -> 'tabla') = 'string' and (p_n ->> 'tabla') ~ c_id) is not true then /*F30*/ return '.tabla'; end if;
    if (jsonb_typeof(p_n -> 'sobre') = 'string' and (p_n ->> 'sobre') ~ c_id) is not true then /*F31*/ return '.sobre'; end if;
    if (jsonb_typeof(p_n -> 'columna') = 'string' and (p_n ->> 'columna') ~ c_id) is not true then /*F32*/ return '.columna'; end if;
  elsif v_tipo = 'calculo' then
    -- La aridad de cada operación, cerrada.
    v_min := case v_op when 'multiplicar' then 2 when 'restar' then 2 when 'dividir' then 2
                       when 'si' then 1 when 'depreciar' then 1 when 'redondear' then 1 else 1 end;
    v_max := case v_op when 'dividir' then 2 when 'si' then 1 when 'depreciar' then 1 when 'redondear' then 1 end;
    v_x := p_n -> 'de';
    if (jsonb_typeof(v_x) = 'array' and jsonb_array_length(v_x) >= v_min
        and (v_max is null or jsonb_array_length(v_x) <= v_max)) is not true then
      /*F33*/ return '.de';
    end if;
    for k in 0 .. jsonb_array_length(v_x) - 1 loop
      if (jsonb_typeof(v_x -> k) = 'string' and (v_x ->> k) ~ c_id) is not true then /*F34*/ return '.de.' || k; end if;
    end loop;
    if v_op = 'porcentaje_de' and (jsonb_typeof(p_n -> 'pct') = 'string' and (p_n ->> 'pct') ~ c_id) is not true then
      /*F35*/ return '.pct';
    end if;
    if v_op = 'depreciar' then
      if (jsonb_typeof(p_n -> 'tabla') = 'string' and (p_n ->> 'tabla') ~ c_id) is not true then /*F36*/ return '.tabla'; end if;
      if (jsonb_typeof(p_n -> 'sobre') = 'string' and (p_n ->> 'sobre') ~ c_id) is not true then /*F37*/ return '.sobre'; end if;
      if (jsonb_typeof(p_n -> 'columna') = 'string' and (p_n ->> 'columna') ~ c_id) is not true then /*F38*/ return '.columna'; end if;
    end if;
    if v_op = 'redondear' then
      -- `z.int().min(0).max(6)` sobre el número como lo lee JS: 2.0 y 6.0000000000000001 valen; lo que JS redondea a 0, también.
      if jsonb_typeof(p_n -> 'n') is distinct from 'number' then /*F39*/ return '.n'; end if;
      v_num := (p_n -> 'n')::numeric;
      if abs(v_num) < 1e-300 then
        if abs(v_num) > 2.4703282292062327e-324 then /*F40*/ return '.n'; end if;
      elsif abs(v_num) >= 7 then
        /*F41*/ return '.n';
      else
        v_f := v_num::float8;
        if v_f <> trunc(v_f) or v_f < 0 or v_f > 6 then /*F42*/ return '.n'; end if;
      end if;
    end if;
  end if;
  return null;
end;
$_$;


ALTER FUNCTION "public"."_formula_forma_nodo"("p_n" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_formula_rechazar"("p_regla" "text", "p_donde" "text", "p_mensaje" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
begin
  -- RAISE no admite una opción nula: sin `donde`, va sin hint.
  if p_donde is null then
    raise exception using errcode = '22023', message = p_mensaje, detail = p_regla;
  end if;
  raise exception using errcode = '22023', message = p_mensaje, detail = p_regla, hint = p_donde;
end;
$$;


ALTER FUNCTION "public"."_formula_rechazar"("p_regla" "text", "p_donde" "text", "p_mensaje" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_formula_variante"("p_nodos" "jsonb", "p_ids" "text"[], "p_tipos" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_n int := jsonb_array_length(p_nodos);
  v_variante int;       -- la posición de la variante (la última `opcion` vista, como TS)
  v_variante_id text;
  v_claves jsonb;       -- sus claves → true
  v_nodo jsonb;
  v_x jsonb;
  v_clave text;
  i int;
  k int;
begin
  for i in 1 .. v_n loop
    continue when p_tipos[i] <> 'opcion';
    if v_variante is not null then
      perform public._formula_rechazar('opcion_repetida', p_ids[i],
        format('La fórmula tiene dos variantes («%s» y «%s»): va una sola.', v_variante_id, p_ids[i]));
    end if;
    v_nodo := p_nodos -> (i - 1);
    select o.clave into v_clave
      from (select x.value ->> 'clave' as clave, x.pos, min(x.pos) over (partition by x.value ->> 'clave') as primera
              from jsonb_array_elements(v_nodo -> 'opciones') with ordinality as x(value, pos)) o
     where o.pos > o.primera
     order by o.pos
     limit 1;
    if v_clave is not null then
      perform public._formula_rechazar('opcion_clave_repetida', p_ids[i],
        format('La variante «%s» repite la opción «%s».', p_ids[i], v_clave));
    end if;
    select coalesce(jsonb_object_agg(x.value ->> 'clave', true), '{}'::jsonb) into v_claves
      from jsonb_array_elements(v_nodo -> 'opciones') as x(value);
    if v_nodo ? 'por_defecto' and not v_claves ? (v_nodo ->> 'por_defecto') then
      perform public._formula_rechazar('opcion_por_defecto_inexistente', p_ids[i],
        format('La opción por defecto «%s» no es una opción de «%s».', v_nodo ->> 'por_defecto', p_ids[i]));
    end if;
    v_variante := i;
    v_variante_id := p_ids[i];
  end loop;
  -- `solo_en` lee la variante: va después de ella, como toda referencia, y nombra opciones que tiene.
  for i in 1 .. v_n loop
    continue when p_tipos[i] in ('tipo_cambio', 'opcion');
    v_x := p_nodos -> (i - 1) -> 'solo_en';
    continue when v_x is null;
    if v_variante is null then
      perform public._formula_rechazar('solo_en_sin_opcion', p_ids[i],
        format('«%s» dice en qué variantes vale, y la fórmula no tiene variante.', p_ids[i]));
    end if;
    if v_variante > i then
      perform public._formula_rechazar('referencia_hacia_adelante', p_ids[i],
        format('«%s» usa «%s», que está después en la lista: el orden de la lista es el de evaluación y sólo se usa lo anterior.', p_ids[i], v_variante_id));
    end if;
    for k in 0 .. jsonb_array_length(v_x) - 1 loop
      if not coalesce(v_claves ? (v_x ->> k), false) then
        perform public._formula_rechazar('solo_en_opcion_inexistente', p_ids[i],
          format('«%s» nombra la opción «%s», que la variante no tiene.', p_ids[i], v_x ->> k));
      end if;
    end loop;
  end loop;
end;
$$;


ALTER FUNCTION "public"."_formula_variante"("p_nodos" "jsonb", "p_ids" "text"[], "p_tipos" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_fotos_abrir"("p_vehiculo" "uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v public.vehiculos; v_version timestamptz;
begin
  perform public.assert_activo();
  select * into v from public.vehiculos x where x.id = p_vehiculo and x.eliminado_en is null for key share;
  if not found then
    raise exception 'Ese vehículo ya no existe o está en la papelera.' using errcode = 'PT409';
  end if;
  if not public.puede_vehiculo(v.id, 'vehiculos.editar') then
    raise exception 'No tienes permiso para cambiar las fotos de este vehículo.' using errcode = '42501';
  end if;
  insert into public.vehiculos_imagenes_version (vehiculo_id, actualizado_en)
  values (p_vehiculo, clock_timestamp()) on conflict (vehiculo_id) do nothing;
  select x.actualizado_en into v_version from public.vehiculos_imagenes_version x where x.vehiculo_id = p_vehiculo for update;
  return v_version;
end;
$$;


ALTER FUNCTION "public"."_fotos_abrir"("p_vehiculo" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_fotos_cerrar"("p_vehiculo" "uuid", "p_accion" "text", "p_detalle" "jsonb") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_version timestamptz;
begin
  update public.vehiculos_imagenes i set orden = n.posicion
  from (select x.id, row_number() over (order by x.orden, x.creado_en, x.id) as posicion
        from public.vehiculos_imagenes x where x.vehiculo_id = p_vehiculo) n
  where i.id = n.id and i.orden <> n.posicion;
  if not exists (select 1 from public.vehiculos_imagenes x where x.vehiculo_id = p_vehiculo and x.es_portada) then
    update public.vehiculos_imagenes i set es_portada = true
    where i.id = (select x.id from public.vehiculos_imagenes x where x.vehiculo_id = p_vehiculo order by x.orden, x.id limit 1);
  end if;
  update public.vehiculos_imagenes_version x
  set actualizado_en = greatest(clock_timestamp(), x.actualizado_en + interval '1 microsecond')
  where x.vehiculo_id = p_vehiculo returning x.actualizado_en into v_version;
  perform public.registrar_actividad(p_accion, 'vehiculos_imagenes_version', p_vehiculo::text, null, null, p_detalle);
  return v_version;
end;
$$;


ALTER FUNCTION "public"."_fotos_cerrar"("p_vehiculo" "uuid", "p_accion" "text", "p_detalle" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_fotos_exigir_version"("p_vehiculo" "uuid", "p_actual" timestamp with time zone, "p_esperado" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_actual is distinct from p_esperado then
    perform public._conflicto_de_edicion('vehiculos_imagenes_version', p_vehiculo, p_actual, 'las fotos de este vehículo');
  end if;
end;
$$;


