ALTER FUNCTION "public"."_gasto_respuesta"("g" "public"."gastos", "p_extra" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_gasto_tributo_protegido"("o" "public"."gastos", "p_categoria_nueva" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare v_fase text;
begin
  if o.vehiculo_id is null or not exists (select 1 from public.categorias_gasto c where c.id = o.categoria_id and c.proposito = 'tributos') then
    return;
  end if;
  if p_categoria_nueva is not null and exists (select 1 from public.categorias_gasto c where c.id = p_categoria_nueva and c.proposito = 'tributos') then
    return;
  end if;
  select f.nombre into v_fase
    from public.vehiculos v join public.fases f on f.id = v.fase_id join public.fases_requisitos r on r.fase_id = f.id
   where v.id = o.vehiculo_id and r.tipo = 'dato' and r.clave_dato = 'aduana.tributos_pagados'
   limit 1;
  if not found then
    return;
  end if;
  if exists (select 1 from public.gastos x join public.categorias_gasto c on c.id = x.categoria_id
              where x.vehiculo_id = o.vehiculo_id and x.eliminado_en is null and c.proposito = 'tributos' and x.id <> o.id) then
    return;
  end if;
  raise exception 'La fase «%» pide los tributos pagados: este es el último gasto de tributos.', v_fase using errcode = '23514', hint = 'categoria_id';
end;
$$;


ALTER FUNCTION "public"."_gasto_tributo_protegido"("o" "public"."gastos", "p_categoria_nueva" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_gasto_validar"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_categoria" "uuid", "p_monto" numeric, "p_ruta" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
begin
  if p_categoria is not null and not exists (select 1 from public.categorias_gasto c where c.id = p_categoria and c.activo) then
    raise exception 'Elige una categoría de gasto activa.' using errcode = '22023', hint = 'categoria_id';
  end if;
  if p_monto is null then
    raise exception 'Falta el monto.' using errcode = '23502', hint = 'monto';
  end if;
  if p_monto < 0 then
    raise exception 'El monto no puede ser negativo.' using errcode = '22023', hint = 'monto';
  end if;
  if not public._comprobante_ruta_valida(coalesce(p_vehiculo, p_repuesto), p_ruta) then
    raise exception 'El comprobante no está en la carpeta de esta unidad.' using errcode = '22023', hint = 'comprobante_ruta';
  end if;
end;
$$;


ALTER FUNCTION "public"."_gasto_validar"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_categoria" "uuid", "p_monto" numeric, "p_ruta" "text") OWNER TO "postgres";


