CREATE OR REPLACE FUNCTION "public"."_hoja_chips"("p_origen" "uuid", "p_params" "jsonb", "p_nodo" "jsonb", "p_columna" "text", "p_filas" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tabla text := p_nodo ->> 'tabla'; v_col text := p_nodo ->> 'columna'; v_id uuid; v_cong jsonb;
begin
  if jsonb_typeof(p_params -> 'tablas') = 'object' and (p_params -> 'tablas') ? v_tabla then
    v_cong := p_params -> 'tablas' -> v_tabla;
    if jsonb_typeof(v_cong) <> 'array' then return '[]'::jsonb; end if;
    return coalesce((select jsonb_agg(jsonb_build_object('etiqueta', c.fila ->> p_columna,
                                                          'valor', case when jsonb_typeof(c.fila -> v_col) = 'number' then c.fila -> v_col end) order by c.ord)
                       from (select f.value as fila, f.ord from jsonb_array_elements(v_cong) with ordinality f (value, ord) where f.ord <= p_filas) c
                      where c.fila ->> p_columna is not null), '[]'::jsonb);
  end if;
  select r.id into v_id from public.tablas_referencia r where r.clave = v_tabla and r.activa and r.origen_id = p_origen;
  if v_id is null then
    select r.id into v_id from public.tablas_referencia r where r.clave = v_tabla and r.activa and r.origen_id is null;
  end if;
  if v_id is null then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('etiqueta', c.valores ->> p_columna,
                                                        'valor', case when jsonb_typeof(c.valores -> v_col) = 'number' then c.valores -> v_col end) order by c.orden, c.id)
                     from (select x.valores, x.orden, x.id from public.tablas_referencia_filas x where x.tabla_id = v_id and x.activa order by x.orden, x.id limit p_filas) c
                    where c.valores ->> p_columna is not null), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."_hoja_chips"("p_origen" "uuid", "p_params" "jsonb", "p_nodo" "jsonb", "p_columna" "text", "p_filas" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_hoja_datos_del_vehiculo"("p_nodos" "jsonb", "p_origen" "uuid", "p_tablas" "jsonb", "p_vivas" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_object_agg(d.nid, jsonb_build_object('tabla', d.tabla, 'columnas', d.columnas)), '{}'::jsonb)
    from (select n.key as nid, n.value ->> 'tabla' as tabla,
                 jsonb_agg(jsonb_build_object('columna', m.key, 'campo', m.value) order by m.key collate "C") as columnas
            from jsonb_each(coalesce(p_nodos, '{}'::jsonb)) n
           cross join lateral jsonb_each_text(case when jsonb_typeof(n.value -> 'match') = 'object' then n.value -> 'match' else '{}'::jsonb end) m
           where n.value ->> 'tipo' = 'tabla'
             and ((jsonb_typeof(p_tablas) = 'object' and p_tablas ? (n.value ->> 'tabla')) or coalesce(p_vivas, '{}'::jsonb) ? (n.value ->> 'tabla'))
             and not p_nodos ? m.value
             and (m.value in ('anio', 'marca', 'modelo', 'kilometraje', 'precio')
                  or exists (select 1 from public.origenes_campos oc where oc.origen_id = p_origen and oc.clave = m.value and oc.activo))
           group by n.key, n.value ->> 'tabla') d
$$;


ALTER FUNCTION "public"."_hoja_datos_del_vehiculo"("p_nodos" "jsonb", "p_origen" "uuid", "p_tablas" "jsonb", "p_vivas" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_hoja_datos_del_vehiculo"("p_nodos" "jsonb", "p_origen" "uuid", "p_tablas" "jsonb", "p_vivas" "jsonb") IS 'El dato del vehículo de cada nodo tabla de una versión (id → {tabla, columnas: [{columna, campo}]}): las entradas del match que no nombran un nodo y nombran una columna del vehículo o un campo activo del origen, de una tabla congelada o viva y activa. Invoker y de nadie; la llama _cotizacion_hoja. docs/COTIZADOR.md › «La lectura que abre la hoja (4.13-1)».';



CREATE OR REPLACE FUNCTION "public"."_hoja_estado"("p_nodo" "jsonb", "p_celda" boolean, "p_edita" boolean, "p_nivel" "text", "p_nombre" "text", "p_cfg" boolean, "p_tc" boolean) RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('editable', e.ok, 'ajustes', e.tipo = 'constante' and p_cfg or e.tipo = 'tipo_cambio' and p_tc)
         || case when e.ok then '{}'::jsonb else jsonb_build_object('motivo', case
              when p_celda and not e.acepta then jsonb_build_object('codigo', case when e.tipo = 'campo_vehiculo' then 'del_vehiculo' else 'se_calcula' end)
              when p_nivel is null then '{"codigo": "no_se_edita"}'::jsonb
              when p_nivel <> 'todos' then jsonb_build_object('codigo', 'nivel', 'nivel', coalesce(p_nombre, p_nivel))
              else '{"codigo": "no_se_edita"}'::jsonb end) end
    from (select t.tipo, t.acepta, coalesce(p_edita, false) and (not p_celda or t.acepta) as ok
            from (select p_nodo ->> 'tipo' as tipo,
                         (p_nodo ->> 'tipo') in ('input', 'constante', 'tipo_cambio')
                         or ((p_nodo ->> 'tipo') in ('tabla', 'tramo', 'calculo') and coalesce((p_nodo -> 'sobrescribible') = 'true'::jsonb, false)) as acepta) t) e;
$$;


ALTER FUNCTION "public"."_hoja_estado"("p_nodo" "jsonb", "p_celda" boolean, "p_edita" boolean, "p_nivel" "text", "p_nombre" "text", "p_cfg" boolean, "p_tc" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_icono_del_catalogo"("p_icono" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if p_icono is null or btrim(p_icono) = '' then
    return null;
  end if;
  if p_icono <> all (public._iconos_del_catalogo()) then
    raise exception 'Ese icono no está en el catálogo: elige uno de la lista o déjalo sin icono.' using errcode = '22023', hint = 'icono';
  end if;
  return p_icono;
end;
$$;


