CREATE TABLE IF NOT EXISTS "public"."importaciones" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "usuario_id" "uuid" NOT NULL,
    "entidad" "text" NOT NULL,
    "archivo_ruta" "text",
    "mapeo" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "estado" "public"."estado_importacion" DEFAULT 'pendiente'::"public"."estado_importacion" NOT NULL,
    "filas_total" integer,
    "filas_ok" integer,
    "errores" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "iniciada_en" timestamp with time zone,
    "terminada_en" timestamp with time zone,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deshecha_en" timestamp with time zone,
    "deshecha_lote" "uuid",
    "deshecha_resultado" "jsonb",
    "asignar_a" "uuid",
    "con_destino" boolean DEFAULT false NOT NULL,
    "origen_id" "uuid",
    "procesadas" integer DEFAULT 0 NOT NULL,
    "ya_existian" integer DEFAULT 0 NOT NULL,
    "rechazadas" integer DEFAULT 0 NOT NULL,
    "avance_en" timestamp with time zone,
    CONSTRAINT "importaciones_asignar_a_check" CHECK ((("asignar_a" IS NULL) OR ("entidad" = 'leads'::"text"))),
    CONSTRAINT "importaciones_check" CHECK ((("archivo_ruta" IS NOT NULL) OR ("entidad" = 'leads'::"text"))),
    CONSTRAINT "importaciones_check1" CHECK ((("deshecha_en" IS NULL) = ("deshecha_resultado" IS NULL))),
    CONSTRAINT "importaciones_con_destino_check" CHECK (((NOT "con_destino") OR ("entidad" = 'leads'::"text"))),
    CONSTRAINT "importaciones_cuentas_check" CHECK ((("ya_existian" >= 0) AND ("rechazadas" >= 0))),
    CONSTRAINT "importaciones_entidad_check" CHECK (("entidad" = ANY (ARRAY['leads'::"text", 'vehiculos'::"text", 'seguimientos'::"text", 'repuestos_items'::"text"]))),
    CONSTRAINT "importaciones_origen_id_check" CHECK ((("origen_id" IS NULL) OR ("entidad" = 'vehiculos'::"text"))),
    CONSTRAINT "importaciones_procesadas_check" CHECK ((("procesadas" >= 0) AND (("filas_total" IS NULL) OR ("procesadas" <= "filas_total"))))
);


ALTER TABLE "public"."importaciones" OWNER TO "postgres";


COMMENT ON TABLE "public"."importaciones" IS 'Importación con vista previa validada por fila; importa las válidas aunque fallen algunas. La procesa la edge function importar-csv.';



COMMENT ON COLUMN "public"."importaciones"."asignar_a" IS 'Importación total de leads (9.06): la persona de destino, que crea los leads y los recibe en su cartera. Nulo = quien importa.';



COMMENT ON COLUMN "public"."importaciones"."con_destino" IS 'Verdadero si se creó para otra persona. Si su perfil se borra (asignar_a queda nulo), la importación pasa a fallida: nunca cambia de dueño en silencio.';



COMMENT ON COLUMN "public"."importaciones"."origen_id" IS 'Importación total de vehículos (9.06): el origen de todas sus filas.';



COMMENT ON COLUMN "public"."importaciones"."procesadas" IS 'Marca de agua: la última fila procesada (las filas 1..procesadas ya tienen su resultado). Un lote que la repite se salta.';



COMMENT ON COLUMN "public"."importaciones"."ya_existian" IS 'Filas que ya existían (un teléfono, un VIN o un lote repetido).';



COMMENT ON COLUMN "public"."importaciones"."rechazadas" IS 'Filas con error (validación o una regla de la base).';



COMMENT ON COLUMN "public"."importaciones"."avance_en" IS 'Último avance de la importación total; el job de continuar busca las detenidas.';



CREATE OR REPLACE FUNCTION "public"."_importacion_autorizar"("p_imp" "public"."importaciones") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  -- Se creó para otra persona y su perfil ya no está: nunca se cambia de dueño en silencio.
  if p_imp.con_destino and p_imp.asignar_a is null then
    return 'destino_no_puede';
  end if;
  perform public._importacion_fijar(p_imp.usuario_id);
  if not public.es_usuario_activo() then
    return 'quien_importa_inactivo';
  end if;
  if p_imp.entidad = 'leads' then
    if p_imp.asignar_a is null then
      if not public.tiene_permiso('leads.crear') then return 'sin_permiso'; end if;
      return null;
    end if;
    if not public.tiene_permiso('datos.importar.todo') then return 'sin_permiso'; end if;
    perform public._importacion_fijar(p_imp.asignar_a);
    if not public.es_usuario_activo() or not public.tiene_permiso('leads.crear') then return 'destino_no_puede'; end if;
    return null;
  end if;
  if p_imp.entidad = 'vehiculos' then
    if p_imp.origen_id is null or not exists (select 1 from public.origenes o where o.id = p_imp.origen_id and o.activo) then
      return 'origen_inactivo';
    end if;
    if not public.tiene_permiso('vehiculos.crear', p_imp.origen_id) then return 'sin_permiso'; end if;
    return null;
  end if;
  return 'sin_permiso';
end;
$$;


ALTER FUNCTION "public"."_importacion_autorizar"("p_imp" "public"."importaciones") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_importacion_autorizar"("p_imp" "public"."importaciones") IS 'Enforcement por lote de datos.importar.todo, leads.crear y vehiculos.crear (9.06): vuelve a mirar a quien importa y al destino con los permisos de hoy.';



CREATE OR REPLACE FUNCTION "public"."_importacion_fallar"("p_importacion" "uuid", "p_clave" "text") RETURNS "void"
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  update public.importaciones i
     set estado = 'fallida', errores = jsonb_build_array(jsonb_build_object('motivo', public._importacion_motivo(p_clave))),
         terminada_en = now(), avance_en = now()
   where i.id = p_importacion;
$$;


