CREATE OR REPLACE FUNCTION "public"."_lead_aplicar_bajas"("p_lead" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_quien uuid;
begin
  with hechas as (
    update public.leads_asesores la set revocado_en = now(), revocado_por = b.por
      from public.equipo_bajas b
     where la.lead_id = p_lead and la.revocado_en is null
       and b.usuario_id = la.usuario_id and b.terminada_en is null
    returning la.usuario_id
  )
  select (array_agg(h.usuario_id order by h.usuario_id))[1] into v_quien from hechas h;
  if v_quien is not null
     and exists (select 1 from public.leads l where l.id = p_lead and l.eliminado_en is null and l.cartera = '{}') then
    update public.equipo_bajas set leads_al_limbo = leads_al_limbo + 1 where usuario_id = v_quien;
  end if;
end;
$$;


ALTER FUNCTION "public"."_lead_aplicar_bajas"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_atributos_formato"("p_nuevos" "jsonb", "p_anteriores" "jsonb", "p_campos" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare k text; v jsonb; c record; e jsonb; t text; x numeric;
begin
  for k in select jsonb_object_keys(p_nuevos) loop
    if not exists (select 1 from jsonb_to_recordset(p_campos) as f (clave text) where f.clave = k) then
      raise exception 'El dato «%» no es un campo de los leads.', k using errcode = '22023', hint = 'atributos.' || k;
    end if;
  end loop;
  for c in select f.clave, f.etiqueta, f.tipo, f.opciones, f.activo
           from jsonb_to_recordset(p_campos) as f (clave text, etiqueta text, tipo text, opciones jsonb, activo boolean) loop
    v := p_nuevos -> c.clave;
    if v is null or v = 'null'::jsonb then
      continue;
    end if;
    if not c.activo then
      if v is distinct from (p_anteriores -> c.clave) then
        raise exception '«%» está desactivado: no se cambia.', c.etiqueta using errcode = '22023', hint = 'atributos.' || c.clave;
      end if;
      continue;
    end if;
    t := v #>> '{}';
    case c.tipo
      when 'texto' then
        if jsonb_typeof(v) = 'string' and char_length(t) > 500 then
          raise exception '«%» admite hasta 500 caracteres.', c.etiqueta using errcode = '22023', hint = 'atributos.' || c.clave;
        end if;
      when 'texto_largo' then
        if jsonb_typeof(v) = 'string' and char_length(t) > 5000 then
          raise exception '«%» admite hasta 5000 caracteres.', c.etiqueta using errcode = '22023', hint = 'atributos.' || c.clave;
        end if;
      when 'numero', 'moneda' then
        x := t::numeric;
        if abs(x) > 1000000000000 then
          raise exception '«%» es demasiado grande.', c.etiqueta using errcode = '22023', hint = 'atributos.' || c.clave;
        end if;
      when 'fecha' then
        begin
          if t !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'x'; end if;
          perform t::date;
        exception when others then
          raise exception '«%» tiene que ser una fecha (aaaa-mm-dd).', c.etiqueta using errcode = '22023', hint = 'atributos.' || c.clave;
        end;
      when 'fecha_hora' then
        begin
          perform t::timestamptz;
        exception when others then
          raise exception '«%» tiene que ser una fecha con hora.', c.etiqueta using errcode = '22023', hint = 'atributos.' || c.clave;
        end;
      when 'url' then
        if t !~* '^https?://[^[:space:]]+$' or char_length(t) > 500 then
          raise exception '«%» tiene que ser un enlace que empiece con http:// o https://.', c.etiqueta using errcode = '22023', hint = 'atributos.' || c.clave;
        end if;
      when 'correo' then
        if t !~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' or char_length(t) > 160 then
          raise exception '«%» tiene que ser un correo.', c.etiqueta using errcode = '22023', hint = 'atributos.' || c.clave;
        end if;
      when 'documento' then
        if t !~ '^[A-Za-z0-9][A-Za-z0-9 ./-]{0,29}$' then
          raise exception '«%» lleva letras, números y separadores, hasta 30.', c.etiqueta using errcode = '22023', hint = 'atributos.' || c.clave;
        end if;
      when 'opcion' then
        if not exists (select 1 from jsonb_array_elements(c.opciones) o where o ->> 'clave' = t)
           and v is distinct from (p_anteriores -> c.clave) then
          raise exception '«%» no es una de las opciones de «%».', t, c.etiqueta using errcode = '22023', hint = 'atributos.' || c.clave;
        end if;
      when 'multi_opcion' then
        for e in select * from jsonb_array_elements(v) loop
          if jsonb_typeof(e) <> 'string' then
            raise exception '«%» tiene que ser una lista de opciones.', c.etiqueta using errcode = '22023', hint = 'atributos.' || c.clave;
          end if;
          if not exists (select 1 from jsonb_array_elements(c.opciones) o where o ->> 'clave' = e #>> '{}')
             and not (coalesce(p_anteriores -> c.clave, '[]'::jsonb) @> jsonb_build_array(e)) then
            raise exception '«%» no es una de las opciones de «%».', e #>> '{}', c.etiqueta using errcode = '22023', hint = 'atributos.' || c.clave;
          end if;
        end loop;
      else
        null;
    end case;
  end loop;
end;
$_$;


ALTER FUNCTION "public"."_lead_atributos_formato"("p_nuevos" "jsonb", "p_anteriores" "jsonb", "p_campos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_atributos_publicos"("p_atributos" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb)
    from jsonb_each(coalesce(p_atributos, '{}'::jsonb)) e
   where exists (select 1 from public.leads_campos c
                  where c.clave = e.key and not c.solo_cartera and c.solo_cartera_pendiente is not true);
$$;


ALTER FUNCTION "public"."_lead_atributos_publicos"("p_atributos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_busqueda_patron"("p_texto" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $$
  select '%' || replace(replace(replace(replace(p_texto, '\', '\\'), '%', '\%'), '_', '\_'), '*', '_') || '%'
$$;


ALTER FUNCTION "public"."_lead_busqueda_patron"("p_texto" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_campo_con_valor"("p_clave" "text") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select count(*)::int from public.leads l where public._campo_tiene_valor(l.atributos -> p_clave);
$$;


ALTER FUNCTION "public"."_lead_campo_con_valor"("p_clave" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_campo_privacidad_lote"("p_campo" "uuid", "p_lote" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.leads_campos; v_n int;
begin
  select * into c from public.leads_campos x where x.id = p_campo for share;
  if not found or c.solo_cartera_pendiente is null then
    return true;
  end if;
  if c.solo_cartera_pendiente then
    -- A privado: quitar la clave. El trigger de `leads` la recalcula igual (con el pendiente, ya no es pública).
    with lote as (
      select l.id from public.leads l where l.atributos_publicos ? c.clave
       order by l.id limit greatest(coalesce(p_lote, 0), 1) for update skip locked
    )
    update public.leads l set atributos_publicos = l.atributos_publicos - c.clave from lote where l.id = lote.id;
    get diagnostics v_n = row_count;
    if exists (select 1 from public.leads l where l.atributos_publicos ? c.clave) then
      return false;
    end if;
    update public.leads_campos x set solo_cartera = true, solo_cartera_pendiente = null where x.id = c.id;
    return true;
  end if;
  -- A público: completar la copia de los que tienen el dato.
  with lote as (
    select l.id from public.leads l where l.atributos ? c.clave and not l.atributos_publicos ? c.clave
     order by l.id limit greatest(coalesce(p_lote, 0), 1) for update skip locked
  )
  update public.leads l set atributos_publicos = l.atributos_publicos || jsonb_build_object(c.clave, l.atributos -> c.clave)
    from lote where l.id = lote.id;
  get diagnostics v_n = row_count;
  if exists (select 1 from public.leads l where l.atributos ? c.clave and not l.atributos_publicos ? c.clave) then
    return false;
  end if;
  update public.leads_campos x set solo_cartera_pendiente = null where x.id = c.id;
  return true;
end;
$$;


ALTER FUNCTION "public"."_lead_campo_privacidad_lote"("p_campo" "uuid", "p_lote" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_campos_renumerar"() RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update public.leads_campos c set orden = n.orden_nuevo
  from public._campos_renumerar((
    select jsonb_agg(jsonb_build_object('id', x.id, 'clave', x.clave, 'orden', x.orden)) from public.leads_campos x)) n
  where c.id = n.campo_id and c.orden <> n.orden_nuevo;
$$;


ALTER FUNCTION "public"."_lead_campos_renumerar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_cartera_calcular"("p_lead" "uuid") RETURNS "uuid"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(array_agg(la.usuario_id order by la.usuario_id), '{}')
    from public.leads_asesores la
   where la.lead_id = p_lead and la.revocado_en is null;
$$;


ALTER FUNCTION "public"."_lead_cartera_calcular"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_cartera_json"("p_lead" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'usuario_id', a.usuario_id,
      'nombre', coalesce(nullif(btrim(p.nombre), ''), 'Sin nombre'),
      'tipo_acceso', a.tipo_acceso,
      'desde', a.desde,
      'compartido_por', nullif(btrim(q.nombre), ''),
      'es_yo', a.usuario_id = (select auth.uid()))
    order by (a.tipo_acceso = 'dueno') desc, a.desde, a.usuario_id), '[]'::jsonb)
  from public.leads_asesores a
  join public.perfiles p on p.id = a.usuario_id
  left join public.perfiles q on q.id = a.compartido_por
  where a.lead_id = p_lead and a.revocado_en is null
    and a.usuario_id <> all ((select public._bajas_en_curso())::uuid[]);
$$;


ALTER FUNCTION "public"."_lead_cartera_json"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_clave_reservada"("p_clave" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select p_clave = any (array['id', 'numero', 'nombre', 'telefono', 'telefonos', 'telefono_cc', 'telefono_principal',
    'tipo', 'origen', 'origen_lead_id', 'atributos', 'cartera', 'dueno', 'creado_por', 'creado_en', 'actualizado_en',
    'eliminado_en', 'eliminado_por', 'ultimo_seguimiento_en', 'lote_papelera_id']);
$$;


ALTER FUNCTION "public"."_lead_clave_reservada"("p_clave" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_conflicto"("p_lead" "uuid", "p_cuando" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actor uuid; v_nombre text; v_hay boolean := false;
begin
  select a.actor_id, true into v_actor, v_hay from public.actividad a
   where a.tabla = 'leads' and a.registro_id = p_lead::text and a.accion = 'leads.update'
   order by a.id desc limit 1;
  if v_actor is not null and v_actor = (select auth.uid()) then
    raise exception 'Cambiaste este lead % desde otra ventana. Recarga para seguir desde ahí.', public._hace(p_cuando)
      using errcode = 'PT409';
  end if;
  if v_actor is not null then
    select nullif(btrim(p.nombre), '') into v_nombre from public.perfiles p where p.id = v_actor;
  end if;
  if v_nombre is null and (v_actor is not null or not coalesce(v_hay, false)) then
    v_nombre := 'Otra persona';
  end if;
  if v_nombre is null then
    raise exception 'Este lead cambió %.', public._hace(p_cuando) using errcode = 'PT409';
  end if;
  raise exception '% cambió este lead %.', v_nombre, public._hace(p_cuando) using errcode = 'PT409';
end;
$$;


ALTER FUNCTION "public"."_lead_conflicto"("p_lead" "uuid", "p_cuando" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_crear"("p_id" "uuid", "p_lead" "jsonb", "p_seguimiento" "jsonb", "p_recordatorio" "jsonb", "p_recordar_origen" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_permitidas constant text[] := array['nombre', 'telefono_cc', 'telefono_principal', 'tipo_lead_id', 'origen_lead_id', 'atributos', 'adoptar'];
  v_k text;
  v_cc text;
  v_cc_digitos text;
  v_tel text;
  v_nombre text;
  v_tipo uuid;
  v_origen uuid;
  v_activos text[];
  v_atributos jsonb := '{}'::jsonb;
  v_verif jsonb;
  v_estado text;
  v_id uuid;
  v_adoptado boolean := false;
  v_tipo_seg uuid;
  v_titulo text;
  v_detalle text;
  v_doc jsonb;
  v_id_previo uuid;
  v_ocurrido timestamptz := now();
  v_k2 text;
  v_msg text;
  v_recordar timestamptz;
  v_titulo_rec text;
begin
  if p_id is null then
    raise exception 'Falta el identificador del intento.' using errcode = '22023';
  end if;
  if p_lead is null or jsonb_typeof(p_lead) <> 'object' then
    raise exception 'Los datos del lead tienen que ser un objeto.' using errcode = '22023';
  end if;
  for v_k in select jsonb_object_keys(p_lead) loop
    if not (v_k = any (v_permitidas)) then
      raise exception 'El dato «%» no va suelto: los campos del lead se mandan dentro de «atributos».', v_k
        using errcode = '22023', hint = v_k;
    end if;
  end loop;

  -- ¿Ya entró este intento? Una respuesta perdida y un reintento: devuelve lo mismo, no duplica.
  select l.id into v_id from public.leads l where l.id = p_id and l.creado_por = v_yo;
  if found then
    return jsonb_build_object('resultado', 'creado', 'id', v_id, 'repetido', true) || public._lead_numeros_de(v_id);
  end if;
  -- ¿Ya entró por una adopción del limbo? Sólo un alta que adopta (`adoptar`) puede haber escrito ese intento, y la
  -- importación nunca adopta: sin `adoptar` no se busca. Buscarlo siempre costaba 0,15 µs por fila de `actividad` por cada
  -- alta (con `leads` grande el planificador recorría `actividad_pkey` entera en vez de `actividad_intento_adopcion_idx`):
  -- importar 500 filas con 126.000 de `actividad` tardaba 10,5 s. `docs/DECISIONES.md`, «Cierre 5a-fix-2».
  if (p_lead ->> 'adoptar') = 'true' then
    select l.id into v_id
      from public.actividad a join public.leads l on l.id::text = a.registro_id
     where a.accion = 'lead.adoptado_del_limbo' and a.actor_id = v_yo and a.detalle ->> 'intento' = p_id::text
     order by a.id desc limit 1;
    if found then
      return jsonb_build_object('resultado', 'adoptado', 'id', v_id, 'repetido', true) || public._lead_numeros_de(v_id);
    end if;
  end if;

  -- El teléfono, y lo que ya se sabe de él.
  v_cc := coalesce(nullif(btrim(p_lead ->> 'telefono_cc'), ''), (select e.telefono_cc from public.ajustes_empresa e where e.id = 1));
  v_tel := public.normalizar_telefono(v_cc, p_lead ->> 'telefono_principal');
  v_verif := public._lead_verificar(v_tel);
  v_estado := v_verif ->> 'estado';
  if v_estado in ('existe', 'de_otro') or (v_estado = 'limbo' and (p_lead ->> 'adoptar') is distinct from 'true') then
    return jsonb_build_object('resultado', v_estado, 'verificacion', v_verif);
  end if;

  -- Lo demás que tiene que pasar, antes de escribir nada.
  v_nombre := btrim(coalesce(p_lead ->> 'nombre', ''));
  if v_nombre = '' then
    raise exception 'Escribe el nombre.' using errcode = '22023', hint = 'nombre';
  end if;
  if char_length(v_nombre) > 120 then
    raise exception 'El nombre admite hasta 120 caracteres.' using errcode = '22023', hint = 'nombre';
  end if;
  begin
    v_tipo := coalesce(nullif(p_lead ->> 'tipo_lead_id', '')::uuid, public._tipo_lead_por_defecto());
  exception when invalid_text_representation then
    raise exception 'Ese tipo de lead no existe.' using errcode = '22023', hint = 'tipo_lead_id';
  end;
  if v_tipo is null then
    raise exception 'Elige el tipo de lead.' using errcode = '22023', hint = 'tipo_lead_id';
  end if;
  perform public._tipo_lead_exigir_activo(v_tipo);
  begin
    v_origen := nullif(p_lead ->> 'origen_lead_id', '')::uuid;
  exception when invalid_text_representation then
    raise exception 'Ese origen del lead no existe.' using errcode = '22023', hint = 'origen_lead_id';
  end;
  if v_origen is not null then
    if not exists (select 1 from public.origenes_lead o where o.id = v_origen and o.activo) then
      raise exception 'Ese origen del lead está desactivado o ya no existe.' using errcode = '22023', hint = 'origen_lead_id';
    end if;
  elsif exists (select 1 from public.origenes_lead o where o.activo) then
    raise exception 'Elige de dónde viene el lead.' using errcode = '22023', hint = 'origen_lead_id';
  end if;

  select coalesce(array_agg(c.clave), '{}') into v_activos from public.leads_campos c where c.activo;
  if p_lead ? 'atributos' then
    v_atributos := public._atributos_fusionar('{}'::jsonb, p_lead -> 'atributos', v_activos,
      'Los atributos de un lead tienen que ser un objeto.',
      'El campo «%s» no es un campo de los leads o está desactivado.');
  end if;

  if p_seguimiento is not null then
    if jsonb_typeof(p_seguimiento) <> 'object' then
      raise exception 'El seguimiento tiene que ser un objeto.' using errcode = '22023', hint = 'seguimiento.titulo';
    end if;
    -- Las mismas claves que `seguimiento_crear`, menos las que el alta no ofrece (la visibilidad y el
    -- vehículo): una de más se rechaza con su nombre, no pasa callada.
    for v_k2 in select jsonb_object_keys(p_seguimiento) loop
      if v_k2 not in ('tipo_id', 'titulo', 'detalle', 'ocurrido_en') then
        raise exception 'El dato «%» no es del primer seguimiento.', v_k2
          using errcode = '22023', hint = 'seguimiento.' || v_k2;
      end if;
    end loop;
    begin
      v_tipo_seg := nullif(p_seguimiento ->> 'tipo_id', '')::uuid;
    exception when invalid_text_representation then
      v_tipo_seg := null;
    end;
    if v_tipo_seg is null or not exists (select 1 from public.tipos_seguimiento t where t.id = v_tipo_seg and t.activo) then
      raise exception 'Elige un tipo de seguimiento que esté activo.' using errcode = '22023', hint = 'seguimiento.tipo_id';
    end if;
    -- El resumen, el detalle y la fecha se validan con las funciones de `seguimiento_crear`: una sola
    -- regla. El resumen recibe su hint; el detalle y la fecha levantan el de la ficha («detalle»,
    -- «ocurrido_en») y acá se les pone el campo del alta.
    v_titulo := public._seguimiento_titulo(p_seguimiento -> 'titulo', 'seguimiento.titulo');
    begin
      v_doc := p_seguimiento -> 'detalle';
      v_detalle := public._seguimiento_detalle(v_doc);
      if v_detalle is null then
        v_doc := null;
      end if;
    exception when sqlstate '22023' then
      get stacked diagnostics v_msg = message_text;
      raise exception '%', v_msg using errcode = '22023', hint = 'seguimiento.detalle';
    end;
    if p_seguimiento ? 'ocurrido_en' and p_seguimiento -> 'ocurrido_en' <> 'null'::jsonb then
      begin
        v_ocurrido := public._seguimiento_fecha(p_seguimiento -> 'ocurrido_en');
      exception when sqlstate '22023' then
        get stacked diagnostics v_msg = message_text;
        raise exception '%', v_msg using errcode = '22023', hint = 'seguimiento.ocurrido_en';
      end;
    end if;
  end if;
  if p_recordatorio is not null then
    if jsonb_typeof(p_recordatorio) <> 'object' then
      raise exception 'El recordatorio tiene que ser un objeto.' using errcode = '22023', hint = 'recordatorio.recordar_en';
    end if;
    begin
      v_recordar := nullif(p_recordatorio ->> 'recordar_en', '')::timestamptz;
    exception when others then
      v_recordar := null;
    end;
    if v_recordar is null then
      raise exception 'Elige cuándo recordarlo.' using errcode = '22023', hint = 'recordatorio.recordar_en';
    end if;
    if v_recordar <= now() then
      raise exception 'El recordatorio tiene que ser en el futuro.' using errcode = '22023', hint = 'recordatorio.recordar_en';
    end if;
    v_titulo_rec := coalesce(nullif(btrim(p_recordatorio ->> 'titulo'), ''), v_titulo);
    if v_titulo_rec is null then
      raise exception 'Escribe de qué es el recordatorio.' using errcode = '22023', hint = 'recordatorio.titulo';
    end if;
  end if;

  if v_estado = 'limbo' then
    -- «Tomar lead»: queda de dueño y lo que el lead ya tiene no se pisa; lo vacío se completa.
    select l.id into v_id from public.leads l
     where l.telefono_principal = v_tel and l.eliminado_en is null for update;
    -- Otra llamada del MISMO intento pudo adoptarlo mientras esta esperaba el candado (un doble envío):
    -- ya se ve confirmado, y adoptar de nuevo duplicaría el seguimiento y el recordatorio. (Otro intento
    -- de otra persona sobre el mismo lead sigue siendo la carrera de siempre, fuera de esta parte.)
    select l.id into v_id_previo
      from public.actividad a join public.leads l on l.id::text = a.registro_id
     where a.accion = 'lead.adoptado_del_limbo' and a.actor_id = v_yo and a.detalle ->> 'intento' = p_id::text
     order by a.id desc limit 1;
    if found then
      return jsonb_build_object('resultado', 'adoptado', 'id', v_id_previo, 'repetido', true) || public._lead_numeros_de(v_id_previo);
    end if;
    -- Una baja en curso de quien lo tenía se aplica a este lead antes de tomarlo (cierre 1); y si otra persona lo tomó
    -- mientras se esperaba el candado, se dice como al verificar, en vez de chocar con el dueño único.
    perform public._lead_aplicar_bajas(v_id);
    if not public.lead_en_limbo(v_id) then
      v_verif := public._lead_verificar(v_tel);
      return jsonb_build_object('resultado', v_verif ->> 'estado', 'verificacion', v_verif);
    end if;
    insert into public.leads_asesores (lead_id, usuario_id, tipo_acceso)
    values (v_id, v_yo, 'dueno')
    on conflict (lead_id, usuario_id) do update
      set tipo_acceso = 'dueno', desde = now(), revocado_en = null, revocado_por = null, compartido_por = null;
    update public.leads l set
      origen_lead_id = coalesce(l.origen_lead_id, v_origen),
      atributos = public._atributos_completar(l.atributos, v_atributos, v_activos,
        'Los atributos de un lead tienen que ser un objeto.',
        'El campo «%s» no es un campo de los leads o está desactivado.')
     where l.id = v_id;
    v_adoptado := true;
    perform public.registrar_actividad('lead.adoptado_del_limbo', 'leads', v_id::text, null,
      jsonb_build_object('telefono', public.enmascarar_telefono(v_tel)), jsonb_build_object('intento', p_id));
  else
    v_cc_digitos := regexp_replace(coalesce(v_cc, ''), '\D', '', 'g');
    begin
      insert into public.leads (id, nombre, telefono_cc, telefono_principal, tipo_lead_id, origen_lead_id, atributos, creado_por)
      values (p_id, v_nombre,
              case when v_cc_digitos <> '' and v_tel like v_cc_digitos || '%' then '+' || v_cc_digitos end,
              v_tel, v_tipo, v_origen, v_atributos, v_yo)
      returning id into v_id;
    exception when unique_violation then
      -- Dos personas guardaron el mismo teléfono a la vez (o este mismo intento, dos veces): el que
      -- llegó segundo ve su estado «existe», no un error.
      select l.id into v_id from public.leads l where l.id = p_id and l.creado_por = v_yo;
      if found then
        return jsonb_build_object('resultado', 'creado', 'id', v_id, 'repetido', true) || public._lead_numeros_de(v_id);
      end if;
      v_verif := public._lead_verificar(v_tel);
      if (v_verif ->> 'estado') in ('existe', 'de_otro', 'limbo') then
        return jsonb_build_object('resultado', v_verif ->> 'estado', 'verificacion', v_verif);
      end if;
      raise exception 'Ese teléfono cambió mientras guardabas. Vuelve a intentarlo.' using errcode = 'PT409';
    end;
    perform public.registrar_actividad('lead.creado', 'leads', v_id::text, null,
      jsonb_build_object('nombre', v_nombre), jsonb_build_object('intento', p_id));
  end if;

  if p_seguimiento is not null then
    insert into public.seguimientos (lead_id, usuario_id, tipo_id, titulo, detalle_doc, detalle_texto, ocurrido_en, actualizado_en)
    values (v_id, v_yo, v_tipo_seg, v_titulo, v_doc, v_detalle, v_ocurrido, clock_timestamp());
  end if;
  if p_recordatorio is not null then
    insert into public.recordatorios (usuario_id, lead_id, titulo, recordar_en)
    values (v_yo, v_id, v_titulo_rec, v_recordar);
  end if;
  if p_recordar_origen and v_origen is not null then
    insert into public.preferencias_usuario (usuario_id, clave, valor)
    values (v_yo, 'leads.ultimo_origen_lead', to_jsonb(v_origen::text))
    on conflict (usuario_id, clave) do update set valor = excluded.valor, actualizado_en = now();
  end if;

  return jsonb_build_object('resultado', case when v_adoptado then 'adoptado' else 'creado' end,
                            'id', v_id, 'repetido', false) || public._lead_numeros_de(v_id);
end;
$$;


ALTER FUNCTION "public"."_lead_crear"("p_id" "uuid", "p_lead" "jsonb", "p_seguimiento" "jsonb", "p_recordatorio" "jsonb", "p_recordar_origen" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_defecto_empresa"("p_tipo" "public"."tipo_campo", "p_defecto" "jsonb", "p_empresa" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if p_empresa is null or p_empresa = '' then return null; end if;
  if p_empresa not in ('ciudad', 'pais') then
    raise exception 'De la empresa sólo se toma la ciudad o el país.' using errcode = '22023';
  end if;
  if p_tipo <> 'texto' then
    raise exception 'El dato de la empresa sólo se usa en un campo de texto.' using errcode = '22023';
  end if;
  if p_defecto is not null then
    raise exception 'Un campo lleva un valor por defecto o el de la empresa, no los dos.' using errcode = '22023';
  end if;
  return p_empresa;
end;
$$;


ALTER FUNCTION "public"."_lead_defecto_empresa"("p_tipo" "public"."tipo_campo", "p_defecto" "jsonb", "p_empresa" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_lead_destino_validar"("p_usuario" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_usuario is null then
    raise exception 'No encontramos a esa persona.' using errcode = '22023', hint = 'usuario';
  end if;
  perform 1 from public.perfiles p where p.id = p_usuario for share;
  if not found then
    raise exception 'No encontramos a esa persona.' using errcode = '22023', hint = 'usuario';
  end if;
  if not exists (select 1 from public.perfiles p where p.id = p_usuario and p.activo and not p.bloqueado) then
    raise exception 'Esa persona no está activa en el equipo.' using errcode = '22023', hint = 'usuario';
  end if;
  if not public.usuario_tiene_permiso(p_usuario, 'leads.ver') then
    raise exception 'Esa persona no puede ver leads.' using errcode = '22023', hint = 'usuario';
  end if;
end;
$$;


ALTER FUNCTION "public"."_lead_destino_validar"("p_usuario" "uuid") OWNER TO "postgres";


