CREATE OR REPLACE FUNCTION "public"."_leads_cartera_recalcular"("p_leads" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_leads is null or cardinality(p_leads) = 0 then
    return;
  end if;
  perform 1 from public.leads l where l.id = any (p_leads) order by l.id for update;
  update public.leads l set cartera = c.cartera
    from (select x.id, coalesce(array_agg(la.usuario_id order by la.usuario_id) filter (where la.usuario_id is not null), '{}') as cartera
            from unnest(p_leads) as x (id)
            left join public.leads_asesores la on la.lead_id = x.id and la.revocado_en is null
           group by x.id) c
   where l.id = c.id and l.cartera is distinct from c.cartera;
end;
$$;


ALTER FUNCTION "public"."_leads_cartera_recalcular"("p_leads" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_leads_columnas_a_atributos"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_n int := 0;
  v_columnas constant text[] := array['edad', 'genero', 'ciudad', 'pais', 'direccion', 'notas'];
begin
  if not exists (select 1 from information_schema.columns
                 where table_schema = 'public' and table_name = 'leads' and column_name = 'edad') then
    return 0;
  end if;
  drop view if exists public.leads_vista;
  alter table public.leads disable trigger trg_lead_version;
  alter table public.leads disable trigger trg_lead_auditar;
  execute format($q$
    update public.leads set atributos = atributos || jsonb_strip_nulls(jsonb_build_object(
      'edad', %1$I,
      'genero', nullif(%2$I::text, 'sin_especificar'),
      'ciudad', nullif(btrim(%3$I), ''),
      'pais', nullif(btrim(%4$I), ''),
      'direccion', nullif(btrim(%5$I), ''),
      'notas', nullif(btrim(%6$I), '')))
  $q$, v_columnas[1], v_columnas[2], v_columnas[3], v_columnas[4], v_columnas[5], v_columnas[6]);
  get diagnostics v_n = row_count;
  alter table public.leads enable trigger trg_lead_version;
  alter table public.leads enable trigger trg_lead_auditar;
  alter table public.leads drop column edad, drop column ciudad, drop column pais,
    drop column direccion, drop column genero, drop column notas;
  drop type if exists public.genero_persona;
  return v_n;
end;
$_$;


ALTER FUNCTION "public"."_leads_columnas_a_atributos"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_leads_derivados_rellenar"("p_lote" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int;
begin
  with pendientes as (
    select l.id from public.leads l
     where l.cartera is null or l.atributos_publicos is null
     order by l.id limit greatest(coalesce(p_lote, 0), 1)
     for update skip locked
  )
  update public.leads l
     set cartera = public._lead_cartera_calcular(l.id),
         atributos_publicos = public._lead_atributos_publicos(l.atributos)
    from pendientes p
   where l.id = p.id;
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;


ALTER FUNCTION "public"."_leads_derivados_rellenar"("p_lote" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_leads_numerar_existentes"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- Sin los triggers de `leads` en este UPDATE (la versión, la auditoría, la copia, la inmutabilidad): con 62.000
  -- leads bajan de ~12 s a ~3,5 s, y ninguno tiene nada que hacer con un número que se está dando. El `alter` es
  -- transaccional: si algo falla, los triggers vuelven a estar encendidos.
  alter table public.leads disable trigger user;
  update public.leads l set numero_propio = x.n
    from (select s.id, coalesce(m.mayor, 0) + row_number() over (partition by s.creado_por order by s.creado_en, s.id)::integer as n
            from public.leads s
            left join (select creado_por, max(numero_propio) as mayor from public.leads
                        where numero_propio is not null group by creado_por) m on m.creado_por = s.creado_por
           where s.creado_por is not null and s.numero_propio is null) x
   where l.id = x.id;
  alter table public.leads enable trigger user;

  insert into public.leads_contadores as c (usuario_id, ultimo)
  select creado_por, max(numero_propio) from public.leads where creado_por is not null group by creado_por
  on conflict (usuario_id) do update set ultimo = greatest(c.ultimo, excluded.ultimo);

  insert into public.leads_numeros_globales (lead_id, numero) select id, numero from public.leads
  on conflict (lead_id) do nothing;
  insert into public.leads_numeros_propios (lead_id, creado_por, numero)
  select id, creado_por, numero_propio from public.leads where numero_propio is not null and creado_por is not null
  on conflict (lead_id) do update set numero = excluded.numero;
end;
$$;


ALTER FUNCTION "public"."_leads_numerar_existentes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_leads_papelera_lote_json"("p_lote" "public"."lotes_papelera", "p_dias" integer, "p_yo" "uuid", "p_primeros" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', p_lote.id, 'actualizado_en', p_lote.actualizado_en, 'creado_en', p_lote.creado_en,
    'creado_por_nombre', (select nullif(btrim(p.nombre), '') from public.perfiles p where p.id = p_lote.creado_por),
    'es_mio', p_lote.creado_por is not distinct from p_yo,
    'purga_el', p_lote.creado_en + make_interval(days => p_dias),
    'enviados', coalesce((p_lote.resumen ->> 'cantidad')::int, 0),
    -- Un lote tiene a lo sumo 200 (índice `leads_lote_papelera_id_idx`).
    'leads', (
      select jsonb_agg(jsonb_build_object(
        'id', x.id, 'nombre', x.nombre,
        'motivo_de_bloqueo', public._lead_motivo_de_bloqueo(x, false),
        'motivo_de_restaurar', public._lead_motivo_de_restaurar(x))
               || public._lead_numeros(x, (select public.tiene_permiso('leads.numero_global.ver'))) order by x.numero)
      from public.leads x
      where x.id = any (array(select x0.id from public.leads x0
                                where x0.lote_papelera_id = p_lote.id and x0.eliminado_en is not null
                                order by x0.numero limit p_primeros))),
    -- Cuántos quedan en la papelera, exacto: un lote tiene a lo sumo 200 (contado sobre 201 para la guarda de escala).
    'en_papelera', (select count(*) from (select 1 from public.leads x where x.lote_papelera_id = p_lote.id
                                           and x.eliminado_en is not null limit 201) c));
$$;


ALTER FUNCTION "public"."_leads_papelera_lote_json"("p_lote" "public"."lotes_papelera", "p_dias" integer, "p_yo" "uuid", "p_primeros" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_leads_vista_crear"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_columnas text;
begin
  drop function if exists public.leads_vista_por_ids(uuid[]);
  drop view if exists public.leads_cartera_vista;
  drop view if exists public.leads_vista;
  create view public.leads_vista with (security_invoker = true) as
  select l.id,
         (select g.numero from public.leads_numeros_globales g where g.lead_id = l.id) as numero,
         l.nombre, l.telefono_cc,
         public.telefono_lead(l.id) as telefono_principal,
         coalesce((select auth.uid()) = any (l.cartera), false) as telefono_visible,
         l.tipo_lead_id, l.origen_lead_id,
         public.atributos_lead(l.id) as atributos,
         l.creado_por, l.ultimo_seguimiento_en, l.creado_en, l.actualizado_en,
         (fav.lead_id is not null) as es_favorito,
         (tach.lead_id is not null) as esta_tachado,
         (select la.usuario_id from public.leads_asesores la where la.lead_id = l.id and la.tipo_acceso = 'dueno' and la.revocado_en is null
                                                         and la.usuario_id <> all ((select public._bajas_en_curso())::uuid[])) as dueno_id,
         coalesce((select auth.uid()) = any (l.cartera), false) as en_cartera,
         array(select le.etiqueta_id from public.leads_etiquetas le join public.etiquetas e on e.id = le.etiqueta_id
                where le.lead_id = l.id and e.usuario_id = (select auth.uid()) order by le.etiqueta_id) as etiquetas,
         (select np.numero from public.leads_numeros_propios np where np.lead_id = l.id) as numero_propio,
         (select np.creado_por from public.leads_numeros_propios np where np.lead_id = l.id) as numero_propio_de,
         (select coalesce((select nullif(btrim(p.nombre), '') from public.perfiles p where p.id = np.creado_por), 'Otra persona')
            from public.leads_numeros_propios np
           where np.lead_id = l.id and np.creado_por <> (select auth.uid())) as numero_propio_creador,
         coalesce((select g.numero from public.leads_numeros_globales g where g.lead_id = l.id),
                  (select np.numero::bigint from public.leads_numeros_propios np where np.lead_id = l.id)) as numero_visible,
         l.atributos_publicos,
         coalesce(l.ultimo_seguimiento_en, l.creado_en) as reciente_en
  from public.leads l
  left join public.leads_favoritos fav on fav.lead_id = l.id and fav.usuario_id = (select auth.uid())
  left join public.leads_tachados tach on tach.lead_id = l.id and tach.usuario_id = (select auth.uid());
  grant select on public.leads_vista to authenticated;
  -- Se lee, nunca se escribe, y anon no la toca: lo que darían los privilegios por defecto de Supabase al recrearla se quita aquí.
  revoke all on public.leads_vista from anon;
  revoke insert, update, delete, truncate, references, trigger, maintain on public.leads_vista from authenticated;
  comment on view public.leads_vista is 'Lo que la app lee de los leads: teléfono enmascarado y atributos recortados según la cartera (atributos), y la copia de lo público (atributos_publicos, para filtrar un campo público). en_cartera = el lead está en la cartera de quien mira («míos»), de leads.cartera. reciente_en = el último seguimiento vivo del lead o, sin ninguno, su alta (el orden de «míos» del panel del cliente). Las marcas son de quien mira. security_invoker: la RLS de leads decide qué filas hay.';

  -- «Míos» por la cartera de quien mira: las mismas columnas, en el mismo orden, con `id` y `creado_en` de la fila de la cartera.
  select string_agg(
           case a.attname
             when 'id' then 'la.lead_id as id'
             when 'creado_en' then 'la.lead_creado_en as creado_en'
             when 'reciente_en' then 'la.lead_reciente_en as reciente_en'
             when 'en_cartera' then 'true as en_cartera'
             when 'telefono_visible' then 'true as telefono_visible'
             else 'v.' || quote_ident(a.attname)
           end, ', ' order by a.attnum)
    into v_columnas
    from pg_attribute a
   where a.attrelid = 'public.leads_vista'::regclass and a.attnum > 0 and not a.attisdropped;
  execute 'create view public.leads_cartera_vista with (security_invoker = true) as select ' || v_columnas
       || ' from public.leads_asesores la join public.leads_vista v on v.id = la.lead_id'
       || ' where la.usuario_id = (select auth.uid()) and la.revocado_en is null';
  revoke all on public.leads_cartera_vista from anon;
  grant select on public.leads_cartera_vista to authenticated;
  revoke insert, update, delete, truncate, references, trigger, maintain on public.leads_cartera_vista from authenticated;
  comment on view public.leads_cartera_vista is 'leads_vista de los leads que están en la cartera de quien mira («míos»), recorridos por su cartera (leads_asesores_listado_idx por el alta, leads_asesores_reciente_idx por lo reciente) y no por la tabla: cuesta lo que pesa la cartera de quien mira, no cuántos leads hay (cierre 5a-fix-1a). Mismas columnas que leads_vista; id, creado_en y reciente_en salen de la fila de la cartera (lead_creado_en y lead_reciente_en, copias que mantienen triggers) y en_cartera y telefono_visible son verdaderas por construcción. security_invoker: la regla de visibilidad (la policy de leads) se aplica igual. Lo que no es «míos» se lee de leads_vista.';
  -- La página de una búsqueda por candidatos (5a-fix-1b): `leads_vista` de los leads con esos ids. Invocador y SQL puro, `stable`, sin `strict`, sin `set` y sin
  -- `security definer`: así Postgres la inlinea en la consulta de PostgREST y los filtros, el cursor, el orden y el límite que le suma la app se empujan adentro
  -- (las columnas caras sólo se calculan para las filas que salen). Con cualquiera de esas cinco cosas deja de inlinearse y calcula todas las filas de los ids.
  -- Una prueba del catálogo (`busqueda-leads.sql`) falla si pierde esa forma. La RLS de `leads` decide, como siempre, qué filas hay.
  create function public.leads_vista_por_ids(p_leads uuid[]) returns setof public.leads_vista
    language sql stable as $por_ids$ select * from public.leads_vista v where v.id = any (p_leads) $por_ids$;
  revoke all on function public.leads_vista_por_ids(uuid[]) from public, anon;
  grant execute on function public.leads_vista_por_ids(uuid[]) to authenticated;
  comment on function public.leads_vista_por_ids(uuid[]) is 'leads_vista de los leads con esos ids (el segundo paso de la búsqueda por candidatos, 5a-fix-1b). Invocador: la RLS de leads decide qué filas hay. Se inlinea en la consulta de PostgREST: no le pongas strict, search_path, security definer ni volatile.';
end;
$_$;


ALTER FUNCTION "public"."_leads_vista_crear"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."vehiculos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "numero" bigint NOT NULL,
    "origen_id" "uuid" NOT NULL,
    "categoria_id" "uuid",
    "titulo" "text" NOT NULL,
    "marca" "text",
    "modelo" "text",
    "anio" smallint,
    "vin" "text",
    "lote" "text",
    "plataforma" "text",
    "url_origen" "text",
    "precio" numeric(18,2),
    "precio_negociable" boolean,
    "acepta_permuta" boolean,
    "placado" boolean,
    "kilometraje" integer,
    "atributos" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "subasta_en" timestamp with time zone,
    "subasta_fin_en" timestamp with time zone,
    "subasta_zona" "text",
    "estado_subasta" "public"."estado_subasta",
    "apibara_sync_en" timestamp with time zone,
    "apibara_raw" "jsonb",
    "importado_apibara" boolean DEFAULT false NOT NULL,
    "fase_id" "uuid",
    "fase_desde" timestamp with time zone,
    "lead_id" "uuid",
    "publicado_web" boolean DEFAULT false NOT NULL,
    "destacado_web" boolean DEFAULT false NOT NULL,
    "precio_web" numeric(18,2),
    "precio_web_hasta" numeric(18,2),
    "precio_web_nota" "text",
    "creado_por" "uuid",
    "eliminado_en" timestamp with time zone,
    "eliminado_por" "uuid",
    "lote_papelera_id" "uuid",
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "cotizado_en" timestamp with time zone,
    "cierre_subasta_en" timestamp with time zone GENERATED ALWAYS AS (
CASE
    WHEN ("estado_subasta" = ANY (ARRAY['abierta'::"public"."estado_subasta", 'en_vivo'::"public"."estado_subasta"])) THEN COALESCE("subasta_fin_en", "subasta_en")
    ELSE NULL::timestamp with time zone
END) STORED,
    CONSTRAINT "vehiculos_anio_check" CHECK ((("anio" IS NULL) OR (("anio" >= 1900) AND ("anio" <= 2100)))),
    CONSTRAINT "vehiculos_fase_desde_coherente" CHECK ((("fase_id" IS NULL) = ("fase_desde" IS NULL))),
    CONSTRAINT "vehiculos_vin_check" CHECK ((("vin" IS NULL) OR ("vin" ~ '^[A-HJ-NPR-Z0-9]{11,17}$'::"text")))
);


ALTER TABLE "public"."vehiculos" OWNER TO "postgres";


COMMENT ON TABLE "public"."vehiculos" IS 'Inventario. De sólo lectura para la app: se escribe por vehiculo_crear() y vehiculo_guardar(). fase_id y fase_desde los escriben cambiar_fase() y, sólo al nacer, vehiculo_crear() (entrada a la única fase inicial), sin mover la versión ni auditar (el cambio consta como unidad.fase_cambiada; 6.02-1). publicado_web lo escribe vehiculo_vitrina(); que además se vea en la web lo decide interno.vitrina_vehiculos (fase activa que publica, origen activo y visible, integración web activa). cotizado_en lo escribe sólo el trigger trg_vehiculo_cotizado de cotizaciones, sin mover la versión ni auditar. Papelera: eliminado_en + lote; una policy RESTRICTIVE esconde lo borrado a todos.';



COMMENT ON COLUMN "public"."vehiculos"."estado_subasta" IS 'abierta | en_vivo | terminada | vendida. Lo deriva _vehiculo_subasta_desde() de apibara_raw: nadie lo escribe a mano.';



COMMENT ON COLUMN "public"."vehiculos"."apibara_raw" IS 'La última respuesta de apibara, entera. La copia la base desde apibara_consultas: nunca llega del navegador.';



COMMENT ON COLUMN "public"."vehiculos"."importado_apibara" IS 'Nació de una consulta a apibara (vehiculo_crear con p_consulta). No cambia nunca: la limpieza automática sólo mira a estos.';



COMMENT ON COLUMN "public"."vehiculos"."cotizado_en" IS 'Cuándo se cotizó por última vez este vehículo: lo escribe sólo trg_vehiculo_cotizado (crear con él, o pasarle una cotización); nunca retrocede. No mueve actualizado_en ni se audita.';



COMMENT ON COLUMN "public"."vehiculos"."cierre_subasta_en" IS 'Cuándo cierra la subasta viva (abierta o en vivo): subasta_fin_en y, si no hay, subasta_en; nula si no está viva o no tiene fecha. Generada: nadie la escribe.';



CREATE OR REPLACE FUNCTION "public"."_limpieza_ancla"("v" "public"."vehiculos") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (select 1 from public.vehiculos_conservados c where c.vehiculo_id = v.id) then return 'conservar'; end if;
  if v.lead_id is not null then return 'vinculo'; end if;
  if v.fase_id is not null and exists (select 1 from public.fases f where f.id = v.fase_id and not f.es_inicial) then
    return 'fase';
  end if;
  -- Cuentan todas las filas, también las borradas: la purga las llevaría en cascada.
  if exists (select 1 from public.documentos d where d.vehiculo_id = v.id) then return 'documentos'; end if;
  if exists (select 1 from public.gastos g where g.vehiculo_id = v.id) then return 'gastos'; end if;
  if exists (select 1 from public.pagos p where p.vehiculo_id = v.id) then return 'pagos'; end if;
  if v.publicado_web then return 'vitrina'; end if;
  -- Una cotización final activa y viva (el predicado de `cotizaciones_final_por_vehiculo`, que la sostiene).
  if exists (select 1 from public.cotizaciones c
              where c.vehiculo_id = v.id and c.clase = 'final' and c.estado = 'activa' and c.eliminado_en is null) then
    return 'cotizacion_final';
  end if;
  -- Lo demás que la papelera manual rechaza (comprobante, declaración aduanera, repuestos): la
  -- limpieza nunca intenta lo que la puerta de siempre cerraría.
  if public._vehiculo_motivo_de_bloqueo(v, true) is not null then return 'bloqueo'; end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."_limpieza_ancla"("v" "public"."vehiculos") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_limpieza_aplica"("v" "public"."vehiculos") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select v.importado_apibara and v.eliminado_en is null
    and exists (select 1 from public.origenes o where o.id = v.origen_id and o.tipo = 'subasta');
$$;


ALTER FUNCTION "public"."_limpieza_aplica"("v" "public"."vehiculos") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_limpieza_fecha"("v" "public"."vehiculos", "p_ahora" timestamp with time zone, "p_proxima" "date") RETURNS "date"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare vence date;
begin
  if not (select e.limpieza_automatica from public.ajustes_empresa e where e.id = 1) then return null; end if;
  vence := public._limpieza_vence(v, p_ahora);
  if vence is null or public._limpieza_ancla(v) is not null then return null; end if;
  return greatest(vence, p_proxima);
end;
$$;


ALTER FUNCTION "public"."_limpieza_fecha"("v" "public"."vehiculos", "p_ahora" timestamp with time zone, "p_proxima" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_limpieza_hora"() RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$ select 3 $$;


ALTER FUNCTION "public"."_limpieza_hora"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_limpieza_proxima"("p_ahora" timestamp with time zone) RETURNS "date"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare hoy date;
begin
  select (p_ahora at time zone e.zona_horaria)::date into hoy from public.ajustes_empresa e where e.id = 1;
  if exists (select 1 from public.limpieza_corridas c where c.fecha = hoy and not c.parcial) then
    return hoy + 1;
  end if;
  return hoy;
end;
$$;


ALTER FUNCTION "public"."_limpieza_proxima"("p_ahora" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_limpieza_termino"("v" "public"."vehiculos", "p_ahora" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case
    when coalesce(v.subasta_fin_en, v.subasta_en) is not null
      then case when coalesce(v.subasta_fin_en, v.subasta_en) <= p_ahora then coalesce(v.subasta_fin_en, v.subasta_en) end
    when v.estado_subasta in ('terminada', 'vendida') then v.apibara_sync_en
  end;
$$;


ALTER FUNCTION "public"."_limpieza_termino"("v" "public"."vehiculos", "p_ahora" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_limpieza_vence"("v" "public"."vehiculos", "p_ahora" timestamp with time zone) RETURNS "date"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a public.ajustes_empresa; t timestamptz; l timestamp;
begin
  if not public._limpieza_aplica(v) then return null; end if;
  t := public._limpieza_termino(v, p_ahora);
  if t is null then return null; end if;
  select * into a from public.ajustes_empresa e where e.id = 1;
  l := (t + make_interval(days => a.limpieza_dias_gracia)) at time zone a.zona_horaria;
  return l::date + case when l::time > make_time(public._limpieza_hora(), 0, 0) then 1 else 0 end;
end;
$$;


ALTER FUNCTION "public"."_limpieza_vence"("v" "public"."vehiculos", "p_ahora" timestamp with time zone) OWNER TO "postgres";


