    LANGUAGE "sql" STABLE
    AS $$
  select case when (a = 0 or abs(a) between 1e-150::float8 and 1e150::float8) and abs(b) between 1e-150::float8 and 1e150::float8
              then a / b
              else public._motor_borde_entre(a, b) end
