CREATE TABLE IF NOT EXISTS "public"."oportunidades" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "lead_id" "uuid" NOT NULL,
    "vehiculo_id" "uuid",
    "usuario_id" "uuid" NOT NULL,
    "embudo_id" "uuid" NOT NULL,
    "etapa_id" "uuid" NOT NULL,
    "estado" "public"."estado_oportunidad" DEFAULT 'abierta'::"public"."estado_oportunidad" NOT NULL,
    "titulo" "text" NOT NULL,
    "notas" "text",
    "monto_estimado" numeric(18,2),
    "moneda" character(3) NOT NULL,
    "motivo_perdida" "text",
    "ultima_actividad_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "eliminado_en" timestamp with time zone,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "oportunidades_moneda_iso" CHECK (("moneda" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "oportunidades_monto_rango" CHECK ((("monto_estimado" IS NULL) OR (("monto_estimado" >= (0)::numeric) AND ("monto_estimado" < ('1000000000000'::bigint)::numeric)))),
    CONSTRAINT "oportunidades_motivo_largo" CHECK ((("motivo_perdida" IS NULL) OR ("char_length"("motivo_perdida") <= 200))),
    CONSTRAINT "oportunidades_notas_largo" CHECK ((("notas" IS NULL) OR ("char_length"("notas") <= 2000))),
    CONSTRAINT "oportunidades_titulo_largo" CHECK ((("char_length"("titulo") >= 1) AND ("char_length"("titulo") <= 120)))
);


ALTER TABLE "public"."oportunidades" OWNER TO "postgres";


COMMENT ON TABLE "public"."oportunidades" IS 'Negocios de un lead dentro de un embudo de una persona. Un lead puede tener varias. Ganada/perdida no la saca del kanban: queda en su columna final. Se escriben sólo por RPC (oportunidad_*): exigen ser su dueña, la cartera del lead y leads.editar. Sólo las ve su dueña, mientras tenga el lead en su cartera.';



CREATE OR REPLACE FUNCTION "public"."_oportunidad_constancia"("o" "public"."oportunidades", "p_antes" "public"."estado_oportunidad") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if o.estado in ('ganada', 'perdida') and o.estado is distinct from p_antes then
    perform public.registrar_actividad('oportunidad.' || o.estado, 'oportunidades', o.id::text, null, null,
      jsonb_build_object('lead', o.lead_id, 'etapa', o.etapa_id));
  end if;
end;
$$;


ALTER FUNCTION "public"."_oportunidad_constancia"("o" "public"."oportunidades", "p_antes" "public"."estado_oportunidad") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_oportunidad_json"("o" "public"."oportunidades") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', o.id, 'lead_id', o.lead_id, 'embudo_id', o.embudo_id, 'etapa_id', o.etapa_id, 'estado', o.estado,
    'titulo', o.titulo, 'notas', o.notas, 'monto_estimado', o.monto_estimado, 'moneda', o.moneda,
    'motivo_perdida', o.motivo_perdida, 'ultima_actividad_en', o.ultima_actividad_en,
    'creado_en', o.creado_en, 'actualizado_en', o.actualizado_en, 'eliminado', o.eliminado_en is not null,
    'vehiculo', case when o.vehiculo_id is not null and public.puede_vehiculo(o.vehiculo_id, 'vehiculos.ver') then
                  (select jsonb_build_object('id', v.id, 'titulo', v.titulo, 'numero', v.numero)
                     from public.vehiculos v where v.id = o.vehiculo_id) end,
    'vehiculo_oculto', o.vehiculo_id is not null and not public.puede_vehiculo(o.vehiculo_id, 'vehiculos.ver'));
$$;


ALTER FUNCTION "public"."_oportunidad_json"("o" "public"."oportunidades") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_oportunidad_mia"("p_id" "uuid", "p_eliminada" boolean DEFAULT false) RETURNS "public"."oportunidades"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.oportunidades; v_yo uuid := (select auth.uid());
begin
  perform public.assert_activo();
  select * into o from public.oportunidades x
   where x.id = p_id and x.usuario_id = v_yo and (x.eliminado_en is null) = not p_eliminada;
  if not found or not public.puede_actuar_lead(o.lead_id, 'leads.editar') then
    raise exception 'No encontramos esta oportunidad o no tienes acceso.' using errcode = '42501';
  end if;
  perform 1 from public.leads l where l.id = o.lead_id and l.eliminado_en is null for update;
  if not found or not public.puede_actuar_lead(o.lead_id, 'leads.editar') then
    raise exception 'No encontramos esta oportunidad o no tienes acceso.' using errcode = '42501';
  end if;
  select * into o from public.oportunidades x
   where x.id = p_id and x.usuario_id = v_yo and (x.eliminado_en is null) = not p_eliminada;
  if not found then
    raise exception 'No encontramos esta oportunidad o no tienes acceso.' using errcode = '42501';
  end if;
  perform 1 from public.embudos e where e.id = o.embudo_id for share;
  select * into o from public.oportunidades x
   where x.id = p_id and x.usuario_id = v_yo and (x.eliminado_en is null) = not p_eliminada for update;
  if not found then
    raise exception 'No encontramos esta oportunidad o no tienes acceso.' using errcode = '42501';
  end if;
  return o;
end;
$$;


ALTER FUNCTION "public"."_oportunidad_mia"("p_id" "uuid", "p_eliminada" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_oportunidad_monto"("p_valor" "jsonb") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v numeric;
begin
  if p_valor is null or p_valor = 'null'::jsonb then
    return null;
  end if;
  if jsonb_typeof(p_valor) <> 'number' then
    raise exception 'El monto tiene que ser un número.' using errcode = '22023', hint = 'monto_estimado';
  end if;
  v := (p_valor #>> '{}')::numeric;
  if v < 0 then
    raise exception 'El monto no puede ser negativo.' using errcode = '22023', hint = 'monto_estimado';
  end if;
  if v >= 1000000000000 then
    raise exception 'El monto es demasiado grande.' using errcode = '22023', hint = 'monto_estimado';
  end if;
  if v <> round(v, 2) then
    raise exception 'El monto lleva hasta 2 decimales.' using errcode = '22023', hint = 'monto_estimado';
  end if;
  return v;
end;
$$;


ALTER FUNCTION "public"."_oportunidad_monto"("p_valor" "jsonb") OWNER TO "postgres";


