    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('id', p.id, 'actualizado_en', p.actualizado_en, 'tipo_cambio_aplicado', p.tipo_cambio_aplicado, 'monto_base', p.monto_base)
         || p_extra;
$$;


ALTER FUNCTION "public"."_pago_respuesta"("p" "public"."pagos", "p_extra" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_pago_tomar"("p_id" "uuid") RETURNS "public"."pagos"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare o public.pagos;
begin
  perform public.assert_activo();
  select * into o from public.pagos x where x.id = p_id;
  if not found or o.eliminado_en is not null then
    raise exception 'Ese pago ya no existe.' using errcode = 'PT409';
  end if;
  perform public._pago_exigir_edicion(o);
  select * into o from public.pagos x where x.id = p_id for update;
  if o.eliminado_en is not null then
    raise exception 'Ese pago ya no existe.' using errcode = 'PT409';
  end if;
  if o.confirmado then
    raise exception 'Este pago ya está confirmado: no se edita ni se elimina.' using errcode = 'PT409';
  end if;
  return o;
end;
$$;


ALTER FUNCTION "public"."_pago_tomar"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_pago_validar"("p_unidad" "uuid", "p_concepto" "text", "p_metodo" "text", "p_monto" numeric, "p_ruta" "text") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if coalesce(length(btrim(p_concepto)), 0) not between 1 and 200 then
    raise exception 'Escribe el concepto del pago (hasta 200 caracteres).' using errcode = '22023', hint = 'concepto';
  end if;
  if length(p_metodo) > 100 then
    raise exception 'El método va en 100 caracteres como mucho.' using errcode = '22023', hint = 'metodo';
  end if;
  if p_monto is null then
    raise exception 'Falta el monto.' using errcode = '23502', hint = 'monto';
  end if;
  if p_monto <= 0 then
    raise exception 'El monto de un pago es mayor que cero.' using errcode = '22023', hint = 'monto';
  end if;
  if not public._comprobante_ruta_valida(p_unidad, p_ruta) then
    raise exception 'El comprobante no está en la carpeta de esta unidad.' using errcode = '22023', hint = 'comprobante_ruta';
  end if;
end;
$$;


ALTER FUNCTION "public"."_pago_validar"("p_unidad" "uuid", "p_concepto" "text", "p_metodo" "text", "p_monto" numeric, "p_ruta" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_pagos_requisitos_de_fase"("p_vehiculo" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_object_agg(r.id, public._requisito_dato_cumplido(p_vehiculo, null, r.clave_dato, r.config)), '{}'::jsonb)
    from public.vehiculos v join public.fases_requisitos r on r.fase_id = v.fase_id
   where v.id = p_vehiculo and r.tipo = 'dato' and r.clave_dato in ('pagos.confirmado', 'pagos.umbral_pct');
$$;


ALTER FUNCTION "public"."_pagos_requisitos_de_fase"("p_vehiculo" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_papelera_purgar_cotizaciones"("p_lote" "uuid", "p_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c record; v_rutas text[]; v_quedan int; v_version timestamptz;
  v_purgados jsonb := '[]'::jsonb; v_bloqueados jsonb := '[]'::jsonb;
begin
  for c in
    select x.id, x.numero, coalesce(x.titulo, 'Cotización #' || x.numero) as titulo from public.cotizaciones x
     where x.lote_papelera_id = p_lote and x.eliminado_en is not null and (p_ids is null or x.id = any (p_ids))
     order by x.id for update
  loop
    begin
      select array_agg(a.ruta) into v_rutas from public.cotizaciones_adjuntos a where a.cotizacion_id = c.id;
      delete from public.cotizaciones x where x.id = c.id;
      -- Después del borrado: el refcount ya no la cuenta (cotizaciones_adjuntos_ruta_idx).
      perform public._encolar_para_limpiar('cotizaciones', v_rutas, false);
      v_purgados := v_purgados || jsonb_build_object('id', c.id, 'numero', c.numero, 'titulo', c.titulo);
    exception when foreign_key_violation or restrict_violation then
      v_bloqueados := v_bloqueados || jsonb_build_object('id', c.id, 'numero', c.numero, 'titulo', c.titulo, 'motivo', 'Otros registros dependen de ella.');
    end;
  end loop;

  -- Cuántas siguen en la papelera del lote (a lo sumo 200 por lote; cotizaciones_lote_papelera_idx).
  select count(*) into v_quedan from (
    select 1 from public.cotizaciones x where x.lote_papelera_id = p_lote and x.eliminado_en is not null limit 201) q;
  if jsonb_array_length(v_purgados) = 0 then
    return jsonb_build_object('actualizado_en', (select l.actualizado_en from public.lotes_papelera l where l.id = p_lote),
      'purgados', v_purgados, 'bloqueados', v_bloqueados, 'quedan', v_quedan);
  end if;
  update public.lotes_papelera l
  set resumen = l.resumen || jsonb_build_object('purgados', coalesce((l.resumen ->> 'purgados')::int, 0) + jsonb_array_length(v_purgados)),
      purgado_en = case when v_quedan = 0 then now() else l.purgado_en end
  where l.id = p_lote;
  v_version := public._lote_papelera_tocar(p_lote);
  perform public.registrar_actividad('papelera.purgado', 'lotes_papelera', p_lote::text, null, null,
    jsonb_build_object('tipo', 'cotizaciones', 'cantidad', jsonb_array_length(v_purgados), 'automatica', (select auth.uid()) is null));
  return jsonb_build_object('actualizado_en', v_version, 'purgados', v_purgados, 'bloqueados', v_bloqueados, 'quedan', v_quedan);
end;
$$;


ALTER FUNCTION "public"."_papelera_purgar_cotizaciones"("p_lote" "uuid", "p_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_papelera_purgar_cotizaciones"("p_lote" "uuid", "p_ids" "uuid"[]) IS 'Borra para siempre del lote las cotizaciones en la papelera (p_ids nulo: todas), una a una por id, con sus hijas; encola las rutas de sus adjuntos que ya nadie nombra; lo que otra tabla necesita (un comprobante) queda en bloqueados. Devuelve {actualizado_en, purgados, bloqueados, quedan}. De nadie: la llaman cotizaciones_papelera_purgar, papelera_purgar y papelera_purgar_vencidos.';



CREATE OR REPLACE FUNCTION "public"."_papelera_purgar_leads"("p_lote" "uuid", "p_leads" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  x public.leads; v_motivo text; v_quedan int; v_version timestamptz;
  v_purgados jsonb := '[]'::jsonb; v_bloqueados jsonb := '[]'::jsonb;
  v_ve boolean := public.tiene_permiso('leads.numero_global.ver');
begin
  for x in
    select * from public.leads y
    where y.lote_papelera_id = p_lote and y.eliminado_en is not null and (p_leads is null or y.id = any (p_leads))
    order by y.id for update
  loop
    v_motivo := public._lead_motivo_de_bloqueo(x, false);
    if v_motivo is null then
      begin
        delete from public.leads y where y.id = x.id;
        v_purgados := v_purgados || (jsonb_build_object('id', x.id, 'nombre', x.nombre) || public._lead_numeros(x, v_ve));
      exception when foreign_key_violation then
        v_motivo := 'Otros registros dependen de él.';
      end;
    end if;
    if v_motivo is not null then
      v_bloqueados := v_bloqueados || (jsonb_build_object('id', x.id, 'nombre', x.nombre, 'motivo', v_motivo) || public._lead_numeros(x, v_ve));
    end if;
  end loop;

  select count(*) into v_quedan from public.leads y where y.lote_papelera_id = p_lote and y.eliminado_en is not null;
  if jsonb_array_length(v_purgados) = 0 then
    return jsonb_build_object('actualizado_en', (select z.actualizado_en from public.lotes_papelera z where z.id = p_lote),
      'purgados', v_purgados, 'bloqueados', v_bloqueados, 'quedan', v_quedan);
  end if;
  update public.lotes_papelera z
  set resumen = z.resumen || jsonb_build_object('purgados', coalesce((z.resumen ->> 'purgados')::int, 0) + jsonb_array_length(v_purgados)),
      purgado_en = case when v_quedan = 0 then now() else z.purgado_en end
  where z.id = p_lote;
  v_version := public._lote_papelera_tocar(p_lote);
  perform public.registrar_actividad('papelera.purgado', 'lotes_papelera', p_lote::text, null, null,
    jsonb_build_object('tipo', 'leads', 'cantidad', jsonb_array_length(v_purgados), 'automatica', (select auth.uid()) is null));
  return jsonb_build_object('actualizado_en', v_version, 'purgados', v_purgados, 'bloqueados', v_bloqueados, 'quedan', v_quedan);
end;
$$;


ALTER FUNCTION "public"."_papelera_purgar_leads"("p_lote" "uuid", "p_leads" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_papelera_purgar_vehiculos"("p_lote" "uuid", "p_vehiculos" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.vehiculos; v_motivo text; v_fotos text[]; v_documentos text[]; v_adjuntos text[]; v_quedan int; v_version timestamptz;
  v_purgados jsonb := '[]'::jsonb; v_bloqueados jsonb := '[]'::jsonb;
begin
  for v in
    select * from public.vehiculos x
    where x.lote_papelera_id = p_lote and x.eliminado_en is not null and (p_vehiculos is null or x.id = any (p_vehiculos))
    order by x.id for update
  loop
    v_motivo := public._vehiculo_motivo_de_bloqueo(v, false);
    if v_motivo is null then
      begin
        select array_agg(distinct r) into v_fotos from (
          select unnest(array[i.ruta, i.ruta_miniatura]) as r from public.vehiculos_imagenes i where i.vehiculo_id = v.id
          union all
          select o.name from storage.objects o where o.bucket_id = 'vehiculos' and o.name like v.id::text || '/%'
          union all
          select c.ruta from public.cola_gc_storage c where c.bucket = 'vehiculos' and c.ruta like v.id::text || '/%' and c.reclamado_en is null
        ) x;
        select array_agg(d.ruta) into v_documentos from public.documentos d where d.vehiculo_id = v.id and d.ruta is not null;
        select array_agg(a.ruta) into v_adjuntos
        from public.cotizaciones_adjuntos a join public.cotizaciones c on c.id = a.cotizacion_id
        where c.vehiculo_id = v.id and c.lote_papelera_id = p_lote;

        delete from public.cotizaciones c where c.vehiculo_id = v.id and c.lote_papelera_id = p_lote;
        delete from public.vehiculos x where x.id = v.id;

        perform public._encolar_para_limpiar('vehiculos', v_fotos, true);
        perform public._encolar_para_limpiar('documentos', v_documentos, false);
        perform public._encolar_para_limpiar('cotizaciones', v_adjuntos, false);
        v_purgados := v_purgados || jsonb_build_object('id', v.id, 'numero', v.numero, 'titulo', v.titulo);
      exception when foreign_key_violation then
        v_motivo := 'Otros registros dependen de él.';
      end;
    end if;
    if v_motivo is not null then
      v_bloqueados := v_bloqueados || jsonb_build_object('id', v.id, 'numero', v.numero, 'titulo', v.titulo, 'motivo', v_motivo);
    end if;
  end loop;

  select count(*) into v_quedan from public.vehiculos x where x.lote_papelera_id = p_lote and x.eliminado_en is not null;
  if jsonb_array_length(v_purgados) = 0 then
    return jsonb_build_object('actualizado_en', (select l.actualizado_en from public.lotes_papelera l where l.id = p_lote),
      'purgados', v_purgados, 'bloqueados', v_bloqueados, 'quedan', v_quedan);
  end if;
  update public.lotes_papelera l
  set resumen = l.resumen || jsonb_build_object('purgados', coalesce((l.resumen ->> 'purgados')::int, 0) + jsonb_array_length(v_purgados)),
      purgado_en = case when v_quedan = 0 then now() else l.purgado_en end
  where l.id = p_lote;
  v_version := public._lote_papelera_tocar(p_lote);
  perform public.registrar_actividad('papelera.purgado', 'lotes_papelera', p_lote::text, null, null,
    jsonb_build_object('cantidad', jsonb_array_length(v_purgados), 'automatica', (select auth.uid()) is null));
  return jsonb_build_object('actualizado_en', v_version, 'purgados', v_purgados, 'bloqueados', v_bloqueados, 'quedan', v_quedan);
end;
$$;


ALTER FUNCTION "public"."_papelera_purgar_vehiculos"("p_lote" "uuid", "p_vehiculos" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_papelera_restaurar_cotizaciones"("p_lote" "uuid", "p_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c record; v_vehiculo uuid; v_lead uuid; v_clase public.clase_cotizacion; v_vehiculo_fuera boolean; v_lead_fuera boolean;
  v_motivo text; v_restriccion text; v_quedan int; v_version timestamptz;
  v_restaurados jsonb := '[]'::jsonb; v_pendientes jsonb := '[]'::jsonb;
begin
  -- 0. Antes de tomar cotización alguna, sus vehículos y después sus leads, por id (cotizaciones_lote_papelera_idx; las PK).
  perform 1 from public.vehiculos v
   where v.id in (select x.vehiculo_id from public.cotizaciones x
                   where x.lote_papelera_id = p_lote and x.eliminado_en is not null and (p_ids is null or x.id = any (p_ids)))
   order by v.id for key share;
  perform 1 from public.leads d
   where d.id in (select x.lead_id from public.cotizaciones x
                   where x.lote_papelera_id = p_lote and x.eliminado_en is not null and (p_ids is null or x.id = any (p_ids)))
   order by d.id for key share;

  for c in
    select x.id, x.numero, coalesce(x.titulo, 'Cotización #' || x.numero) as titulo from public.cotizaciones x
     where x.lote_papelera_id = p_lote and x.eliminado_en is not null and (p_ids is null or x.id = any (p_ids))
     order by x.id for no key update
  loop
    begin
      -- 1. Sobre la fila tomada (la FK pudo poner nulos el vehículo o el lead mientras se esperaba).
      select x.vehiculo_id, x.lead_id, x.clase into v_vehiculo, v_lead, v_clase from public.cotizaciones x where x.id = c.id;
      v_vehiculo_fuera := false; v_lead_fuera := false;
      if v_vehiculo is not null then
        select v.eliminado_en is not null into v_vehiculo_fuera from public.vehiculos v where v.id = v_vehiculo for key share;
      end if;
      if v_lead is not null then
        select d.eliminado_en is not null into v_lead_fuera from public.leads d where d.id = v_lead for key share;
      end if;
      v_motivo := case
        when v_vehiculo_fuera then 'Su vehículo está en la papelera.'
        when v_lead_fuera then 'Su cliente está en la papelera.'
        when v_clase = 'final' and v_vehiculo is null then 'Su vehículo ya no existe.'
      end;
      -- 2. Si nada la detiene, vuelve.
      if v_motivo is null then
        update public.cotizaciones x set eliminado_en = null, eliminado_por = null, lote_papelera_id = null where x.id = c.id;
      end if;
    exception
      when unique_violation then
        get stacked diagnostics v_restriccion = constraint_name;
        v_motivo := case v_restriccion
          when 'cotizaciones_encima_unica' then 'Esa cotización ya tiene otra versión nueva.'
          when 'cotizaciones_final_por_vehiculo' then 'Ese vehículo ya tiene otra cotización final.'
          else 'Choca con otro registro que ya existe.'
        end;
      when check_violation then
        -- La red por si la tabla suma reglas: su texto es nuestro.
        get stacked diagnostics v_motivo = message_text;
    end;
    if v_motivo is null then
      v_restaurados := v_restaurados || jsonb_build_object('id', c.id, 'numero', c.numero, 'titulo', c.titulo);
    else
      v_pendientes := v_pendientes || jsonb_build_object('id', c.id, 'numero', c.numero, 'titulo', c.titulo, 'motivo', v_motivo);
    end if;
  end loop;

  -- Cuántas siguen en la papelera del lote (a lo sumo 200 por lote; cotizaciones_lote_papelera_idx).
  select count(*) into v_quedan from (
    select 1 from public.cotizaciones x where x.lote_papelera_id = p_lote and x.eliminado_en is not null limit 201) q;
  if jsonb_array_length(v_restaurados) = 0 then
    return jsonb_build_object('actualizado_en', (select l.actualizado_en from public.lotes_papelera l where l.id = p_lote),
      'restaurados', v_restaurados, 'pendientes', v_pendientes, 'quedan', v_quedan);
  end if;
  update public.lotes_papelera l
  set resumen = l.resumen || jsonb_build_object('restaurados', coalesce((l.resumen ->> 'restaurados')::int, 0) + jsonb_array_length(v_restaurados)),
      restaurado_en = case when v_quedan = 0 then now() else l.restaurado_en end,
      restaurado_por = case when v_quedan = 0 then (select auth.uid()) else l.restaurado_por end
  where l.id = p_lote;
  v_version := public._lote_papelera_tocar(p_lote);
  perform public.registrar_actividad('papelera.restaurado', 'lotes_papelera', p_lote::text, null, null,
    jsonb_build_object('tipo', 'cotizaciones', 'cantidad', jsonb_array_length(v_restaurados)));
  return jsonb_build_object('actualizado_en', v_version, 'restaurados', v_restaurados, 'pendientes', v_pendientes, 'quedan', v_quedan);
end;
$$;


ALTER FUNCTION "public"."_papelera_restaurar_cotizaciones"("p_lote" "uuid", "p_ids" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_papelera_restaurar_cotizaciones"("p_lote" "uuid", "p_ids" "uuid"[]) IS 'Restaura del lote las cotizaciones en la papelera (p_ids nulo: todas), una a una por id: toma antes sus vehículos y sus leads for key share; lo que choca con otra viva, cuelga de un vehículo o cliente en la papelera o es una final sin vehículo queda en pendientes con su motivo. Devuelve {actualizado_en, restaurados, pendientes, quedan}. De nadie: la llaman cotizaciones_papelera_restaurar y papelera_restaurar.';



CREATE OR REPLACE FUNCTION "public"."_papelera_solo_cotizaciones"("p_tipo" "public"."tipo_lote_papelera") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if p_tipo = 'vehiculos' then
    raise exception 'Los vehículos tienen su propia papelera: usa vehiculos_papelera_*().' using errcode = '22023';
  elsif p_tipo = 'leads' then
    raise exception 'Los leads tienen su propia papelera: usa leads_papelera_*().' using errcode = '22023';
  end if;
end;
$$;


ALTER FUNCTION "public"."_papelera_solo_cotizaciones"("p_tipo" "public"."tipo_lote_papelera") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_personas_dominadas"("p_ids" "uuid"[]) RETURNS SETOF "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with mias as materialized (select * from public.mis_permisos()),
  soy_dueno as materialized (
    select exists (
      select 1 from public.usuarios_roles ur
      join public.roles r on r.id = ur.rol_id
      join public.perfiles p on p.id = ur.usuario_id
      where ur.usuario_id = (select auth.uid()) and r.clave = 'dueno' and p.activo and not p.bloqueado
    ) as si
  )
  select p.id from public.perfiles p
  where p.id = any (coalesce(p_ids, '{}'::uuid[]))
    and (
      (select si from soy_dueno)
      or not exists (
        select 1 from public.usuarios_roles ur
        join public.roles_permisos rp on rp.rol_id = ur.rol_id
        where ur.usuario_id = p.id
          and not exists (
            select 1 from mias m
            where m.clave = rp.permiso_clave
              and (m.origen_id is null or m.origen_id = rp.origen_id)
              and (m.alcance = 'todos' or rp.alcance = 'propios')
          )
      )
    );
$$;


ALTER FUNCTION "public"."_personas_dominadas"("p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_plantilla_borrador_ausente"("p_origen" "uuid", "p_esperada" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_pub public.plantillas_tarjeta;
begin
  select * into v_pub from public.plantillas_tarjeta where origen_id = p_origen and estado = 'publicada';
  if v_pub.id is not null and v_pub.publicado_en >= p_esperada then
    raise exception 'El borrador ya no está: la versión % se publicó %.', v_pub.version, public._hace(v_pub.publicado_en) using errcode = 'PT409';
  end if;
  raise exception 'El borrador ya no está: se descartó.' using errcode = 'PT409';
end;
$$;


ALTER FUNCTION "public"."_plantilla_borrador_ausente"("p_origen" "uuid", "p_esperada" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_plantilla_borrador_ausente"("p_origen" "uuid", "p_esperada" timestamp with time zone) IS 'Interna: el PT409 de guardar, publicar o descartar un borrador que ya no está (se publicó o se descartó). docs/COTIZADOR.md › «Versiones de la plantilla (4.19-1)».';



CREATE OR REPLACE FUNCTION "public"."_plantilla_forma"("p_plantilla" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_id constant text := '^[a-z][a-z0-9_]{0,40}$';
  v_k text; v_x jsonb; v_g jsonb; v_dic text; v_min int; v_max int;
begin
  if jsonb_typeof(p_plantilla) is distinct from 'object' or octet_length(p_plantilla::text) > 32768 then
    perform public._formula_rechazar('forma', 'definicion', 'La plantilla no tiene la forma esperada.');
  end if;
  select k into v_k from jsonb_object_keys(p_plantilla) k
   where k not in ('grupos', 'etiquetas', 'leyendas', 'total', 'nota', 'logo', 'columnas') order by k collate "C" limit 1;
  if v_k is not null then perform public._formula_rechazar('forma', v_k, 'La plantilla no tiene la forma esperada.'); end if;

  -- Los grupos: hasta 20 {grupo, tono?}, con la forma de un id.
  v_x := p_plantilla -> 'grupos';
  if jsonb_typeof(v_x) is distinct from 'array' or jsonb_array_length(v_x) > 20 then perform public._formula_rechazar('forma', 'grupos', 'La plantilla no tiene la forma esperada.'); end if;
  for i in 0 .. jsonb_array_length(v_x) - 1 loop
    v_g := v_x -> i;
    if jsonb_typeof(v_g) is distinct from 'object' then perform public._formula_rechazar('forma', format('grupos[%s]', i), 'La plantilla no tiene la forma esperada.'); end if;
    if exists (select 1 from jsonb_object_keys(v_g) k where k not in ('grupo', 'tono')) then
      perform public._formula_rechazar('forma', format('grupos[%s]', i), 'La plantilla no tiene la forma esperada.');
    end if;
    if jsonb_typeof(v_g -> 'grupo') is distinct from 'string' or (v_g ->> 'grupo') !~ v_id then
      perform public._formula_rechazar('forma', format('grupos[%s].grupo', i), 'La plantilla no tiene la forma esperada.');
    end if;
    if v_g ? 'tono' and (jsonb_typeof(v_g -> 'tono') is distinct from 'string' or (v_g ->> 'tono') !~ v_id) then
      perform public._formula_rechazar('forma', format('grupos[%s].tono', i), 'La plantilla no tiene la forma esperada.');
    end if;
  end loop;

  -- Etiquetas (1 a 60 caracteres) y leyendas (0 a 160; vacía = sin leyenda) por nodo: hasta 200 claves cada una, en orden de bytes.
  foreach v_dic in array array['etiquetas', 'leyendas'] loop
    continue when not p_plantilla ? v_dic;
    v_x := p_plantilla -> v_dic;
    if jsonb_typeof(v_x) is distinct from 'object' then perform public._formula_rechazar('forma', v_dic, 'La plantilla no tiene la forma esperada.'); end if;
    if cardinality(array(select jsonb_object_keys(v_x))) > 200 then perform public._formula_rechazar('forma', v_dic, 'La plantilla no tiene la forma esperada.'); end if;
    v_min := case when v_dic = 'etiquetas' then 1 else 0 end;
    v_max := case when v_dic = 'etiquetas' then 60 else 160 end;
    for v_k, v_g in select e.key, e.value from jsonb_each(v_x) e order by e.key collate "C" loop
      if v_k !~ v_id then perform public._formula_rechazar('forma', v_dic, 'La plantilla no tiene la forma esperada.'); end if;
      if jsonb_typeof(v_g) is distinct from 'string' or char_length(btrim(v_g #>> '{}')) < v_min or char_length(v_g #>> '{}') > v_max then
        perform public._formula_rechazar('forma', v_dic || '.' || v_k, 'La plantilla no tiene la forma esperada.');
      end if;
    end loop;
  end loop;

  -- El total ({etiqueta de 1 a 40, leyenda? hasta 160}), la nota (hasta 300), el logo y las tres columnas.
  v_x := p_plantilla -> 'total';
  if jsonb_typeof(v_x) is distinct from 'object' then perform public._formula_rechazar('forma', 'total', 'La plantilla no tiene la forma esperada.'); end if;
  if exists (select 1 from jsonb_object_keys(v_x) k where k not in ('etiqueta', 'leyenda')) then perform public._formula_rechazar('forma', 'total', 'La plantilla no tiene la forma esperada.'); end if;
  if jsonb_typeof(v_x -> 'etiqueta') is distinct from 'string' or char_length(btrim(v_x ->> 'etiqueta')) < 1 or char_length(v_x ->> 'etiqueta') > 40 then
    perform public._formula_rechazar('forma', 'total.etiqueta', 'La plantilla no tiene la forma esperada.');
  end if;
  if v_x ? 'leyenda' and (jsonb_typeof(v_x -> 'leyenda') is distinct from 'string' or char_length(v_x ->> 'leyenda') > 160) then
    perform public._formula_rechazar('forma', 'total.leyenda', 'La plantilla no tiene la forma esperada.');
  end if;
  if p_plantilla ? 'nota' and (jsonb_typeof(p_plantilla -> 'nota') is distinct from 'string' or char_length(p_plantilla ->> 'nota') > 300) then
    perform public._formula_rechazar('forma', 'nota', 'La plantilla no tiene la forma esperada.');
  end if;
  if jsonb_typeof(p_plantilla -> 'logo') is distinct from 'boolean' then perform public._formula_rechazar('forma', 'logo', 'La plantilla no tiene la forma esperada.'); end if;
  v_x := p_plantilla -> 'columnas';
  if jsonb_typeof(v_x) is distinct from 'object' then perform public._formula_rechazar('forma', 'columnas', 'La plantilla no tiene la forma esperada.'); end if;
  if array(select k from jsonb_object_keys(v_x) k order by k collate "C") is distinct from array['leyenda', 'plazo', 'tipo_cambio']
     or exists (select 1 from jsonb_each(v_x) e where jsonb_typeof(e.value) <> 'boolean') then
    perform public._formula_rechazar('forma', 'columnas', 'La plantilla no tiene la forma esperada.');
  end if;
end;
$_$;


ALTER FUNCTION "public"."_plantilla_forma"("p_plantilla" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_plantilla_nodos"("p_plantilla" "jsonb", "p_def" "jsonb", "p_diseno" "jsonb", "p_visibilidad" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_nodos jsonb; v_lugar jsonb; v_vis jsonb; v_usados jsonb; v_nombrados jsonb; v_total text; v_k text;
begin
  v_nodos := coalesce((select jsonb_object_agg(n ->> 'id', n) from jsonb_array_elements(coalesce(p_def -> 'nodos', '[]'::jsonb)) n), '{}'::jsonb);
  v_vis := coalesce(p_visibilidad, '{}'::jsonb);
  select n ->> 'id' into v_total from jsonb_array_elements(coalesce(p_def -> 'nodos', '[]'::jsonb)) n where n ->> 'salida' = 'total' limit 1;
  v_lugar := coalesce((select jsonb_object_agg(n ->> 'id', true) from jsonb_array_elements(coalesce(p_def -> 'nodos', '[]'::jsonb)) n where n ->> 'grupo' is not null), '{}'::jsonb)
          || coalesce((select jsonb_object_agg(s, true) from jsonb_array_elements_text(coalesce(p_diseno -> 'tarjeta_total' -> 'secundarios', '[]'::jsonb)) s), '{}'::jsonb)
          || case when v_total is null then '{}'::jsonb else jsonb_build_object(v_total, true) end;

  -- Las claves nombradas: las de etiquetas y después las de leyendas, cada una en orden de bytes.
  v_nombrados := coalesce((select jsonb_agg(jsonb_build_object('clave', k, 'd', 1)) from jsonb_object_keys(coalesce(p_plantilla -> 'etiquetas', '{}'::jsonb)) k), '[]'::jsonb)
              || coalesce((select jsonb_agg(jsonb_build_object('clave', k, 'd', 2)) from jsonb_object_keys(coalesce(p_plantilla -> 'leyendas', '{}'::jsonb)) k), '[]'::jsonb);
  select x.clave into v_k from jsonb_to_recordset(v_nombrados) x (clave text, d int) where not v_nodos ? x.clave order by x.d, x.clave collate "C" limit 1;
  if v_k is not null then perform public._formula_rechazar('nodo_inexistente', v_k, format('La plantilla nombra «%s», que no es un nodo de la fórmula.', v_k)); end if;
  select x.clave into v_k from jsonb_to_recordset(v_nombrados) x (clave text, d int) where not v_lugar ? x.clave order by x.d, x.clave collate "C" limit 1;
  if v_k is not null then perform public._formula_rechazar('nodo_sin_lugar', v_k, format('El nodo «%s» no va en la tarjeta: no es de un grupo, el total ni lo aparte.', v_k)); end if;

  -- Lo que dibuja: los miembros en el orden de la fórmula, el total, lo aparte y (defensivo: nodo_sin_lugar va antes) lo nombrado.
  select x.id into v_k from (
    select n ->> 'id' as id, 1 as d, o as ord from jsonb_array_elements(coalesce(p_def -> 'nodos', '[]'::jsonb)) with ordinality t (n, o) where n ->> 'grupo' is not null
    union all select v_total, 2, 0 where v_total is not null
    union all select s, 3, o from jsonb_array_elements_text(coalesce(p_diseno -> 'tarjeta_total' -> 'secundarios', '[]'::jsonb)) with ordinality t (s, o)
    union all select y.clave, 4, y.d from jsonb_to_recordset(v_nombrados) y (clave text, d int)) x
   where coalesce(v_vis -> x.id ->> 'ver', '') <> 'todos'
   order by x.d, x.ord, x.id collate "C" limit 1;
  if v_k is not null then perform public._formula_rechazar('nodo_restringido', v_k, format('La tarjeta no puede mostrar «%s»: no es del nivel «todos».', v_k)); end if;

  -- Con la columna del tipo de cambio, el de cada bucket que usa un grupo (por omisión y en cada modo del diseño) es del nivel «todos».
  if coalesce((p_plantilla -> 'columnas' ->> 'tipo_cambio')::boolean, false) then
    v_usados := coalesce((select jsonb_object_agg(g ->> 'bucket', true) from jsonb_array_elements(coalesce(p_def -> 'grupos', '[]'::jsonb)) g where g ->> 'bucket' is not null), '{}'::jsonb);
    select x.id into v_k from (
      select p_def -> 'buckets' ->> b as id, 1 as d, 0::bigint as ord, b from jsonb_object_keys(v_usados) b
      union all
      select mb ->> 'nodo', 2, m.o * 1000 + t.o, mb ->> 'bucket'
        from jsonb_array_elements(coalesce(p_diseno -> 'cabecera' -> 'modos', '[]'::jsonb)) with ordinality m (v, o)
       cross join lateral jsonb_array_elements(coalesce(m.v -> 'buckets', '[]'::jsonb)) with ordinality t (mb, o)
       where v_usados ? (mb ->> 'bucket')) x
     where x.id is not null and coalesce(v_vis -> x.id ->> 'ver', '') <> 'todos'
     order by x.d, x.ord, x.b collate "C" limit 1;
    if v_k is not null then
      perform public._formula_rechazar('tipo_de_cambio_restringido', v_k, format('La tarjeta no puede nombrar el tipo de cambio de «%s»: no es del nivel «todos».', v_k));
    end if;
  end if;
end;
$$;


ALTER FUNCTION "public"."_plantilla_nodos"("p_plantilla" "jsonb", "p_def" "jsonb", "p_diseno" "jsonb", "p_visibilidad" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_portal_clave_validar"("p_clave" "text") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if length(coalesce(p_clave, '')) < 8 then
    raise exception 'La clave necesita al menos 8 caracteres.' using errcode = '22023', hint = 'clave';
  end if;
  if length(p_clave) > 64 then
    raise exception 'La clave puede tener hasta 64 caracteres.' using errcode = '22023', hint = 'clave';
  end if;
  if octet_length(p_clave) > 72 then
    raise exception 'La clave es demasiado larga: usa menos tildes o símbolos.' using errcode = '22023', hint = 'clave';
  end if;
  if p_clave ~ '[[:cntrl:]]' then
    raise exception 'La clave no puede llevar saltos de línea ni tabulaciones.' using errcode = '22023', hint = 'clave';
  end if;
end;
$$;


ALTER FUNCTION "public"."_portal_clave_validar"("p_clave" "text") OWNER TO "postgres";


