CREATE OR REPLACE FUNCTION "public"."_preparar_publicacion"("p_def" "jsonb", "p_params" "jsonb", "p_diseno" "jsonb", "p_ignorar_retirados" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_niv text[]; v_ret text[]; v_tonos text[];
begin
  if p_diseno is null then
    perform public._formula_rechazar('diseno_faltante', 'diseno', 'Publicar pide el diseño de la hoja.');
  end if;
  -- Los tonos de los grupos y los niveles del diseño, `for key share`: o se publica y no se eliminan, o se eliminan y publicar da `tono_inexistente` o
  -- `nivel_inexistente`. Sólo los que se nombran, no toda la lista.
  perform 1 from public.tonos t where t.clave in (select jsonb_array_elements_text(public._tonos_de_grupos(p_def))) for key share;
  perform 1 from public.cotizaciones_niveles n where n.clave in (select jsonb_array_elements_text(public._niveles_del_diseno(p_diseno))) for key share;
  select coalesce(array_agg(t.clave), '{}') into v_tonos from public.tonos t;
  select n.niveles, case when p_ignorar_retirados then '{}'::text[] else n.retirados end into v_niv, v_ret from public._niveles_de_cotizacion() n;
  perform public.validar_formula(p_def, p_params);
  perform public.validar_diseno(p_def, p_diseno, v_niv, v_ret, v_tonos);
  return public._compilar_visibilidad(p_def, p_diseno);
end; $$;


ALTER FUNCTION "public"."_preparar_publicacion"("p_def" "jsonb", "p_params" "jsonb", "p_diseno" "jsonb", "p_ignorar_retirados" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_publicar_formula"("p_origen" "uuid", "p_nota" "text", "p_publicada_esperada" "uuid", "p_ignorar_retirados" boolean, "p_actualizado_en_esperado" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_b public.formulas; v_pub uuid; v_ver int; v_vis jsonb; v_f text;
begin
  perform public.assert_permiso('cotizaciones.configurar', p_origen);
  if coalesce(trim(p_nota), '') = '' then raise exception 'Publicar pide una nota.' using errcode = '22023'; end if;
  -- Guardar, publicar, el ⚙ y revertir de un origen, en serie: el segundo relee la publicada y el borrador y los compara con sus esperadas.
  perform pg_advisory_xact_lock(hashtextextended('formulas:' || p_origen::text, 0));
  select * into v_b from public.formulas where origen_id = p_origen and estado = 'borrador' for update;
  select id into v_pub from public.formulas where origen_id = p_origen and estado = 'publicada';
  if p_publicada_esperada is not null and v_pub is distinct from p_publicada_esperada then
    if v_pub is null then
      raise exception 'La versión que tenías ya no es la publicada, y el origen no tiene otra.' using errcode = 'PT409';
    end if;
    v_f := public._version_publicada_por(v_pub);
    raise exception '%.', upper(left(v_f, 1)) || substr(v_f, 2) using errcode = 'PT409';
  end if;
  perform public._exigir_borrador_formula(v_b, p_actualizado_en_esperado);
  if v_b.id is null then raise exception 'No hay borrador para publicar.' using errcode = '22023'; end if;
  if v_b.version_origen_id is not null and v_b.version_origen_id is distinct from v_pub then
    raise exception 'Después de que empezaste este borrador, %.', coalesce(public._version_publicada_por(v_pub), 'la versión publicada cambió')
      using errcode = 'PT409';
  end if;

  v_vis := public._preparar_publicacion(v_b.definicion, v_b.params, v_b.diseno, p_ignorar_retirados);

  select coalesce(max(version), 0) + 1 into v_ver from public.formulas where origen_id = p_origen;
  update public.formulas set estado = 'archivada' where id = v_pub;
  update public.formulas set estado = 'publicada', version = v_ver, nota = p_nota, visibilidad = v_vis, publicado_por = (select auth.uid()),
         publicado_en = now(), version_origen_id = v_pub where id = v_b.id;
  perform public.registrar_actividad('formula.publicada', 'formulas', v_b.id::text, jsonb_build_object('anterior', v_pub), jsonb_build_object('version', v_ver, 'nota', p_nota));
  return v_b.id;
end;
$$;


ALTER FUNCTION "public"."_publicar_formula"("p_origen" "uuid", "p_nota" "text", "p_publicada_esperada" "uuid", "p_ignorar_retirados" boolean, "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_publicar_formula"("p_origen" "uuid", "p_nota" "text", "p_publicada_esperada" "uuid", "p_ignorar_retirados" boolean, "p_actualizado_en_esperado" timestamp with time zone) IS 'Interna: publica el borrador de un origen tras el candado, la publicada esperada y la actualizado_en esperada del borrador (nula: no compara). La usa formula_publicar. docs/COTIZADOR.md › «Versiones (4.20-1)».';



CREATE OR REPLACE FUNCTION "public"."_publicar_version"("p_origen" "uuid", "p_def" "jsonb", "p_params" "jsonb", "p_diseno" "jsonb", "p_nota" "text", "p_esperada" "uuid", "p_detalle" "jsonb", "p_ignorar_retirados" boolean) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_pub uuid; v_ver int; v_vis jsonb; v_id uuid; v_f text;
begin
  if coalesce(trim(p_nota), '') = '' then raise exception 'Publicar pide una nota.' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('formulas:' || p_origen::text, 0));
  select id into v_pub from public.formulas where origen_id = p_origen and estado = 'publicada';
  if v_pub is null then raise exception 'El origen no tiene fórmula publicada.' using errcode = '22023'; end if;
  if p_esperada is distinct from v_pub then
    v_f := public._version_publicada_por(v_pub);
    raise exception '%.', upper(left(v_f, 1)) || substr(v_f, 2) using errcode = 'PT409';
  end if;

  v_vis := public._preparar_publicacion(p_def, p_params, p_diseno, p_ignorar_retirados);

  select coalesce(max(version), 0) + 1 into v_ver from public.formulas where origen_id = p_origen;   -- formulas_origen_id_version_key
  update public.formulas set estado = 'archivada' where id = v_pub;
  insert into public.formulas (origen_id, version, estado, definicion, params, diseno, visibilidad, nota, version_origen_id, creado_por, publicado_por, publicado_en)
  values (p_origen, v_ver, 'publicada', p_def, p_params, p_diseno, v_vis, p_nota, v_pub, (select auth.uid()), (select auth.uid()), now())
  returning id into v_id;
  perform public.registrar_actividad('formula.publicada', 'formulas', v_id::text, jsonb_build_object('anterior', v_pub),
                                     jsonb_build_object('version', v_ver, 'nota', p_nota) || coalesce(p_detalle, '{}'::jsonb));
  return v_id;
end;
$$;


ALTER FUNCTION "public"."_publicar_version"("p_origen" "uuid", "p_def" "jsonb", "p_params" "jsonb", "p_diseno" "jsonb", "p_nota" "text", "p_esperada" "uuid", "p_detalle" "jsonb", "p_ignorar_retirados" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_publicar_version"("p_origen" "uuid", "p_def" "jsonb", "p_params" "jsonb", "p_diseno" "jsonb", "p_nota" "text", "p_esperada" "uuid", "p_detalle" "jsonb", "p_ignorar_retirados" boolean) IS 'Interna: publica la N+1 de un origen como fila nueva (archiva la publicada), sin leer ni escribir el borrador, tras el candado del origen y la esperada. La usan el ⚙ y formula_revertir. docs/COTIZADOR.md › «Versiones (4.20-1)».';



CREATE OR REPLACE FUNCTION "public"."_puede_mover"("p_flujo" "uuid", "p_de" "uuid", "p_a" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_origen uuid; v_ambito public.ambito_flujo; v_trans uuid; mis_roles uuid[];
begin
  select origen_id, ambito into v_origen, v_ambito from public.flujos where id = p_flujo;
  if v_ambito = 'vehiculos' then
    if not public.tiene_permiso('flujos.mover', v_origen) then return false; end if;
    if public.tiene_permiso('flujos.mover.cualquiera', v_origen) then return true; end if;
  else
    if not public.tiene_permiso('repuestos.mover') then return false; end if;
    if public.tiene_permiso('flujos.mover.cualquiera') then return true; end if;
  end if;
  select array_agg(rol_id) into mis_roles from public.usuarios_roles where usuario_id = (select auth.uid());
  if p_de is not null then
    select id into v_trans from public.fases_transiciones where de_fase_id = p_de and a_fase_id = p_a;
    if v_trans is not null and exists (select 1 from public.fases_transiciones_roles where transicion_id = v_trans) then
      return exists (select 1 from public.fases_transiciones_roles where transicion_id = v_trans and rol_id = any (mis_roles));
    end if;
  end if;
  if exists (select 1 from public.fases_roles where fase_id = p_a) then
    return exists (select 1 from public.fases_roles where fase_id = p_a and rol_id = any (mis_roles));
  end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."_puede_mover"("p_flujo" "uuid", "p_de" "uuid", "p_a" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_push_endpoint_valido"("p_endpoint" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  select coalesce(p_endpoint is not null and length(p_endpoint) <= 2048 and p_endpoint !~ '[\\[:space:][:cntrl:]]'
    and public._push_host_permitido(lower(substring(p_endpoint from '^https://([A-Za-z0-9.-]+)(?:[/?#]|$)'))), false);
$_$;


ALTER FUNCTION "public"."_push_endpoint_valido"("p_endpoint" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_push_endpoint_valido"("p_endpoint" "text") IS 'Push web (7.03): ¿el endpoint es https de un servicio de push? La usan push_suscribir y push_abrir; sin grant para nadie.';



CREATE OR REPLACE FUNCTION "public"."_push_host_permitido"("p_host" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select p_host is not null and (
    p_host in ('fcm.googleapis.com', 'android.googleapis.com', 'updates.push.services.mozilla.com', 'web.push.apple.com')
    or p_host like '%.push.services.mozilla.com'
    or p_host like '%.notify.windows.com'
    or p_host like '%.push.apple.com');
$$;


ALTER FUNCTION "public"."_push_host_permitido"("p_host" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_push_host_permitido"("p_host" "text") IS 'Push web (7.03): ¿el host es de un servicio de push? Iguales exactos y sufijos con punto. La usa _push_endpoint_valido; sin grant para nadie.';



