    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$ select 10 $$;


ALTER FUNCTION "public"."_push_tope_por_persona"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_push_tope_por_persona"() IS 'Push web (7.03): cuántas suscripciones guarda una persona; al pasarse se borra la menos reciente. Sin grant para nadie.';



CREATE OR REPLACE FUNCTION "public"."_recordatorio_conflicto"("p_cuando" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  raise exception 'Cambiaste este recordatorio % desde otra ventana. Recarga para seguir desde ahí.', public._hace(p_cuando)
    using errcode = 'PT409';
end;
$$;


ALTER FUNCTION "public"."_recordatorio_conflicto"("p_cuando" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_recordatorio_cuando"("p_valor" timestamp with time zone, "p_hint" "text") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
begin
  if p_valor is null then
    raise exception 'Elige cuándo recordarlo.' using errcode = '22023', hint = p_hint;
  end if;
  if p_valor <= now() then
    raise exception 'El recordatorio tiene que ser en el futuro.' using errcode = '22023', hint = p_hint;
  end if;
  if p_valor > now() + interval '5 years' then
    raise exception 'Elige una fecha dentro de los próximos 5 años.' using errcode = '22023', hint = p_hint;
  end if;
  return p_valor;
end;
$$;


ALTER FUNCTION "public"."_recordatorio_cuando"("p_valor" timestamp with time zone, "p_hint" "text") OWNER TO "postgres";


