    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('id', c.id, 'actualizado_en', c.actualizado_en, 'tipo_cambio_aplicado', c.tipo_cambio_aplicado, 'monto_base', c.monto_base)
         || p_extra;
