ALTER FUNCTION "public"."_repuesto_compra_respuesta"("c" "public"."repuestos_compras", "p_extra" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_repuesto_compra_tc_vigente"("p_moneda" "text") RETURNS "uuid"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select t.id
    from public.tipos_cambio t
    join public.ajustes_empresa e on e.id = 1
   where t.activo and t.es_default
     and ((t.moneda_de::text = p_moneda and t.moneda_a = e.moneda_base) or (t.moneda_de = e.moneda_base and t.moneda_a::text = p_moneda))
   order by (t.moneda_de::text = p_moneda) desc
   limit 1;
$$;


ALTER FUNCTION "public"."_repuesto_compra_tc_vigente"("p_moneda" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_repuesto_cotizacion_linea"("p_snapshot" "jsonb", "p_bloque" "text", "p_cantidad" integer, "p_costo" numeric, "p_logistica" numeric, "p_caja" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_sug numeric := public._repuesto_cotizacion_sugerida(p_snapshot, p_costo);
  v_l numeric := coalesce(p_logistica, v_sug);
  v_red numeric; v_x numeric; v_q numeric; v_u numeric; v_t numeric; v_falta text;
begin
  if p_bloque is distinct from 'importado' and p_bloque is distinct from 'local' then
    raise exception 'El bloque es «importado» o «local».' using errcode = '22023', hint = 'bloque';
  end if;
  if p_costo is null then
    v_falta := 'costo';
  elsif v_l is null then
    v_falta := 'logistica';
  elsif p_caja is null then
    v_falta := 'caja';
  else
    if p_bloque = 'importado' then
      v_x := p_costo * (p_snapshot #>> '{config,factor_importado}')::numeric + v_l + p_caja;
    else
      v_x := (p_costo + v_l + p_caja) * (1 + (p_snapshot #>> '{config,recargo_local}')::numeric);
    end if;
    -- Un redondeo ≤ 0 (filas viejas sin el check) vale 0,01.
    v_red := (p_snapshot #>> '{config,redondeo}')::numeric;
    if v_red is null or v_red <= 0 then
      v_red := 0.01;
    end if;
    v_q := div(v_x, v_red);
    if 2 * (v_x - v_q * v_red) >= v_red then
      v_q := v_q + 1;
    end if;
    v_u := v_q * v_red;
    v_t := v_u * p_cantidad;
    if v_t >= 1e16 then
      v_falta := 'no_cabe';
      v_u := null;
      v_t := null;
    end if;
  end if;
  return jsonb_build_object('logistica_sugerida', round(v_sug, 2)::text, 'unitario', round(v_u, 2)::text, 'total', round(v_t, 2)::text,
                            'falta', v_falta);
end;
$$;


ALTER FUNCTION "public"."_repuesto_cotizacion_linea"("p_snapshot" "jsonb", "p_bloque" "text", "p_cantidad" integer, "p_costo" numeric, "p_logistica" numeric, "p_caja" numeric) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."repuestos_cotizaciones_lineas" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "cotizacion_id" "uuid" NOT NULL,
    "item_id" "uuid",
    "descripcion" "text" NOT NULL,
    "tipo_pieza_id" "uuid",
    "condicion_id" "uuid",
    "bloque" "text" NOT NULL,
    "cantidad" integer DEFAULT 1 NOT NULL,
    "costo" numeric(18,2),
    "logistica_sugerida" numeric(18,2),
    "logistica" numeric(18,2),
    "caja_sugerida" numeric(18,2),
    "caja" numeric(18,2),
    "total" numeric(18,2),
    "orden" smallint DEFAULT 0 NOT NULL,
    CONSTRAINT "repuestos_cotizaciones_lineas_bloque_check" CHECK (("bloque" = ANY (ARRAY['importado'::"text", 'local'::"text"]))),
    CONSTRAINT "repuestos_cotizaciones_lineas_cantidad_check" CHECK (("cantidad" > 0))
);


ALTER TABLE "public"."repuestos_cotizaciones_lineas" OWNER TO "postgres";


COMMENT ON TABLE "public"."repuestos_cotizaciones_lineas" IS 'Líneas de una cotización de repuestos. Se escriben sólo por repuestos_cotizacion_guardar, que recalcula la logística sugerida y el total con el snapshot de su cotización.';



CREATE OR REPLACE FUNCTION "public"."_repuesto_cotizacion_linea_de"("p_linea" "jsonb", "p_cotizacion" "uuid", "p_orden" integer, "p_snapshot" "jsonb") RETURNS "public"."repuestos_cotizaciones_lineas"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare l public.repuestos_cotizaciones_lineas; k text; v_txt text; v_num numeric;
begin
  if p_linea is null or jsonb_typeof(p_linea) <> 'object' then
    raise exception 'cada línea va como un objeto.' using errcode = '22023', hint = 'lineas';
  end if;
  select x into k from jsonb_object_keys(p_linea) x
   where x <> all (array['id', 'item_id', 'descripcion', 'tipo_pieza_id', 'condicion_id', 'bloque', 'cantidad', 'costo', 'logistica', 'caja'])
   limit 1;
  if k is not null then
    raise exception 'no se escribe «%».', k using errcode = '22023', hint = k;
  end if;
  begin
    l.id := nullif(btrim(p_linea ->> 'id'), '')::uuid;
  exception when invalid_text_representation then
    raise exception 'el identificador de la línea no es válido.' using errcode = '22023', hint = 'id';
  end;
  begin
    l.item_id := nullif(btrim(p_linea ->> 'item_id'), '')::uuid;
  exception when invalid_text_representation then
    raise exception 'ese ítem no es de este proyecto.' using errcode = '22023', hint = 'item_id';
  end;
  if l.id is null then
    raise exception 'falta el identificador de la línea.' using errcode = '23502', hint = 'id';
  end if;
  l.cotizacion_id := p_cotizacion;
  l.orden := p_orden;

  l.descripcion := nullif(btrim(p_linea ->> 'descripcion'), '');
  if l.descripcion is null then
    raise exception 'falta la descripción.' using errcode = '23502', hint = 'descripcion';
  end if;
  if char_length(l.descripcion) > 200 then
    raise exception 'la descripción va en 200 caracteres como mucho.' using errcode = '22023', hint = 'descripcion';
  end if;
  l.tipo_pieza_id := public._repuesto_catalogo(p_linea, 'tipo_pieza_id', 'tipo_pieza');
  l.condicion_id := public._repuesto_catalogo(p_linea, 'condicion_id', 'condicion');

  l.bloque := nullif(btrim(p_linea ->> 'bloque'), '');
  if l.bloque is null then
    raise exception 'elige el bloque.' using errcode = '23502', hint = 'bloque';
  end if;
  if l.bloque not in ('importado', 'local') then
    raise exception 'el bloque es «importado» o «local».' using errcode = '22023', hint = 'bloque';
  end if;

  v_txt := nullif(btrim(p_linea ->> 'cantidad'), '');
  if v_txt is null then
    l.cantidad := 1;
  else
    begin
      v_num := v_txt::numeric;
    exception when invalid_text_representation then
      v_num := null;
    end;
    if v_num is null or v_num = 'NaN'::numeric or v_num <> trunc(v_num) or v_num < 1 or v_num > 100000 then
      raise exception 'la cantidad es un entero de 1 a 100000.' using errcode = '22023', hint = 'cantidad';
    end if;
    l.cantidad := v_num::integer;
  end if;

  l.costo := public._repuesto_cotizacion_monto(p_linea, 'costo');
  l.logistica := public._repuesto_cotizacion_monto(p_linea, 'logistica');
  l.caja := public._repuesto_cotizacion_monto(p_linea, 'caja');
  -- D1 · la caja es «sin caja» (0) o una de las del snapshot; la elegida queda como `caja_sugerida`.
  if l.caja is not null and l.caja <> 0
     and not exists (select 1 from jsonb_array_elements(coalesce(p_snapshot -> 'cajas', '[]'::jsonb)) b where (b ->> 'monto')::numeric = l.caja) then
    raise exception 'esa caja no está entre las de esta cotización.' using errcode = '22023', hint = 'caja';
  end if;
  l.caja_sugerida := l.caja;
  return l;
end;
$$;


ALTER FUNCTION "public"."_repuesto_cotizacion_linea_de"("p_linea" "jsonb", "p_cotizacion" "uuid", "p_orden" integer, "p_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_repuesto_cotizacion_monto"("p_linea" "jsonb", "p_clave" "text") RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v numeric;
begin
  begin
    v := nullif(btrim(p_linea ->> p_clave), '')::numeric;
  exception when invalid_text_representation then
    raise exception 'el % no es un número válido.', p_clave using errcode = '22023', hint = p_clave;
  end;
  if v is null then
    return null;
  end if;
  if v = 'NaN'::numeric or v < 0 then
    raise exception 'el % no puede ser negativo.', p_clave using errcode = '22023', hint = p_clave;
  end if;
  if v >= 1e16 then
    raise exception 'el % no cabe: revisa la cifra.', p_clave using errcode = '22023', hint = p_clave;
  end if;
  -- Antes de asignar: la columna numeric(18,2) redondearía en silencio.
  if v <> round(v, 2) then
    raise exception 'el % lleva como mucho dos decimales.', p_clave using errcode = '22023', hint = p_clave;
  end if;
  return v;
end;
$$;


ALTER FUNCTION "public"."_repuesto_cotizacion_monto"("p_linea" "jsonb", "p_clave" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."repuestos_cotizaciones" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "numero" bigint NOT NULL,
    "proyecto_id" "uuid" NOT NULL,
    "moneda" character(3) NOT NULL,
    "estado" "public"."estado_cotizacion_repuestos" DEFAULT 'borrador'::"public"."estado_cotizacion_repuestos" NOT NULL,
    "config_snapshot" "jsonb" NOT NULL,
    "total" numeric(18,2),
    "notas" "text",
    "creado_por" "uuid",
    "aceptada_en" timestamp with time zone,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."repuestos_cotizaciones" OWNER TO "postgres";


COMMENT ON TABLE "public"."repuestos_cotizaciones" IS 'Cotización de repuestos de un proyecto. Se escribe sólo por repuestos_cotizacion_crear, _guardar, _aceptar y _anular: el total y config_snapshot (la configuración congelada al crearla) los pone la base. Una sola aceptada por proyecto.';



CREATE OR REPLACE FUNCTION "public"."_repuesto_cotizacion_para_cambiar"("p_id" "uuid", "p_esperado" timestamp with time zone) RETURNS "public"."repuestos_cotizaciones"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare c public.repuestos_cotizaciones;
begin
  select * into c from public.repuestos_cotizaciones x where x.id = p_id for update;
  if not found then
    raise exception 'Esta cotización ya no existe.' using errcode = 'PT409', hint = 'conflicto';
  end if;
  perform public._repuesto_cotizacion_proyecto(c.proyecto_id);
  perform public._exigir_version(c.actualizado_en, p_esperado, 'Otra persona cambió esta cotización. Recarga para ver lo nuevo.');
  if c.estado <> 'borrador' then
    raise exception 'Una cotización aceptada o anulada no se edita.' using errcode = '23514', hint = 'estado';
  end if;
  if c.config_snapshot ->> 'version' is distinct from '1' then
    raise exception 'Esta cotización no tiene una configuración válida: anúlala y crea otra.' using errcode = '23514', hint = 'config_snapshot';
  end if;
  return c;
end;
$$;


ALTER FUNCTION "public"."_repuesto_cotizacion_para_cambiar"("p_id" "uuid", "p_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_repuesto_cotizacion_proyecto"("p_proyecto" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare p public.repuestos_proyectos;
begin
  select * into p from public.repuestos_proyectos x where x.id = p_proyecto for share;
  if not found or p.eliminado_en is not null then
    raise exception 'Este proyecto ya no existe.' using errcode = 'PT409', hint = 'conflicto';
  end if;
  if p.cerrado_en is not null then
    raise exception 'El proyecto está cerrado: reábrelo para cotizar.' using errcode = '23514', hint = 'proyecto';
  end if;
end;
$$;


ALTER FUNCTION "public"."_repuesto_cotizacion_proyecto"("p_proyecto" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_repuesto_cotizacion_respuesta"("c" "public"."repuestos_cotizaciones", "p_ya_existia" boolean) RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object('id', c.id, 'numero', c.numero, 'estado', c.estado, 'moneda', btrim(c.moneda), 'actualizado_en', c.actualizado_en,
                            'config_snapshot', c.config_snapshot, 'ya_existia', p_ya_existia);
$$;


ALTER FUNCTION "public"."_repuesto_cotizacion_respuesta"("c" "public"."repuestos_cotizaciones", "p_ya_existia" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_repuesto_cotizacion_sugerida"("p_snapshot" "jsonb", "p_costo" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select (t ->> 'monto')::numeric
    from jsonb_array_elements(coalesce(p_snapshot -> 'tramos', '[]'::jsonb)) t
   where p_costo is not null
     and (t ->> 'costo_min')::numeric <= p_costo
     and (t ->> 'costo_max' is null or p_costo < (t ->> 'costo_max')::numeric)
   order by (t ->> 'costo_min')::numeric
   limit 1;
$$;


ALTER FUNCTION "public"."_repuesto_cotizacion_sugerida"("p_snapshot" "jsonb", "p_costo" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_repuesto_fase_de_entrada"("p_item" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_iniciales uuid[]; f public.fases;
begin
  select array_agg(fa.id) into v_iniciales
  from public.fases fa join public.flujos fl on fl.id = fa.flujo_id
  where fl.ambito = 'repuestos' and fa.es_inicial and fa.activa;
  if coalesce(cardinality(v_iniciales), 0) <> 1 then return null; end if;
  select * into f from public.fases where id = v_iniciales[1];
  if f.nota_obligatoria then return null; end if;
  if exists (select 1 from public.evaluar_requisitos(null, p_item, f.id) e where e.bloqueante and not e.cumplido) then return null; end if;
  if exists (select 1 from public.fases_roles fr where fr.fase_id = f.id)
     and not exists (
       select 1 from public.fases_roles fr join public.usuarios_roles ur on ur.rol_id = fr.rol_id
       where fr.fase_id = f.id and ur.usuario_id = (select auth.uid())) then
    return null;
  end if;
  return f.id;
end;
$$;


ALTER FUNCTION "public"."_repuesto_fase_de_entrada"("p_item" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_repuesto_proyecto_tomar"("p_proyecto" "uuid", "p_esperado" timestamp with time zone) RETURNS "public"."repuestos_proyectos"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p public.repuestos_proyectos;
begin
  select * into p from public.repuestos_proyectos x where x.id = p_proyecto for update;
  if not found or p.eliminado_en is not null then
    raise exception 'Este proyecto ya no existe.' using errcode = 'PT409', hint = 'conflicto';
  end if;
  perform public._exigir_version(p.actualizado_en, p_esperado, 'Otra persona cambió este proyecto. Recarga para ver lo nuevo.');
  return p;
end;
$$;


