    "descripcion" "text" NOT NULL,
    "tipo_pieza_id" "uuid",
    "condicion_id" "uuid",
    "pais_origen_id" "uuid",
    "modo_transporte_id" "uuid",
    "cantidad" integer DEFAULT 1 NOT NULL,
    "precio_cliente" numeric(18,2),
    "moneda" character(3),
    "fase_id" "uuid",
    "fase_desde" timestamp with time zone,
    "tracking" "text",
    "en_stock_desde" timestamp with time zone,
    "stock_cantidad" integer DEFAULT 0 NOT NULL,
    "notas" "text",
    "creado_por" "uuid",
    "eliminado_en" timestamp with time zone,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "repuestos_items_cantidad_check" CHECK (("cantidad" > 0)),
    CONSTRAINT "repuestos_items_stock_cantidad_check" CHECK (("stock_cantidad" >= 0))
);


ALTER TABLE "public"."repuestos_items" OWNER TO "postgres";


COMMENT ON TABLE "public"."repuestos_items" IS 'ES EL ÍTEM el que recorre el flujo de repuestos (fase_id → fases del flujo ambito=repuestos). Ningún costo vive acá: precio_cliente es precio, los costos van en repuestos_compras (permiso aparte).';



CREATE OR REPLACE FUNCTION "public"."_repuesto_stock_aplicar"("p_item" "public"."repuestos_items", "p_con_signo" integer, "p_motivo" "text", "p_nota" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i public.repuestos_items; v_nuevo integer := p_item.stock_cantidad + p_con_signo; v_mov bigint;
begin
  update public.repuestos_items x
     set stock_cantidad = v_nuevo,
         en_stock_desde = case when v_nuevo > 0 then coalesce(x.en_stock_desde, now()) end
   where x.id = p_item.id
  returning * into i;
  insert into public.repuestos_stock_movimientos (item_id, cantidad, motivo, nota, usuario_id)
  values (i.id, p_con_signo, p_motivo, p_nota, (select auth.uid()))
  returning id into v_mov;
  return jsonb_build_object('item_id', i.id, 'stock_cantidad', i.stock_cantidad, 'en_stock_desde', i.en_stock_desde,
    'actualizado_en', i.actualizado_en, 'movimiento_id', v_mov);
end;
$$;


ALTER FUNCTION "public"."_repuesto_stock_aplicar"("p_item" "public"."repuestos_items", "p_con_signo" integer, "p_motivo" "text", "p_nota" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_repuesto_stock_item"("p_item" "uuid") RETURNS "public"."repuestos_items"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i public.repuestos_items;
begin
  select * into i from public.repuestos_items x where x.id = p_item for update;
  if not found or i.eliminado_en is not null
     or exists (select 1 from public.repuestos_proyectos pr where pr.id = i.proyecto_id and pr.eliminado_en is not null) then
    raise exception 'Este ítem ya no existe.' using errcode = 'PT409', hint = 'conflicto';
  end if;
  return i;
end;
$$;


ALTER FUNCTION "public"."_repuesto_stock_item"("p_item" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."fases_requisitos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "fase_id" "uuid" NOT NULL,
    "tipo" "public"."tipo_requisito" NOT NULL,
    "bloqueante" boolean DEFAULT false NOT NULL,
    "orden" smallint DEFAULT 0 NOT NULL,
    "notas" "text",
    "tipo_documento_id" "uuid",
    "min_archivos" integer,
    "max_archivos" integer,
    "formatos" "text"[],
    "clave_dato" "text",
    "config" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "espera_fase_id" "uuid",
    "espera_ambito" "public"."ambito_espera",
    CONSTRAINT "fases_requisitos_check" CHECK (((("tipo" = 'documento'::"public"."tipo_requisito") AND ("tipo_documento_id" IS NOT NULL) AND ("clave_dato" IS NULL) AND ("espera_fase_id" IS NULL)) OR (("tipo" = 'dato'::"public"."tipo_requisito") AND ("clave_dato" IS NOT NULL) AND ("tipo_documento_id" IS NULL) AND ("espera_fase_id" IS NULL)) OR (("tipo" = 'espera'::"public"."tipo_requisito") AND ("espera_fase_id" IS NOT NULL) AND ("espera_ambito" IS NOT NULL) AND ("tipo_documento_id" IS NULL) AND ("clave_dato" IS NULL)))),
    CONSTRAINT "fases_requisitos_check1" CHECK ((("max_archivos" IS NULL) OR ("min_archivos" IS NULL) OR ("max_archivos" >= "min_archivos"))),
    CONSTRAINT "fases_requisitos_max_archivos_check" CHECK ((("max_archivos" IS NULL) OR ("max_archivos" >= 1))),
    CONSTRAINT "fases_requisitos_min_archivos_check" CHECK ((("min_archivos" IS NULL) OR ("min_archivos" >= 1)))
);


ALTER TABLE "public"."fases_requisitos" OWNER TO "postgres";


COMMENT ON TABLE "public"."fases_requisitos" IS 'Qué pide una fase para ENTRAR. documento: N aprobados de un tipo; dato: una clave evaluada por código (vehiculo.vin, transporte.contenedor, aduana.tributos_pagados, pagos.umbral_pct…); espera: que el padre o los hijos hayan llegado a una fase de otro flujo. Se evalúa sólo al entrar.';



CREATE OR REPLACE FUNCTION "public"."_requisito_aplicar"("p_fila" "public"."fases_requisitos", "p_datos" "jsonb") RETURNS "public"."fases_requisitos"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_populate_record(p_fila, coalesce((
    select jsonb_object_agg(key, case
      when key = 'notas' then coalesce(to_jsonb(nullif(btrim(value #>> '{}'), '')), 'null'::jsonb)
      when key = 'config' and jsonb_typeof(value) = 'null' then '{}'::jsonb
      else value end)
    from jsonb_each(p_datos)), '{}'::jsonb));
$$;


ALTER FUNCTION "public"."_requisito_aplicar"("p_fila" "public"."fases_requisitos", "p_datos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_requisito_dato_cumplido"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_clave" "text", "p_config" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v public.vehiculos; t public.transportes; i public.repuestos_items; pct numeric;
begin
  if p_vehiculo is not null then select * into v from public.vehiculos where id = p_vehiculo; end if;
  if p_repuesto is not null then select * into i from public.repuestos_items where id = p_repuesto; end if;
  select * into t from public.transportes where vehiculo_id is not distinct from p_vehiculo and repuesto_id is not distinct from p_repuesto;
  if p_repuesto is not null and t.sigue_al_vehiculo then
    select tr.* into t from public.transportes tr join public.repuestos_proyectos pr on pr.id = i.proyecto_id where tr.vehiculo_id = pr.vehiculo_id;
  end if;
  case p_clave
    when 'vehiculo.vin' then return v.vin is not null;
    when 'vehiculo.lead' then return v.lead_id is not null;
    when 'vehiculo.cotizacion_final' then return exists (select 1 from public.cotizaciones c where c.vehiculo_id = p_vehiculo and c.clase = 'final' and c.estado = 'activa' and c.eliminado_en is null);
    when 'transporte.naviera' then return t.naviera_id is not null;
    when 'transporte.contenedor' then return coalesce(t.contenedor, '') <> '';
    when 'transporte.booking' then return coalesce(t.booking, '') <> '';
    when 'transporte.zarpe' then return t.zarpe_el is not null;
    when 'transporte.eta' then return t.eta_el is not null;
    when 'transporte.arribo' then return t.arribo_el is not null;
    when 'aduana.declaracion' then return exists (select 1 from public.declaraciones_vehiculos dv where dv.vehiculo_id = p_vehiculo and dv.removido_en is null);
    when 'aduana.canal' then return exists (select 1 from public.declaraciones_vehiculos dv join public.declaraciones_aduana d on d.id = dv.declaracion_id where dv.vehiculo_id = p_vehiculo and dv.removido_en is null and d.canal is not null);
    when 'aduana.tributos_pagados' then return exists (select 1 from public.gastos g join public.categorias_gasto cg on cg.id = g.categoria_id where g.vehiculo_id = p_vehiculo and g.eliminado_en is null and cg.proposito = 'tributos');
    when 'pagos.confirmado' then return exists (select 1 from public.pagos p where p.vehiculo_id = p_vehiculo and p.confirmado and p.eliminado_en is null);
    when 'pagos.umbral_pct' then
      pct := coalesce((p_config ->> 'pct')::numeric, 100);
      return coalesce((select sum(p.monto_base) from public.pagos p where p.vehiculo_id = p_vehiculo and p.confirmado and p.eliminado_en is null), 0)
             >= pct / 100 * coalesce((select c.total_base from public.cotizaciones c where c.vehiculo_id = p_vehiculo and c.clase = 'final' and c.estado = 'activa' and c.eliminado_en is null), 0)
             and exists (select 1 from public.cotizaciones c where c.vehiculo_id = p_vehiculo and c.clase = 'final' and c.estado = 'activa' and c.eliminado_en is null);
    when 'repuesto.tracking' then return coalesce(i.tracking, '') <> '';
    when 'repuesto.precio' then return i.precio_cliente is not null;
    when 'proyecto.pago_cliente' then return exists (select 1 from public.pagos p where p.proyecto_repuestos_id = i.proyecto_id and p.eliminado_en is null);
    else return false;
  end case;
end;
$$;


ALTER FUNCTION "public"."_requisito_dato_cumplido"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_clave" "text", "p_config" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_requisito_forma"("p_tipo" "public"."tipo_requisito", "p_datos" "jsonb", "p_crear" boolean) RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_permitidas text[];
  v_obligatoria text;
  v_clave text;
  v_tipo text;
  v_valor jsonb;
  v_bien boolean;
  v_uuid constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
begin
  if p_datos is null or jsonb_typeof(p_datos) <> 'object' then
    raise exception 'Faltan los datos del requisito.' using errcode = '22023';
  end if;
  if not p_crear and p_datos = '{}'::jsonb then
    raise exception 'No hay cambios para guardar.' using errcode = '22023';
  end if;

  if p_crear then
    v_permitidas := case p_tipo
      when 'documento' then array['tipo_documento_id', 'min_archivos', 'max_archivos', 'formatos', 'notas']
      when 'dato' then array['clave_dato', 'config', 'notas']
      else array['espera_fase_id', 'notas'] end;
    v_obligatoria := case p_tipo when 'documento' then 'tipo_documento_id' when 'dato' then 'clave_dato' else 'espera_fase_id' end;
  else
    v_permitidas := case p_tipo
      when 'documento' then array['min_archivos', 'max_archivos', 'formatos', 'notas', 'bloqueante']
      when 'dato' then array['config', 'notas', 'bloqueante']
      when 'espera' then array['notas', 'bloqueante']
      else array['min_archivos', 'max_archivos', 'formatos', 'config', 'notas', 'bloqueante'] end;
  end if;

  for v_clave, v_valor in select key, value from jsonb_each(p_datos) loop
    if not (v_clave = any (v_permitidas)) then
      raise exception 'El dato «%» no va en este requisito.', v_clave using errcode = '22023', hint = v_clave;
    end if;
    v_tipo := jsonb_typeof(v_valor);
    v_bien := case
      when v_clave in ('tipo_documento_id', 'espera_fase_id') then v_tipo = 'string' and (v_valor #>> '{}') ~ v_uuid
      when v_clave in ('min_archivos', 'max_archivos') then v_tipo = 'null'
        or (v_tipo = 'number' and (v_valor #>> '{}') ~ '^-?[0-9]+$' and (v_valor #>> '{}')::numeric between -2147483648 and 2147483647)
      when v_clave = 'formatos' then v_tipo = 'null'
        or (v_tipo = 'array' and jsonb_array_length(v_valor) > 0
            and not exists (select 1 from jsonb_array_elements(v_valor) e where jsonb_typeof(e) <> 'string'))
      when v_clave = 'config' then v_tipo = 'null'
        or (v_tipo = 'object' and (select array_agg(k) from jsonb_object_keys(v_valor) k) = array['pct'] and jsonb_typeof(v_valor -> 'pct') = 'number')
      when v_clave = 'clave_dato' then v_tipo = 'string'
      when v_clave = 'notas' then v_tipo in ('string', 'null')
      when v_clave = 'bloqueante' then v_tipo = 'boolean'
      else false end;
    if not v_bien then
      raise exception 'El dato «%» no tiene el formato esperado.', v_clave using errcode = '22023', hint = v_clave;
    end if;
  end loop;

  if p_crear and not p_datos ? v_obligatoria then
    raise exception 'Falta «%».', v_obligatoria using errcode = '22023', hint = v_obligatoria;
  end if;
end $_$;


ALTER FUNCTION "public"."_requisito_forma"("p_tipo" "public"."tipo_requisito", "p_datos" "jsonb", "p_crear" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_requisito_validar"("p_fila" "public"."fases_requisitos", "p_claves" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if 'notas' = any (p_claves) and char_length(p_fila.notas) > 500 then
    raise exception 'Las notas tienen hasta 500 caracteres.' using errcode = '22023', hint = 'notas';
  end if;
  if p_fila.min_archivos < 1 then
    raise exception 'Pide al menos 1 archivo.' using errcode = '22023', hint = 'min_archivos';
  end if;
  if p_fila.max_archivos < 1 then
    raise exception 'El máximo es de al menos 1 archivo.' using errcode = '22023', hint = 'max_archivos';
  end if;
  if p_fila.max_archivos < p_fila.min_archivos then
    raise exception 'El máximo de archivos no puede ser menor que el mínimo.' using errcode = '22023',
      hint = case when 'max_archivos' = any (p_claves) then 'max_archivos' else 'min_archivos' end;
  end if;
  if p_fila.config <> '{}'::jsonb and p_fila.clave_dato is distinct from 'pagos.umbral_pct' then
    raise exception 'Sólo «pagos.umbral_pct» lleva configuración.' using errcode = '22023', hint = 'config';
  end if;
end $$;


ALTER FUNCTION "public"."_requisito_validar"("p_fila" "public"."fases_requisitos", "p_claves" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_revision_etiquetas"("p_def" "jsonb", "p_filas" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  with d as (select f -> 'diff' as diff from jsonb_array_elements(coalesce(p_filas, '[]'::jsonb)) f),
  nodos as (
    select distinct k.key as id
      from d cross join lateral (values ('valores'), ('fuentes')) c (col) cross join lateral (values ('de'), ('a')) l (lado)
     cross join lateral jsonb_each(case when jsonb_typeof(d.diff -> c.col -> l.lado) = 'object' then d.diff -> c.col -> l.lado else '{}'::jsonb end) k
  ),
  grupos as (
    select distinct k.key as id
      from d cross join lateral (values ('de'), ('a')) l (lado)
     cross join lateral jsonb_each(case when jsonb_typeof(d.diff -> 'totales' -> l.lado -> 'grupos') = 'object' then d.diff -> 'totales' -> l.lado -> 'grupos' else '{}'::jsonb end) k
  )
  select jsonb_build_object(
    'nodos', coalesce((select jsonb_object_agg(n.id, coalesce((select x ->> 'etiqueta' from jsonb_array_elements(coalesce(p_def -> 'nodos', '[]'::jsonb)) x where x ->> 'id' = n.id limit 1), n.id))
                         from nodos n), '{}'::jsonb),
    'grupos', coalesce((select jsonb_object_agg(g.id, coalesce((select x ->> 'etiqueta' from jsonb_array_elements(coalesce(p_def -> 'grupos', '[]'::jsonb)) x where x ->> 'id' = g.id limit 1), g.id))
                          from grupos g), '{}'::jsonb));
$$;


ALTER FUNCTION "public"."_revision_etiquetas"("p_def" "jsonb", "p_filas" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_revision_etiquetas"("p_def" "jsonb", "p_filas" "jsonb") IS 'Las etiquetas de los nodos y los grupos que nombran los diffs de unas revisiones ya recortadas ({nodos: {id: etiqueta}, grupos: {id: etiqueta}}; sin etiqueta, el id). Pura y de nadie: la llama cotizacion_revisiones con la página que va a devolver.';



CREATE OR REPLACE FUNCTION "public"."_rol_para_editar"("p_rol" "uuid", "p_esperado" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_actual timestamptz;
begin
  if p_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  select actualizado_en into v_actual from public.roles where id = p_rol for update;
  if not found then raise exception 'Ese rol ya no existe.' using errcode = 'PT409'; end if;
  if v_actual is distinct from p_esperado then
    raise exception 'Otra persona cambió este rol mientras lo editabas.' using errcode = 'PT409';
  end if;
end;
$$;


ALTER FUNCTION "public"."_rol_para_editar"("p_rol" "uuid", "p_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_rol_tocar"("p_rol" "uuid") RETURNS timestamp with time zone
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  update public.roles set actualizado_en = now() where id = p_rol returning actualizado_en;
$$;


ALTER FUNCTION "public"."_rol_tocar"("p_rol" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_roles_de_lista"("p_roles" "uuid"[]) RETURNS "uuid"[]
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v uuid[];
begin
  if p_roles is null then
    raise exception 'Faltan los roles.' using errcode = '22023', hint = 'roles';
  end if;
  if array_position(p_roles, null) is not null then
    raise exception 'Hay un rol vacío en la lista.' using errcode = '22023', hint = 'roles';
  end if;
  v := array(select distinct r from unnest(p_roles) r order by r);
  if cardinality(v) > 100 then
    raise exception 'Elige hasta 100 roles.' using errcode = '22023', hint = 'roles';
  end if;
  perform 1 from public.roles where id = any (v) for key share;
  if exists (select 1 from unnest(v) r where not exists (select 1 from public.roles where id = r)) then
    raise exception 'Uno de los roles elegidos ya no existe. Recarga e intenta de nuevo.' using errcode = '22023', hint = 'roles';
  end if;
  return v;
end $$;


ALTER FUNCTION "public"."_roles_de_lista"("p_roles" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_roles_de_lista"("p_roles" "uuid"[]) IS 'Valida una lista de roles de quién mueve: nula, con un nulo, más de 100 o un rol inexistente → 22023 (hint roles). Toma los roles con for key share. Devuelve la lista sin repetidos y ordenada. Sólo para fase_roles_poner y transicion_roles_poner.';



CREATE OR REPLACE FUNCTION "public"."_seguimiento_conflicto"("p_cuando" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- Sólo su autor lo edita: el otro lado del conflicto es otra ventana suya.
  raise exception 'Cambiaste este seguimiento % desde otra ventana. Recarga para seguir desde ahí.', public._hace(p_cuando)
    using errcode = 'PT409';
end;
$$;


ALTER FUNCTION "public"."_seguimiento_conflicto"("p_cuando" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_seguimiento_detalle"("p_doc" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare v_texto text;
begin
  if p_doc is null or p_doc = 'null'::jsonb then
    return null;
  end if;
  if octet_length(p_doc::text) > 20000 then
    raise exception 'El detalle es demasiado largo.' using errcode = '22023', hint = 'detalle';
  end if;
  v_texto := btrim(public._seguimiento_nodo(p_doc, 'raiz', 0), E' \n\t');
  if btrim(coalesce((select string_agg(x #>> '{}', '') from jsonb_path_query(p_doc, 'strict $.**.text') x), ''),
           E' \n\t') = '' then
    return null;
  end if;
  if char_length(v_texto) > 5000 then
    raise exception 'El detalle admite hasta 5000 caracteres.' using errcode = '22023', hint = 'detalle';
  end if;
  return v_texto;
end;
$_$;


ALTER FUNCTION "public"."_seguimiento_detalle"("p_doc" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_seguimiento_fecha"("p_valor" "jsonb") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare v timestamptz;
begin
  if jsonb_typeof(p_valor) is distinct from 'string' then
    raise exception 'Elige cuándo fue.' using errcode = '22023', hint = 'ocurrido_en';
  end if;
  begin
    v := (p_valor #>> '{}')::timestamptz;
  exception when others then
    raise exception 'Elige cuándo fue.' using errcode = '22023', hint = 'ocurrido_en';
  end;
  if v > now() + interval '5 minutes' then
    raise exception 'Un seguimiento no puede ser en el futuro: para eso, agenda un recordatorio.'
      using errcode = '22023', hint = 'ocurrido_en';
  end if;
  if v < '2000-01-01'::timestamptz then
    raise exception 'Elige cuándo fue.' using errcode = '22023', hint = 'ocurrido_en';
  end if;
  return v;
end;
$$;


ALTER FUNCTION "public"."_seguimiento_fecha"("p_valor" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_seguimiento_href_valido"("p_href" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select p_href is not null
     and char_length(p_href) between 1 and 2000
     and p_href ~* '^(https?://|mailto:|tel:)'
     and p_href !~ '[[:space:][:cntrl:]]';
$$;


ALTER FUNCTION "public"."_seguimiento_href_valido"("p_href" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."seguimientos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "lead_id" "uuid" NOT NULL,
    "usuario_id" "uuid" NOT NULL,
    "tipo_id" "uuid" NOT NULL,
    "titulo" "text" NOT NULL,
    "detalle_doc" "jsonb",
    "detalle_texto" "text",
    "visibilidad" "public"."visibilidad_seguimiento" DEFAULT 'privado'::"public"."visibilidad_seguimiento" NOT NULL,
    "ocurrido_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "vehiculo_id" "uuid",
    "eliminado_en" timestamp with time zone,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "seguimientos_detalle_doc_objeto" CHECK ((("detalle_doc" IS NULL) OR ("jsonb_typeof"("detalle_doc") = 'object'::"text"))),
    CONSTRAINT "seguimientos_detalle_texto_largo" CHECK ((("detalle_texto" IS NULL) OR ("char_length"("detalle_texto") <= 5000))),
    CONSTRAINT "seguimientos_titulo_largo" CHECK ((("char_length"("titulo") >= 1) AND ("char_length"("titulo") <= 120)))
);


ALTER TABLE "public"."seguimientos" OWNER TO "postgres";


COMMENT ON TABLE "public"."seguimientos" IS 'Contactos con el lead. Se escriben sólo por RPC (crear_lead, seguimiento_*), y sólo su autor con el lead en su cartera. Nacen privados: privado = sólo lo ve su autor; público («Visible para el cliente») = lo ven también quienes ven el lead y el portal. El detalle viaja como documento del editor (detalle_doc), nunca como HTML; detalle_texto lo deriva la base. Un seguimiento no mueve la versión del lead.';



CREATE OR REPLACE FUNCTION "public"."_seguimiento_json"("s" "public"."seguimientos") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', s.id, 'lead_id', s.lead_id,
    'tipo_id', s.tipo_id, 'tipo_nombre', t.nombre, 'tipo_icono', t.icono,
    'titulo', s.titulo, 'detalle_doc', s.detalle_doc, 'detalle_texto', s.detalle_texto,
    'visibilidad', s.visibilidad, 'ocurrido_en', s.ocurrido_en, 'actualizado_en', s.actualizado_en,
    'eliminado', s.eliminado_en is not null,
    'autor_id', s.usuario_id, 'autor_nombre', nullif(btrim(p.nombre), ''),
    'es_mio', s.usuario_id = (select auth.uid()))
    || public._vehiculo_de_nota_json(s.vehiculo_id, s.usuario_id = (select auth.uid()))
  from public.tipos_seguimiento t, public.perfiles p
  where t.id = s.tipo_id and p.id = s.usuario_id;
$$;


ALTER FUNCTION "public"."_seguimiento_json"("s" "public"."seguimientos") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_seguimiento_marcas"("p_marcas" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare m jsonb; v_tipo text; v_vistas text[] := '{}';
begin
  if p_marcas is null then
    return;
  end if;
  if jsonb_typeof(p_marcas) <> 'array' then
    raise exception 'El detalle tiene un formato que no se admite.' using errcode = '22023', hint = 'detalle';
  end if;
  for m in select x from jsonb_array_elements(p_marcas) x loop
    if jsonb_typeof(m) <> 'object' or jsonb_typeof(m -> 'type') is distinct from 'string' then
      raise exception 'El detalle tiene un formato que no se admite.' using errcode = '22023', hint = 'detalle';
    end if;
    v_tipo := m ->> 'type';
    if v_tipo = any (v_vistas) then
      raise exception 'El detalle tiene un formato que no se admite.' using errcode = '22023', hint = 'detalle';
    end if;
    v_vistas := v_vistas || v_tipo;
    if v_tipo in ('bold', 'italic') then
      if exists (select 1 from jsonb_object_keys(m) k where k <> 'type') then
        raise exception 'El detalle tiene un formato que no se admite.' using errcode = '22023', hint = 'detalle';
      end if;
    elsif v_tipo = 'link' then
      if exists (select 1 from jsonb_object_keys(m) k where k not in ('type', 'attrs'))
         or jsonb_typeof(m -> 'attrs') is distinct from 'object'
         or exists (select 1 from jsonb_object_keys(m -> 'attrs') k where k <> 'href')
         or jsonb_typeof(m -> 'attrs' -> 'href') is distinct from 'string' then
        raise exception 'El detalle tiene un formato que no se admite.' using errcode = '22023', hint = 'detalle';
      end if;
      if not public._seguimiento_href_valido(m -> 'attrs' ->> 'href') then
        raise exception 'Ese enlace no se admite: usa una dirección http, https, mailto o tel.'
          using errcode = '22023', hint = 'detalle';
      end if;
    else
      raise exception 'El detalle tiene un formato que no se admite.' using errcode = '22023', hint = 'detalle';
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."_seguimiento_marcas"("p_marcas" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_seguimiento_mio"("p_id" "uuid") RETURNS "public"."seguimientos"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare s public.seguimientos;
begin
  perform public.assert_activo();
  select * into s from public.seguimientos x where x.id = p_id for update;
  if not found
     or s.usuario_id <> (select auth.uid())
     or not public.puede_actuar_lead(s.lead_id, 'leads.editar') then
    raise exception 'No encontramos este seguimiento o no tienes acceso.' using errcode = '42501';
  end if;
  perform 1 from public.leads x where x.id = s.lead_id for update;
  if not public.puede_actuar_lead(s.lead_id, 'leads.editar') then
    raise exception 'No encontramos este seguimiento o no tienes acceso.' using errcode = '42501';
  end if;
  return s;
end;
$$;


ALTER FUNCTION "public"."_seguimiento_mio"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_seguimiento_nodo"("p_nodo" "jsonb", "p_padre" "text", "p_profundidad" integer) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_tipo text;
  v_hijos jsonb;
  v_hijo jsonb;
  v_partes text[] := '{}';
  v_texto text;
  v_n int;
  v_inicio int;
  v_permitidas text[];
begin
  if p_profundidad > 6 then
    raise exception 'El detalle tiene demasiados niveles de lista.' using errcode = '22023', hint = 'detalle';
  end if;
  if jsonb_typeof(p_nodo) <> 'object' or jsonb_typeof(p_nodo -> 'type') is distinct from 'string' then
    raise exception 'El detalle tiene un formato que no se admite.' using errcode = '22023', hint = 'detalle';
  end if;
  v_tipo := p_nodo ->> 'type';
  if not (case p_padre
            when 'raiz' then v_tipo = 'doc'
            when 'doc' then v_tipo in ('paragraph', 'bulletList', 'orderedList')
            when 'listItem' then v_tipo in ('paragraph', 'bulletList', 'orderedList')
            when 'bulletList' then v_tipo = 'listItem'
            when 'orderedList' then v_tipo = 'listItem'
            when 'paragraph' then v_tipo in ('text', 'hardBreak')
            else false end) then
    raise exception 'El detalle tiene un formato que no se admite.' using errcode = '22023', hint = 'detalle';
  end if;

  v_permitidas := case v_tipo
    when 'text' then array['type', 'text', 'marks']
    when 'hardBreak' then array['type', 'marks']
    when 'orderedList' then array['type', 'content', 'attrs']
    else array['type', 'content'] end;
  if exists (select 1 from jsonb_object_keys(p_nodo) k where not (k = any (v_permitidas))) then
    raise exception 'El detalle tiene un formato que no se admite.' using errcode = '22023', hint = 'detalle';
  end if;

  if v_tipo = 'text' then
    if jsonb_typeof(p_nodo -> 'text') is distinct from 'string' or (p_nodo ->> 'text') = '' then
      raise exception 'El detalle tiene un formato que no se admite.' using errcode = '22023', hint = 'detalle';
    end if;
    perform public._seguimiento_marcas(p_nodo -> 'marks');
    return p_nodo ->> 'text';
  end if;
  if v_tipo = 'hardBreak' then
    perform public._seguimiento_marcas(p_nodo -> 'marks');
    return E'\n';
  end if;

  v_inicio := 1;
  if v_tipo = 'orderedList' and p_nodo ? 'attrs' then
    if jsonb_typeof(p_nodo -> 'attrs') <> 'object'
       or exists (select 1 from jsonb_object_keys(p_nodo -> 'attrs') k where k <> 'start')
       or jsonb_typeof(p_nodo -> 'attrs' -> 'start') is distinct from 'number'
       or (p_nodo -> 'attrs' ->> 'start') !~ '^[0-9]{1,5}$'
       or (p_nodo -> 'attrs' ->> 'start')::int < 1 then
      raise exception 'El detalle tiene un formato que no se admite.' using errcode = '22023', hint = 'detalle';
    end if;
    v_inicio := (p_nodo -> 'attrs' ->> 'start')::int;
  end if;

  v_hijos := p_nodo -> 'content';
  if v_hijos is null then
    if v_tipo in ('bulletList', 'orderedList', 'listItem') then
      raise exception 'El detalle tiene un formato que no se admite.' using errcode = '22023', hint = 'detalle';
    end if;
    return '';
  end if;
  if jsonb_typeof(v_hijos) <> 'array'
     or (v_tipo in ('bulletList', 'orderedList', 'listItem') and jsonb_array_length(v_hijos) = 0) then
    raise exception 'El detalle tiene un formato que no se admite.' using errcode = '22023', hint = 'detalle';
  end if;

  v_n := 0;
  for v_hijo in select x from jsonb_array_elements(v_hijos) x loop
    v_texto := public._seguimiento_nodo(v_hijo, v_tipo, p_profundidad + 1);
    if v_tipo = 'bulletList' then
      v_texto := '• ' || v_texto;
    elsif v_tipo = 'orderedList' then
      v_texto := (v_inicio + v_n)::text || '. ' || v_texto;
    end if;
    v_partes := v_partes || v_texto;
    v_n := v_n + 1;
  end loop;
  if v_tipo = 'paragraph' then
    return array_to_string(v_partes, '');
  end if;
  return array_to_string(v_partes, E'\n');
end;
$_$;


ALTER FUNCTION "public"."_seguimiento_nodo"("p_nodo" "jsonb", "p_padre" "text", "p_profundidad" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_seguimiento_titulo"("p_valor" "jsonb", "p_hint" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v text;
begin
  if jsonb_typeof(p_valor) is distinct from 'string' then
    raise exception 'Escribe un resumen del seguimiento.' using errcode = '22023', hint = p_hint;
  end if;
  v := btrim(p_valor #>> '{}');
  if v = '' then
    raise exception 'Escribe un resumen del seguimiento.' using errcode = '22023', hint = p_hint;
  end if;
  if char_length(v) > 120 then
    raise exception 'El resumen admite hasta 120 caracteres.' using errcode = '22023', hint = p_hint;
  end if;
  return v;
end;
$$;


