ALTER FUNCTION "public"."_tablero_conversion_desde"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_tablero_conversion_desde"() IS 'Día desde el que leads.cliente_desde se registra (9.07, D3): el de la migración tablero_cliente_desde en este entorno.';



CREATE OR REPLACE FUNCTION "public"."_tablero_ventana"("p_desde" "date", "p_hasta" "date") RETURNS TABLE("zona" "text", "ini" timestamp with time zone, "fin" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_zona text;
  v_sin_desde boolean := p_desde is null;
  v_sin_hasta boolean := p_hasta is null;
begin
  if v_sin_desde or v_sin_hasta then
    raise exception 'Elige el período.' using errcode = '22023', hint = case when v_sin_desde then 'p_desde' else 'p_hasta' end;
  end if;
  if p_hasta < p_desde then
    raise exception 'El período termina antes de empezar.' using errcode = '22023', hint = 'p_hasta';
  end if;
  if p_hasta - p_desde + 1 > 366 then
    raise exception 'El período puede tener hasta 366 días.' using errcode = '22023', hint = 'p_hasta';
  end if;
  select e.zona_horaria into v_zona from public.ajustes_empresa e where e.id = 1;
  v_zona := coalesce(v_zona, 'America/La_Paz');
  return query select v_zona, p_desde::timestamp at time zone v_zona, (p_hasta + 1)::timestamp at time zone v_zona;
end;
$$;


ALTER FUNCTION "public"."_tablero_ventana"("p_desde" "date", "p_hasta" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_tarjeta_grupos"("p_plantilla" "jsonb", "p_def" "jsonb", "p_tonos" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with dg as (
    select g ->> 'id' as id, g from jsonb_array_elements(coalesce(p_def -> 'grupos', '[]'::jsonb)) g
  ), filas as (
    select n ->> 'grupo' as grupo,
           jsonb_agg(jsonb_build_object(
             'nodo', n ->> 'id',
             'etiqueta', coalesce(p_plantilla -> 'etiquetas' ->> (n ->> 'id'), n ->> 'etiqueta'),
             -- La leyenda de la plantilla (vacía = sin leyenda) o la descripción del nodo.
             'leyenda', case when coalesce((p_plantilla -> 'leyendas') ? (n ->> 'id'), false) then nullif(p_plantilla -> 'leyendas' ->> (n ->> 'id'), '')
                             else n ->> 'descripcion' end) order by t.o) as filas
      from jsonb_array_elements(coalesce(p_def -> 'nodos', '[]'::jsonb)) with ordinality t (n, o)
     where n ->> 'grupo' is not null
     group by n ->> 'grupo'
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', pg.g ->> 'grupo',
           'etiqueta', dg.g ->> 'etiqueta',
           'plazo', dg.g -> 'plazo',
           -- El tono que elige la plantilla si sigue en el catálogo; si no, el del grupo.
           'tono', case when p_tonos ? (pg.g ->> 'tono') then pg.g ->> 'tono' when p_tonos ? (dg.g ->> 'tono') then dg.g ->> 'tono' end,
           'bucket', dg.g ->> 'bucket',
           'filas', coalesce(f.filas, '[]'::jsonb)) order by pg.o), '[]'::jsonb)
    from jsonb_array_elements(p_plantilla -> 'grupos') with ordinality pg (g, o)
    join dg on dg.id = pg.g ->> 'grupo'
    left join filas f on f.grupo = pg.g ->> 'grupo';
$$;


ALTER FUNCTION "public"."_tarjeta_grupos"("p_plantilla" "jsonb", "p_def" "jsonb", "p_tonos" "jsonb") OWNER TO "postgres";


