    SET "search_path" TO ''
    AS $$
  select nullif(rtrim(btrim(s.decrypted_secret), '/'), '') from vault.decrypted_secrets s where s.name = 'url_proyecto' limit 1
$$;


ALTER FUNCTION "public"."_url_del_proyecto"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_url_del_proyecto"() IS 'La URL del proyecto (secreto url_proyecto de Vault), sin la barra final, o null. La leen los jobs que llaman a una función edge.';



CREATE OR REPLACE FUNCTION "public"."_uuid_de"("p_valor" "jsonb", "p_hint" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if p_valor is null or p_valor = 'null'::jsonb then
    return null;
  end if;
  if jsonb_typeof(p_valor) <> 'string' then
    raise exception 'Ese dato no es válido.' using errcode = '22023', hint = p_hint;
  end if;
  return nullif(p_valor #>> '{}', '')::uuid;
exception when invalid_text_representation then
  raise exception 'Ese dato no es válido.' using errcode = '22023', hint = p_hint;
end;
$$;


ALTER FUNCTION "public"."_uuid_de"("p_valor" "jsonb", "p_hint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_valor_fuera_de_rango"("p_valor" "jsonb", "p_minimo" numeric, "p_maximo" numeric) RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(jsonb_typeof(p_valor) = 'number'
                  and ((p_minimo is not null and (p_valor #>> '{}')::numeric < p_minimo)
                       or (p_maximo is not null and (p_valor #>> '{}')::numeric > p_maximo)), false)
$$;


ALTER FUNCTION "public"."_valor_fuera_de_rango"("p_valor" "jsonb", "p_minimo" numeric, "p_maximo" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculo_a_lote"("v" "public"."vehiculos", "p_lote" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.vehiculos x
  set eliminado_en = now(), eliminado_por = (select auth.uid()), lote_papelera_id = p_lote, publicado_web = false, destacado_web = false
  where x.id = v.id;
  update public.cotizaciones c
  set eliminado_en = now(), eliminado_por = (select auth.uid()), lote_papelera_id = p_lote
  where c.vehiculo_id = v.id and c.eliminado_en is null;
  return jsonb_build_object('id', v.id, 'titulo', v.titulo, 'despublicado', v.publicado_web);
end;
$$;


ALTER FUNCTION "public"."_vehiculo_a_lote"("v" "public"."vehiculos", "p_lote" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculo_a_papelera"("p_vehiculo" "uuid", "p_esperado" timestamp with time zone, "p_lote" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v public.vehiculos; v_motivo text;
begin
  select * into v from public.vehiculos x where x.id = p_vehiculo and x.eliminado_en is null for update;
  if not found then
    raise exception 'Ya no existe o ya está en la papelera.' using errcode = 'PT409';
  end if;
  if not public.puede_vehiculo(v.id, 'vehiculos.eliminar') then
    raise exception 'No tienes permiso para enviarlo a la papelera.' using errcode = '42501';
  end if;
  if p_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  if v.actualizado_en is distinct from p_esperado then
    perform public._conflicto_de_edicion('vehiculos', v.id, v.actualizado_en, 'este vehículo');
  end if;
  v_motivo := public._vehiculo_motivo_de_bloqueo(v, true);
  if v_motivo is not null then
    raise exception '%', v_motivo using errcode = '23514';
  end if;
  return public._vehiculo_a_lote(v, p_lote);
end;
$$;


ALTER FUNCTION "public"."_vehiculo_a_papelera"("p_vehiculo" "uuid", "p_esperado" timestamp with time zone, "p_lote" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculo_apibara_valido"("p_raw" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
begin
  if jsonb_typeof(p_raw) <> 'object' then
    raise exception 'La respuesta de apibara no tiene la forma esperada.' using errcode = '22023';
  end if;
  if octet_length(p_raw::text) > 524288 then
    raise exception 'La respuesta de apibara es demasiado grande para guardarla.' using errcode = '22023';
  end if;
end;
$$;


ALTER FUNCTION "public"."_vehiculo_apibara_valido"("p_raw" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculo_aplicar"("v" "public"."vehiculos", "p_datos" "jsonb") RETURNS "public"."vehiculos"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_permitidas constant text[] := array['titulo', 'marca', 'modelo', 'anio', 'vin', 'lote', 'plataforma', 'url_origen', 'precio',
    'precio_negociable', 'acepta_permuta', 'placado', 'kilometraje', 'categoria_id', 'atributos'];
  k text; v_categoria uuid;
begin
  if p_datos is null or jsonb_typeof(p_datos) <> 'object' then
    raise exception 'Los datos del vehículo tienen que ser un objeto.' using errcode = '22023';
  end if;
  for k in select jsonb_object_keys(p_datos) loop
    if not (k = any (v_permitidas)) then
      raise exception 'El dato «%» no se escribe desde la ficha del vehículo.', k using errcode = '22023';
    end if;
  end loop;

  if p_datos ? 'titulo' then v.titulo := public._vehiculo_texto(p_datos, 'titulo', 'El título', 160); end if;
  if v.titulo is null then
    raise exception 'Falta el título.' using errcode = '23502', hint = 'titulo';
  end if;
  if p_datos ? 'marca' then v.marca := public._vehiculo_texto(p_datos, 'marca', 'La marca', 80); end if;
  if p_datos ? 'modelo' then v.modelo := public._vehiculo_texto(p_datos, 'modelo', 'El modelo', 80); end if;
  if p_datos ? 'lote' then v.lote := public._vehiculo_texto(p_datos, 'lote', 'El lote', 40); end if;
  if p_datos ? 'plataforma' then v.plataforma := lower(public._vehiculo_texto(p_datos, 'plataforma', 'La plataforma', 40)); end if;
  if p_datos ? 'url_origen' then
    v.url_origen := public._vehiculo_texto(p_datos, 'url_origen', 'El enlace', 500);
    if v.url_origen is not null and v.url_origen !~* '^https?://[^[:space:]]+$' then
      raise exception 'El enlace tiene que empezar con http:// o https://.' using errcode = '22023', hint = 'url_origen';
    end if;
  end if;
  if p_datos ? 'vin' then
    v.vin := upper(public._vehiculo_texto(p_datos, 'vin', 'El VIN', 17));
    if v.vin is not null and v.vin !~ '^[A-HJ-NPR-Z0-9]{11,17}$' then
      raise exception 'El VIN lleva entre 11 y 17 letras y números, sin I, O ni Q.' using errcode = '22023', hint = 'vin';
    end if;
  end if;
  if p_datos ? 'anio' then v.anio := public._vehiculo_numero(p_datos, 'anio', 'El año', 1900, 2100, true)::smallint; end if;
  if p_datos ? 'kilometraje' then v.kilometraje := public._vehiculo_numero(p_datos, 'kilometraje', 'El kilometraje', 0, 2000000000, true)::int; end if;
  if p_datos ? 'precio' then v.precio := round(public._vehiculo_numero(p_datos, 'precio', 'El precio', 0, 999999999999, false), 2); end if;
  if p_datos ? 'precio_negociable' then v.precio_negociable := public._vehiculo_si_no(p_datos, 'precio_negociable', 'El precio negociable'); end if;
  if p_datos ? 'acepta_permuta' then v.acepta_permuta := public._vehiculo_si_no(p_datos, 'acepta_permuta', 'Acepta permuta'); end if;
  if p_datos ? 'placado' then v.placado := public._vehiculo_si_no(p_datos, 'placado', 'Placado'); end if;

  if p_datos ? 'categoria_id' then
    if p_datos -> 'categoria_id' = 'null'::jsonb then
      v.categoria_id := null;
    else
      begin
        v_categoria := (p_datos ->> 'categoria_id')::uuid;
      exception when others then
        raise exception 'Esa categoría no existe.' using errcode = '22023', hint = 'categoria_id';
      end;
      if not exists (select 1 from public.categorias k2 where k2.id = v_categoria and k2.origen_id = v.origen_id) then
        raise exception 'Esa categoría no es de este origen.' using errcode = '22023', hint = 'categoria_id';
      end if;
      v.categoria_id := v_categoria;
    end if;
  end if;

  -- Atributos: la fusión y sus mensajes son del motor (`_atributos_fusionar`).
  if p_datos ? 'atributos' then
    v.atributos := public._atributos_fusionar(
      v.atributos, p_datos -> 'atributos',
      array(select c.clave from public.origenes_campos c where c.origen_id = v.origen_id and c.activo),
      'Los atributos de un vehículo tienen que ser un objeto.',
      'El campo «%s» no es de este origen o está desactivado.');
  end if;
  return v;
end;
$_$;


ALTER FUNCTION "public"."_vehiculo_aplicar"("v" "public"."vehiculos", "p_datos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculo_cotizado"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.vehiculo_id is not null and (tg_op = 'INSERT' or new.vehiculo_id is distinct from old.vehiculo_id) then
    update public.vehiculos set cotizado_en = now()
     where id = new.vehiculo_id and (cotizado_en is null or cotizado_en < now());
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."_vehiculo_cotizado"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculo_de_nota_json"("p_vehiculo" "uuid", "p_es_mio" boolean) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when p_vehiculo is null then jsonb_build_object('vehiculo', null, 'vehiculo_oculto', false)
    when public.puede_vehiculo(p_vehiculo, 'vehiculos.ver') then jsonb_build_object(
      'vehiculo', (select jsonb_build_object('id', v.id, 'titulo', v.titulo, 'numero', v.numero)
                     from public.vehiculos v where v.id = p_vehiculo),
      'vehiculo_oculto', false)
    else jsonb_build_object('vehiculo', null, 'vehiculo_oculto', coalesce(p_es_mio, false))
  end;
$$;


ALTER FUNCTION "public"."_vehiculo_de_nota_json"("p_vehiculo" "uuid", "p_es_mio" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculo_fase_de_entrada"("p_vehiculo" "uuid", "p_origen" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_iniciales uuid[]; f public.fases;
begin
  select array_agg(fa.id) into v_iniciales
  from public.fases fa join public.flujos fl on fl.id = fa.flujo_id
  where fl.origen_id = p_origen and fl.ambito = 'vehiculos' and fa.es_inicial and fa.activa;
  if coalesce(cardinality(v_iniciales), 0) <> 1 then return null; end if;
  select * into f from public.fases where id = v_iniciales[1];
  if f.nota_obligatoria then return null; end if;
  if exists (select 1 from public.evaluar_requisitos(p_vehiculo, null, f.id) e where e.bloqueante and not e.cumplido) then return null; end if;
  if exists (select 1 from public.fases_roles fr where fr.fase_id = f.id)
     and not exists (
       select 1 from public.fases_roles fr join public.usuarios_roles ur on ur.rol_id = fr.rol_id
       where fr.fase_id = f.id and ur.usuario_id = (select auth.uid())) then
    return null;
  end if;
  return f.id;
end;
$$;


ALTER FUNCTION "public"."_vehiculo_fase_de_entrada"("p_vehiculo" "uuid", "p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculo_motivo_de_bloqueo"("v" "public"."vehiculos", "p_al_enviar" boolean) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_fase public.fases;
begin
  if v.lead_id is not null then
    return 'Está vinculado a un lead. Quita el vínculo antes.';
  end if;
  if p_al_enviar and v.fase_id is not null then
    select * into v_fase from public.fases f where f.id = v.fase_id;
    if not v_fase.es_inicial then
      return format('Está en «%s». Sólo va a la papelera lo que sigue en su fase inicial.', v_fase.nombre);
    end if;
  end if;
  if exists (select 1 from public.comprobantes cp join public.cotizaciones c on c.id = cp.cotizacion_id where c.vehiculo_id = v.id) then
    return 'Tiene un comprobante emitido.';
  end if;
  -- Enviar a la papelera (y la limpieza, que pregunta con p_al_enviar) frena con documentos vivos: los cargó alguien y son de la logística. La purga
  -- de lo que ya está en la papelera no frena: junta sus rutas y las encola para limpiar (`_papelera_purgar_vehiculos`), como siempre.
  if p_al_enviar and exists (select 1 from public.documentos d where d.vehiculo_id = v.id and d.eliminado_en is null) then
    return 'Tiene documentos cargados.';
  end if;
  if exists (select 1 from public.pagos p where p.vehiculo_id = v.id) or exists (select 1 from public.gastos g where g.vehiculo_id = v.id) then
    return 'Tiene pagos o gastos registrados.';
  end if;
  if exists (select 1 from public.declaraciones_vehiculos d where d.vehiculo_id = v.id and d.removido_en is null) then
    return 'Está en una declaración aduanera.';
  end if;
  if exists (select 1 from public.repuestos_proyectos r where r.vehiculo_id = v.id and r.eliminado_en is null) then
    return 'Tiene un proyecto de repuestos.';
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."_vehiculo_motivo_de_bloqueo"("v" "public"."vehiculos", "p_al_enviar" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculo_numero"("p_datos" "jsonb", "p_clave" "text", "p_nombre" "text", "p_minimo" numeric, "p_maximo" numeric, "p_entero" boolean) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v jsonb := p_datos -> p_clave; n numeric;
begin
  if v is null or v = 'null'::jsonb then return null; end if;
  if jsonb_typeof(v) <> 'number' then
    raise exception '% tiene que ser un número.', p_nombre using errcode = '22023', hint = p_clave;
  end if;
  n := (v #>> '{}')::numeric;
  if (p_entero and n <> trunc(n)) or n < p_minimo or n > p_maximo then
    raise exception '% tiene que estar entre % y %.', p_nombre, p_minimo, p_maximo using errcode = '22023', hint = p_clave;
  end if;
  return n;
end;
$$;


ALTER FUNCTION "public"."_vehiculo_numero"("p_datos" "jsonb", "p_clave" "text", "p_nombre" "text", "p_minimo" numeric, "p_maximo" numeric, "p_entero" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_vehiculo_para_nota"("p_vehiculo" "uuid", "p_hint" "text" DEFAULT 'vehiculo_id'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_vehiculo is null then
    return null;
  end if;
  if not public.puede_vehiculo(p_vehiculo, 'vehiculos.ver') then
    raise exception 'Ese vehículo no existe o no tienes acceso.' using errcode = '42501', hint = p_hint;
  end if;
  return p_vehiculo;
end;
$$;


