COMMENT ON FUNCTION "public"."_vehiculos_inventario_validar"("p_filtros" "jsonb") IS 'Valida los filtros del inventario (Condicion[] de src/modules/vehiculos/entities/filtros.ts) con sus topes; cualquier falla, 22023 con hint filtros. Invocadora; la llama _vehiculos_inventario_sql().';



CREATE OR REPLACE FUNCTION "public"."_vehiculos_papelera_lote_json"("p_lote" "public"."lotes_papelera", "p_dias" integer, "p_yo" "uuid", "p_primeros" integer) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'id', p_lote.id, 'actualizado_en', p_lote.actualizado_en, 'creado_en', p_lote.creado_en,
    'creado_por_nombre', (select nullif(btrim(p.nombre), '') from public.perfiles p where p.id = p_lote.creado_por),
    'es_mio', p_lote.creado_por is not distinct from p_yo,
    'es_limpieza', p_lote.es_limpieza,
    'purga_el', p_lote.creado_en + make_interval(days => p_dias),
    'enviados', coalesce((p_lote.resumen ->> 'cantidad')::int, 0),
    -- Un lote tiene a lo sumo 200; las fotos de un vehículo, a lo sumo 24 (`vehiculo_imagenes_tope`).
    'vehiculos', (
      select jsonb_agg(jsonb_build_object(
        'id', v.id, 'numero', v.numero, 'titulo', v.titulo, 'origen_id', v.origen_id,
        'miniatura', (select i.ruta_miniatura from public.vehiculos_imagenes i where i.vehiculo_id = v.id and i.es_portada),
        'fotos', (select count(*) from public.vehiculos_imagenes i where i.vehiculo_id = v.id),
        'motivo_de_bloqueo', public._vehiculo_motivo_de_bloqueo(v, false)) order by v.numero)
      from public.vehiculos v
      where v.id = any (array(select v0.id from public.vehiculos v0
                                where v0.lote_papelera_id = p_lote.id and v0.eliminado_en is not null
                                order by v0.numero limit p_primeros))),
    -- Cuántos quedan en la papelera, exacto: un lote tiene a lo sumo 200 (contado sobre 201 para la guarda de escala).
    'en_papelera', (select count(*) from (select 1 from public.vehiculos v where v.lote_papelera_id = p_lote.id
                                           and v.eliminado_en is not null limit 201) c));
$$;


ALTER FUNCTION "public"."_vehiculos_papelera_lote_json"("p_lote" "public"."lotes_papelera", "p_dias" integer, "p_yo" "uuid", "p_primeros" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_version_publicada_por"("p_formula" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_f public.formulas; v_sujeto text;
begin
  select * into v_f from public.formulas f where f.id = p_formula;
  if v_f.id is null then return null; end if;
  if v_f.publicado_por is not null and v_f.publicado_por = (select auth.uid()) then
    v_sujeto := 'publicaste';
  else
    select nullif(btrim(p.nombre), '') || ' publicó' into v_sujeto from public.perfiles p where p.id = v_f.publicado_por;
    v_sujeto := coalesce(v_sujeto, 'otra persona publicó');
  end if;
  return v_sujeto || ' la versión ' || v_f.version || case when v_f.publicado_en is null then '' else ' ' || public._hace(v_f.publicado_en) end;
end;
$$;


ALTER FUNCTION "public"."_version_publicada_por"("p_formula" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_version_publicada_por"("p_formula" "uuid") IS 'Interna: la frase del PT409 de publicar, el ⚙ y revertir sobre una publicada (quién, qué versión y cuándo). docs/COTIZADOR.md › «Versiones (4.20-1)».';



CREATE OR REPLACE FUNCTION "public"."_web_ajustes_objeto"("p_clave" "text", "p_valor" "jsonb", "p_actual" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  k text;
  v jsonb;
  v_texto text;
  v_salida jsonb := '{}'::jsonb;
  v_ids uuid[] := '{}';
  v_id uuid;
  v_largo int;
begin
  if p_clave = 'origenes_visibles' then
    if jsonb_typeof(p_valor) is distinct from 'array' then
      raise exception 'El valor de «origenes_visibles» no es válido.' using errcode = '22023', hint = p_clave;
    end if;
    for v in select x from jsonb_array_elements(p_valor) x loop
      if jsonb_typeof(v) is distinct from 'string' or not pg_input_is_valid(v #>> '{}', 'uuid') then
        raise exception 'Ese origen no existe.' using errcode = '22023', hint = p_clave;
      end if;
      v_id := (v #>> '{}')::uuid;
      if not exists (select 1 from public.origenes o where o.id = v_id) then
        raise exception 'Ese origen no existe.' using errcode = '22023', hint = p_clave;
      end if;
      if not (v_id = any (v_ids)) then
        v_ids := v_ids || v_id;
      end if;
    end loop;
    return to_jsonb(v_ids);
  end if;

  if jsonb_typeof(p_valor) is distinct from 'object' then
    raise exception 'El valor de «%» no es válido.', p_clave using errcode = '22023', hint = p_clave;
  end if;

  if p_clave = 'legales' then
    v_salida := coalesce(p_actual, '{}'::jsonb);
    for k, v in select e.key, e.value from jsonb_each(p_valor) e loop
      if k not in ('terminos', 'privacidad') then
        raise exception 'Los legales admiten «terminos» y «privacidad».' using errcode = '22023', hint = p_clave;
      end if;
      if jsonb_typeof(v) = 'null' then
        v_salida := v_salida - k;
        continue;
      end if;
      if jsonb_typeof(v) is distinct from 'object'
         or exists (select 1 from jsonb_object_keys(v) c where c not in ('titulo', 'doc')) then
        raise exception 'Los legales tienen un formato que no se admite.' using errcode = '22023', hint = p_clave;
      end if;
      v_texto := case when jsonb_typeof(v -> 'titulo') = 'string' then btrim(v ->> 'titulo') end;
      if v_texto is null or char_length(v_texto) not between 1 and 120 then
        raise exception 'Escribe el título de «%».', k using errcode = '22023', hint = p_clave;
      end if;
      if jsonb_typeof(v -> 'doc') is distinct from 'object' then
        raise exception 'Escribe el texto de «%».', k using errcode = '22023', hint = p_clave;
      end if;
      if not coalesce(v_salida -> k ->> 'titulo' = v_texto and v_salida -> k -> 'doc' = v -> 'doc', false) then
        v_salida := v_salida || jsonb_build_object(k, jsonb_build_object('titulo', v_texto, 'doc', v -> 'doc'));
      end if;
    end loop;
    return v_salida;
  end if;

  -- redes y seo: se reemplazan enteros; un valor nulo o vacío omite la clave (D9).
  for k, v in select e.key, e.value from jsonb_each(p_valor) e loop
    if (p_clave = 'redes' and k not in ('facebook', 'instagram', 'tiktok', 'youtube', 'x', 'linkedin'))
       or (p_clave = 'seo' and k not in ('titulo', 'descripcion')) then
      raise exception '%', case p_clave when 'redes' then format('No se admite la red «%s».', k) else format('No se admite «%s» en SEO.', k) end
        using errcode = '22023', hint = p_clave;
    end if;
    if jsonb_typeof(v) = 'null' then
      continue;
    end if;
    if jsonb_typeof(v) is distinct from 'string' then
      raise exception 'El valor de «%» no es válido.', k using errcode = '22023', hint = p_clave;
    end if;
    v_texto := nullif(btrim(v #>> '{}'), '');
    continue when v_texto is null;
    if p_clave = 'redes' and (v_texto !~ '^https://[^[:space:]]+$' or char_length(v_texto) > 500) then
      raise exception 'La dirección de «%» empieza con https://.', k using errcode = '22023', hint = p_clave;
    end if;
    v_largo := case k when 'titulo' then 70 else 160 end;
    if p_clave = 'seo' and char_length(v_texto) > v_largo then
      raise exception '%', case k when 'titulo' then 'El título para buscadores lleva hasta 70 caracteres.'
        else 'La descripción para buscadores lleva hasta 160 caracteres.' end using errcode = '22023', hint = p_clave;
    end if;
    v_salida := v_salida || jsonb_build_object(k, v_texto);
  end loop;
  return v_salida;
end;
$_$;


ALTER FUNCTION "public"."_web_ajustes_objeto"("p_clave" "text", "p_valor" "jsonb", "p_actual" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_web_ajustes_valor"("p_clave" "text", "p_valor" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_tipo text := jsonb_typeof(p_valor);
  v_texto text;
  v_maximo int;
  v_min int;
  v_max int;
  v_rango text;
begin
  if p_clave in ('nombre_sitio', 'lema', 'horario', 'whatsapp_respaldo', 'direccion_publica') then
    if v_tipo = 'null' then
      return 'null'::jsonb;
    end if;
    if v_tipo is distinct from 'string' then
      raise exception 'El valor de «%» no es válido.', p_clave using errcode = '22023', hint = p_clave;
    end if;
    v_texto := nullif(btrim(p_valor #>> '{}'), '');
    if v_texto is null then
      return 'null'::jsonb;
    end if;
    v_maximo := case p_clave when 'nombre_sitio' then 80 when 'lema' then 160 when 'horario' then 200 else 500 end;
    if char_length(v_texto) > v_maximo then
      raise exception '%', case p_clave
        when 'nombre_sitio' then 'El nombre del sitio lleva hasta 80 caracteres.'
        when 'lema' then 'El lema lleva hasta 160 caracteres.'
        when 'horario' then 'El horario lleva hasta 200 caracteres.'
        when 'whatsapp_respaldo' then 'El WhatsApp va con el código de país, por ejemplo +59170000000.'
        else 'La dirección pública lleva hasta 500 caracteres.' end
        using errcode = '22023', hint = p_clave;
    end if;
    if p_clave = 'whatsapp_respaldo' and v_texto !~ '^\+[1-9][0-9]{6,14}$' then
      raise exception 'El WhatsApp va con el código de país, por ejemplo +59170000000.' using errcode = '22023', hint = p_clave;
    end if;
    if p_clave = 'direccion_publica' and v_texto !~ '^https://[^[:space:]]+$' then
      raise exception 'La dirección pública empieza con https://.' using errcode = '22023', hint = p_clave;
    end if;
    return to_jsonb(v_texto);
  end if;

  if p_clave in ('mostrar_moneda_secundaria', 'cola_activa') then
    if v_tipo is distinct from 'boolean' then
      raise exception 'El valor de «%» no es válido.', p_clave using errcode = '22023', hint = p_clave;
    end if;
    return p_valor;
  end if;

  if p_clave in ('ttl_contacto_minutos', 'dias_pegajoso', 'max_abiertas_default', 'max_intentos') then
    v_min := case p_clave when 'ttl_contacto_minutos' then 5 when 'dias_pegajoso' then 0 else 1 end;
    v_max := case p_clave when 'ttl_contacto_minutos' then 1440 when 'dias_pegajoso' then 365 when 'max_abiertas_default' then 50 else 10 end;
    v_rango := case p_clave
      when 'ttl_contacto_minutos' then 'El tiempo para contactar va de 5 a 1440 minutos.'
      when 'dias_pegajoso' then 'Los días con el mismo asesor van de 0 a 365.'
      when 'max_abiertas_default' then 'Las solicitudes abiertas por asesor van de 1 a 50.'
      else 'Los intentos van de 1 a 10.' end;
    if v_tipo is distinct from 'number' or (p_valor #>> '{}') !~ '^-?[0-9]{1,6}$'
       or (p_valor #>> '{}')::int not between v_min and v_max then
      raise exception '%', v_rango using errcode = '22023', hint = p_clave;
    end if;
    return to_jsonb((p_valor #>> '{}')::int);
  end if;

  raise exception 'No se cambia «%».', p_clave using errcode = '22023', hint = p_clave;
end;
$_$;


ALTER FUNCTION "public"."_web_ajustes_valor"("p_clave" "text", "p_valor" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_web_doc_html"("p_doc" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare v_html text;
begin
  if p_doc is null or p_doc = 'null'::jsonb then
    return '';
  end if;
  if octet_length(p_doc::text) > 102400 then
    raise exception 'El documento es demasiado largo.' using errcode = '22023', hint = 'doc';
  end if;
  v_html := public._web_doc_nodo(p_doc, 'raiz', 0);
  if btrim(coalesce((select string_agg(x #>> '{}', '') from jsonb_path_query(p_doc, 'strict $.**.text') x), ''), E' \n\t') = ''
     and not jsonb_path_exists(p_doc, 'lax $.content[*].type ? (@ == "image")') then
    return '';
  end if;
  return v_html;
end;
$_$;


ALTER FUNCTION "public"."_web_doc_html"("p_doc" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_web_doc_html"("p_doc" "jsonb") IS 'El HTML de un documento del sitio (guías, legales) validado contra la lista blanca; 22023 hint doc si no cabe. Espejo: web/entities/contenido/doc.ts. 8.01-1.';



CREATE OR REPLACE FUNCTION "public"."_web_doc_imagen"("p_nodo" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v_attrs jsonb := p_nodo -> 'attrs'; v_alt text := '';
begin
  if jsonb_typeof(v_attrs) is distinct from 'object'
     or exists (select 1 from jsonb_object_keys(v_attrs) k where k not in ('ruta', 'alt'))
     or jsonb_typeof(v_attrs -> 'ruta') is distinct from 'string' then
    raise exception 'El documento tiene un formato que no se admite.' using errcode = '22023', hint = 'doc';
  end if;
  if v_attrs ? 'alt' and jsonb_typeof(v_attrs -> 'alt') <> 'null' then
    if jsonb_typeof(v_attrs -> 'alt') <> 'string' or char_length(v_attrs ->> 'alt') > 300 then
      raise exception 'El documento tiene un formato que no se admite.' using errcode = '22023', hint = 'doc';
    end if;
    v_alt := v_attrs ->> 'alt';
  end if;
  if not public._web_doc_ruta_valida(v_attrs ->> 'ruta') then
    raise exception 'Esa imagen no se admite: súbela desde el editor.' using errcode = '22023', hint = 'doc';
  end if;
  return '<img data-ruta="' || public._web_html_escapar(v_attrs ->> 'ruta') || '" alt="' || public._web_html_escapar(v_alt) || '">';
end;
$$;


ALTER FUNCTION "public"."_web_doc_imagen"("p_nodo" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_web_doc_marcas"("p_marcas" "jsonb", "p_html" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  m jsonb;
  v_tipo text;
  v_vistas text[] := '{}';
  v_negrita boolean := false;
  v_cursiva boolean := false;
  v_href text;
  v_salida text := p_html;
begin
  if p_marcas is null then
    return v_salida;
  end if;
  if jsonb_typeof(p_marcas) <> 'array' then
    raise exception 'El documento tiene un formato que no se admite.' using errcode = '22023', hint = 'doc';
  end if;
  for m in select x from jsonb_array_elements(p_marcas) x loop
    if jsonb_typeof(m) <> 'object' or jsonb_typeof(m -> 'type') is distinct from 'string' then
      raise exception 'El documento tiene un formato que no se admite.' using errcode = '22023', hint = 'doc';
    end if;
    v_tipo := m ->> 'type';
    if v_tipo = any (v_vistas) then
      raise exception 'El documento tiene un formato que no se admite.' using errcode = '22023', hint = 'doc';
    end if;
    v_vistas := v_vistas || v_tipo;
    if v_tipo in ('bold', 'italic') then
      if exists (select 1 from jsonb_object_keys(m) k where k <> 'type') then
        raise exception 'El documento tiene un formato que no se admite.' using errcode = '22023', hint = 'doc';
      end if;
      if v_tipo = 'bold' then
        v_negrita := true;
      else
        v_cursiva := true;
      end if;
    elsif v_tipo = 'link' then
      if exists (select 1 from jsonb_object_keys(m) k where k not in ('type', 'attrs'))
         or jsonb_typeof(m -> 'attrs') is distinct from 'object'
         or exists (select 1 from jsonb_object_keys(m -> 'attrs') k where k <> 'href')
         or jsonb_typeof(m -> 'attrs' -> 'href') is distinct from 'string' then
        raise exception 'El documento tiene un formato que no se admite.' using errcode = '22023', hint = 'doc';
      end if;
      if not public._seguimiento_href_valido(m -> 'attrs' ->> 'href') then
        raise exception 'Ese enlace no se admite: usa una dirección http, https, mailto o tel.' using errcode = '22023', hint = 'doc';
      end if;
      v_href := m -> 'attrs' ->> 'href';
    else
      raise exception 'El documento tiene un formato que no se admite.' using errcode = '22023', hint = 'doc';
    end if;
  end loop;
  if v_negrita then
    v_salida := '<strong>' || v_salida || '</strong>';
  end if;
  if v_cursiva then
    v_salida := '<em>' || v_salida || '</em>';
  end if;
  if v_href is not null then
    v_salida := '<a href="' || public._web_html_escapar(v_href) || '" rel="noopener noreferrer nofollow">' || v_salida || '</a>';
  end if;
  return v_salida;
end;
$$;


ALTER FUNCTION "public"."_web_doc_marcas"("p_marcas" "jsonb", "p_html" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_web_doc_minutos"("p_doc" "jsonb") RETURNS smallint
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select case when t = '' then null
              else greatest(1, ceil(cardinality(regexp_split_to_array(t, '\s+')) / 200.0))::smallint end
    from (select btrim(coalesce((select string_agg(x #>> '{}', ' ')
                                   from jsonb_path_query(coalesce(p_doc, 'null'::jsonb), 'strict $.**.text') x), ''),
                       E' \n\t\r') as t) s;
$_$;


ALTER FUNCTION "public"."_web_doc_minutos"("p_doc" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_web_doc_nodo"("p_nodo" "jsonb", "p_padre" "text", "p_profundidad" integer) RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_tipo text;
  v_admitido boolean;
  v_permitidas text[];
  v_hijos jsonb;
  v_hijo jsonb;
  v_partes text[] := '{}';
  v_attrs jsonb;
  v_inicio int := 1;
  v_nivel text;
  v_interior text;
begin
  if p_profundidad > 6 then
    raise exception 'El documento tiene demasiados niveles.' using errcode = '22023', hint = 'doc';
  end if;
  if jsonb_typeof(p_nodo) <> 'object' or jsonb_typeof(p_nodo -> 'type') is distinct from 'string' then
    raise exception 'El documento tiene un formato que no se admite.' using errcode = '22023', hint = 'doc';
  end if;
  v_tipo := p_nodo ->> 'type';
  v_admitido := case p_padre
    when 'raiz' then v_tipo = 'doc'
    when 'doc' then v_tipo in ('paragraph', 'heading', 'bulletList', 'orderedList', 'blockquote', 'image')
    when 'blockquote' then v_tipo in ('paragraph', 'bulletList', 'orderedList')
    when 'listItem' then v_tipo in ('paragraph', 'bulletList', 'orderedList')
    when 'bulletList' then v_tipo = 'listItem'
    when 'orderedList' then v_tipo = 'listItem'
    when 'paragraph' then v_tipo in ('text', 'hardBreak')
    when 'heading' then v_tipo in ('text', 'hardBreak')
    else false end;
  if not v_admitido then
    raise exception 'El documento tiene un formato que no se admite.' using errcode = '22023', hint = 'doc';
  end if;

  v_permitidas := case v_tipo
    when 'text' then array['type', 'text', 'marks']
    when 'hardBreak' then array['type', 'marks']
    when 'orderedList' then array['type', 'content', 'attrs']
    when 'heading' then array['type', 'content', 'attrs']
    when 'image' then array['type', 'attrs']
    else array['type', 'content'] end;
  if exists (select 1 from jsonb_object_keys(p_nodo) k where not (k = any (v_permitidas))) then
    raise exception 'El documento tiene un formato que no se admite.' using errcode = '22023', hint = 'doc';
  end if;

  if v_tipo = 'text' then
    if jsonb_typeof(p_nodo -> 'text') is distinct from 'string' or (p_nodo ->> 'text') = '' then
      raise exception 'El documento tiene un formato que no se admite.' using errcode = '22023', hint = 'doc';
    end if;
    return public._web_doc_marcas(p_nodo -> 'marks', public._web_html_escapar(p_nodo ->> 'text'));
  end if;
  if v_tipo = 'hardBreak' then
    perform public._web_doc_marcas(p_nodo -> 'marks', '');
    return '<br>';
  end if;
  if v_tipo = 'image' then
    return public._web_doc_imagen(p_nodo);
  end if;

  if v_tipo = 'heading' then
    v_attrs := p_nodo -> 'attrs';
    if jsonb_typeof(v_attrs) is distinct from 'object'
       or exists (select 1 from jsonb_object_keys(v_attrs) k where k <> 'level')
       or jsonb_typeof(v_attrs -> 'level') is distinct from 'number'
       or (v_attrs ->> 'level') not in ('2', '3') then
      raise exception 'El documento tiene un formato que no se admite.' using errcode = '22023', hint = 'doc';
    end if;
    v_nivel := v_attrs ->> 'level';
  end if;
  if v_tipo = 'orderedList' and p_nodo ? 'attrs' then
    v_attrs := p_nodo -> 'attrs';
    if jsonb_typeof(v_attrs) <> 'object'
       or exists (select 1 from jsonb_object_keys(v_attrs) k where k <> 'start')
       or jsonb_typeof(v_attrs -> 'start') is distinct from 'number'
       or (v_attrs ->> 'start') !~ '^[0-9]{1,5}$'
       or (v_attrs ->> 'start')::int < 1 then
      raise exception 'El documento tiene un formato que no se admite.' using errcode = '22023', hint = 'doc';
    end if;
    v_inicio := (v_attrs ->> 'start')::int;
  end if;

  v_hijos := p_nodo -> 'content';
  if v_hijos is null then
    if v_tipo in ('bulletList', 'orderedList', 'listItem', 'blockquote') then
      raise exception 'El documento tiene un formato que no se admite.' using errcode = '22023', hint = 'doc';
    end if;
  else
    if jsonb_typeof(v_hijos) <> 'array'
       or (v_tipo in ('bulletList', 'orderedList', 'listItem', 'blockquote') and jsonb_array_length(v_hijos) = 0) then
      raise exception 'El documento tiene un formato que no se admite.' using errcode = '22023', hint = 'doc';
    end if;
    for v_hijo in select x from jsonb_array_elements(v_hijos) x loop
      v_partes := v_partes || public._web_doc_nodo(v_hijo, v_tipo, p_profundidad + 1);
    end loop;
  end if;
  v_interior := array_to_string(v_partes, '');

  return case v_tipo
    when 'doc' then v_interior
    when 'paragraph' then '<p>' || v_interior || '</p>'
    when 'heading' then '<h' || v_nivel || '>' || v_interior || '</h' || v_nivel || '>'
    when 'bulletList' then '<ul>' || v_interior || '</ul>'
    when 'orderedList' then (case when v_inicio = 1 then '<ol>' else '<ol start="' || v_inicio || '">' end) || v_interior || '</ol>'
    when 'listItem' then '<li>' || v_interior || '</li>'
    when 'blockquote' then '<blockquote>' || v_interior || '</blockquote>'
  end;
end;
$_$;


ALTER FUNCTION "public"."_web_doc_nodo"("p_nodo" "jsonb", "p_padre" "text", "p_profundidad" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_web_doc_ruta_valida"("p_ruta" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select p_ruta is not null
     and char_length(p_ruta) <= 300
     and p_ruta ~ '^[A-Za-z0-9_-]+(/[A-Za-z0-9_-]+)*\.(webp|png|jpe?g)$';
$_$;


ALTER FUNCTION "public"."_web_doc_ruta_valida"("p_ruta" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_web_html_escapar"("p_texto" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select replace(replace(replace(replace(replace(p_texto, '&', '&amp;'), '<', '&lt;'), '>', '&gt;'), '"', '&quot;'), '''', '&#39;');
$$;


ALTER FUNCTION "public"."_web_html_escapar"("p_texto" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_web_legales_validar"("p_legales" "jsonb", "p_anterior" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  k text;
  v jsonb;
  v_ant jsonb;
  v_titulo text;
  v_html text;
  v_salida jsonb := '{}'::jsonb;
begin
  if jsonb_typeof(p_legales) is distinct from 'object' then
    raise exception 'Los legales admiten «terminos» y «privacidad».' using errcode = '22023', hint = 'legales';
  end if;
  for k, v in select e.key, e.value from jsonb_each(p_legales) e loop
    if k not in ('terminos', 'privacidad') then
      raise exception 'Los legales admiten «terminos» y «privacidad».' using errcode = '22023', hint = 'legales';
    end if;
    if jsonb_typeof(v) is distinct from 'object'
       or exists (select 1 from jsonb_object_keys(v) c where c not in ('titulo', 'doc', 'html', 'actualizado_en')) then
      raise exception 'Los legales tienen un formato que no se admite.' using errcode = '22023', hint = 'legales';
    end if;
    v_titulo := case when jsonb_typeof(v -> 'titulo') = 'string' then btrim(v ->> 'titulo') end;
    if v_titulo is null or char_length(v_titulo) not between 1 and 120 then
      raise exception 'Escribe el título de «%».', k using errcode = '22023', hint = 'legales';
    end if;
    if jsonb_typeof(v -> 'doc') is distinct from 'object' then
      raise exception 'Escribe el texto de «%».', k using errcode = '22023', hint = 'legales';
    end if;
    if jsonb_path_exists(v -> 'doc', 'lax $.content[*] ? (@.type == "image")') then
      raise exception 'Los legales no llevan imágenes.' using errcode = '22023', hint = 'legales';
    end if;
    begin
      v_html := public._web_doc_html(v -> 'doc');
    exception when sqlstate '22023' then
      raise exception '%', sqlerrm using errcode = '22023', hint = 'legales';
    end;
    if v_html = '' then
      raise exception 'Escribe el texto de «%».', k using errcode = '22023', hint = 'legales';
    end if;
    v_ant := p_anterior -> k;
    v_salida := v_salida || jsonb_build_object(k, jsonb_build_object(
      'titulo', v_titulo, 'doc', v -> 'doc', 'html', v_html,
      'actualizado_en', case
        when v_ant ->> 'titulo' = v_titulo and v_ant -> 'doc' = v -> 'doc' and jsonb_typeof(v_ant -> 'actualizado_en') = 'string'
          then v_ant -> 'actualizado_en'
        else to_jsonb(now()) end));
  end loop;
  return v_salida;
end;
$_$;


ALTER FUNCTION "public"."_web_legales_validar"("p_legales" "jsonb", "p_anterior" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."_web_revalidar_anotar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  insert into interno.web_revalidar_pendiente (etiqueta)
  select tg_argv[0]
  where not exists (
    select 1 from interno.web_revalidar_pendiente q
    where q.etiqueta = tg_argv[0] and q.transaccion = pg_current_xact_id()
  );
  return null;
end $$;


ALTER FUNCTION "public"."_web_revalidar_anotar"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."_web_revalidar_anotar"() IS 'Trigger por sentencia: anota en la cola de revalidación la etiqueta que recibe como argumento, una vez por transacción.';



CREATE OR REPLACE FUNCTION "public"."actividad_diff"("p_id" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  a public.actividad;
  v jsonb;
  v_moneda boolean;
begin
  if not public.tiene_permiso('actividad.ver') then
    raise exception 'No tienes permiso para ver la actividad.' using errcode = '42501';
  end if;
  -- actividad_pkey
  select x.* into a from public.actividad x where x.id = p_id;
  if not found then
    return jsonb_build_object('id', p_id, 'visible', false);
  end if;
  v := public._actividad_recortar(a.tabla, a.registro_id, a.antes, a.despues);
  if not (v ->> 'visible')::boolean then
    return jsonb_build_object('id', p_id, 'visible', false);
  end if;
  -- La moneda sale con la misma regla de columnas que el recorte: fuera de leads y sólo si authenticated lee esa columna.
  v_moneda := a.tabla <> 'leads' and exists (
    select 1 from pg_catalog.pg_attribute x
     where x.attrelid = to_regclass('public.' || quote_ident(a.tabla)) and x.attname = 'moneda' and not x.attisdropped
       and has_column_privilege('authenticated', x.attrelid, x.attnum, 'select'));
  return jsonb_build_object(
    'id', a.id, 'accion', a.accion, 'tabla', a.tabla, 'registro_id', a.registro_id, 'actor_id', a.actor_id,
    'actor_nombre', (select nullif(btrim(p.nombre), '') from public.perfiles p where p.id = a.actor_id),
    'creado_en', a.creado_en, 'visible', true, 'cambios', v -> 'cambios',
    'moneda_antes', case when v_moneda then nullif(a.antes ->> 'moneda', '') end,
    'moneda_despues', case when v_moneda then nullif(a.despues ->> 'moneda', '') end,
    'origen_id', case when a.tabla = 'vehiculos' then coalesce(a.despues ->> 'origen_id', a.antes ->> 'origen_id') end);
end;
$$;


ALTER FUNCTION "public"."actividad_diff"("p_id" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."actividad_diff"("p_id" bigint) IS 'El diff de un cambio de la actividad, recortado (9.01-1). Pide actividad.ver (42501). {id, visible: false} si no existe o no se ve. Con visible: true suma moneda_antes y moneda_despues de la foto (fuera de leads y sólo si authenticated lee moneda) y origen_id de un vehículo (9.01-4).';



CREATE OR REPLACE FUNCTION "public"."actividad_listar"("p_antes_id" bigint DEFAULT NULL::bigint, "p_tamano" integer DEFAULT NULL::integer, "p_actor" "uuid" DEFAULT NULL::"uuid", "p_tabla" "text" DEFAULT NULL::"text", "p_registro" "text" DEFAULT NULL::"text", "p_hasta" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_accion" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_n int := public._acotar_pagina(p_tamano, 20, 100);
  v_antes bigint := p_antes_id;
  v_t timestamptz;
  v_filas public.actividad[];
  v_salida jsonb;
begin
  if not public.tiene_permiso('actividad.ver') then
    raise exception 'No tienes permiso para ver la actividad.' using errcode = '42501';
  end if;
  if p_registro is not null and p_tabla is null then
    raise exception 'Para filtrar por un registro hace falta su entidad.' using errcode = '22023', hint = 'registro';
  end if;
  if v_antes is null and p_hasta is not null then
    -- actividad_fecha_idx: la última fila antes de esa hora y, de las que comparten su hora (una transacción escribe varias con el mismo now()),
    -- la de id mayor, para no perder ninguna.
    select a.creado_en into v_t from public.actividad a where a.creado_en < p_hasta order by a.creado_en desc limit 1;
    if v_t is null then
      return jsonb_build_object('hay_mas', false, 'filas', '[]'::jsonb);
    end if;
    select a.id + 1 into v_antes from public.actividad a where a.creado_en = v_t order by a.id desc limit 1;
  end if;
  v_antes := coalesce(v_antes, 9223372036854775807);

  if p_registro is not null then
    -- actividad_registro_id_idx (tabla, registro_id, id desc)
    v_filas := array(
      select a from public.actividad a
       where a.tabla = p_tabla and a.registro_id = p_registro and a.id < v_antes
         and (p_actor is null or a.actor_id = p_actor) and (p_accion is null or a.accion = p_accion)
       order by a.id desc limit v_n + 1);
  elsif p_actor is not null then
    -- actividad_actor_id_idx (actor_id, id desc)
    v_filas := array(
      select a from public.actividad a
       where a.actor_id = p_actor and a.id < v_antes
         and (p_tabla is null or a.tabla = p_tabla) and (p_accion is null or a.accion = p_accion)
       order by a.id desc limit v_n + 1);
  elsif p_accion is not null then
    -- actividad_accion_id_idx (accion, id desc)
    v_filas := array(
      select a from public.actividad a
       where a.accion = p_accion and a.id < v_antes and (p_tabla is null or a.tabla = p_tabla)
       order by a.id desc limit v_n + 1);
  elsif p_tabla is not null then
    -- actividad_tabla_id_idx (tabla, id desc)
    v_filas := array(
      select a from public.actividad a
       where a.tabla = p_tabla and a.id < v_antes
       order by a.id desc limit v_n + 1);
  else
    -- actividad_pkey
    v_filas := array(
      select a from public.actividad a
       where a.id < v_antes
       order by a.id desc limit v_n + 1);
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', f.id, 'accion', f.accion, 'tabla', f.tabla, 'registro_id', f.registro_id, 'actor_id', f.actor_id,
           'actor_nombre', nullif(btrim(p.nombre), ''), 'creado_en', f.creado_en,
           'visible', r.visible,
           'campos', to_jsonb(coalesce(c.claves[1:5], '{}'::text[])),
           'mas_campos', coalesce(cardinality(c.claves), 0) > 5
         ) order by f.id desc), '[]'::jsonb)
    into v_salida
    from unnest(v_filas[1:v_n]) f
    left join public.perfiles p on p.id = f.actor_id
   cross join lateral (select public._actividad_recortar(f.tabla, f.registro_id, f.antes, f.despues) as v) x
   cross join lateral (select coalesce((x.v ->> 'visible')::boolean, false) as visible) r
   cross join lateral (
     select case when r.visible and f.accion like '%.update'
                 then array(select k from jsonb_object_keys(x.v -> 'cambios') k order by k limit 6)
                 else '{}'::text[] end as claves
   ) c;

  return jsonb_build_object('hay_mas', coalesce(cardinality(v_filas), 0) > v_n, 'filas', v_salida);
end;
$$;


ALTER FUNCTION "public"."actividad_listar"("p_antes_id" bigint, "p_tamano" integer, "p_actor" "uuid", "p_tabla" "text", "p_registro" "text", "p_hasta" timestamp with time zone, "p_accion" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."actividad_listar"("p_antes_id" bigint, "p_tamano" integer, "p_actor" "uuid", "p_tabla" "text", "p_registro" "text", "p_hasta" timestamp with time zone, "p_accion" "text") IS 'La página de /actividad (9.01-1): por cursor sobre id, una ruta por filtro con su índice, tamaño por _acotar_pagina (20, máx. 100), «Ir a una fecha» por actividad_fecha_idx. Pide actividad.ver (42501). Cada fila: cabecera, visible y hasta 5 campos que cambiaron; nunca un valor ni detalle.';



CREATE OR REPLACE FUNCTION "public"."actividad_purgar"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c_lote constant int := 10000;
  c_lotes constant int := 10;
  v_dias int;
  v_corte timestamptz;
  v_n int;
  v_actividad int := 0;
begin
  select e.actividad_dias into v_dias from public.ajustes_empresa e where e.id = 1;
  v_corte := now() - make_interval(days => coalesce(v_dias, 14));
  for i in 1 .. c_lotes loop
    -- actividad_fecha_idx
    delete from public.actividad
    where id = any (array(select x.id from public.actividad x where x.creado_en < v_corte limit c_lote));
    get diagnostics v_n = row_count;
    v_actividad := v_actividad + v_n;
    exit when v_n < c_lote;
  end loop;
  for i in 1 .. c_lotes loop
    -- eventos_web_fecha_idx
    delete from public.eventos_web
    where id = any (array(select x.id from public.eventos_web x where x.creado_en < now() - interval '12 months' limit c_lote));
    get diagnostics v_n = row_count;
    exit when v_n < c_lote;
  end loop;
  return v_actividad;
end;
$$;


ALTER FUNCTION "public"."actividad_purgar"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."actividad_purgar"() IS 'Purga diaria (9.01-1): la actividad de más de ajustes_empresa.actividad_dias y los eventos_web de más de 12 meses, por lotes de 10.000 y hasta 10 por tabla y corrida. Job actividad-purgar. notificaciones y visitados los purga notificaciones_purgar().';



CREATE OR REPLACE FUNCTION "public"."agenda_quienes_reciben"("p_texto" "text", "p_conversacion" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_texto text := left(btrim(coalesce(p_texto, '')), 100);
  v_tope constant int := 20;
  v_filas jsonb; v_hay boolean;
begin
  perform public.assert_activo();
  perform public.assert_permiso('agenda.tareas.asignar');
  if p_conversacion is not null and not public.es_miembro(p_conversacion) then
    raise exception 'No estás en esa conversación.' using errcode = '42501', hint = 'conversacion_id';
  end if;
  if not public._equipo_lista_indexable(v_texto) then
    return jsonb_build_object('personas', '[]'::jsonb, 'hay_mas', false);
  end if;
  -- `perfiles` es la tabla del equipo (decenas de filas, no crece): el patrón la recorre y el limit corta.
  select coalesce(jsonb_agg(jsonb_build_object('id', q.id, 'nombre', q.nombre) order by q.nombre, q.id), '[]'::jsonb), coalesce(count(*) > v_tope, false)
    into v_filas, v_hay
    from (select p.id, p.nombre from public.perfiles p
           where p.activo and not p.bloqueado
             and public._sin_tildes(p.nombre || ' ' || coalesce(p.email::text, '')) like public._equipo_busqueda_patron(v_texto)
             and (p_conversacion is null
                  or exists (select 1 from public.conversaciones_miembros m where m.conversacion_id = p_conversacion and m.usuario_id = p.id))
             and public._agenda_puede_recibir(p.id)
           order by p.nombre, p.id limit v_tope + 1) q;
  if v_hay then v_filas := v_filas - v_tope; end if;
  return jsonb_build_object('personas', v_filas, 'hay_mas', v_hay);
end $$;


ALTER FUNCTION "public"."agenda_quienes_reciben"("p_texto" "text", "p_conversacion" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."agenda_quienes_reciben"("p_texto" "text", "p_conversacion" "uuid") IS 'A quién puede darle una tarea quien pregunta: personas activas, sin bloqueo y con agenda.tareas.recibir cuyo nombre o email contiene p_texto (3 letras o dígitos seguidos; si no, lista vacía), y con p_conversacion sólo sus miembros (quien pregunta tiene que serlo: si no, 42501 hint conversacion_id). Pide agenda.tareas.asignar. {personas: [{id, nombre}], hay_mas}, 20 como mucho. 7.06-2.';



CREATE OR REPLACE FUNCTION "public"."agenda_rango"("p_desde" timestamp with time zone, "p_hasta" timestamp with time zone, "p_de_todos" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_tope constant int := 200;
  v_todos boolean := coalesce(p_de_todos, false);
  v_eventos jsonb; v_tareas jsonb; v_recordatorios jsonb; v_subastas jsonb;
  v_hay_e boolean; v_hay_t boolean; v_hay_r boolean; v_hay_s boolean;
begin
  perform public.assert_activo();
  if p_desde is null or p_hasta is null then
    raise exception 'Elige el rango de fechas.' using errcode = '22023', hint = 'rango';
  end if;
  if p_hasta <= p_desde then
    raise exception 'El rango termina antes de empezar.' using errcode = '22023', hint = 'rango';
  end if;
  if p_hasta - p_desde > interval '45 days' then
    raise exception 'El rango puede abarcar hasta 45 días.' using errcode = '22023', hint = 'rango';
  end if;
  if v_todos then
    perform public.assert_permiso('agenda.ver_todo');
  end if;

  -- Eventos por eventos_inicio_idx (inicia_en), bajo `eventos: leer`.
  if v_todos then
    select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'titulo', e.titulo, 'inicia_en', e.inicia_en, 'termina_en', e.termina_en,
                                                 'visibilidad', e.visibilidad, 'estado', e.estado, 'mio', e.creado_por = v_yo)
                              order by e.inicia_en, e.id), '[]'::jsonb),
           coalesce(count(*) > v_tope, false)
      into v_eventos, v_hay_e
      from (select x.id, x.titulo, x.inicia_en, x.termina_en, x.visibilidad, x.estado, x.creado_por from public.eventos x
             where x.eliminado_en is null and x.inicia_en >= p_desde and x.inicia_en < p_hasta
             order by x.inicia_en, x.id limit v_tope + 1) e;
  else
    select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'titulo', e.titulo, 'inicia_en', e.inicia_en, 'termina_en', e.termina_en,
                                                 'visibilidad', e.visibilidad, 'estado', e.estado, 'mio', e.creado_por = v_yo)
                              order by e.inicia_en, e.id), '[]'::jsonb),
           coalesce(count(*) > v_tope, false)
      into v_eventos, v_hay_e
      from (select x.id, x.titulo, x.inicia_en, x.termina_en, x.visibilidad, x.estado, x.creado_por from public.eventos x
             where x.eliminado_en is null and x.inicia_en >= p_desde and x.inicia_en < p_hasta
               and (x.creado_por = v_yo or x.visibilidad = 'publico' or public._agenda_soy_destinatario(x.id))
             order by x.inicia_en, x.id limit v_tope + 1) e;
  end if;

  -- Tareas: las mías por tareas_responsable_idx (responsable_id, vence_en); las de todos por tareas_vence_idx (vence_en, id). Bajo `tareas: leer`.
  if v_todos then
    select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'titulo', t.titulo, 'vence_en', t.vence_en, 'estado', t.estado,
                                                 'responsable_id', t.responsable_id, 'mia', t.creado_por = v_yo)
                              order by t.vence_en, t.id), '[]'::jsonb),
           coalesce(count(*) > v_tope, false)
      into v_tareas, v_hay_t
      from (select x.id, x.titulo, x.vence_en, x.estado, x.responsable_id, x.creado_por from public.tareas x
             where x.eliminado_en is null and x.vence_en >= p_desde and x.vence_en < p_hasta
             order by x.vence_en, x.id limit v_tope + 1) t;
  else
    select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'titulo', t.titulo, 'vence_en', t.vence_en, 'estado', t.estado,
                                                 'responsable_id', t.responsable_id, 'mia', t.creado_por = v_yo)
                              order by t.vence_en, t.id), '[]'::jsonb),
           coalesce(count(*) > v_tope, false)
      into v_tareas, v_hay_t
      from (select x.id, x.titulo, x.vence_en, x.estado, x.responsable_id, x.creado_por from public.tareas x
             where x.responsable_id = v_yo and x.eliminado_en is null and x.vence_en >= p_desde and x.vence_en < p_hasta
             order by x.vence_en, x.id limit v_tope + 1) t;
  end if;

  -- Recordatorios propios y pendientes por recordatorios_usuario_idx (usuario_id, recordar_en). Sin lead: el panel lo lee si se ve.
  select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'titulo', r.titulo, 'recordar_en', r.recordar_en) order by r.recordar_en, r.id), '[]'::jsonb),
         coalesce(count(*) > v_tope, false)
    into v_recordatorios, v_hay_r
    from (select x.id, x.titulo, x.recordar_en from public.recordatorios x
           where x.usuario_id = v_yo and x.completado_en is null and x.eliminado_en is null and x.recordar_en >= p_desde and x.recordar_en < p_hasta
           order by x.recordar_en, x.id limit v_tope + 1) r;

  -- Subastas vivas por vehiculos_cierre_subasta_idx (origen_id, cierre_subasta_en, id): origen por origen de los que tienen vehiculos.ver, cada uno
  -- con su limit; afuera el orden junta a lo sumo orígenes × 201. La RLS de vehículos descarta adentro lo que no se ve (en un origen «propios»,
  -- los ajenos: acotado a las subastas vivas del origen en el rango).
  select coalesce(jsonb_agg(jsonb_build_object('vehiculo_id', s.id, 'titulo', s.titulo, 'cierre_subasta_en', s.cierre_subasta_en,
                                               'estado_subasta', s.estado_subasta, 'origen_id', s.origen_id)
                            order by s.cierre_subasta_en, s.id), '[]'::jsonb),
         coalesce(count(*) > v_tope, false)
    into v_subastas, v_hay_s
    from (select v.id, v.titulo, v.cierre_subasta_en, v.estado_subasta, v.origen_id
            from unnest(public.origenes_con_alcance('vehiculos.ver', 'propios')) o(id)
            cross join lateral (
              select y.id, y.titulo, y.cierre_subasta_en, y.estado_subasta, y.origen_id from public.vehiculos y
               where y.origen_id = o.id and y.eliminado_en is null and y.cierre_subasta_en >= p_desde and y.cierre_subasta_en < p_hasta
               order by y.cierre_subasta_en, y.id limit v_tope + 1) v
           order by v.cierre_subasta_en, v.id limit v_tope + 1) s;

  -- La de más no viaja: es sólo el aviso de que hay más.
  if v_hay_e then v_eventos := v_eventos - v_tope; end if;
  if v_hay_t then v_tareas := v_tareas - v_tope; end if;
  if v_hay_r then v_recordatorios := v_recordatorios - v_tope; end if;
  if v_hay_s then v_subastas := v_subastas - v_tope; end if;
  return jsonb_build_object('eventos', v_eventos, 'tareas', v_tareas, 'recordatorios', v_recordatorios, 'subastas', v_subastas,
                            'hay_mas', jsonb_build_object('eventos', v_hay_e, 'tareas', v_hay_t, 'recordatorios', v_hay_r, 'subastas', v_hay_s),
                            'tope', v_tope);
end $$;


ALTER FUNCTION "public"."agenda_rango"("p_desde" timestamp with time zone, "p_hasta" timestamp with time zone, "p_de_todos" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."agenda_rango"("p_desde" timestamp with time zone, "p_hasta" timestamp with time zone, "p_de_todos" boolean) IS 'La agenda en [p_desde, p_hasta) (hasta 45 días; si no, 22023 hint rango): eventos, tareas, recordatorios y subastas, sólo lo que dibuja un chip, 200 por clase como mucho. De invocador: la RLS de cada tabla decide. Sin p_de_todos, «mi agenda»; con él (exige agenda.ver_todo, si no 42501) todos los eventos y tareas. {eventos, tareas, recordatorios, subastas, hay_mas: {…}, tope}. 7.06-2.';



CREATE OR REPLACE FUNCTION "public"."agenda_tareas_sin_fecha"("p_tamano" integer DEFAULT NULL::integer, "p_antes_en" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_antes_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_n int := public._acotar_pagina(p_tamano, 20, 50);
  v_filas jsonb; v_hay boolean;
begin
  perform public.assert_activo();
  if (p_antes_en is null) <> (p_antes_id is null) then
    raise exception 'El cursor de la página está incompleto.' using errcode = '22023', hint = 'cursor';
  end if;
  -- Las dos por tareas_sin_fecha_idx (responsable_id, creado_en desc, id desc).
  if p_antes_en is null then
    select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'titulo', t.titulo, 'estado', t.estado, 'creado_en', t.creado_en, 'mia', t.creado_por = v_yo)
                              order by t.creado_en desc, t.id desc), '[]'::jsonb),
           coalesce(count(*) > v_n, false)
      into v_filas, v_hay
      from (select x.id, x.titulo, x.estado, x.creado_en, x.creado_por from public.tareas x
             where x.responsable_id = v_yo and x.eliminado_en is null and x.vence_en is null and x.estado <> 'cancelado'
             order by x.creado_en desc, x.id desc limit v_n + 1) t;
  else
    select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'titulo', t.titulo, 'estado', t.estado, 'creado_en', t.creado_en, 'mia', t.creado_por = v_yo)
                              order by t.creado_en desc, t.id desc), '[]'::jsonb),
           coalesce(count(*) > v_n, false)
      into v_filas, v_hay
      from (select x.id, x.titulo, x.estado, x.creado_en, x.creado_por from public.tareas x
             where x.responsable_id = v_yo and x.eliminado_en is null and x.vence_en is null and x.estado <> 'cancelado'
               and (x.creado_en, x.id) < (p_antes_en, p_antes_id)
             order by x.creado_en desc, x.id desc limit v_n + 1) t;
  end if;
  -- La de más no viaja: es sólo el aviso de que hay otra página.
  if v_hay then v_filas := v_filas - v_n; end if;
  return jsonb_build_object('tareas', v_filas, 'hay_mas', v_hay);
end $$;


ALTER FUNCTION "public"."agenda_tareas_sin_fecha"("p_tamano" integer, "p_antes_en" timestamp with time zone, "p_antes_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."agenda_tareas_sin_fecha"("p_tamano" integer, "p_antes_en" timestamp with time zone, "p_antes_id" "uuid") IS 'Una página de mis tareas (responsable) vivas, sin fecha y no canceladas, la más nueva primero (p_tamano: 20 por defecto, 50 como mucho). El cursor es (creado_en, id) de la última de la página anterior; a medias, 22023 hint cursor. De invocador. {tareas, hay_mas}. 7.06-2.';



CREATE OR REPLACE FUNCTION "public"."agenda_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  new.actualizado_en := greatest(clock_timestamp(), old.actualizado_en + interval '1 microsecond');
  return new;
end;
$$;


