COMMENT ON FUNCTION "public"."alertas_cerrar_al_mover"() IS 'Alertas (6.12): after insert en historial_fases de un vehículo; acciona los avisos demora_fase abiertos de esa unidad, de todos sus destinatarios.';



CREATE OR REPLACE FUNCTION "public"."alertas_demora"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c_lote constant int := 200;
  c_tope constant int := 2000;
  p record; w record;
  v_origen uuid; v_usuarios uuid[]; v_todos boolean[];
  v_ids uuid[]; v_desde timestamptz; v_id uuid;
  v_vistas int := 0; v_n int := 0;
  -- Quien está en una baja en curso deja de contar su cartera (la unidad propia, sí).
  v_fuera constant uuid[] := public._bajas_en_curso();
begin
  for p in
    select fl.origen_id, f.id as fase_id, f.nombre, x.dias, coalesce(f.alerta_cada_horas, 72) as horas
      from public.flujos fl
      join public.fases f on f.flujo_id = fl.id
      cross join lateral (select public._logistica_dias(f.id) as dias) x
     where fl.ambito = 'vehiculos' and fl.origen_id is not null and x.dias is not null
     order by fl.origen_id, f.orden, f.id
  loop
    exit when v_vistas >= c_tope;
    if v_origen is distinct from p.origen_id then
      v_origen := p.origen_id;
      select coalesce(array_agg(d.usuario_id order by d.usuario_id), '{}'), coalesce(array_agg(d.todos order by d.usuario_id), '{}')
        into v_usuarios, v_todos from public._alertas_destinatarios('flujos.mover', p.origen_id) d;
    end if;
    continue when cardinality(v_usuarios) = 0;
    v_id := null;
    loop
      -- vehiculos_cadena_idx: (origen_id, fase_id) fijos, rango de fase_desde; con cursor, desde (fase_desde, id).
      if v_id is null then
        v_ids := array(select v.id from public.vehiculos v
                        where v.origen_id = p.origen_id and v.fase_id = p.fase_id and v.eliminado_en is null
                          and v.fase_desde < now() - make_interval(days => p.dias)
                        order by v.fase_desde, v.id limit least(c_lote, c_tope - v_vistas));
      else
        v_ids := array(select v.id from public.vehiculos v
                        where v.origen_id = p.origen_id and v.fase_id = p.fase_id and v.eliminado_en is null
                          and v.fase_desde < now() - make_interval(days => p.dias) and (v.fase_desde, v.id) > (v_desde, v_id)
                        order by v.fase_desde, v.id limit least(c_lote, c_tope - v_vistas));
      end if;
      exit when cardinality(v_ids) = 0;
      v_vistas := v_vistas + cardinality(v_ids);
      for w in select x.id, x.titulo, x.fase_desde, x.creado_por, x.lead_id from public.vehiculos x
                where x.id = any (v_ids) order by x.fase_desde, x.id loop
        for i in 1 .. cardinality(v_usuarios) loop
          if v_todos[i] or w.creado_por = v_usuarios[i]
             or (w.lead_id is not null and v_usuarios[i] <> all (v_fuera) and exists (select 1 from public.leads_asesores la
                  where la.lead_id = w.lead_id and la.usuario_id = v_usuarios[i] and la.revocado_en is null)) then
            v_n := v_n + public._alerta_demora_avisar(w.id, w.titulo, p.fase_id, p.nombre, w.fase_desde, p.dias, p.horas, v_usuarios[i]);
          end if;
        end loop;
        v_desde := w.fase_desde; v_id := w.id;
      end loop;
      exit when cardinality(v_ids) < c_lote or v_vistas >= c_tope;
    end loop;
  end loop;
  return v_n;
end;
$$;


ALTER FUNCTION "public"."alertas_demora"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."alertas_demora"() IS 'Alertas (6.12): job alertas-demora cada hora. Por pares (origen, fase) que alertan, de a 200 y hasta 2.000 unidades por corrida; avisa demora_fase a quien tiene flujos.mover, logistica.ver y vehiculos.ver del origen (el menor alcance) y reabre el mismo aviso pasado alerta_cada_horas (nulo = 72 h). Devuelve los intentos.';



CREATE OR REPLACE FUNCTION "public"."apibara_consulta_guardar"("p_usuario" "uuid", "p_origen" "uuid", "p_raw" "jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid;
begin
  if p_usuario is null or not exists (select 1 from public.perfiles p where p.id = p_usuario) then
    raise exception 'Falta quién consultó.' using errcode = '22023';
  end if;
  if not exists (select 1 from public.origenes o where o.id = p_origen and o.tipo = 'subasta') then
    raise exception 'Sólo un origen de subasta consulta apibara.' using errcode = '22023';
  end if;
  perform public._vehiculo_apibara_valido(p_raw);
  insert into public.apibara_consultas (origen_id, creado_por, raw) values (p_origen, p_usuario, p_raw)
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."apibara_consulta_guardar"("p_usuario" "uuid", "p_origen" "uuid", "p_raw" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apibara_consulta_leer"("p_consulta" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_raw jsonb;
begin
  perform public.assert_activo();
  select c.raw into v_raw from public.apibara_consultas c
  where c.id = p_consulta and c.creado_por = (select auth.uid()) and c.creado_en >= now() - interval '24 hours';
  if not found then
    raise exception 'Esa consulta a la subasta ya no existe. Vuelve a consultar.' using errcode = '22023';
  end if;
  return v_raw;
end;
$$;


ALTER FUNCTION "public"."apibara_consulta_leer"("p_consulta" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apibara_consultas_purgar"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n integer; v_total integer := 0; i integer;
begin
  for i in 1..10 loop
    delete from public.apibara_consultas c
     where c.id in (select x.id from public.apibara_consultas x
                     where x.creado_en < now() - interval '48 hours' order by x.creado_en limit 10000);
    get diagnostics v_n = row_count;
    v_total := v_total + v_n;
    exit when v_n < 10000;
  end loop;
  return v_total;
end;
$$;


ALTER FUNCTION "public"."apibara_consultas_purgar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apibara_contexto"("p_origen" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_int public.integraciones; v_origen public.origenes; v_plat text[]; v_config text[]; v_uso boolean;
begin
  if (select auth.uid()) is null then
    return jsonb_build_object('aplica', false, 'puede_ver_uso', false);
  end if;
  v_uso := public.tiene_permiso('empresa.ajustes.gestionar');
  select * into v_int from public.integraciones i where i.clave = 'apibara';
  select * into v_origen from public.origenes o where o.id = p_origen;
  if p_origen is null or not found or v_origen.tipo <> 'subasta' then
    return jsonb_build_object('aplica', false, 'puede_ver_uso', v_uso);
  end if;
  select coalesce(array_agg(x), '{}') into v_config from jsonb_array_elements_text(coalesce(v_int.config -> 'plataformas', '[]'::jsonb)) x;
  v_plat := case when cardinality(v_origen.apibara_plataformas) = 0 then v_config
                 else (select coalesce(array_agg(p), '{}') from unnest(v_origen.apibara_plataformas) p where p = any (v_config)) end;
  return jsonb_build_object(
    'aplica', true,
    'usuario', (select auth.uid()),
    'activa', coalesce(v_int.activa, false) and v_int.secreto_guardado_en is not null,
    'endpoint', v_int.config ->> 'endpoint',
    'plataformas', to_jsonb(v_plat),
    'puede_crear', public.tiene_permiso('vehiculos.crear', p_origen),
    'puede_editar', public.tiene_permiso('vehiculos.editar', p_origen),
    'puede_ver_uso', v_uso);
end;
$$;


ALTER FUNCTION "public"."apibara_contexto"("p_origen" "uuid") OWNER TO "postgres";


