CREATE OR REPLACE FUNCTION "public"."avatares_miniaturas_correr"() RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_url text := public._url_del_proyecto();
begin
  if v_url is null then
    raise warning 'avatares-miniaturas no corrió: falta el secreto url_proyecto en Vault (lo pone scripts/demo/restaurar.sh).';
    return null;
  end if;
  return public.avatares_miniaturas_disparar(v_url || '/functions/v1/avatares-miniaturas');
end $$;


ALTER FUNCTION "public"."avatares_miniaturas_correr"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."avatares_miniaturas_correr"() IS 'El job avatares-miniaturas: dispara la función con la URL de Vault (url_proyecto). Sin el secreto, avisa y no hace nada.';



CREATE OR REPLACE FUNCTION "public"."avatares_miniaturas_disparar"("p_url" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_pase uuid; v_pedido bigint;
begin
  if p_url is null or p_url !~ '^https?://[^[:space:]]+/functions/v1/avatares-miniaturas$' then
    raise exception 'La dirección de avatares-miniaturas no es válida.' using errcode = '22023';
  end if;
  insert into public.cola_gc_pases default values returning pase into v_pase;
  select net.http_post(url := p_url, body := jsonb_build_object('pase', v_pase),
    headers := jsonb_build_object('Content-Type', 'application/json'), timeout_milliseconds := 60000) into v_pedido;
  return v_pedido;
end;
$_$;


ALTER FUNCTION "public"."avatares_miniaturas_disparar"("p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avatares_miniaturas_pendientes"("p_max" integer) RETURNS TABLE("usuario_id" "uuid", "avatar_ruta" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select p.id, p.avatar_ruta from public.perfiles p
   where p.avatar_ruta is not null and p.avatar_miniatura_ruta is null and p.avatar_miniatura_fallo_en is null
   order by p.id
   limit public._acotar_pagina(p_max, 20, 100);
$$;


ALTER FUNCTION "public"."avatares_miniaturas_pendientes"("p_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."avatares_miniaturas_programar"("p_url" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
begin
  if p_url is null or p_url !~ '^https?://[^[:space:]]+/functions/v1/avatares-miniaturas$' then
    raise exception 'La dirección de avatares-miniaturas no es válida.' using errcode = '22023';
  end if;
  perform cron.schedule('avatares-miniaturas', '23 * * * *', format('select public.avatares_miniaturas_disparar(%L)', p_url));
end;
$_$;


ALTER FUNCTION "public"."avatares_miniaturas_programar"("p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."buscador_cotizaciones"("p_texto" "text", "p_tamano" integer) RETURNS TABLE("id" "uuid", "numero" bigint, "origen_id" "uuid", "titulo" "text", "clase" "public"."clase_cotizacion", "estado" "public"."estado_cotizacion", "creado_en" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo constant uuid := (select auth.uid());
  v_n constant integer := public._acotar_pagina(p_tamano, 5, 20);
  v_t uuid[];
  v_p uuid[];
  v_solo_propios uuid[];
  b record;
  v_patron text;
  v_ids uuid[] := '{}'::uuid[];
begin
  if v_yo is null then
    return;
  end if;
  select i.numero, i.texto into b from public._buscador_interpretar(p_texto) i;
  if b.numero is null and b.texto is null then
    return;
  end if;
  v_t := coalesce((select public.origenes_con_alcance('cotizaciones.ver', 'todos')), '{}');
  v_p := coalesce((select public.origenes_con_alcance('cotizaciones.ver', 'propios')), '{}');
  if cardinality(v_t) = 0 and cardinality(v_p) = 0 then
    return;
  end if;
  -- El número exacto, por `cotizaciones_numero_key`.
  if b.numero is not null then
    v_ids := array(select c.id from public.cotizaciones c where c.numero = b.numero and c.eliminado_en is null);
  end if;
  if b.texto is not null then
    v_patron := '%' || replace(replace(replace(b.texto, '\', '\\'), '%', '\%'), '_', '\_') || '%';
    -- El título, por `cotizaciones_titulo_trgm`: a lo sumo 1.000 candidatas de los orígenes que quien llama ve, antes del resto de la visibilidad
    -- (sin el filtro de origen, 1.000 de otros orígenes con el mismo título dejaban fuera las que sí le corresponden).
    v_ids := v_ids || array(
      select c.id from public.cotizaciones c
       where c.titulo ilike v_patron and c.eliminado_en is null and c.origen_id = any (v_t || v_p)
       limit 1000);
    -- Las propias, por `cotizaciones_creador_idx (creado_por, creado_en desc, id desc) where eliminado_en is null`, sólo donde quien llama tiene «propios» sin
    -- «todos»: encuentra las suyas aunque el título lo compartan miles de ajenas que no ve. Donde ve «todos» no corre (recorría todas sus propias con un título
    -- raro): ahí, con más de 1.000 coincidencias, las suyas no tienen prioridad. Crece con las propias de quien busca, no con N (límite declarado en RENDIMIENTO).
    v_solo_propios := array(select unnest(v_p) except select unnest(v_t));
    if cardinality(v_solo_propios) > 0 then
      v_ids := v_ids || array(
        select c.id from public.cotizaciones c
         where c.creado_por = v_yo and c.eliminado_en is null and c.origen_id = any (v_solo_propios) and c.titulo ilike v_patron
         order by c.creado_en desc, c.id desc
         limit v_n + 1);
    end if;
  end if;
  if cardinality(v_ids) = 0 then
    return;
  end if;
  -- La policy «cotizaciones: leer», tal cual, sobre las candidatas (por la PK).
  return query
    select c.id, c.numero, c.origen_id, c.titulo, c.clase, c.estado, c.creado_en
      from public.cotizaciones c
     where c.id = any (v_ids)
       and c.eliminado_en is null
       and (c.origen_id = any (v_t)
            or (c.origen_id = any (v_p) and (c.creado_por = v_yo or public.en_cartera(c.lead_id))))
     order by (c.numero = b.numero) desc nulls last, c.creado_en desc, c.id desc
     limit v_n + 1;
end $$;


ALTER FUNCTION "public"."buscador_cotizaciones"("p_texto" "text", "p_tamano" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."buscador_cotizaciones"("p_texto" "text", "p_tamano" integer) IS 'El buscador (7.12), sección cotizaciones: por número exacto (cotizaciones_numero_key) o por título (cotizaciones_titulo_trgm, hasta 1.000 candidatas, más las propias por cotizaciones_creador_idx sólo donde se tiene «propios» sin «todos»), nunca por el lead. Security definer: repite la policy «cotizaciones: leer» fila por fila; sin papelera, sin montos, sin lead_id, vehiculo_id ni creado_por. Mínimo de _buscador_interpretar; hasta _acotar_pagina(p_tamano, 5, 20) + 1. La llama el navegador (src/modules/buscador).';



CREATE OR REPLACE FUNCTION "public"."buscador_leads"("p_texto" "text", "p_tamano" integer) RETURNS "uuid"[]
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_n constant integer := public._acotar_pagina(p_tamano, 5, 20);
  b record;
  v_ids uuid[] := '{}'::uuid[];
begin
  if (select auth.uid()) is null then
    return '{}'::uuid[];
  end if;
  select i.numero, i.texto into b from public._buscador_interpretar(p_texto) i;
  if b.numero is null and b.texto is null then
    return '{}'::uuid[];
  end if;
  -- El número: el global con `leads.numero_global.ver`, si no el propio de quien llama (`leads_numeros_globales`/`leads_numeros_propios`, por su PK).
  if b.numero is not null then
    v_ids := public.leads_ids_del_numero(b.numero, (select public.tiene_permiso('leads.numero_global.ver')));
  end if;
  -- El nombre: la ventana de `leads_candidatos()` (índice de trigramas de `leads.nombre`, la búsqueda del listado) con sólo el texto, nunca
  -- `comparaciones`, `privados` ni `extra`: el texto se aplica a `l.nombre` y a nada más.
  if b.texto is not null then
    v_ids := v_ids || array(
      select j.x::uuid
        from jsonb_array_elements_text(public.leads_candidatos(jsonb_build_object('texto', b.texto, 'sentido', 'siguiente')) -> 'ids') with ordinality j (x, o)
       order by j.o);
  end if;
  -- Una sola pasada por `leads_vista_por_ids()` (la RLS de leads es el único filtro), sin repetir y en el orden de llegada: el número primero.
  return coalesce(array(
    select u.id
      from (select distinct on (x) x as id, o from unnest(v_ids) with ordinality t (x, o) order by x, o) u
     where u.id in (select v.id from public.leads_vista_por_ids(v_ids) v)
     order by u.o
     limit v_n + 1), '{}'::uuid[]);
end $$;


ALTER FUNCTION "public"."buscador_leads"("p_texto" "text", "p_tamano" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."buscador_leads"("p_texto" "text", "p_tamano" integer) IS 'El buscador (7.12), sección leads: ids de los leads que quien llama ve, por número (leads_ids_del_numero) y por nombre (leads_candidatos con sólo el texto), el número primero, pasados por leads_vista_por_ids. Nunca por teléfono ni por un campo. Mínimo de _buscador_interpretar; hasta _acotar_pagina(p_tamano, 5, 20) + 1. Invocadora. La llama el navegador (src/modules/buscador).';



CREATE OR REPLACE FUNCTION "public"."buscador_vehiculos"("p_texto" "text", "p_tamano" integer) RETURNS TABLE("id" "uuid", "origen_id" "uuid", "titulo" "text", "vin" "text", "lote" "text", "creado_en" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_n constant integer := public._acotar_pagina(p_tamano, 5, 20);
  v_texto text;
  v_patron text;
begin
  if (select auth.uid()) is null then
    return;
  end if;
  select i.texto into v_texto from public._buscador_interpretar(p_texto) i;
  -- `#n` (sólo número) no busca vehículos; un número de 3 o más dígitos se busca como texto.
  if v_texto is null then
    return;
  end if;
  -- El patrón «contiene», escapado en línea como `_vehiculos_inventario_patron()` (`_lead_busqueda_patron` es de service_role).
  v_patron := '%' || replace(replace(replace(v_texto, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  -- Cada origen visible por `vehiculos_origen_listado_idx (origen_id, creado_en desc, id desc) where eliminado_en is null`, n + 1 por origen.
  return query
    select v.id, v.origen_id, v.titulo, v.vin, v.lote, v.creado_en
      from unnest(public.origenes_con_alcance('vehiculos.ver', 'propios')) o (id)
     cross join lateral (
       select x.id, x.origen_id, x.titulo, x.vin, x.lote, x.creado_en
         from public.vehiculos x
        where x.origen_id = o.id and x.eliminado_en is null
          and (x.titulo ilike v_patron or x.vin ilike v_patron or x.lote ilike v_patron)
        order by x.creado_en desc, x.id desc
        limit v_n + 1) v
     order by v.creado_en desc, v.id desc
     limit v_n + 1;
end $$;


ALTER FUNCTION "public"."buscador_vehiculos"("p_texto" "text", "p_tamano" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."buscador_vehiculos"("p_texto" "text", "p_tamano" integer) IS 'El buscador (7.12), sección vehículos: los que quien llama ve cuyo título, VIN o lote contiene el texto, del más nuevo al más viejo. Una ruta por origen de origenes_con_alcance(vehiculos.ver, propios) por vehiculos_origen_listado_idx. #n no busca vehículos. Mínimo de _buscador_interpretar; hasta _acotar_pagina(p_tamano, 5, 20) + 1. Invocadora. La llama el navegador (src/modules/buscador).';



CREATE OR REPLACE FUNCTION "public"."cambiar_fase"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_fase_destino" "uuid", "p_nota" "text" DEFAULT NULL::"text", "p_fase_esperada" "uuid" DEFAULT NULL::"uuid") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare pre jsonb; v_actual uuid; v_flujo uuid; v_hist bigint;
begin
  perform public.assert_activo();
  if num_nonnulls(p_vehiculo, p_repuesto) <> 1 then raise exception 'Una unidad por vez.' using errcode = '22023', hint = 'unidad'; end if;
  -- El acceso antes del candado: quien no ve la unidad recibe 42501 sin esperar a quien la está moviendo.
  if not public.puede_unidad(p_vehiculo, p_repuesto, 'logistica.ver', 'repuestos.ver') then
    raise exception '%', public._unidad_sin_acceso(p_vehiculo) using errcode = '42501', hint = 'acceso';
  end if;
  -- El candado de la unidad antes de leer: otro que mueve la misma unidad espera aquí y, cuando éste confirma, lee la fase nueva.
  if p_vehiculo is not null then
    perform 1 from public.vehiculos v where v.id = p_vehiculo and v.eliminado_en is null for no key update;
  else
    perform 1 from public.repuestos_items i where i.id = p_repuesto and i.eliminado_en is null for no key update;
  end if;
  -- Sentencia nueva: ve lo confirmado después del candado (la papelera y el acceso se vuelven a mirar).
  pre := public.previsualizar_cambio_fase(p_vehiculo, p_repuesto, p_fase_destino);
  if pre -> 'codigos' ->> 0 = 'acceso' then
    raise exception '%', pre -> 'motivos' ->> 0 using errcode = '42501', hint = 'acceso';
  end if;
  v_actual := (pre ->> 'fase_actual')::uuid;
  if v_actual is distinct from p_fase_esperada then
    perform public._fase_conflicto(p_vehiculo, p_repuesto, v_actual);
  end if;
  if not (pre ->> 'ok')::boolean then
    raise exception 'No se puede mover: %', array_to_string(array(select jsonb_array_elements_text(pre -> 'motivos')), ' ')
      using errcode = '23514', hint = pre -> 'codigos' ->> 0;
  end if;
  if (pre ->> 'nota_obligatoria')::boolean and coalesce(trim(p_nota), '') = '' then
    raise exception 'Esta fase pide una nota interna.' using errcode = '23514', hint = 'nota';
  end if;
  select flujo_id into v_flujo from public.fases where id = p_fase_destino;
  if p_vehiculo is not null then
    update public.vehiculos set fase_id = p_fase_destino, fase_desde = now() where id = p_vehiculo;
  else
    update public.repuestos_items set fase_id = p_fase_destino, fase_desde = now() where id = p_repuesto;
  end if;
  insert into public.historial_fases (flujo_id, vehiculo_id, repuesto_id, de_fase_id, a_fase_id, nota, usuario_id)
  values (v_flujo, p_vehiculo, p_repuesto, v_actual, p_fase_destino, nullif(trim(p_nota), ''), (select auth.uid())) returning id into v_hist;
  if nullif(trim(p_nota), '') is not null then
    insert into public.notas (vehiculo_id, repuesto_id, historial_fase_id, cuerpo, autor_id)
    values (p_vehiculo, p_repuesto, v_hist, trim(p_nota), (select auth.uid()));
  end if;
  perform public.registrar_actividad('unidad.fase_cambiada', case when p_vehiculo is not null then 'vehiculos' else 'repuestos_items' end,
    coalesce(p_vehiculo, p_repuesto)::text, jsonb_build_object('fase', v_actual), jsonb_build_object('fase', p_fase_destino, 'historial', v_hist));
  return v_hist;
end;
$$;


ALTER FUNCTION "public"."cambiar_fase"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_fase_destino" "uuid", "p_nota" "text", "p_fase_esperada" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cambiar_fase"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_fase_destino" "uuid", "p_nota" "text", "p_fase_esperada" "uuid") IS 'Mueve una unidad de fase (paso 6.02-1): acceso → candado for no key update → vista previa → conflicto → rechazos → escribir. p_fase_esperada nula significa «la espero sin fase»: vale sólo para una unidad que todavía no tiene fase; con fase da PT409 (cierra la deuda aceptada de ESTADO). Los rechazos llevan su código en hint: acceso, unidad (42501/22023), conflicto (PT409, con quién y cuándo), transicion, rol, requisitos, nota (23514).';



CREATE OR REPLACE FUNCTION "public"."cambiar_fase_lote"("p_unidades" "jsonb", "p_fase_destino" "uuid", "p_nota" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  e jsonb; v uuid; v_ids uuid[] := '{}'::uuid[]; v_esperadas uuid[] := '{}'::uuid[]; i int; h bigint; salida jsonb[]; v_m text; v_h text;
begin
  -- Una cuenta bloqueada aborta el lote entero (no 200 filas con el 42501 sin código de `assert_activo`).
  perform public.assert_activo();
  if jsonb_typeof(p_unidades) is distinct from 'array' or jsonb_array_length(p_unidades) not between 1 and 200 then
    raise exception 'Un lote lleva de 1 a 200 unidades.' using errcode = '22023', hint = 'p_unidades';
  end if;
  -- La forma es del llamador, no de una unidad: un elemento mal formado o repetido no mueve nada. Los ids se validan antes de convertir (un cast
  -- inválido daría 22P02).
  for e in select x from jsonb_array_elements(p_unidades) x loop
    if jsonb_typeof(e) is distinct from 'object' or jsonb_typeof(e -> 'vehiculo') is distinct from 'string'
       or not pg_input_is_valid(e ->> 'vehiculo', 'uuid')
       or coalesce(jsonb_typeof(e -> 'fase_esperada'), 'null') not in ('string', 'null')
       or (jsonb_typeof(e -> 'fase_esperada') = 'string' and not pg_input_is_valid(e ->> 'fase_esperada', 'uuid')) then
      raise exception 'Cada unidad del lote es {vehiculo, fase_esperada} con ids válidos.' using errcode = '22023', hint = 'p_unidades';
    end if;
    v := (e ->> 'vehiculo')::uuid;
    if v = any (v_ids) then
      raise exception 'Un vehículo está dos veces en el lote.' using errcode = '22023', hint = 'p_unidades';
    end if;
    v_ids := array_append(v_ids, v);
    v_esperadas := array_append(v_esperadas, (e ->> 'fase_esperada')::uuid);
  end loop;
  salida := array_fill(null::jsonb, array[cardinality(v_ids)]);
  for i in select o.n from unnest(v_ids) with ordinality o (id, n) order by o.id loop
    begin
      h := public.cambiar_fase(v_ids[i], null, p_fase_destino, p_nota, v_esperadas[i]);
      salida[i] := jsonb_build_object('vehiculo_id', v_ids[i], 'ok', true, 'codigo', null, 'motivo', null, 'historial_id', h);
    exception when sqlstate 'PT409' or check_violation or insufficient_privilege or invalid_parameter_value then
      get stacked diagnostics v_m = message_text, v_h = pg_exception_hint;
      salida[i] := jsonb_build_object('vehiculo_id', v_ids[i], 'ok', false, 'codigo', nullif(v_h, ''), 'motivo', v_m, 'historial_id', null);
    end;
  end loop;
  return to_jsonb(salida);
end;
$$;


ALTER FUNCTION "public"."cambiar_fase_lote"("p_unidades" "jsonb", "p_fase_destino" "uuid", "p_nota" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cambiar_fase_lote"("p_unidades" "jsonb", "p_fase_destino" "uuid", "p_nota" "text") IS 'Mueve hasta 200 vehículos a una fase (paso 6.02-1): p_unidades = [{vehiculo, fase_esperada}]; devuelve por unidad, en el orden de entrada, {vehiculo_id, ok, codigo, motivo, historial_id}. Un lote mal formado da 22023 (hint p_unidades) sin mover nada.';



CREATE OR REPLACE FUNCTION "public"."cambiar_telefono_lead"("p_lead" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cc" "text", "p_tel" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  l public.leads;
  v_cc text;
  v_cc_digitos text;
  v_tel text;
  v_verif jsonb;
  v_estado text;
begin
  l := public._lead_mio(p_lead, 'leads.editar', true);
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  v_cc := coalesce(nullif(btrim(p_cc), ''), (select e.telefono_cc from public.ajustes_empresa e where e.id = 1));
  v_tel := public.normalizar_telefono(v_cc, p_tel);
  -- El mismo número no es un conflicto aunque la versión sea otra: un reintento no choca consigo mismo.
  if v_tel = l.telefono_principal then
    return public._lead_telefonos_estado(l.id, 'sin_cambios');
  end if;
  v_verif := public._lead_verificar(v_tel, l.id);
  v_estado := v_verif ->> 'estado';
  if v_estado in ('existe', 'de_otro', 'limbo') then
    return jsonb_build_object('resultado', v_estado, 'verificacion', v_verif);
  end if;
  if l.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._lead_conflicto(l.id, l.actualizado_en);
  end if;

  v_cc_digitos := regexp_replace(coalesce(v_cc, ''), '\D', '', 'g');
  begin
    update public.leads x set
      telefono_cc = case when v_cc_digitos <> '' and v_tel like v_cc_digitos || '%' then '+' || v_cc_digitos end,
      telefono_principal = v_tel
    where x.id = l.id;
  exception when unique_violation then
    -- Otra persona tomó ese número justo ahora: se dice como valor, no como error.
    v_verif := public._lead_verificar(v_tel, l.id);
    v_estado := v_verif ->> 'estado';
    if v_estado in ('existe', 'de_otro', 'limbo') then
      return jsonb_build_object('resultado', v_estado, 'verificacion', v_verif);
    end if;
    raise exception 'Ese teléfono cambió mientras guardabas. Vuelve a intentarlo.' using errcode = 'PT409';
  end;

  delete from public.leads_telefonos t where t.lead_id = l.id and t.telefono = v_tel;
  insert into public.leads_telefonos (lead_id, telefono, etiqueta)
  values (l.id, l.telefono_principal, 'Anterior')
  on conflict (lead_id, telefono) do nothing;

  perform public.registrar_actividad('lead.telefono_cambiado', 'leads', l.id::text, null, null,
    jsonb_build_object('anterior', public.enmascarar_telefono(l.telefono_principal),
                       'nuevo', public.enmascarar_telefono(v_tel)));
  return public._lead_telefonos_estado(l.id, 'cambiado');
end;
$$;


ALTER FUNCTION "public"."cambiar_telefono_lead"("p_lead" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cc" "text", "p_tel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."categoria_crear"("p_origen" "uuid", "p_nombre" "text", "p_padre" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_nombre text; v_id uuid; v_version timestamptz;
begin
  perform public.assert_permiso('origenes.gestionar');
  perform 1 from public.origenes o where o.id = p_origen for update;
  if not found then raise exception 'Ese origen ya no existe.' using errcode = 'PT409'; end if;
  v_nombre := public._origen_nombre_valido(p_nombre, 'el nombre de la categoría', 60);
  if p_padre is not null then
    if not exists (select 1 from public.categorias x where x.id = p_padre and x.origen_id = p_origen) then
      raise exception 'La categoría padre ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
    end if;
    if exists (select 1 from public.categorias x where x.id = p_padre and x.padre_id is not null) then
      raise exception 'Las categorías tienen un solo nivel de anidado.';
    end if;
  end if;
  begin
    insert into public.categorias (origen_id, padre_id, nombre, orden)
    values (p_origen, p_padre, v_nombre,
            coalesce((select max(x.orden) + 10 from public.categorias x where x.origen_id = p_origen and x.padre_id is not distinct from p_padre), 10))
    returning id, actualizado_en into v_id, v_version;
  exception when unique_violation then
    raise exception 'Ya hay una categoría «%» en este lugar.', v_nombre using errcode = '23505';
  end;
  return jsonb_build_object('id', v_id, 'actualizado_en', v_version);
end;
$$;


ALTER FUNCTION "public"."categoria_crear"("p_origen" "uuid", "p_nombre" "text", "p_padre" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."categoria_eliminar"("p_categoria" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.categorias; v_vehiculos int; v_hijas int;
begin
  perform public.assert_permiso('origenes.gestionar');
  select * into c from public.categorias x where x.id = p_categoria for update;
  if not found then raise exception 'Esa categoría ya no existe.' using errcode = 'PT409'; end if;
  perform public._exigir_version(c.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió esta categoría mientras la editabas.');
  select count(*) into v_hijas from public.categorias x where x.padre_id = p_categoria;
  if v_hijas > 0 then
    raise exception '«%» tiene subcategorías: elimínalas primero.', c.nombre using errcode = '23503';
  end if;
  select count(*) into v_vehiculos from public.vehiculos v where v.categoria_id = p_categoria;
  if v_vehiculos > 0 then
    raise exception '% % están en «%». Desactívala para conservarlos agrupados.',
      v_vehiculos, case when v_vehiculos = 1 then 'vehículo' else 'vehículos' end, c.nombre using errcode = '23503';
  end if;
  delete from public.categorias where id = p_categoria;
end;
$$;


ALTER FUNCTION "public"."categoria_eliminar"("p_categoria" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."categoria_guardar"("p_categoria" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text" DEFAULT NULL::"text", "p_activa" boolean DEFAULT NULL::boolean) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.categorias; v_nombre text; v_nueva timestamptz;
begin
  perform public.assert_permiso('origenes.gestionar');
  select * into c from public.categorias x where x.id = p_categoria for update;
  if not found then raise exception 'Esa categoría ya no existe.' using errcode = 'PT409'; end if;
  perform public._exigir_version(c.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió esta categoría mientras la editabas.');
  v_nombre := case when p_nombre is null then c.nombre else public._origen_nombre_valido(p_nombre, 'el nombre de la categoría', 60) end;
  if p_activa is false and exists (select 1 from public.categorias x where x.padre_id = p_categoria and x.activa) then
    raise exception 'Desactiva primero las subcategorías de «%».', c.nombre;
  end if;
  begin
    update public.categorias x set nombre = v_nombre, activa = coalesce(p_activa, x.activa)
    where x.id = p_categoria returning x.actualizado_en into v_nueva;
  exception when unique_violation then
    raise exception 'Ya hay una categoría «%» en este lugar.', v_nombre using errcode = '23505';
  end;
  return v_nueva;
end;
$$;


ALTER FUNCTION "public"."categoria_guardar"("p_categoria" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text", "p_activa" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."categoria_mover"("p_categoria" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_despues_de" "uuid" DEFAULT NULL::"uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.categorias; v_nueva timestamptz;
begin
  perform public.assert_permiso('origenes.gestionar');
  select * into c from public.categorias x where x.id = p_categoria;
  if not found then raise exception 'Esa categoría ya no existe.' using errcode = 'PT409'; end if;
  perform 1 from public.origenes o where o.id = c.origen_id for update;
  select * into c from public.categorias x where x.id = p_categoria for update;
  perform public._exigir_version(c.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió esta categoría mientras la editabas.');
  if p_despues_de is not null then
    if p_despues_de = p_categoria then raise exception 'Una categoría no puede ir después de sí misma.'; end if;
    if not exists (select 1 from public.categorias x where x.id = p_despues_de and x.origen_id = c.origen_id and x.padre_id is not distinct from c.padre_id) then
      raise exception 'Esa categoría ya no está en este lugar. Recarga e intenta de nuevo.' using errcode = 'PT409';
    end if;
  end if;

  update public.categorias x set orden = n.nuevo
  from (
    select id, (row_number() over (order by posicion, nombre) * 10)::smallint as nuevo from (
      select x.id, x.nombre,
        case
          when x.id = p_categoria then (case when p_despues_de is null then -1.0
                                             else (select y.orden from public.categorias y where y.id = p_despues_de) + 0.5 end)
          else x.orden::numeric
        end as posicion
      from public.categorias x where x.origen_id = c.origen_id and x.padre_id is not distinct from c.padre_id
    ) q
  ) n
  where x.id = n.id and x.orden <> n.nuevo;

  select x.actualizado_en into v_nueva from public.categorias x where x.id = p_categoria;
  return v_nueva;
end;
$$;


ALTER FUNCTION "public"."categoria_mover"("p_categoria" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_despues_de" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."categorias_con_uso"("p_origen" "uuid") RETURNS TABLE("categoria_id" "uuid", "vehiculos" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_permiso('origenes.gestionar');
  return query
  select k.id, (select count(*)::int from public.vehiculos v where v.categoria_id = k.id)
  from public.categorias k where k.origen_id = p_origen;
end;
$$;


ALTER FUNCTION "public"."categorias_con_uso"("p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_conversaciones"("p_tamano" integer DEFAULT NULL::integer, "p_antes_en" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_antes_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_n int := public._acotar_pagina(p_tamano, 20, 50);
  v_global boolean;
  v_ids uuid[];
  v_hay boolean;
  v_filas jsonb;
begin
  perform public.assert_activo();
  if (p_antes_en is null) <> (p_antes_id is null) then
    raise exception 'El cursor de la página está incompleto.' using errcode = '22023', hint = 'cursor';
  end if;
  v_global := public.tiene_permiso('chat.global');
  -- Las dos por conversaciones_miembros_usuario_idx (usuario_id) y conversaciones_pkey; ordenan sólo las conversaciones de quien mira.
  if p_antes_en is null then
    select coalesce(array_agg(t.id order by t.ultimo_mensaje_en desc, t.id desc), '{}') into v_ids
      from (select c.id, c.ultimo_mensaje_en
              from public.conversaciones_miembros m
              join public.conversaciones c on c.id = m.conversacion_id
             where m.usuario_id = v_yo and (not c.es_global or v_global)
             order by c.ultimo_mensaje_en desc, c.id desc limit v_n + 1) t;
  else
    select coalesce(array_agg(t.id order by t.ultimo_mensaje_en desc, t.id desc), '{}') into v_ids
      from (select c.id, c.ultimo_mensaje_en
              from public.conversaciones_miembros m
              join public.conversaciones c on c.id = m.conversacion_id
             where m.usuario_id = v_yo and (not c.es_global or v_global)
               and (c.ultimo_mensaje_en, c.id) < (p_antes_en, p_antes_id)
             order by c.ultimo_mensaje_en desc, c.id desc limit v_n + 1) t;
  end if;
  -- La de más no viaja: es sólo el aviso de que hay otra página.
  v_hay := cardinality(v_ids) > v_n;
  if v_hay then v_ids := v_ids[1:v_n]; end if;
  -- Lo derivado, sobre la página: conversaciones_pkey y conversaciones_miembros_pkey por fila; no leídos por mensajes_hilo_idx (≤ 100 entradas);
  -- la otra persona por perfiles_pkey.
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', c.id,
           'tipo', c.tipo,
           'nombre', c.nombre,
           'es_global', c.es_global,
           'ultimo_mensaje_en', c.ultimo_mensaje_en,
           'ultimo_leido_en', m.ultimo_leido_en,
           'silenciada', m.silenciada,
           'no_leidos', (select count(*) filter (where s.autor_id <> v_yo)
                           from (select x.autor_id from public.mensajes x
                                  where x.conversacion_id = c.id and x.creado_en > coalesce(m.ultimo_leido_en, '-infinity'::timestamptz)
                                  order by x.creado_en desc, x.id desc limit 100) s),
           'otro', case when c.tipo = 'directa' then
                     (select jsonb_build_object('id', pf.id, 'nombre', pf.nombre)
                        from public.perfiles pf
                       where pf.id = coalesce(
                               case when c.par_directo[1] = v_yo then c.par_directo[2] else c.par_directo[1] end,
                               (select o.usuario_id from public.conversaciones_miembros o
                                 where o.conversacion_id = c.id and o.usuario_id <> v_yo
                                 order by o.usuario_id limit 1)))
                   end
         ) order by u.o), '[]'::jsonb)
    into v_filas
    from unnest(v_ids) with ordinality u (id, o)
    join public.conversaciones c on c.id = u.id
    join public.conversaciones_miembros m on m.conversacion_id = c.id and m.usuario_id = v_yo;
  return jsonb_build_object('conversaciones', v_filas, 'hay_mas', v_hay);
end;
$$;


ALTER FUNCTION "public"."chat_conversaciones"("p_tamano" integer, "p_antes_en" timestamp with time zone, "p_antes_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."chat_conversaciones"("p_tamano" integer, "p_antes_en" timestamp with time zone, "p_antes_id" "uuid") IS 'Una página de mis conversaciones (fila de miembro propia y, en el global, chat.global), la del mensaje más reciente primero (p_tamano: 20 por defecto, 50 como mucho). El cursor es (ultimo_mensaje_en, id) de la última de la página anterior; a medias, 22023 hint cursor. Cada fila: id, tipo, nombre, es_global, ultimo_mensaje_en, ultimo_leido_en, silenciada, no_leidos (0 a 100: 100 es «99+»), otro ({id, nombre} en una directa). {conversaciones, hay_mas}. 7.08-3.';



CREATE OR REPLACE FUNCTION "public"."chat_directa"("p_usuario" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare yo uuid := (select auth.uid()); v_par uuid[]; v_id uuid;
begin
  perform public.assert_activo();
  perform public.assert_permiso('chat.participar');
  if p_usuario is null or p_usuario = yo then
    raise exception 'Elige a otra persona del equipo.' using errcode = '22023', hint = 'usuario';
  end if;
  v_par := array[least(yo, p_usuario), greatest(yo, p_usuario)];
  select c.id into v_id from public.conversaciones c where c.par_directo = v_par;
  if v_id is not null then
    return jsonb_build_object('resultado', 'existente', 'id', v_id);
  end if;
  if not public._chat_puede_conversar(p_usuario) then
    raise exception 'Esa persona no puede usar el chat.' using errcode = '23514', hint = 'usuario';
  end if;
  insert into public.conversaciones (tipo, creado_por, par_directo) values ('directa', yo, v_par)
  on conflict (par_directo) where par_directo is not null do nothing
  returning id into v_id;
  if v_id is null then
    -- Otra sesión la abrió a la vez y ganó: el índice esperó su commit y esta lectura ya la ve.
    select c.id into v_id from public.conversaciones c where c.par_directo = v_par;
    return jsonb_build_object('resultado', 'existente', 'id', v_id);
  end if;
  insert into public.conversaciones_miembros (conversacion_id, usuario_id) values (v_id, yo), (v_id, p_usuario);
  return jsonb_build_object('resultado', 'creada', 'id', v_id);
end;
$$;


ALTER FUNCTION "public"."chat_directa"("p_usuario" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_global_entrar"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare yo uuid := (select auth.uid()); v_id uuid; n int;
begin
  perform public.assert_activo();
  perform public.assert_permiso('chat.global');
  select c.id into v_id from public.conversaciones c where c.es_global;
  if v_id is null then
    raise exception 'No encontramos esta conversación.' using errcode = '42501';
  end if;
  insert into public.conversaciones_miembros (conversacion_id, usuario_id) values (v_id, yo) on conflict do nothing;
  get diagnostics n = row_count;
  return jsonb_build_object('resultado', case when n = 1 then 'entro' else 'ya_estaba' end, 'id', v_id);
end;
$$;


ALTER FUNCTION "public"."chat_global_entrar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_grupo_crear"("p_id" "uuid", "p_nombre" "text", "p_miembros" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare yo uuid := (select auth.uid()); r public.conversaciones; v_nombre text := btrim(p_nombre); v_otros uuid[]; u uuid;
begin
  perform public.assert_activo();
  perform public.assert_permiso('chat.participar');
  if p_id is null then
    raise exception 'Falta el identificador del grupo.' using errcode = '22023', hint = 'id';
  end if;
  select * into r from public.conversaciones c where c.id = p_id;
  if found then
    if r.creado_por = yo and r.tipo = 'grupo' and not r.es_global then
      return jsonb_build_object('resultado', 'repetido', 'id', r.id);
    end if;
    raise exception 'No pudimos crear este grupo. Vuelve a intentarlo.' using errcode = '22023';
  end if;
  if v_nombre is null or char_length(v_nombre) not between 1 and 80 then
    raise exception 'Ponle al grupo un nombre de hasta 80 caracteres.' using errcode = '22023', hint = 'nombre';
  end if;
  if p_miembros is null or array_position(p_miembros, null) is not null then
    raise exception 'Elige a quiénes sumas al grupo.' using errcode = '22023', hint = 'miembros';
  end if;
  v_otros := array(select distinct m from unnest(p_miembros) m where m <> yo);
  if cardinality(v_otros) not between 1 and 49 then
    raise exception 'Un grupo tiene de 2 a 50 personas.' using errcode = '22023', hint = 'miembros';
  end if;
  foreach u in array v_otros loop
    if not public._chat_puede_conversar(u) then
      raise exception 'Alguien de la lista no puede usar el chat.' using errcode = '23514', hint = 'miembros';
    end if;
  end loop;
  begin
    insert into public.conversaciones (id, tipo, nombre, creado_por) values (p_id, 'grupo', v_nombre, yo);
  exception when unique_violation then
    select * into r from public.conversaciones c where c.id = p_id;
    if r.creado_por = yo and r.tipo = 'grupo' and not r.es_global then
      return jsonb_build_object('resultado', 'repetido', 'id', r.id);
    end if;
    raise exception 'No pudimos crear este grupo. Vuelve a intentarlo.' using errcode = '22023';
  end;
  insert into public.conversaciones_miembros (conversacion_id, usuario_id) select p_id, x from unnest(v_otros || yo) x;
  return jsonb_build_object('resultado', 'creado', 'id', p_id);
end;
$$;


ALTER FUNCTION "public"."chat_grupo_crear"("p_id" "uuid", "p_nombre" "text", "p_miembros" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_grupo_miembros"("p_conversacion" "uuid", "p_agregar" "uuid"[], "p_quitar" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare yo uuid := (select auth.uid()); c public.conversaciones; v_ag uuid[]; v_qu uuid[]; u uuid; n int; v_total int; v_cambios int := 0;
begin
  perform public.assert_activo();
  perform public.assert_permiso('chat.participar');
  if p_conversacion is null then
    raise exception 'Falta la conversación.' using errcode = '22023', hint = 'conversacion';
  end if;
  if array_position(p_agregar, null) is not null then
    raise exception 'Hay una persona vacía en la lista.' using errcode = '22023', hint = 'agregar';
  end if;
  if array_position(p_quitar, null) is not null then
    raise exception 'Hay una persona vacía en la lista.' using errcode = '22023', hint = 'quitar';
  end if;
  v_ag := array(select distinct x from unnest(coalesce(p_agregar, '{}')) x);
  v_qu := array(select distinct x from unnest(coalesce(p_quitar, '{}')) x);
  if v_ag && v_qu then
    raise exception 'No puedes sumar y quitar a la misma persona.' using errcode = '22023', hint = 'agregar';
  end if;
  select * into c from public.conversaciones x where x.id = p_conversacion for no key update;
  if not found or not public.es_miembro(p_conversacion) then
    raise exception 'No encontramos esta conversación.' using errcode = '42501';
  end if;
  if c.tipo <> 'grupo' or c.es_global or c.creado_por is distinct from yo then
    raise exception 'Sólo quien creó el grupo cambia sus miembros.' using errcode = '42501';
  end if;
  if yo = any (v_qu) then
    raise exception 'Para dejar el grupo, sal de él.' using errcode = '22023', hint = 'quitar';
  end if;
  -- Cuenta con tope: alcanza saber si pasa de 50.
  select count(*) into v_total from (
    select m.usuario_id from public.conversaciones_miembros m where m.conversacion_id = p_conversacion and m.usuario_id <> all (v_qu)
    union
    select x from unnest(v_ag) x
    limit 51
  ) t;
  if v_total > 50 then
    raise exception 'Un grupo tiene hasta 50 personas.' using errcode = '22023', hint = 'agregar';
  end if;
  foreach u in array v_ag loop
    if not exists (select 1 from public.conversaciones_miembros m where m.conversacion_id = p_conversacion and m.usuario_id = u)
       and not public._chat_puede_conversar(u) then
      raise exception 'Alguien de la lista no puede usar el chat.' using errcode = '23514', hint = 'agregar';
    end if;
  end loop;
  delete from public.conversaciones_miembros m where m.conversacion_id = p_conversacion and m.usuario_id = any (v_qu);
  get diagnostics n = row_count;
  v_cambios := v_cambios + n;
  insert into public.conversaciones_miembros (conversacion_id, usuario_id) select p_conversacion, x from unnest(v_ag) x on conflict do nothing;
  get diagnostics n = row_count;
  v_cambios := v_cambios + n;
  return jsonb_build_object('resultado', case when v_cambios > 0 then 'guardado' else 'sin_cambios' end, 'id', p_conversacion);
end;
$$;


ALTER FUNCTION "public"."chat_grupo_miembros"("p_conversacion" "uuid", "p_agregar" "uuid"[], "p_quitar" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_leer"("p_conversacion" "uuid", "p_hasta" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare yo uuid := (select auth.uid()); v_hasta timestamptz; v timestamptz;
begin
  perform public.assert_activo();
  if p_conversacion is null then
    raise exception 'Falta la conversación.' using errcode = '22023', hint = 'conversacion';
  end if;
  if p_hasta is null then
    raise exception 'Falta hasta dónde leíste.' using errcode = '22023', hint = 'hasta';
  end if;
  if not public.es_miembro(p_conversacion) then
    raise exception 'No encontramos esta conversación.' using errcode = '42501';
  end if;
  v_hasta := least(p_hasta, clock_timestamp());
  update public.conversaciones_miembros m set ultimo_leido_en = v_hasta
   where m.conversacion_id = p_conversacion and m.usuario_id = yo and (m.ultimo_leido_en is null or m.ultimo_leido_en < v_hasta)
  returning m.ultimo_leido_en into v;
  if found then
    return jsonb_build_object('resultado', 'leido', 'id', p_conversacion, 'ultimo_leido_en', v);
  end if;
  select m.ultimo_leido_en into v from public.conversaciones_miembros m where m.conversacion_id = p_conversacion and m.usuario_id = yo;
  return jsonb_build_object('resultado', 'sin_cambios', 'id', p_conversacion, 'ultimo_leido_en', v);
end;
$$;


ALTER FUNCTION "public"."chat_leer"("p_conversacion" "uuid", "p_hasta" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_no_leidos"() RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_global boolean;
  v int;
begin
  perform public.assert_activo();
  v_global := public.tiene_permiso('chat.global');
  -- conversaciones_miembros_usuario_idx (usuario_id) y conversaciones_pkey; por conversación, mensajes_hilo_idx; se corta a las 100.
  select count(*) into v
    from (select 1
            from public.conversaciones_miembros m
            join public.conversaciones c on c.id = m.conversacion_id
            cross join lateral (select x.autor_id from public.mensajes x
                                 where x.conversacion_id = c.id and x.creado_en > coalesce(m.ultimo_leido_en, '-infinity'::timestamptz)
                                 order by x.creado_en desc, x.id desc limit 100) s
           where m.usuario_id = v_yo and not m.silenciada and (not c.es_global or v_global) and s.autor_id <> v_yo
           limit 100) t;
  return v;
end;
$$;


ALTER FUNCTION "public"."chat_no_leidos"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."chat_no_leidos"() IS 'Mis mensajes sin leer (de otras personas, tras mi última lectura) en las conversaciones donde soy miembro y no silencié; el global, sólo con chat.global. De 0 a 100: 100 es «99+». 7.08-3.';



CREATE OR REPLACE FUNCTION "public"."chat_salir"("p_conversacion" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare yo uuid := (select auth.uid()); c public.conversaciones;
begin
  perform public.assert_activo();
  if p_conversacion is null then
    raise exception 'Falta la conversación.' using errcode = '22023', hint = 'conversacion';
  end if;
  select * into c from public.conversaciones x where x.id = p_conversacion;
  if not found or not public.es_miembro(p_conversacion) then
    raise exception 'No encontramos esta conversación.' using errcode = '42501';
  end if;
  if c.tipo = 'directa' then
    raise exception 'Una conversación directa no se deja: puedes silenciarla.' using errcode = '22023';
  end if;
  delete from public.conversaciones_miembros m where m.conversacion_id = p_conversacion and m.usuario_id = yo;
  return jsonb_build_object('resultado', 'salio', 'id', p_conversacion);
end;
$$;


ALTER FUNCTION "public"."chat_salir"("p_conversacion" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."chat_silenciar"("p_conversacion" "uuid", "p_silenciada" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare yo uuid := (select auth.uid());
begin
  perform public.assert_activo();
  if p_conversacion is null then
    raise exception 'Falta la conversación.' using errcode = '22023', hint = 'conversacion';
  end if;
  if p_silenciada is null then
    raise exception 'Di si la silencias o no.' using errcode = '22023', hint = 'silenciada';
  end if;
  if not public.es_miembro(p_conversacion) then
    raise exception 'No encontramos esta conversación.' using errcode = '42501';
  end if;
  update public.conversaciones_miembros m set silenciada = p_silenciada
   where m.conversacion_id = p_conversacion and m.usuario_id = yo and m.silenciada is distinct from p_silenciada;
  return jsonb_build_object('resultado', case when found then 'guardado' else 'sin_cambios' end, 'id', p_conversacion);
end;
$$;


