CREATE OR REPLACE FUNCTION "public"."comprobante_anular"("p_comprobante" "uuid", "p_motivo" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_cot uuid; v_motivo text; k public.comprobantes; v_en timestamptz;
begin
  perform public.assert_activo();
  perform public.assert_permiso('cotizaciones.comprobantes.emitir');
  -- Sin candado: el que no existe y el de una cotización que no se ve dan lo mismo.
  select cp.cotizacion_id into v_cot from public.comprobantes cp where cp.id = p_comprobante;
  if v_cot is null or not public.puede_cotizacion(v_cot, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a este comprobante.' using errcode = '42501';
  end if;
  v_motivo := btrim(coalesce(p_motivo, ''));
  if v_motivo = '' or char_length(v_motivo) > 500 then
    raise exception 'Anular pide un motivo de hasta 500 caracteres.' using errcode = '22023', hint = 'motivo';
  end if;
  select * into k from public.comprobantes cp where cp.id = p_comprobante for no key update;
  if k.anulado_en is not null then
    raise exception 'Este comprobante ya estaba anulado.' using errcode = 'PT409';
  end if;
  update public.comprobantes cp set anulado_por = (select auth.uid()), anulado_en = now(), motivo_anulacion = v_motivo
   where cp.id = k.id
  returning cp.anulado_en into v_en;
  perform public.registrar_actividad('comprobante.anulado', 'comprobantes', k.id::text, null, jsonb_build_object('serie', k.serie, 'numero', k.numero));
  return jsonb_build_object('id', k.id, 'anulado_en', v_en);
end;
$$;


ALTER FUNCTION "public"."comprobante_anular"("p_comprobante" "uuid", "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."comprobante_anular"("p_comprobante" "uuid", "p_motivo" "text") IS 'Anula un comprobante (4.26-1): cotizaciones.comprobantes.emitir (P5 a); ver su cotización (si no, 42501); motivo de 1 a 500 caracteres (22023, hint motivo); uno ya anulado da PT409. El número no vuelve: la serie sigue. Devuelve {id, anulado_en}.';



CREATE OR REPLACE FUNCTION "public"."comprobante_emitir"("p_cotizacion" "uuid", "p_cotizacion_esperada" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.cotizaciones; v_def jsonb; v_vis jsonb; v_ctx jsonb; v_rec jsonb; v_datos jsonb; v_serie text; v_numero bigint; v_id uuid; v_emitido timestamptz;
  v_vigente text; v_restriccion text;
begin
  -- 1. La clave.
  perform public.assert_activo();
  perform public.assert_permiso('cotizaciones.comprobantes.emitir');
  -- 2. Sin candado: lo que no existe, está en la papelera o no se ve da lo mismo, antes de tomar nada.
  perform 1 from public.cotizaciones x where x.id = p_cotizacion and x.eliminado_en is null;
  if not found or not public.puede_cotizacion(p_cotizacion, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  -- 3. La fila viva, tomada (como `_cotizacion_a_papelera` y marcar final: no choca con las hijas que la referencian).
  select * into c from public.cotizaciones x where x.id = p_cotizacion and x.eliminado_en is null for no key update;
  if not found or not public.puede_cotizacion(c.id, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  -- 4. Sobre la fila tomada: final activa.
  if c.clase <> 'final' or c.estado <> 'activa' then
    raise exception 'Sólo se emite comprobante de una cotización final activa.' using errcode = '23514';
  end if;
  -- 5. Lo que se congela es lo que quien emite tenía en pantalla.
  if p_cotizacion_esperada is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.' using errcode = '22023';
  end if;
  if c.actualizado_en is distinct from p_cotizacion_esperada then
    perform public._conflicto_de_edicion('cotizaciones', c.id, c.actualizado_en, 'esta cotización');
  end if;
  -- 6. Un vigente por cotización (P2 a).
  select cp.serie || '-' || cp.numero into v_vigente from public.comprobantes cp where cp.cotizacion_id = c.id and cp.anulado_en is null;
  if v_vigente is not null then
    raise exception 'Esta cotización ya tiene el comprobante «%» vigente: anúlalo para emitir otro.', v_vigente using errcode = 'PT409';
  end if;
  -- 7. `datos`, antes de tomar la serie: sólo lo del nivel «todos» (el recorte de quien sólo tiene cotizaciones.ver), y del cliente y el vehículo, los ids.
  select f.definicion, coalesce(f.visibilidad, '{}'::jsonb) into v_def, v_vis from public.formulas f where f.id = c.formula_id;
  v_ctx := public._cotizacion_contexto(coalesce(array(select e.key from jsonb_each(v_vis) e where e.value ->> 'ver' = 'todos'), '{}'), v_def, v_vis);
  v_rec := public._cotizacion_recorte(jsonb_build_object('valores', c.valores, 'fuentes', c.fuentes, 'totales', c.totales, 'tipos_cambio', c.tipos_cambio), v_ctx);
  v_datos := jsonb_build_object(
    'version', 1,
    'cotizacion', jsonb_build_object('id', c.id, 'numero', c.numero, 'titulo', c.titulo, 'clase', c.clase),
    'origen', (select jsonb_build_object('id', o.id, 'nombre', o.nombre) from public.origenes o where o.id = c.origen_id),
    'formula_id', c.formula_id,
    'cliente', jsonb_build_object('lead_id', c.lead_id),
    'vehiculo', case when c.vehiculo_id is null then null else jsonb_build_object('id', c.vehiculo_id) end,
    'empresa', (select jsonb_build_object('razon_social', e.razon_social, 'nit', e.nit) from public.ajustes_empresa e where e.id = 1),
    'valores', coalesce(v_rec -> 'valores', '{}'::jsonb),
    'totales', coalesce(v_rec -> 'totales', '{}'::jsonb),
    'tipos_cambio', coalesce(v_rec -> 'tipos_cambio', '{}'::jsonb),
    'etiquetas', coalesce((select jsonb_object_agg(n ->> 'id', n ->> 'etiqueta') from jsonb_array_elements(coalesce(v_def -> 'nodos', '[]'::jsonb)) n
                            where coalesce(v_rec -> 'valores', '{}'::jsonb) ? (n ->> 'id')), '{}'::jsonb));
  -- 8. La serie vigente, tomada (ordena contra comprobantes_serie_cambiar).
  select a.serie into v_serie from public.comprobantes_ajustes a where a.unica for update;
  if v_serie is null then
    raise exception 'No hay una serie vigente de comprobantes.' using errcode = 'P0001';
  end if;
  -- 9. El número y el comprobante en un solo bloque: si sale un error, la subtransacción ya devolvió el número aunque quien llama lo atrape.
  begin
    update public.comprobantes_contadores k set ultimo = k.ultimo + 1 where k.serie = v_serie returning k.ultimo into v_numero;
    if not found then
      raise exception 'No hay contador para la serie vigente.' using errcode = 'P0001';
    end if;
    insert into public.comprobantes (cotizacion_id, serie, numero, datos, emitido_por)
    values (c.id, v_serie, v_numero, v_datos, (select auth.uid()))
    returning id, emitido_en into v_id, v_emitido;
  exception when unique_violation then
    get stacked diagnostics v_restriccion = constraint_name;
    if v_restriccion = 'comprobantes_un_vigente_por_cotizacion' then
      raise exception 'Esta cotización ya tiene un comprobante vigente: anúlalo para emitir otro.' using errcode = 'PT409';
    end if;
    raise;
  end;
  -- 10. La actividad y la respuesta.
  perform public.registrar_actividad('comprobante.emitido', 'comprobantes', v_id::text, null, jsonb_build_object('serie', v_serie, 'numero', v_numero));
  return jsonb_build_object('id', v_id, 'serie', v_serie, 'numero', v_numero, 'emitido_en', v_emitido);
end;
$$;


ALTER FUNCTION "public"."comprobante_emitir"("p_cotizacion" "uuid", "p_cotizacion_esperada" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."comprobante_emitir"("p_cotizacion" "uuid", "p_cotizacion_esperada" timestamp with time zone) IS 'Emite el comprobante de una cotización final activa en la serie vigente (4.26-1): cotizaciones.comprobantes.emitir; ver la cotización antes y con la fila tomada (si no, el 42501 de lo inexistente); la versión que se tenía en pantalla (nula 22023, distinta PT409); un vigente por cotización (PT409). datos = el recorte del nivel «todos» con sus etiquetas, la cotización, el origen, los ids del cliente y del vehículo, y la razón social y el NIT. Candados: cotización → comprobantes_ajustes → contador; sin huecos. Devuelve {id, serie, numero, emitido_en}.';



CREATE OR REPLACE FUNCTION "public"."comprobante_puede"("p_nombre" "text", "p_accion" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare u uuid := public._comprobante_unidad(p_nombre);
begin
  if u is null then
    return false;
  end if;
  if p_accion = 'subir' then
    return public.puede_vehiculo(u, 'logistica.gastos.editar') or public.puede_vehiculo(u, 'logistica.pagos.editar')
        or public.puede_repuesto(u, 'repuestos.costos.editar')
        or (exists (select 1 from public.repuestos_proyectos pr where pr.id = u and pr.eliminado_en is null) and public.tiene_permiso('repuestos.costos.editar'));
  end if;
  if p_accion <> 'ver' then
    return false;
  end if;
  if exists (select 1 from public.gastos g
              where g.comprobante_ruta = p_nombre and g.eliminado_en is null
                and public.puede_unidad(g.vehiculo_id, g.repuesto_id, 'logistica.gastos.ver', 'repuestos.costos.ver'))
     or exists (select 1 from public.pagos p
                 where p.comprobante_ruta = p_nombre and p.eliminado_en is null
                   and case when p.vehiculo_id is not null then public.puede_vehiculo(p.vehiculo_id, 'logistica.pagos.ver')
                            else public.tiene_permiso('repuestos.costos.ver') end)
     or exists (select 1 from public.repuestos_compras rc
                 where rc.comprobante_ruta = p_nombre and rc.eliminado_en is null and public.tiene_permiso('repuestos.costos.ver')) then
    return true;
  end if;
  -- D2 · recién subido: ninguna fila (viva o borrada) lo nombra; lo lee quien puede subir a esa carpeta.
  return not exists (select 1 from public.gastos g where g.comprobante_ruta = p_nombre)
     and not exists (select 1 from public.pagos p where p.comprobante_ruta = p_nombre)
     and not exists (select 1 from public.repuestos_compras rc where rc.comprobante_ruta = p_nombre)
     and public.comprobante_puede(p_nombre, 'subir');
end;
$$;


ALTER FUNCTION "public"."comprobante_puede"("p_nombre" "text", "p_accion" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."comprobante_puede"("p_nombre" "text", "p_accion" "text") IS 'Si quien llama puede «ver» o «subir» ese objeto del bucket comprobantes. Subir: poder editar gastos o pagos de la unidad viva de la carpeta. Ver: ver la fila viva que lo nombra (gasto: logistica.gastos.ver de su unidad; pago: como «pagos: leer»; compra: repuestos.costos.ver), o, si ninguna fila lo nombra, poder subir a esa carpeta. Nunca nula. La llaman las policies de storage.objects (6.10-2, D1–D3).';



CREATE OR REPLACE FUNCTION "public"."comprobantes_serie_cambiar"("p_serie" "text", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_serie text; a public.comprobantes_ajustes; v_antes text; v_siguiente bigint;
begin
  perform public.assert_activo();
  perform public.assert_permiso('empresa.ajustes.gestionar');
  v_serie := upper(btrim(coalesce(p_serie, '')));
  if not (v_serie collate "C" ~ '^[A-Z0-9-]{1,12}$') then
    raise exception 'La serie lleva de 1 a 12 letras, números o guiones.' using errcode = '22023', hint = 'serie';
  end if;
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.' using errcode = '22023';
  end if;
  select * into a from public.comprobantes_ajustes x where x.unica for update;
  if a.actualizado_en is distinct from p_actualizado_en_esperado then
    raise exception 'La serie cambió mientras la editabas. Recarga para ver la vigente.' using errcode = 'PT409';
  end if;
  insert into public.comprobantes_contadores (serie, ultimo) values (v_serie, 0) on conflict do nothing;
  if v_serie is distinct from a.serie then
    v_antes := a.serie;
    update public.comprobantes_ajustes x
       set serie = v_serie, actualizado_en = greatest(clock_timestamp(), a.actualizado_en + interval '1 microsecond'), actualizado_por = (select auth.uid())
     where x.unica
    returning * into a;
    perform public.registrar_actividad('comprobante.serie_cambiada', 'comprobantes_ajustes', 'unica',
      jsonb_build_object('serie', v_antes), jsonb_build_object('serie', v_serie));
  end if;
  select k.ultimo + 1 into v_siguiente from public.comprobantes_contadores k where k.serie = a.serie;
  return jsonb_build_object('serie', a.serie, 'siguiente', v_siguiente, 'actualizado_en', a.actualizado_en);
end;
$_$;


ALTER FUNCTION "public"."comprobantes_serie_cambiar"("p_serie" "text", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."comprobantes_serie_cambiar"("p_serie" "text", "p_actualizado_en_esperado" timestamp with time zone) IS 'Cambia la serie vigente de los comprobantes (4.26-1): empresa.ajustes.gestionar; la serie se guarda en mayúsculas, de 1 a 12 letras A–Z, números o guiones (si no, 22023 con hint serie); versión nula 22023, distinta PT409. Crea el contador de la serie si no existe (una nueva empieza en 1; volver a una usada sigue su numeración). Devuelve {serie, siguiente, actualizado_en}.';



CREATE OR REPLACE FUNCTION "public"."concesion_dominada"("p_clave" "text", "p_origen" "uuid", "p_alcance" "public"."alcance_permiso") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1 from public.mis_permisos() m
    where m.clave = p_clave
      and (m.origen_id is null or m.origen_id = p_origen)
      and (m.alcance = 'todos' or p_alcance = 'propios')
  );
$$;


ALTER FUNCTION "public"."concesion_dominada"("p_clave" "text", "p_origen" "uuid", "p_alcance" "public"."alcance_permiso") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cotizacion_adjuntar"("p_cotizacion" "uuid", "p_ruta" "text", "p_nombre" "text", "p_mime" "text", "p_bytes" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_yo uuid := (select auth.uid());
  v_nombre text := btrim(p_nombre);
  v_meta jsonb;
  v_mime text; v_bytes bigint; v_ext text;
  a public.cotizaciones_adjuntos;
begin
  perform public.assert_activo();
  if not public.puede_cotizacion(p_cotizacion, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  if not public.cotizacion_puede_adjuntar(p_cotizacion) then
    raise exception 'No tienes permiso para adjuntar en esta cotización.' using errcode = '42501';
  end if;
  if p_ruta is null or p_ruta !~ ('^' || p_cotizacion::text || '/[0-9a-f]{64}\.(pdf|webp|jpg|png|docx)$') then
    raise exception 'El archivo no está en la carpeta de esta cotización.' using errcode = '22023', hint = 'ruta';
  end if;
  if v_nombre is null or char_length(v_nombre) not between 1 and 200 or v_nombre ~ '[/\\]' then
    raise exception 'Ponle un nombre al archivo (hasta 200 caracteres, sin barras).' using errcode = '22023', hint = 'nombre';
  end if;
  select o.metadata into v_meta from storage.objects o where o.bucket_id = 'cotizaciones' and o.name = p_ruta;
  if not found then
    raise exception 'El archivo no terminó de subir. Vuelve a intentarlo.' using errcode = '22023', hint = 'ruta';
  end if;
  -- Lo que dice storage pesa más que lo que manda el cliente.
  v_mime := coalesce(v_meta ->> 'mimetype', p_mime);
  v_bytes := coalesce((v_meta ->> 'size')::bigint, p_bytes);
  v_ext := substring(p_ruta from '\.([a-z]+)$');
  if v_mime is distinct from (case v_ext when 'pdf' then 'application/pdf' when 'webp' then 'image/webp' when 'jpg' then 'image/jpeg'
                                          when 'png' then 'image/png'
                                          when 'docx' then 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' end) then
    raise exception 'Ese tipo de archivo no se puede adjuntar (PDF, imágenes o Word).' using errcode = '22023', hint = 'mime';
  end if;
  if v_bytes is null or v_bytes not between 1 and 26214400 then
    raise exception 'El archivo está vacío o pesa más de 25 MB.' using errcode = '22023', hint = 'bytes';
  end if;
  -- Hasta 20 por cotización (cotizaciones_adjuntos_cotizacion_ruta_key): se cuentan a lo sumo 20.
  if (select count(*) from (select 1 from public.cotizaciones_adjuntos x where x.cotizacion_id = p_cotizacion limit 20) t) >= 20 then
    raise exception 'Una cotización admite hasta 20 adjuntos.' using errcode = '23514';
  end if;
  begin
    insert into public.cotizaciones_adjuntos (cotizacion_id, ruta, nombre, mime, bytes, subido_por)
    values (p_cotizacion, p_ruta, v_nombre, v_mime, v_bytes::integer, v_yo)
    returning * into a;
  exception when unique_violation then
    raise exception 'Ese archivo ya está adjunto.' using errcode = '23505';
  end;
  return jsonb_build_object('id', a.id, 'ruta', a.ruta, 'nombre', a.nombre, 'mime', a.mime, 'bytes', a.bytes, 'creado_en', a.creado_en);
end $_$;


ALTER FUNCTION "public"."cotizacion_adjuntar"("p_cotizacion" "uuid", "p_ruta" "text", "p_nombre" "text", "p_mime" "text", "p_bytes" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_adjuntar"("p_cotizacion" "uuid", "p_ruta" "text", "p_nombre" "text", "p_mime" "text", "p_bytes" integer) IS 'Registra un archivo ya subido al bucket cotizaciones como adjunto de la cotización. Pide ver (42501 «No tienes acceso…») y poder adjuntar (cotizacion_puede_adjuntar: 42501 «No tienes permiso para adjuntar…»). La ruta, <cotización>/<sha256>.<pdf|webp|jpg|png|docx>, en la carpeta de la cotización y existente en storage.objects; tipo y tamaño de su metadata si están (si no, los del cliente), concordantes con la extensión y de 1 byte a 25 MB; nombre de 1 a 200 sin barras (22023 con hint). Hasta 20 (23514); el mismo archivo dos veces, 23505. 4.27-1.';



CREATE OR REPLACE FUNCTION "public"."cotizacion_adjunto_quitar"("p_adjunto" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  a public.cotizaciones_adjuntos;
begin
  perform public.assert_activo();
  select * into a from public.cotizaciones_adjuntos x where x.id = p_adjunto;
  if not found or not public.puede_cotizacion(a.cotizacion_id, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  if not ((a.subido_por = v_yo and public.cotizacion_puede_adjuntar(a.cotizacion_id)) or public.tiene_permiso('cotizaciones.moderar')) then
    raise exception 'No puedes quitar este adjunto.' using errcode = '42501';
  end if;
  delete from public.cotizaciones_adjuntos x where x.id = a.id;
  if not found then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  -- A la cola de limpieza sólo si nadie más usa esa ruta (storage_refcount), con la gracia de siempre.
  perform public._encolar_para_limpiar('cotizaciones', array[a.ruta], false);
  return jsonb_build_object('resultado', 'quitado');
end $$;


ALTER FUNCTION "public"."cotizacion_adjunto_quitar"("p_adjunto" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_adjunto_quitar"("p_adjunto" "uuid") IS 'Quita un adjunto: quien lo subió y todavía puede adjuntar, o quien tiene cotizaciones.moderar (42501 «No puedes quitar este adjunto.»). Pide ver la cotización (42501, también si el adjunto no existe). Encola su ruta para limpiar si nadie más la usa. 4.27-1.';



CREATE OR REPLACE FUNCTION "public"."cotizacion_auditar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id text; v public.cotizaciones;
begin
  -- Un cambio sólo de los contadores de reportes o favoritos no es un cambio de la cotización.
  if tg_op = 'UPDATE' then
    v := new;
    v.actualizado_en := old.actualizado_en;
    v.reportes_count := old.reportes_count;
    v.favoritos_count := old.favoritos_count;
    if v is not distinct from old then return null; end if;
  end if;
  v_id := coalesce(to_jsonb(coalesce(new, old)) ->> 'id', '');
  insert into public.actividad (accion, actor_id, tabla, registro_id, antes, despues)
  values (tg_table_name || '.' || lower(tg_op), (select auth.uid()), tg_table_name, v_id,
          case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) - 'valores' - 'fuentes' - 'totales' - 'tipos_cambio' end,
          case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) - 'valores' - 'fuentes' - 'totales' - 'tipos_cambio' end);
  return null;
end;
$$;


ALTER FUNCTION "public"."cotizacion_auditar"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_auditar"() IS 'Trigger de auditoría de cotizaciones: la fila sin valores, fuentes, totales ni tipos_cambio (el snapshot lo ven las revisiones, recortado por nivel); no registra un cambio sólo de contadores. Pasos 4.10-1 y 4.10-3.';



CREATE OR REPLACE FUNCTION "public"."cotizacion_comentar"("p_cotizacion" "uuid", "p_padre" "uuid", "p_cuerpo" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_cuerpo text := btrim(p_cuerpo);
  v_cot uuid; v_abuelo uuid; v_raiz uuid;
  r public.cotizaciones_comentarios;
  v_nombre text;
begin
  perform public.assert_activo();
  if not public.puede_cotizacion(p_cotizacion, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  if v_cuerpo is null or char_length(v_cuerpo) not between 1 and 4000 then
    raise exception 'Escribe el comentario (hasta 4.000 caracteres).' using errcode = '22023', hint = 'cuerpo';
  end if;
  if p_padre is not null then
    select x.cotizacion_id, x.padre_id into v_cot, v_abuelo from public.cotizaciones_comentarios x where x.id = p_padre;
    if v_cot is distinct from p_cotizacion then
      raise exception 'Ese comentario ya no está.' using errcode = '22023', hint = 'padre';
    end if;
    -- Un nivel: la respuesta a una respuesta cuelga de su raíz. La raíz se toma `for share`: borrarla a la vez espera, y si ya se fue, no se responde.
    v_raiz := coalesce(v_abuelo, p_padre);
    perform 1 from public.cotizaciones_comentarios x where x.id = v_raiz for share;
    if not found then
      raise exception 'Ese comentario ya no está.' using errcode = '22023', hint = 'padre';
    end if;
  end if;
  insert into public.cotizaciones_comentarios (cotizacion_id, usuario_id, padre_id, cuerpo)
  values (p_cotizacion, v_yo, v_raiz, v_cuerpo)
  returning * into r;
  select p.nombre into v_nombre from public.perfiles p where p.id = v_yo;
  return public._comentario_item(r.id, r.usuario_id, v_nombre, r.cuerpo, r.eliminado_en, r.creado_en, r.actualizado_en, v_yo);
end $$;


ALTER FUNCTION "public"."cotizacion_comentar"("p_cotizacion" "uuid", "p_padre" "uuid", "p_cuerpo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_comentar"("p_cotizacion" "uuid", "p_padre" "uuid", "p_cuerpo" "text") IS 'Comenta una cotización o responde un comentario (p_padre). Pide cotizaciones.ver (42501). El cuerpo, sin espacios a los lados, de 1 a 4.000 caracteres (22023, hint cuerpo). Un padre de otra cotización o que ya no está: 22023, hint padre; la respuesta a una respuesta cuelga de su raíz (un nivel). Devuelve el comentario como lo lee cotizacion_comentarios. 4.27-1.';



CREATE OR REPLACE FUNCTION "public"."cotizacion_comentario_borrar"("p_comentario" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_cot uuid; v_padre uuid;
  v_raiz public.cotizaciones_comentarios;
  r public.cotizaciones_comentarios;
  v_ajeno boolean; v_res text;
begin
  perform public.assert_activo();
  select x.cotizacion_id, x.padre_id into v_cot, v_padre from public.cotizaciones_comentarios x where x.id = p_comentario;
  if v_cot is null or not public.puede_cotizacion(v_cot, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  -- La raíz antes que la respuesta: si se va la última respuesta de una raíz eliminada, la raíz también.
  if v_padre is not null then
    select * into v_raiz from public.cotizaciones_comentarios x where x.id = v_padre for update;
  end if;
  select * into r from public.cotizaciones_comentarios x where x.id = p_comentario for update;
  if not found or not public.puede_cotizacion(r.cotizacion_id, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  v_ajeno := r.usuario_id is distinct from v_yo;
  if v_ajeno and not public.tiene_permiso('cotizaciones.moderar') then
    raise exception 'No puedes borrar este comentario.' using errcode = '42501';
  end if;
  if r.eliminado_en is not null then
    return jsonb_build_object('resultado', 'sin_cambios');
  end if;
  perform public._exigir_version(r.actualizado_en, p_actualizado_en_esperado,
                                 'Alguien cambió este comentario mientras lo mirabas. Recarga e intenta de nuevo.');
  if r.padre_id is null and exists (select 1 from public.cotizaciones_comentarios x where x.padre_id = r.id) then
    update public.cotizaciones_comentarios x set eliminado_en = now(), cuerpo = '' where x.id = r.id;
    v_res := 'eliminado';
  else
    delete from public.cotizaciones_comentarios x where x.id = r.id;
    v_res := 'borrado';
    if r.padre_id is not null and v_raiz.eliminado_en is not null
       and not exists (select 1 from public.cotizaciones_comentarios x where x.padre_id = v_raiz.id) then
      delete from public.cotizaciones_comentarios x where x.id = v_raiz.id;
    end if;
  end if;
  -- El de otra persona queda en la actividad, sin el texto.
  if v_ajeno then
    perform public.registrar_actividad('cotizacion.comentario_moderado', 'cotizaciones', r.cotizacion_id::text, null, null,
                                       jsonb_build_object('comentario', r.id, 'autor', r.usuario_id));
  end if;
  return jsonb_build_object('resultado', v_res);
end $$;


ALTER FUNCTION "public"."cotizacion_comentario_borrar"("p_comentario" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_comentario_borrar"("p_comentario" "uuid", "p_actualizado_en_esperado" timestamp with time zone) IS 'Borra un comentario: el autor, o quien tiene cotizaciones.moderar (42501 «No puedes borrar este comentario.»), con la versión (PT409). Pide ver la cotización (42501, también si no existe). Una respuesta o una raíz sin respuestas se quitan (borrado); una raíz con respuestas queda eliminada sin texto (eliminado) y se va con su última respuesta; una ya eliminada: sin_cambios. El de otra persona deja cotizacion.comentario_moderado en la actividad, sin el texto. 4.27-1.';



CREATE OR REPLACE FUNCTION "public"."cotizacion_comentario_editar"("p_comentario" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cuerpo" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_cuerpo text := btrim(p_cuerpo);
  v_cot uuid;
  r public.cotizaciones_comentarios;
  v_nombre text;
begin
  perform public.assert_activo();
  -- Ver antes de tomar la fila, y otra vez con la fila tomada.
  select x.cotizacion_id into v_cot from public.cotizaciones_comentarios x where x.id = p_comentario;
  if v_cot is null or not public.puede_cotizacion(v_cot, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  select * into r from public.cotizaciones_comentarios x where x.id = p_comentario for update;
  if not found or not public.puede_cotizacion(r.cotizacion_id, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  if r.usuario_id is distinct from v_yo or r.eliminado_en is not null then
    raise exception 'Sólo quien escribió el comentario puede editarlo.' using errcode = '42501';
  end if;
  perform public._exigir_version(r.actualizado_en, p_actualizado_en_esperado,
                                 'Alguien cambió este comentario mientras lo editabas. Recarga e intenta de nuevo.');
  if v_cuerpo is null or char_length(v_cuerpo) not between 1 and 4000 then
    raise exception 'Escribe el comentario (hasta 4.000 caracteres).' using errcode = '22023', hint = 'cuerpo';
  end if;
  if v_cuerpo is distinct from r.cuerpo then
    update public.cotizaciones_comentarios x set cuerpo = v_cuerpo where x.id = r.id returning * into r;
  end if;
  select p.nombre into v_nombre from public.perfiles p where p.id = r.usuario_id;
  return public._comentario_item(r.id, r.usuario_id, v_nombre, r.cuerpo, r.eliminado_en, r.creado_en, r.actualizado_en, v_yo);
end $$;


ALTER FUNCTION "public"."cotizacion_comentario_editar"("p_comentario" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cuerpo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_comentario_editar"("p_comentario" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cuerpo" "text") IS 'Edita el texto de un comentario propio y vivo, con su versión (actualizado_en: PT409 si cambió). Pide ver la cotización (42501, también si no existe); otra persona, aun con moderar: 42501. Devuelve el comentario como lo lee cotizacion_comentarios (editado). 4.27-1.';



CREATE OR REPLACE FUNCTION "public"."cotizacion_comentario_respuestas"("p_comentario" "uuid", "p_despues_en" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_despues_id" "uuid" DEFAULT NULL::"uuid", "p_tope" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_n int := public._acotar_pagina(p_tope, 20, 50);
  v_cot uuid; v_padre uuid;
  v_filas jsonb; v_hay boolean;
begin
  perform public.assert_activo();
  select x.cotizacion_id, x.padre_id into v_cot, v_padre from public.cotizaciones_comentarios x where x.id = p_comentario;
  -- Un comentario inexistente, una respuesta o uno de una cotización que no se ve: lo mismo.
  if v_cot is null or v_padre is not null or not public.puede_cotizacion(v_cot, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  if (p_despues_en is null) <> (p_despues_id is null) then
    raise exception 'El cursor de la página está incompleto.' using errcode = '22023', hint = 'cursor';
  end if;
  -- Por cotizaciones_comentarios_respuestas_idx.
  if p_despues_en is null then
    select coalesce(jsonb_agg(public._comentario_item(y.id, y.usuario_id, q.nombre, y.cuerpo, y.eliminado_en, y.creado_en, y.actualizado_en, v_yo)
                              order by y.creado_en, y.id), '[]'::jsonb),
           coalesce(count(*) > v_n, false)
      into v_filas, v_hay
      from (select z.id, z.usuario_id, z.cuerpo, z.eliminado_en, z.creado_en, z.actualizado_en from public.cotizaciones_comentarios z
             where z.padre_id = p_comentario order by z.creado_en, z.id limit v_n + 1) y
      left join public.perfiles q on q.id = y.usuario_id;
  else
    select coalesce(jsonb_agg(public._comentario_item(y.id, y.usuario_id, q.nombre, y.cuerpo, y.eliminado_en, y.creado_en, y.actualizado_en, v_yo)
                              order by y.creado_en, y.id), '[]'::jsonb),
           coalesce(count(*) > v_n, false)
      into v_filas, v_hay
      from (select z.id, z.usuario_id, z.cuerpo, z.eliminado_en, z.creado_en, z.actualizado_en from public.cotizaciones_comentarios z
             where z.padre_id = p_comentario and (z.creado_en, z.id) > (p_despues_en, p_despues_id)
             order by z.creado_en, z.id limit v_n + 1) y
      left join public.perfiles q on q.id = y.usuario_id;
  end if;
  if v_hay then v_filas := v_filas - v_n; end if;
  return jsonb_build_object('respuestas', v_filas, 'hay_mas', v_hay);
end $$;


ALTER FUNCTION "public"."cotizacion_comentario_respuestas"("p_comentario" "uuid", "p_despues_en" timestamp with time zone, "p_despues_id" "uuid", "p_tope" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_comentario_respuestas"("p_comentario" "uuid", "p_despues_en" timestamp with time zone, "p_despues_id" "uuid", "p_tope" integer) IS 'Las respuestas de un comentario raíz después del cursor (creado_en, id), en orden de llegada (p_tope, 20 por defecto, 50 como mucho). Pide ver su cotización; un comentario inexistente, una respuesta o uno que no se ve dan el mismo 42501. {respuestas, hay_mas}. 4.27-1.';



CREATE OR REPLACE FUNCTION "public"."cotizacion_comentarios"("p_cotizacion" "uuid", "p_antes_en" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_antes_id" "uuid" DEFAULT NULL::"uuid", "p_tope" integer DEFAULT NULL::integer, "p_primeros" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_n int := public._acotar_pagina(p_tope, 20, 50);
  v_r int := public._acotar_pagina(p_primeros, 20, 50);
  v_filas jsonb; v_hay boolean;
begin
  perform public.assert_activo();
  if not public.puede_cotizacion(p_cotizacion, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  if (p_antes_en is null) <> (p_antes_id is null) then
    raise exception 'El cursor de la página está incompleto.' using errcode = '22023', hint = 'cursor';
  end if;
  -- Las raíces por cotizaciones_comentarios_raices_idx; las respuestas de cada una por cotizaciones_comentarios_respuestas_idx (primeras + 1).
  if p_antes_en is null then
    select coalesce(jsonb_agg(public._comentario_item(r.id, r.usuario_id, p.nombre, r.cuerpo, r.eliminado_en, r.creado_en, r.actualizado_en, v_yo)
                              || jsonb_build_object('respuestas', case when jsonb_array_length(h.a) > v_r then h.a - v_r else h.a end,
                                                    'hay_mas_respuestas', jsonb_array_length(h.a) > v_r)
                              order by r.creado_en desc, r.id desc), '[]'::jsonb),
           coalesce(count(*) > v_n, false)
      into v_filas, v_hay
      from (select x.id, x.usuario_id, x.cuerpo, x.eliminado_en, x.creado_en, x.actualizado_en from public.cotizaciones_comentarios x
             where x.cotizacion_id = p_cotizacion and x.padre_id is null
             order by x.creado_en desc, x.id desc limit v_n + 1) r
      left join public.perfiles p on p.id = r.usuario_id
      cross join lateral (
        select coalesce(jsonb_agg(public._comentario_item(y.id, y.usuario_id, q.nombre, y.cuerpo, y.eliminado_en, y.creado_en, y.actualizado_en, v_yo)
                                  order by y.creado_en, y.id), '[]'::jsonb) as a
          from (select z.id, z.usuario_id, z.cuerpo, z.eliminado_en, z.creado_en, z.actualizado_en from public.cotizaciones_comentarios z
                 where z.padre_id = r.id order by z.creado_en, z.id limit v_r + 1) y
          left join public.perfiles q on q.id = y.usuario_id) h;
  else
    select coalesce(jsonb_agg(public._comentario_item(r.id, r.usuario_id, p.nombre, r.cuerpo, r.eliminado_en, r.creado_en, r.actualizado_en, v_yo)
                              || jsonb_build_object('respuestas', case when jsonb_array_length(h.a) > v_r then h.a - v_r else h.a end,
                                                    'hay_mas_respuestas', jsonb_array_length(h.a) > v_r)
                              order by r.creado_en desc, r.id desc), '[]'::jsonb),
           coalesce(count(*) > v_n, false)
      into v_filas, v_hay
      from (select x.id, x.usuario_id, x.cuerpo, x.eliminado_en, x.creado_en, x.actualizado_en from public.cotizaciones_comentarios x
             where x.cotizacion_id = p_cotizacion and x.padre_id is null and (x.creado_en, x.id) < (p_antes_en, p_antes_id)
             order by x.creado_en desc, x.id desc limit v_n + 1) r
      left join public.perfiles p on p.id = r.usuario_id
      cross join lateral (
        select coalesce(jsonb_agg(public._comentario_item(y.id, y.usuario_id, q.nombre, y.cuerpo, y.eliminado_en, y.creado_en, y.actualizado_en, v_yo)
                                  order by y.creado_en, y.id), '[]'::jsonb) as a
          from (select z.id, z.usuario_id, z.cuerpo, z.eliminado_en, z.creado_en, z.actualizado_en from public.cotizaciones_comentarios z
                 where z.padre_id = r.id order by z.creado_en, z.id limit v_r + 1) y
          left join public.perfiles q on q.id = y.usuario_id) h;
  end if;
  -- La de más no viaja: es sólo el aviso de que hay otra página.
  if v_hay then v_filas := v_filas - v_n; end if;
  return jsonb_build_object('comentarios', v_filas, 'hay_mas', v_hay,
                            'puede_moderar', public.tiene_permiso('cotizaciones.moderar'));
end $$;


ALTER FUNCTION "public"."cotizacion_comentarios"("p_cotizacion" "uuid", "p_antes_en" timestamp with time zone, "p_antes_id" "uuid", "p_tope" integer, "p_primeros" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_comentarios"("p_cotizacion" "uuid", "p_antes_en" timestamp with time zone, "p_antes_id" "uuid", "p_tope" integer, "p_primeros" integer) IS 'Una página de comentarios raíz de una cotización, de la más nueva a la más vieja (p_tope, 20 por defecto, 50 como mucho), cada una con sus primeras p_primeros respuestas en orden de llegada (20, hasta 50) y hay_mas_respuestas. El cursor es (creado_en, id) de la última raíz de la página anterior. Pide cotizaciones.ver; sin ella, o inexistente o en la papelera, 42501. {comentarios, hay_mas, puede_moderar}. 4.27-1.';



CREATE OR REPLACE FUNCTION "public"."cotizacion_contadores"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_table_name = 'cotizaciones_reportes' then
    update public.cotizaciones set reportes_count = (select count(*) from public.cotizaciones_reportes r where r.cotizacion_id = coalesce(new.cotizacion_id, old.cotizacion_id)) where id = coalesce(new.cotizacion_id, old.cotizacion_id);
  else
    update public.cotizaciones set favoritos_count = (select count(*) from public.cotizaciones_favoritos r where r.cotizacion_id = coalesce(new.cotizacion_id, old.cotizacion_id)) where id = coalesce(new.cotizacion_id, old.cotizacion_id);
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."cotizacion_contadores"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cotizacion_crear"("p_id" "uuid", "p_origen" "uuid", "p_lead" "uuid", "p_entradas" "jsonb", "p_abierta" "text", "p_vehiculo" "uuid" DEFAULT NULL::"uuid", "p_vehiculo_nuevo" "jsonb" DEFAULT NULL::"jsonb", "p_modo_tc" "text" DEFAULT NULL::"text", "p_clase" "public"."clase_cotizacion" DEFAULT 'preventa'::"public"."clase_cotizacion", "p_con_la_abierta" boolean DEFAULT false, "p_ver_total_bs" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  c_uuid constant text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
  v_yo uuid := (select auth.uid());
  c public.cotizaciones;
  a record;
  v_formula uuid; v_uso uuid; v_vuelta int := 0; v_version int;
  v_ab_formula uuid; v_ab_en timestamptz;
  v_veh uuid := p_vehiculo;
  v_obligatorio boolean;
  v_modo jsonb;
  v_visibles text[]; v_editables jsonb; v_ctx jsonb;
  v_k text; v_opc text;
  v_res jsonb;
  v_total_base numeric;
  v_constraint text;
  v_ids uuid[]; v_tomadas uuid[];
begin
  perform public.assert_activo();
  if p_id is null or p_origen is null then
    raise exception 'Faltan el identificador y el origen de la cotización.' using errcode = '22023';
  end if;
  perform public.assert_permiso('cotizaciones.crear', p_origen);
  -- Cotizar pide también ver: con sólo `crear` la hoja no tiene nada que mostrar (4-32). Después de `crear`: quien no cotiza ahí sigue recibiendo ese permiso en el error.
  perform public.assert_permiso('cotizaciones.ver', p_origen);
  -- D2: la hoja que se abrió. La firma la base (`cotizacion_hoja()`): trae la versión de la fórmula y la hora de la apertura, y no se puede inventar (4-27).
  if p_abierta is null then
    raise exception 'Falta la hoja que abriste: ábrela de nuevo.' using errcode = '22023', hint = 'abierta';
  end if;
  if p_clase = 'final' then
    perform public.assert_permiso('cotizaciones.final.gestionar', p_origen);
  end if;

  -- El intento: dos llamadas con el mismo id se ordenan acá (la segunda espera a que la primera confirme). Sólo una cotización MÍA, de este origen y viva se devuelve; un id ajeno
  -- no se mira (sería una sonda barata de ids): sigue y choca con la clave en el `insert`.
  perform pg_advisory_xact_lock(hashtextextended('cotizacion_crear:' || p_id::text, 0));
  select * into c from public.cotizaciones x where x.id = p_id and x.creado_por = v_yo and x.origen_id = p_origen and x.eliminado_en is null;
  if found then
    return public._cotizacion_respuesta(c) || jsonb_build_object('repetido', true);
  end if;

  -- La hoja abierta: su firma, su versión y su hora. Después del intento: un reintento vuelve lo guardado aunque la clave haya rotado o la hoja sea vieja.
  select l.formula_id, l.abierta_en into v_ab_formula, v_ab_en from public._cotizacion_abierta_leer(p_abierta, p_origen) l;

  -- 4.25-1b, C1.1: una final sin vehículo, antes de mirar el lead (el mismo error que abajo con el ajuste en «sí»).
  if p_clase = 'final' and p_vehiculo is null and p_vehiculo_nuevo is null then
    raise exception 'Elige el vehículo de la cotización.' using errcode = '22023', hint = 'vehiculo';
  end if;

  -- El lead (comprobar, bloquear y volver a comprobar: nadie bloquea un lead que no ve).
  if p_lead is null then
    raise exception 'Elige el lead de la cotización.' using errcode = '22023', hint = 'lead';
  end if;
  if not public.puede_lead(p_lead, 'leads.ver') then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;
  if p_clase = 'final' then
    -- 4.25-1b, una final mira sin candado lo que mira marcar (C1): el lead en la cartera con leads.editar (P2 a) y, con un vehículo del inventario, que lo
    -- vea (antes que nada que delate su final, su vínculo o sus preventas) y, en la ayudante, otra final activa (P7 a), las preventas que no puede mandar a la
    -- papelera (P3 a) y el vínculo de otro lead (P4 a). Después toma el lead como marcar (no key update); una preventa, como siempre (key share).
    if not public.puede_actuar_lead(p_lead, 'leads.editar') then
      raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
    end if;
    if p_vehiculo is not null and p_vehiculo_nuevo is null then
      if not public.puede_vehiculo(p_vehiculo, 'vehiculos.ver') then
        raise exception 'No tienes acceso a este vehículo.' using errcode = '42501';
      end if;
      v_ids := array(select z.id from public.cotizaciones z where z.vehiculo_id = p_vehiculo and z.eliminado_en is null order by z.id);
      perform public._final_crear_mirar(p_vehiculo, p_lead, v_ids);
    end if;
    perform 1 from public.leads l where l.id = p_lead and l.eliminado_en is null for no key update;
  else
    perform 1 from public.leads l where l.id = p_lead and l.eliminado_en is null for key share;
  end if;
  if not found or not public.puede_lead(p_lead, 'leads.ver') then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;

  -- El vehículo.
  if p_vehiculo is not null and p_vehiculo_nuevo is not null then
    raise exception 'Elige un vehículo del inventario o carga uno a mano, no los dos.' using errcode = '22023', hint = 'vehiculo';
  end if;
  select coalesce((select e.vehiculo_obligatorio_al_cotizar from public.ajustes_empresa e where e.id = 1), true) into v_obligatorio;
  if p_vehiculo_nuevo is not null then
    if jsonb_typeof(p_vehiculo_nuevo) <> 'object' or (p_vehiculo_nuevo - array['id', 'datos', 'consulta']) <> '{}'::jsonb
       or coalesce(p_vehiculo_nuevo ->> 'id', '') !~ c_uuid
       or (p_vehiculo_nuevo ? 'consulta' and coalesce(p_vehiculo_nuevo ->> 'consulta', '') !~ c_uuid)
       or (p_vehiculo_nuevo ? 'datos' and jsonb_typeof(p_vehiculo_nuevo -> 'datos') <> 'object') then
      raise exception 'El vehículo a mano lleva su identificador y sus datos.' using errcode = '22023', hint = 'vehiculo';
    end if;
    v_veh := (p_vehiculo_nuevo ->> 'id')::uuid;
    -- En su propia sentencia y antes de armar: `_cotizacion_armar()` es STABLE y ve lo que esta transacción ya escribió.
    perform public.vehiculo_crear(v_veh, p_origen, coalesce(p_vehiculo_nuevo -> 'datos', '{}'::jsonb), (p_vehiculo_nuevo ->> 'consulta')::uuid);
  elsif p_vehiculo is not null then
    perform public._cotizacion_vehiculo(p_vehiculo);
  elsif v_obligatorio then
    raise exception 'Elige el vehículo de la cotización.' using errcode = '22023', hint = 'vehiculo';
  end if;

  -- La fórmula publicada, `for share` por su id: si publicaron mientras esperábamos, READ COMMITTED descarta la fila que ya se archivó y se vuelve a leer la nueva.
  loop
    v_vuelta := v_vuelta + 1;
    select f.id into v_formula from public.formulas f where f.origen_id = p_origen and f.estado = 'publicada';
    if v_formula is null then
      perform public._motor_fallar('origen_sin_formula', null, 'Este origen no tiene una fórmula publicada.');
    end if;
    perform 1 from public.formulas f where f.id = v_formula and f.estado = 'publicada' for share;
    exit when found;
    if v_vuelta >= 3 then
      raise exception 'La fórmula cambió mientras cotizabas. Vuelve a intentarlo.' using errcode = 'PT409';
    end if;
  end loop;

  -- D2: la hoja se abrió sobre otra versión que la publicada. Sin «Guardar con la N», se avisa y no se guarda; con ella, se usa esa versión (publicada o archivada de este origen, y reciente).
  -- «Con la abierta» vale siempre dentro de las 24 h de la apertura (4-27): con la versión vigente sólo cambia algo si una tarifa cambió desde entonces, y la hora ya no la elige el cliente.
  v_uso := v_formula;
  if v_ab_formula is distinct from v_formula then
    select f.version into v_version from public.formulas f where f.id = v_formula;
    if not p_con_la_abierta then
      raise exception 'Se publicó la versión % de la hoja mientras cotizabas.', v_version using errcode = 'PT409', detail = 'desactualizada', hint = 'formula';
    end if;
    perform public._cotizacion_abierta(p_origen, v_ab_formula, v_ab_en);
    -- `for share`, como la publicada: archivada ya no cambia, pero el candado ordena esta alta con quien la borre (un origen que se elimina).
    perform 1 from public.formulas f where f.id = v_ab_formula and f.estado in ('publicada', 'archivada') for share;
    if not found then
      raise exception 'La versión de la hoja que abriste ya no está disponible: ábrela de nuevo.' using errcode = '22023', detail = 'abierta_no_disponible', hint = 'abierta';
    end if;
    v_uso := v_ab_formula;
  elsif p_con_la_abierta then
    perform public._cotizacion_abierta(p_origen, v_ab_formula, v_ab_en);
  end if;

  select * into a from public._cotizacion_armar(p_entradas, null, p_origen, v_veh, v_uso, v_ab_en, p_con_la_abierta);
  if a.formula_id is distinct from v_uso then
    raise exception 'La fórmula cambió mientras cotizabas. Vuelve a intentarlo.' using errcode = 'PT409';
  end if;
  -- D2: algún tipo de cambio que la hoja usa cambió desde que se abrió (ARMAR lo lee en una sola foto con los de hoy).
  if a.tc_cambiado and not p_con_la_abierta then
    raise exception 'Cambió un tipo de cambio de la hoja mientras cotizabas.' using errcode = 'PT409', detail = 'desactualizada', hint = 'tipo_cambio';
  end if;

  -- El modo de cambio: la clave de uno de los modos del diseño de esa versión, convertido a la forma del motor.
  v_modo := public._cotizacion_modo(a.formula_id, p_modo_tc);
  -- «Ver total Bs»: sólo si el diseño de esa versión lo ofrece (y nunca nulo).
  perform public._cotizacion_ver_total_bs(a.formula_id, p_ver_total_bs);

  -- Lo que se ve y lo que se edita (una sola lectura de los niveles) y la revisión de lo tipeado, la misma que hace `cotizacion_evaluar()`.
  select coalesce(array_agg(n.nodo), '{}'), coalesce(jsonb_object_agg(n.nodo, true) filter (where n.editar), '{}'::jsonb)
    into v_visibles, v_editables from public._nodos_visibles(a.formula_id) n;
  v_ctx := public._cotizacion_contexto(v_visibles, a.definicion, a.visibilidad);
  perform public._cotizacion_tipeado(a.definicion, a.entrada, v_modo, v_ctx -> 'ok');

  -- Un override de un nodo que no se ve y uno de un nodo que no existe: el mismo error (el primero por id, en bytes).
  select min(k collate "C") into v_k from jsonb_object_keys(a.entrada -> 'overrides') k where not (v_ctx -> 'ok') ? k;
  if v_k is not null then
    raise exception 'La hoja no tiene un nodo «%».', v_k using errcode = '22023', detail = 'nodo_inexistente', hint = v_k;
  end if;
  -- Un valor para un nodo que se ve y no se edita.
  select min(t.k collate "C") into v_k
    from (select jsonb_object_keys(a.entrada -> 'inputs') as k
          union all select jsonb_object_keys(a.entrada -> 'banderas')
          union all select jsonb_object_keys(a.entrada -> 'overrides')) t
   where not v_editables ? t.k;
  if v_k is null and a.entrada ? 'variante' then
    select n ->> 'id' into v_opc from jsonb_array_elements(a.definicion -> 'nodos') n where n ->> 'tipo' = 'opcion' limit 1;
    if v_opc is not null and not v_editables ? v_opc then v_k := v_opc; end if;
  end if;
  if v_k is not null then
    raise exception 'No puedes cambiar «%» en esta hoja.', v_k using errcode = '42501', detail = 'nodo_no_editable', hint = v_k;
  end if;

  -- El cálculo, entero (los nodos que quien llama no ve toman el valor de la fórmula y se guardan igual).
  v_res := public.evaluar_formula(a.definicion, a.params, a.entrada, v_modo);
  -- Lo que el motor descarta de un nodo visible no se guarda en silencio; el total tiene que tener valor, caber y estar en la moneda base: `_cotizacion_guardable()`.
  v_total_base := public._cotizacion_guardable(v_res, a.entrada -> 'overrides');

  -- 4.25-1b, una final (C2.4 y C3): después del cálculo, las vivas del vehículo en una pasada por id (el orden de marcar y de la papelera de cotizaciones);
  -- con todo tomado, otra vez la cartera y la ayudante, que relee el vínculo en una sentencia nueva (otro pudo escribirlo mientras se esperaba).
  if p_clase = 'final' then
    v_tomadas := array(select z.id from public.cotizaciones z where z.vehiculo_id = v_veh and z.eliminado_en is null order by z.id for no key update);
    if not public.puede_actuar_lead(p_lead, 'leads.editar') then
      raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
    end if;
    perform public._final_crear_mirar(v_veh, p_lead, v_tomadas);
  end if;

  begin
    insert into public.cotizaciones (id, origen_id, lead_id, vehiculo_id, creado_por, clase, formula_id, valores, fuentes, tipos_cambio, totales, total_base, modo_tc, ver_total_bs)
    values (p_id, p_origen, p_lead, v_veh, v_yo, p_clase, a.formula_id, v_res -> 'valores', coalesce(v_res -> 'fuentes', '{}'::jsonb), a.entrada -> 'tipos_cambio',
            v_res -> 'totales', v_total_base, p_modo_tc, p_ver_total_bs)
    returning * into c;
  exception when unique_violation then
    get stacked diagnostics v_constraint = constraint_name;
    if v_constraint = 'cotizaciones_pkey' then
      raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
    elsif v_constraint = 'cotizaciones_final_por_vehiculo' then
      raise exception 'Este vehículo ya tiene una cotización final activa.' using errcode = '23505', hint = 'vehiculo';
    end if;
    raise;
  end;
  -- 4.25-1b, C4: los efectos de marcar, con todo tomado (la cotización ya es final: el paso 2 no la toca). La respuesta no cambia.
  if p_clase = 'final' then
    perform public._final_aplicar(c, v_tomadas);
  end if;

  return public._cotizacion_respuesta(c, v_ctx) || jsonb_build_object('repetido', false);
end $_$;


ALTER FUNCTION "public"."cotizacion_crear"("p_id" "uuid", "p_origen" "uuid", "p_lead" "uuid", "p_entradas" "jsonb", "p_abierta" "text", "p_vehiculo" "uuid", "p_vehiculo_nuevo" "jsonb", "p_modo_tc" "text", "p_clase" "public"."clase_cotizacion", "p_con_la_abierta" boolean, "p_ver_total_bs" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_crear"("p_id" "uuid", "p_origen" "uuid", "p_lead" "uuid", "p_entradas" "jsonb", "p_abierta" "text", "p_vehiculo" "uuid", "p_vehiculo_nuevo" "jsonb", "p_modo_tc" "text", "p_clase" "public"."clase_cotizacion", "p_con_la_abierta" boolean, "p_ver_total_bs" boolean) IS 'Crea una cotización calculada en la base (evaluar_formula sobre la fórmula publicada del origen, o sobre la abierta con p_con_la_abierta) y devuelve lo que quien llama ve (_cotizacion_respuesta). Pide cotizaciones.crear y cotizaciones.ver. Idempotente por el id del intento. D2: PT409 desactualizada si la hoja que se abrió (p_abierta, la de cotizacion_hoja) ya no es la vigente. «Ver total Bs» (p_ver_total_bs, falso por omisión) sólo vale si el diseño de la versión que se usa lo ofrece (_cotizacion_ver_total_bs). Una final (4.25-1b) deja el estado de marcarla: mira sin candado (el lead en la cartera con leads.editar, ver el vehículo y, en _final_crear_mirar, otra final activa, las preventas que no puede mandar a la papelera y el vínculo de otro lead), toma lead (no key update) → vehículo → fórmula → las vivas del vehículo, vuelve a mirar y aplica _final_aplicar. docs/COTIZADOR.md › «Quién escribe una cotización y cómo (4.10-2)», «Cómo se guarda (4.10-3)» y «La hoja abierta (4.13-3a)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_encima"("p_id" "uuid", "p_anterior" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  c public.cotizaciones; ant public.cotizaciones; a record;
  v_formula uuid; v_vuelta int := 0; v_enc uuid; v_obligatorio boolean;
  v_lleva jsonb; v_modo_tc text; v_bs boolean; v_res jsonb; v_total_base numeric; v_constraint text; v_desc int;
begin
  perform public.assert_activo();
  if p_id is null or p_anterior is null then
    raise exception 'Faltan el identificador y la cotización anterior.' using errcode = '22023';
  end if;
  -- La anterior, antes que todo lo demás: una que no existe, está en la papelera o no se ve da el mismo error, con o sin permiso de cotizar y vea o no su lead.
  if not public.puede_cotizacion(p_anterior, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  select * into ant from public.cotizaciones x where x.id = p_anterior;
  perform public.assert_permiso('cotizaciones.crear', ant.origen_id);
  perform public.assert_permiso('cotizaciones.ver', ant.origen_id);
  if ant.lead_id is null then
    raise exception 'La cotización anterior no tiene lead: cotiza una nueva.' using errcode = '22023', hint = 'lead';
  end if;
  if not public.puede_lead(ant.lead_id, 'leads.ver') then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;

  -- El intento, como en `cotizacion_crear` (el mismo candado): una mía viva con ese id es la de este intento si es de esta anterior.
  perform pg_advisory_xact_lock(hashtextextended('cotizacion_crear:' || p_id::text, 0));
  select * into c from public.cotizaciones x where x.id = p_id and x.creado_por = v_yo and x.eliminado_en is null;
  if found then
    if c.cotizacion_padre_id is distinct from p_anterior then
      raise exception 'Ese intento ya se usó para otra cotización.' using errcode = '22023', detail = 'intento_reusado', hint = 'intento';
    end if;
    return public._cotizacion_respuesta(c) || jsonb_build_object('repetido', true);
  end if;

  -- La anterior `for share` (choca con guardarla y con mandarla a la papelera) y otra vez visible; se relee lo que quedó.
  perform 1 from public.cotizaciones x where x.id = p_anterior and x.eliminado_en is null for share;
  if not found or not public.puede_cotizacion(p_anterior, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  select * into ant from public.cotizaciones x where x.id = p_anterior;
  -- Una versión nueva viva por anterior (P3): de la que se ve, su id en el hint; de la que no, sólo que existe (P11).
  select x.id into v_enc from public.cotizaciones x where x.cotizacion_padre_id = p_anterior and x.eliminado_en is null limit 1;   -- cotizaciones_encima_unica
  if v_enc is not null and public.puede_cotizacion(v_enc, 'cotizaciones.ver') then
    raise exception 'Esta cotización ya tiene una versión nueva.' using errcode = 'PT409', detail = 'ya_tiene_encima', hint = v_enc::text;
  elsif v_enc is not null then
    raise exception 'Esta cotización ya tiene una versión nueva.' using errcode = 'PT409', detail = 'ya_tiene_encima';
  end if;

  -- El lead (bloquear y volver a mirar) y el vehículo de la anterior.
  perform 1 from public.leads l where l.id = ant.lead_id and l.eliminado_en is null for key share;
  if not found or not public.puede_lead(ant.lead_id, 'leads.ver') then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;
  if ant.vehiculo_id is not null then
    perform public._cotizacion_vehiculo(ant.vehiculo_id);
  else
    select coalesce((select e.vehiculo_obligatorio_al_cotizar from public.ajustes_empresa e where e.id = 1), true) into v_obligatorio;
    if v_obligatorio then
      raise exception 'Elige el vehículo de la cotización.' using errcode = '22023', hint = 'vehiculo';
    end if;
  end if;

  -- La publicada de hoy, `for share` (como en `cotizacion_crear`).
  loop
    v_vuelta := v_vuelta + 1;
    select f.id into v_formula from public.formulas f where f.origen_id = ant.origen_id and f.estado = 'publicada';
    if v_formula is null then
      perform public._motor_fallar('origen_sin_formula', null, 'Este origen no tiene una fórmula publicada.');
    end if;
    perform 1 from public.formulas f where f.id = v_formula and f.estado = 'publicada' for share;
    exit when found;
    if v_vuelta >= 3 then
      raise exception 'La fórmula cambió mientras cotizabas. Vuelve a intentarlo.' using errcode = 'PT409';
    end if;
  end loop;

  -- La versión y las tarifas de hoy, con lo que se lleva de la anterior (P2: también lo que quien llama no ve); el modo de la anterior si sigue (si no, el primero de hoy) y
  -- «Ver total Bs» si hoy se ofrece. Un override llevado que el motor descarta no falla (nadie lo mandó): cuenta en `descartados`.
  select * into a from public._cotizacion_armar('{}'::jsonb, null, ant.origen_id, ant.vehiculo_id, v_formula);
  v_lleva := public._cotizacion_lo_que_se_lleva(a.definicion, a.entrada, ant.valores, ant.fuentes);
  select coalesce((select m ->> 'clave' from jsonb_array_elements(coalesce(f.diseno -> 'cabecera' -> 'modos', '[]'::jsonb)) m where m ->> 'clave' = ant.modo_tc),
                  case when ant.modo_tc is not null then f.diseno -> 'cabecera' -> 'modos' -> 0 ->> 'clave' end),
         ant.ver_total_bs and coalesce((f.diseno -> 'cabecera' ->> 'ver_total_bs')::boolean, false)
    into v_modo_tc, v_bs from public.formulas f where f.id = v_formula;
  v_res := public.evaluar_formula(a.definicion, a.params, v_lleva, public._cotizacion_modo(v_formula, v_modo_tc));
  v_total_base := public._cotizacion_guardable(v_res, '{}'::jsonb);
  v_desc := public._cotizacion_descartados((select f.definicion from public.formulas f where f.id = ant.formula_id),
                                           coalesce(array(select n.nodo from public._nodos_visibles(ant.formula_id) n), '{}'), ant.valores, ant.fuentes, v_lleva, v_res);

  begin
    insert into public.cotizaciones (id, origen_id, lead_id, vehiculo_id, creado_por, clase, formula_id, valores, fuentes, tipos_cambio, totales, total_base, modo_tc, ver_total_bs,
                                     titulo, notas, cotizacion_padre_id, version)
    values (p_id, ant.origen_id, ant.lead_id, ant.vehiculo_id, v_yo, 'preventa', v_formula, v_res -> 'valores', coalesce(v_res -> 'fuentes', '{}'::jsonb), a.entrada -> 'tipos_cambio',
            v_res -> 'totales', v_total_base, v_modo_tc, v_bs, ant.titulo, ant.notas, p_anterior, ant.version + 1)
    returning * into c;
  exception when unique_violation then
    get stacked diagnostics v_constraint = constraint_name;
    if v_constraint = 'cotizaciones_pkey' then
      raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
    elsif v_constraint = 'cotizaciones_encima_unica' then
      raise exception 'Esta cotización ya tiene una versión nueva.' using errcode = 'PT409', detail = 'ya_tiene_encima';
    end if;
    raise;
  end;

  return public._cotizacion_respuesta(c) || jsonb_build_object('repetido', false, 'descartados', v_desc);
end $$;


ALTER FUNCTION "public"."cotizacion_encima"("p_id" "uuid", "p_anterior" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_encima"("p_id" "uuid", "p_anterior" "uuid") IS 'Cotizar encima (N+1): crea en el acto una cotización nueva, preventa, sobre la anterior (cotizacion_padre_id, version + 1, su número, su lead y su vehículo) con la publicada y las tarifas de hoy y lo tipeado de la anterior en los nodos que siguen (también lo que quien llama no ve; no se le devuelve). La anterior no cambia; una versión nueva viva por anterior (PT409 ya_tiene_encima). Pide ver la anterior y su lead, cotizaciones.crear y cotizaciones.ver del origen. Idempotente por el id del intento. Devuelve la respuesta de cotizacion_leer, repetido y descartados (lo que quien llama ve y se pierde). docs/COTIZADOR.md › «La hoja de una guardada y cotizar encima (4.15-2)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_evaluar"("p_entradas" "jsonb", "p_cotizacion" "uuid" DEFAULT NULL::"uuid", "p_origen" "uuid" DEFAULT NULL::"uuid", "p_vehiculo" "uuid" DEFAULT NULL::"uuid", "p_modo" "jsonb" DEFAULT NULL::"jsonb", "p_modo_tc" "text" DEFAULT NULL::"text", "p_abierta" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  a record;
  v_visibles text[]; v_editables jsonb; v_ctx jsonb; v_ok jsonb;
  v_cfg boolean;
  v_ent jsonb; v_ov_ocultos text[];
  v_modo jsonb := p_modo;
  v_formula uuid; v_abierta_en timestamptz; v_publicada uuid;
  v_res jsonb;
begin
  -- La hoja abierta es de una hoja nueva (por origen): una cotización ya trae su versión y sus tipos de cambio.
  if p_abierta is not null and p_cotizacion is not null then
    perform public.assert_activo();
    perform public._motor_fallar('llamada_invalida', 'p_abierta', 'Una cotización ya trae su versión de la hoja y sus tipos de cambio.');
  end if;
  -- Por origen se cotiza con `crear` y `ver` del origen (4-32), antes de leer la hoja abierta y de mirar nada más.
  if p_cotizacion is null and p_origen is not null then
    perform public.assert_permiso('cotizaciones.crear', p_origen);
    perform public.assert_permiso('cotizaciones.ver', p_origen);
    if p_abierta is not null then
      select l.formula_id, l.abierta_en into v_formula, v_abierta_en from public._cotizacion_abierta_leer(p_abierta, p_origen) l;
      select f.id into v_publicada from public.formulas f where f.origen_id = p_origen and f.estado = 'publicada';       -- formulas_publicada_unica
      -- Una versión que ya no es la publicada: ¿todavía se podría guardar con ella? Si no, «abierta_vencida» y la hoja pide recargar.
      if v_formula is distinct from v_publicada then
        perform public._cotizacion_abierta(p_origen, v_formula, v_abierta_en);
      end if;
    end if;
  end if;
  -- Con la hoja abierta (4-28): la versión Y las tarifas de la apertura, lo mismo que verá D2 al guardar «con la N»; sin ella, la publicada y las tarifas de hoy.
  if v_formula is not null then
    select * into a from public._cotizacion_armar(p_entradas, p_cotizacion, p_origen, p_vehiculo, v_formula, v_abierta_en, true);
  else
    select * into a from public._cotizacion_armar(p_entradas, p_cotizacion, p_origen, p_vehiculo);
  end if;
  -- El modo por su clave (de esa versión) se vuelve la forma del motor antes de revisar lo tipeado.
  if p_modo_tc is not null then
    if p_modo is not null then
      perform public._motor_fallar('llamada_invalida', null, 'Pide el modo por su clave o completo, no los dos.');
    end if;
    v_modo := public._cotizacion_modo(a.formula_id, p_modo_tc);
  end if;
  v_cfg := public.tiene_permiso('cotizaciones.configurar', a.origen_id);
  select coalesce(array_agg(n.nodo), '{}'), coalesce(jsonb_object_agg(n.nodo, true) filter (where n.editar), '{}'::jsonb) into v_visibles, v_editables from public._nodos_visibles(a.formula_id) n;
  v_ctx := public._cotizacion_contexto(v_visibles, a.definicion, a.visibilidad);
  v_ok := v_ctx -> 'ok';
  v_ent := a.entrada;

  -- Lo tipeado (la forma, la fórmula inválida, inputs, banderas y variante que se ven): `_cotizacion_tipeado()`, la misma que revisa `cotizacion_crear()`.
  v_ov_ocultos := public._cotizacion_tipeado(a.definicion, a.entrada, v_modo, v_ok, p_cotizacion is not null);
  -- Un override de un nodo que existe y no se ve se quita antes del motor; vuelve como `nodo_inexistente` (abajo).
  if cardinality(v_ov_ocultos) > 0 then
    v_ent := jsonb_set(a.entrada, '{overrides}', (a.entrada -> 'overrides') - v_ov_ocultos);
  end if;
  -- Con una cotización, lo que quien llama no ve o no edita es lo GUARDADO (D7: guardar conserva lo que quien guarda no ve), y un valor distinto para un nodo que se ve y no se edita es un
  -- error. Con un origen no hay nada guardado.
  if p_cotizacion is not null then
    v_ent := public._cotizacion_conservar(a.definicion, v_ent, v_editables, a.guardado);
  end if;

  -- El modo: quien no configura sólo elige uno de los del diseño de esa versión (convertido a la forma del motor).
  if v_modo is not null and not v_cfg and not exists (
       select 1 from public.formulas f, jsonb_array_elements(coalesce(f.diseno -> 'cabecera' -> 'modos', '[]'::jsonb)) m
        where f.id = a.formula_id
          and jsonb_build_object('buckets', coalesce((select jsonb_object_agg(b ->> 'bucket', b ->> 'nodo') from jsonb_array_elements(m -> 'buckets') b), '{}'::jsonb),
                                 'total_en', m ->> 'total_en') = v_modo) then
    perform public._motor_fallar('modo_invalido', null, 'El modo no es uno de los que ofrece la hoja.');
  end if;

  v_res := public.evaluar_formula(a.definicion, a.params, v_ent, v_modo);
  v_res := public._cotizacion_recorte(v_res, v_ctx);

  -- Los overrides que se quitaron vuelven como inexistentes, entre los inexistentes y en su orden (por id, en bytes), después de los descartados de nodos que existen: es lo que el
  -- motor habría dicho si el nodo no estuviera. (Se agregan después de recortar: el recorte descarta, con razón, todo lo de un nodo que existe y no se ve.)
  if cardinality(v_ov_ocultos) > 0 then
    v_res := jsonb_set(v_res, '{overrides_descartados}', (
      select coalesce(jsonb_agg(x.e order by x.grupo, x.id collate "C", x.ord), '[]'::jsonb)
        from (select d.e, case when d.e ->> 'motivo' = 'nodo_inexistente' then 1 else 0 end as grupo, d.e ->> 'id' as id, d.ord
                from jsonb_array_elements(coalesce(v_res -> 'overrides_descartados', '[]'::jsonb)) with ordinality d (e, ord)
              union all
              select jsonb_build_object('id', k, 'motivo', 'nodo_inexistente'), 1, k, 0 from unnest(v_ov_ocultos) k) x));
  end if;
  return v_res;
end $$;


ALTER FUNCTION "public"."cotizacion_evaluar"("p_entradas" "jsonb", "p_cotizacion" "uuid", "p_origen" "uuid", "p_vehiculo" "uuid", "p_modo" "jsonb", "p_modo_tc" "text", "p_abierta" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_evaluar"("p_entradas" "jsonb", "p_cotizacion" "uuid", "p_origen" "uuid", "p_vehiculo" "uuid", "p_modo" "jsonb", "p_modo_tc" "text", "p_abierta" "text") IS 'Calcula una hoja y devuelve sólo lo que quien llama ve. El modo, completo (p_modo, el editor de la fórmula) o por su clave (p_modo_tc, la hoja), no los dos. Por origen pide cotizaciones.crear y cotizaciones.ver; con p_abierta (la de cotizacion_hoja) calcula con la versión y las tarifas de esa apertura. docs/COTIZADOR.md › «En la base (4.06-2)» y «La hoja abierta (4.13-3a)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_favorito_poner"("p_cotizacion" "uuid", "p_valor" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int;
begin
  perform public.assert_activo();
  if not public.puede_cotizacion(p_cotizacion, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  if p_valor is null then
    raise exception 'Falta decir si va o no.' using errcode = '22023', hint = 'valor';
  end if;
  if p_valor then
    insert into public.cotizaciones_favoritos (cotizacion_id, usuario_id) values (p_cotizacion, (select auth.uid())) on conflict do nothing;
  else
    delete from public.cotizaciones_favoritos f where f.cotizacion_id = p_cotizacion and f.usuario_id = (select auth.uid());
  end if;
  get diagnostics n = row_count;
  return jsonb_build_object('resultado', case when n = 0 then 'sin_cambios' when p_valor then 'puesto' else 'quitado' end,
                            'valor', p_valor);
end $$;


ALTER FUNCTION "public"."cotizacion_favorito_poner"("p_cotizacion" "uuid", "p_valor" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_favorito_poner"("p_cotizacion" "uuid", "p_valor" boolean) IS 'Pone o quita la marca de favorita de quien llama en una cotización. Pide cotizaciones.ver (42501); p_valor nulo, 22023. No mueve la versión. {resultado: puesto | quitado | sin_cambios, valor}. 4.27-1.';



CREATE OR REPLACE FUNCTION "public"."cotizacion_guardar"("p_id" "uuid", "p_intento" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_entradas" "jsonb", "p_modo_tc" "text", "p_titulo" "text", "p_notas" "text", "p_vehiculo" "uuid", "p_ver_total_bs" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  c0 record;
  c public.cotizaciones;
  r public.cotizaciones_revisiones;
  a record;
  v_ids uuid[]; v_v uuid;
  v_huella text;
  v_titulo text := nullif(btrim(p_titulo), '');
  v_notas text := nullif(btrim(p_notas), '');
  v_nuevo_veh uuid;
  v_modo jsonb;
  v_visibles text[]; v_editables jsonb; v_ctx jsonb;
  v_k text; v_ent jsonb; v_res jsonb; v_total_base numeric;
begin
  perform public.assert_activo();
  if p_id is null or p_intento is null then
    raise exception 'Faltan el identificador de la cotización y el del guardado.' using errcode = '22023';
  end if;

  -- Sin candado: sólo para saber qué vehículo hay que tomar antes que la cotización.
  select x.origen_id, x.clase, x.vehiculo_id into c0 from public.cotizaciones x where x.id = p_id and x.eliminado_en is null;
  if not found then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  -- Quien no la ve recibe lo mismo que si no existiera, antes del vehículo, del candado, del intento, de la versión y del título (4-34).
  if not public._cotizacion_puede_guardar(p_id, c0.clase, c0.origen_id) then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;

  -- El vehículo: sólo cambia el de una preventa y nunca se quita. Lo que se pide se valida antes de tomar nada.
  if p_vehiculo is distinct from c0.vehiculo_id then
    if c0.clase = 'final' then
      raise exception 'Una cotización final no cambia de vehículo.' using errcode = '22023', hint = 'vehiculo';
    end if;
    if p_vehiculo is null then
      raise exception 'No se quita el vehículo de una cotización: elige otro.' using errcode = '22023', hint = 'vehiculo';
    end if;
    if not public.puede_vehiculo(p_vehiculo, 'vehiculos.ver') then
      raise exception 'No tienes acceso a este vehículo.' using errcode = '42501';
    end if;
    -- El actual y el nuevo, en orden de id (como la papelera por lotes), antes que la cotización.
    v_ids := array(select distinct x from unnest(array[c0.vehiculo_id, p_vehiculo]) x where x is not null order by 1);
    foreach v_v in array v_ids loop
      perform 1 from public.vehiculos v where v.id = v_v for key share;
    end loop;
    perform 1 from public.vehiculos v where v.id = p_vehiculo and v.eliminado_en is null;
    if not found or not public.puede_vehiculo(p_vehiculo, 'vehiculos.ver') then
      raise exception 'No tienes acceso a este vehículo.' using errcode = '42501';
    end if;
  end if;

  select * into c from public.cotizaciones x where x.id = p_id and x.eliminado_en is null for no key update;
  if not found then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  -- Si mientras esperaba le cambiaron el vehículo, los candados de arriba son de otro vehículo. No hace falta una comprobación aparte: cualquier cambio de la fila mueve su versión
  -- (`cotizacion_version()`), así que quien la tenía en pantalla recibe el conflicto de la versión más abajo, y el repetido de un intento ya guardado no mira candados.

  -- El permiso con la fila tomada (la clase o el alcance pudieron cambiar mientras esperaba).
  if not public._cotizacion_puede_guardar(p_id, c.clase, c.origen_id) then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;

  -- El intento: la misma persona con los mismos datos recibe lo guardado; otros datos, un error claro.
  v_huella := md5(jsonb_build_object('version', to_char(p_actualizado_en_esperado at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'), 'entradas', p_entradas, 'modo', p_modo_tc,
                                     'titulo', p_titulo, 'notas', p_notas, 'vehiculo', p_vehiculo, 'ver_total_bs', p_ver_total_bs)::text);
  select * into r from public.cotizaciones_revisiones x where x.cotizacion_id = p_id and x.intento = p_intento;
  if found then
    if r.usuario_id is distinct from v_yo or r.huella is distinct from v_huella then
      raise exception 'Ese guardado ya se hizo con otros datos. Recarga la cotización.' using errcode = '22023', detail = 'intento_reusado', hint = 'intento';
    end if;
    return public._cotizacion_respuesta(c) || jsonb_build_object('repetido', true);
  end if;

  -- La versión.
  if p_actualizado_en_esperado is null then
    perform public._exigir_version(c.actualizado_en, null, '');
  elsif c.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._conflicto_de_edicion('cotizaciones', c.id, c.actualizado_en, 'esta cotización');
  end if;

  -- Título y notas.
  if char_length(v_titulo) > 120 then
    raise exception 'El título tiene como máximo 120 caracteres.' using errcode = '22023', hint = 'titulo';
  end if;
  if char_length(v_notas) > 2000 then
    raise exception 'Las notas tienen como máximo 2.000 caracteres.' using errcode = '22023', hint = 'notas';
  end if;

  -- SU versión de la fórmula, SUS tipos de cambio y (si cambia) el vehículo nuevo; el modo de esa versión.
  v_nuevo_veh := case when p_vehiculo is distinct from c.vehiculo_id then p_vehiculo end;
  select * into a from public._cotizacion_armar(p_entradas, p_id, null, v_nuevo_veh);
  v_modo := public._cotizacion_modo(c.formula_id, p_modo_tc);
  -- «Ver total Bs»: contra el diseño de SU versión, como el modo (una final también lo cambia).
  perform public._cotizacion_ver_total_bs(c.formula_id, p_ver_total_bs);

  -- Lo que se ve y lo que se edita, y la revisión de lo tipeado (la misma de `cotizacion_evaluar()` y `cotizacion_crear()`).
  select coalesce(array_agg(n.nodo), '{}'), coalesce(jsonb_object_agg(n.nodo, true) filter (where n.editar), '{}'::jsonb) into v_visibles, v_editables from public._nodos_visibles(a.formula_id) n;
  v_ctx := public._cotizacion_contexto(v_visibles, a.definicion, a.visibilidad);
  perform public._cotizacion_tipeado(a.definicion, a.entrada, v_modo, v_ctx -> 'ok', true);
  -- Un override de un nodo que no se ve y uno de un nodo que no existe: el mismo error (el primero por id, en bytes).
  select min(k collate "C") into v_k from jsonb_object_keys(a.entrada -> 'overrides') k where not (v_ctx -> 'ok') ? k;
  if v_k is not null then
    raise exception 'La hoja no tiene un nodo «%».', v_k using errcode = '22023', detail = 'nodo_inexistente', hint = v_k;
  end if;

  -- Lo que no se edita sale de lo guardado; el motor; y lo guardable.
  v_ent := public._cotizacion_conservar(a.definicion, a.entrada, v_editables, a.guardado);
  v_res := public.evaluar_formula(a.definicion, a.params, v_ent, v_modo);
  v_total_base := public._cotizacion_guardable(v_res, a.entrada -> 'overrides');

  -- Nada cambió: no se escribe (ni la versión ni la revisión).
  if c.valores is not distinct from (v_res -> 'valores') and c.fuentes is not distinct from coalesce(v_res -> 'fuentes', '{}'::jsonb) and c.totales is not distinct from (v_res -> 'totales')
     and c.total_base = v_total_base and c.modo_tc is not distinct from p_modo_tc and c.titulo is not distinct from v_titulo and c.notas is not distinct from v_notas
     and c.vehiculo_id is not distinct from p_vehiculo and c.ver_total_bs is not distinct from p_ver_total_bs then
    return public._cotizacion_respuesta(c, v_ctx) || jsonb_build_object('repetido', false);
  end if;

  perform set_config('importadora.guardado', jsonb_build_object('intento', p_intento, 'huella', v_huella)::text, true);
  update public.cotizaciones x
     set valores = v_res -> 'valores', fuentes = coalesce(v_res -> 'fuentes', '{}'::jsonb), totales = v_res -> 'totales', total_base = v_total_base,
         modo_tc = p_modo_tc, titulo = v_titulo, notas = v_notas, vehiculo_id = p_vehiculo, ver_total_bs = p_ver_total_bs
   where x.id = p_id
   returning * into c;
  perform set_config('importadora.guardado', '', true);

  return public._cotizacion_respuesta(c, v_ctx) || jsonb_build_object('repetido', false);
end $$;


ALTER FUNCTION "public"."cotizacion_guardar"("p_id" "uuid", "p_intento" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_entradas" "jsonb", "p_modo_tc" "text", "p_titulo" "text", "p_notas" "text", "p_vehiculo" "uuid", "p_ver_total_bs" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_guardar"("p_id" "uuid", "p_intento" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_entradas" "jsonb", "p_modo_tc" "text", "p_titulo" "text", "p_notas" "text", "p_vehiculo" "uuid", "p_ver_total_bs" boolean) IS 'Guarda una cotización calculada en la base con SU versión de la fórmula y SUS tipos de cambio; lo que quien guarda no ve ni edita se conserva de lo guardado. Versión esperada (PT409), intento idempotente y devuelve lo que quien llama ve (_cotizacion_respuesta) con repetido. «Ver total Bs» (p_ver_total_bs, sin valor por omisión: el estado entero de lo que se edita) se valida contra el diseño de SU versión (_cotizacion_ver_total_bs). docs/COTIZADOR.md › «Cómo se guarda (4.10-3)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_hoja"("p_origen" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_nombre text; v_formula uuid; v_obligatorio boolean;
begin
  -- Los permisos, antes de mirar si el origen existe: con cualquier uuid, quien no cotiza ahí recibe el mismo 42501. Cotizar pide ver (4-32): con sólo `crear` la hoja iba vacía.
  perform public.assert_permiso('cotizaciones.crear', p_origen);
  perform public.assert_permiso('cotizaciones.ver', p_origen);
  if p_origen is null then
    raise exception 'Falta el origen.' using errcode = '22023';
  end if;
  select o.nombre into v_nombre from public.origenes o where o.id = p_origen;
  if v_nombre is null then
    raise exception 'No encontramos ese origen.' using errcode = '22023';
  end if;
  select x.id into v_formula from public.formulas x where x.origen_id = p_origen and x.estado = 'publicada';   -- formulas_publicada_unica
  if v_formula is null then
    return jsonb_build_object('estado', 'sin_publicar', 'origen', jsonb_build_object('id', p_origen, 'nombre', v_nombre),
                              'puede_configurar', public.tiene_permiso('cotizaciones.configurar', p_origen));
  end if;
  select a.vehiculo_obligatorio_al_cotizar into v_obligatorio from public.ajustes_empresa a where a.id = 1;
  -- `abierta` es lo que `cotizacion_crear()` y `cotizacion_evaluar()` reciben como `p_abierta`: la versión y la hora, firmadas para esta persona y este origen (4-27 y 4-28).
  return jsonb_build_object('estado', 'lista', 'origen', jsonb_build_object('id', p_origen, 'nombre', v_nombre),
                            'abierta_en', now(), 'abierta', public._cotizacion_abierta_firmar(p_origen, v_formula, now()), 'vehiculo_obligatorio', coalesce(v_obligatorio, true))
         || public._cotizacion_hoja(v_formula, p_origen);
end $$;


ALTER FUNCTION "public"."cotizacion_hoja"("p_origen" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_hoja"("p_origen" "uuid") IS 'La lectura que abre la hoja de cotizar de un origen: el diseño publicado recortado al nivel de quien llama, la versión de la fórmula, la hora y la hoja abierta firmada (p_abierta de cotizacion_crear y cotizacion_evaluar) o «sin_publicar». Con cotizaciones.crear y cotizaciones.ver del origen. docs/COTIZADOR.md › «La lectura que abre la hoja (4.13-1)» y «La hoja abierta (4.13-3a)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_hoja_guardada"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.cotizaciones; v_edita boolean; v_nombre text; v_pub record; v_vence date; v_hoy date;
begin
  perform public.assert_activo();
  -- Una que no existe, una en la papelera y una que no se ve dan el mismo error que `cotizacion_leer`.
  if not public.puede_cotizacion(p_id, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  select * into c from public.cotizaciones x where x.id = p_id;
  -- Quién guarda decide también qué celdas se editan (no `_nodos_visibles()`, que da «editar» con `crear`).
  v_edita := public._cotizacion_puede_guardar(c.id, c.clase, c.origen_id);
  select o.nombre into v_nombre from public.origenes o where o.id = c.origen_id;
  select x.id, x.version into v_pub from public.formulas x where x.origen_id = c.origen_id and x.estado = 'publicada';   -- formulas_publicada_unica
  -- La vigencia, por día en la zona de la empresa (docs/GLOSARIO.md › «Vencida»): vale hasta el día de `creado_en` + `vigencia_dias`, entero.
  select (c.creado_en at time zone e.zona_horaria)::date + e.vigencia_dias, (now() at time zone e.zona_horaria)::date
    into v_vence, v_hoy from public.ajustes_empresa e where e.id = 1;
  return public._cotizacion_respuesta(c)
      || public._cotizacion_hoja(c.formula_id, c.origen_id, v_edita)
      || jsonb_build_object(
           'estado', 'lista',
           'origen', jsonb_build_object('id', c.origen_id, 'nombre', v_nombre),
           'puede_guardar', v_edita,
           'publicada', case when v_pub.id is not null then jsonb_build_object('id', v_pub.id, 'version', v_pub.version) end,
           'vence_el', v_vence,
           'vencida', v_vence < v_hoy)
      || public._cotizacion_cadena(c, v_pub.id);
end $$;


ALTER FUNCTION "public"."cotizacion_hoja_guardada"("p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_hoja_guardada"("p_id" "uuid") IS 'La hoja de una cotización guardada, para quien la ve: la fila y el snapshot recortados (como cotizacion_leer), el diseño de SU versión (como cotizacion_hoja, con lo editable decidido por _cotizacion_puede_guardar), puede_guardar, el origen, la publicada de hoy, vence_el y vencida (por día, en la zona de la empresa), anterior, encima y puede_cotizar_encima. Lo que no existe, está en la papelera o no se ve da el 42501 de cotizacion_leer. docs/COTIZADOR.md › «La hoja de una guardada y cotizar encima (4.15-2)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_leer"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.cotizaciones;
begin
  perform public.assert_activo();
  -- Una que no existe, una en la papelera y una que no se ve dan el mismo error.
  if not public.puede_cotizacion(p_id, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  select * into c from public.cotizaciones x where x.id = p_id;
  return public._cotizacion_respuesta(c);
end $$;


ALTER FUNCTION "public"."cotizacion_leer"("p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_leer"("p_id" "uuid") IS 'Una cotización con su snapshot recortado por nivel (_nodos_visibles de SU versión de la fórmula): siempre el total y lo aparte; los subtotales por grupo sólo si se ve el grupo entero. docs/COTIZADOR.md › «En la base (4.10-1)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_marcar_final"("p_cotizacion" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.cotizaciones; c2 public.cotizaciones; v_vuelta int := 0; v_tomadas uuid[]; v_lead_del_vehiculo uuid;
begin
  perform public.assert_activo();
  loop
    v_vuelta := v_vuelta + 1;
    -- C1. Sin candado: lo que no se ve da lo mismo que lo inexistente y no espera nada.
    select * into c from public.cotizaciones x where x.id = p_cotizacion and x.eliminado_en is null;
    if not found or not public.puede_cotizacion(p_cotizacion, 'cotizaciones.ver') then
      raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
    end if;
    if not public.tiene_permiso('cotizaciones.final.gestionar', c.origen_id) then
      raise exception 'No tienes permiso para marcar la final.' using errcode = '42501';
    end if;
    if c.vehiculo_id is null then
      raise exception 'Una final exige vehículo vinculado.' using errcode = '23514';
    end if;
    if c.lead_id is null then
      raise exception 'Esta cotización no tiene lead: no se puede marcar final.' using errcode = '23514';
    end if;
    if exists (select 1 from public.leads l where l.id = c.lead_id and l.eliminado_en is not null) then
      raise exception 'El lead de esta cotización está en la papelera. Restáuralo antes de marcarla final.' using errcode = '23514';
    end if;
    if not public.puede_actuar_lead(c.lead_id, 'leads.editar') then
      raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
    end if;
    if exists (select 1 from public.cotizaciones z
                where z.vehiculo_id = c.vehiculo_id and z.eliminado_en is null and z.id <> c.id
                  and not (public.puede_cotizacion(z.id, 'cotizaciones.ver')
                           and case when z.clase = 'final' then public.tiene_permiso('cotizaciones.final.gestionar', z.origen_id)
                                    else public.puede_cotizacion(z.id, 'cotizaciones.editar') or public.tiene_permiso('cotizaciones.moderar') end)) then
      raise exception 'Este vehículo tiene preventas que no puedes mandar a la papelera. Pídeselo a quien las cotizó o a quien modera.' using errcode = '42501';
    end if;

    begin
      -- C2. (1) el lead, (2) el vehículo, (3) la cotización y todas las vivas del vehículo en una pasada por id. Lo que ya no está vivo: otra vuelta.
      perform 1 from public.leads l where l.id = c.lead_id and l.eliminado_en is null for no key update;
      if not found then raise exception using errcode = 'PF425'; end if;
      perform 1 from public.vehiculos v where v.id = c.vehiculo_id and v.eliminado_en is null for key share;
      if not found then raise exception using errcode = 'PF425'; end if;
      v_tomadas := array(select z.id from public.cotizaciones z
                          where (z.vehiculo_id = c.vehiculo_id or z.id = c.id) and z.eliminado_en is null order by z.id for no key update);
      -- C3. Lo que cambió mientras se esperaba (guardar le cambió el vehículo o el lead, o se fue a la papelera): otra vuelta.
      select * into c2 from public.cotizaciones x where x.id = c.id;
      if c2.eliminado_en is not null or c2.vehiculo_id is distinct from c.vehiculo_id or c2.lead_id is distinct from c.lead_id
         or not (c.id = any (v_tomadas)) then
        raise exception using errcode = 'PF425';
      end if;
      c := c2;
      -- Con todo tomado, sobre lo confirmado: (i) el lead, (ii) ver, (iii) P3 a, (iv) el vínculo, leído ahora (otro marcar pudo escribirlo).
      if not public.puede_actuar_lead(c.lead_id, 'leads.editar') then
        raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
      end if;
      if not public.puede_cotizacion(c.id, 'cotizaciones.ver') then
        raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
      end if;
      if exists (select 1 from public.cotizaciones z
                  where z.id = any (v_tomadas) and z.id <> c.id
                    and not (public.puede_cotizacion(z.id, 'cotizaciones.ver')
                             and case when z.clase = 'final' then public.tiene_permiso('cotizaciones.final.gestionar', z.origen_id)
                                      else public.puede_cotizacion(z.id, 'cotizaciones.editar') or public.tiene_permiso('cotizaciones.moderar') end)) then
        raise exception 'Este vehículo tiene preventas que no puedes mandar a la papelera. Pídeselo a quien las cotizó o a quien modera.' using errcode = '42501';
      end if;
      select v.lead_id into v_lead_del_vehiculo from public.vehiculos v where v.id = c.vehiculo_id;
      if v_lead_del_vehiculo is not null and v_lead_del_vehiculo <> c.lead_id then
        raise exception 'Este vehículo está vinculado a otro lead. Desvincúlalo antes de marcar la final.' using errcode = '23514';
      end if;
      -- C5. Los efectos, con todo tomado.
      perform public._final_aplicar(c, v_tomadas);
      return;
    exception when sqlstate 'PF425' then
      if v_vuelta >= 3 then
        raise exception 'La cotización cambió mientras la marcabas. Vuelve a intentarlo.' using errcode = 'PT409';
      end if;
    end;
  end loop;
end;
$$;


ALTER FUNCTION "public"."cotizacion_marcar_final"("p_cotizacion" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_marcar_final"("p_cotizacion" "uuid") IS 'Marca una cotización como final (4.25-1): mira sin candado (ver, cotizaciones.final.gestionar, vehículo, lead vivo y en la cartera con leads.editar, que pueda mandar las demás del vehículo a la papelera); toma lead (no key update) → vehículo (key share) → la cotización y las vivas del vehículo en una pasada por id; si algo cambió, otra vuelta (a la tercera, PT409); con todo tomado vuelve a mirar y el vínculo (otro lead: 23514); los efectos, en _final_aplicar.';



CREATE OR REPLACE FUNCTION "public"."cotizacion_moderar"("p_cotizacion" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_estado" "public"."estado_cotizacion") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c record;
  v_puede_final boolean;
begin
  perform public.assert_activo();
  -- Ver antes de tomar la fila, y otra vez con la fila tomada.
  if not public.puede_cotizacion(p_cotizacion, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  -- Moderar es global: se mira antes de tomar la fila, para no dejarla tomada a quien no puede. `final.gestionar` es del origen: después.
  if not public.tiene_permiso('cotizaciones.moderar') then
    raise exception 'No tienes permiso para moderar esta cotización.' using errcode = '42501';
  end if;
  select x.id, x.clase, x.origen_id, x.estado, x.actualizado_en, x.reportes_count into c
    from public.cotizaciones x where x.id = p_cotizacion and x.eliminado_en is null for no key update;
  if not found or not public.puede_cotizacion(p_cotizacion, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  v_puede_final := c.clase <> 'final' or public.tiene_permiso('cotizaciones.final.gestionar', c.origen_id);
  if not public.tiene_permiso('cotizaciones.moderar') or not v_puede_final then
    raise exception 'No tienes permiso para moderar esta cotización.' using errcode = '42501';
  end if;
  if p_estado is null or p_estado = 'reportada' then
    raise exception 'Elige invalidarla o descartar sus reportes.' using errcode = '22023', hint = 'estado';
  end if;
  perform public._exigir_version(c.actualizado_en, p_actualizado_en_esperado,
                                 'Alguien cambió esta cotización mientras la mirabas. Recarga e intenta de nuevo.');
  -- Nada que hacer: el mismo estado y, si se pide activa, sin reportes que descartar.
  if p_estado = c.estado and (p_estado <> 'activa' or c.reportes_count = 0) then
    return jsonb_build_object('resultado', 'sin_cambios', 'estado', c.estado, 'actualizado_en', c.actualizado_en);
  end if;
  if p_estado = 'activa' then
    delete from public.cotizaciones_reportes r where r.cotizacion_id = c.id;
  end if;
  if p_estado <> c.estado then
    update public.cotizaciones x set estado = p_estado where x.id = c.id;
  end if;
  perform public.registrar_actividad('cotizacion.moderada', 'cotizaciones', c.id::text, null,
                                     jsonb_build_object('estado', p_estado, 'reportes', c.reportes_count));
  return (select jsonb_build_object('resultado', 'moderada', 'estado', x.estado, 'actualizado_en', x.actualizado_en)
            from public.cotizaciones x where x.id = c.id);
end $$;


ALTER FUNCTION "public"."cotizacion_moderar"("p_cotizacion" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_estado" "public"."estado_cotizacion") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_moderar"("p_cotizacion" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_estado" "public"."estado_cotizacion") IS 'Modera una cotización: invalida (mueve la versión y conserva los reportes) o activa (descarta los reportes; la versión se mueve sólo si cambia el estado). Pide ver (42501, también si no existe o está en la papelera), cotizaciones.moderar y, en una final, cotizaciones.final.gestionar del origen (42501 «No tienes permiso para moderar…»); la versión (PT409); reportada no se pide (22023, hint estado). Deja cotizacion.moderada en la actividad. {resultado: moderada | sin_cambios, estado, actualizado_en}. 4.27-1.';



CREATE OR REPLACE FUNCTION "public"."cotizacion_puede_adjuntar"("p_cot" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce((
    select public._cotizacion_puede_guardar(c.id, c.clase, c.origen_id)
      from public.cotizaciones c
     where c.id = p_cot and c.eliminado_en is null
  ), false);
$$;


ALTER FUNCTION "public"."cotizacion_puede_adjuntar"("p_cot" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_puede_adjuntar"("p_cot" "uuid") IS 'Si quien llama puede adjuntar a esa cotización: lo que pide guardarla (preventa: cotizaciones.ver y cotizaciones.editar por su alcance; final: cotizaciones.ver y cotizaciones.final.gestionar del origen). Falso si no existe o está en la papelera; nunca nula. La llaman las policies de adjuntos y cotizacion_adjuntar (4.27-1, cierra 4-69).';



CREATE OR REPLACE FUNCTION "public"."cotizacion_reportar"("p_cotizacion" "uuid", "p_motivo" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_motivo text := btrim(p_motivo);
  v_nuevo boolean;
begin
  perform public.assert_activo();
  if not public.puede_cotizacion(p_cotizacion, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  if v_motivo is null or char_length(v_motivo) not between 1 and 500 then
    raise exception 'Cuéntanos qué está mal (hasta 500 caracteres).' using errcode = '22023', hint = 'motivo';
  end if;
  -- Uno por persona: el segundo cambia el motivo.
  insert into public.cotizaciones_reportes as r (cotizacion_id, usuario_id, motivo) values (p_cotizacion, v_yo, v_motivo)
  on conflict (cotizacion_id, usuario_id) do update set motivo = excluded.motivo where r.motivo is distinct from excluded.motivo
  returning (xmax = 0) into v_nuevo;
  return jsonb_build_object('resultado', case when v_nuevo is null then 'sin_cambios' when v_nuevo then 'reportada' else 'motivo_cambiado' end);
end $$;


ALTER FUNCTION "public"."cotizacion_reportar"("p_cotizacion" "uuid", "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_reportar"("p_cotizacion" "uuid", "p_motivo" "text") IS 'Reporta una cotización con un motivo (1 a 500 caracteres; 22023, hint motivo). Pide cotizaciones.ver (42501). Uno por persona: el segundo cambia el motivo. No cambia el estado ni la versión. {resultado: reportada | motivo_cambiado | sin_cambios}. 4.27-1.';



CREATE OR REPLACE FUNCTION "public"."cotizacion_reporte_retirar"("p_cotizacion" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_activo();
  if not public.puede_cotizacion(p_cotizacion, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  -- La cotización antes que el reporte, como moderar: el trigger de contadores la toma de todos modos al borrar.
  perform 1 from public.cotizaciones x where x.id = p_cotizacion and x.eliminado_en is null for no key update;
  delete from public.cotizaciones_reportes r where r.cotizacion_id = p_cotizacion and r.usuario_id = (select auth.uid());
  return jsonb_build_object('resultado', case when found then 'retirado' else 'sin_cambios' end);
end $$;


ALTER FUNCTION "public"."cotizacion_reporte_retirar"("p_cotizacion" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_reporte_retirar"("p_cotizacion" "uuid") IS 'Retira el reporte propio de una cotización. Pide cotizaciones.ver (42501). {resultado: retirado | sin_cambios}. 4.27-1.';



CREATE OR REPLACE FUNCTION "public"."cotizacion_revision"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  d jsonb := '{}'::jsonb; k text; a jsonb := to_jsonb(old); b jsonb := to_jsonb(new);
  v_de jsonb; v_a jsonb; v_g jsonb; v_gde jsonb; v_ga jsonb;
begin
  for k in select jsonb_object_keys(b) loop
    if k in ('actualizado_en', 'reportes_count', 'favoritos_count') or a -> k is not distinct from b -> k then continue; end if;
    if k in ('valores', 'fuentes') and jsonb_typeof(a -> k) = 'object' and jsonb_typeof(b -> k) = 'object' then
      -- Sólo los nodos que cambiaron (`-> clave` da el jsonb null de un valor nulo y el SQL null de una clave que no está).
      select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) into v_de from jsonb_each(a -> k) e where (b -> k) -> e.key is distinct from e.value;
      select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) into v_a from jsonb_each(b -> k) e where (a -> k) -> e.key is distinct from e.value;
      d := d || jsonb_build_object(k, jsonb_build_object('de', v_de, 'a', v_a));
    elsif k = 'totales' and jsonb_typeof(a -> k) = 'object' and jsonb_typeof(b -> k) = 'object' then
      -- Las claves de primer nivel que cambiaron (menos `grupos`), y de `grupos` cada grupo entero que cambió.
      select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) into v_de from jsonb_each(a -> k) e where e.key <> 'grupos' and (b -> k) -> e.key is distinct from e.value;
      select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) into v_a from jsonb_each(b -> k) e where e.key <> 'grupos' and (a -> k) -> e.key is distinct from e.value;
      if jsonb_typeof(a -> k -> 'grupos') = 'object' and jsonb_typeof(b -> k -> 'grupos') = 'object' then
        select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) into v_gde from jsonb_each(a -> k -> 'grupos') e where (b -> k -> 'grupos') -> e.key is distinct from e.value;
        select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) into v_ga from jsonb_each(b -> k -> 'grupos') e where (a -> k -> 'grupos') -> e.key is distinct from e.value;
        if v_gde <> '{}'::jsonb then v_de := v_de || jsonb_build_object('grupos', v_gde); end if;
        if v_ga <> '{}'::jsonb then v_a := v_a || jsonb_build_object('grupos', v_ga); end if;
      elsif (a -> k -> 'grupos') is distinct from (b -> k -> 'grupos') then
        -- `grupos` de un solo lado (o que no es un objeto): entero, del lado donde está.
        if (a -> k) ? 'grupos' then v_de := v_de || jsonb_build_object('grupos', a -> k -> 'grupos'); end if;
        if (b -> k) ? 'grupos' then v_a := v_a || jsonb_build_object('grupos', b -> k -> 'grupos'); end if;
      end if;
      d := d || jsonb_build_object(k, jsonb_build_object('de', v_de, 'a', v_a));
    else
      d := d || jsonb_build_object(k, jsonb_build_object('de', a -> k, 'a', b -> k));
    end if;
  end loop;
  if d <> '{}'::jsonb then
    -- Lo deja `cotizacion_guardar()`; un ajuste que alguna vez se fijó en la sesión vuelve como texto vacío, no como nulo.
    v_g := nullif(current_setting('importadora.guardado', true), '')::jsonb;
    insert into public.cotizaciones_revisiones (cotizacion_id, usuario_id, diff, intento, huella)
    values (new.id, (select auth.uid()), d, (v_g ->> 'intento')::uuid, v_g ->> 'huella');
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."cotizacion_revision"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_revision"() IS 'Trigger de cotizaciones: una revisión por cambio, con el diff por columna ({de, a}; en valores y fuentes sólo los nodos que cambiaron; en totales, las claves y los grupos que cambiaron, cada grupo entero) y el intento y la huella de cotizacion_guardar. docs/COTIZADOR.md › «Cómo se guarda (4.10-3)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_revisiones"("p_cotizacion" "uuid", "p_antes" bigint DEFAULT NULL::bigint, "p_tamano" integer DEFAULT NULL::integer, "p_hasta" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_formula uuid; v_def jsonb; v_vis jsonb; v_visibles text[]; v_ctx jsonb; v_legibles text[];
  v_n int := public._acotar_pagina(p_tamano, 20, 100);
  v_filas jsonb; v_hay boolean;
  v_ancla bigint; v_tope bigint := p_antes;
begin
  perform public.assert_activo();
  if not public.puede_cotizacion(p_cotizacion, 'cotizaciones.ver') then
    raise exception 'No tienes acceso a esta cotización.' using errcode = '42501';
  end if;
  -- El ancla (cotizaciones_revisiones_cotizacion_creado_idx): la más nueva de ESTA cotización antes del instante. Sin ella no hay nada que leer.
  if p_hasta is not null then
    select x.id into v_ancla from public.cotizaciones_revisiones x
     where x.cotizacion_id = p_cotizacion and x.creado_en < p_hasta order by x.creado_en desc, x.id desc limit 1;
    if v_ancla is null then
      return jsonb_build_object('revisiones', '[]'::jsonb, 'hay_mas', false, 'siguiente', null,
                                'etiquetas', jsonb_build_object('nodos', '{}'::jsonb, 'grupos', '{}'::jsonb));
    end if;
    -- La página empieza en el ancla (inclusive) y, si llegó un cursor, en el menor de los dos.
    v_tope := least(coalesce(p_antes, v_ancla + 1), v_ancla + 1);
  end if;
  select c.formula_id into v_formula from public.cotizaciones c where c.id = p_cotizacion;
  select f.definicion, coalesce(f.visibilidad, '{}'::jsonb) into v_def, v_vis from public.formulas f where f.id = v_formula;
  v_visibles := coalesce(array(select n.nodo from public._nodos_visibles(v_formula) n), '{}');
  v_ctx := public._cotizacion_contexto(v_visibles, v_def, v_vis);
  v_legibles := coalesce(array(select a.attname::text from pg_attribute a
                                where a.attrelid = 'public.cotizaciones'::regclass and a.attnum > 0 and not a.attisdropped and has_column_privilege('authenticated', a.attrelid, a.attnum, 'select')), '{}');
  -- Una página y una de más, para saber si hay otra (cotizaciones_revisiones_cotizacion_idx). Con cursor y sin cursor son dos consultas.
  -- El autor, por la clave de `perfiles` (una fila por revisión de la página; `left join`: una revisión sin usuario sigue).
  if v_tope is null then
    select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'usuario_id', r.usuario_id, 'creado_en', r.creado_en,
                                                 'autor', case when r.usuario_id is not null then jsonb_build_object('id', r.usuario_id, 'nombre', nullif(btrim(p.nombre), '')) end,
                                                 'diff', public._cotizacion_diff_recortado(r.diff, v_ctx, v_legibles)) order by r.id desc), '[]'::jsonb),
           coalesce(count(*) > v_n, false)
      into v_filas, v_hay
      from (select x.id, x.usuario_id, x.creado_en, x.diff from public.cotizaciones_revisiones x where x.cotizacion_id = p_cotizacion order by x.id desc limit v_n + 1) r
      left join public.perfiles p on p.id = r.usuario_id;
  else
    select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'usuario_id', r.usuario_id, 'creado_en', r.creado_en,
                                                 'autor', case when r.usuario_id is not null then jsonb_build_object('id', r.usuario_id, 'nombre', nullif(btrim(p.nombre), '')) end,
                                                 'diff', public._cotizacion_diff_recortado(r.diff, v_ctx, v_legibles)) order by r.id desc), '[]'::jsonb),
           coalesce(count(*) > v_n, false)
      into v_filas, v_hay
      from (select x.id, x.usuario_id, x.creado_en, x.diff from public.cotizaciones_revisiones x where x.cotizacion_id = p_cotizacion and x.id < v_tope order by x.id desc limit v_n + 1) r
      left join public.perfiles p on p.id = r.usuario_id;
  end if;
  -- La de más no viaja: es sólo el aviso de que hay otra página.
  if v_hay then v_filas := v_filas - v_n; end if;
  -- Las etiquetas, de lo que ya viaja recortado en esta página.
  return jsonb_build_object('revisiones', v_filas, 'hay_mas', v_hay,
                            'siguiente', case when v_hay then (v_filas -> (jsonb_array_length(v_filas) - 1) ->> 'id')::bigint end,
                            'etiquetas', public._revision_etiquetas(v_def, v_filas));
end $$;


ALTER FUNCTION "public"."cotizacion_revisiones"("p_cotizacion" "uuid", "p_antes" bigint, "p_tamano" integer, "p_hasta" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_revisiones"("p_cotizacion" "uuid", "p_antes" bigint, "p_tamano" integer, "p_hasta" timestamp with time zone) IS 'Una página de revisiones de una cotización, de la más nueva a la más vieja, con cada diff recortado por nodo (la visibilidad de SU versión) y su autor ({id, nombre}); etiquetas de los nodos y grupos que nombran los diffs de la página. El cursor es el id de la última de la página anterior. Con p_hasta (un instante, exclusivo) empieza en la más nueva de esa cotización con creado_en < p_hasta, por cotizaciones_revisiones_cotizacion_creado_idx; sin ninguna, va vacía. Supone que el id crece con creado_en (4-95: los caminos sin versión pueden invertirlo dentro de una ventana). docs/COTIZADOR.md › «En la base (4.10-1)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_tabla"("p_tabla" "text", "p_cotizacion" "uuid" DEFAULT NULL::"uuid", "p_origen" "uuid" DEFAULT NULL::"uuid", "p_abierta" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_formula uuid; v_origen uuid; v_def jsonb; v_par jsonb; v_diseno jsonb; v_cfg boolean; v_visibles text[]; v_vis jsonb;
  v_tabla public.tablas_referencia; v_congelada jsonb; v_permitidas jsonb; v_filas jsonb; v_cols jsonb; v_hay boolean := false; v_nodos jsonb;
begin
  -- La versión (la de la cotización, la de la hoja abierta o la publicada) y la puerta. Sin publicada, el origen sigue siendo el pedido (no se cae a la compartida).
  v_formula := public._cotizacion_tabla_version(p_cotizacion, p_origen, p_abierta);
  v_origen := coalesce(p_origen, (select c.origen_id from public.cotizaciones c where c.id = p_cotizacion));
  select f.definicion, f.params, f.diseno into v_def, v_par, v_diseno from public.formulas f where f.id = v_formula;
  v_nodos := coalesce(v_def -> 'nodos', '[]'::jsonb);
  v_cfg := public.tiene_permiso('cotizaciones.configurar', v_origen);

  -- Las columnas que leen los nodos que quien llama ve (sin configurar). Si ninguno la lee, la tabla es como si no existiera.
  if not v_cfg then
    v_visibles := coalesce(array(select n.nodo from public._nodos_visibles(v_formula) n), '{}');
    v_vis := coalesce((select jsonb_object_agg(x, true) from unnest(v_visibles) x), '{}'::jsonb);
    select jsonb_object_agg(c, true) into v_permitidas from (
      select jsonb_object_keys(case when jsonb_typeof(n -> 'match') = 'object' then n -> 'match' else '{}'::jsonb end) as c
        from jsonb_array_elements(v_nodos) n where n ->> 'tipo' = 'tabla' and n ->> 'tabla' = p_tabla and v_vis ? (n ->> 'id')
      union select n ->> 'columna' from jsonb_array_elements(v_nodos) n where n ->> 'tabla' = p_tabla and v_vis ? (n ->> 'id') and (n ->> 'columna') is not null
      union select 'desde' from jsonb_array_elements(v_nodos) n where n ->> 'tabla' = p_tabla and v_vis ? (n ->> 'id') and (n ->> 'tipo' = 'tramo' or n ->> 'op' = 'depreciar')
      union select 'hasta' from jsonb_array_elements(v_nodos) n where n ->> 'tabla' = p_tabla and v_vis ? (n ->> 'id') and (n ->> 'tipo' = 'tramo' or n ->> 'op' = 'depreciar')
      -- La columna que etiqueta unos atajos que se ven.
      union select it ->> 'columna'
        from jsonb_array_elements(coalesce(v_diseno -> 'secciones', '[]'::jsonb)) s, jsonb_array_elements(coalesce(s -> 'items', '[]'::jsonb)) it,
             jsonb_array_elements(v_nodos) n
       where it ->> 'tipo' = 'atajos' and n ->> 'id' = it ->> 'nodo' and n ->> 'tabla' = p_tabla and v_vis ? (n ->> 'id') and (it ->> 'columna') is not null
    ) x where c is not null;
    if v_permitidas is null then
      raise exception 'No tienes acceso a esa tabla.' using errcode = '42501';
    end if;
  end if;

  -- La congelada de esa versión manda, aunque esté vacía; si no, la viva del origen y, si no hay una activa, la compartida.
  v_congelada := case when jsonb_typeof(v_par -> 'tablas') = 'object' and v_par -> 'tablas' ? p_tabla then v_par -> 'tablas' -> p_tabla end;
  select r.* into v_tabla from public.tablas_referencia r where r.origen_id = v_origen and r.clave = p_tabla and r.activa;
  if v_tabla.id is null then
    select r.* into v_tabla from public.tablas_referencia r where r.origen_id is null and r.clave = p_tabla and r.activa;
  end if;
  if v_congelada is null and v_tabla.id is null then
    raise exception 'No tienes acceso a esa tabla.' using errcode = '42501';
  end if;
  if v_congelada is not null and jsonb_typeof(v_congelada) = 'array' then
    v_filas := coalesce((select jsonb_agg(f.value order by f.ord) from jsonb_array_elements(v_congelada) with ordinality f (value, ord) where f.ord <= 1000), '[]'::jsonb);
    v_hay := jsonb_array_length(v_congelada) > 1000;
  else
    select coalesce(jsonb_agg(x.valores order by x.orden, x.id), '[]'::jsonb), coalesce(count(*) > 1000, false) into v_filas, v_hay
      from (select f.valores, f.orden, f.id from public.tablas_referencia_filas f where f.tabla_id = v_tabla.id and f.activa order by f.orden, f.id limit 1001) x;
    if v_hay then v_filas := v_filas - 1000; end if;
  end if;
  v_cols := coalesce(v_tabla.columnas, '[]'::jsonb);
  if not v_cfg then
    v_filas := coalesce((select jsonb_agg((select coalesce(jsonb_object_agg(e.key, e.value), '{}'::jsonb) from jsonb_each(case when jsonb_typeof(f.value) = 'object' then f.value else '{}'::jsonb end) e where v_permitidas ? e.key) order by f.ord)
                           from jsonb_array_elements(v_filas) with ordinality f (value, ord)), '[]'::jsonb);
    v_cols := coalesce((select jsonb_agg(c order by o) from jsonb_array_elements(v_cols) with ordinality t (c, o) where v_permitidas ? (c ->> 'clave')), '[]'::jsonb);
  end if;
  return jsonb_build_object('clave', p_tabla, 'nombre', coalesce(v_tabla.nombre, p_tabla), 'columnas', v_cols, 'filas', v_filas, 'hay_mas', v_hay, 'congelada', v_congelada is not null);
end $$;


ALTER FUNCTION "public"."cotizacion_tabla"("p_tabla" "text", "p_cotizacion" "uuid", "p_origen" "uuid", "p_abierta" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_tabla"("p_tabla" "text", "p_cotizacion" "uuid", "p_origen" "uuid", "p_abierta" "text") IS 'Una tabla de referencia con sólo las columnas que leen los nodos que quien llama ve (la entera, a quien configura el origen); la copia congelada de la versión manda. La versión es la de la cotización, la de la hoja abierta (p_abierta, por origen) o la publicada; por origen pide cotizaciones.crear y cotizaciones.ver. Sin acceso, el error de una tabla que no existe. docs/COTIZADOR.md › «En la base (4.10-1)» y «La hoja abierta (4.13-3a)».';



CREATE OR REPLACE FUNCTION "public"."cotizacion_tarjeta"("p_formula" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  fo public.formulas; v_pla public.plantillas_tarjeta; v_p jsonb; v_nodos jsonb; v_total text; v_ton jsonb; v_grupos jsonb; v_opcion jsonb;
  v_claves text[]; v_buckets text[];
begin
  perform public.assert_activo();
  select * into fo from public.formulas f where f.id = p_formula;
  -- La inexistencia y el borrador se deciden antes del permiso (`tiene_permiso` con un origen nulo da verdadero) y dan lo mismo que no tenerlo.
  if not found or fo.estado = 'borrador' then raise exception 'No tienes acceso a esa versión de la fórmula.' using errcode = '42501'; end if;
  if not public.tiene_permiso('cotizaciones.ver', fo.origen_id) then raise exception 'No tienes acceso a esa versión de la fórmula.' using errcode = '42501'; end if;

  -- La publicada del origen (plantillas_publicada_unica), validada contra ESTA versión; sin tonos: uno borrado cae al del grupo.
  select * into v_pla from public.plantillas_tarjeta p where p.origen_id = fo.origen_id and p.estado = 'publicada';
  if not found then return jsonb_build_object('estado', 'sin_plantilla'); end if;
  begin
    perform public.validar_plantilla(v_pla.definicion, fo.definicion, fo.diseno, fo.visibilidad, null);
  exception when sqlstate '22023' then
    return jsonb_build_object('estado', 'sin_plantilla');
  end;

  v_p := v_pla.definicion;
  v_nodos := coalesce((select jsonb_object_agg(n ->> 'id', n) from jsonb_array_elements(coalesce(fo.definicion -> 'nodos', '[]'::jsonb)) n), '{}'::jsonb);
  select n ->> 'id' into v_total from jsonb_array_elements(coalesce(fo.definicion -> 'nodos', '[]'::jsonb)) n where n ->> 'salida' = 'total' limit 1;
  select n into v_opcion from jsonb_array_elements(coalesce(fo.definicion -> 'nodos', '[]'::jsonb)) n where n ->> 'tipo' = 'opcion' limit 1;
  v_ton := coalesce((select jsonb_object_agg(t.clave, jsonb_build_object('clave', t.clave,
                                                    'claro', jsonb_build_object('fondo', t.claro_fondo, 'borde', t.claro_borde, 'tinta', t.claro_tinta),
                                                    'oscuro', jsonb_build_object('fondo', t.oscuro_fondo, 'borde', t.oscuro_borde, 'tinta', t.oscuro_tinta)))
                       from public.tonos t), '{}'::jsonb);
  v_grupos := public._tarjeta_grupos(v_p, fo.definicion, v_ton);
  v_claves := array(select distinct g ->> 'tono' from jsonb_array_elements(v_grupos) g where g ->> 'tono' is not null);
  v_buckets := array(select distinct g ->> 'bucket' from jsonb_array_elements(v_grupos) g where g ->> 'bucket' is not null);

  return jsonb_build_object(
    'estado', 'lista',
    'plantilla', jsonb_build_object('version', v_pla.version),
    'logo', v_p -> 'logo',
    'nota', v_p -> 'nota',
    'columnas', v_p -> 'columnas',
    'total', jsonb_build_object('nodo', v_total, 'etiqueta', v_p -> 'total' ->> 'etiqueta', 'leyenda', v_p -> 'total' ->> 'leyenda'),
    'secundarios', coalesce((select jsonb_agg(jsonb_build_object('nodo', x.s, 'etiqueta', coalesce(v_p -> 'etiquetas' ->> x.s, v_nodos -> x.s ->> 'etiqueta')) order by x.o)
                               from jsonb_array_elements_text(coalesce(fo.diseno -> 'tarjeta_total' -> 'secundarios', '[]'::jsonb)) with ordinality x (s, o)), '[]'::jsonb),
    'grupos', v_grupos,
    'tipos_de_cambio', case when (v_p -> 'columnas' ->> 'tipo_cambio')::boolean then public._tarjeta_tipos_de_cambio(fo.definicion, fo.diseno, v_buckets)
                            else '{"buckets": {}, "modos": {}}'::jsonb end,
    'variante', case when (fo.visibilidad -> (v_opcion ->> 'id') ->> 'ver') = 'todos'
                     then jsonb_build_object('nodo', v_opcion ->> 'id', 'opciones', coalesce((select jsonb_agg(jsonb_build_object('clave', x.v ->> 'clave', 'titulo', x.v ->> 'titulo') order by x.o)
                                                                                               from jsonb_array_elements(v_opcion -> 'opciones') with ordinality x (v, o)), '[]'::jsonb)) end,
    'tonos', coalesce((select jsonb_agg(v_ton -> c order by c collate "C") from unnest(v_claves) c), '[]'::jsonb),
    -- La moneda del total en Bs: la `moneda_a` del tipo de cambio activo que nombra el `total_en` de esta versión (la regla de la hoja).
    'moneda_bs', (select to_jsonb(t.moneda_a::text) from public.tipos_cambio t where t.activo and t.clave = (v_nodos -> (fo.definicion ->> 'total_en')) ->> 'clave'));
end;
$$;


ALTER FUNCTION "public"."cotizacion_tarjeta"("p_formula" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cotizacion_validar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' and not exists (select 1 from public.formulas f where f.id = new.formula_id and f.origen_id = new.origen_id and f.estado in ('publicada', 'archivada')) then
    raise exception 'La cotización debe nacer de una versión publicada de la fórmula de su origen.' using errcode = '23514';
  end if;
  if new.clase = 'final' and new.vehiculo_id is null then
    raise exception 'Una cotización final exige un vehículo vinculado.' using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."cotizacion_validar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cotizacion_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v public.cotizaciones;
begin
  -- Una copia de la fila nueva con lo que no cuenta puesto como estaba: si queda igual a la vieja, sólo cambiaron los contadores.
  v := new;
  v.actualizado_en := old.actualizado_en;
  v.reportes_count := old.reportes_count;
  v.favoritos_count := old.favoritos_count;
  if v is not distinct from old then
    new.actualizado_en := old.actualizado_en;
    return new;
  end if;
  new.actualizado_en := greatest(clock_timestamp(), old.actualizado_en + interval '1 microsecond');
  return new;
end $$;


ALTER FUNCTION "public"."cotizacion_version"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizacion_version"() IS 'Trigger de cotizaciones: sella la versión (actualizado_en) con greatest(clock_timestamp(), anterior + 1 µs) y no la mueve si sólo cambian los contadores de reportes o favoritos. docs/COTIZADOR.md › «Cómo se guarda (4.10-3)».';



CREATE OR REPLACE FUNCTION "public"."cotizaciones_listado"("p_tamano" integer, "p_origen" "uuid" DEFAULT NULL::"uuid", "p_clase" "public"."clase_cotizacion" DEFAULT NULL::"public"."clase_cotizacion", "p_mias" boolean DEFAULT false, "p_vehiculo" "uuid" DEFAULT NULL::"uuid", "p_cursor_en" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_id" "uuid" DEFAULT NULL::"uuid", "p_hacia_atras" boolean DEFAULT false, "p_lead" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("id" "uuid", "numero" bigint, "origen_id" "uuid", "lead_id" "uuid", "vehiculo_id" "uuid", "creado_por" "uuid", "clase" "public"."clase_cotizacion", "estado" "public"."estado_cotizacion", "titulo" "text", "total_base" numeric, "moneda_mostrar" character, "creado_en" timestamp with time zone, "vence_el" "date", "vencida" boolean)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  -- MAXIMO_DE_PAGINA_DE_COTIZACIONES (src/modules/cotizaciones/entities/listado.ts), más una para saber si hay otra.
  v_n integer := public._acotar_pagina(p_tamano, 100, 100) + 1;
  v_uid uuid := (select auth.uid());
  v_t uuid[] := public.origenes_con_alcance('cotizaciones.ver', 'todos');
  v_p uuid[] := public.origenes_con_alcance('cotizaciones.ver', 'propios');
  v_clases public.clase_cotizacion[] := case when p_clase is null then enum_range(null::public.clase_cotizacion) else array[p_clase] end;
  v_mias_en uuid[]; v_ver uuid[]; v_zona text; v_dias integer; v_hoy date;
  -- Con el lead, la ruta es la del lead y el vehículo, si llega, es un filtro sobre sus filas (4.17-4a).
  v_final boolean := p_clase is not distinct from 'final'; v_por_lead boolean := p_lead is not null; v_por_vehiculo boolean := p_vehiculo is not null and p_lead is null; v_todos boolean;
  v_listado boolean; v_finales boolean; v_por_origen boolean; v_origen_finales boolean; v_propias boolean; v_cartera boolean;
begin
  if (p_cursor_en is null) <> (p_cursor_id is null) then
    raise exception 'El cursor del listado está incompleto.' using errcode = '22023', hint = 'cursor';
  end if;
  v_p := array(select x from unnest(v_p) x where x <> all (v_t));
  if p_origen is not null then
    v_t := case when p_origen = any (v_t) then array[p_origen] else '{}' end;
    v_p := case when p_origen = any (v_p) then array[p_origen] else '{}' end;
    v_todos := false;
  else
    v_todos := cardinality(v_t) > 0 and not exists (select 1 from public.origenes o where o.id <> all (v_t));
  end if;
  v_ver := v_t || v_p;
  v_mias_en := case when p_mias then v_ver else v_p end;
  -- La clase nunca es columna de un índice (`enum_eq` no es leakproof: bajo la RLS no sería condición de índice): la final va por sus parciales, con `'final'` literal.
  v_listado := not p_mias and not v_por_vehiculo and not v_por_lead and v_todos and not v_final;
  v_finales := not p_mias and not v_por_vehiculo and not v_por_lead and v_todos and v_final;
  v_por_origen := not p_mias and not v_por_vehiculo and not v_por_lead and not v_todos and cardinality(v_t) > 0 and not v_final;
  v_origen_finales := not p_mias and not v_por_vehiculo and not v_por_lead and not v_todos and cardinality(v_t) > 0 and v_final;
  v_propias := not v_por_vehiculo and not v_por_lead and cardinality(v_mias_en) > 0;
  v_cartera := not p_mias and not v_por_vehiculo and not v_por_lead and cardinality(v_p) > 0;
  select e.zona_horaria, e.vigencia_dias into v_zona, v_dias from public.ajustes_empresa e where e.id = 1;
  v_hoy := (now() at time zone v_zona)::date;

  if p_cursor_en is null then
    return query
    with filas as (
      (select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
         from public.cotizaciones c where v_listado and c.clase = any (v_clases) order by c.creado_en desc, c.id desc limit v_n)  -- cotizaciones_listado_idx
      union all
      (select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
         from public.cotizaciones c where v_finales and c.eliminado_en is null and c.clase = 'final' order by c.creado_en desc, c.id desc limit v_n)  -- cotizaciones_finales_idx
      union all
      (select x.* from unnest(v_t) o (id) cross join lateral (
         select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
           from public.cotizaciones c where c.origen_id = o.id and c.clase = any (v_clases) order by c.creado_en desc, c.id desc limit v_n) x  -- cotizaciones_origen_creado_idx
        where v_por_origen)
      union all
      (select x.* from unnest(v_t) o (id) cross join lateral (
         select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
           from public.cotizaciones c where c.origen_id = o.id and c.eliminado_en is null and c.clase = 'final' order by c.creado_en desc, c.id desc limit v_n) x  -- cotizaciones_origen_finales_idx
        where v_origen_finales)
      union all
      (select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
         from public.cotizaciones c where v_propias and c.creado_por = v_uid and c.origen_id = any (v_mias_en) and c.clase = any (v_clases)
        order by c.creado_en desc, c.id desc limit v_n)  -- cotizaciones_creador_idx
      union all
      (select x.* from public.mis_leads() m (lead_id) cross join lateral (
         select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
           from public.cotizaciones c where c.lead_id = m.lead_id and c.creado_por <> v_uid and c.origen_id = any (v_p) and c.clase = any (v_clases)
          order by c.creado_en desc, c.id desc limit v_n) x  -- cotizaciones_lead_creado_idx
        where v_cartera)
      union all
      (select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
         from public.cotizaciones c where v_por_vehiculo and c.vehiculo_id = p_vehiculo and c.origen_id = any (v_ver) and c.clase = any (v_clases)
          and (not p_mias or c.creado_por = v_uid) order by c.creado_en desc, c.id desc limit v_n)  -- cotizaciones_vehiculo_creado_idx
      union all
      (select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
         from public.cotizaciones c where v_por_lead and c.lead_id = p_lead and c.origen_id = any (v_ver) and c.clase = any (v_clases)
          and (not p_mias or c.creado_por = v_uid) and (p_vehiculo is null or c.vehiculo_id = p_vehiculo) order by c.creado_en desc, c.id desc limit v_n)  -- cotizaciones_lead_creado_idx
    )
    select f.*, (f.creado_en at time zone v_zona)::date + v_dias, (f.creado_en at time zone v_zona)::date + v_dias < v_hoy
      from filas f order by f.creado_en desc, f.id desc limit v_n;
  elsif not p_hacia_atras then
    return query
    with filas as (
      (select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
         from public.cotizaciones c where v_listado and c.clase = any (v_clases) and (c.creado_en, c.id) < (p_cursor_en, p_cursor_id) order by c.creado_en desc, c.id desc limit v_n)
      union all
      (select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
         from public.cotizaciones c where v_finales and c.eliminado_en is null and c.clase = 'final' and (c.creado_en, c.id) < (p_cursor_en, p_cursor_id) order by c.creado_en desc, c.id desc limit v_n)
      union all
      (select x.* from unnest(v_t) o (id) cross join lateral (
         select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
           from public.cotizaciones c where c.origen_id = o.id and c.clase = any (v_clases) and (c.creado_en, c.id) < (p_cursor_en, p_cursor_id) order by c.creado_en desc, c.id desc limit v_n) x
        where v_por_origen)
      union all
      (select x.* from unnest(v_t) o (id) cross join lateral (
         select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
           from public.cotizaciones c where c.origen_id = o.id and c.eliminado_en is null and c.clase = 'final' and (c.creado_en, c.id) < (p_cursor_en, p_cursor_id) order by c.creado_en desc, c.id desc limit v_n) x
        where v_origen_finales)
      union all
      (select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
         from public.cotizaciones c where v_propias and c.creado_por = v_uid and c.origen_id = any (v_mias_en) and c.clase = any (v_clases) and (c.creado_en, c.id) < (p_cursor_en, p_cursor_id)
        order by c.creado_en desc, c.id desc limit v_n)
      union all
      (select x.* from public.mis_leads() m (lead_id) cross join lateral (
         select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
           from public.cotizaciones c where c.lead_id = m.lead_id and c.creado_por <> v_uid and c.origen_id = any (v_p) and c.clase = any (v_clases) and (c.creado_en, c.id) < (p_cursor_en, p_cursor_id)
          order by c.creado_en desc, c.id desc limit v_n) x
        where v_cartera)
      union all
      (select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
         from public.cotizaciones c where v_por_vehiculo and c.vehiculo_id = p_vehiculo and c.origen_id = any (v_ver) and c.clase = any (v_clases)
          and (not p_mias or c.creado_por = v_uid) and (c.creado_en, c.id) < (p_cursor_en, p_cursor_id) order by c.creado_en desc, c.id desc limit v_n)
      union all
      (select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
         from public.cotizaciones c where v_por_lead and c.lead_id = p_lead and c.origen_id = any (v_ver) and c.clase = any (v_clases)
          and (not p_mias or c.creado_por = v_uid) and (p_vehiculo is null or c.vehiculo_id = p_vehiculo) and (c.creado_en, c.id) < (p_cursor_en, p_cursor_id)
        order by c.creado_en desc, c.id desc limit v_n))
    select f.*, (f.creado_en at time zone v_zona)::date + v_dias, (f.creado_en at time zone v_zona)::date + v_dias < v_hoy
      from filas f order by f.creado_en desc, f.id desc limit v_n;
  else
    -- Hacia atrás: lo estrictamente anterior, en orden ascendente (`armarPagina` lo da vuelta).
    return query
    with filas as (
      (select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
         from public.cotizaciones c where v_listado and c.clase = any (v_clases) and (c.creado_en, c.id) > (p_cursor_en, p_cursor_id) order by c.creado_en, c.id limit v_n)
      union all
      (select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
         from public.cotizaciones c where v_finales and c.eliminado_en is null and c.clase = 'final' and (c.creado_en, c.id) > (p_cursor_en, p_cursor_id) order by c.creado_en, c.id limit v_n)
      union all
      (select x.* from unnest(v_t) o (id) cross join lateral (
         select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
           from public.cotizaciones c where c.origen_id = o.id and c.clase = any (v_clases) and (c.creado_en, c.id) > (p_cursor_en, p_cursor_id) order by c.creado_en, c.id limit v_n) x
        where v_por_origen)
      union all
      (select x.* from unnest(v_t) o (id) cross join lateral (
         select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
           from public.cotizaciones c where c.origen_id = o.id and c.eliminado_en is null and c.clase = 'final' and (c.creado_en, c.id) > (p_cursor_en, p_cursor_id) order by c.creado_en, c.id limit v_n) x
        where v_origen_finales)
      union all
      (select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
         from public.cotizaciones c where v_propias and c.creado_por = v_uid and c.origen_id = any (v_mias_en) and c.clase = any (v_clases) and (c.creado_en, c.id) > (p_cursor_en, p_cursor_id)
        order by c.creado_en, c.id limit v_n)
      union all
      (select x.* from public.mis_leads() m (lead_id) cross join lateral (
         select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
           from public.cotizaciones c where c.lead_id = m.lead_id and c.creado_por <> v_uid and c.origen_id = any (v_p) and c.clase = any (v_clases) and (c.creado_en, c.id) > (p_cursor_en, p_cursor_id)
          order by c.creado_en, c.id limit v_n) x
        where v_cartera)
      union all
      (select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
         from public.cotizaciones c where v_por_vehiculo and c.vehiculo_id = p_vehiculo and c.origen_id = any (v_ver) and c.clase = any (v_clases)
          and (not p_mias or c.creado_por = v_uid) and (c.creado_en, c.id) > (p_cursor_en, p_cursor_id) order by c.creado_en, c.id limit v_n)
      union all
      (select c.id, c.numero, c.origen_id, c.lead_id, c.vehiculo_id, c.creado_por, c.clase, c.estado, c.titulo, c.total_base, c.moneda_mostrar, c.creado_en
         from public.cotizaciones c where v_por_lead and c.lead_id = p_lead and c.origen_id = any (v_ver) and c.clase = any (v_clases)
          and (not p_mias or c.creado_por = v_uid) and (p_vehiculo is null or c.vehiculo_id = p_vehiculo) and (c.creado_en, c.id) > (p_cursor_en, p_cursor_id)
        order by c.creado_en, c.id limit v_n))
    select f.*, (f.creado_en at time zone v_zona)::date + v_dias, (f.creado_en at time zone v_zona)::date + v_dias < v_hoy
      from filas f order by f.creado_en, f.id limit v_n;
  end if;
end $$;


ALTER FUNCTION "public"."cotizaciones_listado"("p_tamano" integer, "p_origen" "uuid", "p_clase" "public"."clase_cotizacion", "p_mias" boolean, "p_vehiculo" "uuid", "p_cursor_en" timestamp with time zone, "p_cursor_id" "uuid", "p_hacia_atras" boolean, "p_lead" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizaciones_listado"("p_tamano" integer, "p_origen" "uuid", "p_clase" "public"."clase_cotizacion", "p_mias" boolean, "p_vehiculo" "uuid", "p_cursor_en" timestamp with time zone, "p_cursor_id" "uuid", "p_hacia_atras" boolean, "p_lead" "uuid") IS 'Una página del listado /cotizaciones de la más nueva a la más vieja (creado_en desc, id desc), por cursor (hacia atrás, en orden ascendente), con los filtros origen, clase, mías (las que creó quien mira), vehículo y lead, y la vigencia (vence_el, vencida) de cotizacion_hoja_guardada. Corre como quien la llama: la RLS decide qué se ve; cada ruta (lo de «todos», lo propio, la cartera de mis_leads(), el vehículo, el lead) va por su índice; con el lead, una sola ruta y el vehículo como filtro. Sin el snapshot. Lo mide supabase/tests/medir-cotizaciones-listado.sql.';



CREATE OR REPLACE FUNCTION "public"."cotizaciones_papelera_enviar"("p_cotizaciones" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  e record; v_lote uuid; v_version timestamptz; v_mensaje text; v_codigo text; v_titulo text;
  v_enviados jsonb := '[]'::jsonb; v_rechazados jsonb := '[]'::jsonb;
begin
  perform public.assert_activo();
  if jsonb_typeof(p_cotizaciones) is distinct from 'array' or jsonb_array_length(p_cotizaciones) = 0 then
    raise exception 'No llegó ninguna cotización.' using errcode = '22023';
  end if;
  if jsonb_array_length(p_cotizaciones) > 200 then
    raise exception 'Se envían hasta 200 por vez.' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_cotizaciones) x
    where jsonb_typeof(x) <> 'object'
       or coalesce(x ->> 'id', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or coalesce(x ->> 'actualizado_en', '2000-01-01') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}') then
    raise exception 'Una de las cotizaciones llegó incompleta. Recarga e intenta de nuevo.' using errcode = '22023';
  end if;

  insert into public.lotes_papelera (tipo, creado_por) values ('cotizaciones', (select auth.uid())) returning id into v_lote;
  for e in
    select distinct on (x ->> 'id') (x ->> 'id')::uuid as id, x ->> 'actualizado_en' as version
    from jsonb_array_elements(p_cotizaciones) x order by x ->> 'id'
  loop
    begin
      v_enviados := v_enviados || public._cotizacion_a_papelera(e.id, v_lote, true, e.version::timestamptz);
    exception when others then
      get stacked diagnostics v_mensaje = message_text, v_codigo = returned_sqlstate;
      -- Sólo lo que escribimos nosotros llega a la pantalla (22023: falta la versión).
      if v_codigo not in ('PT409', '42501', '23514', '22023', 'P0001') then
        v_mensaje := 'No se pudo enviar. Vuelve a intentarlo.';
      end if;
      -- El título, sólo de lo que quien llama ve.
      v_titulo := null;
      select coalesce(x.titulo, 'Cotización #' || x.numero) into v_titulo from public.cotizaciones x
       where x.id = e.id and public.puede_cotizacion(x.id, 'cotizaciones.ver');
      v_rechazados := v_rechazados || jsonb_build_object('id', e.id, 'titulo', v_titulo, 'codigo', v_codigo, 'motivo', v_mensaje);
    end;
  end loop;

  if jsonb_array_length(v_enviados) = 0 then
    delete from public.lotes_papelera l where l.id = v_lote;
    return jsonb_build_object('lote', null, 'actualizado_en', null, 'enviados', v_enviados, 'rechazados', v_rechazados);
  end if;
  update public.lotes_papelera l
  set resumen = jsonb_build_object('cantidad', jsonb_array_length(v_enviados), 'restaurados', 0, 'purgados', 0)
  where l.id = v_lote;
  v_version := public._lote_papelera_tocar(v_lote);
  perform public.registrar_actividad('papelera.enviado', 'lotes_papelera', v_lote::text, null, null,
    jsonb_build_object('tipo', 'cotizaciones', 'cantidad', jsonb_array_length(v_enviados)));
  return jsonb_build_object('lote', v_lote, 'actualizado_en', v_version, 'enviados', v_enviados, 'rechazados', v_rechazados);
end;
$_$;


ALTER FUNCTION "public"."cotizaciones_papelera_enviar"("p_cotizaciones" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizaciones_papelera_enviar"("p_cotizaciones" "jsonb") IS 'Manda a la papelera de cotizaciones hasta 200 {id, actualizado_en}, cada una por _cotizacion_a_papelera (ver antes del candado, el permiso de su clase y la versión). Devuelve {lote, actualizado_en, enviados: [{id, numero, titulo}], rechazados: [{id, titulo, codigo, motivo}]}; sin enviadas, lote nulo y ningún lote. El título de un rechazo, sólo si quien llama la ve.';



CREATE OR REPLACE FUNCTION "public"."cotizaciones_papelera_listar"("p_antes_en" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_antes_id" "uuid" DEFAULT NULL::"uuid", "p_hacia_atras" boolean DEFAULT false, "p_tope" integer DEFAULT 6, "p_primeros" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_dias int; v_todo boolean; v_yo uuid := (select auth.uid()); v_n int := public._acotar_pagina(p_tope, 6, 51);
        v_primeros int := public._acotar_pagina(p_primeros, 20, 200); v_ids uuid[];
begin
  perform public.assert_activo();
  select e.papelera_dias into v_dias from public.ajustes_empresa e where e.id = 1;
  v_todo := public.tiene_permiso('cotizaciones.papelera.purgar');
  -- Las tres por `lotes_papelera_tipo_idx` (tipo, creado_en desc, id desc) where pendientes: sin cursor, hacia adelante y hacia atrás. «Le queda alguna en
  -- la papelera» es una sonda por lote (`cotizaciones_lote_papelera_idx`, `limit 1`) y no un `exists`: con pocas en la papelera, el `exists` del plan genérico
  -- se vuelve un semi join que lee entero ese índice (crece con la papelera, no con la página; medido en el 4.24-1a, `medir-escala.sql`).
  if p_antes_en is null then
    v_ids := array(select l.id from public.lotes_papelera l
      where l.tipo = 'cotizaciones' and l.purgado_en is null and l.restaurado_en is null
        and (v_todo or l.creado_por = v_yo)
        and (select true from public.cotizaciones c where c.lote_papelera_id = l.id and c.eliminado_en is not null limit 1)
      order by l.creado_en desc, l.id desc limit v_n);
  elsif not coalesce(p_hacia_atras, false) then
    v_ids := array(select l.id from public.lotes_papelera l
      where l.tipo = 'cotizaciones' and l.purgado_en is null and l.restaurado_en is null
        and (v_todo or l.creado_por = v_yo)
        and (l.creado_en, l.id) < (p_antes_en, p_antes_id)
        and (select true from public.cotizaciones c where c.lote_papelera_id = l.id and c.eliminado_en is not null limit 1)
      order by l.creado_en desc, l.id desc limit v_n);
  else
    v_ids := array(select l.id from public.lotes_papelera l
      where l.tipo = 'cotizaciones' and l.purgado_en is null and l.restaurado_en is null
        and (v_todo or l.creado_por = v_yo)
        and (l.creado_en, l.id) > (p_antes_en, p_antes_id)
        and (select true from public.cotizaciones c where c.lote_papelera_id = l.id and c.eliminado_en is not null limit 1)
      order by l.creado_en, l.id limit v_n);
  end if;
  return coalesce((
    select jsonb_agg(public._cotizaciones_papelera_lote_json(l, v_dias, v_yo, v_primeros) order by o.ord)
    from unnest(v_ids) with ordinality o (id, ord) join public.lotes_papelera l on l.id = o.id), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."cotizaciones_papelera_listar"("p_antes_en" timestamp with time zone, "p_antes_id" "uuid", "p_hacia_atras" boolean, "p_tope" integer, "p_primeros" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizaciones_papelera_listar"("p_antes_en" timestamp with time zone, "p_antes_id" "uuid", "p_hacia_atras" boolean, "p_tope" integer, "p_primeros" integer) IS 'Los lotes pendientes de la papelera de cotizaciones con algo en la papelera, por cursor (creado_en, id) desc; hacia atrás, del más cercano al más lejano. Con cotizaciones.papelera.purgar, todos; sin ella, los de quien llama. p_tope hasta 51 lotes, p_primeros hasta 200 cotizaciones por lote (_acotar_pagina).';



CREATE OR REPLACE FUNCTION "public"."cotizaciones_papelera_lote"("p_lote" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_dias int; v_todo boolean; v_yo uuid := (select auth.uid()); l public.lotes_papelera;
begin
  perform public.assert_activo();
  select e.papelera_dias into v_dias from public.ajustes_empresa e where e.id = 1;
  v_todo := public.tiene_permiso('cotizaciones.papelera.purgar');
  select * into l from public.lotes_papelera x
   where x.id = p_lote and x.tipo = 'cotizaciones' and x.purgado_en is null and x.restaurado_en is null
     and (v_todo or x.creado_por = v_yo)
     and exists (select 1 from public.cotizaciones y where y.lote_papelera_id = x.id and y.eliminado_en is not null);
  if not found then
    return null;
  end if;
  return public._cotizaciones_papelera_lote_json(l, v_dias, v_yo, null);
end;
$$;


ALTER FUNCTION "public"."cotizaciones_papelera_lote"("p_lote" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizaciones_papelera_lote"("p_lote" "uuid") IS 'Un lote de la papelera de cotizaciones entero, si es de cotizaciones, pendiente, con algo en la papelera y de quien llama (o con cotizaciones.papelera.purgar); si no, nulo, sin decir por qué.';



CREATE OR REPLACE FUNCTION "public"."cotizaciones_papelera_purgar"("p_lote" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cotizaciones" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare l public.lotes_papelera;
begin
  perform public.assert_activo();
  -- Antes de mirar el lote: sin la clave no se sabe ni si existe.
  if not public.tiene_permiso('cotizaciones.papelera.purgar') then
    raise exception 'No tienes permiso para purgar la papelera.' using errcode = '42501';
  end if;
  select * into l from public.lotes_papelera x
   where x.id = p_lote and x.tipo = 'cotizaciones' and x.purgado_en is null and x.restaurado_en is null for no key update;
  if not found then
    raise exception 'Ese lote ya no está en la papelera.' using errcode = 'PT409';
  end if;
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.' using errcode = '22023';
  end if;
  if l.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._conflicto_de_edicion('lotes_papelera', l.id, l.actualizado_en, 'este lote de la papelera');
  end if;
  return public._papelera_purgar_cotizaciones(l.id, p_cotizaciones);
end;
$$;


ALTER FUNCTION "public"."cotizaciones_papelera_purgar"("p_lote" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cotizaciones" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."cotizaciones_papelera_purgar"("p_lote" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cotizaciones" "uuid"[]) IS 'Purga un lote de la papelera de cotizaciones (o sólo p_cotizaciones) con la versión que quien llama tenía en pantalla; pide cotizaciones.papelera.purgar antes de mirar el lote. Lo bloqueado se queda. Devuelve {actualizado_en, purgados: [{id, numero, titulo}], bloqueados: [{id, numero, titulo, motivo}], quedan}.';



CREATE OR REPLACE FUNCTION "public"."cotizaciones_papelera_restaurar"("p_lote" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cotizaciones" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare l public.lotes_papelera;
begin
  perform public.assert_activo();
  -- Sin candado: quien no puede nunca espera el del lote.
  select * into l from public.lotes_papelera x
   where x.id = p_lote and x.tipo = 'cotizaciones' and x.purgado_en is null and x.restaurado_en is null;
  if not found then
    raise exception 'Ese lote ya no está en la papelera.' using errcode = 'PT409';
  end if;
  if l.creado_por is distinct from (select auth.uid()) and not public.tiene_permiso('cotizaciones.papelera.purgar') then
    raise exception 'Sólo lo restaura quien lo envió o quien puede vaciar la papelera.' using errcode = '42501';
  end if;
  -- El lote tomado (no se borra: no choca con quien lo nombra) y otra vez las dos miradas.
  select * into l from public.lotes_papelera x
   where x.id = p_lote and x.tipo = 'cotizaciones' and x.purgado_en is null and x.restaurado_en is null for no key update;
  if not found then
    raise exception 'Ese lote ya no está en la papelera.' using errcode = 'PT409';
  end if;
  if l.creado_por is distinct from (select auth.uid()) and not public.tiene_permiso('cotizaciones.papelera.purgar') then
    raise exception 'Sólo lo restaura quien lo envió o quien puede vaciar la papelera.' using errcode = '42501';
  end if;
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.' using errcode = '22023';
  end if;
  if l.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._conflicto_de_edicion('lotes_papelera', l.id, l.actualizado_en, 'este lote de la papelera');
  end if;
  return public._papelera_restaurar_cotizaciones(l.id, p_cotizaciones);
end;
$$;


