CREATE OR REPLACE FUNCTION "public"."declaracion_canal"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_canal" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d public.declaraciones_aduana; v_ver timestamptz;
begin
  perform public.assert_activo();
  if not (select public.tiene_permiso('logistica.aduana.gestionar')) then
    raise exception 'No tienes el permiso «logistica.aduana.gestionar».' using errcode = '42501';
  end if;
  -- C15.
  if p_canal is null then
    raise exception 'El canal no se puede quitar: la composición quedó congelada.' using errcode = '22023', hint = 'canal';
  end if;
  if not pg_input_is_valid(p_canal, 'public.canal_aforo') then
    raise exception 'Ese canal de aforo no existe.' using errcode = '22023', hint = 'canal';
  end if;
  -- C16 · la cabecera por su PK y la versión.
  select * into d from public.declaraciones_aduana c where c.id = p_id for update;
  if not found then
    raise exception 'La declaración ya no existe. Recarga.' using errcode = 'PT409';
  end if;
  if p_actualizado_en_esperado is null or d.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._conflicto_de_edicion('declaraciones_aduana', d.id, d.actualizado_en, 'esta declaración');
  end if;
  if d.canal is not distinct from p_canal::public.canal_aforo then
    return jsonb_build_object('id', d.id, 'actualizado_en', d.actualizado_en, 'canal', d.canal, 'sin_cambios', true);
  end if;
  -- D26 · no se congela una composición vacía. Por declaraciones_vehiculos_pkey.
  if not exists (select 1 from public.declaraciones_vehiculos dv where dv.declaracion_id = d.id and dv.removido_en is null limit 1) then
    raise exception 'Agrega al menos un vehículo antes de asignar el canal.' using errcode = '23514', hint = 'canal';
  end if;
  update public.declaraciones_aduana c set canal = p_canal::public.canal_aforo where c.id = d.id returning c.actualizado_en into v_ver;
  return jsonb_build_object('id', d.id, 'actualizado_en', v_ver, 'canal', p_canal, 'sin_cambios', false);
end;
$$;


ALTER FUNCTION "public"."declaracion_canal"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_canal" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."declaracion_canal"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_canal" "text") IS 'Asigna o cambia el canal de aforo de una declaración con la versión (paso 6.07-2). Nunca a nulo; no a una declaración sin vehículos vivos. Congela la composición. Pide logistica.aduana.gestionar. Devuelve {id, actualizado_en, canal, sin_cambios}.';



CREATE OR REPLACE FUNCTION "public"."declaracion_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_datos" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  d public.declaraciones_aduana; n public.declaraciones_aduana; v_c text;
  v_sujeto constant text := 'esta declaración';
begin
  perform public.assert_activo();
  -- C4 · el permiso no es por origen: antes de leer nada.
  if not (select public.tiene_permiso('logistica.aduana.gestionar')) then
    raise exception 'No tienes el permiso «logistica.aduana.gestionar».' using errcode = '42501';
  end if;
  if p_id is null then
    -- C5 · crear.
    if p_actualizado_en_esperado is not null then
      raise exception 'Para crear, la versión va vacía.' using errcode = '22023', hint = 'version';
    end if;
    n := public._declaracion_datos(d, p_datos);
    if n.numero is null then
      raise exception 'El número es obligatorio.' using errcode = '22023', hint = 'numero';
    end if;
  else
    -- C6 · editar: la cabecera por su PK.
    select * into d from public.declaraciones_aduana x where x.id = p_id for update;
    if not found then
      raise exception 'La declaración ya no existe. Recarga.' using errcode = 'PT409';
    end if;
    if p_actualizado_en_esperado is null then
      perform public._conflicto_de_edicion('declaraciones_aduana', d.id, d.actualizado_en, v_sujeto);
    end if;
    n := public._declaracion_datos(d, p_datos);
    if (n.numero, n.aceptada_el, n.vence_tributos_el, n.despachante, n.deposito, n.notas)
       is not distinct from (d.numero, d.aceptada_el, d.vence_tributos_el, d.despachante, d.deposito, d.notas) then
      return jsonb_build_object('id', d.id, 'actualizado_en', d.actualizado_en, 'sin_cambios', true);
    end if;
    if d.actualizado_en is distinct from p_actualizado_en_esperado then
      perform public._conflicto_de_edicion('declaraciones_aduana', d.id, d.actualizado_en, v_sujeto);
    end if;
  end if;
  begin
    if p_id is null then
      insert into public.declaraciones_aduana (numero, aceptada_el, vence_tributos_el, despachante, deposito, notas, creado_por)
      values (n.numero, n.aceptada_el, n.vence_tributos_el, n.despachante, n.deposito, n.notas, (select auth.uid()))
      returning * into n;
    else
      update public.declaraciones_aduana x
         set numero = n.numero, aceptada_el = n.aceptada_el, vence_tributos_el = n.vence_tributos_el, despachante = n.despachante,
             deposito = n.deposito, notas = n.notas
       where x.id = d.id
      returning * into n;
    end if;
  exception when unique_violation then
    get stacked diagnostics v_c = constraint_name;
    if v_c = 'declaraciones_aduana_numero_key' then
      raise exception 'Ya hay una declaración con el número «%».', n.numero using errcode = '23505', hint = 'numero';
    end if;
    raise;
  end;
  return jsonb_build_object('id', n.id, 'actualizado_en', n.actualizado_en, 'sin_cambios', false);
end;
$$;


ALTER FUNCTION "public"."declaracion_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_datos" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."declaracion_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_datos" "jsonb") IS 'Crea (p_id nulo, esperada nula) o edita con la versión una declaración de aduana (paso 6.07-2). p_datos: numero, aceptada_el, vence_tributos_el, despachante, deposito, notas (null = vaciar). Pide logistica.aduana.gestionar. Devuelve {id, actualizado_en, sin_cambios}.';



CREATE OR REPLACE FUNCTION "public"."declaracion_leer"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_gestiona boolean;
  v_todos uuid[]; v_algun uuid[];
  d public.declaraciones_aduana; s record;
  v_vehiculos jsonb; v_mas boolean;
begin
  perform public.assert_activo();
  v_gestiona := public.tiene_permiso('logistica.aduana.gestionar');
  if not (v_gestiona or public.tiene_permiso('logistica.ver')) then
    raise exception 'No tienes permiso para ver las declaraciones.' using errcode = '42501';
  end if;
  if p_id is null then
    raise exception 'Falta la declaración.' using errcode = '22023', hint = 'id';
  end if;
  v_todos := public.origenes_con_alcance('logistica.ver', 'todos');
  v_algun := public.origenes_con_alcance('logistica.ver', 'propios');
  select * into d from public.declaraciones_aduana x where x.id = p_id;
  if d.id is not null then
    select * into s from public._declaracion_resumen(d.id, v_todos, v_algun, v_yo);
  end if;
  if d.id is null or (not v_gestiona and s.vehiculos = 0) then
    raise exception 'La declaración no existe o no la ves.' using errcode = 'P0002';
  end if;
  -- Hasta 201 (201 = hay más) por la PK, en orden de vehiculo_id; el tributo con la condición de aduana.tributos_pagados (gastos_vehiculo_idx).
  select coalesce(jsonb_agg(jsonb_build_object('vehiculo_id', y.vehiculo_id, 'titulo', y.titulo, 'origen_id', y.origen_id, 'fase_id', y.fase_id,
                                               'fase', y.fase, 'agregado_en', y.agregado_en, 'tributo', y.tributo) order by y.vehiculo_id)
                    filter (where y.n <= 200), '[]'::jsonb),
         count(*) > 200
    into v_vehiculos, v_mas
    from (select x.*, row_number() over (order by x.vehiculo_id) as n
            from (select dv.vehiculo_id, v.titulo, v.origen_id, v.fase_id, f.nombre as fase, dv.agregado_en,
                         exists (select 1 from public.gastos g join public.categorias_gasto cg on cg.id = g.categoria_id
                                  where g.vehiculo_id = dv.vehiculo_id and g.eliminado_en is null and cg.proposito = 'tributos') as tributo
                    from public.declaraciones_vehiculos dv
                    join public.vehiculos v on v.id = dv.vehiculo_id and v.eliminado_en is null
                    left join public.fases f on f.id = v.fase_id
                   where dv.declaracion_id = d.id and dv.removido_en is null
                     and public._aduana_vehiculo_visible(v.origen_id, v.creado_por, v.lead_id, v_todos, v_algun, v_yo)
                   order by dv.vehiculo_id
                   limit 201) x) y;
  -- C15 · actualizado_en es la versión de declaracion_version(): sirve de esperada para guardar, poner vehículos y el canal.
  return jsonb_build_object(
    'id', d.id, 'numero', d.numero, 'canal', d.canal, 'aceptada_el', d.aceptada_el, 'vence_tributos_el', d.vence_tributos_el,
    'despachante', d.despachante, 'deposito', d.deposito, 'notas', d.notas, 'creado_en', d.creado_en, 'actualizado_en', d.actualizado_en,
    'vehiculos', v_vehiculos, 'hay_mas', v_mas, 'hay_ocultos', s.hay_ocultos, 'pagada', s.pagada, 'faltan', s.faltan);
end;
$$;


ALTER FUNCTION "public"."declaracion_leer"("p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."declaracion_leer"("p_id" "uuid") IS 'Una declaración de aduana con los vehículos vivos que quien llama ve (hasta 200, hay_mas), hay_ocultos, pagada (de todos los vivos, D31), faltan y por vehículo tributo. Con logistica.aduana.gestionar, toda declaración; con logistica.ver, la que tiene un vehículo que ve. La que no existe y la que no se ve, el mismo P0002 (6.07-3).';



CREATE OR REPLACE FUNCTION "public"."declaracion_vehiculo_proteger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_cambia boolean; v_antes boolean; v_despues boolean; v_decl uuid; v_veh uuid; v_canal public.canal_aforo; v_hay boolean;
  v_fase uuid; v_clave text; v_nombre text;
begin
  if tg_op = 'UPDATE' then
    v_cambia := new.declaracion_id is distinct from old.declaracion_id or new.vehiculo_id is distinct from old.vehiculo_id;
    if v_cambia then
      raise exception 'La composición se cambia con declaracion_vehiculos_poner.' using errcode = '22023', hint = 'vehiculos';
    end if;
  end if;
  if tg_op = 'INSERT' then
    v_antes := false;
  else
    v_antes := old.removido_en is null;
  end if;
  if tg_op = 'DELETE' then
    v_despues := false;
    v_decl := old.declaracion_id;
    v_veh := old.vehiculo_id;
  else
    v_despues := new.removido_en is null;
    v_decl := new.declaracion_id;
    v_veh := new.vehiculo_id;
  end if;
  if v_antes = v_despues then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;
  -- C18 · la purga en cascada del vehículo: ya no está (por vehiculos_pkey, sin candado) y sale antes de mirar la cabecera.
  if tg_op = 'DELETE' and not exists (select 1 from public.vehiculos v where v.id = v_veh) then
    return old;
  end if;
  -- Congelado. Si la cabecera no está, se borra en cascada: no hay composición que congelar.
  select c.canal into v_canal from public.declaraciones_aduana c where c.id = v_decl for share;
  v_hay := found;
  if v_hay and v_canal is not null then
    raise exception 'La declaración ya tiene canal de aforo: su composición no cambia.' using errcode = '23514', hint = 'canal';
  end if;
  -- C19 · lo exigido, sólo al quitar o borrar una viva. La unidad `for share`: espera y hace esperar a cambiar_fase (for no key update).
  if v_antes and not v_despues then
    select v.fase_id into v_fase from public.vehiculos v where v.id = v_veh for share;
    if v_fase is not null then
      -- Por fases_requisitos_fase_id_idx.
      select q.clave_dato into v_clave from public.fases_requisitos q
       where q.fase_id = v_fase and q.tipo = 'dato' and q.bloqueante and q.clave_dato in ('aduana.declaracion', 'aduana.canal')
       order by q.clave_dato desc
       limit 1;
      if v_clave is not null then
        select f.nombre into v_nombre from public.fases f where f.id = v_fase;
        raise exception 'La fase «%» exige %: no se puede quitar el vehículo.', v_nombre,
          case v_clave when 'aduana.declaracion' then 'la declaración de aduana' else 'el canal de aforo' end
          using errcode = '23514', hint = v_clave;
      end if;
    end if;
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."declaracion_vehiculo_proteger"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."declaracion_vehiculo_proteger"() IS 'Trigger before insert, delete o update de declaraciones_vehiculos: congela la composición con canal y no deja quitar un vehículo cuya fase exige aduana.declaracion o aduana.canal como bloqueante. 6.07-2.';



CREATE OR REPLACE FUNCTION "public"."declaracion_vehiculos_poner"("p_declaracion" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_agregar" "uuid"[], "p_quitar" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  d public.declaraciones_aduana; l record; v_x uuid; v_c text; v_otra text; v_titulo text; v_escribio boolean := false; v_ver timestamptz;
begin
  perform public.assert_activo();
  if not (select public.tiene_permiso('logistica.aduana.gestionar')) then
    raise exception 'No tienes el permiso «logistica.aduana.gestionar».' using errcode = '42501';
  end if;
  select * into l from public._declaracion_vehiculos_listas(p_agregar, p_quitar);
  -- C10 · la cabecera por su PK; la versión antes que el canal: quien tenía la pantalla vieja recibe PT409.
  select * into d from public.declaraciones_aduana c where c.id = p_declaracion for update;
  if not found then
    raise exception 'La declaración ya no existe. Recarga.' using errcode = 'PT409';
  end if;
  if p_actualizado_en_esperado is null or d.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._conflicto_de_edicion('declaraciones_aduana', d.id, d.actualizado_en, 'esta declaración');
  end if;
  if cardinality(l.agregar) + cardinality(l.quitar) = 0 then
    return jsonb_build_object('id', d.id, 'actualizado_en', d.actualizado_en, 'sin_cambios', true);
  end if;
  if d.canal is not null then
    raise exception 'La declaración ya tiene canal de aforo: su composición no cambia.' using errcode = '23514', hint = 'canal';
  end if;
  perform public._declaracion_vehiculos_validar(d.id, l.agregar, l.agregar || l.quitar);
  -- C12–C13 · un solo recorrido en orden de id. Por declaraciones_vehiculos_pkey y declaraciones_vehiculo_activo_unico.
  for v_x in select u from unnest(l.agregar || l.quitar) u order by u loop
    if v_x = any (l.quitar) then
      update public.declaraciones_vehiculos dv set removido_en = now()
       where dv.declaracion_id = d.id and dv.vehiculo_id = v_x and dv.removido_en is null;
      v_escribio := v_escribio or found;
      continue;
    end if;
    continue when exists (select 1 from public.declaraciones_vehiculos dv
                           where dv.declaracion_id = d.id and dv.vehiculo_id = v_x and dv.removido_en is null);
    begin
      insert into public.declaraciones_vehiculos as dv (declaracion_id, vehiculo_id) values (d.id, v_x)
        on conflict (declaracion_id, vehiculo_id) do update set removido_en = null, agregado_en = now() where dv.removido_en is not null;
      v_escribio := true;
    exception when unique_violation then
      get stacked diagnostics v_c = constraint_name;
      if v_c = 'declaraciones_vehiculo_activo_unico' then
        select v.titulo into v_titulo from public.vehiculos v where v.id = v_x;
        select o.numero into v_otra from public.declaraciones_vehiculos dv join public.declaraciones_aduana o on o.id = dv.declaracion_id
         where dv.vehiculo_id = v_x and dv.removido_en is null;
        raise exception '«%» ya está en la declaración «%».', v_titulo, coalesce(v_otra, 'otra') using errcode = '23514', hint = 'vehiculos';
      end if;
      raise;
    end;
  end loop;
  if not v_escribio then
    return jsonb_build_object('id', d.id, 'actualizado_en', d.actualizado_en, 'sin_cambios', true);
  end if;
  -- El toque mueve la versión (declaracion_version) y deja en actividad quién cambió (trg_auditar).
  update public.declaraciones_aduana x set actualizado_en = x.actualizado_en where x.id = d.id returning x.actualizado_en into v_ver;
  return jsonb_build_object('id', d.id, 'actualizado_en', v_ver, 'sin_cambios', false);
end;
$$;


ALTER FUNCTION "public"."declaracion_vehiculos_poner"("p_declaracion" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_agregar" "uuid"[], "p_quitar" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."declaracion_vehiculos_poner"("p_declaracion" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_agregar" "uuid"[], "p_quitar" "uuid"[]) IS 'Agrega y quita vehículos de una declaración con la versión de la cabecera (paso 6.07-2). Pide logistica.aduana.gestionar y logistica.ver de cada vehículo; a lo sumo 200. Con canal no cambia (23514 canal). Un vehículo vivo en otra declaración, 23514 vehiculos. Devuelve {id, actualizado_en, sin_cambios}.';



CREATE OR REPLACE FUNCTION "public"."declaracion_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  new.actualizado_en := greatest(clock_timestamp(), old.actualizado_en + interval '1 microsecond');
  return new;
end;
$$;


ALTER FUNCTION "public"."declaracion_version"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."declaracion_version"() IS 'Trigger before update de declaraciones_aduana: la versión con greatest(clock_timestamp(), anterior + 1 µs), para que se mueva dos veces en una transacción. 6.07-2.';



CREATE OR REPLACE FUNCTION "public"."declaraciones_listar"("p_desde" timestamp with time zone, "p_id" "uuid", "p_tope" integer, "p_filtros" "jsonb") RETURNS TABLE("id" "uuid", "numero" "text", "canal" "text", "aceptada_el" "date", "vence_tributos_el" "date", "despachante" "text", "deposito" "text", "creado_en" timestamp with time zone, "actualizado_en" timestamp with time zone, "vehiculos" integer, "hay_ocultos" boolean, "pagada" boolean, "faltan" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  -- TAMANO_DE_PAGINA_POR_DEFECTO (50), máximo 100, más una para saber si hay otra.
  v_n integer := public._acotar_pagina(p_tope, 50, 100) + 1;
  v_lote constant integer := 200;
  v_yo uuid := (select auth.uid());
  v_gestiona boolean;
  f record;
  v_todos uuid[]; v_algun uuid[];
  v_desde timestamptz; v_id uuid;
  d public.declaraciones_aduana; s record;
  v_leidas integer; v_hallados integer := 0;
begin
  perform public.assert_activo();
  v_gestiona := public.tiene_permiso('logistica.aduana.gestionar');
  if not (v_gestiona or public.tiene_permiso('logistica.ver')) then
    raise exception 'No tienes permiso para ver las declaraciones.' using errcode = '42501';
  end if;
  select * into f from public._declaraciones_filtros(p_filtros);
  if (p_desde is null) <> (p_id is null) then
    raise exception 'El cursor de la lista está incompleto.' using errcode = '22023', hint = 'cursor';
  end if;
  v_todos := public.origenes_con_alcance('logistica.ver', 'todos');
  v_algun := public.origenes_con_alcance('logistica.ver', 'propios');
  -- Sin cursor, uno que va antes de toda fila (creado_en nunca es infinity): una sola consulta y el cursor sigue siendo condición de índice.
  v_desde := coalesce(p_desde, 'infinity'::timestamptz);
  v_id := coalesce(p_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid);
  -- Por lotes de 200 sobre declaraciones_aduana_creado_idx (creado_en desc, id desc), sin filtros en la consulta: con ellos, el plan genérico los
  -- creía selectivos y ordenaba toda la tabla. Los filtros y la visibilidad sin gestionar descartan filas del índice: la tabla es de volumen bajo (D34).
  loop
    v_leidas := 0;
    for d in
      select x.* from public.declaraciones_aduana x
       where (x.creado_en, x.id) < (v_desde, v_id)
       order by x.creado_en desc, x.id desc
       limit v_lote
    loop
      v_leidas := v_leidas + 1;
      v_desde := d.creado_en;
      v_id := d.id;
      continue when f.canal is not null and d.canal is distinct from f.canal;
      continue when f.q is not null and not starts_with(upper(d.numero), upper(f.q));
      select * into s from public._declaracion_resumen(d.id, v_todos, v_algun, v_yo);
      continue when not v_gestiona and s.vehiculos = 0;
      continue when f.pagada is not null and s.pagada is distinct from f.pagada;
      id := d.id; numero := d.numero; canal := d.canal::text; aceptada_el := d.aceptada_el; vence_tributos_el := d.vence_tributos_el;
      despachante := d.despachante; deposito := d.deposito; creado_en := d.creado_en; actualizado_en := d.actualizado_en;
      vehiculos := s.vehiculos; hay_ocultos := s.hay_ocultos; pagada := s.pagada; faltan := s.faltan;
      return next;
      v_hallados := v_hallados + 1;
      exit when v_hallados >= v_n;
    end loop;
    exit when v_hallados >= v_n or v_leidas < v_lote;
  end loop;
end;
$$;


ALTER FUNCTION "public"."declaraciones_listar"("p_desde" timestamp with time zone, "p_id" "uuid", "p_tope" integer, "p_filtros" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."declaraciones_listar"("p_desde" timestamp with time zone, "p_id" "uuid", "p_tope" integer, "p_filtros" "jsonb") IS 'Las declaraciones de aduana que quien llama ve (con logistica.aduana.gestionar, todas; con logistica.ver, las que tienen un vehículo vivo que ve), por cursor (creado_en desc, id desc) sobre declaraciones_aduana_creado_idx, con filtros canal, pagada y q. Por fila: vehiculos y faltan (de los que ve), hay_ocultos, pagada (de todos los vivos, D31). Hasta el tope más una. Sin total (6.07-3).';



