    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  new.actualizado_en := greatest(clock_timestamp(), old.actualizado_en + interval '1 microsecond');
  return new;
end;
$$;


ALTER FUNCTION "public"."dinero_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."documento_editar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  d public.documentos; td public.tipos_documento; k text; v_nota text; v_emitido date; v_vence date; v_portal boolean;
  v_admitidas constant text[] := array['emitido_el', 'vence_el', 'nota', 'visible_portal'];
begin
  perform public.assert_activo();
  if p_cambios is null or jsonb_typeof(p_cambios) <> 'object' then
    raise exception 'Los cambios van como un objeto.' using errcode = '22023', hint = 'cambios';
  end if;
  for k in select jsonb_object_keys(p_cambios) loop
    if not (k = any (v_admitidas)) then
      raise exception 'No se puede cambiar «%» de un documento.', k using errcode = '22023', hint = k;
    end if;
  end loop;
  select * into d from public.documentos x where x.id = p_id for update;
  if not found or d.eliminado_en is not null then
    raise exception 'Ese documento ya no existe.' using errcode = 'PT409';
  end if;
  if p_cambios ? 'visible_portal'
     and not public.puede_unidad(d.vehiculo_id, d.repuesto_id, 'logistica.documentos.aprobar', 'repuestos.documentos.aprobar') then
    raise exception 'Sólo quien aprueba documentos decide si se ve en el portal.' using errcode = '42501', hint = 'visible_portal';
  end if;
  if not public._documento_puede_tocar(d.vehiculo_id, d.repuesto_id, d.subido_por, d.estado) then
    raise exception 'No puedes editar este documento.' using errcode = '42501';
  end if;
  perform public._exigir_version(d.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este documento mientras lo editabas.');

  v_nota := d.nota; v_emitido := d.emitido_el; v_vence := d.vence_el; v_portal := d.visible_portal;
  if p_cambios ? 'nota' then
    if jsonb_typeof(p_cambios -> 'nota') not in ('string', 'null') or char_length(p_cambios ->> 'nota') > 2000 then
      raise exception 'La nota admite hasta 2000 caracteres.' using errcode = '22023', hint = 'nota';
    end if;
    v_nota := nullif(btrim(p_cambios ->> 'nota'), '');
  end if;
  if p_cambios ? 'visible_portal' then
    if jsonb_typeof(p_cambios -> 'visible_portal') <> 'boolean' then
      raise exception '«Visible en el portal» es sí o no.' using errcode = '22023', hint = 'visible_portal';
    end if;
    v_portal := (p_cambios -> 'visible_portal')::boolean;
  end if;
  -- Las fechas se revalidan sólo si cambian (C8.5): editar la nota no traba un tipo que cambió de modo.
  if p_cambios ? 'emitido_el' or p_cambios ? 'vence_el' then
    select * into td from public.tipos_documento t where t.id = d.tipo_documento_id;
    if p_cambios ? 'emitido_el' then v_emitido := public._documento_fecha(p_cambios, 'emitido_el'); end if;
    if p_cambios ? 'vence_el' then
      v_vence := public._documento_fecha(p_cambios, 'vence_el');
    elsif td.modo_vencimiento = 'renovar' then
      v_vence := null;
    end if;
    v_vence := public._documento_vence(td.modo_vencimiento, td.vigencia_dias, v_emitido, v_vence, d.creado_en::date);
  end if;

  update public.documentos x
     set nota = v_nota, emitido_el = v_emitido, vence_el = v_vence, visible_portal = v_portal
   where x.id = d.id
  returning * into d;
  return jsonb_build_object('id', d.id, 'actualizado_en', d.actualizado_en);
end;
$$;


ALTER FUNCTION "public"."documento_editar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."documento_editar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") IS 'Edita emitido_el, vence_el, nota o visible_portal de un documento vivo (si no existe, PT409; otra clave, 22023 con la clave). visible_portal pide la clave de aprobar (42501/visible_portal); lo demás, quien aprueba o quien lo subió mientras siga «subido» con la clave de subir (42501). La versión vieja da PT409. Las fechas se revalidan según el modo del tipo sólo si cambian (22023/vence_el); un tipo que no admite el portal da 23514 al encenderlo. Devuelve {id, actualizado_en}. 6.05.';



CREATE OR REPLACE FUNCTION "public"."documento_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d public.documentos;
begin
  perform public.assert_activo();
  select * into d from public.documentos x where x.id = p_id for update;
  if not found or d.eliminado_en is not null then
    raise exception 'Ese documento ya no existe.' using errcode = 'PT409';
  end if;
  if not public._documento_puede_tocar(d.vehiculo_id, d.repuesto_id, d.subido_por, d.estado) then
    raise exception 'No puedes eliminar este documento.' using errcode = '42501';
  end if;
  perform public._exigir_version(d.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este documento mientras lo eliminabas.');
  update public.documentos x set eliminado_en = now(), eliminado_por = (select auth.uid()) where x.id = d.id;
  perform public._encolar_para_limpiar('documentos', array[d.ruta], false);
  return jsonb_build_object('id', d.id);
end;
$$;


ALTER FUNCTION "public"."documento_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."documento_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) IS 'Elimina (borrado suave, sin restaurar) un documento vivo (si no existe, PT409): quien aprueba o quien lo subió mientras siga «subido» con la clave de subir (42501, que se mira con logistica.documentos.aprobar / repuestos.documentos.aprobar y logistica.documentos.subir / repuestos.documentos.subir). La versión vieja da PT409. El que exige la fase actual no se elimina (documento_exigido, 23514). Encola el objeto si ya ninguna fila viva lo usa. Devuelve {id}. 6.05.';



CREATE OR REPLACE FUNCTION "public"."documento_exigido"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_fase uuid; v_unidad uuid := coalesce(old.vehiculo_id, old.repuesto_id); r record; n int; v_min int; v_despues boolean;
begin
  if old.vehiculo_id is not null then
    select v.fase_id into v_fase from public.vehiculos v where v.id = old.vehiculo_id for share;
  else
    select i.fase_id into v_fase from public.repuestos_items i where i.id = old.repuesto_id for share;
  end if;
  -- Sin fase, o el documento ya no contaba (vencido): no hay nada que proteger.
  if v_fase is null or (old.vence_el is not null and old.vence_el < current_date) then
    return new;
  end if;
  v_despues := new.estado = 'aprobado' and new.eliminado_en is null and (new.vence_el is null or new.vence_el >= current_date);
  perform pg_advisory_xact_lock(hashtextextended('documento_exigido:' || v_unidad::text || ':' || old.tipo_documento_id::text, 0));
  for r in select q.min_archivos, q.max_archivos, q.formatos, f.nombre as fase_nombre
           from public.fases_requisitos q join public.fases f on f.id = q.fase_id
           where q.fase_id = v_fase and q.tipo = 'documento' and q.bloqueante and q.tipo_documento_id = old.tipo_documento_id loop
    -- Con el predicado de evaluar_requisitos (base.sql:11152): aprobado, vivo, sin vencer y con un formato del requisito.
    if (r.formatos is null or old.mime is null or old.mime = any (r.formatos))
       and not (v_despues and (r.formatos is null or new.mime is null or new.mime = any (r.formatos))) then
      v_min := coalesce(r.min_archivos, 1);
      -- Se cuentan a lo sumo max + 1 (o min + 1): basta para saber si hoy cumple y si sin éste deja de cumplir.
      select count(*) into n from (
        select 1 from public.documentos doc
        where doc.vehiculo_id is not distinct from old.vehiculo_id and doc.repuesto_id is not distinct from old.repuesto_id
          and doc.tipo_documento_id = old.tipo_documento_id and doc.estado = 'aprobado' and doc.eliminado_en is null
          and (doc.vence_el is null or doc.vence_el >= current_date)
          and (r.formatos is null or doc.mime is null or doc.mime = any (r.formatos))
        limit coalesce(r.max_archivos, v_min) + 1) t;
      if n >= v_min and (r.max_archivos is null or n <= r.max_archivos) and n - 1 < v_min then
        raise exception 'La fase «%» exige este documento. Sube el reemplazo antes de quitarlo.', r.fase_nombre using errcode = '23514';
      end if;
    end if;
  end loop;
  return new;
end;
$$;


ALTER FUNCTION "public"."documento_exigido"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."documento_exigido"() IS 'Trigger before update de documentos (un aprobado vivo que cambia): si hoy hace cumplir un requisito bloqueante de la fase actual de su unidad y sin él deja de cumplirse, 23514 «La fase «…» exige este documento.». Toma la unidad for share y un candado por unidad y tipo. 6.05.';



CREATE OR REPLACE FUNCTION "public"."documento_registrar"("p_id" "uuid", "p_vehiculos" "uuid"[], "p_repuesto" "uuid", "p_tipo" "uuid", "p_ruta" "text", "p_nombre" "text", "p_mime" "text", "p_bytes" integer, "p_emitido_el" "date", "p_vence_el" "date", "p_nota" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_unidades uuid[]; v_ids uuid[]; td public.tipos_documento; a record; v_vence date; v_nota text := nullif(btrim(p_nota), ''); n int;
begin
  perform public.assert_activo();
  v_unidades := public._documento_validar_unidades(p_vehiculos, p_repuesto);
  if p_id is null then
    raise exception 'Falta el identificador del registro.' using errcode = '22023', hint = 'id';
  end if;
  v_ids := array(select md5(p_id::text || ':' || u::text)::uuid from unnest(v_unidades) u);
  if exists (select 1 from public.documentos d where d.id = any (v_ids)) then
    return public._documento_ya_registrado(v_ids, p_ruta);
  end if;
  td := public._documento_tipo_de(p_vehiculos, p_repuesto, p_tipo);
  select * into a from public._documento_validar_archivo(p_ruta, v_unidades, p_nombre, p_mime, p_bytes, td.formatos);
  v_vence := public._documento_vence(td.modo_vencimiento, td.vigencia_dias, p_emitido_el, p_vence_el, current_date);
  if char_length(v_nota) > 2000 then
    raise exception 'La nota admite hasta 2000 caracteres.' using errcode = '22023', hint = 'nota';
  end if;
  insert into public.documentos (id, vehiculo_id, repuesto_id, tipo_documento_id, estado, ruta, nombre_archivo, mime, bytes, emitido_el, vence_el, nota)
  select md5(p_id::text || ':' || u::text)::uuid, case when p_repuesto is null then u end, p_repuesto, td.id, 'subido', p_ruta, btrim(p_nombre),
         a.o_mime, a.o_bytes, p_emitido_el, v_vence, v_nota
  from unnest(v_unidades) u
  on conflict (id) do nothing;
  get diagnostics n = row_count;
  if n < cardinality(v_ids) then
    -- Un reintento simultáneo con el mismo p_id escribió antes: si calza, son las mismas filas.
    return public._documento_ya_registrado(v_ids, p_ruta);
  end if;
  return public._documentos_de(v_ids);
end;
$$;


ALTER FUNCTION "public"."documento_registrar"("p_id" "uuid", "p_vehiculos" "uuid"[], "p_repuesto" "uuid", "p_tipo" "uuid", "p_ruta" "text", "p_nombre" "text", "p_mime" "text", "p_bytes" integer, "p_emitido_el" "date", "p_vence_el" "date", "p_nota" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."documento_registrar"("p_id" "uuid", "p_vehiculos" "uuid"[], "p_repuesto" "uuid", "p_tipo" "uuid", "p_ruta" "text", "p_nombre" "text", "p_mime" "text", "p_bytes" integer, "p_emitido_el" "date", "p_vence_el" "date", "p_nota" "text") IS 'Registra un archivo ya subido al bucket documentos para 1 a 100 vehículos (una fila por vehículo, la misma ruta) o un repuesto, en «subido». Pide logistica.documentos.subir en cada vehículo o repuestos.documentos.subir en el repuesto (42501). El tipo activo y global o del flujo de cada unidad (22023/tipo); ruta en la carpeta de una de las unidades, objeto existente, mime en los formatos del tipo, 1 byte a 25 MB (22023 con hint); vencimiento según el modo del tipo (22023/vence_el). Idempotente por p_id: reintentar devuelve las mismas filas; con otros datos, 23505/id. Devuelve [{id, vehiculo_id, repuesto_id, actualizado_en}]. 6.05.';



CREATE OR REPLACE FUNCTION "public"."documento_rescatar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.ruta is not null then
    perform public.storage_gc_rescatar('documentos', new.ruta);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."documento_rescatar"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."documento_rescatar"() IS 'Trigger before insert de documentos: saca la ruta de la cola de limpieza de storage (o avisa si ya se está limpiando). 6.05.';



CREATE OR REPLACE FUNCTION "public"."documento_revisar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_estado" "public"."estado_documento", "p_motivo" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare d public.documentos; v_motivo text := nullif(btrim(p_motivo), '');
begin
  perform public.assert_activo();
  select * into d from public.documentos x where x.id = p_id for update;
  if not found or d.eliminado_en is not null then
    raise exception 'Ese documento ya no existe.' using errcode = 'PT409';
  end if;
  if not public.puede_unidad(d.vehiculo_id, d.repuesto_id, 'logistica.documentos.aprobar', 'repuestos.documentos.aprobar') then
    raise exception 'No puedes revisar este documento.' using errcode = '42501';
  end if;
  perform public._exigir_version(d.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este documento mientras lo revisabas.');
  if p_estado is null or p_estado not in ('aprobado', 'rechazado') then
    raise exception 'Un documento se aprueba o se rechaza.' using errcode = '22023', hint = 'estado';
  end if;
  if p_estado = 'rechazado' and (v_motivo is null or char_length(v_motivo) > 500) then
    raise exception 'Rechazar pide un motivo (hasta 500 caracteres).' using errcode = '22023', hint = 'motivo';
  end if;
  update public.documentos x
     set estado = p_estado, motivo_rechazo = case when p_estado = 'rechazado' then v_motivo end
   where x.id = d.id
  returning * into d;
  return jsonb_build_object('id', d.id, 'estado', d.estado, 'actualizado_en', d.actualizado_en);
end;
$$;


ALTER FUNCTION "public"."documento_revisar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_estado" "public"."estado_documento", "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."documento_revisar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_estado" "public"."estado_documento", "p_motivo" "text") IS 'Aprueba o rechaza un documento vivo (si no existe, PT409). Pide logistica.documentos.aprobar del vehículo o repuestos.documentos.aprobar del repuesto (42501), antes que la versión (PT409). Rechazar pide motivo de 1 a 500 (22023/motivo); otro estado, 22023/estado. Aprobar limpia el motivo. Quitar un aprobado que exige la fase actual lo impide documento_exigido. Devuelve {id, estado, actualizado_en}. 6.05.';



CREATE OR REPLACE FUNCTION "public"."documento_sellos"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    new.subido_por := (select auth.uid());
    if new.estado = 'aprobado' then new.estado := 'subido'; end if;   -- nadie nace aprobado
  elsif new.estado is distinct from old.estado and new.estado in ('aprobado', 'rechazado') then
    new.revisado_por := (select auth.uid()); new.revisado_en := now();
    if new.estado = 'rechazado' and coalesce(new.motivo_rechazo, '') = '' then
      raise exception 'Rechazar pide motivo.' using errcode = '23514';
    end if;
  end if;
  if new.visible_portal and (tg_op = 'INSERT' or not old.visible_portal)
     and not exists (select 1 from public.tipos_documento td where td.id = new.tipo_documento_id and td.visible_portal_permitido) then
    raise exception 'Este tipo de documento no puede mostrarse en el portal.' using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."documento_sellos"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."documento_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  new.actualizado_en := greatest(clock_timestamp(), old.actualizado_en + interval '1 microsecond');
  return new;
end;
$$;


ALTER FUNCTION "public"."documento_version"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."documento_version"() IS 'Trigger before update de documentos: la versión de la fila con greatest(clock_timestamp(), anterior + 1 µs), para que se mueva dos veces en una transacción. 6.05.';



CREATE OR REPLACE FUNCTION "public"."documentos_vencimientos"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c_lote constant int := 200;
  c_tope constant int := 2000;
  c_meses constant text[] := array['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
  v_hoy date; v_zona text; v_max int;
  v_ids uuid[]; v_vence date; v_id uuid; d record;
  v_origen uuid; v_usuarios uuid[]; v_todos boolean[];
  v_vistos int := 0; v_n int := 0; v_cuerpo text;
  -- Quien está en una baja en curso deja de contar su cartera (la unidad propia, sí).
  v_fuera constant uuid[] := public._bajas_en_curso();
begin
  select (now() at time zone e.zona_horaria)::date, e.zona_horaria into v_hoy, v_zona from public.ajustes_empresa e where e.id = 1;
  select max(t.aviso_dias) into v_max from public.tipos_documento t where t.modo_vencimiento in ('renovar', 'solicitar') and t.aviso_dias is not null;
  if v_hoy is null or v_max is null then
    return 0;
  end if;
  loop
    -- documentos_vencen_idx (vence_el) where aprobado y vivo: rango [hoy, hoy + el mayor aviso]; el cursor (vence_el, id) ordena parcial por id y
    -- recorre también los de repuestos (cuentan para el tope).
    if v_id is null then
      v_ids := array(select x.id from public.documentos x
                      where x.estado = 'aprobado' and x.eliminado_en is null and x.vence_el is not null and x.vence_el between v_hoy and v_hoy + v_max
                      order by x.vence_el, x.id limit least(c_lote, c_tope - v_vistos));
    else
      v_ids := array(select x.id from public.documentos x
                      where x.estado = 'aprobado' and x.eliminado_en is null and x.vence_el is not null and x.vence_el between v_hoy and v_hoy + v_max
                        and (x.vence_el, x.id) > (v_vence, v_id)
                      order by x.vence_el, x.id limit least(c_lote, c_tope - v_vistos));
    end if;
    exit when cardinality(v_ids) = 0;
    v_vistos := v_vistos + cardinality(v_ids);
    select x.vence_el, x.id into v_vence, v_id from public.documentos x where x.id = any (v_ids) order by x.vence_el desc, x.id desc limit 1;
    for d in
      select doc.id, doc.vehiculo_id, doc.vence_el, v.origen_id, v.titulo, v.creado_por, v.lead_id, t.nombre as tipo, t.modo_vencimiento, t.aviso_dias
        from public.documentos doc
        join public.tipos_documento t on t.id = doc.tipo_documento_id
        join public.vehiculos v on v.id = doc.vehiculo_id
       where doc.id = any (v_ids) and v.eliminado_en is null
         and t.modo_vencimiento in ('renovar', 'solicitar') and t.aviso_dias is not null and doc.vence_el - t.aviso_dias <= v_hoy
       order by v.origen_id, doc.vence_el, doc.id
    loop
      if v_origen is distinct from d.origen_id then
        v_origen := d.origen_id;
        select coalesce(array_agg(x.usuario_id order by x.usuario_id), '{}'), coalesce(array_agg(x.todos order by x.usuario_id), '{}')
          into v_usuarios, v_todos from public._alertas_destinatarios('logistica.documentos.subir', d.origen_id) x;
      end if;
      v_cuerpo := d.titulo || ' · vence el ' || extract(day from d.vence_el)::int || ' ' || c_meses[extract(month from d.vence_el)::int] || ' '
                  || extract(year from d.vence_el)::int || '. '
                  || case when d.modo_vencimiento = 'renovar' then 'Sube el nuevo para renovarlo.' else 'Pide uno nuevo antes de que venza.' end;
      for i in 1 .. cardinality(v_usuarios) loop
        if v_todos[i] or d.creado_por = v_usuarios[i]
           or (d.lead_id is not null and v_usuarios[i] <> all (v_fuera) and exists (select 1 from public.leads_asesores la
                where la.lead_id = d.lead_id and la.usuario_id = v_usuarios[i] and la.revocado_en is null)) then
          v_n := v_n + public._documento_vencimiento_avisar(d.id, d.vehiculo_id, 'Documento por vencer: «' || d.tipo || '»', v_cuerpo,
                                                            ((d.vence_el - d.aviso_dias)::timestamp at time zone v_zona), v_usuarios[i]);
        end if;
      end loop;
    end loop;
    exit when cardinality(v_ids) < c_lote or v_vistos >= c_tope;
  end loop;
  return v_n;
end;
$$;


ALTER FUNCTION "public"."documentos_vencimientos"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."documentos_vencimientos"() IS 'Alertas (6.12): job documentos-vencimientos diario. Avisa documento_por_vencer una vez por persona y documento desde que empieza su ventana (vence_el - aviso_dias) a quien tiene logistica.documentos.subir del origen; el texto cambia con modo_vencimiento. De a 200 y hasta 2.000 documentos por corrida. Devuelve los intentos.';



CREATE OR REPLACE FUNCTION "public"."embudo_crear"("p_id" "uuid", "p_nombre" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_yo uuid := public._embudos_puedo(); e public.embudos; v_nombre text;
begin
  if p_id is null then
    raise exception 'Falta el identificador del embudo.' using errcode = '22023';
  end if;
  perform public._embudos_candado(v_yo);
  select * into e from public.embudos x where x.id = p_id;
  if found then
    if e.usuario_id = v_yo then
      return jsonb_build_object('resultado', 'repetido', 'embudo', public._embudo_json(e.id));
    end if;
    raise exception 'No pudimos crear este embudo. Vuelve a intentarlo.' using errcode = '22023';
  end if;
  v_nombre := public._embudo_nombre(p_nombre);
  perform public._embudo_nombre_libre(v_yo, v_nombre, null);
  if (select count(*) from public.embudos x where x.usuario_id = v_yo) >= 10 then
    raise exception 'Puedes tener hasta 10 embudos. Elimina uno para crear otro.' using errcode = '22023', hint = 'nombre';
  end if;
  begin
    perform public._embudo_insertar(v_yo, p_id, v_nombre,
      not exists (select 1 from public.embudos x where x.usuario_id = v_yo),
      jsonb_build_array(
        jsonb_build_object('nombre', 'Nueva', 'color', 'gris', 'es_inicial', true),
        jsonb_build_object('nombre', 'Ganada', 'color', 'verde', 'es_ganada', true),
        jsonb_build_object('nombre', 'Perdida', 'color', 'rojo', 'es_perdida', true)));
  exception when unique_violation then
    raise exception 'No pudimos crear este embudo. Vuelve a intentarlo.' using errcode = '22023';
  end;
  return jsonb_build_object('resultado', 'creado', 'embudo', public._embudo_json(p_id));
end;
$$;


ALTER FUNCTION "public"."embudo_crear"("p_id" "uuid", "p_nombre" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."embudo_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_yo uuid := public._embudos_puedo(); e public.embudos; n int;
begin
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  perform public._embudos_candado(v_yo);
  select * into e from public.embudos x where x.id = p_id and x.usuario_id = v_yo for update;
  if not found then
    return jsonb_build_object('resultado', 'sin_cambios');
  end if;
  if e.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._embudo_conflicto(e.actualizado_en);
  end if;
  if e.es_default then
    raise exception 'El embudo por defecto no se elimina: puedes renombrarlo.' using errcode = '23514';
  end if;
  select count(*) into n from public.oportunidades o where o.embudo_id = e.id and o.eliminado_en is null;
  if n > 0 then
    raise exception 'Este embudo tiene % %. Elimínalas antes de eliminarlo.', n,
      case when n = 1 then 'oportunidad' else 'oportunidades' end using errcode = '23514';
  end if;
  delete from public.oportunidades o where o.embudo_id = e.id;
  delete from public.embudos x where x.id = e.id;
  return jsonb_build_object('resultado', 'eliminado');
end;
$$;


ALTER FUNCTION "public"."embudo_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."embudo_etapa_pagina"("p_etapa" "uuid", "p_antes_en" timestamp with time zone, "p_antes_id" "uuid", "p_tope" integer DEFAULT 50, "p_buscar" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_n int := public._acotar_pagina(p_tope, 50, 100);
  v_patron text := public._embudo_patron(p_buscar);
  v_tarjetas jsonb;
  v_hay_mas boolean;
begin
  if p_antes_en is null then
    select coalesce(jsonb_agg(p.tarjeta order by p.en desc, p.id desc) filter (where p.k <= v_n), '[]'::jsonb),
           coalesce(bool_or(p.k > v_n), false)
      into v_tarjetas, v_hay_mas
      from (select public._tarjeta_json(o, jsonb_build_object('id', l.id,
                                         'numero', (select g.numero from public.leads_numeros_globales g where g.lead_id = l.id),
                                         'numero_propio', (select np.numero from public.leads_numeros_propios np where np.lead_id = l.id),
                                         'nombre', l.nombre),
                                           case when v.id is not null then jsonb_build_object('id', v.id, 'titulo', v.titulo, 'numero', v.numero) end) as tarjeta,
                   o.ultima_actividad_en as en, o.id,
                   row_number() over (order by o.ultima_actividad_en desc, o.id desc) as k
              from public.oportunidades o
              join public.leads l on l.id = o.lead_id
              left join public.vehiculos v on v.id = o.vehiculo_id
             where o.etapa_id = p_etapa
               and (v_patron is null or o.titulo ilike v_patron or l.nombre ilike v_patron)
             order by o.ultima_actividad_en desc, o.id desc
             limit v_n + 1) p;
  else
    select coalesce(jsonb_agg(p.tarjeta order by p.en desc, p.id desc) filter (where p.k <= v_n), '[]'::jsonb),
           coalesce(bool_or(p.k > v_n), false)
      into v_tarjetas, v_hay_mas
      from (select public._tarjeta_json(o, jsonb_build_object('id', l.id,
                                         'numero', (select g.numero from public.leads_numeros_globales g where g.lead_id = l.id),
                                         'numero_propio', (select np.numero from public.leads_numeros_propios np where np.lead_id = l.id),
                                         'nombre', l.nombre),
                                           case when v.id is not null then jsonb_build_object('id', v.id, 'titulo', v.titulo, 'numero', v.numero) end) as tarjeta,
                   o.ultima_actividad_en as en, o.id,
                   row_number() over (order by o.ultima_actividad_en desc, o.id desc) as k
              from public.oportunidades o
              join public.leads l on l.id = o.lead_id
              left join public.vehiculos v on v.id = o.vehiculo_id
             where o.etapa_id = p_etapa
               and (o.ultima_actividad_en, o.id) < (p_antes_en, p_antes_id)
               and (v_patron is null or o.titulo ilike v_patron or l.nombre ilike v_patron)
             order by o.ultima_actividad_en desc, o.id desc
             limit v_n + 1) p;
  end if;
  return jsonb_build_object('tarjetas', v_tarjetas, 'hay_mas', v_hay_mas);
end;
$$;


ALTER FUNCTION "public"."embudo_etapa_pagina"("p_etapa" "uuid", "p_antes_en" timestamp with time zone, "p_antes_id" "uuid", "p_tope" integer, "p_buscar" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."embudo_etapas_guardar"("p_embudo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_etapas" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  e public.embudos; x jsonb; v_n int; v_ids uuid[] := '{}'::uuid[]; v_id uuid; v_nombres text[] := '{}'::text[]; v_nombre text;
  v_color text; v_ini int := 0; v_gan int := 0; v_per int := 0; v_nueva jsonb := '[]'::jsonb;
  v_quitada record;
begin
  perform public._embudos_puedo();
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  e := public._embudo_mio(p_embudo);
  if p_etapas is null or jsonb_typeof(p_etapas) <> 'array' then
    raise exception 'Las etapas tienen que ser una lista.' using errcode = '22023', hint = 'etapas';
  end if;
  v_n := jsonb_array_length(p_etapas);
  if v_n < 3 or v_n > 12 then
    raise exception 'Un embudo lleva entre 3 y 12 etapas.' using errcode = '22023', hint = 'etapas';
  end if;
  for x in select * from jsonb_array_elements(p_etapas) loop
    if jsonb_typeof(x) <> 'object' then
      raise exception 'Una de las etapas llegó incompleta. Recarga e intenta de nuevo.' using errcode = '22023', hint = 'etapas';
    end if;
    v_id := coalesce(public._uuid_de(x -> 'id', 'etapas'), gen_random_uuid());
    if v_id = any (v_ids) then
      raise exception 'Una etapa llegó dos veces. Recarga e intenta de nuevo.' using errcode = '22023', hint = 'etapas';
    end if;
    if exists (select 1 from public.embudos_etapas s where s.id = v_id and s.embudo_id <> e.id) then
      raise exception 'Una de las etapas no es de este embudo. Recarga e intenta de nuevo.' using errcode = '22023', hint = 'etapas';
    end if;
    v_nombre := btrim(coalesce(x ->> 'nombre', ''));
    if char_length(v_nombre) not between 1 and 30 then
      raise exception 'El nombre de una etapa lleva entre 1 y 30 caracteres.' using errcode = '22023', hint = 'etapas';
    end if;
    if exists (select 1 from unnest(v_nombres) n where lower(n) = lower(v_nombre)) then
      raise exception 'Hay dos etapas «%». Cámbiale el nombre a una.', v_nombre using errcode = '22023', hint = 'etapas';
    end if;
    v_color := x ->> 'color';
    if v_color is null or not (v_color = any (public._etiquetas_paleta())) then
      raise exception 'Elige un color de la paleta para «%».', v_nombre using errcode = '22023', hint = 'etapas';
    end if;
    if coalesce((x ->> 'es_ganada')::boolean, false) and coalesce((x ->> 'es_perdida')::boolean, false) then
      raise exception '«%» no puede ser ganada y perdida a la vez.', v_nombre using errcode = '22023', hint = 'etapas';
    end if;
    if coalesce((x ->> 'es_inicial')::boolean, false)
       and (coalesce((x ->> 'es_ganada')::boolean, false) or coalesce((x ->> 'es_perdida')::boolean, false)) then
      raise exception 'La etapa inicial no puede ser ganada ni perdida.' using errcode = '22023', hint = 'etapas';
    end if;
    v_ini := v_ini + case when coalesce((x ->> 'es_inicial')::boolean, false) then 1 else 0 end;
    v_gan := v_gan + case when coalesce((x ->> 'es_ganada')::boolean, false) then 1 else 0 end;
    v_per := v_per + case when coalesce((x ->> 'es_perdida')::boolean, false) then 1 else 0 end;
    v_ids := v_ids || v_id;
    v_nombres := v_nombres || v_nombre;
    v_nueva := v_nueva || jsonb_build_object('id', v_id, 'nombre', v_nombre, 'color', v_color,
      'es_inicial', coalesce((x ->> 'es_inicial')::boolean, false),
      'es_ganada', coalesce((x ->> 'es_ganada')::boolean, false),
      'es_perdida', coalesce((x ->> 'es_perdida')::boolean, false));
  end loop;
  if v_ini <> 1 then
    raise exception 'Marca una sola etapa como inicial.' using errcode = '22023', hint = 'etapas';
  end if;
  if v_gan < 1 then
    raise exception 'Hace falta al menos una etapa ganada.' using errcode = '22023', hint = 'etapas';
  end if;
  if v_per < 1 then
    raise exception 'Hace falta al menos una etapa perdida.' using errcode = '22023', hint = 'etapas';
  end if;

  if v_nueva = (public._embudo_json(e.id) -> 'etapas') then
    return jsonb_build_object('resultado', 'sin_cambios', 'embudo', public._embudo_json(e.id));
  end if;
  if e.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._embudo_conflicto(e.actualizado_en);
  end if;

  -- Una etapa que se quita no puede llevarse oportunidades vivas; las eliminadas se van con ella.
  for v_quitada in
    select s.id, s.nombre, (select count(*) from public.oportunidades o where o.etapa_id = s.id and o.eliminado_en is null) as n
      from public.embudos_etapas s where s.embudo_id = e.id and not (s.id = any (v_ids)) order by s.orden, s.id
  loop
    if v_quitada.n > 0 then
      raise exception '«%» tiene % %: muévelas antes de quitarla.', v_quitada.nombre, v_quitada.n,
        case when v_quitada.n = 1 then 'oportunidad' else 'oportunidades' end using errcode = '23514', hint = 'etapas';
    end if;
    delete from public.oportunidades o where o.etapa_id = v_quitada.id;
    delete from public.embudos_etapas s where s.id = v_quitada.id;
  end loop;

  -- Primero se liberan los nombres y la inicial (un intercambio de nombres no choca con el índice),
  -- después se escriben los valores finales.
  update public.embudos_etapas s set nombre = '~' || left(replace(s.id::text, '-', ''), 29), es_inicial = false
   where s.embudo_id = e.id;
  insert into public.embudos_etapas (id, embudo_id, nombre, color, es_inicial, es_ganada, es_perdida, orden)
  select (y ->> 'id')::uuid, e.id, '~' || left(replace(y ->> 'id', '-', ''), 29), y ->> 'color', false, false, false, 0
    from jsonb_array_elements(v_nueva) y
   where not exists (select 1 from public.embudos_etapas s where s.id = (y ->> 'id')::uuid);
  update public.embudos_etapas s set
    nombre = y ->> 'nombre', color = y ->> 'color', es_inicial = (y ->> 'es_inicial')::boolean,
    es_ganada = (y ->> 'es_ganada')::boolean, es_perdida = (y ->> 'es_perdida')::boolean, orden = (o * 10)::smallint
    from jsonb_array_elements(v_nueva) with ordinality t (y, o)
   where s.id = (y ->> 'id')::uuid;

  -- Una etapa que cambió de final a abierta (o al revés) cambia el estado de lo que tiene.
  update public.oportunidades o set
    estado = case when s.es_ganada then 'ganada' when s.es_perdida then 'perdida' else 'abierta' end::public.estado_oportunidad,
    motivo_perdida = case when s.es_perdida then o.motivo_perdida end
    from public.embudos_etapas s
   where s.id = o.etapa_id and s.embudo_id = e.id and o.estado <> 'cancelada'
     and o.estado <> case when s.es_ganada then 'ganada' when s.es_perdida then 'perdida' else 'abierta' end::public.estado_oportunidad;

  update public.embudos x set actualizado_en = greatest(clock_timestamp(), e.actualizado_en + interval '1 microsecond')
   where x.id = e.id;
  return jsonb_build_object('resultado', 'guardado', 'embudo', public._embudo_json(e.id));
end;
$$;


ALTER FUNCTION "public"."embudo_etapas_guardar"("p_embudo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_etapas" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."embudo_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_yo uuid := public._embudos_puedo(); e public.embudos; v_nombre text;
begin
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  e := public._embudo_mio(p_id);
  v_nombre := public._embudo_nombre(p_nombre);
  if v_nombre = e.nombre then
    return jsonb_build_object('resultado', 'sin_cambios', 'embudo', public._embudo_json(e.id));
  end if;
  if e.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._embudo_conflicto(e.actualizado_en);
  end if;
  perform public._embudo_nombre_libre(v_yo, v_nombre, e.id);
  update public.embudos x set nombre = v_nombre,
    actualizado_en = greatest(clock_timestamp(), e.actualizado_en + interval '1 microsecond')
  where x.id = e.id;
  return jsonb_build_object('resultado', 'guardado', 'embudo', public._embudo_json(e.id));
end;
$$;


ALTER FUNCTION "public"."embudo_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."embudo_plantilla_guardar"("p_etapas" "jsonb", "p_actualizado_en_esperado" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare a public.ajustes_leads; v_nueva jsonb;
begin
  perform public.assert_permiso('leads.configurar');
  v_nueva := case when p_etapas is null then null else public._embudo_plantilla_normalizar(p_etapas) end;
  select * into a from public.ajustes_leads where id = 1 for update;
  perform public._exigir_version(a.embudo_actualizado_en, p_actualizado_en_esperado,
    'Alguien cambió la plantilla del embudo mientras la veías. Recarga para seguir.');
  if v_nueva is not distinct from a.embudo_etapas then
    return a.embudo_actualizado_en;
  end if;
  update public.ajustes_leads
     set embudo_etapas = v_nueva,
         embudo_actualizado_en = greatest(clock_timestamp(), a.embudo_actualizado_en + interval '1 microsecond')
   where id = 1
  returning embudo_actualizado_en into a.embudo_actualizado_en;
  return a.embudo_actualizado_en;
end;
$$;


ALTER FUNCTION "public"."embudo_plantilla_guardar"("p_etapas" "jsonb", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."embudo_plantilla_guardar"("p_etapas" "jsonb", "p_actualizado_en_esperado" timestamp with time zone) IS 'Guarda las etapas con que nace un embudo nuevo (null = las seis de fábrica). leads.configurar; 22023 con hint etapas; PT409 con versión vieja. Devuelve la versión. 9.04-4.';



CREATE OR REPLACE FUNCTION "public"."embudo_por_defecto"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_yo uuid := public._embudos_puedo(); v_habia boolean; v_id uuid;
begin
  v_habia := exists (select 1 from public.embudos e where e.usuario_id = v_yo);
  -- En su propia sentencia: `_embudo_json` (STABLE) lee con la foto de la sentencia que la llama, y
  -- en la misma no vería el embudo recién creado.
  v_id := public._embudo_defecto_de(v_yo);
  return jsonb_build_object('resultado', case when v_habia then 'existente' else 'creado' end,
    'embudo', public._embudo_json(v_id));
end;
$$;


ALTER FUNCTION "public"."embudo_por_defecto"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."embudo_tablero"("p_embudo" "uuid", "p_tope" integer DEFAULT 50, "p_tope_total" integer DEFAULT 500, "p_buscar" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with tope as (select public._acotar_pagina(p_tope, 50, 100) as n,
                       public._acotar_pagina(p_tope_total, 500, 1000) as total,
                       public._embudo_patron(p_buscar) as patron)
  select jsonb_build_object(
    'embudo', jsonb_build_object('id', x.id, 'nombre', x.nombre, 'es_default', x.es_default, 'actualizado_en', x.actualizado_en),
    'columnas', coalesce((
      select jsonb_agg(jsonb_build_object(
        'etapa', jsonb_build_object('id', s.id, 'nombre', s.nombre, 'color', s.color,
                   'es_inicial', s.es_inicial, 'es_ganada', s.es_ganada, 'es_perdida', s.es_perdida),
        'total', least(c.leidas, (select total from tope)),
        'total_hay_mas', c.leidas > (select total from tope),
        'hay_mas', c.leidas > (select n from tope),
        'tarjetas', coalesce((
          select jsonb_agg(t.tarjeta order by t.en desc, t.id desc)
            from (select public._tarjeta_json(o, jsonb_build_object('id', l.id,
                                         'numero', (select g.numero from public.leads_numeros_globales g where g.lead_id = l.id),
                                         'numero_propio', (select np.numero from public.leads_numeros_propios np where np.lead_id = l.id),
                                         'nombre', l.nombre),
                                         case when v.id is not null then jsonb_build_object('id', v.id, 'titulo', v.titulo, 'numero', v.numero) end) as tarjeta, o.ultima_actividad_en as en, o.id
                    from public.oportunidades o
                    join public.leads l on l.id = o.lead_id
                    left join public.vehiculos v on v.id = o.vehiculo_id
                   where o.etapa_id = s.id
                     and ((select patron from tope) is null
                          or o.titulo ilike (select patron from tope) or l.nombre ilike (select patron from tope))
                   order by o.ultima_actividad_en desc, o.id desc
                   limit (select n from tope)) t), '[]'::jsonb))
        order by s.orden, s.id)
      from public.embudos_etapas s
      cross join lateral (select count(*)::int as leidas
                            from (select 1 from public.oportunidades o2 join public.leads l2 on l2.id = o2.lead_id
                                   where o2.etapa_id = s.id
                                     and ((select patron from tope) is null
                                          or o2.titulo ilike (select patron from tope) or l2.nombre ilike (select patron from tope))
                                  limit (select total from tope) + 1) q) c
      where s.embudo_id = x.id), '[]'::jsonb))
  from public.embudos x where x.id = p_embudo;
$$;


ALTER FUNCTION "public"."embudo_tablero"("p_embudo" "uuid", "p_tope" integer, "p_tope_total" integer, "p_buscar" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."empresa_con_datos_cargados"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from public.vehiculos)
      or exists (select 1 from public.oportunidades o where o.monto_estimado is not null)
      or exists (select 1 from public.cotizaciones)
      or exists (select 1 from public.gastos)
      or exists (select 1 from public.pagos)
      or exists (select 1 from public.repuestos_compras)
      or exists (select 1 from public.repuestos_cotizaciones);
$$;


ALTER FUNCTION "public"."empresa_con_datos_cargados"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."empresa_guardar_ajustes"("p_cambios" "jsonb", "p_actualizado_en_esperado" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v public.ajustes_empresa;
  v_clave text;
  v_nueva timestamptz;
  v_editables constant text[] := array['nombre', 'razon_social', 'nit', 'direccion', 'ciudad', 'pais', 'telefono', 'whatsapp', 'email',
    'logo_ruta', 'logo_oscuro_ruta', 'color_acento', 'iconos', 'locale', 'zona_horaria', 'moneda_base', 'registro_abierto', 'papelera_dias', 'actividad_dias',
    'limpieza_automatica', 'limpieza_dias_gracia', 'telefono_cc'];
  v_obligatorias constant text[] := array['nombre', 'pais', 'locale', 'zona_horaria', 'moneda_base', 'registro_abierto', 'papelera_dias', 'actividad_dias',
    'limpieza_automatica', 'limpieza_dias_gracia'];
begin
  perform public.assert_permiso('empresa.ajustes.gestionar');
  if p_cambios is null or jsonb_typeof(p_cambios) <> 'object' then
    raise exception 'Faltan los cambios a guardar.';
  end if;
  for v_clave in select jsonb_object_keys(p_cambios) loop
    if not (v_clave = any (v_editables)) then
      raise exception 'El dato «%» no se cambia desde los ajustes de la empresa.', v_clave;
    end if;
    if v_clave = any (v_obligatorias) and nullif(btrim(p_cambios ->> v_clave), '') is null then
      raise exception 'El dato «%» no puede quedar vacío.', v_clave;
    end if;
  end loop;

  select * into v from public.ajustes_empresa where id = 1 for update;
  perform public._exigir_version(v.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió los ajustes de la empresa mientras los editabas.');

  if p_cambios ? 'zona_horaria' then
    begin
      perform now() at time zone (p_cambios ->> 'zona_horaria');
    exception when others then
      raise exception 'La zona horaria «%» no existe.', p_cambios ->> 'zona_horaria';
    end;
  end if;
  -- Con el locale se formatea cada número de la app: uno con otra forma rompería todas las pantallas.
  if p_cambios ? 'locale' and btrim(p_cambios ->> 'locale') !~ '^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$' then
    raise exception 'El formato regional «%» no tiene la forma esperada, como es-BO.', p_cambios ->> 'locale';
  end if;
  if p_cambios ? 'iconos' and jsonb_typeof(p_cambios -> 'iconos') not in ('object', 'null') then
    raise exception 'Los íconos no tienen la forma esperada.';
  end if;
  if p_cambios ? 'telefono_cc' and nullif(btrim(p_cambios ->> 'telefono_cc'), '') is not null
     and btrim(p_cambios ->> 'telefono_cc') !~ '^\+[1-9][0-9]{0,2}$' then
    raise exception 'El código de país lleva un «+» y de 1 a 3 dígitos.' using errcode = '22023', hint = 'telefono_cc';
  end if;
  if p_cambios ? 'limpieza_dias_gracia'
     and (btrim(p_cambios ->> 'limpieza_dias_gracia') !~ '^[0-9]{1,3}$' or (p_cambios ->> 'limpieza_dias_gracia')::int not between 1 and 90) then
    raise exception 'Los días de gracia de la limpieza van de 1 a 90.' using errcode = '22023', hint = 'limpieza_dias_gracia';
  end if;
  if p_cambios ? 'limpieza_automatica' and (p_cambios ->> 'limpieza_automatica') not in ('true', 'false') then
    raise exception 'La limpieza automática se enciende o se apaga.' using errcode = '22023', hint = 'limpieza_automatica';
  end if;
  if p_cambios ? 'moneda_base' and (p_cambios ->> 'moneda_base') is distinct from v.moneda_base::text then
    if not exists (select 1 from public.monedas m where m.codigo::text = p_cambios ->> 'moneda_base' and m.activa) then
      raise exception 'La moneda base tiene que ser una de las monedas activas.';
    end if;
    if public.empresa_con_datos_cargados() then
      raise exception 'La moneda base no se cambia con datos cargados: los montos ya están guardados en %.', v.moneda_base;
    end if;
  end if;

  update public.ajustes_empresa e set
    nombre = case when p_cambios ? 'nombre' then btrim(p_cambios ->> 'nombre') else e.nombre end,
    razon_social = case when p_cambios ? 'razon_social' then nullif(btrim(p_cambios ->> 'razon_social'), '') else e.razon_social end,
    nit = case when p_cambios ? 'nit' then nullif(btrim(p_cambios ->> 'nit'), '') else e.nit end,
    direccion = case when p_cambios ? 'direccion' then nullif(btrim(p_cambios ->> 'direccion'), '') else e.direccion end,
    ciudad = case when p_cambios ? 'ciudad' then nullif(btrim(p_cambios ->> 'ciudad'), '') else e.ciudad end,
    pais = case when p_cambios ? 'pais' then btrim(p_cambios ->> 'pais') else e.pais end,
    telefono = case when p_cambios ? 'telefono' then nullif(btrim(p_cambios ->> 'telefono'), '') else e.telefono end,
    telefono_cc = case when p_cambios ? 'telefono_cc' then nullif(btrim(p_cambios ->> 'telefono_cc'), '') else e.telefono_cc end,
    whatsapp = case when p_cambios ? 'whatsapp' then nullif(btrim(p_cambios ->> 'whatsapp'), '') else e.whatsapp end,
    email = case when p_cambios ? 'email' then nullif(btrim(p_cambios ->> 'email'), '') else e.email end,
    logo_ruta = case when p_cambios ? 'logo_ruta' then nullif(p_cambios ->> 'logo_ruta', '') else e.logo_ruta end,
    logo_oscuro_ruta = case when p_cambios ? 'logo_oscuro_ruta' then nullif(p_cambios ->> 'logo_oscuro_ruta', '') else e.logo_oscuro_ruta end,
    color_acento = case when p_cambios ? 'color_acento' then nullif(lower(p_cambios ->> 'color_acento'), '') else e.color_acento end,
    iconos = case when p_cambios ? 'iconos' then nullif(p_cambios -> 'iconos', 'null'::jsonb) else e.iconos end,
    locale = case when p_cambios ? 'locale' then btrim(p_cambios ->> 'locale') else e.locale end,
    zona_horaria = case when p_cambios ? 'zona_horaria' then btrim(p_cambios ->> 'zona_horaria') else e.zona_horaria end,
    moneda_base = case when p_cambios ? 'moneda_base' then (p_cambios ->> 'moneda_base')::char(3) else e.moneda_base end,
    registro_abierto = case when p_cambios ? 'registro_abierto' then (p_cambios ->> 'registro_abierto')::boolean else e.registro_abierto end,
    papelera_dias = case when p_cambios ? 'papelera_dias' then (p_cambios ->> 'papelera_dias')::int else e.papelera_dias end,
    actividad_dias = case when p_cambios ? 'actividad_dias' then (p_cambios ->> 'actividad_dias')::int else e.actividad_dias end,
    limpieza_automatica = case when p_cambios ? 'limpieza_automatica' then (p_cambios ->> 'limpieza_automatica')::boolean else e.limpieza_automatica end,
    limpieza_dias_gracia = case when p_cambios ? 'limpieza_dias_gracia' then (p_cambios ->> 'limpieza_dias_gracia')::int else e.limpieza_dias_gracia end,
    actualizado_por = (select auth.uid())
  where e.id = 1
  returning e.actualizado_en into v_nueva;
  return v_nueva;
end;
$_$;


ALTER FUNCTION "public"."empresa_guardar_ajustes"("p_cambios" "jsonb", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."empresa_guardar_ajustes_de_cotizacion"("p_vigencia_dias" integer, "p_vehiculo_obligatorio" boolean, "p_actualizado_en_esperado" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.ajustes_empresa;
  v_nueva timestamptz;
begin
  perform public.assert_activo();
  if not exists (select 1 from public.mis_permisos() m where m.clave = 'cotizaciones.configurar' and m.origen_id is null) then
    raise exception 'No tienes el permiso «cotizaciones.configurar» en todos los orígenes.' using errcode = '42501';
  end if;
  if p_vigencia_dias is null or p_vigencia_dias not between 1 and 365 then
    raise exception 'La vigencia va de 1 a 365 días.' using errcode = '22023', hint = 'vigencia_dias';
  end if;
  if p_vehiculo_obligatorio is null then
    raise exception 'Falta decir si el vehículo es obligatorio al cotizar.' using errcode = '22023', hint = 'vehiculo_obligatorio_al_cotizar';
  end if;

  select * into v from public.ajustes_empresa where id = 1 for update;
  perform public._exigir_version(v.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió los ajustes de la empresa mientras los editabas.');

  update public.ajustes_empresa e
     set vigencia_dias = p_vigencia_dias,
         vehiculo_obligatorio_al_cotizar = p_vehiculo_obligatorio,
         actualizado_por = (select auth.uid())
   where e.id = 1
  returning e.actualizado_en into v_nueva;
  return v_nueva;
end;
$$;


ALTER FUNCTION "public"."empresa_guardar_ajustes_de_cotizacion"("p_vigencia_dias" integer, "p_vehiculo_obligatorio" boolean, "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."empresa_guardar_ajustes_de_cotizacion"("p_vigencia_dias" integer, "p_vehiculo_obligatorio" boolean, "p_actualizado_en_esperado" timestamp with time zone) IS 'Guarda la vigencia (1 a 365 días) y el vehículo obligatorio al cotizar (cotizaciones.configurar en todos los orígenes). Misma versión de la fila que empresa_guardar_ajustes: PT409 si cambió; 22023 con hint por valor fuera de rango. Paso 4.20-4a.';



