CREATE OR REPLACE FUNCTION "public"."etiqueta_crear"("p_id" "uuid", "p_nombre" "text", "p_color" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare e public.etiquetas; v_nombre text; v_color text;
begin
  perform public.assert_activo();
  if p_id is null then
    raise exception 'Falta el identificador de la etiqueta.' using errcode = '22023';
  end if;
  perform public._etiquetas_candado();
  select * into e from public.etiquetas x where x.id = p_id;
  if found then
    if e.usuario_id = (select auth.uid()) then
      return jsonb_build_object('resultado', 'repetido', 'etiqueta', public._etiqueta_json(e));
    end if;
    raise exception 'No pudimos crear esta etiqueta. Vuelve a intentarlo.' using errcode = '22023';
  end if;
  v_nombre := public._etiqueta_nombre(p_nombre);
  v_color := case when p_color is null then null else public._etiqueta_color(p_color) end;
  perform public._etiqueta_nombre_libre(v_nombre, null);
  if (select count(*) from public.etiquetas x where x.usuario_id = (select auth.uid())) >= 50 then
    raise exception 'Puedes tener hasta 50 etiquetas. Elimina una para crear otra.' using errcode = '22023', hint = 'nombre';
  end if;
  if v_color is null then
    select p.k into v_color
      from unnest(public._etiquetas_paleta()) with ordinality p (k, o)
     order by (select count(*) from public.etiquetas x where x.usuario_id = (select auth.uid()) and x.color = p.k), p.o
     limit 1;
  end if;
  begin
    insert into public.etiquetas (id, usuario_id, nombre, color, actualizado_en)
    values (p_id, (select auth.uid()), v_nombre, v_color, clock_timestamp())
    returning * into e;
  exception when unique_violation then
    -- El mismo id de otra persona (el candado es por persona): no se dice nada de ella.
    raise exception 'No pudimos crear esta etiqueta. Vuelve a intentarlo.' using errcode = '22023';
  end;
  return jsonb_build_object('resultado', 'creada', 'etiqueta', public._etiqueta_json(e));
end;
$$;


ALTER FUNCTION "public"."etiqueta_crear"("p_id" "uuid", "p_nombre" "text", "p_color" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."etiqueta_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare e public.etiquetas; v_leads int;
begin
  perform public.assert_activo();
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  perform public._etiquetas_candado();
  select * into e from public.etiquetas x where x.id = p_id and x.usuario_id = (select auth.uid()) for update;
  if not found then
    return jsonb_build_object('resultado', 'sin_cambios', 'etiqueta', null, 'leads', 0);
  end if;
  if e.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._etiqueta_conflicto(e.actualizado_en);
  end if;
  select count(*) into v_leads from public.leads_etiquetas le
   where le.etiqueta_id = e.id and public.puede_lead(le.lead_id, 'leads.ver');
  delete from public.etiquetas x where x.id = e.id;
  return jsonb_build_object('resultado', 'eliminada', 'etiqueta', public._etiqueta_json(e), 'leads', v_leads);
end;
$$;


ALTER FUNCTION "public"."etiqueta_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."etiqueta_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text" DEFAULT NULL::"text", "p_color" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare e public.etiquetas; n public.etiquetas; v_nombre text; v_color text;
begin
  perform public.assert_activo();
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  perform public._etiquetas_candado();
  select * into e from public.etiquetas x where x.id = p_id and x.usuario_id = (select auth.uid()) for update;
  if not found then
    raise exception 'No encontramos esta etiqueta. Recarga para ver las tuyas.' using errcode = '42501';
  end if;
  v_nombre := case when p_nombre is null then e.nombre else public._etiqueta_nombre(p_nombre) end;
  v_color := case when p_color is null then e.color else public._etiqueta_color(p_color) end;
  if (v_nombre, v_color) is not distinct from (e.nombre, e.color) then
    return jsonb_build_object('resultado', 'sin_cambios', 'etiqueta', public._etiqueta_json(e));
  end if;
  if e.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._etiqueta_conflicto(e.actualizado_en);
  end if;
  perform public._etiqueta_nombre_libre(v_nombre, e.id);
  update public.etiquetas x set
    nombre = v_nombre, color = v_color,
    actualizado_en = greatest(clock_timestamp(), e.actualizado_en + interval '1 microsecond')
  where x.id = e.id
  returning * into n;
  return jsonb_build_object('resultado', 'guardada', 'etiqueta', public._etiqueta_json(n));
end;
$$;


ALTER FUNCTION "public"."etiqueta_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text", "p_color" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluar_formula"("p_def" "jsonb", "p_params" "jsonb", "p_entrada" "jsonb", "p_modo" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    SET "extra_float_digits" TO '3'
    AS $$
declare
  v_hint text;
  -- La fórmula y la entrada, desarmadas una vez.
  v_nodos jsonb;
  v_n int;
  v_grupos jsonb;
  v_ng int;
  v_constantes jsonb;
  v_congeladas jsonb;
  v_vivas jsonb;
  v_inputs jsonb;
  v_banderas jsonb;
  v_tc jsonb;
  v_veh jsonb;
  v_ov jsonb;
  v_ids text[];
  v_tipos text[];
  v_pos jsonb;                -- id → posición (1..n); con un id repetido, la última, como el `nodos.set` de TS
  v_opc int;                  -- el nodo `opcion`
  v_segunda text;
  v_total int;                -- el nodo `salida: total`
  v_variante text;
  -- El cambio que se usa (cambioDe).
  v_cb jsonb;
  v_total_en text;
  v_cod text;
  v_rep_id text[] := '{}';
  v_rep_bucket text[] := '{}';
  -- El estado de cada nodo y de cada grupo.
  v_estado text[];
  v_enc boolean[];
  v_pisado boolean[];
  v_lugar jsonb;              -- id de grupo → su lugar (1..g)
  v_grupo_ids text[];
  v_dib boolean[];
  v_sub float8[];             -- el USD de cada grupo mientras se suma
  v_sub_set boolean[];
  v_g_usd float8[];
  v_g_bs float8[];
  -- Lo ya evaluado, en el orden de la lista.
  v_val float8[];
  v_hecho boolean[];          -- está en `valores` (el `opcion` también)
  v_leible boolean[];         -- está en `valores` y es un número (no la variante)
  v_fuente text[];
  v_falt text[] := '{}';      -- 'codigo|donde|ref', en el orden en que nacen
  v_desc text[] := '{}';      -- 'id|motivo'
  -- Por nodo.
  v_nodo jsonb;
  v_id text;
  v_tipo text;
  v_op text;
  v_est text;
  v_x float8;
  v_y float8;
  v_z float8;
  v_xov float8;
  v_t float8;
  v_tiene_ov boolean;
  v_acepta boolean;
  v_resuelto boolean;
  v_leer_de boolean;
  v_de jsonb;
  v_base float8;
  v_nulo boolean;
  v_sug text;
  v_req text;
  v_tabla text;
  v_columna text;
  v_campo text;
  v_filas jsonb;
  v_cols text[];
  v_kinds text[];
  v_nums float8[];
  v_txts text[];
  v_col text;
  v_falta text;
  v_f jsonb;
  v_celda jsonb;
  v_hay boolean;
  v_sobre float8;
  v_bs float8;
  v_suma_usd float8;
  v_usd float8;
  v_tcv float8;
  v_b text;
  v_k text;
  v_r text;
  v_s text;
  r text;
  g int;
  i int;
  j int;
  k int;
  jp int;
begin
  -- §0 la forma de lo que llega: la entrada y el modo, como los Zod de TS.
  v_hint := public._motor_forma_entrada(p_entrada);
  if v_hint is not null then
    perform public._motor_fallar('entrada_invalida', nullif(v_hint, ''),
      case when v_hint = '' then 'La entrada no tiene la forma esperada.' else format('La entrada no tiene la forma esperada en «%s».', v_hint) end);
  end if;
  if p_modo is not null then
    v_hint := public._motor_forma_modo(p_modo);
    if v_hint is not null then
      perform public._motor_fallar('modo_invalido', nullif(v_hint, ''),
        case when v_hint = '' then 'El modo no tiene la forma esperada.' else format('El modo no tiene la forma esperada en «%s».', v_hint) end);
    end if;
  end if;
  if jsonb_typeof(p_def -> 'nodos') is distinct from 'array' then
    perform public._motor_sin_validar(null, 'la definición no tiene la lista de nodos');
  end if;

  -- Los argumentos, una sola vez.
  v_nodos := p_def -> 'nodos';
  v_n := jsonb_array_length(v_nodos);
  v_grupos := coalesce(p_def -> 'grupos', '[]'::jsonb);
  v_ng := jsonb_array_length(v_grupos);
  v_constantes := coalesce(p_params, '{}'::jsonb) - 'tablas';
  v_congeladas := coalesce(p_params -> 'tablas', '{}'::jsonb);
  v_vivas := p_entrada -> 'tablas';
  v_inputs := p_entrada -> 'inputs';
  v_banderas := p_entrada -> 'banderas';
  v_tc := p_entrada -> 'tipos_cambio';
  v_veh := p_entrada -> 'vehiculo';
  v_ov := p_entrada -> 'overrides';

  -- prepararEvaluacion: el índice de nodos, a lo sumo un `opcion` y exactamente un total (el primero con `salida: total`).
  select coalesce(array_agg(x.value ->> 'id' order by x.pos), '{}'::text[]),
         coalesce(array_agg(x.value ->> 'tipo' order by x.pos), '{}'::text[]),
         coalesce(jsonb_object_agg(x.value ->> 'id', x.pos order by x.pos), '{}'::jsonb),
         min(x.pos) filter (where x.value ->> 'tipo' = 'opcion'),
         (array_agg(x.value ->> 'id' order by x.pos) filter (where x.value ->> 'tipo' = 'opcion'))[2],
         min(x.pos) filter (where x.value ->> 'salida' = 'total')
    into v_ids, v_tipos, v_pos, v_opc, v_segunda, v_total
    from jsonb_array_elements(v_nodos) with ordinality as x(value, pos);
  if v_segunda is not null then
    perform public._motor_sin_validar(v_segunda, 'tiene dos variantes');
  end if;
  if v_total is null then
    perform public._motor_sin_validar(null, 'no tiene un nodo con salida «total»');
  end if;

  -- revisarEntrada: lo tipeado sólo nombra inputs, y las banderas sólo banderas.
  for v_k in select jsonb_object_keys(v_inputs) loop
    if v_tipos[(v_pos ->> v_k)::int] is distinct from 'input' then
      perform public._motor_fallar('entrada_invalida', v_k, format('La entrada nombra «%s», que no es un input de la fórmula.', v_k));
    end if;
  end loop;
  for v_k in select jsonb_object_keys(v_banderas) loop
    if v_tipos[(v_pos ->> v_k)::int] is distinct from 'bandera' then
      perform public._motor_fallar('entrada_invalida', v_k, format('La entrada nombra «%s», que no es un bandera de la fórmula.', v_k));
    end if;
  end loop;

  -- P6 resolverVariante: la de la entrada o, sin clave, la `por_defecto`; elegir otra cosa es un error de llamada.
  if v_opc is null then
    if p_entrada ? 'variante' then
      perform public._motor_fallar('entrada_invalida', null,
        format('La entrada elige la variante «%s», y la fórmula no tiene variante.', p_entrada ->> 'variante'));
    end if;
  else
    v_nodo := v_nodos -> (v_opc - 1);
    v_variante := coalesce(p_entrada ->> 'variante', v_nodo ->> 'por_defecto');
    if v_variante is null then
      perform public._motor_fallar('entrada_invalida', v_ids[v_opc],
        format('La variante «%s» no tiene opción por defecto, y la entrada no elige una.', v_ids[v_opc]));
    end if;
    if not exists (select 1 from jsonb_array_elements(v_nodo -> 'opciones') o where o ->> 'clave' = v_variante) then
      perform public._motor_fallar('entrada_invalida', v_ids[v_opc],
        format('«%s» no es una opción de la variante «%s».', v_variante, v_ids[v_opc]));
    end if;
  end if;

  -- P6 decidirEstados: una pasada previa y lineal. Primero la variante, después la condición (la bandera de otra variante está
  -- apagada); de paso, los grupos que se dibujan y el pct de cada par cuyo monto trae override.
  select coalesce(jsonb_object_agg(u.id, u.lugar), '{}'::jsonb), coalesce(array_agg(u.id order by u.lugar), '{}'::text[])
    into v_lugar, v_grupo_ids
    from (select f.id, row_number() over (order by f.primera) as lugar
            from (select x.value ->> 'id' as id, min(x.pos) as primera
                    from jsonb_array_elements(v_grupos) with ordinality as x(value, pos)
                   group by x.value ->> 'id') f) u;
  v_estado := array_fill(null::text, array[v_n]);
  v_enc := array_fill(false, array[v_n]);
  v_pisado := array_fill(false, array[v_n]);
  v_dib := array_fill(false, array[v_ng]);
  for i in 1 .. v_n loop
    v_nodo := v_nodos -> (i - 1);
    v_tipo := v_tipos[i];
    v_est := 'activo';
    if v_tipo not in ('tipo_cambio', 'opcion') and v_nodo ? 'solo_en' then
      if v_variante is null then
        perform public._motor_sin_validar(v_ids[i], 'un nodo dice en qué variantes vale y no hay variante');
      end if;
      if not (v_nodo -> 'solo_en') ? v_variante then
        /*P6a*/ v_est := 'fuera_de_variante';
      end if;
    end if;
    if v_est = 'activo' and v_tipo in ('input', 'constante', 'tabla', 'tramo', 'calculo') and v_nodo ? 'condicion' then
      if v_enc[(v_pos ->> (v_nodo ->> 'condicion'))::int] is not true then
        /*P6b*/ v_est := 'condicion_apagada';
      end if;
    end if;
    v_estado[i] := v_est;
    if v_tipo = 'bandera' and v_est = 'activo' and (v_banderas -> v_ids[i]) = 'true'::jsonb then
      v_enc[i] := true;
    end if;
    if v_nodo ? 'grupo' and v_est <> 'fuera_de_variante' then
      g := (v_lugar ->> (v_nodo ->> 'grupo'))::int;
      if g is not null then /*P6c*/ v_dib[g] := true; end if;
    end if;
    if v_est = 'activo' and v_tipo = 'calculo' and v_nodo ->> 'op' = 'porcentaje_de'
       and (v_nodo -> 'sobrescribible') = 'true'::jsonb and v_ov ? v_ids[i] then
      j := (v_pos ->> (v_nodo ->> 'pct'))::int;
      if v_estado[j] = 'activo' then /*P6d*/ v_pisado[j] := true; end if;
    end if;
  end loop;

  -- cambioDe: el modo, si llega, reemplaza `buckets` y `total_en` completos. Tiene que nombrar tipos de cambio de la fórmula y
  -- cubrir cada bucket que se usa. Sin modo, un fallo es de la fórmula.
  if p_modo is null then
    v_cb := coalesce(p_def -> 'buckets', '{}'::jsonb);
    v_total_en := p_def ->> 'total_en';
    v_cod := 'formula_sin_validar';
  else
    v_cb := p_modo -> 'buckets';
    v_total_en := p_modo ->> 'total_en';
    v_cod := 'modo_invalido';
  end if;
  for v_b, v_r in select b.key, b.value #>> '{}' from jsonb_each(v_cb) b loop
    if v_tipos[(v_pos ->> v_r)::int] is distinct from 'tipo_cambio' then
      perform public._motor_fallar(v_cod, 'buckets.' || v_b,
        format('%s nombra «%s», que no es un tipo de cambio de la fórmula.', 'buckets.' || v_b, v_r));
    end if;
  end loop;
  if v_total_en is not null and v_tipos[(v_pos ->> v_total_en)::int] is distinct from 'tipo_cambio' then
    perform public._motor_fallar(v_cod, 'total_en', format('%s nombra «%s», que no es un tipo de cambio de la fórmula.', 'total_en', v_total_en));
  end if;
  v_nodo := v_nodos -> (v_total - 1);
  if v_ng = 0 then
    -- Sin grupos, el total se reparte: tiene bucket o es una suma de nodos que lo tienen (`ninguno` es «sin bucket»).
    v_b := v_nodo ->> 'bucket';
    if v_b is not null and v_b <> 'ninguno' then
      v_rep_id := array[v_ids[v_total]];
      v_rep_bucket := array[v_b];
    else
      if v_tipos[v_total] <> 'calculo' or v_nodo ->> 'op' <> 'suma' then
        perform public._motor_sin_validar(v_ids[v_total], 'sin grupos, el total no tiene bucket ni es una suma');
      end if;
      v_de := v_nodo -> 'de';
      for k in 0 .. jsonb_array_length(v_de) - 1 loop
        r := v_de ->> k;
        j := (v_pos ->> r)::int;
        v_b := case when j is not null then v_nodos -> (j - 1) ->> 'bucket' end;
        if v_b is null or v_b = 'ninguno' then
          perform public._motor_sin_validar(v_ids[v_total], format('sin grupos, «%s» suma al total sin bucket', r));
        end if;
        v_rep_id := array_append(v_rep_id, r);
        v_rep_bucket := array_append(v_rep_bucket, v_b);
      end loop;
    end if;
    for k in 1 .. cardinality(v_rep_bucket) loop
      if not v_cb ? v_rep_bucket[k] then
        perform public._motor_fallar(v_cod, v_rep_bucket[k], format('no dice qué tipo de cambio usa el bucket «%s»', v_rep_bucket[k]));
      end if;
    end loop;
  else
    for g in 1 .. v_ng loop
      v_b := v_grupos -> (g - 1) ->> 'bucket';
      if not v_cb ? v_b then
        perform public._motor_fallar(v_cod, v_b, format('no dice qué tipo de cambio usa el bucket «%s»', v_b));
      end if;
    end loop;
  end if;

  -- La pasada: un nodo por vez, en el orden de la lista, sólo mirando hacia atrás.
  v_val := array_fill(null::float8, array[v_n]);
  v_hecho := array_fill(false, array[v_n]);
  v_leible := array_fill(false, array[v_n]);
  v_fuente := array_fill(null::text, array[v_n]);
  v_sub := array_fill(null::float8, array[v_ng]);
  v_sub_set := array_fill(false, array[v_ng]);
  for i in 1 .. v_n loop
    v_nodo := v_nodos -> (i - 1);
    v_id := v_ids[i];
    v_tipo := v_tipos[i];
    v_tiene_ov := v_ov ? v_id;
    if v_tipo = 'opcion' then
      -- La variante vale su clave, no se sobrescribe, no tiene fuente y no suma a ningún grupo.
      if v_tiene_ov then v_desc := array_append(v_desc, v_id || '|no_sobrescribible'); end if;
      v_hecho[i] := true;
      continue;
    end if;
    v_est := v_estado[i];
    v_op := case when v_tipo = 'calculo' then v_nodo ->> 'op' end;
    v_x := null;
    v_resuelto := false;
    v_leer_de := false;
    v_xov := null;
    if v_est <> 'activo' then
      -- P7: un nodo inactivo vale 0 sin leer nada, y su override se descarta con su estado.
      v_x := 0;
      v_resuelto := true;
      if v_tiene_ov then v_desc := array_append(v_desc, v_id || '|' || v_est); end if;
    else
      -- P8 sobrescrito: el override antes del cálculo, por tipo. P10: la fuente, sólo de los activos que aceptan un valor.
      v_acepta := v_tipo in ('input', 'constante', 'tipo_cambio')
                  or (v_tipo in ('tabla', 'tramo', 'calculo') and coalesce((v_nodo -> 'sobrescribible') = 'true'::jsonb, false));
      if v_pisado[i] then
        -- El pct de un par cuyo monto manda no se calcula: vale null hasta que llega el par.
        /*P8a*/ v_fuente[i] := 'override';
        v_x := null;
        v_resuelto := true;
      elsif v_tipo = 'input' or not v_acepta then
        if v_tiene_ov then v_desc := array_append(v_desc, v_id || '|no_sobrescribible'); end if;
      else
        /*P10*/ v_fuente[i] := case when v_tiene_ov then 'override'
                                    when v_tipo in ('constante', 'tipo_cambio') then 'default'
                                    else 'sugerido' end;
        if v_tiene_ov then
          v_xov := public._motor_numero(v_ov -> v_id);
          v_resuelto := true;
          if v_op = 'porcentaje_de' then
            -- Si manda el monto y el pct está pisado, el par lo reescribe más abajo (monto ÷ base).
            v_leer_de := v_pisado[(v_pos ->> (v_nodo ->> 'pct'))::int] is true;
          end if;
          if v_tipo = 'tipo_cambio' and not (v_xov > 0) then
            -- Un tipo de cambio de la persona pasa la misma revisión que el de la empresa.
            v_falt := array_append(v_falt, 'tipo_de_cambio_sin_valor|' || v_id || '|' || (v_nodo ->> 'clave'));
          else
            v_x := v_xov;
          end if;
        end if;
      end if;
    end if;

    -- P1 sumar: ((d0 + d1) + d2)… en el orden de `de`; se leen todos los términos aunque uno sea null. Lo piden `suma`,
    -- `porcentaje_de` y el par cuyo monto manda (que lee su base sólo si su pct está pisado).
    if v_leer_de or (not v_resuelto and v_op in ('suma', 'porcentaje_de')) then
      v_de := v_nodo -> 'de';
      v_base := 0;
      v_nulo := false;
      for k in 0 .. jsonb_array_length(v_de) - 1 loop
        r := v_de ->> k;
        j := (v_pos ->> r)::int;
        if v_leible[j] is not true then perform public._motor_sin_leer(v_id, r); end if;
        v_t := v_val[j];
        if v_t is null then v_nulo := true;
        else /*P1*/ v_base := public._motor_mas(v_base, v_t); end if;
      end loop;
    end if;

    -- El par: si manda el monto, el pct vale monto ÷ base (null si la base es 0, con su faltante en el pct, o si es null).
    if v_leer_de then
      jp := (v_pos ->> (v_nodo ->> 'pct'))::int;
      v_y := null;
      if not v_nulo then
        if v_base = 0 then
          /*P8b*/ v_falt := array_append(v_falt, 'division_por_cero|' || v_ids[jp] || '|');
        else
          v_y := public._motor_entre(v_xov, v_base);
        end if;
      end if;
      if v_y is not null and not (abs(v_y) < 'Infinity'::float8) then
        v_falt := array_append(v_falt, 'fuera_de_rango|' || v_ids[jp] || '|');
        v_y := null;
      end if;
      v_val[jp] := case when v_y = 0 then 0::float8 else v_y end;
      v_hecho[jp] := true;
      v_leible[jp] := true;
    end if;

    if not v_resuelto then
      -- valorCalculado: el default, lo tipeado o el sugerido.
      if v_tipo = 'input' then
        v_sug := v_nodo ->> 'sugerido_de';
        v_req := v_nodo ->> 'requerido_si';
        if v_inputs ? v_id then
          -- «Tipeado» es que la clave está, aunque valga 0: había un sugerido si el nodo lo nombra, y ↺ vuelve a él.
          v_fuente[i] := case when v_sug is null then 'input' else 'override' end;
          v_x := public._motor_numero(v_inputs -> v_id);
        else
          v_nulo := false;
          if v_req is not null then
            j := (v_pos ->> v_req)::int;
            if v_leible[j] is not true then perform public._motor_sin_leer(v_id, v_req); end if;
            v_nulo := v_val[j] = 1;
          end if;
          v_fuente[i] := case when v_sug is null or v_nulo then 'input' else 'sugerido' end;
          if v_nulo then
            -- «Requerido» es que la persona lo escriba: un sugerido no lo cumple.
            v_falt := array_append(v_falt, 'requerido_sin_valor|' || v_id || '|' || v_req);
          elsif v_sug is null then
            v_x := 0;
          else
            j := (v_pos ->> v_sug)::int;
            if v_leible[j] is not true then perform public._motor_sin_leer(v_id, v_sug); end if;
            v_x := v_val[j];
          end if;
        end if;

      elsif v_tipo = 'constante' then
        v_f := v_constantes -> v_id;
        if v_f is null then
          perform public._motor_sin_validar(v_id, format('la constante «%s» no tiene valor en params', v_id));
        end if;
        v_x := public._motor_numero(v_f);

      elsif v_tipo = 'tipo_cambio' then
        -- Un tipo de cambio que no llega, o que no es mayor que 0, no tiene valor.
        v_campo := v_nodo ->> 'clave';
        v_f := v_tc -> v_campo;
        if v_f is not null then v_t := public._motor_numero(v_f); end if;
        if v_f is not null and v_t > 0 then
          v_x := v_t;
        else
          v_falt := array_append(v_falt, 'tipo_de_cambio_sin_valor|' || v_id || '|' || v_campo);
        end if;

      elsif v_tipo = 'campo_vehiculo' then
        v_campo := v_nodo ->> 'campo';
        v_f := v_veh -> v_campo;
        if jsonb_typeof(v_f) = 'number' then
          v_x := public._motor_numero(v_f);
        else
          v_falt := array_append(v_falt, 'campo_sin_valor|' || v_id || '|' || v_campo);
        end if;

      elsif v_tipo = 'bandera' then
        v_x := case when (v_banderas -> v_id) = 'true'::jsonb then 1 else 0 end;

      elsif v_tipo = 'tabla' then
        -- Cada nodo anota a lo sumo un faltante, el primero: tabla sin filas, campo sin valor, fila sin coincidencia, celda sin
        -- valor. P3: gana la PRIMERA fila (en el orden de la tabla) cuyo `match` coincide; la congelada manda, aunque esté vacía.
        v_tabla := v_nodo ->> 'tabla';
        v_columna := v_nodo ->> 'columna';
        v_filas := v_congeladas -> v_tabla;
        if v_filas is null then v_filas := v_vivas -> v_tabla; end if;
        if v_filas is null or jsonb_array_length(v_filas) = 0 then
          v_falt := array_append(v_falt, 'tabla_sin_filas|' || v_id || '|' || v_tabla);
        else
          v_cols := '{}'; v_kinds := '{}'; v_nums := '{}'; v_txts := '{}';
          v_nulo := false;
          v_falta := null;
          for v_col, v_r in select m.key, m.value #>> '{}' from jsonb_each(v_nodo -> 'match') m loop
            j := (v_pos ->> v_r)::int;
            if j is not null then
              -- Un nodo anterior (la variante, su clave; un null no coincide con nada).
              if v_hecho[j] is not true then perform public._motor_sin_leer(v_id, v_r); end if;
              if v_tipos[j] = 'opcion' then
                v_cols := array_append(v_cols, v_col); v_kinds := array_append(v_kinds, 's');
                v_nums := array_append(v_nums, null::float8); v_txts := array_append(v_txts, v_variante);
              elsif v_val[j] is null then
                v_nulo := true;
              else
                v_cols := array_append(v_cols, v_col); v_kinds := array_append(v_kinds, 'n');
                v_nums := array_append(v_nums, v_val[j]); v_txts := array_append(v_txts, null::text);
              end if;
            else
              -- Un campo del vehículo. Si faltan varios, el faltante nombra el menor en orden de código: no depende del orden de
              -- las claves, que jsonb no guarda.
              v_f := v_veh -> v_r;
              if v_f is null or jsonb_typeof(v_f) = 'null' then
                v_nulo := true;
                /*P4*/ if v_falta is null or (v_r collate "C") < (v_falta collate "C") then v_falta := v_r; end if;
              elsif jsonb_typeof(v_f) = 'number' then
                v_cols := array_append(v_cols, v_col); v_kinds := array_append(v_kinds, 'n');
                v_nums := array_append(v_nums, public._motor_numero(v_f)); v_txts := array_append(v_txts, null::text);
              else
                v_cols := array_append(v_cols, v_col); v_kinds := array_append(v_kinds, 's');
                v_nums := array_append(v_nums, null::float8); v_txts := array_append(v_txts, v_f #>> '{}');
              end if;
            end if;
          end loop;
          if v_falta is not null then
            v_falt := array_append(v_falt, 'campo_sin_valor|' || v_id || '|' || v_falta);
          end if;
          if not v_nulo then
            -- La igualdad es estricta y sin conversión: un número con un número (como dobles), un texto con un texto.
            v_hay := null;
            select true, f.fila -> v_columna into v_hay, v_celda
              from jsonb_array_elements(v_filas) with ordinality as f(fila, orden)
             where not exists (
                     select 1 from unnest(v_cols, v_kinds, v_nums, v_txts) as m(col, kind, num, txt)
                      where case when m.kind = 'n'
                                 then case when jsonb_typeof(f.fila -> m.col) = 'number' then public._motor_numero(f.fila -> m.col) <> m.num else true end
                                 else case when jsonb_typeof(f.fila -> m.col) = 'string' then (f.fila ->> m.col) <> m.txt else true end
                            end)
             order by f.orden
             limit 1;
            if v_hay is not true then
              v_falt := array_append(v_falt, 'fila_sin_coincidencia|' || v_id || '|' || v_tabla);
            elsif jsonb_typeof(v_celda) = 'number' then
              v_x := public._motor_numero(v_celda);
            else
              v_falt := array_append(v_falt, 'celda_sin_valor|' || v_id || '|' || v_tabla);
            end if;
          end if;
        end if;

      elsif v_tipo = 'tramo' or v_op = 'depreciar' then
        -- La primera fila con desde ≤ sobre ≤ hasta, los dos extremos incluidos. Una fila sin `desde` o sin `hasta` numérico no
        -- coincide nunca. `depreciar` es d0 × el tramo de esa tabla, y lo busca aunque d0 sea null.
        v_tabla := v_nodo ->> 'tabla';
        v_columna := v_nodo ->> 'columna';
        r := v_nodo ->> 'sobre';
        j := (v_pos ->> r)::int;
        if v_op = 'depreciar' then
          v_s := (v_nodo -> 'de') ->> 0;
          jp := (v_pos ->> v_s)::int;
          if v_leible[jp] is not true then perform public._motor_sin_leer(v_id, v_s); end if;
        end if;
        if v_leible[j] is not true then perform public._motor_sin_leer(v_id, r); end if;
        v_sobre := v_val[j];
        v_t := null;
        v_filas := v_congeladas -> v_tabla;
        if v_filas is null then v_filas := v_vivas -> v_tabla; end if;
        if v_filas is null or jsonb_array_length(v_filas) = 0 then
          v_falt := array_append(v_falt, 'tabla_sin_filas|' || v_id || '|' || v_tabla);
        elsif v_sobre is not null then
          v_hay := null;
          select true, f.fila -> v_columna into v_hay, v_celda
            from jsonb_array_elements(v_filas) with ordinality as f(fila, orden)
           where jsonb_typeof(f.fila -> 'desde') = 'number' and jsonb_typeof(f.fila -> 'hasta') = 'number'
             and public._motor_numero(f.fila -> 'desde') <= v_sobre and v_sobre <= public._motor_numero(f.fila -> 'hasta')
           order by f.orden
           limit 1;
          if v_hay is not true then
            v_falt := array_append(v_falt, 'fila_sin_coincidencia|' || v_id || '|' || v_tabla);
          elsif jsonb_typeof(v_celda) = 'number' then
            v_t := public._motor_numero(v_celda);
          else
            v_falt := array_append(v_falt, 'celda_sin_valor|' || v_id || '|' || v_tabla);
          end if;
        end if;
        if v_op = 'depreciar' then
          v_x := case when v_val[jp] is null or v_t is null then null else public._motor_por(v_val[jp], v_t) end;
        else
          v_x := v_t;
        end if;

      elsif v_op = 'suma' then
        v_x := case when v_nulo then null else v_base end;

      elsif v_op = 'porcentaje_de' then
        r := v_nodo ->> 'pct';
        j := (v_pos ->> r)::int;
        if v_leible[j] is not true then perform public._motor_sin_leer(v_id, r); end if;
        v_t := v_val[j];
        v_x := case when v_nulo or v_t is null then null else public._motor_por(v_base, v_t) end;

      elsif v_op in ('multiplicar', 'restar') then
        -- ((d0 × d1) × d2)… y ((d0 − d1) − d2)…, nunca d0 − (d1 + d2): en dobles no es lo mismo. Se leen todos los términos.
        v_de := v_nodo -> 'de';
        v_base := case v_op when 'multiplicar' then 1 else 0 end;
        v_nulo := false;
        for k in 0 .. jsonb_array_length(v_de) - 1 loop
          r := v_de ->> k;
          j := (v_pos ->> r)::int;
          if v_leible[j] is not true then perform public._motor_sin_leer(v_id, r); end if;
          v_t := v_val[j];
          if v_t is null then v_nulo := true;
          elsif v_op = 'multiplicar' then v_base := public._motor_por(v_base, v_t);
          elsif k = 0 then v_base := v_t;
          else v_base := public._motor_menos(v_base, v_t); end if;
        end loop;
        v_x := case when v_nulo then null else v_base end;

      elsif v_op = 'dividir' then
        v_de := v_nodo -> 'de';
        r := v_de ->> 0;
        j := (v_pos ->> r)::int;
        if v_leible[j] is not true then perform public._motor_sin_leer(v_id, r); end if;
        v_y := v_val[j];
        r := v_de ->> 1;
        j := (v_pos ->> r)::int;
        if v_leible[j] is not true then perform public._motor_sin_leer(v_id, r); end if;
        v_z := v_val[j];
        if v_y is null or v_z is null then
          v_x := null;
        elsif v_z = 0 then
          v_falt := array_append(v_falt, 'division_por_cero|' || v_id || '|');
        else
          v_x := public._motor_entre(v_y, v_z);
        end if;

      elsif v_op = 'si' or v_op = 'redondear' then
        -- La condición apagada ya la resolvió el estado: acá llega encendida.
        r := (v_nodo -> 'de') ->> 0;
        j := (v_pos ->> r)::int;
        if v_leible[j] is not true then perform public._motor_sin_leer(v_id, r); end if;
        v_t := v_val[j];
        if v_op = 'si' then v_x := v_t;
        elsif v_t is not null then v_x := public._motor_redondear(v_t, ((v_nodo -> 'n')::numeric)::int); end if;
      end if;
    end if;

    -- asentar: lo que no es finito queda null con `fuera_de_rango`, y −0 vale 0 (JSON y jsonb no lo distinguen).
    if v_x is not null and not (abs(v_x) < 'Infinity'::float8) then
      v_falt := array_append(v_falt, 'fuera_de_rango|' || v_id || '|');
      v_x := null;
    end if;
    /*P5*/ v_val[i] := case when v_x = 0 then 0::float8 else v_x end;
    v_hecho[i] := true;
    v_leible[i] := true;
    -- acumular: el USD de un grupo es la suma de sus miembros en el orden de la lista; un miembro null lo deja null.
    if v_nodo ? 'grupo' then
      g := (v_lugar ->> (v_nodo ->> 'grupo'))::int;
      if g is not null then
        if not v_sub_set[g] then
          v_sub[g] := v_val[i];
          v_sub_set[g] := true;
        elsif v_sub[g] is not null and v_val[i] is not null then
          /*P1b*/ v_sub[g] := public._motor_mas(v_sub[g], v_val[i]);
        else
          v_sub[g] := null;
        end if;
      end if;
    end if;
  end loop;

  -- P9 descartarInexistentes: al final, los overrides de ids que no son nodos, ordenados por id (bytes, como `collate "C"`).
  for v_k in select o.id from (select jsonb_object_keys(v_ov) as id) o where not v_pos ? o.id order by o.id collate "C" loop
    v_desc := array_append(v_desc, v_k || '|nodo_inexistente');
  end loop;

  -- totalesDe.
  if v_leible[v_total] is not true then perform public._motor_sin_leer(v_ids[v_total], v_ids[v_total]); end if;
  v_suma_usd := v_val[v_total];
  v_g_usd := array_fill(null::float8, array[v_ng]);
  v_g_bs := array_fill(null::float8, array[v_ng]);
  v_bs := 0;
  if v_ng > 0 then
    for g in 1 .. v_ng loop
      -- P11: el USD de un grupo es null si lo es un miembro; uno sin miembros vale 0.
      v_y := case when v_sub_set[g] then v_sub[g] else 0 end;
      if v_y is not null and not (abs(v_y) < 'Infinity'::float8) then
        v_falt := array_append(v_falt, 'fuera_de_rango|' || v_grupo_ids[g] || '|');
        v_y := null;
      end if;
      v_g_usd[g] := case when v_y = 0 then 0::float8 else v_y end;
      -- P7: un grupo que no se dibuja vale 0 y no lee su tipo de cambio.
      if v_dib[g] then
        v_t := v_val[(v_pos ->> (v_cb ->> (v_grupos -> (g - 1) ->> 'bucket')))::int];
        v_z := case when v_y is null or v_t is null then null else public._motor_por(v_y, v_t) end;
        if v_z is not null and not (abs(v_z) < 'Infinity'::float8) then
          v_falt := array_append(v_falt, 'fuera_de_rango|' || v_grupo_ids[g] || '|');
          v_z := null;
        end if;
      else
        v_z := 0;
      end if;
      v_g_bs[g] := case when v_z = 0 then 0::float8 else v_z end;
      v_bs := case when v_bs is null or v_z is null then null else public._motor_mas(v_bs, v_z) end;
    end loop;
  else
    -- Sin grupos: Bs = Σ término × tc(su bucket), en el orden de `total.de` (o el total por el tc de su bucket).
    for k in 1 .. cardinality(v_rep_id) loop
      j := (v_pos ->> v_rep_id[k])::int;
      -- Un término fuera de la variante aporta 0 sin leer su tipo de cambio; uno apagado aporta 0 × tc. No hay un `leer` que pueda
      -- fallar acá: el total ya se leyó arriba, y los demás términos son los `de` del total, que su suma ya leyó.
      continue when v_estado[j] = 'fuera_de_variante';
      v_t := v_val[j];
      v_tcv := v_val[(v_pos ->> (v_cb ->> v_rep_bucket[k]))::int];
      v_z := case when v_t is null or v_tcv is null then null else public._motor_por(v_t, v_tcv) end;
      v_bs := case when v_bs is null or v_z is null then null else public._motor_mas(v_bs, v_z) end;
    end loop;
  end if;
  if v_bs is not null and not (abs(v_bs) < 'Infinity'::float8) then
    v_falt := array_append(v_falt, 'fuera_de_rango|total|');
    v_bs := null;
  end if;
  v_bs := case when v_bs = 0 then 0::float8 else v_bs end;
  -- El «TOTAL DÓLARES»: Bs ÷ tc(`total_en`). Sin `total_en` (y sin modo), la suma de los dólares.
  if v_total_en is null then
    v_usd := v_suma_usd;
  else
    v_tcv := v_val[(v_pos ->> v_total_en)::int];
    if v_bs is null or v_tcv is null then
      v_usd := null;
    else
      v_usd := public._motor_entre(v_bs, v_tcv);
      if not (abs(v_usd) < 'Infinity'::float8) then
        v_falt := array_append(v_falt, 'fuera_de_rango|total|');
        v_usd := null;
      end if;
      v_usd := case when v_usd = 0 then 0::float8 else v_usd end;
    end if;
  end if;

  return jsonb_build_object(
    'valores', (select coalesce(jsonb_object_agg(u.id, case when u.tipo = 'opcion' then to_jsonb(v_variante) else coalesce(to_jsonb(u.val), 'null'::jsonb) end), '{}'::jsonb)
                  from unnest(v_ids, v_tipos, v_val) as u(id, tipo, val)),
    'estados', (select coalesce(jsonb_object_agg(u.id, coalesce(u.estado, 'activo')), '{}'::jsonb)
                  from unnest(v_ids, v_estado) as u(id, estado)),
    'fuentes', (select coalesce(jsonb_object_agg(u.id, u.fuente), '{}'::jsonb)
                  from unnest(v_ids, v_fuente) as u(id, fuente) where u.fuente is not null),
    'totales', jsonb_build_object(
      'grupos', (select coalesce(jsonb_object_agg(u.id, jsonb_build_object('usd', coalesce(to_jsonb(u.usd), 'null'::jsonb),
                                                                           'bs', coalesce(to_jsonb(u.bs), 'null'::jsonb),
                                                                           'se_dibuja', u.dib)), '{}'::jsonb)
                   from unnest(v_grupo_ids, v_g_usd, v_g_bs, v_dib) as u(id, usd, bs, dib)),
      'bs', coalesce(to_jsonb(v_bs), 'null'::jsonb),
      'usd', coalesce(to_jsonb(v_usd), 'null'::jsonb),
      'suma_usd', coalesce(to_jsonb(v_suma_usd), 'null'::jsonb)),
    'faltantes', (select coalesce(jsonb_agg(case when split_part(f.dato, '|', 3) = ''
                                                 then jsonb_build_object('codigo', split_part(f.dato, '|', 1), 'donde', split_part(f.dato, '|', 2))
                                                 else jsonb_build_object('codigo', split_part(f.dato, '|', 1), 'donde', split_part(f.dato, '|', 2),
                                                                         'ref', split_part(f.dato, '|', 3)) end
                                                 order by f.orden), '[]'::jsonb)
                    from unnest(v_falt) with ordinality as f(dato, orden)),
    'overrides_descartados', (select coalesce(jsonb_agg(jsonb_build_object('id', split_part(d.dato, '|', 1), 'motivo', split_part(d.dato, '|', 2))
                                                        order by d.orden), '[]'::jsonb)
                                from unnest(v_desc) with ordinality as d(dato, orden)));
end;
$$;


ALTER FUNCTION "public"."evaluar_formula"("p_def" "jsonb", "p_params" "jsonb", "p_entrada" "jsonb", "p_modo" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."evaluar_formula"("p_def" "jsonb", "p_params" "jsonb", "p_entrada" "jsonb", "p_modo" "jsonb") IS 'El motor del cotizador, espejo de evaluar() de TS: valores, estados, fuentes, totales, faltantes y overrides descartados. Pura: recibe las tablas vivas en la entrada. docs/COTIZADOR.md › «El motor».';



CREATE OR REPLACE FUNCTION "public"."evaluar_requisitos"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_fase" "uuid") RETURNS TABLE("requisito_id" "uuid", "tipo" "public"."tipo_requisito", "bloqueante" boolean, "descripcion" "text", "cumplido" boolean, "detalle" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; n int; ok boolean; d jsonb; v_padre uuid; v_hijos int; v_hijos_ok int; v_sin_llegar int;
begin
  for r in select q.*, td.nombre as tipo_doc_nombre, td.formatos as tipo_doc_formatos, fe.nombre as espera_nombre
           from public.fases_requisitos q
           left join public.tipos_documento td on td.id = q.tipo_documento_id
           left join public.fases fe on fe.id = q.espera_fase_id
           where q.fase_id = p_fase order by q.orden loop
    d := '{}'::jsonb;
    if r.tipo = 'documento' then
      select count(*) into n from public.documentos doc
      where doc.vehiculo_id is not distinct from p_vehiculo and doc.repuesto_id is not distinct from p_repuesto
        and doc.tipo_documento_id = r.tipo_documento_id and doc.estado = 'aprobado' and doc.eliminado_en is null
        and (doc.vence_el is null or doc.vence_el >= current_date)
        and (r.formatos is null or doc.mime is null or doc.mime = any (r.formatos));
      ok := n >= coalesce(r.min_archivos, 1) and (r.max_archivos is null or n <= r.max_archivos);
      d := jsonb_build_object('aprobados', n, 'min', coalesce(r.min_archivos, 1), 'max', r.max_archivos, 'tipo_documento_id', r.tipo_documento_id);
      requisito_id := r.id; tipo := r.tipo; bloqueante := r.bloqueante; descripcion := 'Documento: ' || r.tipo_doc_nombre; cumplido := ok; detalle := d;
      return next;
    elsif r.tipo = 'dato' then
      ok := public._requisito_dato_cumplido(p_vehiculo, p_repuesto, r.clave_dato, r.config);
      requisito_id := r.id; tipo := r.tipo; bloqueante := r.bloqueante; descripcion := 'Dato: ' || r.clave_dato; cumplido := ok; detalle := coalesce(r.config, '{}'::jsonb) || jsonb_build_object('clave_dato', r.clave_dato);
      return next;
    elsif r.tipo = 'espera' then
      if r.espera_ambito = 'hijos' then
        -- vehículo espera a sus repuestos (los en stock no cuentan). Sin hijos = no aplica = cumple. Un ítem que terminó sin llegar (en una fase
        -- final que no es la esperada: «Perdido») no frena (8.08-1, C10): cuenta en `sin_llegar`. La regla vive en `_repuesto_ante_espera`.
        select count(*), count(*) filter (where e.estado = 'llego'), count(*) filter (where e.estado = 'sin_llegar')
          into v_hijos, v_hijos_ok, v_sin_llegar
        from public.repuestos_items i join public.repuestos_proyectos pr on pr.id = i.proyecto_id
        cross join lateral (select public._repuesto_ante_espera(i.id, r.espera_fase_id) as estado) e
        where pr.vehiculo_id = p_vehiculo and i.eliminado_en is null and i.en_stock_desde is null and pr.eliminado_en is null;
        ok := v_hijos = v_hijos_ok + v_sin_llegar;
        d := jsonb_build_object('hijos', v_hijos, 'llegaron', v_hijos_ok, 'sin_llegar', v_sin_llegar);
      else
        select pr.vehiculo_id into v_padre from public.repuestos_items i join public.repuestos_proyectos pr on pr.id = i.proyecto_id where i.id = p_repuesto;
        ok := v_padre is null or public.unidad_llego_a_fase(v_padre, null, r.espera_fase_id);
        d := jsonb_build_object('padre', v_padre);
      end if;
      requisito_id := r.id; tipo := r.tipo; bloqueante := r.bloqueante; descripcion := 'Espera: ' || r.espera_nombre; cumplido := ok; detalle := d;
      return next;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."evaluar_requisitos"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_fase" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evento_crear"("p_id" "uuid", "p_datos" "jsonb", "p_destinatarios" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.eventos; v public.eventos; v_dest uuid[]; yo uuid := (select auth.uid());
begin
  perform public.assert_activo();
  if p_id is null then
    raise exception 'Falta el identificador del evento.' using errcode = '22023', hint = 'id';
  end if;
  select * into r from public.eventos x where x.id = p_id;
  if found then
    if r.creado_por = yo then
      return jsonb_build_object('resultado', 'repetido', 'id', r.id, 'actualizado_en', r.actualizado_en);
    end if;
    raise exception 'No pudimos guardar este evento. Vuelve a intentarlo.' using errcode = '22023';
  end if;
  v.visibilidad := 'privado';
  v := public._agenda_evento_datos(v, p_datos);
  if v.visibilidad <> 'privado' then
    perform public.assert_permiso('agenda.eventos.publicar');
  end if;
  v_dest := public._agenda_destinatarios_validar(p_destinatarios, v.visibilidad, yo, '{}');
  begin
    insert into public.eventos (id, titulo, descripcion, inicia_en, termina_en, lugar, visibilidad, lead_id, vehiculo_id, cotizacion_id, creado_por, actualizado_en)
    values (p_id, v.titulo, v.descripcion, v.inicia_en, v.termina_en, v.lugar, v.visibilidad, v.lead_id, v.vehiculo_id, v.cotizacion_id, yo, clock_timestamp())
    returning * into r;
  exception when unique_violation then
    select * into r from public.eventos x where x.id = p_id;
    if r.creado_por = yo then
      return jsonb_build_object('resultado', 'repetido', 'id', r.id, 'actualizado_en', r.actualizado_en);
    end if;
    raise exception 'No pudimos guardar este evento. Vuelve a intentarlo.' using errcode = '22023';
  end;
  perform public._agenda_destinatarios_aplicar(r.id, v_dest, r.titulo);
  return jsonb_build_object('resultado', 'creado', 'id', r.id, 'actualizado_en', r.actualizado_en);
end;
$$;


ALTER FUNCTION "public"."evento_crear"("p_id" "uuid", "p_datos" "jsonb", "p_destinatarios" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."evento_crear"("p_id" "uuid", "p_datos" "jsonb", "p_destinatarios" "uuid"[]) IS 'Crea un evento con el id del navegador (repetido si ya es suyo; 22023 si es ajeno). Público o seleccionados exige agenda.eventos.publicar; destinatarios sólo en seleccionados (1 a 50, activos); avisa evento_invitacion. Responde {resultado, id, actualizado_en} (7.06-1).';



CREATE OR REPLACE FUNCTION "public"."evento_eliminar"("p_evento" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.eventos; n public.eventos;
begin
  r := public._agenda_evento_mio(p_evento);
  if r.visibilidad <> 'privado' then
    perform public.assert_permiso('agenda.eventos.publicar');
  end if;
  perform public._exigir_version(r.actualizado_en, p_actualizado_en_esperado, 'Este evento cambió mientras lo veías. Recarga para seguir desde la última versión.');
  update public.eventos x set eliminado_en = now() where x.id = r.id returning * into n;
  return jsonb_build_object('resultado', 'eliminado', 'id', n.id, 'actualizado_en', n.actualizado_en);
end;
$$;


ALTER FUNCTION "public"."evento_eliminar"("p_evento" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."evento_eliminar"("p_evento" "uuid", "p_actualizado_en_esperado" timestamp with time zone) IS 'Elimina un evento propio con su versión (PT409); uno publicado exige agenda.eventos.publicar. Responde {resultado, id, actualizado_en} (7.06-1).';



CREATE OR REPLACE FUNCTION "public"."evento_guardar"("p_evento" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_datos" "jsonb", "p_destinatarios" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.eventos; v public.eventos; n public.eventos; v_dest uuid[]; v_actuales uuid[];
begin
  r := public._agenda_evento_mio(p_evento);
  v := public._agenda_evento_datos(r, p_datos);
  if r.visibilidad <> 'privado' or v.visibilidad <> 'privado' then
    perform public.assert_permiso('agenda.eventos.publicar');
  end if;
  v_actuales := coalesce(array(select ed.usuario_id from public.eventos_destinatarios ed where ed.evento_id = r.id order by ed.usuario_id), '{}');
  v_dest := public._agenda_destinatarios_validar(
    case when p_destinatarios is not null then p_destinatarios when v.visibilidad = 'seleccionados' then v_actuales else '{}'::uuid[] end,
    v.visibilidad, r.creado_por, v_actuales);
  if (v.titulo, v.descripcion, v.inicia_en, v.termina_en, v.lugar, v.visibilidad, v.lead_id, v.vehiculo_id, v.cotizacion_id)
     is not distinct from (r.titulo, r.descripcion, r.inicia_en, r.termina_en, r.lugar, r.visibilidad, r.lead_id, r.vehiculo_id, r.cotizacion_id)
     and v_dest = v_actuales then
    return jsonb_build_object('resultado', 'sin_cambios', 'id', r.id, 'actualizado_en', r.actualizado_en);
  end if;
  perform public._exigir_version(r.actualizado_en, p_actualizado_en_esperado, 'Este evento cambió mientras lo veías. Recarga para seguir desde la última versión.');
  -- Siempre un update, también si sólo cambian los destinatarios: `agenda_version()` mueve la versión.
  update public.eventos x set
    titulo = v.titulo, descripcion = v.descripcion, inicia_en = v.inicia_en, termina_en = v.termina_en, lugar = v.lugar,
    visibilidad = v.visibilidad, lead_id = v.lead_id, vehiculo_id = v.vehiculo_id, cotizacion_id = v.cotizacion_id
  where x.id = r.id
  returning * into n;
  perform public._agenda_destinatarios_aplicar(n.id, v_dest, n.titulo);
  return jsonb_build_object('resultado', 'guardado', 'id', n.id, 'actualizado_en', n.actualizado_en);
end;
$$;


ALTER FUNCTION "public"."evento_guardar"("p_evento" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_datos" "jsonb", "p_destinatarios" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."evento_guardar"("p_evento" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_datos" "jsonb", "p_destinatarios" "uuid"[]) IS 'Guarda un evento propio con su versión (PT409). Lo publicado exige agenda.eventos.publicar en todo guardar; p_datos: presente = cambio, nulo = quitar; p_destinatarios nulo deja la lista. Responde {resultado, id, actualizado_en} (7.06-1).';



CREATE OR REPLACE FUNCTION "public"."fase_crear"("p_id" "uuid", "p_flujo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_datos" "jsonb") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.fases;
  v_restriccion text;
begin
  if p_id is null then
    raise exception 'Falta el id de la fase.' using errcode = '22023', hint = 'id';
  end if;
  perform public._fase_forma(p_datos, true);
  perform public._flujo_para_editar(p_flujo, p_actualizado_en_esperado);

  v.id := p_id;
  v.flujo_id := p_flujo;
  v.color := '#717c93';
  v.orden := (select coalesce(max(f.orden), 0) + 10 from public.fases f where f.flujo_id = p_flujo);
  v.es_inicial := false;
  v.es_final := false;
  v.activa := true;
  v.es_logistica := public.flujo_regla_activa(p_flujo, 'logistica');
  v.nota_obligatoria := false;
  v.permite_contenedor := true;
  v.permite_aduana := false;
  v.cuenta_llegada_repuestos := false;
  v.publica_web := false;
  v.visible_portal := false;
  v.creado_en := now();
  v.actualizado_en := now();
  v := public._fase_aplicar(v, p_datos);
  perform public._fase_validar(v, array(select jsonb_object_keys(p_datos)));

  begin
    insert into public.fases select (v).*;
  exception when unique_violation then
    get stacked diagnostics v_restriccion = constraint_name;
    perform public._fase_unico(v_restriccion, v.nombre);
    raise;
  end;
  return public._flujo_tocar(p_flujo);
end $$;


ALTER FUNCTION "public"."fase_crear"("p_id" "uuid", "p_flujo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_datos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fase_eliminar"("p_fase" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.fases;
  v_flujo uuid;
  v_uso jsonb;
  v_accion text;
  v_motivo text;
begin
  select flujo_id into v_flujo from public.fases where id = p_fase;
  if v_flujo is null then
    raise exception 'Esta fase ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  perform public._flujo_para_editar(v_flujo, p_actualizado_en_esperado);
  select * into v from public.fases where id = p_fase for update;
  if not found then
    raise exception 'Esta fase ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;

  v_uso := public._fase_uso(p_fase);
  v_accion := v_uso ->> 'accion';
  v_motivo := v_uso ->> 'motivo';

  if v_accion = 'jubilar' then
    update public.fases set activa = false where id = p_fase;
    perform public.registrar_actividad('fase.jubilada', 'fases', p_fase::text, null,
      jsonb_build_object('hay_historial', v_uso -> 'hay_historial', 'paradas', v_uso -> 'paradas'));
    return jsonb_build_object('accion', 'jubilada', 'version', public._flujo_tocar(v_flujo));
  elsif v_accion = 'eliminar' then
    delete from public.fases where id = p_fase;
    perform public.registrar_actividad('fase.eliminada', 'fases', p_fase::text, null, null);
    return jsonb_build_object('accion', 'eliminada', 'version', public._flujo_tocar(v_flujo));
  elsif v_motivo = 'esperas' then
    raise exception 'Hay requisitos que esperan a esta fase. Quítalos antes de eliminarla.' using errcode = '23503';
  elsif v_motivo = 'unica_inicial' then
    raise exception 'Es la única fase inicial del flujo: marca otra como inicial antes de eliminarla.' using errcode = '23514', hint = 'es_inicial';
  else
    raise exception 'Esta fase ya está jubilada.' using errcode = '22023';
  end if;
end $$;


ALTER FUNCTION "public"."fase_eliminar"("p_fase" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fase_eliminar"("p_fase" "uuid", "p_actualizado_en_esperado" timestamp with time zone) IS 'Jubila o borra una fase según _fase_uso (la regla de fase_impacto). Contrato _flujo_para_editar/_flujo_tocar; la fase for update antes de contar. Devuelve {accion: jubilada|eliminada, version}. Esperas → 23503; única inicial activa → 23514 (hint es_inicial); ya jubilada con uso → 22023.';



CREATE OR REPLACE FUNCTION "public"."fase_guardar"("p_fase" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.fases;
  v_antes public.fases;
  v_flujo uuid;
  v_restriccion text;
begin
  perform public._fase_forma(p_cambios, false);
  select flujo_id into v_flujo from public.fases where id = p_fase;
  if v_flujo is null then
    raise exception 'Esta fase ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  perform public._flujo_para_editar(v_flujo, p_actualizado_en_esperado);
  select * into v from public.fases where id = p_fase for no key update;
  if not found then
    raise exception 'Esta fase ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  v_antes := v;

  v := public._fase_aplicar(v, p_cambios);
  perform public._fase_validar(v, array(select jsonb_object_keys(p_cambios)));

  begin
    -- `nombre` (con `flujo_id`, la clave de `fases_flujo_id_nombre_key`) va al update sólo si cambia: asignarlo, aun igual, toma el candado de
    -- clave de la fila y frena el key share de `vehiculos.fase_id` (medido). Renombrar sí espera a quien mueve un vehículo a esa fase.
    if v.nombre is distinct from v_antes.nombre then
      update public.fases f set
        nombre = v.nombre, descripcion = v.descripcion, color = v.color, icono = v.icono, es_inicial = v.es_inicial, es_final = v.es_final,
        es_logistica = v.es_logistica, demora_dias = v.demora_dias, alerta_cada_horas = v.alerta_cada_horas, nota_obligatoria = v.nota_obligatoria,
        permite_contenedor = v.permite_contenedor, permite_aduana = v.permite_aduana, cuenta_llegada_repuestos = v.cuenta_llegada_repuestos,
        publica_web = v.publica_web, visible_portal = v.visible_portal, alias_portal = v.alias_portal, descripcion_portal = v.descripcion_portal
      where f.id = p_fase;
    else
      update public.fases f set
        descripcion = v.descripcion, color = v.color, icono = v.icono, es_inicial = v.es_inicial, es_final = v.es_final,
        es_logistica = v.es_logistica, demora_dias = v.demora_dias, alerta_cada_horas = v.alerta_cada_horas, nota_obligatoria = v.nota_obligatoria,
        permite_contenedor = v.permite_contenedor, permite_aduana = v.permite_aduana, cuenta_llegada_repuestos = v.cuenta_llegada_repuestos,
        publica_web = v.publica_web, visible_portal = v.visible_portal, alias_portal = v.alias_portal, descripcion_portal = v.descripcion_portal
      where f.id = p_fase;
    end if;
  exception when unique_violation then
    get stacked diagnostics v_restriccion = constraint_name;
    perform public._fase_unico(v_restriccion, v.nombre);
    raise;
  end;
  return public._flujo_tocar(v_flujo);
end $$;


