COMMENT ON FUNCTION "public"."fase_impacto"("p_fase" "uuid") IS 'Qué pasaría al eliminar una fase (la regla de _fase_uso). Inexistente → PT409; sin puede_configurar_flujo → 42501. Lectura: no devuelve versión.';



CREATE OR REPLACE FUNCTION "public"."fase_mover"("p_fase" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_despues_de" "uuid" DEFAULT NULL::"uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.fases;
  v_flujo uuid;
begin
  if p_despues_de is not null and p_despues_de = p_fase then
    raise exception 'Una fase no puede ir después de sí misma.' using errcode = '22023', hint = 'despues_de';
  end if;
  select flujo_id into v_flujo from public.fases where id = p_fase;
  if v_flujo is null then
    raise exception 'Esta fase ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  perform public._flujo_para_editar(v_flujo, p_actualizado_en_esperado);
  select * into v from public.fases where id = p_fase for no key update;
  if not found then
    raise exception 'Esta fase ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  if p_despues_de is not null and not exists (select 1 from public.fases x where x.id = p_despues_de and x.flujo_id = v_flujo) then
    raise exception 'Esa fase ya no está en este flujo. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;

  update public.fases x set orden = n.nuevo
  from (
    select q.id, (row_number() over (order by q.posicion, q.nombre, q.id) * 10)::smallint as nuevo from (
      select x.id, x.nombre,
        case
          when x.id = p_fase then (case when p_despues_de is null then -1.0
                                        else (select y.orden from public.fases y where y.id = p_despues_de) + 0.5 end)
          else x.orden::numeric
        end as posicion
      from public.fases x where x.flujo_id = v_flujo
    ) q
  ) n
  where x.id = n.id and x.orden <> n.nuevo;

  return public._flujo_tocar(v_flujo);
end $$;


ALTER FUNCTION "public"."fase_mover"("p_fase" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_despues_de" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fase_mover"("p_fase" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_despues_de" "uuid") IS 'Mueve una fase (primera o tras p_despues_de) y renumera todo el flujo de 10 en 10, sin orden repetido. Contrato _flujo_para_editar/_flujo_tocar; devuelve la versión del flujo.';



CREATE OR REPLACE FUNCTION "public"."fase_reactivar"("p_fase" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.fases;
  v_flujo uuid;
begin
  select flujo_id into v_flujo from public.fases where id = p_fase;
  if v_flujo is null then
    raise exception 'Esta fase ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  perform public._flujo_para_editar(v_flujo, p_actualizado_en_esperado);
  select * into v from public.fases where id = p_fase for no key update;
  if not found then
    raise exception 'Esta fase ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  if v.activa then
    raise exception 'Esta fase ya está activa.' using errcode = '22023';
  end if;
  v.activa := true;
  perform public._fase_validar(v, '{}'::text[]);
  update public.fases set activa = true where id = p_fase;
  return public._flujo_tocar(v_flujo);
end $$;


ALTER FUNCTION "public"."fase_reactivar"("p_fase" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fase_reactivar"("p_fase" "uuid", "p_actualizado_en_esperado" timestamp with time zone) IS 'Reactiva una fase jubilada. Contrato _flujo_para_editar/_flujo_tocar; ya activa → 22023; reglas del flujo → 23514 con hint. Devuelve la versión del flujo.';



CREATE OR REPLACE FUNCTION "public"."fase_requisito_validar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_flujo uuid;
  v_ambito public.ambito_flujo;
  v_ambito_espera public.ambito_flujo;
  v_espera_activa boolean;
  v_formatos text[];
  v_mira_dato boolean;
  v_mira_documento boolean;
  v_mira_espera boolean;
begin
  if tg_op = 'INSERT' then
    v_mira_dato := true;
    v_mira_documento := true;
    v_mira_espera := true;
  else
    v_mira_dato := new.fase_id is distinct from old.fase_id or new.tipo is distinct from old.tipo
      or new.clave_dato is distinct from old.clave_dato or new.config is distinct from old.config;
    v_mira_documento := new.fase_id is distinct from old.fase_id or new.tipo is distinct from old.tipo
      or new.tipo_documento_id is distinct from old.tipo_documento_id or new.formatos is distinct from old.formatos;
    v_mira_espera := new.fase_id is distinct from old.fase_id or new.tipo is distinct from old.tipo
      or new.espera_fase_id is distinct from old.espera_fase_id or new.espera_ambito is distinct from old.espera_ambito;
  end if;
  v_mira_dato := v_mira_dato and new.tipo = 'dato';
  v_mira_documento := v_mira_documento and new.tipo = 'documento';
  v_mira_espera := v_mira_espera and new.tipo = 'espera';

  select f.flujo_id, fl.ambito into v_flujo, v_ambito from public.fases f join public.flujos fl on fl.id = f.flujo_id where f.id = new.fase_id;

  if v_mira_dato then
    if not (new.clave_dato = any (public.claves_dato_requisito(v_ambito))) then
      raise exception 'Clave de dato desconocida para este flujo: %', new.clave_dato using errcode = '22023', hint = 'clave_dato';
    end if;
    if new.clave_dato = 'pagos.umbral_pct' and coalesce((new.config ->> 'pct')::numeric, -1) not between 0 and 100 then
      raise exception 'pagos.umbral_pct necesita config.pct entre 0 y 100' using errcode = '22023', hint = 'config';
    end if;
  end if;

  if v_mira_documento then
    select formatos into v_formatos from public.tipos_documento where id = new.tipo_documento_id for share;
    if new.formatos is not null and not (new.formatos <@ v_formatos) then
      raise exception 'Los formatos del requisito deben estar entre los del tipo de documento.' using errcode = '22023', hint = 'formatos';
    end if;
    if exists (select 1 from public.tipos_documento td where td.id = new.tipo_documento_id and td.flujo_id is not null and td.flujo_id <> v_flujo) then
      raise exception 'El tipo de documento pertenece a otro flujo.' using errcode = '22023', hint = 'tipo_documento_id';
    end if;
  end if;

  if v_mira_espera then
    if not public.flujo_regla_activa(v_flujo, 'esperas') then
      raise exception 'Las esperas están apagadas en este flujo.' using errcode = '23514', hint = 'espera_fase_id';
    end if;
    select fl.ambito, f.activa into v_ambito_espera, v_espera_activa
    from public.fases f join public.flujos fl on fl.id = f.flujo_id where f.id = new.espera_fase_id;
    if v_ambito_espera = v_ambito then
      raise exception 'Una espera apunta a una fase de OTRO flujo (vehículos ↔ repuestos).' using errcode = '22023', hint = 'espera_fase_id';
    end if;
    if not v_espera_activa then
      raise exception 'No se puede esperar a una fase jubilada.' using errcode = '22023', hint = 'espera_fase_id';
    end if;
    if (v_ambito = 'vehiculos' and new.espera_ambito <> 'hijos') or (v_ambito = 'repuestos' and new.espera_ambito <> 'padre') then
      raise exception 'Un vehículo espera a sus hijos (repuestos); un repuesto espera a su padre (vehículo).' using errcode = '22023', hint = 'espera_fase_id';
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."fase_requisito_validar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fase_roles_poner"("p_fase" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_roles" "uuid"[]) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_flujo uuid;
  v_lista uuid[];
  v_antes uuid[];
begin
  select flujo_id into v_flujo from public.fases where id = p_fase;
  if v_flujo is null then
    raise exception 'Esta fase ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  perform public._flujo_para_editar(v_flujo, p_actualizado_en_esperado);
  if not exists (select 1 from public.fases where id = p_fase) then
    raise exception 'Esta fase ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  v_lista := public._roles_de_lista(p_roles);
  v_antes := array(select rol_id from public.fases_roles where fase_id = p_fase order by rol_id);

  delete from public.fases_roles where fase_id = p_fase and rol_id <> all (v_lista);
  insert into public.fases_roles (fase_id, rol_id) select p_fase, r from unnest(v_lista) r on conflict do nothing;
  if v_antes is distinct from v_lista then
    perform public.registrar_actividad('fase.roles_cambiados', 'fases', p_fase::text,
      jsonb_build_object('roles', to_jsonb(v_antes)), jsonb_build_object('roles', to_jsonb(v_lista)));
  end if;
  return public._flujo_tocar(v_flujo);
end $$;


ALTER FUNCTION "public"."fase_roles_poner"("p_fase" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_roles" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."fase_roles_poner"("p_fase" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_roles" "uuid"[]) IS 'Pone los roles que pueden mover hasta una fase (5.05), todo o nada; vacía = cualquiera con flujos.mover. Inexistente → PT409; _flujo_para_editar (42501, PT409); la lista por _roles_de_lista (22023, hint roles). Actividad fase.roles_cambiados {roles} sólo si cambia. Devuelve la versión nueva del flujo.';



CREATE OR REPLACE FUNCTION "public"."fase_validar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and new.flujo_id <> old.flujo_id then
    raise exception 'Una fase no cambia de flujo.' using errcode = '23514';
  end if;
  if new.publica_web and not public.flujo_regla_activa(new.flujo_id, 'vitrina_web') then
    raise exception 'La vitrina web está apagada en este flujo.' using errcode = '23514';
  end if;
  if new.visible_portal and not public.flujo_regla_activa(new.flujo_id, 'portal_cliente') then
    raise exception 'El portal del cliente está apagado en este flujo.' using errcode = '23514';
  end if;
  if new.permite_aduana and not public.flujo_regla_activa(new.flujo_id, 'aduana') then
    raise exception 'La aduana está apagada en este flujo.' using errcode = '23514';
  end if;
  if new.es_logistica and not public.flujo_regla_activa(new.flujo_id, 'logistica') then
    raise exception 'La logística está apagada en este flujo.' using errcode = '23514';
  end if;
  return new;
end;
$$;


