CREATE OR REPLACE FUNCTION "public"."flujo_fuera_de_regla"("p_flujo" "uuid", "p_tope" integer DEFAULT NULL::integer) RETURNS TABLE("vehiculo_id" "uuid", "repuesto_id" "uuid", "fase_id" "uuid", "faltan" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  v_ambito public.ambito_flujo;
  v_resto int := public._acotar_pagina(p_tope, 50, 100) + 1;
  v_fase uuid;
  v_ids uuid[];
  v_n int;
begin
  select fl.ambito into v_ambito from public.flujos fl where fl.id = p_flujo;
  if v_ambito is null then
    raise exception 'Este flujo ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  if not public.puede_configurar_flujo(p_flujo) then
    raise exception 'No tienes permiso para configurar este flujo.' using errcode = '42501';
  end if;

  for v_fase in
    select f.id from public.fases f
    where f.flujo_id = p_flujo and exists (select 1 from public.fases_requisitos r where r.fase_id = f.id and r.bloqueante)
    order by f.orden, f.id
  loop
    if v_ambito = 'repuestos' then
      -- repuestos_items_fase_id_idx
      v_ids := array(select i.id from public.repuestos_items i where i.fase_id = v_fase and i.eliminado_en is null limit 1000);
      return query
        select null::uuid, u.id, v_fase, c.n
        from unnest(v_ids) u(id)
        cross join lateral (select count(*)::int as n from public.evaluar_requisitos(null, u.id, v_fase) e where e.bloqueante and not e.cumplido) c
        where c.n > 0
        limit v_resto;
    else
      -- vehiculos_fase_id_idx
      v_ids := array(select v.id from public.vehiculos v where v.fase_id = v_fase and v.eliminado_en is null limit 1000);
      return query
        select u.id, null::uuid, v_fase, c.n
        from unnest(v_ids) u(id)
        cross join lateral (select count(*)::int as n from public.evaluar_requisitos(u.id, null, v_fase) e where e.bloqueante and not e.cumplido) c
        where c.n > 0
        limit v_resto;
    end if;
    get diagnostics v_n = row_count;
    v_resto := v_resto - v_n;
    exit when v_resto <= 0;
  end loop;
end $$;


ALTER FUNCTION "public"."flujo_fuera_de_regla"("p_flujo" "uuid", "p_tope" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."flujo_fuera_de_regla"("p_flujo" "uuid", "p_tope" integer) IS 'Unidades del flujo que no cumplen los requisitos bloqueantes de su fase: ids, fase y cuántos faltan, a lo sumo _acotar_pagina(p_tope, 50, 100) + 1 filas (1.000 revisadas por fase). Sólo quien configura el flujo. Reemplaza a fuera_de_regla().';



CREATE OR REPLACE FUNCTION "public"."flujo_oferta"("p_flujo" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_existe boolean;
begin
  v_existe := exists (select 1 from public.flujos where id = p_flujo);
  if not v_existe then
    raise exception 'Este flujo ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  -- Sin limit: el tope de 200 por lista lo pone flujo_oferta_guardar(). flujos_transporte_oferta_flujo_id_idx; puertos_pkey, navieras_pkey.
  return jsonb_build_object(
    'transporte', coalesce((select r.activa from public.flujos_reglas r where r.flujo_id = p_flujo and r.regla = 'transporte'), false),
    'puertos_origen', coalesce((
      select jsonb_agg(jsonb_build_object('id', p.id, 'nombre', p.nombre, 'activo', p.activo) order by p.orden, p.nombre, p.id)
      from public.flujos_transporte_oferta o join public.puertos p on p.id = o.puerto_id
      where o.flujo_id = p_flujo and o.tipo = 'puerto_origen'), '[]'::jsonb),
    'puertos_destino', coalesce((
      select jsonb_agg(jsonb_build_object('id', p.id, 'nombre', p.nombre, 'activo', p.activo) order by p.orden, p.nombre, p.id)
      from public.flujos_transporte_oferta o join public.puertos p on p.id = o.puerto_id
      where o.flujo_id = p_flujo and o.tipo = 'puerto_destino'), '[]'::jsonb),
    'navieras', coalesce((
      select jsonb_agg(jsonb_build_object('id', n.id, 'nombre', n.nombre, 'activo', n.activo) order by n.nombre, n.id)
      from public.flujos_transporte_oferta o join public.navieras n on n.id = o.naviera_id
      where o.flujo_id = p_flujo and o.tipo = 'naviera'), '[]'::jsonb)
  );
end $$;


ALTER FUNCTION "public"."flujo_oferta"("p_flujo" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."flujo_oferta"("p_flujo" "uuid") IS 'La oferta de transporte de un flujo: {transporte, puertos_origen, puertos_destino, navieras}, cada elemento {id, nombre, activo}; puertos por (orden, nombre, id), navieras por (nombre, id); lista vacía = se ofrece todo. Flujo inexistente → PT409.';



CREATE OR REPLACE FUNCTION "public"."flujo_oferta_guardar"("p_flujo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_puertos_origen" "uuid"[], "p_puertos_destino" "uuid"[], "p_navieras" "uuid"[]) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_hint text;
  v_transporte boolean;
  v_origen uuid[];
  v_destino uuid[];
  v_navieras uuid[];
begin
  -- Forma, por arreglo y en su orden; nulo vale vacío.
  v_hint := case
    when array_position(p_puertos_origen, null) is not null then 'puertos_origen'
    when array_position(p_puertos_destino, null) is not null then 'puertos_destino'
    when array_position(p_navieras, null) is not null then 'navieras'
  end;
  if v_hint is not null then
    raise exception 'Un puerto o una naviera viene vacío.' using errcode = '22023', hint = v_hint;
  end if;
  v_hint := case
    when cardinality(p_puertos_origen) > 200 then 'puertos_origen'
    when cardinality(p_puertos_destino) > 200 then 'puertos_destino'
    when cardinality(p_navieras) > 200 then 'navieras'
  end;
  if v_hint is not null then
    raise exception 'Son demasiados: hasta 200 por lista.' using errcode = '22023', hint = v_hint;
  end if;
  v_origen := coalesce((select array_agg(distinct x) from unnest(p_puertos_origen) x), '{}');
  v_destino := coalesce((select array_agg(distinct x) from unnest(p_puertos_destino) x), '{}');
  v_navieras := coalesce((select array_agg(distinct x) from unnest(p_navieras) x), '{}');

  perform public._flujo_para_editar(p_flujo, p_actualizado_en_esperado);

  v_transporte := public.flujo_regla_activa(p_flujo, 'transporte');
  if not v_transporte then
    raise exception 'La oferta de transporte se guarda con la regla «Transporte» encendida.' using errcode = '23514', hint = 'transporte';
  end if;

  -- Existencia antes de escribir (puertos_pkey, navieras_pkey).
  v_hint := case
    when exists (select 1 from unnest(v_origen) x where not exists (select 1 from public.puertos p where p.id = x)) then 'puertos_origen'
    when exists (select 1 from unnest(v_destino) x where not exists (select 1 from public.puertos p where p.id = x)) then 'puertos_destino'
    when exists (select 1 from unnest(v_navieras) x where not exists (select 1 from public.navieras n where n.id = x)) then 'navieras'
  end;
  if v_hint is not null then
    raise exception 'Un puerto o una naviera ya no existe. Recarga e intenta de nuevo.' using errcode = '23503', hint = v_hint;
  end if;

  -- flujos_transporte_oferta_flujo_id_idx
  delete from public.flujos_transporte_oferta where flujo_id = p_flujo;
  insert into public.flujos_transporte_oferta (flujo_id, tipo, puerto_id, naviera_id)
  select p_flujo, 'puerto_origen', x, null::uuid from unnest(v_origen) x
  union all
  select p_flujo, 'puerto_destino', x, null::uuid from unnest(v_destino) x
  union all
  select p_flujo, 'naviera', null::uuid, x from unnest(v_navieras) x;

  return public._flujo_tocar(p_flujo);
end $$;


ALTER FUNCTION "public"."flujo_oferta_guardar"("p_flujo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_puertos_origen" "uuid"[], "p_puertos_destino" "uuid"[], "p_navieras" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."flujo_oferta_guardar"("p_flujo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_puertos_origen" "uuid"[], "p_puertos_destino" "uuid"[], "p_navieras" "uuid"[]) IS 'Reemplaza la oferta de transporte de un flujo (todo o nada) y devuelve la versión nueva del flujo. Vacío = se ofrece todo. Orden: forma (22023: elemento nulo o más de 200, hint el arreglo); _flujo_para_editar (PT409 / 42501 / versión PT409); regla transporte apagada → 23514 (hint transporte); un id inexistente → 23503 (hint el arreglo). Repetidos se colapsan; inactivos se aceptan. La versión se mueve siempre.';



CREATE OR REPLACE FUNCTION "public"."flujo_regla_activa"("p_flujo" "uuid", "p_regla" "text") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce((select activa from public.flujos_reglas where flujo_id = p_flujo and regla = p_regla), false);
$$;


ALTER FUNCTION "public"."flujo_regla_activa"("p_flujo" "uuid", "p_regla" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flujo_regla_apagar_validar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_deja boolean;
  v_flujo_vivo boolean;
  v_bloquea boolean;
begin
  v_deja := (tg_op = 'DELETE' and old.activa)
    or (tg_op = 'UPDATE' and old.activa
        and (not new.activa or old.regla is distinct from new.regla or old.flujo_id is distinct from new.flujo_id));
  if v_deja then
    v_flujo_vivo := exists (select 1 from public.flujos where id = old.flujo_id);
    if v_flujo_vivo then
      v_bloquea := coalesce((public._flujo_regla_uso(old.flujo_id, old.regla) ->> 'bloquea')::boolean, false);
      if v_bloquea then
        raise exception 'No se puede apagar esta regla: la usan fases o requisitos de este flujo.' using errcode = '23514', hint = 'regla';
      end if;
    end if;
  end if;
  return coalesce(new, old);
end $$;


ALTER FUNCTION "public"."flujo_regla_apagar_validar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."flujo_regla_cambiar"("p_flujo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_regla" "text", "p_activa" boolean) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.flujos;
  v_ok boolean;
  v_activa boolean;
  v_bloquea boolean;
begin
  v_ok := public._flujo_regla_admitida('vehiculos', p_regla);
  if not v_ok then
    raise exception 'Esta regla no existe.' using errcode = '22023', hint = 'regla';
  end if;
  if p_activa is null then
    raise exception 'Falta si la regla se enciende o se apaga.' using errcode = '22023', hint = 'activa';
  end if;
  v := public._flujo_para_editar(p_flujo, p_actualizado_en_esperado);

  if p_activa then
    v_ok := public._flujo_regla_admitida(v.ambito, p_regla);
    if not v_ok then
      raise exception 'Esta regla no está disponible en este flujo.' using errcode = '22023', hint = 'regla';
    end if;
    insert into public.flujos_reglas (flujo_id, regla, activa) values (p_flujo, p_regla, true)
    on conflict (flujo_id, regla) do update set activa = true;
  else
    -- flujos_reglas_pkey. Apagar no mira el catálogo: limpia una fila heredada.
    select activa into v_activa from public.flujos_reglas where flujo_id = p_flujo and regla = p_regla;
    v_activa := coalesce(v_activa, false);
    if v_activa then
      v_bloquea := coalesce((public._flujo_regla_uso(p_flujo, p_regla) ->> 'bloquea')::boolean, false);
      if v_bloquea then
        raise exception 'No se puede apagar esta regla: la usan fases o requisitos de este flujo.' using errcode = '23514', hint = 'regla';
      end if;
      update public.flujos_reglas set activa = false where flujo_id = p_flujo and regla = p_regla;
    end if;
  end if;

  return public._flujo_tocar(p_flujo);
end $$;


ALTER FUNCTION "public"."flujo_regla_cambiar"("p_flujo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_regla" "text", "p_activa" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."flujo_regla_cambiar"("p_flujo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_regla" "text", "p_activa" boolean) IS 'Enciende o apaga una regla de un flujo y devuelve la versión nueva del flujo. Orden: forma (22023, hint regla|activa); _flujo_para_editar (PT409 / 42501 / versión PT409); encender fuera del catálogo del ámbito → 22023; apagar con uso → 23514 (hint regla). La versión se mueve siempre.';



CREATE OR REPLACE FUNCTION "public"."flujo_regla_impacto"("p_flujo" "uuid", "p_regla" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_existe boolean;
  v_activa boolean;
  v jsonb;
begin
  v_existe := public._flujo_regla_admitida('vehiculos', p_regla);
  if not v_existe then
    raise exception 'Esta regla no existe.' using errcode = '22023', hint = 'regla';
  end if;
  v_existe := p_flujo is not null and exists (select 1 from public.flujos where id = p_flujo);
  if not v_existe then
    raise exception 'Este flujo ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  if not public.puede_configurar_flujo(p_flujo) then
    raise exception 'No tienes permiso para configurar este flujo.' using errcode = '42501';
  end if;
  v := public._flujo_regla_uso(p_flujo, p_regla);
  v_activa := public.flujo_regla_activa(p_flujo, p_regla);
  if not v_activa then
    v := jsonb_set(v, '{bloquea}', 'false'::jsonb);
  end if;
  return v;
end $$;


ALTER FUNCTION "public"."flujo_regla_impacto"("p_flujo" "uuid", "p_regla" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."flujo_regla_impacto"("p_flujo" "uuid", "p_regla" "text") IS 'Qué frena apagar una regla de un flujo (la regla de _flujo_regla_uso): {bloquea, fases, requisitos}. Regla fuera del catálogo → 22023 (hint regla); inexistente → PT409; sin puede_configurar_flujo → 42501. Ya apagada → bloquea false. Lectura: no devuelve versión.';



CREATE OR REPLACE FUNCTION "public"."flujo_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  new.actualizado_en := greatest(clock_timestamp(), old.actualizado_en + interval '1 microsecond');
  return new;
end $$;


ALTER FUNCTION "public"."flujo_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."formula_auditar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id text;
begin
  v_id := coalesce(to_jsonb(coalesce(new, old)) ->> 'id', '');
  insert into public.actividad (accion, actor_id, tabla, registro_id, antes, despues)
  values (tg_table_name || '.' || lower(tg_op), (select auth.uid()), tg_table_name, v_id,
          case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) - 'definicion' - 'params' - 'diseno' - 'visibilidad' end,
          case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) - 'definicion' - 'params' - 'diseno' - 'visibilidad' end);
  return null;
end;
$$;


ALTER FUNCTION "public"."formula_auditar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."formula_cambiar_constante"("p_origen" "uuid", "p_nodo" "text", "p_valor" numeric, "p_publicada_esperada" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_pub public.formulas; v_anterior numeric; v_f text;
begin
  perform public.assert_permiso('cotizaciones.configurar', p_origen);
  select * into v_pub from public.formulas where origen_id = p_origen and estado = 'publicada';
  if v_pub.id is null then raise exception 'El origen no tiene fórmula publicada.' using errcode = '22023'; end if;
  -- Se compara con lo leído aquí, que es lo que se copia: `_publicar_version` vuelve a comparar tras el candado.
  if p_publicada_esperada is not null and p_publicada_esperada is distinct from v_pub.id then
    v_f := public._version_publicada_por(v_pub.id);
    raise exception '%.', upper(left(v_f, 1)) || substr(v_f, 2) using errcode = 'PT409';
  end if;
  v_anterior := (v_pub.params ->> p_nodo)::numeric;
  if v_anterior is null then raise exception 'La fórmula publicada no tiene la constante «%».', p_nodo using errcode = '22023'; end if;
  if v_anterior = p_valor then raise exception 'La constante ya tiene ese valor.' using errcode = '22023', hint = 'valor'; end if;
  return public._publicar_version(p_origen, v_pub.definicion, v_pub.params || jsonb_build_object(p_nodo, p_valor), v_pub.diseno,
                                  format('%s: %s → %s, desde el cotizador', p_nodo, v_anterior, p_valor), v_pub.id,
                                  jsonb_build_object('constante', p_nodo), true);
end;
$$;


ALTER FUNCTION "public"."formula_cambiar_constante"("p_origen" "uuid", "p_nodo" "text", "p_valor" numeric, "p_publicada_esperada" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."formula_cambiar_constante"("p_origen" "uuid", "p_nodo" "text", "p_valor" numeric, "p_publicada_esperada" "uuid") IS 'El ⚙ de una constante: publica la N+1 desde la publicada con ese valor, sin tocar el borrador (cotizaciones.configurar del origen). PT409 si la esperada ya no es la publicada; 22023 si el valor no cambia. docs/COTIZADOR.md › «Versiones (4.20-1)».';



CREATE OR REPLACE FUNCTION "public"."formula_descartar_borrador"("p_origen" "uuid", "p_actualizado_en_esperado" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_b public.formulas;
begin
  perform public.assert_permiso('cotizaciones.configurar', p_origen);
  perform pg_advisory_xact_lock(hashtextextended('formulas:' || p_origen::text, 0));
  select * into v_b from public.formulas where origen_id = p_origen and estado = 'borrador' for update;   -- formulas_borrador_unico
  perform public._exigir_borrador_formula(v_b, p_actualizado_en_esperado);
  delete from public.formulas where id = v_b.id;
end;
$$;


ALTER FUNCTION "public"."formula_descartar_borrador"("p_origen" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."formula_descartar_borrador"("p_origen" "uuid", "p_actualizado_en_esperado" timestamp with time zone) IS 'Descarta el borrador de un origen (cotizaciones.configurar). Con p_actualizado_en_esperado, sólo si es la del borrador (PT409 si cambió o ya no está); sin ella, el que haya. docs/COTIZADOR.md › «Versiones (4.20-1)».';



CREATE OR REPLACE FUNCTION "public"."formula_guardar_borrador"("p_origen" "uuid", "p_def" "jsonb", "p_params" "jsonb", "p_diseno" "jsonb", "p_nota" "text" DEFAULT NULL::"text", "p_publicada_esperada" "uuid" DEFAULT NULL::"uuid", "p_actualizado_en_esperado" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_b public.formulas; v_pub uuid; v_id uuid; v_en timestamptz;
begin
  perform public.assert_permiso('cotizaciones.configurar', p_origen);
  perform public.validar_formula(p_def, p_params);
  if p_diseno is not null then
    perform public._diseno_forma(p_diseno);   -- sólo la forma: cruzarlo con la fórmula es de publicar
  end if;
  -- Guardar, publicar, el ⚙ y revertir de un origen, en serie: el segundo lee lo que dejó el primero.
  perform pg_advisory_xact_lock(hashtextextended('formulas:' || p_origen::text, 0));
  select * into v_b from public.formulas where origen_id = p_origen and estado = 'borrador' for update;   -- formulas_borrador_unico
  if p_actualizado_en_esperado is null then
    -- Crear: no había borrador, y la publicada sobre la que se empezó (si se dice) sigue siendo la publicada.
    if v_b.id is not null then
      raise exception 'Ya hay un borrador: % y se guardó %.', public._borrador_formula_empezado_por(v_b.creado_por), public._hace(v_b.actualizado_en)
        using errcode = 'PT409';
    end if;
    select id into v_pub from public.formulas where origen_id = p_origen and estado = 'publicada';   -- formulas_publicada_unica
    if p_publicada_esperada is not null and v_pub is distinct from p_publicada_esperada then
      if v_pub is null then
        raise exception 'La versión que tenías ya no es la publicada, y el origen no tiene otra.' using errcode = 'PT409';
      end if;
      raise exception 'Mientras editabas, %.', public._version_publicada_por(v_pub) using errcode = 'PT409';
    end if;
    insert into public.formulas (origen_id, estado, definicion, params, diseno, nota, creado_por, version_origen_id)
    values (p_origen, 'borrador', p_def, p_params, p_diseno, p_nota, (select auth.uid()), v_pub)
    returning id, actualizado_en into v_id, v_en;
  else
    -- Pisar: el borrador que leyó, tal como lo leyó. La publicada no se compara: publicarlo atrasado da su propio PT409.
    perform public._exigir_borrador_formula(v_b, p_actualizado_en_esperado);
    update public.formulas set definicion = p_def, params = p_params, diseno = p_diseno, nota = p_nota, visibilidad = null
     where id = v_b.id
    returning id, actualizado_en into v_id, v_en;   -- la hora que puso trg_actualizado_en
  end if;
  return jsonb_build_object('id', v_id, 'actualizado_en', v_en);
end;
$$;


ALTER FUNCTION "public"."formula_guardar_borrador"("p_origen" "uuid", "p_def" "jsonb", "p_params" "jsonb", "p_diseno" "jsonb", "p_nota" "text", "p_publicada_esperada" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."formula_guardar_borrador"("p_origen" "uuid", "p_def" "jsonb", "p_params" "jsonb", "p_diseno" "jsonb", "p_nota" "text", "p_publicada_esperada" "uuid", "p_actualizado_en_esperado" timestamp with time zone) IS 'Guarda el borrador de un origen (cotizaciones.configurar). Sin p_actualizado_en_esperado crea (PT409 si ya hay borrador o si p_publicada_esperada ya no es la publicada); con ella pisa sólo si es la del borrador (PT409 si cambió o ya no está). Devuelve {id, actualizado_en}. docs/COTIZADOR.md › «Versiones (4.20-1)».';



CREATE OR REPLACE FUNCTION "public"."formula_para_cotizar"("p_origen" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  f public.formulas;
begin
  perform public.assert_permiso('cotizaciones.configurar', p_origen);
  if p_origen is null then
    raise exception 'Falta el origen.' using errcode = '22023';
  end if;
  select * into f from public.formulas x where x.origen_id = p_origen and x.estado = 'publicada';   -- formulas_publicada_unica
  if f.id is null then
    raise exception 'Este origen no tiene una fórmula publicada.' using errcode = '22023';
  end if;
  return jsonb_build_object('id', f.id, 'version', f.version, 'nota', f.nota, 'publicado_en', f.publicado_en,
                            'definicion', f.definicion, 'params', f.params, 'diseno', f.diseno, 'visibilidad', f.visibilidad);
end $$;


