COMMENT ON FUNCTION "public"."formula_para_cotizar"("p_origen" "uuid") IS 'La versión publicada de un origen entera (definicion, params, diseno y visibilidad), sólo con cotizaciones.configurar de ese origen. docs/COTIZADOR.md › «En la base (4.10-1)».';



CREATE OR REPLACE FUNCTION "public"."formula_publicar"("p_origen" "uuid", "p_nota" "text", "p_publicada_esperada" "uuid" DEFAULT NULL::"uuid", "p_actualizado_en_esperado" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  return public._publicar_formula(p_origen, p_nota, p_publicada_esperada, false, p_actualizado_en_esperado);
end;
$$;


ALTER FUNCTION "public"."formula_publicar"("p_origen" "uuid", "p_nota" "text", "p_publicada_esperada" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."formula_publicar"("p_origen" "uuid", "p_nota" "text", "p_publicada_esperada" "uuid", "p_actualizado_en_esperado" timestamp with time zone) IS 'Publica el borrador de un origen (cotizaciones.configurar). PT409 si p_publicada_esperada ya no es la publicada, si el borrador ya no tiene la p_actualizado_en_esperado (o ya no está) o si nació sobre otra publicada. docs/COTIZADOR.md › «Versiones (4.20-1)».';



CREATE OR REPLACE FUNCTION "public"."formula_revertir"("p_origen" "uuid", "p_version" "uuid", "p_nota" "text", "p_publicada_esperada" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_v public.formulas; v_estado text;
begin
  perform public.assert_permiso('cotizaciones.configurar', p_origen);
  if p_publicada_esperada is null then
    raise exception 'Revertir pide la versión publicada que tienes.' using errcode = '22023', hint = 'publicada_esperada';
  end if;
  -- Una versión de otro origen y una que no existe dan el mismo texto: no se delata ninguna fila.
  select * into v_v from public.formulas f where f.id = p_version and f.origen_id = p_origen;
  if v_v.id is null then raise exception 'Esa versión no es de este origen.' using errcode = '22023', hint = 'version'; end if;
  v_estado := v_v.estado::text;
  if v_estado = 'publicada' then raise exception 'Esa ya es la versión publicada.' using errcode = '22023', hint = 'version'; end if;
  if v_estado = 'borrador' then raise exception 'Un borrador no se revierte: se publica.' using errcode = '22023', hint = 'version'; end if;
  return public._publicar_version(p_origen, v_v.definicion, v_v.params, v_v.diseno, p_nota, p_publicada_esperada,
                                  jsonb_build_object('copia_de', v_v.id, 'version_copiada', v_v.version), false);
end;
$$;


ALTER FUNCTION "public"."formula_revertir"("p_origen" "uuid", "p_version" "uuid", "p_nota" "text", "p_publicada_esperada" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."formula_revertir"("p_origen" "uuid", "p_version" "uuid", "p_nota" "text", "p_publicada_esperada" "uuid") IS 'Revertir la fórmula de un origen (cotizaciones.configurar): publica la N+1 como copia, con su diseño, de una versión archivada, sin tocar el borrador. PT409 si la esperada ya no es la publicada; 22023 con nivel_retirado si su diseño usa un nivel retirado. docs/COTIZADOR.md › «Versiones (4.20-1)».';



CREATE OR REPLACE FUNCTION "public"."formula_tipo_cambio_del_nodo"("p_formula" "uuid", "p_nodo" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_clave text;
begin
  perform public.assert_permiso('empresa.tipos_cambio.gestionar');
  -- La versión por `formulas_pkey`; un borrador no cuenta (una hoja dibuja la publicada o la versión de una guardada). Sólo un nodo `tipo_cambio` nombra una tarifa.
  select n ->> 'clave' into v_clave
    from public.formulas f
   cross join lateral jsonb_array_elements(f.definicion -> 'nodos') n
   where f.id = p_formula
     and f.estado <> 'borrador'
     and n ->> 'id' = p_nodo
     and n ->> 'tipo' = 'tipo_cambio'
   limit 1;
  if v_clave is null then
    return null;
  end if;
  -- Que quien llama vea el nodo en esa versión: `_nodos_visibles()` relee la versión por `formulas_pkey` (lo que un nivel esconde no sale).
  if not exists (select 1 from public._nodos_visibles(p_formula) v where v.nodo = p_nodo) then
    return null;
  end if;
  -- La fila por `tipos_cambio_clave_key`; desactivada viene con `activo: false`.
  return (
    select jsonb_build_object(
      'id', t.id,
      'clave', t.clave,
      'nombre', t.nombre,
      'moneda_de', t.moneda_de::text,
      'moneda_a', t.moneda_a::text,
      'valor', t.valor,
      'activo', t.activo,
      'actualizado_en', t.actualizado_en)
      from public.tipos_cambio t
     where t.clave = v_clave);
end;
$$;


ALTER FUNCTION "public"."formula_tipo_cambio_del_nodo"("p_formula" "uuid", "p_nodo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."formula_tipo_cambio_del_nodo"("p_formula" "uuid", "p_nodo" "text") IS 'La fila de tipos_cambio (id, clave, nombre, monedas, valor, activo y actualizado_en exacto) que nombra el nodo tipo_cambio p_nodo de la versión p_formula, para el ⚙ de una celda de tipo de cambio (4.20-3c/3d). Pide empresa.tipos_cambio.gestionar (42501) y que quien llama vea el nodo (_nodos_visibles); un borrador, un nodo de otro tipo o que no se ve, y una versión o tarifa que no existe dan null. Lee formulas_pkey dos veces (aquí y en _nodos_visibles) y tipos_cambio_clave_key.';



CREATE OR REPLACE FUNCTION "public"."gasto_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.gastos; v_en timestamptz;
begin
  perform public.assert_activo();
  select * into o from public.gastos x where x.id = p_id;
  if not found or o.eliminado_en is not null then
    raise exception 'Ese gasto ya no existe.' using errcode = 'PT409';
  end if;
  if not public.puede_unidad(o.vehiculo_id, o.repuesto_id, 'logistica.gastos.editar', 'repuestos.costos.editar') then
    raise exception 'No tienes el permiso «%».', case when o.vehiculo_id is not null then 'logistica.gastos.editar' else 'repuestos.costos.editar' end
      using errcode = '42501';
  end if;
  perform public._gasto_bloquear(o);
  select * into o from public.gastos x where x.id = p_id for update;
  if o.eliminado_en is not null then
    raise exception 'Ese gasto ya no existe.' using errcode = 'PT409';
  end if;
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este gasto mientras lo editabas.');
  perform public._gasto_tributo_protegido(o, null);
  update public.gastos x set eliminado_en = now() where x.id = p_id returning x.actualizado_en into v_en;
  return jsonb_build_object('id', p_id, 'actualizado_en', v_en);
end;
$$;


ALTER FUNCTION "public"."gasto_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gasto_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.gastos; n public.gastos;
begin
  perform public.assert_activo();
  select * into o from public.gastos x where x.id = p_id;
  if not found or o.eliminado_en is not null then
    raise exception 'Ese gasto ya no existe.' using errcode = 'PT409';
  end if;
  if not public.puede_unidad(o.vehiculo_id, o.repuesto_id, 'logistica.gastos.editar', 'repuestos.costos.editar') then
    raise exception 'No tienes el permiso «%».', case when o.vehiculo_id is not null then 'logistica.gastos.editar' else 'repuestos.costos.editar' end
      using errcode = '42501';
  end if;
  perform public._gasto_bloquear(o);
  select * into o from public.gastos x where x.id = p_id for update;
  if o.eliminado_en is not null then
    raise exception 'Ese gasto ya no existe.' using errcode = 'PT409';
  end if;
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  n := public._gasto_de_cambios(o, p_cambios);
  if (n.categoria_id, n.moneda, n.monto, n.tipo_cambio_id, n.tipo_cambio_aplicado, n.monto_base, n.fecha, n.proveedor, n.comprobante_ruta, n.notas)
     is not distinct from
     (o.categoria_id, o.moneda, o.monto, o.tipo_cambio_id, o.tipo_cambio_aplicado, o.monto_base, o.fecha, o.proveedor, o.comprobante_ruta, o.notas) then
    return public._gasto_respuesta(o, '{"sin_cambios": true}');
  end if;
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este gasto mientras lo editabas.');
  if n.categoria_id is distinct from o.categoria_id then
    perform public._gasto_tributo_protegido(o, n.categoria_id);
  end if;
  update public.gastos x
     set categoria_id = n.categoria_id, moneda = n.moneda, monto = n.monto, tipo_cambio_id = n.tipo_cambio_id,
         tipo_cambio_aplicado = n.tipo_cambio_aplicado, monto_base = n.monto_base, fecha = n.fecha, proveedor = n.proveedor,
         comprobante_ruta = n.comprobante_ruta, notas = n.notas
   where x.id = p_id
  returning * into n;
  return public._gasto_respuesta(n, '{"sin_cambios": false}');
end;
$$;


ALTER FUNCTION "public"."gasto_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gasto_registrar"("p_id" "uuid", "p_vehiculo" "uuid", "p_repuesto" "uuid", "p_categoria" "uuid", "p_moneda" "text", "p_monto" numeric, "p_tipo_cambio" "uuid", "p_fecha" "date", "p_proveedor" "text", "p_comprobante_ruta" "text", "p_notas" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare g public.gastos; c record;
begin
  perform public.assert_activo();
  if p_id is null then
    raise exception 'Falta el id del gasto.' using errcode = '23502', hint = 'id';
  end if;
  if num_nonnulls(p_vehiculo, p_repuesto) <> 1 then
    raise exception 'Un gasto es de un vehículo o de un repuesto: uno solo.' using errcode = '22023', hint = 'unidad';
  end if;
  if not public.puede_unidad(p_vehiculo, p_repuesto, 'logistica.gastos.editar', 'repuestos.costos.editar') then
    raise exception 'No tienes el permiso «%».', case when p_vehiculo is not null then 'logistica.gastos.editar' else 'repuestos.costos.editar' end
      using errcode = '42501';
  end if;
  select * into g from public.gastos x where x.id = p_id;
  if not found then
    if not public._dinero_regla_activa(p_vehiculo, p_repuesto, 'gastos') then
      raise exception 'Los gastos están apagados en el flujo de esta unidad.' using errcode = '23514';
    end if;
    perform public._gasto_validar(p_vehiculo, p_repuesto, p_categoria, p_monto, p_comprobante_ruta);
    if p_categoria is null then
      raise exception 'Elige una categoría de gasto activa.' using errcode = '23502', hint = 'categoria_id';
    end if;
    c := public._monto_en_base(p_moneda, p_tipo_cambio, p_monto);
    insert into public.gastos (id, vehiculo_id, repuesto_id, categoria_id, proveedor, moneda, monto, tipo_cambio_id, tipo_cambio_aplicado, monto_base, fecha,
                               comprobante_ruta, notas, creado_por)
    values (p_id, p_vehiculo, p_repuesto, p_categoria, nullif(btrim(p_proveedor), ''), p_moneda, p_monto, c.tipo_cambio_id, c.tipo_cambio_aplicado,
            c.monto_base, coalesce(p_fecha, current_date), p_comprobante_ruta, nullif(btrim(p_notas), ''), (select auth.uid()))
    on conflict (id) do nothing
    returning * into g;
    if found then
      return public._gasto_respuesta(g, '{"ya_existia": false}');
    end if;
    select * into g from public.gastos x where x.id = p_id;
  end if;
  -- D8 · un reintento devuelve lo ya registrado; nunca duplica ni pisa.
  if g.vehiculo_id is distinct from p_vehiculo or g.repuesto_id is distinct from p_repuesto then
    raise exception 'Ese id ya es de otro gasto.' using errcode = '23505', hint = 'id';
  end if;
  if g.eliminado_en is not null then
    raise exception 'Ese gasto ya no existe.' using errcode = 'PT409';
  end if;
  return public._gasto_respuesta(g, '{"ya_existia": true}');
end;
$$;


ALTER FUNCTION "public"."gasto_registrar"("p_id" "uuid", "p_vehiculo" "uuid", "p_repuesto" "uuid", "p_categoria" "uuid", "p_moneda" "text", "p_monto" numeric, "p_tipo_cambio" "uuid", "p_fecha" "date", "p_proveedor" "text", "p_comprobante_ruta" "text", "p_notas" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gastos_listar"("p_cursor_fecha" "date", "p_cursor_id" "uuid", "p_tope" integer, "p_filtros" "jsonb") RETURNS TABLE("id" "uuid", "vehiculo_id" "uuid", "vehiculo_titulo" "text", "origen_id" "uuid", "categoria_id" "uuid", "categoria_nombre" "text", "moneda" "text", "monto" numeric, "tipo_cambio_aplicado" numeric, "monto_base" numeric, "fecha" "date", "proveedor" "text", "comprobante_ruta" "text", "lote_id" "uuid", "actualizado_en" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  -- TAMANO_DE_PAGINA_POR_DEFECTO (50), máximo 100, más una para saber si hay otra.
  v_n integer := public._acotar_pagina(p_tope, 50, 100) + 1;
  v_yo uuid := (select auth.uid());
  f record;
  v_todos uuid[]; v_algun uuid[];
begin
  perform public.assert_activo();
  select * into f from public._dinero_filtros(p_filtros, array['origen', 'categoria', 'desde', 'hasta']);
  if (p_cursor_fecha is null) <> (p_cursor_id is null) then
    raise exception 'El cursor de la lista está incompleto.' using errcode = '22023', hint = 'cursor';
  end if;
  v_todos := public.origenes_con_alcance('logistica.gastos.ver', 'todos');
  v_algun := public.origenes_con_alcance('logistica.gastos.ver', 'propios');
  if cardinality(v_algun) = 0 then
    return;
  end if;
  -- gastos_fecha_idx: (fecha desc, id desc) where eliminado_en is null. Con cursor y sin cursor son dos consultas (escala.md): la
  -- condición del cursor queda como condición de índice.
  if p_cursor_fecha is null then
    return query
      select g.id, g.vehiculo_id, v.titulo, v.origen_id, g.categoria_id, c.nombre, g.moneda::text, g.monto, g.tipo_cambio_aplicado, g.monto_base, g.fecha,
             g.proveedor, g.comprobante_ruta, g.lote_id, g.actualizado_en
        from public.gastos g
        join public.vehiculos v on v.id = g.vehiculo_id and v.eliminado_en is null
        join public.categorias_gasto c on c.id = g.categoria_id
       where g.eliminado_en is null
         and v.origen_id = any (v_algun)
         and (v.origen_id = any (v_todos) or v.creado_por = v_yo or (v.lead_id is not null and public.en_cartera(v.lead_id)))
         and (f.origen is null or v.origen_id = f.origen)
         and (f.categoria is null or g.categoria_id = f.categoria)
         and (f.desde is null or g.fecha >= f.desde)
         and (f.hasta is null or g.fecha <= f.hasta)
       order by g.fecha desc, g.id desc
       limit v_n;
  else
    return query
      select g.id, g.vehiculo_id, v.titulo, v.origen_id, g.categoria_id, c.nombre, g.moneda::text, g.monto, g.tipo_cambio_aplicado, g.monto_base, g.fecha,
             g.proveedor, g.comprobante_ruta, g.lote_id, g.actualizado_en
        from public.gastos g
        join public.vehiculos v on v.id = g.vehiculo_id and v.eliminado_en is null
        join public.categorias_gasto c on c.id = g.categoria_id
       where g.eliminado_en is null
         and (g.fecha, g.id) < (p_cursor_fecha, p_cursor_id)
         and v.origen_id = any (v_algun)
         and (v.origen_id = any (v_todos) or v.creado_por = v_yo or (v.lead_id is not null and public.en_cartera(v.lead_id)))
         and (f.origen is null or v.origen_id = f.origen)
         and (f.categoria is null or g.categoria_id = f.categoria)
         and (f.desde is null or g.fecha >= f.desde)
         and (f.hasta is null or g.fecha <= f.hasta)
       order by g.fecha desc, g.id desc
       limit v_n;
  end if;
end;
$$;


ALTER FUNCTION "public"."gastos_listar"("p_cursor_fecha" "date", "p_cursor_id" "uuid", "p_tope" integer, "p_filtros" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."gastos_listar"("p_cursor_fecha" "date", "p_cursor_id" "uuid", "p_tope" integer, "p_filtros" "jsonb") IS 'Los gastos de vehículos que quien llama ve (logistica.gastos.ver con su alcance), por cursor (fecha desc, id desc), con filtros origen, categoria, desde y hasta. Devuelve hasta el tope más una (hay otra página). Sin la clave, vacía. Sin total (6.10-2, C5–C8).';



CREATE OR REPLACE FUNCTION "public"."gastos_prorratear"("p_lote" "uuid", "p_vehiculos" "uuid"[], "p_categoria" "uuid", "p_moneda" "text", "p_monto" numeric, "p_tipo_cambio" "uuid", "p_fecha" "date", "p_proveedor" "text", "p_comprobante_ruta" "text", "p_notas" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int := coalesce(cardinality(p_vehiculos), 0); v uuid; c record; p record; v_centavos bigint; v_cada bigint; v_sobran bigint; v_parte numeric;
  v_id uuid; v_ids uuid[] := '{}'::uuid[];
begin
  perform public.assert_activo();
  if p_lote is null then
    raise exception 'Falta el id del reparto.' using errcode = '23502', hint = 'lote';
  end if;
  if n < 1 or n > 200 or array_position(p_vehiculos, null) is not null
     or n <> cardinality(array(select distinct x from unnest(p_vehiculos) x)) then
    raise exception 'Elige entre 1 y 200 vehículos, sin repetir.' using errcode = '22023', hint = 'vehiculos';
  end if;
  foreach v in array p_vehiculos loop
    if not public.puede_vehiculo(v, 'logistica.gastos.editar') then
      raise exception 'No tienes el permiso «logistica.gastos.editar».' using errcode = '42501';
    end if;
  end loop;
  perform pg_advisory_xact_lock(hashtextextended('gastos_prorratear:' || p_lote::text, 0));
  -- D8 · por gastos_lote_idx.
  if exists (select 1 from public.gastos g where g.lote_id = p_lote) then
    if (select array_agg(x order by x) from unnest(p_vehiculos) x)
       is distinct from (select array_agg(g.vehiculo_id order by g.vehiculo_id) from public.gastos g where g.lote_id = p_lote) then
      raise exception 'Ese reparto ya existe con otros vehículos.' using errcode = '23505', hint = 'lote';
    end if;
    return jsonb_build_object('lote', p_lote, 'ya_existia', true, 'ids',
      to_jsonb(array(select g.id from unnest(p_vehiculos) with ordinality u (v, o) join public.gastos g on g.vehiculo_id = u.v and g.lote_id = p_lote
                      order by u.o)));
  end if;
  foreach v in array p_vehiculos loop
    if not public._dinero_regla_activa(v, null, 'gastos') then
      raise exception 'Los gastos están apagados en el flujo de uno de los vehículos.' using errcode = '23514';
    end if;
  end loop;
  if p_categoria is null then
    raise exception 'Elige una categoría de gasto activa.' using errcode = '23502', hint = 'categoria_id';
  end if;
  perform public._gasto_validar(p_vehiculos[1], null, p_categoria, p_monto, p_comprobante_ruta);
  c := public._monto_en_base(p_moneda, p_tipo_cambio, p_monto);
  v_centavos := (p_monto * 100)::bigint;
  v_cada := v_centavos / n;
  v_sobran := v_centavos % n;
  for i in 1 .. n loop
    v_parte := (v_cada + case when i <= v_sobran then 1 else 0 end)::numeric / 100;
    p := public._monto_en_base(p_moneda, c.tipo_cambio_id, v_parte, c.tipo_cambio_aplicado);
    insert into public.gastos (vehiculo_id, categoria_id, proveedor, moneda, monto, tipo_cambio_id, tipo_cambio_aplicado, monto_base, fecha, comprobante_ruta,
                               notas, creado_por, lote_id)
    values (p_vehiculos[i], p_categoria, nullif(btrim(p_proveedor), ''), p_moneda, v_parte, p.tipo_cambio_id, p.tipo_cambio_aplicado, p.monto_base,
            coalesce(p_fecha, current_date), p_comprobante_ruta, nullif(btrim(p_notas), ''), (select auth.uid()), p_lote)
    returning id into v_id;
    v_ids := v_ids || v_id;
  end loop;
  return jsonb_build_object('lote', p_lote, 'ya_existia', false, 'ids', to_jsonb(v_ids));
end;
$$;


ALTER FUNCTION "public"."gastos_prorratear"("p_lote" "uuid", "p_vehiculos" "uuid"[], "p_categoria" "uuid", "p_moneda" "text", "p_monto" numeric, "p_tipo_cambio" "uuid", "p_fecha" "date", "p_proveedor" "text", "p_comprobante_ruta" "text", "p_notas" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."importacion_abrir"("p_pase" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid;
begin
  update public.importaciones_pases p set usado_en = now()
  where p.pase = p_pase and p.usado_en is null and p.creado_en > now() - interval '10 minutes'
  returning p.importacion_id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."importacion_abrir"("p_pase" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."importacion_abrir"("p_pase" "uuid") IS 'La función importar-csv canjea un pase (un uso, 10 minutos) por el id de su importación; null si no vale. Sólo service_role.';



CREATE OR REPLACE FUNCTION "public"."importacion_crear"("p_id" "uuid", "p_entidad" "text", "p_archivo_ruta" "text", "p_mapeo" "jsonb", "p_asignar_a" "uuid" DEFAULT NULL::"uuid", "p_origen" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_yo uuid := (select auth.uid());
  v_prev public.importaciones;
  v_destino uuid;
  v_con_destino boolean := false;
  v_ruta text := btrim(coalesce(p_archivo_ruta, ''));
  v_k text;
  v_tipo text;
  v_n integer := 0;
begin
  perform public.assert_activo();
  if p_id is null then
    raise exception 'Falta el identificador de la importación.' using errcode = '22023';
  end if;

  -- Un reintento con el mismo id devuelve lo mismo; una importación ajena o de `/leads` no se nombra.
  select * into v_prev from public.importaciones i where i.id = p_id;
  if found then
    if v_prev.usuario_id is distinct from v_yo or v_prev.archivo_ruta is null then
      raise exception 'No encontramos esta importación.' using errcode = '42501';
    end if;
    return jsonb_build_object('id', v_prev.id, 'estado', v_prev.estado, 'repetido', true);
  end if;

  if p_entidad is null or p_entidad not in ('leads', 'vehiculos') then
    raise exception 'Sólo se importan leads o vehículos.' using errcode = '22023', hint = 'entidad';
  end if;

  -- La ruta, en la carpeta de quien importa (la misma regla que la policy del bucket `importaciones`).
  if v_ruta = '' or char_length(v_ruta) > 500 or split_part(v_ruta, '/', 1) <> v_yo::text
     or strpos(v_ruta, '..') > 0 or strpos(v_ruta, '//') > 0 or lower(v_ruta) !~ '\.(csv|txt)$' then
    raise exception 'El archivo tiene que estar en tu carpeta y ser .csv o .txt.' using errcode = '22023', hint = 'archivo_ruta';
  end if;

  -- El mapeo: columna del archivo → campo (o nulo). Qué campo es cada uno lo valida la función edge contra la plantilla.
  if p_mapeo is null or jsonb_typeof(p_mapeo) <> 'object' then
    raise exception 'El emparejamiento de columnas no tiene la forma esperada.' using errcode = '22023', hint = 'mapeo';
  end if;
  for v_k in select jsonb_object_keys(p_mapeo) loop
    v_n := v_n + 1;
    v_tipo := jsonb_typeof(p_mapeo -> v_k);
    if v_tipo not in ('string', 'null') or (v_tipo = 'string' and char_length(p_mapeo ->> v_k) > 120) or char_length(v_k) > 120 then
      raise exception 'El emparejamiento de columnas no tiene la forma esperada.' using errcode = '22023', hint = 'mapeo';
    end if;
  end loop;
  if v_n not between 1 and 200 then
    raise exception 'El emparejamiento lleva de 1 a 200 columnas.' using errcode = '22023', hint = 'mapeo';
  end if;

  if p_entidad = 'leads' then
    if p_origen is not null then
      raise exception 'Una importación de leads no lleva origen.' using errcode = '22023', hint = 'origen';
    end if;
    v_destino := coalesce(p_asignar_a, v_yo);
    if v_destino = v_yo then
      perform public.assert_permiso('leads.crear');
      v_destino := null;
    else
      perform public.assert_permiso('datos.importar.todo');
      if not exists (select 1 from public.perfiles p where p.id = v_destino and p.activo and not p.bloqueado)
         or not public.usuario_tiene_permiso(v_destino, 'leads.crear') then
        raise exception 'Esa persona no puede recibir leads: está inactiva o no tiene el permiso de crear leads.'
          using errcode = '22023', hint = 'asignar_a';
      end if;
      v_con_destino := true;
    end if;
  else
    if p_asignar_a is not null then
      raise exception 'Una importación de vehículos no se asigna a nadie.' using errcode = '22023', hint = 'asignar_a';
    end if;
    if p_origen is null or not exists (select 1 from public.origenes o where o.id = p_origen and o.activo) then
      raise exception 'Elige un origen activo para los vehículos.' using errcode = '22023', hint = 'origen';
    end if;
    perform public.assert_permiso('vehiculos.crear', p_origen);
  end if;

  insert into public.importaciones (id, usuario_id, entidad, archivo_ruta, mapeo, estado, asignar_a, con_destino, origen_id)
  values (p_id, v_yo, p_entidad, v_ruta, p_mapeo, 'pendiente', v_destino, v_con_destino, case when p_entidad = 'vehiculos' then p_origen end);
  return jsonb_build_object('id', p_id, 'estado', 'pendiente', 'repetido', false);
end;
$_$;


ALTER FUNCTION "public"."importacion_crear"("p_id" "uuid", "p_entidad" "text", "p_archivo_ruta" "text", "p_mapeo" "jsonb", "p_asignar_a" "uuid", "p_origen" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."importacion_crear"("p_id" "uuid", "p_entidad" "text", "p_archivo_ruta" "text", "p_mapeo" "jsonb", "p_asignar_a" "uuid", "p_origen" "uuid") IS 'Importación total (9.06): crea la importación en pendiente, idempotente por id. Leads: para sí misma pide leads.crear; para otra persona, datos.importar.todo y que el destino esté activo y tenga leads.crear. Vehículos: un origen activo y vehiculos.crear de ese origen. La ruta va en la carpeta de quien importa.';



CREATE OR REPLACE FUNCTION "public"."importacion_empezar"("p_importacion" "uuid", "p_total" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.importaciones;
  v_previo jsonb;
  v_motivo text;
begin
  select * into v from public.importaciones i where i.id = p_importacion for update;
  if not found or v.archivo_ruta is null then
    raise exception 'No encontramos esta importación.' using errcode = '22023';
  end if;
  v_previo := public._importacion_previo();
  if p_total is null or p_total < 1 or p_total > 20000 then
    raise exception 'Un archivo lleva de 1 a 20.000 filas: pártelo.' using errcode = '22023', hint = 'filas_total';
  end if;
  if v.estado in ('terminada', 'fallida') then
    raise exception 'Esta importación ya terminó.' using errcode = '22023';
  end if;
  if v.estado = 'procesando' then
    if v.filas_total is distinct from p_total then
      raise exception 'Esta importación ya empezó con otro total de filas.' using errcode = '22023', hint = 'filas_total';
    end if;
    perform public._importacion_volver(v_previo);
    return jsonb_build_object('importacion', v.id, 'estado', 'procesando', 'filas_total', v.filas_total, 'procesadas', v.procesadas, 'repetido', true);
  end if;
  v_motivo := public._importacion_autorizar(v);
  perform public._importacion_volver(v_previo);
  if v_motivo is not null then
    perform public._importacion_fallar(v.id, v_motivo);
    return jsonb_build_object('importacion', v.id, 'estado', 'fallida', 'rechazado', v_motivo);
  end if;
  update public.importaciones i set estado = 'procesando', filas_total = p_total, iniciada_en = now(), avance_en = now() where i.id = v.id;
  return jsonb_build_object('importacion', v.id, 'estado', 'procesando', 'filas_total', p_total, 'procesadas', 0, 'repetido', false);
end;
$$;


ALTER FUNCTION "public"."importacion_empezar"("p_importacion" "uuid", "p_total" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."importacion_empezar"("p_importacion" "uuid", "p_total" integer) IS 'Importación total (9.06), sólo service_role: fija el total (1 a 20.000) y pasa a procesando tras mirar los permisos; en procesando con el mismo total, retoma.';



CREATE OR REPLACE FUNCTION "public"."importacion_pase_emitir"("p_importacion" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_imp public.importaciones;
  v_pase uuid;
begin
  perform public.assert_activo();
  if p_importacion is null then
    raise exception 'Falta el identificador de la importación.' using errcode = '22023';
  end if;
  select * into v_imp from public.importaciones i where i.id = p_importacion;
  if not found or v_imp.usuario_id is distinct from v_yo or v_imp.archivo_ruta is null then
    raise exception 'No encontramos esta importación.' using errcode = '42501';
  end if;
  if v_imp.estado in ('terminada', 'fallida') then
    raise exception 'Esta importación ya terminó.' using errcode = '22023';
  end if;
  -- Sobre importaciones_pases_importacion_idx.
  select p.pase into v_pase from public.importaciones_pases p
  where p.importacion_id = p_importacion and p.usado_en is null and p.creado_en > now() - interval '5 minutes'
  order by p.creado_en desc limit 1;
  if v_pase is null then
    insert into public.importaciones_pases (importacion_id) values (p_importacion) returning pase into v_pase;
  end if;
  return v_pase;
end;
$$;


ALTER FUNCTION "public"."importacion_pase_emitir"("p_importacion" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."importacion_pase_emitir"("p_importacion" "uuid") IS 'Un pase de un solo uso para la importación total propia (pendiente o procesando); devuelve el vivo si hay uno de los últimos 5 minutos. La acción de /datos se lo manda a la función importar-csv. Ajena, inexistente o de /leads: 42501.';



CREATE OR REPLACE FUNCTION "public"."importacion_procesar_lote"("p_importacion" "uuid", "p_desde" integer, "p_filas" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.importaciones;
  v_previo jsonb;
  v_motivo text;
  v_cc text := (select e.telefono_cc from public.ajustes_empresa e where e.id = 1);
  v_e record;
  v_r jsonb;
  v_ultima integer;
  v_creadas integer := 0;
  v_ya integer := 0;
  v_rech integer := 0;
  v_ids uuid[] := '{}';
  v_filas integer[] := '{}';
  v_sqlstate text;
  v_mensaje text;
  v_hint text;
begin
  -- Dos invocaciones sobre la misma importación se forman en fila aquí: la segunda ve la marca ya movida.
  select * into v from public.importaciones i where i.id = p_importacion for update;
  if not found or v.archivo_ruta is null then
    raise exception 'No encontramos esta importación.' using errcode = '22023';
  end if;
  v_previo := public._importacion_previo();
  if v.estado <> 'procesando' then
    raise exception 'Esta importación no está en curso.' using errcode = '22023';
  end if;
  perform public._importacion_lote_validar(p_desde, p_filas, v.filas_total, v.procesadas);
  v_ultima := p_desde + jsonb_array_length(p_filas) - 1;
  if v_ultima <= v.procesadas then
    perform public._importacion_volver(v_previo);
    return jsonb_build_object('importacion', v.id, 'procesadas', v.procesadas, 'creadas', 0, 'ya_existian', 0, 'rechazadas', 0,
                              'saltadas', jsonb_array_length(p_filas));
  end if;

  v_motivo := public._importacion_autorizar(v);
  if v_motivo is not null then
    perform public._importacion_volver(v_previo);
    perform public._importacion_fallar(v.id, v_motivo);
    return jsonb_build_object('importacion', v.id, 'estado', 'fallida', 'rechazado', v_motivo);
  end if;

  -- Leads en el orden del teléfono (dos importaciones que se cruzan toman los candados en el mismo orden), luego por fila.
  for v_e in
    select x.value as v, (x.value ->> 'fila')::integer as fila
      from jsonb_array_elements(p_filas) x
     where (x.value ->> 'fila')::integer > v.procesadas
     order by case when v.entidad = 'leads' then public._telefono_o_nulo(v_cc, x.value -> 'datos' ->> 'telefono_principal') end nulls first,
              (x.value ->> 'fila')::integer
  loop
    begin
      if v_e.v ? 'rechazo' then
        v_r := jsonb_build_object('resultado', 'error', 'campo', nullif(btrim(v_e.v -> 'rechazo' ->> 'campo'), ''),
                                  'motivo', btrim(v_e.v -> 'rechazo' ->> 'motivo'));
      elsif v.entidad = 'leads' then
        v_r := public._importacion_fila_lead(v, v_e.fila, v_e.v -> 'datos');
      else
        v_r := public._importacion_fila_vehiculo(v, v_e.fila, v_e.v -> 'datos');
      end if;
    exception when others then
      get stacked diagnostics v_sqlstate = returned_sqlstate, v_mensaje = message_text, v_hint = pg_exception_hint;
      -- Lo que levantan nuestras reglas es humano; lo inesperado no se cuenta.
      if v_sqlstate not in ('22023', '23502', '23514', 'PT409') then
        v_mensaje := 'No pudimos importar esta fila.';
        v_hint := null;
      end if;
      v_r := jsonb_build_object('resultado', 'error', 'campo', left(nullif(v_hint, ''), 120), 'motivo', left(v_mensaje, 500));
    end;
    if (v_r ->> 'resultado') in ('creado', 'repetido') then
      v_creadas := v_creadas + 1;
      if (v_r ->> 'resultado') = 'creado' and v_r ? 'id' then
        v_ids := v_ids || (v_r ->> 'id')::uuid;
        v_filas := v_filas || v_e.fila;
      end if;
    else
      if (v_r ->> 'resultado') = 'ya_existe' then v_ya := v_ya + 1; else v_rech := v_rech + 1; end if;
      insert into public.importaciones_filas (importacion_id, fila, resultado, campo, motivo)
      values (v.id, v_e.fila, v_r ->> 'resultado', v_r ->> 'campo', v_r ->> 'motivo')
      on conflict (importacion_id, fila) do nothing;
    end if;
  end loop;

  -- Los números propios de lo que entró ahora, repartidos por orden de fila (el bloque de leads_importar_lote).
  if cardinality(v_ids) > 1 then
    perform set_config('importadora.numerar_lote', 'si', true);
    with a as (select t.id, row_number() over (order by t.fila) as rn from unnest(v_ids, v_filas) as t(id, fila)),
         n as (select l.numero_propio, row_number() over (order by l.numero_propio) as rn from public.leads l where l.id = any (v_ids)),
         m as (select a.id, n.numero_propio from a join n using (rn))
    update public.leads l set numero_propio = m.numero_propio from m where l.id = m.id and l.numero_propio is distinct from m.numero_propio;
    perform set_config('importadora.numerar_lote', 'no', true);
  end if;

  update public.importaciones i
     set procesadas = v_ultima, filas_ok = coalesce(i.filas_ok, 0) + v_creadas, ya_existian = i.ya_existian + v_ya,
         rechazadas = i.rechazadas + v_rech, avance_en = now()
   where i.id = v.id;
  perform public._importacion_volver(v_previo);
  return jsonb_build_object('importacion', v.id, 'procesadas', v_ultima, 'creadas', v_creadas, 'ya_existian', v_ya, 'rechazadas', v_rech,
                            'saltadas', jsonb_array_length(p_filas) - (v_ultima - v.procesadas));
end;
$$;


ALTER FUNCTION "public"."importacion_procesar_lote"("p_importacion" "uuid", "p_desde" integer, "p_filas" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."importacion_procesar_lote"("p_importacion" "uuid", "p_desde" integer, "p_filas" "jsonb") IS 'Importación total (9.06), sólo service_role: un lote de hasta 50 filas consecutivas a nombre de quien importa (los leads, del destino), con los permisos de hoy. Todo o nada por fila; idempotente por (importación, fila). Devuelve sólo cuentas.';



CREATE OR REPLACE FUNCTION "public"."importacion_terminar"("p_importacion" "uuid", "p_error" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.importaciones;
  v_previo jsonb;
begin
  select * into v from public.importaciones i where i.id = p_importacion for update;
  if not found or v.archivo_ruta is null then
    raise exception 'No encontramos esta importación.' using errcode = '22023';
  end if;
  v_previo := public._importacion_previo();
  if v.estado in ('terminada', 'fallida') then
    perform public._importacion_volver(v_previo);
    return jsonb_build_object('importacion', v.id, 'estado', v.estado, 'repetido', true);
  end if;
  if p_error is null then
    if v.estado <> 'procesando' or v.procesadas is distinct from v.filas_total then
      raise exception 'Faltan filas por procesar.' using errcode = '22023';
    end if;
    update public.importaciones i set estado = 'terminada', terminada_en = now(), avance_en = now() where i.id = v.id returning * into v;
  else
    if btrim(p_error) = '' or char_length(p_error) > 500 then
      raise exception 'El motivo del fallo lleva de 1 a 500 caracteres.' using errcode = '22023', hint = 'error';
    end if;
    update public.importaciones i
       set estado = 'fallida', errores = jsonb_build_array(jsonb_build_object('motivo', btrim(p_error))), terminada_en = now(), avance_en = now()
     where i.id = v.id returning * into v;
  end if;
  perform public._importacion_fijar(v.usuario_id);
  perform public.registrar_actividad('datos.importado', 'importaciones', v.id::text, null, null, jsonb_build_object(
    'entidad', v.entidad, 'estado', v.estado, 'filas', v.filas_total, 'procesadas', v.procesadas, 'creadas', coalesce(v.filas_ok, 0),
    'ya_existian', v.ya_existian, 'rechazadas', v.rechazadas, 'asignar_a', v.asignar_a));
  perform public._importacion_volver(v_previo);
  return jsonb_build_object('importacion', v.id, 'estado', v.estado, 'creadas', coalesce(v.filas_ok, 0), 'ya_existian', v.ya_existian,
                            'rechazadas', v.rechazadas, 'repetido', false);
end;
$$;


ALTER FUNCTION "public"."importacion_terminar"("p_importacion" "uuid", "p_error" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."importacion_terminar"("p_importacion" "uuid", "p_error" "text") IS 'Importación total (9.06), sólo service_role: terminada (todas las filas procesadas) o fallida (p_error), con la constancia datos.importado a nombre de quien importa.';



CREATE OR REPLACE FUNCTION "public"."importaciones_continuar_correr"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_url text := public._url_del_proyecto();
begin
  if v_url is null then
    raise warning 'importaciones-continuar no corrió: falta el secreto url_proyecto en Vault (lo pone scripts/demo/restaurar.sh).';
    return null;
  end if;
  return public.importaciones_continuar_disparar(v_url || '/functions/v1/importar-csv');
end;
$$;


ALTER FUNCTION "public"."importaciones_continuar_correr"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."importaciones_continuar_correr"() IS 'El job importaciones-continuar: retoma las importaciones totales detenidas con la URL de Vault (url_proyecto). Sin el secreto, avisa y no hace nada.';



CREATE OR REPLACE FUNCTION "public"."importaciones_continuar_disparar"("p_url" "text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_id uuid;
  v_pase uuid;
  v_n integer := 0;
begin
  if p_url is null or p_url !~ '^https?://[^[:space:]]+/functions/v1/importar-csv$' then
    raise exception 'La dirección de importar-csv no es válida.' using errcode = '22023';
  end if;

  -- 24 horas sin avance: fallida (hasta 50 por corrida; una que la función tiene tomada se salta). Sobre importaciones_en_curso_idx.
  for v_id in
    select i.id from public.importaciones i
     where i.archivo_ruta is not null and i.estado in ('pendiente', 'procesando')
       and coalesce(i.avance_en, i.creado_en) < now() - interval '24 hours'
     order by coalesce(i.avance_en, i.creado_en), i.id
     limit 50
     for update skip locked
  loop
    perform public._importacion_fallar(v_id, 'sin_avance');
  end loop;

  -- Hasta 5 detenidas: más de 2 minutos sin avance y sin un pase de los últimos 5 minutos. Sobre importaciones_en_curso_idx y, el pase
  -- reciente, sobre importaciones_pases_importacion_idx.
  for v_id in
    select i.id from public.importaciones i
     where i.archivo_ruta is not null and i.estado in ('pendiente', 'procesando')
       and coalesce(i.avance_en, i.creado_en) < now() - interval '2 minutes'
       and not exists (select 1 from public.importaciones_pases p
                        where p.importacion_id = i.id and p.creado_en > now() - interval '5 minutes')
     order by coalesce(i.avance_en, i.creado_en), i.id
     limit 5
     for update skip locked
  loop
    insert into public.importaciones_pases (importacion_id) values (v_id) returning pase into v_pase;
    perform net.http_post(url := p_url, body := jsonb_build_object('pase', v_pase),
      headers := jsonb_build_object('Content-Type', 'application/json'), timeout_milliseconds := 60000);
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$_$;


ALTER FUNCTION "public"."importaciones_continuar_disparar"("p_url" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."importaciones_continuar_disparar"("p_url" "text") IS 'Una corrida de importaciones-continuar contra esa dirección de importar-csv: deja fallidas las totales sin avance en 24 h (50 por corrida) y manda un pase a hasta 5 detenidas (2 min sin avance, sin pase reciente). Devuelve los pedidos mandados. Sólo service_role.';



CREATE OR REPLACE FUNCTION "public"."importaciones_filas_purgar"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n integer; v_total integer := 0; i integer;
begin
  -- Las filas de una total terminada o fallida hace más de 30 días, por su clave primaria (importacion_id, fila).
  for i in 1..10 loop
    delete from public.importaciones_filas f
     where (f.importacion_id, f.fila) in (
       select y.importacion_id, y.fila from public.importaciones_filas y
        where y.importacion_id in (
          select im.id from public.importaciones im
           where im.archivo_ruta is not null and im.estado in ('terminada', 'fallida')
             and im.terminada_en < now() - interval '30 days')
        limit 10000);
    get diagnostics v_n = row_count;
    v_total := v_total + v_n;
    exit when v_n < 10000;
  end loop;

  -- Los pases de más de 7 días (pocos por importación: emitir reusa el vivo y el job manda uno cada 5 minutos a lo sumo).
  for i in 1..10 loop
    delete from public.importaciones_pases p
     where p.pase in (select q.pase from public.importaciones_pases q where q.creado_en < now() - interval '7 days' limit 10000);
    get diagnostics v_n = row_count;
    exit when v_n < 10000;
  end loop;
  return v_total;
end;
$$;


ALTER FUNCTION "public"."importaciones_filas_purgar"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."importaciones_filas_purgar"() IS 'El job importaciones-filas-purgar: borra el informe por fila de las importaciones totales terminadas o fallidas hace más de 30 días y los pases de más de 7, de a 10.000 y hasta 10 lotes por corrida. Devuelve las filas del informe borradas.';



CREATE OR REPLACE FUNCTION "public"."importaciones_vinculos_purgar"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n integer; v_total integer := 0; i integer;
begin
  for i in 1..10 loop
    delete from public.importaciones_leads il
     where (il.importacion_id, il.lead_id) in (
       select y.importacion_id, y.lead_id from public.importaciones_leads y
        where y.importacion_id in (
          select im.id from public.importaciones im
           where im.entidad = 'leads'
             and coalesce(im.deshecha_en, public._importacion_vence_en(im)) < now() - interval '7 days')
        limit 10000);
    get diagnostics v_n = row_count;
    v_total := v_total + v_n;
    exit when v_n < 10000;
  end loop;
  return v_total;
end;
$$;


ALTER FUNCTION "public"."importaciones_vinculos_purgar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."integracion_guardar"("p_clave" "text", "p_actualizado_en_esperado" timestamp with time zone, "p_activa" boolean DEFAULT NULL::boolean, "p_config" "jsonb" DEFAULT NULL::"jsonb") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v public.integraciones;
  v_nueva timestamptz;
  v_config jsonb := p_config;
  v_url text;
begin
  perform public.assert_permiso('empresa.ajustes.gestionar');
  select * into v from public.integraciones i where i.clave = p_clave for update;
  if not found then
    raise exception 'Esa integración no existe.';
  end if;
  perform public._exigir_version(v.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió esta integración mientras la editabas.');
  if p_config is not null and jsonb_typeof(p_config) <> 'object' then
    raise exception 'La configuración no tiene la forma esperada.';
  end if;
  if v.clave = 'apibara' and p_config is not null
     and coalesce(p_config ->> 'endpoint', '') !~ '^https://([a-z0-9-]+\.)*apibara\.tech(:[0-9]+)?(/[^[:space:]]*)?$' then
    raise exception 'La dirección de apibara tiene que empezar con https:// y ser de apibara.tech.';
  end if;
  if v.clave = 'web_publica' and p_config is not null then
    v_url := nullif(btrim(coalesce(p_config ->> 'revalidar_url', '')), '');
    if v_url is not null and length(v_url) > 2000 then
      raise exception 'La dirección es demasiado larga.' using errcode = '22023', hint = 'revalidar_url';
    end if;
    if v_url is not null
       and v_url !~* '^https://[a-z0-9.-]+(:[0-9]{1,5})?(/[^[:space:]]*)?$'
       and v_url !~* '^http://(localhost|127\.0\.0\.1)(:[0-9]{1,5})?(/[^[:space:]]*)?$' then
      raise exception 'La dirección de revalidación tiene que empezar con https://.' using errcode = '22023', hint = 'revalidar_url';
    end if;
    v_config := jsonb_build_object('revalidar_url', v_url);
  end if;
  if coalesce(p_activa, v.activa) and v.clave = 'apibara' and v.secreto_guardado_en is null then
    raise exception 'Guarda la clave de apibara antes de activarla.';
  end if;
  update public.integraciones i set
    activa = coalesce(p_activa, i.activa),
    config = coalesce(v_config, i.config),
    actualizado_por = (select auth.uid())
  where i.clave = v.clave
  returning i.actualizado_en into v_nueva;
  return v_nueva;
end;
$_$;


ALTER FUNCTION "public"."integracion_guardar"("p_clave" "text", "p_actualizado_en_esperado" timestamp with time zone, "p_activa" boolean, "p_config" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."integracion_guardar_secreto"("p_clave" "text", "p_secreto" "text", "p_actualizado_en_esperado" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.integraciones;
  v_nombre text := 'integracion:' || p_clave;
  v_secreto text := btrim(coalesce(p_secreto, ''));
  v_id uuid;
  v_nueva timestamptz;
begin
  perform public.assert_permiso('empresa.ajustes.gestionar');
  select * into v from public.integraciones i where i.clave = p_clave for update;
  if not found then
    raise exception 'Esa integración no existe.';
  end if;
  perform public._exigir_version(v.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió esta integración mientras la editabas.');
  if length(v_secreto) < 8 or length(v_secreto) > 500 then
    raise exception 'La clave tiene que tener entre 8 y 500 caracteres.';
  end if;
  select s.id into v_id from vault.secrets s where s.name = v_nombre;
  if v_id is null then
    perform vault.create_secret(new_secret => v_secreto, new_name => v_nombre, new_description => 'Secreto de la integración ' || p_clave);
  else
    perform vault.update_secret(secret_id => v_id, new_secret => v_secreto);
  end if;
  update public.integraciones i set
    secreto_guardado_en = now(),
    actualizado_por = (select auth.uid())
  where i.clave = v.clave
  returning i.actualizado_en into v_nueva;
  return v_nueva;
end;
$$;


ALTER FUNCTION "public"."integracion_guardar_secreto"("p_clave" "text", "p_secreto" "text", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."integracion_secreto"("p_clave" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select s.decrypted_secret from vault.decrypted_secrets s where s.name = 'integracion:' || p_clave;
$$;


ALTER FUNCTION "public"."integracion_secreto"("p_clave" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_alta_contexto"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_ultimo text;
begin
  perform public.assert_permiso('leads.crear');
  select pu.valor #>> '{}' into v_ultimo
    from public.preferencias_usuario pu
   where pu.usuario_id = (select auth.uid()) and pu.clave = 'leads.ultimo_origen_lead';
  return jsonb_build_object(
    'telefono_cc', (select e.telefono_cc from public.ajustes_empresa e where e.id = 1),
    -- La ciudad y el país de la empresa: de ahí salen los valores por defecto «la de la empresa».
    'empresa', (select jsonb_build_object('ciudad', e.ciudad, 'pais', e.pais) from public.ajustes_empresa e where e.id = 1),
    'topes', jsonb_build_object('origenes', public._origenes_lead_tope(), 'tipos', public._tipos_lead_tope(),
                                'tipos_seguimiento', public._tipos_seguimiento_tope()),
    'origenes', coalesce((
      select jsonb_agg(jsonb_build_object('id', q.id, 'nombre', q.nombre) order by q.orden, q.nombre)
        from (select o.id, o.nombre, o.orden from public.origenes_lead o where o.activo
               order by o.orden, o.nombre limit public._origenes_lead_tope()) q), '[]'::jsonb),
    'tipos_seguimiento', coalesce((
      select jsonb_agg(jsonb_build_object('id', q.id, 'nombre', q.nombre) order by q.orden, q.nombre)
        from (select t.id, t.nombre, t.orden from public.tipos_seguimiento t where t.activo
               order by t.orden, t.nombre limit public._tipos_seguimiento_tope()) q), '[]'::jsonb),
    'tipos', coalesce((
      select jsonb_agg(jsonb_build_object('id', q.id, 'nombre', q.nombre, 'clase', q.clase) order by q.orden, q.nombre)
        from (select x.id, x.nombre, x.clase, x.orden from public.tipos_lead x where x.activo
               order by x.orden, x.nombre limit public._tipos_lead_tope()) q), '[]'::jsonb),
    'tipo_por_defecto_id', public._tipo_lead_por_defecto(),
    'origen_por_defecto_id', (select o.id from public.origenes_lead o where o.por_defecto and o.activo),
    'ultimo_origen_id', (select o.id from public.origenes_lead o where o.id::text = v_ultimo and o.activo));
end;
$$;


ALTER FUNCTION "public"."lead_alta_contexto"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_auditar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and new.actualizado_en is not distinct from old.actualizado_en then
    return null;
  end if;
  insert into public.actividad (accion, actor_id, tabla, registro_id, antes, despues)
  values ('leads.' || lower(tg_op), (select auth.uid()), 'leads', coalesce(new.id, old.id)::text,
          case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) - 'telefono_principal' - 'numero' - 'numero_propio' end,
          case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) - 'telefono_principal' - 'numero' - 'numero_propio' end);
  return null;
end;
$$;


ALTER FUNCTION "public"."lead_auditar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_campo_crear"("p_clave" "text", "p_etiqueta" "text", "p_tipo" "public"."tipo_campo", "p_opciones" "jsonb" DEFAULT '[]'::"jsonb", "p_requerido" boolean DEFAULT false, "p_grupo" "text" DEFAULT NULL::"text", "p_en_tabla" boolean DEFAULT false, "p_filtrable" boolean DEFAULT false, "p_solo_cartera" boolean DEFAULT NULL::boolean, "p_valor_defecto" "jsonb" DEFAULT NULL::"jsonb", "p_valor_defecto_empresa" "text" DEFAULT NULL::"text", "p_minimo" numeric DEFAULT NULL::numeric, "p_maximo" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_etiqueta text; v_grupo text := nullif(btrim(p_grupo), ''); v_id uuid; v_version timestamptz;
  v_defecto jsonb; v_empresa text;
begin
  perform public.assert_permiso('leads.campos.gestionar');
  -- El orden es del layout entero: el candado también ordena el «último + 10» de dos altas a la vez.
  lock table public.leads_campos in share row exclusive mode;
  if p_clave is null or p_clave !~ '^[a-z][a-z0-9_]{1,40}$' then
    raise exception 'La clave del campo usa minúsculas, números y guion bajo, y empieza con una letra.';
  end if;
  if public._lead_clave_reservada(p_clave) then
    raise exception '«%» ya es un dato fijo de todos los leads: no se crea como campo propio.', p_clave;
  end if;
  if p_tipo in ('vin', 'lote') then
    raise exception 'Un lead no lleva campos de ese tipo.';
  end if;
  v_etiqueta := public._campo_nombre_valido(p_etiqueta, 'el nombre del campo', 60);
  perform public._campo_opciones_validas(coalesce(p_opciones, '[]'::jsonb));
  if p_tipo in ('opcion', 'multi_opcion') and jsonb_array_length(coalesce(p_opciones, '[]'::jsonb)) = 0 then
    raise exception 'Un campo de opciones necesita al menos una opción.';
  end if;
  if p_tipo not in ('opcion', 'multi_opcion') and jsonb_array_length(coalesce(p_opciones, '[]'::jsonb)) > 0 then
    raise exception 'Sólo un campo de opciones lleva opciones.';
  end if;
  if v_grupo is not null and length(v_grupo) > 40 then raise exception 'El nombre del grupo no puede pasar de 40 caracteres.'; end if;
  v_defecto := public._campo_valor_defecto(p_tipo, coalesce(p_opciones, '[]'::jsonb), p_valor_defecto);
  v_empresa := public._lead_defecto_empresa(p_tipo, v_defecto, p_valor_defecto_empresa);
  perform public._campo_rango(p_tipo, p_minimo, p_maximo, v_defecto);
  begin
    insert into public.leads_campos (clave, etiqueta, tipo, opciones, requerido, grupo, orden, en_tabla, filtrable,
                                     solo_cartera, es_sistema, valor_defecto, valor_defecto_empresa, minimo, maximo)
    values (p_clave, v_etiqueta, p_tipo, coalesce(p_opciones, '[]'::jsonb), coalesce(p_requerido, false), v_grupo,
            coalesce((select max(c.orden) + 10 from public.leads_campos c), 10),
            coalesce(p_en_tabla, false), coalesce(p_filtrable, false),
            coalesce(p_solo_cartera, p_tipo in ('correo', 'documento')), false, v_defecto, v_empresa, p_minimo, p_maximo)
    returning id, actualizado_en into v_id, v_version;
  exception when unique_violation then
    raise exception 'Ya hay un campo con la clave «%».', p_clave using errcode = '23505';
  end;
  return jsonb_build_object('id', v_id, 'actualizado_en', v_version);
end;
$_$;


ALTER FUNCTION "public"."lead_campo_crear"("p_clave" "text", "p_etiqueta" "text", "p_tipo" "public"."tipo_campo", "p_opciones" "jsonb", "p_requerido" boolean, "p_grupo" "text", "p_en_tabla" boolean, "p_filtrable" boolean, "p_solo_cartera" boolean, "p_valor_defecto" "jsonb", "p_valor_defecto_empresa" "text", "p_minimo" numeric, "p_maximo" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_campo_eliminar"("p_campo" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.leads_campos; v_con int;
begin
  perform public.assert_permiso('leads.campos.gestionar');
  select * into c from public.leads_campos x where x.id = p_campo for update;
  if not found then raise exception 'Ese campo ya no existe.' using errcode = 'PT409'; end if;
  perform public._exigir_version(c.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este campo mientras lo editabas.');
  if c.es_sistema then
    raise exception '«%» es un campo de fábrica: no se elimina. Puedes desactivarlo.', c.etiqueta using errcode = '23503';
  end if;
  v_con := public._lead_campo_con_valor(c.clave);
  if v_con > 0 then
    raise exception '% % tienen un valor en «%». Desactívalo para conservarlo.',
      v_con, case when v_con = 1 then 'lead' else 'leads' end, c.etiqueta using errcode = '23503';
  end if;
  delete from public.leads_campos where id = p_campo;
end;
$$;


ALTER FUNCTION "public"."lead_campo_eliminar"("p_campo" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_campo_guardar"("p_campo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.leads_campos; v_clave text; v_nueva timestamptz;
  v_editables constant text[] := array['etiqueta', 'tipo', 'opciones', 'requerido', 'grupo', 'en_tabla', 'filtrable',
    'solo_cartera', 'activo', 'valor_defecto', 'valor_defecto_empresa', 'minimo', 'maximo'];
  v_tipo public.tipo_campo; v_opciones jsonb; v_grupo text; v_con int; v_orden smallint; v_defecto jsonb; v_empresa text;
  v_minimo numeric; v_maximo numeric;
  v_privado boolean := (p_cambios ->> 'solo_cartera')::boolean; v_pendiente boolean;
begin
  perform public.assert_permiso('leads.campos.gestionar');
  if p_cambios is null or jsonb_typeof(p_cambios) <> 'object' then
    raise exception 'Faltan los cambios a guardar.';
  end if;
  for v_clave in select jsonb_object_keys(p_cambios) loop
    if not (v_clave = any (v_editables)) then
      raise exception 'El dato «%» no se cambia desde el layout de campos.', v_clave;
    end if;
    if v_clave in ('etiqueta', 'tipo', 'opciones', 'requerido', 'en_tabla', 'filtrable', 'solo_cartera', 'activo')
       and p_cambios -> v_clave = 'null'::jsonb then
      raise exception 'El dato «%» no puede quedar vacío.', v_clave;
    end if;
  end loop;

  lock table public.leads_campos in share row exclusive mode;
  select * into c from public.leads_campos x where x.id = p_campo for update;
  if not found then raise exception 'Ese campo ya no existe.' using errcode = 'PT409'; end if;
  perform public._exigir_version(c.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este campo mientras lo editabas.');

  v_tipo := coalesce((p_cambios ->> 'tipo')::public.tipo_campo, c.tipo);
  if v_tipo is distinct from c.tipo then
    if c.es_sistema then
      raise exception 'El tipo de «%» no cambia: es un campo de fábrica.', c.etiqueta;
    end if;
    if v_tipo in ('vin', 'lote') then
      raise exception 'Un lead no lleva campos de ese tipo.';
    end if;
    v_con := public._lead_campo_con_valor(c.clave);
    if v_con > 0 then
      raise exception '% % ya tienen un valor en «%»: no se puede cambiar su tipo. Desactívalo y crea otro campo.',
        v_con, case when v_con = 1 then 'lead' else 'leads' end, c.etiqueta;
    end if;
  end if;

  v_opciones := coalesce(p_cambios -> 'opciones', c.opciones);
  if v_tipo not in ('opcion', 'multi_opcion') then
    v_opciones := '[]'::jsonb;
  else
    perform public._campo_opciones_validas(v_opciones);
    if jsonb_array_length(v_opciones) = 0 then
      raise exception 'Un campo de opciones necesita al menos una opción.';
    end if;
  end if;

  if p_cambios ? 'valor_defecto' then
    v_defecto := public._campo_valor_defecto(v_tipo, v_opciones, p_cambios -> 'valor_defecto');
  elsif v_tipo is distinct from c.tipo then
    v_defecto := null;
  else
    begin
      v_defecto := public._campo_valor_defecto(v_tipo, v_opciones, c.valor_defecto);
    exception when invalid_parameter_value then
      v_defecto := null;
    end;
  end if;

  -- El rango: lo que se manda (null = sin límite) o el vigente; si el tipo deja de ser numérico, se va solo, como las opciones.
  v_minimo := public._campo_limite(p_cambios, 'minimo', case when v_tipo in ('numero', 'moneda') then c.minimo end);
  v_maximo := public._campo_limite(p_cambios, 'maximo', case when v_tipo in ('numero', 'moneda') then c.maximo end);
  perform public._campo_rango(v_tipo, v_minimo, v_maximo, v_defecto);

  -- «La de la empresa»: si ahora hay un valor fijo se va solo; si el tipo ya no es texto, también.
  if p_cambios ? 'valor_defecto_empresa' then
    v_empresa := public._lead_defecto_empresa(v_tipo, v_defecto, p_cambios ->> 'valor_defecto_empresa');
  elsif v_tipo <> 'texto' or v_defecto is not null then
    v_empresa := null;
  else
    v_empresa := c.valor_defecto_empresa;
  end if;

  v_grupo := case when p_cambios ? 'grupo' then nullif(btrim(p_cambios ->> 'grupo'), '') else c.grupo end;
  if v_grupo is not null and length(v_grupo) > 40 then raise exception 'El nombre del grupo no puede pasar de 40 caracteres.'; end if;

  -- Cambiar de grupo lo manda al final del grupo nuevo.
  v_orden := c.orden;
  if v_grupo is distinct from c.grupo then
    select max(x.orden) + 1 into v_orden from public.leads_campos x where x.id <> c.id and x.grupo is not distinct from v_grupo;
    v_orden := coalesce(v_orden, (select coalesce(max(x.orden), 0) + 10 from public.leads_campos x));
  end if;

  update public.leads_campos x set
    etiqueta = case when p_cambios ? 'etiqueta' then public._campo_nombre_valido(p_cambios ->> 'etiqueta', 'el nombre del campo', 60) else x.etiqueta end,
    tipo = v_tipo,
    opciones = v_opciones,
    requerido = coalesce((p_cambios ->> 'requerido')::boolean, x.requerido),
    grupo = v_grupo,
    en_tabla = coalesce((p_cambios ->> 'en_tabla')::boolean, x.en_tabla),
    filtrable = coalesce((p_cambios ->> 'filtrable')::boolean, x.filtrable),
    -- 9h: pasar a privado no cambia `solo_cartera` hasta quitar la clave de los atributos públicos de todos los leads
    -- (por lotes, `_lead_campo_privacidad_lote`); pasar a público es inmediato y deja completar los atributos públicos.
    solo_cartera = case when v_privado is null or v_privado then x.solo_cartera else false end,
    solo_cartera_pendiente = case
      when v_privado is null then x.solo_cartera_pendiente
      when v_privado and x.solo_cartera and x.solo_cartera_pendiente is null then null
      when v_privado then true
      when not x.solo_cartera and x.solo_cartera_pendiente is null then null
      else false end,
    activo = coalesce((p_cambios ->> 'activo')::boolean, x.activo),
    valor_defecto = v_defecto,
    valor_defecto_empresa = v_empresa,
    minimo = v_minimo,
    maximo = v_maximo,
    orden = v_orden
  where x.id = p_campo
  returning x.actualizado_en, x.solo_cartera_pendiente into v_nueva, v_pendiente;
  if v_orden is distinct from c.orden then
    perform public._lead_campos_renumerar();
  end if;
  -- El primer lote, en esta misma llamada: una base chica termina acá. Lo que quede lo sigue el job.
  if v_pendiente is not null then
    perform public._lead_campo_privacidad_lote(p_campo, 5000);
  end if;
  return v_nueva;
end;
$$;


ALTER FUNCTION "public"."lead_campo_guardar"("p_campo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_campo_impacto"("p_campo" "uuid", "p_cambios" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.leads_campos; v_min numeric; v_max numeric; v_fuera int;
begin
  perform public.assert_permiso('leads.campos.gestionar');
  if p_cambios is not null and jsonb_typeof(p_cambios) <> 'object' then
    raise exception 'Faltan los cambios a medir.' using errcode = '22023';
  end if;
  select * into c from public.leads_campos x where x.id = p_campo;
  if not found then raise exception 'Ese campo ya no existe.' using errcode = 'PT409'; end if;
  -- Los fuera del rango propuesto (o del vigente), con tope 50 y uno de más; null si el campo no es numérico o no tiene límites.
  v_min := public._campo_limite(coalesce(p_cambios, '{}'::jsonb), 'minimo', c.minimo);
  v_max := public._campo_limite(coalesce(p_cambios, '{}'::jsonb), 'maximo', c.maximo);
  if c.tipo in ('numero', 'moneda') and (v_min is not null or v_max is not null) then
    select count(*)::int into v_fuera from (
      select 1 from public.leads l where public._valor_fuera_de_rango(l.atributos -> c.clave, v_min, v_max) limit 51) q;
  end if;
  return public._campo_impacto(array(select l.atributos -> c.clave from public.leads l), c.tipo)
         || jsonb_build_object('fuera_de_rango', v_fuera);
end;
$$;


ALTER FUNCTION "public"."lead_campo_impacto"("p_campo" "uuid", "p_cambios" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_campo_mover"("p_campo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_despues_de" "uuid" DEFAULT NULL::"uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.leads_campos; v_nueva timestamptz;
begin
  perform public.assert_permiso('leads.campos.gestionar');
  -- El orden es del layout entero: el candado hace que dos reordenamientos vayan en fila.
  lock table public.leads_campos in share row exclusive mode;
  select * into c from public.leads_campos x where x.id = p_campo for update;
  if not found then raise exception 'Ese campo ya no existe.' using errcode = 'PT409'; end if;
  perform public._exigir_version(c.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este campo mientras lo editabas.');
  if p_despues_de is not null then
    if p_despues_de = p_campo then raise exception 'Un campo no puede ir después de sí mismo.'; end if;
    if not exists (select 1 from public.leads_campos x where x.id = p_despues_de) then
      raise exception 'Ese campo ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
    end if;
  end if;

  update public.leads_campos x set orden = n.orden_nuevo
  from public._campos_reordenar((
    select jsonb_agg(jsonb_build_object('id', y.id, 'clave', y.clave, 'orden', y.orden)) from public.leads_campos y),
    p_campo, p_despues_de) n
  where x.id = n.campo_id and x.orden <> n.orden_nuevo;

  select x.actualizado_en into v_nueva from public.leads_campos x where x.id = p_campo;
  return v_nueva;
end;
$$;


ALTER FUNCTION "public"."lead_campo_mover"("p_campo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_despues_de" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_cartera"("p_lead" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_lead is null or not public.puede_lead(p_lead, 'leads.ver') then
    return null;
  end if;
  return public._lead_cartera_json(p_lead);
end;
$$;


ALTER FUNCTION "public"."lead_cartera"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_cartera_candidatos"("p_lead" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_lead is null or not public.puede_lead(p_lead, 'leads.ver')
     or (public.alcance_de('leads.compartir') is null and public.alcance_de('leads.transferir') is null) then
    return '[]'::jsonb;
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', x.id, 'nombre', x.nombre) order by lower(x.nombre), x.id)
    from (
      select p.id, coalesce(nullif(btrim(p.nombre), ''), 'Sin nombre') as nombre
      from public.perfiles p
      where p.activo and not p.bloqueado and p.id <> (select auth.uid())
        and public.usuario_tiene_permiso(p.id, 'leads.ver')
        and not exists (select 1 from public.leads_asesores a
                        where a.lead_id = p_lead and a.usuario_id = p.id and a.revocado_en is null)
      order by lower(coalesce(nullif(btrim(p.nombre), ''), 'Sin nombre')), p.id
      limit 500
    ) x), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."lead_cartera_candidatos"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_cliente_desde"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_cambio boolean;
  v_era_prospecto boolean;
  v_es_cliente boolean;
begin
  -- D4: un alta nunca trae fecha, venga como venga.
  if tg_op = 'INSERT' then
    new.cliente_desde := null;
    return new;
  end if;
  -- Nadie la escribe a mano: sin cambio de tipo, queda la que había.
  v_cambio := new.tipo_lead_id is distinct from old.tipo_lead_id;
  if not v_cambio then
    new.cliente_desde := old.cliente_desde;
    return new;
  end if;
  select coalesce(bool_or(t.clase = 'cliente'), false) into v_es_cliente from public.tipos_lead t where t.id = new.tipo_lead_id;
  select coalesce(bool_or(t.clase = 'prospecto'), false) into v_era_prospecto from public.tipos_lead t where t.id = old.tipo_lead_id;
  if not v_es_cliente then
    new.cliente_desde := null;
  elsif v_era_prospecto then
    new.cliente_desde := now();
  else
    -- D5: de cliente a cliente, la fecha de antes (nula si era un cliente sin fecha).
    new.cliente_desde := old.cliente_desde;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."lead_cliente_desde"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lead_compartir"("p_lead" "uuid", "p_usuario" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare l public.leads; v_dueno uuid; v_alcance public.alcance_permiso; v_yo uuid := (select auth.uid());
begin
  l := public._lead_para_mover(p_lead);
  v_dueno := public._lead_dueno(l.id);
  v_alcance := public.alcance_de('leads.compartir');
  if v_alcance is null then
    raise exception 'No tienes permiso para compartir este lead.' using errcode = '42501';
  end if;
  if v_alcance <> 'todos' and v_dueno is distinct from v_yo then
    raise exception 'Sólo quien es dueño del lead lo comparte.' using errcode = '42501';
  end if;
  -- Nadie se da acceso a sí mismo: si ya lo tiene no pasa nada, si no, no se lo puede dar.
  if p_usuario = v_yo then
    if public.en_cartera(l.id) then
      return jsonb_build_object('resultado', 'sin_cambios', 'cartera', public._lead_cartera_json(l.id));
    end if;
    raise exception 'No puedes darte acceso a un lead que no tienes.' using errcode = '42501', hint = 'usuario';
  end if;
  perform public._lead_destino_validar(p_usuario);
  if exists (select 1 from public.leads_asesores a where a.lead_id = l.id and a.usuario_id = p_usuario and a.revocado_en is null) then
    return jsonb_build_object('resultado', 'sin_cambios', 'cartera', public._lead_cartera_json(l.id));
  end if;
  insert into public.leads_asesores (lead_id, usuario_id, tipo_acceso, compartido_por)
  values (l.id, p_usuario, 'compartido', v_yo)
  on conflict (lead_id, usuario_id) do update set tipo_acceso = 'compartido', revocado_en = null, revocado_por = null,
    compartido_por = excluded.compartido_por, desde = now();
  perform public.registrar_actividad('lead.compartido', 'leads', l.id::text, null, jsonb_build_object('con', p_usuario));
  -- El aviso a quien recibe: sin teléfono, número ni nombre del lead; el abierto de antes se reemplaza (si no, el antispam lo tragaría).
  delete from public.notificaciones n
  where n.usuario_id = p_usuario and n.tipo = 'lead_compartido' and n.referencia_id = l.id and n.accionada_en is null;
  perform public.notificar(p_usuario, 'lead_compartido',
    coalesce((select nullif(btrim(p.nombre), '') from public.perfiles p where p.id = v_yo), 'Alguien') || ' te compartió un lead',
    null, 'lead', l.id, '/leads/' || l.id, false);
  return jsonb_build_object('resultado', 'compartido', 'cartera', public._lead_cartera_json(l.id));
end;
$$;


ALTER FUNCTION "public"."lead_compartir"("p_lead" "uuid", "p_usuario" "uuid") OWNER TO "postgres";


