    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.creado_por is not null then
    insert into public.leads_asesores (lead_id, usuario_id, tipo_acceso) values (new.id, new.creado_por, 'dueno') on conflict do nothing;
  end if;
  return new;
end;
