CREATE OR REPLACE FUNCTION "public"."leads_asesores_creado_en_guarda"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if pg_trigger_depth() < 2 then
    if new.lead_id is distinct from old.lead_id or new.lead_creado_en is distinct from old.lead_creado_en then
      raise exception 'La fecha de creación del lead en la cartera sigue a la del lead: no se cambia a mano.' using errcode = '23514';
    end if;
    if new.lead_reciente_en is distinct from old.lead_reciente_en then
      raise exception 'Lo reciente del lead en la cartera sigue al lead: no se cambia a mano.' using errcode = '23514';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."leads_asesores_creado_en_guarda"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leads_campos_privacidad_aplicar"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_campo uuid; v_lotes int := 0; v_terminados int := 0; v_listo boolean;
begin
  for v_campo in select x.id from public.leads_campos x where x.solo_cartera_pendiente is not null order by x.id loop
    loop
      v_listo := public._lead_campo_privacidad_lote(v_campo, 5000);
      v_lotes := v_lotes + 1;
      exit when v_listo or v_lotes >= 10;
    end loop;
    if v_listo then v_terminados := v_terminados + 1; end if;
    exit when v_lotes >= 10;
  end loop;
  return jsonb_build_object('lotes', v_lotes, 'campos_terminados', v_terminados);
end;
$$;


ALTER FUNCTION "public"."leads_campos_privacidad_aplicar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leads_candidatos"("p_filtros" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_alcance public.alcance_permiso := public.alcance_de('leads.ver');
  v_fuera uuid[] := public._bajas_en_curso();
  v_k int := public._leads_candidatos_tope();
  v_s int := public._leads_candidatos_recorrido();
  v_ids uuid[]; v_scanned int; v_completa boolean; v_hasta jsonb; v_ultimo uuid; v_acotada boolean := false; v_ids_tramo uuid[]; v_scanned_tramo int; v_ultimo_tramo uuid;
  v_extra uuid[]; v_mas uuid[]; v_atras boolean := (p_filtros ->> 'sentido') = 'anterior';
  v_en timestamptz := nullif(p_filtros #>> '{cursor,creado_en}', '')::timestamptz;
  v_id uuid := nullif(p_filtros #>> '{cursor,id}', '')::uuid;
  v_hasta_en timestamptz; v_hasta_id uuid;
  v_con_etiquetas boolean := coalesce(jsonb_typeof(p_filtros -> 'etiquetas') = 'array', false);
  v_etiquetas uuid[] := public._leads_candidatos_etiquetas(p_filtros, (select auth.uid()));
  v_solo_indice boolean := false;
  -- El tope de un campo público (ver `_leads_candidatos_sql`): quien ve «todos» y filtra sólo por el texto o el rango de un campo público recorre como mucho 2,5 ventanas.
  v_acotado boolean := v_alcance = 'todos'
    and public._leads_candidatos_indexable(jsonb_build_object('comparaciones', p_filtros -> 'comparaciones'))
    and not public._leads_candidatos_indexable(p_filtros - 'comparaciones')
    and coalesce(p_filtros -> 'sin_tope' is distinct from 'true'::jsonb, true);
  v_recorrido int := case when v_acotado then (v_s * 5) / 2 else v_s end;
  v_n_mas int;
begin
  -- Sin sesión, sin permiso o sin forma: nada (y lo mismo que cuando no coincide nadie).
  if v_yo is null or v_alcance is null or p_filtros is null or jsonb_typeof(p_filtros) <> 'object' then
    return jsonb_build_object('ids', '[]'::jsonb, 'completa', true, 'hasta', null);
  end if;
  -- Una etiqueta con pocos leads (como mucho S) se resuelve por su índice, sin recorrer antes el orden del listado: cuesta lo que tiene la etiqueta, no lo que haya que caminar
  -- hasta encontrarlos (Ana, con una etiqueta en 300 de sus 9.500 leads, caminaba 4.000 filas: 22 ms, y 147 cuando las estadísticas de `leads_etiquetas` no estaban al día).
  if v_con_etiquetas and cardinality(v_etiquetas) > 0 then
    v_solo_indice := (select count(*) from (select 1 from public.leads_etiquetas le where le.etiqueta_id = any (v_etiquetas) limit v_s + 1) x) <= v_s;
  end if;
  -- Lo mismo con los tachados de quien llama (5a-34): si son pocos, se resuelve por ellos sin recorrer antes el orden del listado.
  if coalesce(p_filtros -> 'tachados' = 'true'::jsonb, false) then
    v_solo_indice := v_solo_indice or (select count(*) from (select 1 from public.leads_tachados t where t.usuario_id = v_yo limit v_s + 1) x) <= v_s;
  end if;
  -- Sin nada que buscarle al índice, un solo recorrido sin tope (no dos: el de S filas y después el entero).
  if public._leads_candidatos_indexable(p_filtros) and not v_solo_indice then
    execute public._leads_candidatos_sql('recorrer', p_filtros, v_yo, v_alcance, v_fuera) into v_ids, v_scanned, v_ultimo;
  else
    v_ids := '{}'::uuid[]; v_scanned := v_s;
  end if;
  -- El tope de un campo público: si las S primeras filas no juntaron los candidatos, el recorrido sigue desde donde quedó hasta 2,5 ventanas en total (un valor denso no paga más que antes:
  -- corta en las S primeras). Los candidatos del tramo van después de los primeros, en el mismo orden.
  if v_acotado and cardinality(v_ids) <= v_k and v_scanned >= v_s and v_ultimo is not null then
    select l.creado_en into v_hasta_en from public.leads l where l.id = v_ultimo;
    execute public._leads_candidatos_sql('recorrer', p_filtros || jsonb_build_object('cursor', jsonb_build_object('creado_en', v_hasta_en, 'id', v_ultimo), 'recorrido', v_recorrido - v_s), v_yo, v_alcance, v_fuera)
      into v_ids_tramo, v_scanned_tramo, v_ultimo_tramo;
    v_ids := (v_ids || v_ids_tramo)[1:v_k + 1];
    v_scanned := v_scanned + v_scanned_tramo;
    v_ultimo := coalesce(v_ultimo_tramo, v_ultimo);
  end if;
  -- Con el tope no hay segunda etapa: lo que no se recorrió se dice (`acotada`) y se sigue desde `hasta`.
  if coalesce(cardinality(v_ids), 0) <= v_k and v_scanned >= v_s and not v_acotado then
    execute public._leads_candidatos_sql('indice', p_filtros, v_yo, v_alcance, v_fuera) into v_ids, v_scanned, v_ultimo;
  end if;
  v_ids := coalesce(v_ids, '{}'::uuid[]);
  v_acotada := v_acotado and cardinality(v_ids) <= v_k and v_scanned >= v_recorrido and v_ultimo is not null;
  v_completa := cardinality(v_ids) <= v_k and not v_acotada;
  if v_acotada then
    -- Hasta dónde llegó el recorrido: el último lead que miró, en el orden del listado.
    select l.creado_en, l.id into v_hasta_en, v_hasta_id from public.leads l where l.id = v_ultimo;
    v_hasta := jsonb_build_object('creado_en', v_hasta_en, 'id', v_hasta_id);
  elsif not v_completa then
    select l.creado_en, l.id into v_hasta_en, v_hasta_id from public.leads l where l.id = v_ids[v_k];
    v_hasta := jsonb_build_object('creado_en', v_hasta_en, 'id', v_hasta_id);
    v_ids := v_ids[1:v_k];
  end if;
  -- Los ids que cuentan aunque el nombre no coincida (el lead con el número buscado): los visibles que caen en la ventana y cumplen lo mismo que ella.
  if jsonb_typeof(p_filtros -> 'extra') = 'array' then
    v_extra := array(select jsonb_array_elements_text(p_filtros -> 'extra'))::uuid[];
    execute public._leads_candidatos_sql('extra', p_filtros, v_yo, v_alcance, v_fuera) into v_mas, v_n_mas, v_ultimo using v_extra, v_completa, v_hasta_en, v_hasta_id;
    v_ids := array(select distinct u from unnest(v_ids || v_mas) u);
  end if;
  return jsonb_build_object('ids', to_jsonb(v_ids), 'completa', v_completa, 'hasta', v_hasta)
         || case when v_acotada then jsonb_build_object('acotada', true, 'recorridos', v_scanned) else '{}'::jsonb end;
end $$;


ALTER FUNCTION "public"."leads_candidatos"("p_filtros" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."leads_candidatos"("p_filtros" "jsonb") IS 'Los candidatos de una búsqueda del listado de leads (5a-fix-1b): los primeros K que cumplen, en el orden del listado y después del cursor, sólo de lo que quien llama ve, con si hay más y hasta dónde llegó. Sólo acota: la página la arma leads_vista_por_ids con las condiciones de siempre.';



CREATE OR REPLACE FUNCTION "public"."leads_cartera_corta"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    (select auth.uid()) is not null
    and (select count(*) from (select 1 from public.leads_asesores la
                                where la.usuario_id = (select auth.uid()) and la.revocado_en is null
                                limit public._leads_cartera_corta_tope() + 1) x) <= public._leads_cartera_corta_tope(),
    false)
$$;


ALTER FUNCTION "public"."leads_cartera_corta"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."leads_cartera_corta"() IS 'Si quien llama tiene como mucho _leads_cartera_corta_tope() filas vigentes en su cartera (5a-5). Sólo un sí o un no: la app lee «míos» por leads_cartera_vista si es así y quien ve «todos» tiene pocos leads propios. No devuelve ningún número.';



CREATE OR REPLACE FUNCTION "public"."leads_catalogos"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'origenes', coalesce((select jsonb_agg(jsonb_build_object('id', o.id, 'clave', o.clave, 'nombre', o.nombre, 'icono', o.icono, 'activo', o.activo)
                                           order by o.orden, o.nombre) from public.origenes_lead o), '[]'::jsonb),
    'tipos', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'clave', t.clave, 'nombre', t.nombre, 'clase', t.clase, 'icono', t.icono, 'activo', t.activo)
                                           order by t.orden, t.nombre) from public.tipos_lead t), '[]'::jsonb));
$$;


ALTER FUNCTION "public"."leads_catalogos"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leads_creado_en_seguir"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.leads_asesores set lead_creado_en = new.creado_en where lead_id = new.id;
  return null;
end;
$$;


ALTER FUNCTION "public"."leads_creado_en_seguir"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leads_exportacion_registrar"("p_filas" integer, "p_filtros" "text"[] DEFAULT '{}'::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_yo uuid := (select auth.uid());
  v_cuantas integer;
  v_desde timestamptz;
  v_f text;
begin
  perform public.assert_permiso('leads.exportar');
  perform public.assert_activo();
  if p_filas is null or p_filas < 0 or p_filas > 5000 then
    raise exception 'Una exportación lleva hasta 5.000 leads.' using errcode = '22023';
  end if;
  p_filtros := coalesce(p_filtros, '{}');
  if cardinality(p_filtros) > 40 then
    raise exception 'Demasiados filtros.' using errcode = '22023';
  end if;
  foreach v_f in array p_filtros loop
    if v_f is null or v_f !~ '^[a-z][a-z0-9_.]{0,60}$' then
      raise exception 'Un filtro no tiene un nombre válido.' using errcode = '22023';
    end if;
  end loop;
  -- Dos exportaciones a la vez de la misma persona no se cuelan juntas por debajo del tope.
  perform pg_advisory_xact_lock(hashtext('leads_exportacion'), hashtext(v_yo::text));
  select count(*), min(a.creado_en) into v_cuantas, v_desde
    from public.actividad a
   where a.actor_id = v_yo and a.accion = 'leads.exportado' and a.creado_en > now() - interval '1 hour';
  if v_cuantas >= 5 then
    return jsonb_build_object('ok', false, 'libre_en', v_desde + interval '1 hour');
  end if;
  perform public.registrar_actividad('leads.exportado', 'leads', null, null, null,
    jsonb_build_object('filas', p_filas, 'filtros', to_jsonb(p_filtros)));
  return jsonb_build_object('ok', true, 'restantes', 4 - v_cuantas);
end;
$_$;


ALTER FUNCTION "public"."leads_exportacion_registrar"("p_filas" integer, "p_filtros" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leads_ids_del_numero"("p_numero" bigint, "p_todos" boolean) RETURNS "uuid"[]
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(array(
    select t.lead_id
      from (
        select g.lead_id, 0 as orden
          from public.leads_numeros_globales g
         where p_todos and g.numero = p_numero
        union all
        select n.lead_id, 1
          from (select p.id from public.perfiles p where p_todos
                union all
                select (select auth.uid()) where not p_todos) c
         cross join lateral (select np.lead_id
                               from public.leads_numeros_propios np
                              where np.creado_por = c.id and np.numero = p_numero
                                and p_numero between 1 and 2147483647) n
      ) t
     group by t.lead_id
     order by min(t.orden), t.lead_id
     limit 100), '{}'::uuid[])
$$;


ALTER FUNCTION "public"."leads_ids_del_numero"("p_numero" bigint, "p_todos" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."leads_ids_del_numero"("p_numero" bigint, "p_todos" boolean) IS 'Los ids de los leads que quien llama ve con ese número: con p_todos, el global y el propio de cualquier creador (sólo con leads.numero_global.ver; sin él, el propio de quien llama); sin p_todos, el propio de quien llama. Invocador: la policy de las copias decide. Como mucho 100. Lo usa la búsqueda del listado y la exportación.';



CREATE OR REPLACE FUNCTION "public"."leads_importacion_deshacer"("p_importacion" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_orden constant text[] := array['papelera', 'otra_persona', 'compartido', 'editado', 'seguimientos',
    'recordatorios', 'telefonos', 'vehiculos', 'oportunidades', 'portal', 'otros'];
  i public.importaciones;
  r record;
  v_motivo text;
  v_movidos uuid[] := '{}'::uuid[];
  v_quedan jsonb := '[]'::jsonb;
  v_quedaron jsonb;
  v_por_motivo jsonb;
  v_vinculos integer;
  v_purgados integer;
  v_lote uuid;
  v_resultado jsonb;
  v_dueno uuid;
begin
  perform public.assert_activo();
  if p_importacion is null then
    raise exception 'Falta el identificador de la importación.' using errcode = '22023';
  end if;
  -- Primero se mira sin bloquear: a una importación ajena no se le toma el candado. Ajena, inexistente o
  -- de otra cosa que leads dicen lo mismo.
  if not exists (select 1 from public.importaciones x where x.id = p_importacion and x.usuario_id = v_yo and x.entidad = 'leads') then
    raise exception 'No encontramos esta importación.' using errcode = '42501';
  end if;
  select * into i from public.importaciones x where x.id = p_importacion for update;
  if i.usuario_id is distinct from v_yo or i.entidad <> 'leads' then
    raise exception 'No encontramos esta importación.' using errcode = '42501';
  end if;
  -- Ya deshecha: lo mismo que la primera vez (un doble clic o un reintento tardío no son un error).
  if i.deshecha_en is not null then
    return i.deshecha_resultado || jsonb_build_object('repetido', true);
  end if;
  -- Una importación total (9.06): sólo cuando ya no está en curso (deshacer nunca corta el proceso), con datos.importar.todo vigente si
  -- tuvo destino (mueve leads de otra persona) y con a lo sumo 2.000 leads creados.
  if i.archivo_ruta is not null then
    if i.estado in ('pendiente', 'procesando') then
      raise exception 'Esta importación sigue en curso: espera a que termine para deshacerla.' using errcode = '22023';
    end if;
    if i.con_destino and not (select public.tiene_permiso('datos.importar.todo')) then
      raise exception 'Ya no tienes el permiso para deshacer esta importación.' using errcode = '42501';
    end if;
    if coalesce(i.filas_ok, 0) > 2000 then
      raise exception 'Esta importación creó más de 2.000 leads: no se puede deshacer de una vez.' using errcode = '22023', hint = 'importacion';
    end if;
  end if;
  -- «Intacto» se mide contra quien recibió los leads: el destino de una total (nulo si su perfil se borró: nada se mueve), si no quien importó.
  v_dueno := case when i.con_destino then i.asignar_a else i.usuario_id end;
  if now() >= public._importacion_vence_en(i) then
    raise exception 'Pasaron más de 24 horas desde esta importación: ya no se puede deshacer.' using errcode = '22023';
  end if;

  -- Los leads, bloqueados en orden; con el candado, cada uno se mira de nuevo (pudo cambiar mientras tanto).
  perform 1 from public.leads x
   where x.id in (select il.lead_id from public.importaciones_leads il where il.importacion_id = i.id)
   order by x.id for update;
  for r in select il.lead_id, il.fila from public.importaciones_leads il where il.importacion_id = i.id order by il.fila loop
    v_motivo := public._lead_motivo_para_deshacer(r.lead_id, v_dueno);
    if v_motivo is null then
      v_movidos := v_movidos || r.lead_id;
    else
      v_quedan := v_quedan || jsonb_build_object('motivo', v_motivo, 'fila', r.fila);
    end if;
  end loop;
  v_vinculos := (select count(*) from public.importaciones_leads il where il.importacion_id = i.id);
  -- Lo que ya se purgó de la papelera se fue con su vínculo (cascada).
  v_purgados := greatest(coalesce(i.filas_ok, 0) - v_vinculos, 0);

  if cardinality(v_movidos) > 0 then
    v_lote := gen_random_uuid();
    insert into public.lotes_papelera (id, tipo, creado_por, resumen)
    values (v_lote, 'leads', v_yo, jsonb_build_object('cantidad', cardinality(v_movidos), 'restaurados', 0, 'purgados', 0,
                                                      'importacion', i.id));
    update public.leads x set eliminado_en = now(), eliminado_por = v_yo, lote_papelera_id = v_lote
     where x.id = any (v_movidos);
    perform public._lote_papelera_tocar(v_lote);
    perform public.registrar_actividad('papelera.enviado', 'lotes_papelera', v_lote::text, null, null,
      jsonb_build_object('tipo', 'leads', 'cantidad', cardinality(v_movidos), 'portal_revocados', 0, 'desde', 'importacion'));
  end if;

  select coalesce(jsonb_agg(jsonb_build_object('motivo', m.motivo, 'cantidad', m.cantidad, 'filas', m.filas)
                            order by array_position(v_orden, m.motivo)), '[]'::jsonb),
         coalesce(jsonb_object_agg(m.motivo, m.cantidad), '{}'::jsonb)
    into v_quedaron, v_por_motivo
    from (select e ->> 'motivo' as motivo, count(*)::int as cantidad,
                 jsonb_agg((e ->> 'fila')::int order by (e ->> 'fila')::int) as filas
            from jsonb_array_elements(v_quedan) e group by 1) m;
  v_resultado := jsonb_build_object('importacion', i.id, 'movidos', cardinality(v_movidos),
    'quedaron', v_quedaron, 'purgados', v_purgados);

  -- Queda marcada; si seguía abierta, se cierra (un lote tardío de otra pestaña ya no crea nada; sólo una de `/leads`: la total en curso
  -- ya salió arriba). Sin
  -- `terminada_en`: su plazo y su fecha siguen siendo las del último lote.
  update public.importaciones x
     set deshecha_en = now(), deshecha_lote = v_lote, deshecha_resultado = v_resultado,
         estado = case when x.estado = 'procesando' then 'terminada'::public.estado_importacion else x.estado end
   where x.id = i.id;
  perform public.registrar_actividad('leads.importacion_deshecha', 'importaciones', i.id::text, null, null,
    jsonb_build_object('movidos', cardinality(v_movidos), 'quedaron', jsonb_array_length(v_quedan),
                       'por_motivo', v_por_motivo, 'purgados', v_purgados));
  return v_resultado || jsonb_build_object('repetido', false);
end;
$$;


ALTER FUNCTION "public"."leads_importacion_deshacer"("p_importacion" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leads_importacion_terminar"("p_importacion" "uuid", "p_ya_existian" integer, "p_rechazadas" integer, "p_origen" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_dueno uuid;
  v_estado public.estado_importacion;
  v_creadas integer;
begin
  perform public.assert_permiso('leads.crear');
  perform public.assert_activo();
  if p_ya_existian is null or p_ya_existian < 0 or p_ya_existian > 500 or p_rechazadas is null or p_rechazadas < 0 or p_rechazadas > 500 then
    raise exception 'Las cuentas de la importación no son válidas.' using errcode = '22023';
  end if;
  select i.usuario_id, i.estado into v_dueno, v_estado
    from public.importaciones i where i.id = p_importacion and i.entidad = 'leads' and i.archivo_ruta is null for update;
  if not found or v_dueno is distinct from v_yo then
    raise exception 'No encontramos esta importación.' using errcode = '42501';
  end if;
  select count(*) into v_creadas from public.importaciones_leads x where x.importacion_id = p_importacion;
  if v_estado = 'terminada' then
    return jsonb_build_object('importacion', p_importacion, 'creadas', v_creadas, 'repetido', true);
  end if;
  update public.importaciones set estado = 'terminada', terminada_en = now(), filas_ok = v_creadas
   where id = p_importacion;
  perform public.registrar_actividad('leads.importado', 'importaciones', p_importacion::text, null, null,
    jsonb_build_object('creadas', v_creadas, 'ya_existian', p_ya_existian, 'rechazadas', p_rechazadas));
  if p_origen is not null and exists (select 1 from public.origenes_lead o where o.id = p_origen and o.activo) then
    insert into public.preferencias_usuario (usuario_id, clave, valor)
    values (v_yo, 'leads.ultimo_origen_lead', to_jsonb(p_origen::text))
    on conflict (usuario_id, clave) do update set valor = excluded.valor, actualizado_en = now();
  end if;
  return jsonb_build_object('importacion', p_importacion, 'creadas', v_creadas, 'repetido', false);
end;
$$;


ALTER FUNCTION "public"."leads_importacion_terminar"("p_importacion" "uuid", "p_ya_existian" integer, "p_rechazadas" integer, "p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leads_importaciones_recientes"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_yo uuid := (select auth.uid());
begin
  perform public.assert_activo();
  return coalesce((
    select jsonb_agg(x.fila order by x.vence_en desc, x.id)
    from (
      select i.id, v.vence_en, jsonb_build_object(
        'id', i.id,
        'fecha', v.vence_en - interval '24 hours',
        'vence_en', v.vence_en,
        'estado', case when i.deshecha_en is not null then 'deshecha'
                       when i.estado = 'terminada' then 'terminada' else 'abierta' end,
        'creadas', coalesce(i.filas_ok, 0),
        'ya_existian', (a.detalle ->> 'ya_existian')::int,
        'rechazadas', (a.detalle ->> 'rechazadas')::int,
        'intactos', case when i.deshecha_en is null then (
          select count(*)::int from public.importaciones_leads il
           where il.importacion_id = i.id and public._lead_motivo_para_deshacer(il.lead_id, v_yo) is null) end,
        'deshecha_en', i.deshecha_en,
        'resultado', i.deshecha_resultado) as fila
      from public.importaciones i
      cross join lateral (select public._importacion_vence_en(i) as vence_en) v
      left join lateral (
        select y.detalle from public.actividad y
         where y.tabla = 'importaciones' and y.registro_id = i.id::text and y.accion = 'leads.importado'
         order by y.id desc limit 1) a on true
      where i.usuario_id = v_yo and i.entidad = 'leads' and i.archivo_ruta is null
        and (i.deshecha_en > now() - interval '24 hours' or (i.deshecha_en is null and v.vence_en > now()))
      order by v.vence_en desc, i.id
      limit 20
    ) x), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."leads_importaciones_recientes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leads_importar_lote"("p_importacion" "uuid", "p_total" integer, "p_filas" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_yo uuid := (select auth.uid());
  v_cc text := (select e.telefono_cc from public.ajustes_empresa e where e.id = 1);
  v_dueno uuid;
  v_estado public.estado_importacion;
  v_fila record;
  v_lead jsonb;
  v_res jsonb;
  v_salida jsonb := '[]'::jsonb;
  v_numero_de_fila integer;
  v_sqlstate text;
  v_mensaje text;
  v_hint text;
  v_permitidas constant text[] := array['nombre', 'telefono_principal', 'tipo_lead_id', 'origen_lead_id', 'atributos'];
  v_k text;
  v_ids uuid[] := '{}';
  v_filas integer[] := '{}';
  v_ve boolean := public.tiene_permiso('leads.numero_global.ver');
begin
  perform public.assert_permiso('leads.crear');
  perform public.assert_activo();
  if p_importacion is null then
    raise exception 'Falta el identificador de la importación.' using errcode = '22023';
  end if;
  if p_total is null or p_total < 1 or p_total > 500 then
    raise exception 'Una importación lleva de 1 a 500 filas.' using errcode = '22023';
  end if;
  if p_filas is null or jsonb_typeof(p_filas) <> 'array' or jsonb_array_length(p_filas) < 1 or jsonb_array_length(p_filas) > 50 then
    raise exception 'Un lote lleva de 1 a 50 filas.' using errcode = '22023';
  end if;

  -- La importación es de quien la empieza: retomarla con el mismo id es lo que hace un reintento.
  insert into public.importaciones (id, usuario_id, entidad, archivo_ruta, estado, filas_total, iniciada_en)
  values (p_importacion, v_yo, 'leads', null, 'procesando', p_total, now())
  on conflict (id) do nothing;
  select i.usuario_id, i.estado into v_dueno, v_estado from public.importaciones i where i.id = p_importacion for update;
  -- Una importación total (`archivo_ruta`, 9.06) no es de `/leads`: para aquí no existe.
  if v_dueno is distinct from v_yo
     or not exists (select 1 from public.importaciones i where i.id = p_importacion and i.entidad = 'leads' and i.archivo_ruta is null) then
    raise exception 'No encontramos esta importación.' using errcode = '42501';
  end if;
  if v_estado <> 'procesando' then
    raise exception 'Esta importación ya terminó.' using errcode = '22023';
  end if;

  -- Cada elemento, validado antes de tocar nada: una forma rota es un error del cliente, no de una fila.
  for v_fila in select e.value as v from jsonb_array_elements(p_filas) e loop
    if jsonb_typeof(v_fila.v) <> 'object' or jsonb_typeof(v_fila.v -> 'lead') is distinct from 'object'
       or jsonb_typeof(v_fila.v -> 'id') is distinct from 'string'
       or jsonb_typeof(v_fila.v -> 'fila') is distinct from 'number' then
      raise exception 'Una fila del lote no tiene la forma esperada.' using errcode = '22023';
    end if;
  end loop;

  -- En el orden del teléfono: dos lotes de dos personas que se cruzan toman los candados en el mismo
  -- orden y no se bloquean entre sí.
  for v_fila in
    select e.value as v, e.ordinality as ord
    from jsonb_array_elements(p_filas) with ordinality e
    order by public._telefono_o_nulo(v_cc, e.value -> 'lead' ->> 'telefono_principal') nulls first, e.ordinality
  loop
    v_numero_de_fila := (v_fila.v ->> 'fila')::integer;
    begin
      v_lead := v_fila.v -> 'lead';
      -- Sólo viajan las claves conocidas: `adoptar` y cualquier otra se rechazan, no se ignoran.
      for v_k in select jsonb_object_keys(v_lead) loop
        if not (v_k = any (v_permitidas)) then
          raise exception 'El dato «%» no se puede importar.', v_k using errcode = '22023', hint = v_k;
        end if;
      end loop;
      v_res := public._lead_crear((v_fila.v ->> 'id')::uuid, v_lead, null, null, false);
      if (v_res ->> 'resultado') = 'creado' then
        insert into public.importaciones_leads (importacion_id, lead_id, fila)
        values (p_importacion, (v_res ->> 'id')::uuid, v_numero_de_fila)
        on conflict do nothing;
        -- Los que ya existían (un reintento) conservan el número que tienen: sólo se reparten los de ahora.
        if not coalesce((v_res ->> 'repetido')::boolean, false) then
          v_ids := v_ids || (v_res ->> 'id')::uuid;
          v_filas := v_filas || v_numero_de_fila;
        end if;
        v_salida := v_salida || jsonb_build_array(jsonb_build_object(
          'id', v_fila.v ->> 'id', 'fila', v_numero_de_fila, 'resultado', 'creado',
          'repetido', coalesce((v_res ->> 'repetido')::boolean, false)));
      else
        -- existe, de_otro y limbo se dicen igual: en masa sólo se sabe que el número ya está.
        v_salida := v_salida || jsonb_build_array(jsonb_build_object(
          'id', v_fila.v ->> 'id', 'fila', v_numero_de_fila, 'resultado', 'ya_existe'));
      end if;
    exception when others then
      get stacked diagnostics v_sqlstate = returned_sqlstate, v_mensaje = message_text, v_hint = pg_exception_hint;
      -- Lo que levantan nuestras reglas es humano; lo inesperado no se cuenta.
      if v_sqlstate not in ('22023', '23502', '23514', 'PT409') then
        v_mensaje := 'No pudimos importar esta fila. Inténtalo de nuevo.';
        v_hint := null;
      end if;
      v_salida := v_salida || jsonb_build_array(jsonb_build_object(
        'id', v_fila.v ->> 'id', 'fila', v_numero_de_fila, 'resultado', 'error',
        'campo', nullif(v_hint, ''), 'motivo', v_mensaje));
    end;
  end loop;

  -- Los números propios de lo que entró ahora, repartidos por orden de fila (el menor, a la primera del archivo).
  if cardinality(v_ids) > 1 then
    perform set_config('importadora.numerar_lote', 'si', true);
    with a as (select t.id, row_number() over (order by t.fila) as rn from unnest(v_ids, v_filas) as t(id, fila)),
         n as (select l.numero_propio, row_number() over (order by l.numero_propio) as rn
                 from public.leads l where l.id = any (v_ids)),
         m as (select a.id, n.numero_propio from a join n using (rn))
    update public.leads l set numero_propio = m.numero_propio
      from m where l.id = m.id and l.numero_propio is distinct from m.numero_propio;
    perform set_config('importadora.numerar_lote', 'no', true);
  end if;

  -- Lo que vuelve por fila lleva los números que se ven, con el reparto por fila ya hecho.
  v_salida := coalesce((
    select jsonb_agg(case when t.e ->> 'resultado' = 'creado' then t.e || public._lead_numeros(l, v_ve) else t.e end order by t.ord)
      from jsonb_array_elements(v_salida) with ordinality as t (e, ord)
      left join public.leads l on l.id = case when t.e ->> 'resultado' = 'creado' then (t.e ->> 'id')::uuid end), '[]'::jsonb);

  update public.importaciones i set filas_ok = (select count(*) from public.importaciones_leads x where x.importacion_id = i.id)
   where i.id = p_importacion;
  return jsonb_build_object('importacion', p_importacion, 'filas', v_salida);
end;
$$;


ALTER FUNCTION "public"."leads_importar_lote"("p_importacion" "uuid", "p_total" integer, "p_filas" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leads_papelera_enviar"("p_lote" "uuid", "p_leads" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ids uuid[]; v_id uuid; v_n int; v_alcance public.alcance_permiso; v_lote public.lotes_papelera;
  v_yo uuid := (select auth.uid()); l public.leads; v_motivo text; v_portal int; v_version timestamptz;
begin
  perform public.assert_activo();
  if p_lote is null then
    raise exception 'Falta el identificador del envío.' using errcode = '22023';
  end if;
  if coalesce(array_length(p_leads, 1), 0) = 0 then
    raise exception 'Nada que enviar.' using errcode = '22023';
  end if;
  if array_length(p_leads, 1) > 200 then
    raise exception 'Máximo 200 por lote.' using errcode = '22023';
  end if;
  if array_position(p_leads, null) is not null then
    raise exception 'Uno de los leads llegó incompleto. Recarga e intenta de nuevo.' using errcode = '22023';
  end if;
  select array_agg(distinct x order by x) into v_ids from unnest(p_leads) x;

  -- Un reintento con el mismo lote no manda dos veces: devuelve lo que ya se mandó.
  select * into v_lote from public.lotes_papelera x where x.id = p_lote;
  if found then
    if v_lote.tipo <> 'leads' or v_lote.creado_por is distinct from v_yo then
      raise exception 'No pudimos enviar estos leads. Vuelve a intentarlo.' using errcode = '22023';
    end if;
    -- El mismo lote con otros leads no es un reintento: se rechaza en vez de decir «ya se envió».
    if exists (select 1 from unnest(v_ids) x where not exists (
         select 1 from public.leads l2 where l2.id = x and l2.lote_papelera_id = v_lote.id)) then
      raise exception 'Ese envío ya existe con otros leads. Vuelve a intentarlo.' using errcode = '22023';
    end if;
    return jsonb_build_object('lote', v_lote.id, 'actualizado_en', v_lote.actualizado_en, 'repetido', true,
      'portal_revocados', 0,
      'enviados', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'nombre', x.nombre) || public._lead_numeros(x, (select public.tiene_permiso('leads.numero_global.ver'))) order by x.numero)
                            from public.leads x where x.lote_papelera_id = v_lote.id and x.eliminado_en is not null), '[]'::jsonb));
  end if;

  v_alcance := public.alcance_de('leads.eliminar');
  if v_alcance is null then
    raise exception 'No tienes permiso para enviar leads a la papelera.' using errcode = '42501';
  end if;
  -- Primero se mira, sin bloquear: lo que no se ve da el mensaje de siempre y no dice cuál falló.
  foreach v_id in array v_ids loop
    if not public.puede_lead(v_id, 'leads.ver') then
      raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
    end if;
    if v_alcance <> 'todos' and public._lead_dueno(v_id) is distinct from v_yo then
      raise exception 'Sólo quien es dueño de un lead lo envía a la papelera.' using errcode = '42501';
    end if;
  end loop;
  -- Después se bloquea lo que se ve, en orden, y se vuelve a mirar: algo pudo irse mientras tanto.
  select count(*) into v_n from (
    select x.id from public.leads x where x.id = any (v_ids) and x.eliminado_en is null order by x.id for update) s;
  if v_n <> array_length(v_ids, 1) then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;
  for l in select * from public.leads x where x.id = any (v_ids) order by x.numero loop
    -- Con el lead bloqueado se vuelve a mirar quién es el dueño: pudo transferirse mientras esperaba.
    if v_alcance <> 'todos' and public._lead_dueno(l.id) is distinct from v_yo then
      raise exception 'Sólo quien es dueño de un lead lo envía a la papelera.' using errcode = '42501';
    end if;
    v_motivo := public._lead_motivo_de_bloqueo(l, true);
    if v_motivo is not null then
      raise exception 'No se envió nada. «%»: %', l.nombre, v_motivo using errcode = '23514';
    end if;
  end loop;

  begin
    insert into public.lotes_papelera (id, tipo, creado_por, resumen)
    values (p_lote, 'leads', v_yo, jsonb_build_object('cantidad', v_n, 'restaurados', 0, 'purgados', 0));
  exception when unique_violation then
    raise exception 'Ese envío ya se estaba procesando. Vuelve a intentarlo.' using errcode = 'PT409';
  end;
  update public.leads x set eliminado_en = now(), eliminado_por = v_yo, lote_papelera_id = p_lote
  where x.id = any (v_ids) and x.eliminado_en is null;
  update public.accesos_portal a set habilitado = false, revocado_por = v_yo, revocado_en = now()
  where a.lead_id = any (v_ids) and a.habilitado;
  get diagnostics v_portal = row_count;
  v_version := public._lote_papelera_tocar(p_lote);
  perform public.registrar_actividad('papelera.enviado', 'lotes_papelera', p_lote::text, null, null,
    jsonb_build_object('tipo', 'leads', 'cantidad', v_n, 'portal_revocados', v_portal));
  return jsonb_build_object('lote', p_lote, 'actualizado_en', v_version, 'repetido', false, 'portal_revocados', v_portal,
    'enviados', (select jsonb_agg(jsonb_build_object('id', x.id, 'nombre', x.nombre) || public._lead_numeros(x, (select public.tiene_permiso('leads.numero_global.ver'))) order by x.numero)
                 from public.leads x where x.lote_papelera_id = p_lote));
end;
$$;


ALTER FUNCTION "public"."leads_papelera_enviar"("p_lote" "uuid", "p_leads" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leads_papelera_listar"("p_antes_en" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_antes_id" "uuid" DEFAULT NULL::"uuid", "p_hacia_atras" boolean DEFAULT false, "p_tope" integer DEFAULT 6, "p_primeros" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_dias int; v_todo boolean; v_yo uuid := (select auth.uid()); v_n int := public._acotar_pagina(p_tope, 6, 51);
        v_primeros int := public._acotar_pagina(p_primeros, 20, 200); v_ids uuid[];
begin
  perform public.assert_activo();
  select e.papelera_dias into v_dias from public.ajustes_empresa e where e.id = 1;
  v_todo := public.tiene_permiso('leads.papelera.purgar');
  if p_antes_en is null then
    v_ids := array(select l.id from public.lotes_papelera l
      where l.tipo = 'leads' and l.purgado_en is null and l.restaurado_en is null
        and (v_todo or l.creado_por = v_yo)
        and exists (select 1 from public.leads x where x.lote_papelera_id = l.id and x.eliminado_en is not null)
      order by l.creado_en desc, l.id desc limit v_n);
  elsif not coalesce(p_hacia_atras, false) then
    v_ids := array(select l.id from public.lotes_papelera l
      where l.tipo = 'leads' and l.purgado_en is null and l.restaurado_en is null
        and (v_todo or l.creado_por = v_yo)
        and (l.creado_en, l.id) < (p_antes_en, p_antes_id)
        and exists (select 1 from public.leads x where x.lote_papelera_id = l.id and x.eliminado_en is not null)
      order by l.creado_en desc, l.id desc limit v_n);
  else
    v_ids := array(select l.id from public.lotes_papelera l
      where l.tipo = 'leads' and l.purgado_en is null and l.restaurado_en is null
        and (v_todo or l.creado_por = v_yo)
        and (l.creado_en, l.id) > (p_antes_en, p_antes_id)
        and exists (select 1 from public.leads x where x.lote_papelera_id = l.id and x.eliminado_en is not null)
      order by l.creado_en, l.id limit v_n);
  end if;
  return coalesce((
    select jsonb_agg(public._leads_papelera_lote_json(l, v_dias, v_yo, v_primeros) order by o.ord)
    from unnest(v_ids) with ordinality o (id, ord) join public.lotes_papelera l on l.id = o.id), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."leads_papelera_listar"("p_antes_en" timestamp with time zone, "p_antes_id" "uuid", "p_hacia_atras" boolean, "p_tope" integer, "p_primeros" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leads_papelera_lote"("p_lote" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_dias int; v_todo boolean; v_yo uuid := (select auth.uid()); l public.lotes_papelera;
begin
  perform public.assert_activo();
  select e.papelera_dias into v_dias from public.ajustes_empresa e where e.id = 1;
  v_todo := public.tiene_permiso('leads.papelera.purgar');
  select * into l from public.lotes_papelera x
   where x.id = p_lote and x.tipo = 'leads' and x.purgado_en is null and x.restaurado_en is null
     and (v_todo or x.creado_por = v_yo)
     and exists (select 1 from public.leads y where y.lote_papelera_id = x.id and y.eliminado_en is not null);
  if not found then
    return null;
  end if;
  return public._leads_papelera_lote_json(l, v_dias, v_yo, null);
end;
$$;


ALTER FUNCTION "public"."leads_papelera_lote"("p_lote" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leads_papelera_purgar"("p_lote" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_leads" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare l public.lotes_papelera;
begin
  perform public.assert_activo();
  if not public.tiene_permiso('leads.papelera.purgar') then
    raise exception 'No tienes permiso para purgar la papelera de leads.' using errcode = '42501';
  end if;
  select * into l from public.lotes_papelera x where x.id = p_lote and x.tipo = 'leads' for update;
  if not found then
    raise exception 'Ese lote ya no está en la papelera.' using errcode = 'PT409';
  end if;
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  if l.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._conflicto_de_edicion('lotes_papelera', l.id, l.actualizado_en, 'este lote de la papelera');
  end if;
  return public._papelera_purgar_leads(l.id, p_leads);
end;
$$;


ALTER FUNCTION "public"."leads_papelera_purgar"("p_lote" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_leads" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leads_papelera_restaurar"("p_lote" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_leads" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  l public.lotes_papelera; x public.leads; v_motivo text; v_quedan int; v_version timestamptz;
  v_restaurados jsonb := '[]'::jsonb; v_pendientes jsonb := '[]'::jsonb;
  v_ve boolean := public.tiene_permiso('leads.numero_global.ver');
begin
  perform public.assert_activo();
  select * into l from public.lotes_papelera y where y.id = p_lote and y.tipo = 'leads' for update;
  if not found then
    raise exception 'Ese lote ya no está en la papelera.' using errcode = 'PT409';
  end if;
  if l.creado_por is distinct from (select auth.uid()) and not public.tiene_permiso('leads.papelera.purgar') then
    raise exception 'Sólo lo restaura quien lo envió o quien puede vaciar la papelera.' using errcode = '42501';
  end if;
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  if l.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._conflicto_de_edicion('lotes_papelera', l.id, l.actualizado_en, 'este lote de la papelera');
  end if;

  for x in
    select * from public.leads y
    where y.lote_papelera_id = l.id and y.eliminado_en is not null and (p_leads is null or y.id = any (p_leads))
    order by y.id for update
  loop
    v_motivo := public._lead_motivo_de_restaurar(x);
    if v_motivo is null then
      begin
        update public.leads y set eliminado_en = null, eliminado_por = null, lote_papelera_id = null where y.id = x.id;
        v_restaurados := v_restaurados || (jsonb_build_object('id', x.id, 'nombre', x.nombre) || public._lead_numeros(x, v_ve));
      exception when unique_violation then
        -- Otra persona tomó ese teléfono justo ahora.
        v_motivo := coalesce(public._lead_motivo_de_restaurar(x), 'Ese teléfono ya lo tiene otro lead.');
      end;
    end if;
    if v_motivo is not null then
      v_pendientes := v_pendientes || (jsonb_build_object('id', x.id, 'nombre', x.nombre, 'motivo', v_motivo) || public._lead_numeros(x, v_ve));
    end if;
  end loop;

  select count(*) into v_quedan from public.leads y where y.lote_papelera_id = l.id and y.eliminado_en is not null;
  if jsonb_array_length(v_restaurados) = 0 then
    return jsonb_build_object('actualizado_en', l.actualizado_en, 'restaurados', v_restaurados, 'pendientes', v_pendientes, 'quedan', v_quedan);
  end if;
  update public.lotes_papelera y
  set resumen = y.resumen || jsonb_build_object('restaurados', coalesce((y.resumen ->> 'restaurados')::int, 0) + jsonb_array_length(v_restaurados)),
      restaurado_en = case when v_quedan = 0 then now() else y.restaurado_en end,
      restaurado_por = case when v_quedan = 0 then (select auth.uid()) else y.restaurado_por end
  where y.id = l.id;
  v_version := public._lote_papelera_tocar(l.id);
  perform public.registrar_actividad('papelera.restaurado', 'lotes_papelera', l.id::text, null, null,
    jsonb_build_object('tipo', 'leads', 'cantidad', jsonb_array_length(v_restaurados)));
  return jsonb_build_object('actualizado_en', v_version, 'restaurados', v_restaurados, 'pendientes', v_pendientes, 'quedan', v_quedan);
end;
$$;


ALTER FUNCTION "public"."leads_papelera_restaurar"("p_lote" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_leads" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leads_reciente_seguir"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.leads_asesores set lead_reciente_en = coalesce(new.ultimo_seguimiento_en, new.creado_en)
   where lead_id = new.id and lead_reciente_en is distinct from coalesce(new.ultimo_seguimiento_en, new.creado_en);
  return null;
end;
$$;


ALTER FUNCTION "public"."leads_reciente_seguir"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."telefono_lead"("p_lead" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_alcance public.alcance_permiso;
  v_tel text;
  v_cartera boolean;
  v_vivo boolean;
begin
  v_alcance := public.alcance_de('leads.ver');
  if v_alcance is null then
    return null;
  end if;
  select l.telefono_principal,
         exists (select 1 from public.leads_asesores la
                  where la.lead_id = l.id and la.usuario_id = (select auth.uid()) and la.revocado_en is null),
         exists (select 1 from public.leads_asesores la where la.lead_id = l.id and la.revocado_en is null)
    into v_tel, v_cartera, v_vivo
  from public.leads l
  where l.id = p_lead and l.eliminado_en is null;
  if not found or not v_vivo then
    return null;
  end if;
  if v_alcance <> 'todos' and not v_cartera then
    return null;
  end if;
  return case when v_cartera then v_tel else public.enmascarar_telefono(v_tel) end;
end;
$$;


ALTER FUNCTION "public"."telefono_lead"("p_lead" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."leads_asesores" (
    "lead_id" "uuid" NOT NULL,
    "usuario_id" "uuid" NOT NULL,
    "tipo_acceso" "public"."tipo_acceso_lead" NOT NULL,
    "compartido_por" "uuid",
    "desde" timestamp with time zone DEFAULT "now"() NOT NULL,
    "revocado_en" timestamp with time zone,
    "revocado_por" "uuid",
    "lead_creado_en" timestamp with time zone NOT NULL,
    "lead_reciente_en" timestamp with time zone NOT NULL
);


ALTER TABLE "public"."leads_asesores" OWNER TO "postgres";


COMMENT ON TABLE "public"."leads_asesores" IS 'Cartera: quién tiene acceso a qué lead y cómo (dueño, compartido, adoptado del limbo). Un lead tiene a lo sumo un dueño vigente. lead_creado_en y lead_reciente_en son copias de leads.creado_en y de coalesce(leads.ultimo_seguimiento_en, leads.creado_en) para ordenar la cartera de una persona sin recorrer leads (las mantienen triggers; nadie las escribe).';



COMMENT ON COLUMN "public"."leads_asesores"."lead_reciente_en" IS 'Copia de coalesce(leads.ultimo_seguimiento_en, leads.creado_en): lo más reciente del lead, para ordenar la cartera de una persona (leads_asesores_reciente_idx). Está en todas las filas del lead, también las revocadas. La mantienen triggers; nadie la escribe.';



CREATE TABLE IF NOT EXISTS "public"."leads_etiquetas" (
    "lead_id" "uuid" NOT NULL,
    "etiqueta_id" "uuid" NOT NULL
);


ALTER TABLE "public"."leads_etiquetas" OWNER TO "postgres";


COMMENT ON TABLE "public"."leads_etiquetas" IS 'Qué etiquetas puso cada persona en un lead (hasta 20 suyas por lead). Sólo se leen las de etiquetas propias; las escribe lead_etiquetas_poner(), que exige ver el lead. Compartir el lead no las comparte.';



