CREATE OR REPLACE VIEW "public"."leads_vista" WITH ("security_invoker"='true') AS
 SELECT "l"."id",
    ( SELECT "g"."numero"
           FROM "public"."leads_numeros_globales" "g"
          WHERE ("g"."lead_id" = "l"."id")) AS "numero",
    "l"."nombre",
    "l"."telefono_cc",
    "public"."telefono_lead"("l"."id") AS "telefono_principal",
    COALESCE((( SELECT "auth"."uid"() AS "uid") = ANY ("l"."cartera")), false) AS "telefono_visible",
    "l"."tipo_lead_id",
    "l"."origen_lead_id",
    "public"."atributos_lead"("l"."id") AS "atributos",
    "l"."creado_por",
    "l"."ultimo_seguimiento_en",
    "l"."creado_en",
    "l"."actualizado_en",
    ("fav"."lead_id" IS NOT NULL) AS "es_favorito",
    ("tach"."lead_id" IS NOT NULL) AS "esta_tachado",
    ( SELECT "la"."usuario_id"
           FROM "public"."leads_asesores" "la"
          WHERE (("la"."lead_id" = "l"."id") AND ("la"."tipo_acceso" = 'dueno'::"public"."tipo_acceso_lead") AND ("la"."revocado_en" IS NULL) AND ("la"."usuario_id" <> ALL (( SELECT "public"."_bajas_en_curso"() AS "_bajas_en_curso")::"uuid"[])))) AS "dueno_id",
    COALESCE((( SELECT "auth"."uid"() AS "uid") = ANY ("l"."cartera")), false) AS "en_cartera",
    ARRAY( SELECT "le"."etiqueta_id"
           FROM ("public"."leads_etiquetas" "le"
             JOIN "public"."etiquetas" "e" ON (("e"."id" = "le"."etiqueta_id")))
          WHERE (("le"."lead_id" = "l"."id") AND ("e"."usuario_id" = ( SELECT "auth"."uid"() AS "uid")))
          ORDER BY "le"."etiqueta_id") AS "etiquetas",
    ( SELECT "np"."numero"
           FROM "public"."leads_numeros_propios" "np"
          WHERE ("np"."lead_id" = "l"."id")) AS "numero_propio",
    ( SELECT "np"."creado_por"
           FROM "public"."leads_numeros_propios" "np"
          WHERE ("np"."lead_id" = "l"."id")) AS "numero_propio_de",
    ( SELECT COALESCE(( SELECT NULLIF("btrim"("p"."nombre"), ''::"text") AS "nullif"
                   FROM "public"."perfiles" "p"
                  WHERE ("p"."id" = "np"."creado_por")), 'Otra persona'::"text") AS "coalesce"
           FROM "public"."leads_numeros_propios" "np"
          WHERE (("np"."lead_id" = "l"."id") AND ("np"."creado_por" <> ( SELECT "auth"."uid"() AS "uid")))) AS "numero_propio_creador",
    COALESCE(( SELECT "g"."numero"
           FROM "public"."leads_numeros_globales" "g"
          WHERE ("g"."lead_id" = "l"."id")), ( SELECT ("np"."numero")::bigint AS "numero"
           FROM "public"."leads_numeros_propios" "np"
          WHERE ("np"."lead_id" = "l"."id"))) AS "numero_visible",
    "l"."atributos_publicos",
    COALESCE("l"."ultimo_seguimiento_en", "l"."creado_en") AS "reciente_en"
   FROM (("public"."leads" "l"
     LEFT JOIN "public"."leads_favoritos" "fav" ON ((("fav"."lead_id" = "l"."id") AND ("fav"."usuario_id" = ( SELECT "auth"."uid"() AS "uid")))))
     LEFT JOIN "public"."leads_tachados" "tach" ON ((("tach"."lead_id" = "l"."id") AND ("tach"."usuario_id" = ( SELECT "auth"."uid"() AS "uid")))));


ALTER VIEW "public"."leads_vista" OWNER TO "postgres";


COMMENT ON VIEW "public"."leads_vista" IS 'Lo que la app lee de los leads: teléfono enmascarado y atributos recortados según la cartera (atributos), y la copia de lo público (atributos_publicos, para filtrar un campo público). en_cartera = el lead está en la cartera de quien mira («míos»), de leads.cartera. reciente_en = el último seguimiento vivo del lead o, sin ninguno, su alta (el orden de «míos» del panel del cliente). Las marcas son de quien mira. security_invoker: la RLS de leads decide qué filas hay.';



CREATE OR REPLACE FUNCTION "public"."leads_vista_por_ids"("p_leads" "uuid"[]) RETURNS SETOF "public"."leads_vista"
    LANGUAGE "sql" STABLE
    AS $$ select * from public.leads_vista v where v.id = any (p_leads) $$;


ALTER FUNCTION "public"."leads_vista_por_ids"("p_leads" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."leads_vista_por_ids"("p_leads" "uuid"[]) IS 'leads_vista de los leads con esos ids (el segundo paso de la búsqueda por candidatos, 5a-fix-1b). Invocador: la RLS de leads decide qué filas hay. Se inlinea en la consulta de PostgREST: no le pongas strict, search_path, security definer ni volatile.';



CREATE OR REPLACE FUNCTION "public"."limpieza_automatica_correr"("p_ahora" timestamp with time zone DEFAULT "now"(), "p_origenes" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  a public.ajustes_empresa; v public.vehiculos; r record;
  v_hoy date; v_corrida uuid; v_lote uuid; v_ancla text;
  v_parcial boolean := p_origenes is not null;
  v_tope constant int := 200;
  -- Cuántas filas más se revisan después de llenar el lote, para contar lo que espera a la noche siguiente.
  v_revision constant int := 1000;
  v_tras_tope int := 0;
  v_movidos int := 0; v_pendientes int := 0; v_saltados jsonb := '{}'::jsonb;
begin
  select * into a from public.ajustes_empresa e where e.id = 1;
  if not a.limpieza_automatica then
    return jsonb_build_object('estado', 'apagada');
  end if;
  v_hoy := (p_ahora at time zone a.zona_horaria)::date;

  if v_parcial then
    insert into public.limpieza_corridas (fecha, parcial) values (v_hoy, true) returning id into v_corrida;
  else
    if (p_ahora at time zone a.zona_horaria)::time < make_time(public._limpieza_hora(), 0, 0) then
      return jsonb_build_object('estado', 'temprano');
    end if;
    -- La corrida del día se reserva antes de mover nada: dos a la vez no duplican lotes.
    insert into public.limpieza_corridas (fecha, parcial) values (v_hoy, false)
    on conflict (fecha) where not parcial do nothing returning id into v_corrida;
    if v_corrida is null then
      return jsonb_build_object('estado', 'ya_corrio', 'fecha', v_hoy);
    end if;
  end if;

  for r in
    select x.id from public.vehiculos x join public.origenes o on o.id = x.origen_id
    where x.eliminado_en is null and x.importado_apibara and o.tipo = 'subasta'
      and (p_origenes is null or x.origen_id = any (p_origenes))
      and (x.subasta_en is not null or x.subasta_fin_en is not null or x.estado_subasta in ('terminada', 'vendida'))
    order by coalesce(x.subasta_fin_en, x.subasta_en, x.apibara_sync_en), x.id
  loop
    -- Con el lote lleno no hace falta revisar los 100.000 que siguen: se cuentan los próximos
    -- `v_revision` (vencen de a poco: van ordenados por su fecha) y el resto queda para mañana.
    if v_movidos >= v_tope then
      v_tras_tope := v_tras_tope + 1;
      exit when v_tras_tope > v_revision;
    end if;
    begin
      select * into v from public.vehiculos x where x.id = r.id and x.eliminado_en is null for update skip locked;
      if not found then
        v_saltados := v_saltados || jsonb_build_object('ocupado', coalesce((v_saltados ->> 'ocupado')::int, 0) + 1);
        continue;
      end if;
      -- Se decide de nuevo, con la fila ya bloqueada. Todavía no le toca: no es de esta corrida.
      if public._limpieza_vence(v, p_ahora) is null or public._limpieza_vence(v, p_ahora) > v_hoy then
        continue;
      end if;
      v_ancla := public._limpieza_ancla(v);
      if v_ancla is not null then
        v_saltados := v_saltados || jsonb_build_object(v_ancla, coalesce((v_saltados ->> v_ancla)::int, 0) + 1);
        continue;
      end if;
      if v_movidos >= v_tope then
        v_pendientes := v_pendientes + 1;
        continue;
      end if;
      if v_lote is null then
        insert into public.lotes_papelera (tipo, creado_por, es_limpieza, resumen)
        values ('vehiculos', null, true, jsonb_build_object('cantidad', 0, 'restaurados', 0, 'purgados', 0))
        returning id into v_lote;
      end if;
      perform public._vehiculo_a_lote(v, v_lote);
      v_movidos := v_movidos + 1;
    exception when others then
      raise warning 'limpieza: no se pudo mover el vehículo %: %', r.id, sqlerrm;
      v_saltados := v_saltados || jsonb_build_object('error', coalesce((v_saltados ->> 'error')::int, 0) + 1);
    end;
  end loop;

  if v_lote is not null then
    update public.lotes_papelera l set resumen = jsonb_build_object('cantidad', v_movidos, 'restaurados', 0, 'purgados', 0)
    where l.id = v_lote;
    perform public._lote_papelera_tocar(v_lote);
  end if;
  update public.limpieza_corridas c
  set lote_id = v_lote, movidos = v_movidos, saltados = v_saltados, pendientes = v_pendientes, termino_en = clock_timestamp()
  where c.id = v_corrida;
  perform public.registrar_actividad('limpieza.corrida', 'limpieza_corridas', v_corrida::text, null, null,
    jsonb_build_object('fecha', v_hoy, 'movidos', v_movidos, 'saltados', v_saltados, 'pendientes', v_pendientes,
      'lote', v_lote, 'parcial', v_parcial));
  return jsonb_build_object('estado', 'corrida', 'corrida', v_corrida, 'fecha', v_hoy, 'lote', v_lote,
    'movidos', v_movidos, 'saltados', v_saltados, 'pendientes', v_pendientes);
end;
$$;


ALTER FUNCTION "public"."limpieza_automatica_correr"("p_ahora" timestamp with time zone, "p_origenes" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."limpieza_avisar"("p_ahora" timestamp with time zone DEFAULT "now"(), "p_origenes" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  a public.ajustes_empresa; v public.vehiculos; r record;
  v_hoy date; v_proxima date; v_hasta date; v_fecha date; v_marcado uuid;
  v_tope constant int := 200;
  v_avisados int := 0; v_pendientes boolean := false;
begin
  select * into a from public.ajustes_empresa e where e.id = 1;
  if not a.limpieza_automatica then
    return jsonb_build_object('estado', 'apagada');
  end if;
  v_hoy := (p_ahora at time zone a.zona_horaria)::date;
  v_proxima := public._limpieza_proxima(p_ahora);
  v_hasta := v_hoy + public._limpieza_ventana_de_aviso();

  -- Por `vehiculos_limpieza_orden_idx`. La cota: para caer en la ventana, término + gracia tiene que llegar antes de las 03:00 de hoy + 3
  -- (en la zona), que siempre es antes de ahora + ventana + 2 días − gracia.
  for r in
    select x.id from public.vehiculos x join public.origenes o on o.id = x.origen_id
    where x.eliminado_en is null and x.importado_apibara and o.tipo = 'subasta'
      and (p_origenes is null or x.origen_id = any (p_origenes))
      and (x.subasta_en is not null or x.subasta_fin_en is not null or x.estado_subasta in ('terminada', 'vendida'))
      and coalesce(x.subasta_fin_en, x.subasta_en, x.apibara_sync_en)
          < p_ahora + make_interval(days => public._limpieza_ventana_de_aviso() + 2 - a.limpieza_dias_gracia)
      and not exists (select 1 from public.limpieza_avisos m where m.vehiculo_id = x.id)
    order by coalesce(x.subasta_fin_en, x.subasta_en, x.apibara_sync_en), x.id
  loop
    if v_avisados >= v_tope then
      v_pendientes := true;
      exit;
    end if;
    select * into v from public.vehiculos x where x.id = r.id and x.eliminado_en is null;
    continue when not found;
    v_fecha := public._limpieza_fecha(v, p_ahora, v_proxima);
    continue when v_fecha is null or v_fecha > v_hasta;
    -- La marca primero: una corrida a la vez que tomó el mismo vehículo espera y salta.
    insert into public.limpieza_avisos (vehiculo_id, fecha) values (v.id, v_fecha)
    on conflict (vehiculo_id) do nothing returning vehiculo_id into v_marcado;
    continue when v_marcado is null;
    v_marcado := null;
    -- La marca queda aunque no haya creador o la puerta lo descarte (de baja): así no se relee cada día.
    if v.creado_por is not null then
      perform public.notificar(v.creado_por, 'limpieza_pronto', 'Se limpiará pronto: ' || left(v.titulo, 80),
        'Va a la papelera en la limpieza automática de los próximos días. Si lo quieres, ábrelo y toca «Conservar».',
        'vehiculo', v.id, '/vehiculos/' || v.id, true);
    end if;
    v_avisados := v_avisados + 1;
  end loop;
  return jsonb_build_object('estado', 'corrida', 'avisados', v_avisados, 'pendientes', v_pendientes);
end;
$$;


ALTER FUNCTION "public"."limpieza_avisar"("p_ahora" timestamp with time zone, "p_origenes" "uuid"[]) OWNER TO "postgres";


