CREATE OR REPLACE FUNCTION "public"."limpieza_ultima"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.limpieza_corridas;
begin
  perform public.assert_activo();
  if not public.tiene_permiso('vehiculos.papelera.purgar') then
    return null;
  end if;
  select * into r from public.limpieza_corridas c where not c.parcial order by c.fecha desc limit 1;
  if not found then
    return null;
  end if;
  return jsonb_build_object('fecha', r.fecha, 'movidos', r.movidos, 'saltados', r.saltados,
    'pendientes', r.pendientes, 'termino_en', r.termino_en);
end;
$$;


ALTER FUNCTION "public"."limpieza_ultima"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."logistica_bandeja"("p_tope" integer DEFAULT 5) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  n int := public._acotar_pagina(p_tope, 5, 20);
  v_vacia constant jsonb := '{"filas": [], "hay_mas": false}';
  v_dem jsonb;
begin
  if (select auth.uid()) is null then
    return jsonb_build_object('demoradas', v_vacia, 'trabados', v_vacia, 'por_aprobar', v_vacia);
  end if;
  -- Las primeras 50 demoradas (las de trabados); las primeras n son la lista de demoradas.
  select coalesce(jsonb_agg(to_jsonb(d) - 'vence' order by d.vence, d.id), '[]'::jsonb) into v_dem
    from (select * from public._bandeja_demoradas(50) x order by x.vence, x.id limit 50) d;
  return jsonb_build_object(
    'demoradas', jsonb_build_object(
      'filas', coalesce((select jsonb_agg(e order by i) from jsonb_array_elements(v_dem) with ordinality z(e, i) where i <= n), '[]'::jsonb),
      'hay_mas', jsonb_array_length(v_dem) > n),
    'trabados', public._bandeja_trabados(v_dem, n),
    'por_aprobar', public._bandeja_por_aprobar(n));
end;
$$;


ALTER FUNCTION "public"."logistica_bandeja"("p_tope" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."logistica_bandeja"("p_tope" integer) IS 'Bandeja de logística en Inicio (6.12): { demoradas, trabados, por_aprobar }, cada una { filas, hay_mas } con hasta p_tope (5, máximo 20); sin conteo. Sólo lo de los orígenes que quien mira ve (el menor de logistica.ver y vehiculos.ver; por aprobar, además logistica.documentos.aprobar).';



CREATE OR REPLACE FUNCTION "public"."logistica_cadena"("p_origen" "uuid", "p_tope" integer DEFAULT 50, "p_filtros" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_n integer := public._acotar_pagina(p_tope, 50, 100);
  v_f jsonb;
  v_alcance public.alcance_permiso;
  v_todos boolean;
  v_col jsonb;
  v_columnas jsonb := '[]'::jsonb;
  r record;
begin
  if p_origen is null then
    raise exception 'Falta el origen.' using errcode = '22023', hint = 'p_origen';
  end if;
  v_f := public._logistica_filtros(p_filtros);
  v_alcance := public._logistica_alcance(p_origen);
  if v_alcance is null then
    raise exception 'No tienes acceso a la logística de este origen.' using errcode = '42501', hint = 'acceso';
  end if;
  v_todos := v_alcance = 'todos';

  v_col := public._logistica_columna(p_origen, null, null, null, v_n, v_f, v_todos, null);
  if jsonb_array_length(v_col -> 'tarjetas') > 0 then
    v_columnas := v_columnas || jsonb_build_array(jsonb_build_object(
      'fase_id', null, 'nombre', null, 'color', null, 'orden', null, 'activa', null, 'es_final', false, 'demora_dias', null) || v_col);
  end if;

  for r in
    select f.id, f.nombre, f.color, f.orden, f.activa, f.es_final, public._logistica_dias(f.id) as dias
      from public.fases f
      join public.flujos fl on fl.id = f.flujo_id
     where fl.ambito = 'vehiculos' and fl.origen_id = p_origen and f.es_logistica
     order by not f.activa, f.orden, f.id
  loop
    v_col := public._logistica_columna(p_origen, r.id, null, null, v_n, v_f, v_todos, r.dias);
    if r.activa or jsonb_array_length(v_col -> 'tarjetas') > 0 then
      v_columnas := v_columnas || jsonb_build_array(jsonb_build_object(
        'fase_id', r.id, 'nombre', r.nombre, 'color', r.color, 'orden', r.orden, 'activa', r.activa, 'es_final', r.es_final,
        'demora_dias', r.dias) || v_col);
    end if;
  end loop;

  return jsonb_build_object('columnas', v_columnas);
end;
$$;


ALTER FUNCTION "public"."logistica_cadena"("p_origen" "uuid", "p_tope" integer, "p_filtros" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."logistica_cadena"("p_origen" "uuid", "p_tope" integer, "p_filtros" "jsonb") IS 'La cadena de logística de un origen (6.02-2): {columnas: [{fase_id, nombre, color, orden, activa, es_final, demora_dias, tarjetas, hay_mas}]}. «Sin fase» (fase_id nulo; el texto lo pone la interfaz) primero y sólo con tarjetas; activas con es_logistica por orden; jubiladas al final y sólo con tarjetas. demora_dias = los días con que alerta (nulo si no alerta). Cada columna trae p_tope tarjetas (_acotar_pagina 50/100) y hay_mas; «Ver más» es logistica_cadena_columna. Definer, mismo acceso y filtros que la columna.';



CREATE OR REPLACE FUNCTION "public"."logistica_cadena_columna"("p_origen" "uuid", "p_fase" "uuid", "p_desde" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_id" "uuid" DEFAULT NULL::"uuid", "p_tope" integer DEFAULT 50, "p_filtros" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_n integer := public._acotar_pagina(p_tope, 50, 100);
  v_f jsonb;
  v_alcance public.alcance_permiso;
  v_dias integer;
begin
  if p_origen is null then
    raise exception 'Falta el origen.' using errcode = '22023', hint = 'p_origen';
  end if;
  v_f := public._logistica_filtros(p_filtros);
  v_alcance := public._logistica_alcance(p_origen);
  if v_alcance is null then
    raise exception 'No tienes acceso a la logística de este origen.' using errcode = '42501', hint = 'acceso';
  end if;
  if p_fase is not null and p_id is not null and p_desde is null then
    raise exception 'El cursor de la columna no es válido.' using errcode = '22023', hint = 'cursor';
  end if;
  if p_fase is not null then
    perform 1 from public.fases f join public.flujos fl on fl.id = f.flujo_id
     where f.id = p_fase and f.es_logistica and fl.ambito = 'vehiculos' and fl.origen_id = p_origen;
    if not found then
      raise exception 'Esa fase no es de la cadena de este origen.' using errcode = '22023', hint = 'p_fase';
    end if;
    v_dias := public._logistica_dias(p_fase);
  end if;
  return public._logistica_columna(p_origen, p_fase, p_desde, p_id, v_n, v_f, v_alcance = 'todos', v_dias);
end;
$$;


ALTER FUNCTION "public"."logistica_cadena_columna"("p_origen" "uuid", "p_fase" "uuid", "p_desde" timestamp with time zone, "p_id" "uuid", "p_tope" integer, "p_filtros" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."logistica_cadena_columna"("p_origen" "uuid", "p_fase" "uuid", "p_desde" timestamp with time zone, "p_id" "uuid", "p_tope" integer, "p_filtros" "jsonb") IS 'Una columna de la cadena de logística (6.02-2): {tarjetas: [{id, titulo, vin, lote, fase_desde, demorada, contenedor, booking, eta_el}], hay_mas}, por cursor (fase_desde, id) sobre vehiculos_cadena_idx; p_fase nulo = «Sin fase» (por id). Definer: el alcance es el menor de logistica.ver y vehiculos.ver del origen, resuelto una vez (42501 hint acceso si no lo hay). Filtros: q, demoradas, por_aprobar, contenedor, booking, naviera (22023 hint filtros); fase ajena o sin es_logistica, 22023 hint p_fase; cursor sin p_desde, 22023 hint cursor.';



CREATE OR REPLACE FUNCTION "public"."logistica_donde_esta"("p_buscar" "text", "p_tope" integer DEFAULT 10) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_n integer := public._acotar_pagina(p_tope, 10, 10);
  v_yo uuid := (select auth.uid());
  v_exacto text := upper(btrim(p_buscar));
  v_patron text;
  v_t uuid[];
  v_p uuid[];
  v_ids uuid[];
  v_unidades jsonb;
begin
  if char_length(p_buscar) > 100 then
    raise exception 'El texto a buscar es demasiado largo.' using errcode = '22023', hint = 'p_buscar';
  end if;
  -- El mismo escape y el mismo mínimo (3 letras o dígitos seguidos) que `q` de la cadena; si no alcanza, no se busca.
  v_patron := public._logistica_filtros(jsonb_build_object('q', p_buscar)) ->> 'patron';
  if v_patron is null then
    return jsonb_build_object('unidades', '[]'::jsonb, 'hay_mas', false);
  end if;
  -- Los orígenes: los de `logistica.ver` con la regla `logistica` activa en su flujo de vehículos (`flujos_origen_unico`), por su alcance.
  select coalesce(array_agg(o.id) filter (where a.alcance = 'todos'), '{}'), coalesce(array_agg(o.id) filter (where a.alcance = 'propios'), '{}')
    into v_t, v_p
    from unnest(public.origenes_con_alcance('logistica.ver', 'propios')) as o(id)
    join public.flujos fl on fl.origen_id = o.id and fl.ambito = 'vehiculos'
    cross join lateral (select public._logistica_alcance(o.id) as alcance) a
   where public.flujo_regla_activa(fl.id, 'logistica');
  if cardinality(v_t) = 0 and cardinality(v_p) = 0 then
    return jsonb_build_object('unidades', '[]'::jsonb, 'hay_mas', false);
  end if;
  -- Candidatas por `vehiculos_titulo_trgm`, `vehiculos_vin_trgm` y `vehiculos_lote_trgm` (bitmap or): a lo sumo 1.000 de los orígenes que veo.
  v_ids := array(
    select v.id from public.vehiculos v
     where (v.titulo ilike v_patron or v.vin ilike v_patron or v.lote ilike v_patron)
       and v.eliminado_en is null and v.origen_id = any (v_t || v_p)
     limit 1000);
  -- Las propias, por `vehiculos_creador_idx (creado_por, origen_id, creado_en desc, id desc)`, sólo donde tengo «propios»: encuentra las mías aunque el
  -- título lo compartan más de 1.000 ajenas. Una de un lead de mi cartera creada por otra persona no se rescata (el límite de `buscador_cotizaciones`).
  if cardinality(v_p) > 0 then
    v_ids := v_ids || array(
      select v.id from public.vehiculos v
       where v.creado_por = v_yo and v.origen_id = any (v_p) and v.eliminado_en is null
         and (v.titulo ilike v_patron or v.vin ilike v_patron or v.lote ilike v_patron)
       order by v.creado_en desc, v.id desc
       limit v_n + 1);
  end if;
  -- La regla de la fila sobre las candidatas (por la clave primaria); primero el VIN o el lote exactos, después lo más nuevo.
  v_ids := array(
    select v.id from public.vehiculos v
     where v.id = any (v_ids) and v.eliminado_en is null
       and (v.origen_id = any (v_t)
            or (v.origen_id = any (v_p) and (v.creado_por = v_yo or (v.lead_id is not null and public.en_cartera(v.lead_id)))))
     order by (upper(v.vin) = v_exacto or upper(v.lote) = v_exacto) is true desc, v.creado_en desc, v.id desc
     limit v_n + 1);
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', v.id, 'origen_id', v.origen_id, 'titulo', v.titulo, 'vin', v.vin, 'lote', v.lote, 'fase_id', v.fase_id, 'fase_nombre', f.nombre,
           'fase_color', f.color, 'fase_desde', v.fase_desde, 'eta_el', t.eta_el) order by u.k), '[]'::jsonb)
    into v_unidades
    from unnest(v_ids[1:v_n]) with ordinality as u(id, k)
    join public.vehiculos v on v.id = u.id
    left join public.fases f on f.id = v.fase_id
    left join public.transportes t on t.vehiculo_id = v.id;
  return jsonb_build_object('unidades', v_unidades, 'hay_mas', coalesce(cardinality(v_ids), 0) > v_n);
end;
$$;


ALTER FUNCTION "public"."logistica_donde_esta"("p_buscar" "text", "p_tope" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."logistica_donde_esta"("p_buscar" "text", "p_tope" integer) IS '«Dónde está» (6.02-3): {unidades: [{id, origen_id, titulo, vin, lote, fase_id, fase_nombre, fase_color, fase_desde, eta_el}], hay_mas}, hasta _acotar_pagina(p_tope, 10, 10), de los orígenes con la regla logistica activa cuya logística veo. Por título, VIN o lote (vehiculos_*_trgm, hasta 1.000 candidatas, más las propias por vehiculos_creador_idx donde se tiene «propios»), con la regla de la fila de la cadena sobre las candidatas; VIN o lote exactos primero. Menos de 3 letras o dígitos seguidos, o ningún origen: vacío sin error; más de 100 caracteres: 22023 hint p_buscar. Sin lead_id.';



CREATE OR REPLACE FUNCTION "public"."logistica_unidad"("p_vehiculo" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v record;
  v_alcance public.alcance_permiso;
  v_dias integer;
  v_faltan jsonb := '[]'::jsonb;
  v_movida jsonb;
begin
  if p_vehiculo is null then
    raise exception 'Falta el vehículo.' using errcode = '22023', hint = 'p_vehiculo';
  end if;
  -- Por la clave primaria.
  select x.origen_id, x.creado_por, x.lead_id, x.fase_id, x.fase_desde, x.eliminado_en into v from public.vehiculos x where x.id = p_vehiculo;
  if found and v.eliminado_en is null then
    v_alcance := public._logistica_alcance(v.origen_id);
  end if;
  if v_alcance is null
     or (v_alcance = 'propios' and v.creado_por is distinct from (select auth.uid())
         and not (v.lead_id is not null and public.en_cartera(v.lead_id))) then
    raise exception '%', public._unidad_sin_acceso(p_vehiculo) using errcode = '42501', hint = 'acceso';
  end if;

  if v.fase_id is not null then
    v_dias := public._logistica_dias(v.fase_id);
    -- Sólo los bloqueantes sin cumplir de su fase actual: el criterio de «fuera de regla» (`flujo_fuera_de_regla`).
    select coalesce(jsonb_agg(jsonb_build_object('requisito_id', e.requisito_id, 'tipo', e.tipo, 'descripcion', e.descripcion, 'detalle', e.detalle)
                              order by e.k), '[]'::jsonb)
      into v_faltan
      from public.evaluar_requisitos(p_vehiculo, null, v.fase_id) with ordinality as e(requisito_id, tipo, bloqueante, descripcion, cumplido, detalle, k)
     where e.bloqueante and not e.cumplido;
  end if;

  -- La última fila de su historial, por `historial_fases_vehiculo_idx (vehiculo_id, creado_en)`; el nombre, de `perfiles` (sin la nota).
  select jsonb_build_object('historial_id', h.id, 'usuario_id', h.usuario_id, 'nombre', nullif(btrim(p.nombre), ''), 'en', h.creado_en,
                            'de_fase_id', h.de_fase_id, 'a_fase_id', h.a_fase_id)
    into v_movida
    from (select * from public.historial_fases hf where hf.vehiculo_id = p_vehiculo order by hf.creado_en desc, hf.id desc limit 1) h
    left join public.perfiles p on p.id = h.usuario_id;

  return jsonb_build_object(
    'vehiculo_id', p_vehiculo,
    'fase_id', v.fase_id,
    'fase_desde', v.fase_desde,
    'demora_dias', v_dias,
    'demorada', coalesce(v_dias > 0 and v.fase_desde < now() - make_interval(days => v_dias), false),
    'fuera_de_regla', jsonb_array_length(v_faltan) > 0,
    'faltan', v_faltan,
    'movida', v_movida);
end;
$$;


ALTER FUNCTION "public"."logistica_unidad"("p_vehiculo" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."logistica_unidad"("p_vehiculo" "uuid") IS 'Lo del panel de una unidad que no da vehiculos (6.02-3): {vehiculo_id, fase_id, fase_desde, demora_dias, demorada, fuera_de_regla, faltan: [{requisito_id, tipo, descripcion, detalle}] (los bloqueantes sin cumplir de su fase actual), movida: {historial_id, usuario_id, nombre, en, de_fase_id, a_fase_id} | null}. Definer con el acceso de la cadena (el menor de logistica.ver y vehiculos.ver del origen; «propios» = la creó o su lead está en la cartera); inexistente, papelera o sin acceso: 42501 hint acceso con un solo texto. No devuelve lead_id ni creado_por.';



CREATE OR REPLACE FUNCTION "public"."margen_vehiculo"("p_vehiculo" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_origen uuid; cot numeric; real numeric; venta numeric; v_por jsonb;
begin
  select origen_id into v_origen from public.vehiculos where id = p_vehiculo and eliminado_en is null;
  if v_origen is null then
    perform public.assert_activo();
    raise exception 'No tienes el permiso «%».', 'logistica.margen.ver' using errcode = '42501';
  end if;
  perform public.assert_permiso('logistica.margen.ver', v_origen);
  select total_base into cot from public.cotizaciones where vehiculo_id = p_vehiculo and clase = 'final' and estado = 'activa' and eliminado_en is null;
  -- gastos_vehiculo_idx.
  select coalesce(jsonb_agg(jsonb_build_object('categoria_id', c.id, 'nombre', c.nombre, 'proposito', c.proposito, 'real', s.suma)
                            order by c.orden, c.nombre, c.id), '[]'::jsonb),
         coalesce(sum(s.suma), 0)
    into v_por, real
    from (select g.categoria_id, sum(g.monto_base) as suma
            from public.gastos g
           where g.vehiculo_id = p_vehiculo and g.eliminado_en is null
           group by g.categoria_id) s
    join public.categorias_gasto c on c.id = s.categoria_id;
  select sum(monto_base) into venta from public.pagos where vehiculo_id = p_vehiculo and confirmado and eliminado_en is null;
  return jsonb_build_object('cotizado', cot, 'real', real, 'desviacion', case when cot is null then null else cot - real end, 'venta', venta,
                            'margen', case when venta is null then null else venta - real end, 'por_categoria', v_por);
end;
$$;


ALTER FUNCTION "public"."margen_vehiculo"("p_vehiculo" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."margen_vehiculo"("p_vehiculo" "uuid") IS 'Cotizado (la final activa), real (gastos vivos en moneda base), desviación (nula sin final), venta (pagos confirmados; nula sin ninguno), margen (nulo sin venta) y por_categoria ([{categoria_id, nombre, proposito, real}], en el orden del catálogo). Pide logistica.margen.ver del origen; un vehículo inexistente o en la papelera da el mismo 42501 (6.10-2, C10–C11).';



CREATE OR REPLACE FUNCTION "public"."mensaje_editar"("p_mensaje" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cuerpo" "text", "p_menciones" "jsonb" DEFAULT '[]'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare yo uuid := (select auth.uid()); r public.mensajes; v_cuerpo text;
begin
  perform public.assert_permiso('chat.participar');
  if p_mensaje is null then
    raise exception 'Falta el mensaje.' using errcode = '22023', hint = 'id';
  end if;
  select * into r from public.mensajes m where m.id = p_mensaje for update;
  if not found or not public.es_miembro(r.conversacion_id) then
    raise exception 'No encontramos este mensaje.' using errcode = '42501';
  end if;
  if r.autor_id <> yo then
    raise exception 'Sólo quien escribió el mensaje puede editarlo.' using errcode = '42501';
  end if;
  if r.eliminado_en is not null then
    raise exception 'Un mensaje eliminado no se edita.' using errcode = '23514';
  end if;
  if clock_timestamp() > r.creado_en + interval '15 minutes' then
    raise exception 'Pasaron más de 15 minutos: el mensaje ya no se edita.' using errcode = '23514', hint = 'cuerpo';
  end if;
  v_cuerpo := public._chat_cuerpo(p_cuerpo, r.tipo = 'texto');
  if v_cuerpo is not distinct from r.cuerpo then
    return jsonb_build_object('resultado', 'sin_cambios', 'id', r.id, 'actualizado_en', coalesce(r.editado_en, r.creado_en));
  end if;
  perform public._exigir_version(coalesce(r.editado_en, r.creado_en), p_actualizado_en_esperado,
                                 'Este mensaje cambió mientras lo editabas. Recarga e intenta de nuevo.');
  update public.mensajes m set cuerpo = v_cuerpo where m.id = r.id returning * into r;
  perform public._chat_menciones_guardar(r.id, r.conversacion_id, v_cuerpo, p_menciones);
  return jsonb_build_object('resultado', 'editado', 'id', r.id, 'actualizado_en', coalesce(r.editado_en, r.creado_en));
end;
$$;


ALTER FUNCTION "public"."mensaje_editar"("p_mensaje" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cuerpo" "text", "p_menciones" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mensaje_editar_validar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.eliminado_en is null and new.cuerpo is distinct from old.cuerpo then
    if old.autor_id <> (select auth.uid()) then raise exception 'Sólo el autor edita un mensaje.' using errcode = '42501'; end if;
    new.editado_en := clock_timestamp();
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."mensaje_editar_validar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mensaje_eliminar"("p_mensaje" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare yo uuid := (select auth.uid()); r public.mensajes;
begin
  perform public.assert_activo();
  if p_mensaje is null then
    raise exception 'Falta el mensaje.' using errcode = '22023', hint = 'id';
  end if;
  select * into r from public.mensajes m where m.id = p_mensaje for update;
  if not found or not public.es_miembro(r.conversacion_id) then
    raise exception 'No encontramos este mensaje.' using errcode = '42501';
  end if;
  if r.eliminado_en is not null then
    return jsonb_build_object('resultado', 'sin_cambios', 'id', r.id);
  end if;
  if r.autor_id <> yo and not public.tiene_permiso('chat.moderar') then
    raise exception 'Sólo quien lo escribió o quien modera puede eliminar este mensaje.' using errcode = '42501';
  end if;
  update public.mensajes m set cuerpo = null, eliminado_en = clock_timestamp() where m.id = r.id;
  delete from public.mensajes_menciones mm where mm.mensaje_id = r.id;
  return jsonb_build_object('resultado', 'eliminado', 'id', r.id);
end;
$$;


ALTER FUNCTION "public"."mensaje_eliminar"("p_mensaje" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mensaje_enviar"("p_id" "uuid", "p_conversacion" "uuid", "p_cuerpo" "text", "p_menciones" "jsonb" DEFAULT '[]'::"jsonb", "p_responde_a" "uuid" DEFAULT NULL::"uuid", "p_ficha" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  yo uuid := (select auth.uid()); r public.mensajes;
  v_tipo text := 'texto'; v_ref uuid; v_ok boolean; v_cuerpo text;
begin
  perform public.assert_permiso('chat.participar');
  if p_id is null then
    raise exception 'Falta el identificador del mensaje.' using errcode = '22023', hint = 'id';
  end if;
  select * into r from public.mensajes m where m.id = p_id;
  if found then
    if r.autor_id = yo and r.conversacion_id = p_conversacion then
      return jsonb_build_object('resultado', 'repetido', 'id', r.id, 'creado_en', r.creado_en);
    end if;
    raise exception 'No pudimos enviar este mensaje. Vuelve a intentarlo.' using errcode = '22023';
  end if;
  if p_conversacion is null or not public.es_miembro(p_conversacion) then
    raise exception 'No encontramos esta conversación.' using errcode = '42501';
  end if;
  if p_ficha is not null and p_ficha <> 'null'::jsonb then
    v_tipo := case when jsonb_typeof(p_ficha) = 'object' then p_ficha ->> 'tipo' end;
    if v_tipo in ('tarea', 'evento') then
      raise exception 'Una tarea o un evento se crean con su comando.' using errcode = '22023', hint = 'ficha';
    end if;
    if v_tipo is null or v_tipo not in ('vehiculo', 'lead', 'cotizacion') then
      raise exception 'Esa ficha no es válida.' using errcode = '22023', hint = 'ficha';
    end if;
    v_ref := public._uuid_de(p_ficha -> 'id', 'ficha');
    if v_ref is null then
      raise exception 'Esa ficha no es válida.' using errcode = '22023', hint = 'ficha';
    end if;
    v_ok := case v_tipo
              when 'vehiculo' then public.puede_vehiculo(v_ref, 'vehiculos.ver')
              when 'lead' then public.puede_lead(v_ref, 'leads.ver')
              else public.puede_cotizacion(v_ref, 'cotizaciones.ver')
            end;
    if not v_ok then
      raise exception 'No encontramos esa ficha o no tienes acceso.' using errcode = '42501', hint = 'ficha';
    end if;
  end if;
  v_cuerpo := public._chat_cuerpo(p_cuerpo, v_tipo = 'texto');
  if p_responde_a is not null
     and not exists (select 1 from public.mensajes m where m.id = p_responde_a and m.conversacion_id = p_conversacion) then
    raise exception 'Ese mensaje no está en esta conversación.' using errcode = '22023', hint = 'responde_a';
  end if;
  begin
    insert into public.mensajes (id, conversacion_id, autor_id, tipo, cuerpo, vehiculo_id, lead_id, cotizacion_id, responde_a_id, creado_en)
    values (p_id, p_conversacion, yo, v_tipo::public.tipo_mensaje, v_cuerpo,
            case when v_tipo = 'vehiculo' then v_ref end, case when v_tipo = 'lead' then v_ref end, case when v_tipo = 'cotizacion' then v_ref end,
            p_responde_a, clock_timestamp())
    returning * into r;
  exception when unique_violation then
    select * into r from public.mensajes m where m.id = p_id;
    if r.autor_id = yo and r.conversacion_id = p_conversacion then
      return jsonb_build_object('resultado', 'repetido', 'id', r.id, 'creado_en', r.creado_en);
    end if;
    raise exception 'No pudimos enviar este mensaje. Vuelve a intentarlo.' using errcode = '22023';
  end;
  perform public._chat_menciones_guardar(r.id, p_conversacion, v_cuerpo, p_menciones);
  return jsonb_build_object('resultado', 'enviado', 'id', r.id, 'creado_en', r.creado_en);
end;
$$;


ALTER FUNCTION "public"."mensaje_enviar"("p_id" "uuid", "p_conversacion" "uuid", "p_cuerpo" "text", "p_menciones" "jsonb", "p_responde_a" "uuid", "p_ficha" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mensaje_evento_crear"("p_id" "uuid", "p_conversacion" "uuid", "p_datos" "jsonb", "p_destinatarios" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare yo uuid := (select auth.uid()); r public.mensajes; v_evento uuid;
begin
  perform public.assert_permiso('chat.participar');
  if p_id is null then
    raise exception 'Falta el identificador del mensaje.' using errcode = '22023', hint = 'id';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('chat_mensaje:' || p_id::text, 0));
  select * into r from public.mensajes m where m.id = p_id;
  if found then
    if r.autor_id = yo and r.conversacion_id = p_conversacion and r.tipo = 'evento' then
      return jsonb_build_object('resultado', 'repetido', 'id', r.id, 'evento_id', r.evento_id);
    end if;
    raise exception 'No pudimos crear este evento. Vuelve a intentarlo.' using errcode = '22023';
  end if;
  if p_conversacion is null or not public.es_miembro(p_conversacion) then
    raise exception 'No encontramos esta conversación.' using errcode = '42501';
  end if;
  v_evento := (public.evento_crear(gen_random_uuid(), p_datos, coalesce(p_destinatarios, '{}')) ->> 'id')::uuid;
  if exists (select 1 from public.eventos_destinatarios ed
              where ed.evento_id = v_evento and not public._chat_miembro_vigente(p_conversacion, ed.usuario_id)) then
    raise exception 'Esa persona no está en la conversación.' using errcode = '23514', hint = 'destinatarios';
  end if;
  insert into public.mensajes (id, conversacion_id, autor_id, tipo, evento_id, creado_en)
  values (p_id, p_conversacion, yo, 'evento', v_evento, clock_timestamp());
  return jsonb_build_object('resultado', 'creado', 'id', p_id, 'evento_id', v_evento);
end;
$$;


ALTER FUNCTION "public"."mensaje_evento_crear"("p_id" "uuid", "p_conversacion" "uuid", "p_datos" "jsonb", "p_destinatarios" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mensaje_tarea_crear"("p_id" "uuid", "p_conversacion" "uuid", "p_datos" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare yo uuid := (select auth.uid()); r public.mensajes; v_tarea uuid; v_responsable uuid;
begin
  perform public.assert_permiso('chat.participar');
  if p_id is null then
    raise exception 'Falta el identificador del mensaje.' using errcode = '22023', hint = 'id';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('chat_mensaje:' || p_id::text, 0));
  select * into r from public.mensajes m where m.id = p_id;
  if found then
    if r.autor_id = yo and r.conversacion_id = p_conversacion and r.tipo = 'tarea' then
      return jsonb_build_object('resultado', 'repetido', 'id', r.id, 'tarea_id', r.tarea_id);
    end if;
    raise exception 'No pudimos crear esta tarea. Vuelve a intentarlo.' using errcode = '22023';
  end if;
  if p_conversacion is null or not public.es_miembro(p_conversacion) then
    raise exception 'No encontramos esta conversación.' using errcode = '42501';
  end if;
  v_tarea := (public.tarea_crear(gen_random_uuid(), p_datos, p_conversacion) ->> 'id')::uuid;
  select t.responsable_id into v_responsable from public.tareas t where t.id = v_tarea;
  if v_responsable <> yo and not public._chat_miembro_vigente(p_conversacion, v_responsable) then
    raise exception 'Esa persona no está en la conversación de la tarea.' using errcode = '23514', hint = 'responsable_id';
  end if;
  insert into public.mensajes (id, conversacion_id, autor_id, tipo, tarea_id, creado_en)
  values (p_id, p_conversacion, yo, 'tarea', v_tarea, clock_timestamp());
  return jsonb_build_object('resultado', 'creado', 'id', p_id, 'tarea_id', v_tarea);
end;
$$;


ALTER FUNCTION "public"."mensaje_tarea_crear"("p_id" "uuid", "p_conversacion" "uuid", "p_datos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mi_sesion"("p_perspectiva" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'estado', case when not p.activo then 'baja' when p.bloqueado then 'bloqueada' else 'activa' end,
    'perfil', jsonb_build_object(
      'id', p.id, 'nombre', p.nombre, 'email', p.email, 'avatar_ruta', p.avatar_ruta,
      'actualizado_en', p.actualizado_en),
    'roles', coalesce((
      select jsonb_agg(jsonb_build_object('id', r.id, 'clave', r.clave, 'nombre', r.nombre, 'color', r.color, 'es_principal', ur.es_principal)
                       order by ur.es_principal desc, r.orden, r.nombre)
      from public.usuarios_roles ur join public.roles r on r.id = ur.rol_id
      where ur.usuario_id = p.id), '[]'::jsonb),
    'permisos', coalesce((
      select jsonb_agg(jsonb_build_object('clave', m.clave, 'origen_id', m.origen_id, 'alcance', m.alcance))
      from public.permisos_efectivos(p_perspectiva) m), '[]'::jsonb),
    'perspectiva', jsonb_build_object(
      'disponible', v.disponible,
      'rol', (
        select jsonb_build_object('id', r.id, 'nombre', r.nombre, 'color', r.color)
        from public.roles r where v.disponible and r.id = p_perspectiva),
      'roles', coalesce((
        select jsonb_agg(jsonb_build_object('id', r.id, 'nombre', r.nombre, 'color', r.color) order by r.orden, r.nombre)
        from public.roles r where v.disponible), '[]'::jsonb)),
    'preferencias', coalesce((
      select jsonb_object_agg(pu.clave, pu.valor)
      from public.preferencias_usuario pu
      where pu.usuario_id = p.id), '{}'::jsonb))
  from public.perfiles p
  cross join lateral (select public.tiene_permiso('equipo.roles.gestionar') as disponible) v
  where p.id = (select auth.uid());
$$;


ALTER FUNCTION "public"."mi_sesion"("p_perspectiva" "uuid") OWNER TO "postgres";


