CREATE OR REPLACE FUNCTION "public"."moneda_crear"("p_codigo" "text", "p_nombre" "text", "p_simbolo" "text", "p_decimales" integer DEFAULT 2) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_codigo text := upper(btrim(coalesce(p_codigo, '')));
  v_nueva timestamptz;
begin
  perform public.assert_permiso('empresa.tipos_cambio.gestionar');
  if v_codigo !~ '^[A-Z]{3}$' then
    raise exception 'El código de la moneda son tres letras, como USD.';
  end if;
  if nullif(btrim(p_nombre), '') is null or nullif(btrim(p_simbolo), '') is null then
    raise exception 'La moneda necesita un nombre y un símbolo.';
  end if;
  if exists (select 1 from public.monedas m where m.codigo::text = v_codigo) then
    raise exception 'Ya existe la moneda %.', v_codigo using errcode = '23505';
  end if;
  insert into public.monedas (codigo, nombre, simbolo, decimales, orden)
  values (v_codigo, btrim(p_nombre), btrim(p_simbolo), coalesce(p_decimales, 2),
          (select coalesce(max(m.orden), -1) + 1 from public.monedas m))
  returning actualizado_en into v_nueva;
  return v_nueva;
end;
$_$;


ALTER FUNCTION "public"."moneda_crear"("p_codigo" "text", "p_nombre" "text", "p_simbolo" "text", "p_decimales" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."moneda_guardar"("p_codigo" "text", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text" DEFAULT NULL::"text", "p_simbolo" "text" DEFAULT NULL::"text", "p_decimales" integer DEFAULT NULL::integer, "p_activa" boolean DEFAULT NULL::boolean) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.monedas;
  v_nueva timestamptz;
begin
  perform public.assert_permiso('empresa.tipos_cambio.gestionar');
  select * into v from public.monedas m where m.codigo::text = upper(btrim(p_codigo)) for update;
  if not found then
    raise exception 'Esa moneda ya no existe.' using errcode = 'PT409';
  end if;
  perform public._exigir_version(v.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió esta moneda mientras la editabas.');
  if p_activa = false and v.activa then
    if exists (select 1 from public.ajustes_empresa e where e.id = 1 and e.moneda_base = v.codigo) then
      raise exception 'La moneda base no se desactiva.';
    end if;
    if exists (select 1 from public.tipos_cambio t where t.activo and (t.moneda_de = v.codigo or t.moneda_a = v.codigo)) then
      raise exception 'Desactiva primero los tipos de cambio que usan %.', v.codigo;
    end if;
  end if;
  update public.monedas m set
    nombre = coalesce(nullif(btrim(p_nombre), ''), m.nombre),
    simbolo = coalesce(nullif(btrim(p_simbolo), ''), m.simbolo),
    decimales = coalesce(p_decimales, m.decimales),
    activa = coalesce(p_activa, m.activa)
  where m.codigo = v.codigo
  returning m.actualizado_en into v_nueva;
  return v_nueva;
end;
$$;


ALTER FUNCTION "public"."moneda_guardar"("p_codigo" "text", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text", "p_simbolo" "text", "p_decimales" integer, "p_activa" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nivel_crear"("p_id" "uuid", "p_nombre" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_nombre text; v_clave text; v_version timestamptz; v_estado text; v_tope integer := public._niveles_tope();
begin
  perform public.assert_permiso('equipo.roles.gestionar');
  lock table public.cotizaciones_niveles in share row exclusive mode;
  if p_id is null then
    raise exception 'Falta el identificador del intento.' using errcode = '22023';
  end if;
  select n.actualizado_en into v_version from public.cotizaciones_niveles n where n.id = p_id;
  if found then
    return jsonb_build_object('id', p_id, 'actualizado_en', v_version, 'repetido', true, 'lista', public._niveles_lista());
  end if;
  v_nombre := public._nivel_nombre(p_nombre);
  v_clave := public._nivel_clave(v_nombre);
  if (select count(*) from (select 1 from public.cotizaciones_niveles limit v_tope) t) >= v_tope then
    raise exception 'Ya hay % niveles, que es el máximo. Elimina uno que ninguna hoja use.', v_tope using errcode = '22023', hint = 'nombre';
  end if;
  if exists (select 1 from public.cotizaciones_niveles n where lower(btrim(n.nombre)) = lower(v_nombre)) then
    raise exception 'Ya hay un nivel «%».', v_nombre using errcode = '23505', hint = 'nombre';
  end if;
  select case when n.retirado_en is not null then ' (retirado)' else '' end into v_estado from public.cotizaciones_niveles n where n.clave = v_clave;
  if found then
    raise exception 'Ya hay un nivel con la clave «%»%: elige otro nombre.', v_clave, v_estado using errcode = '23505', hint = 'nombre';
  end if;
  insert into public.cotizaciones_niveles (id, clave, nombre) values (p_id, v_clave, v_nombre) returning actualizado_en into v_version;
  perform public._nivel_permisos_crear(v_clave, v_nombre, true);
  perform public.registrar_actividad('nivel.crear', 'cotizaciones_niveles', p_id::text, null, jsonb_build_object('clave', v_clave, 'nombre', v_nombre));
  return jsonb_build_object('id', p_id, 'clave', v_clave, 'actualizado_en', v_version, 'repetido', false, 'lista', public._niveles_lista());
end;
$$;


ALTER FUNCTION "public"."nivel_crear"("p_id" "uuid", "p_nombre" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nivel_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.cotizaciones_niveles; v_motivo text; v_roles uuid[]; v_rol uuid; v_concesiones int;
  v_ver text; v_editar text;
begin
  perform public.assert_permiso('equipo.roles.gestionar');
  select * into o from public.cotizaciones_niveles x where x.id = p_id for update;
  if not found then
    raise exception 'Ese nivel ya no existe.' using errcode = 'PT409';
  end if;
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este nivel mientras lo editabas.');
  if o.clave = 'todos' then
    raise exception 'El nivel «Todos» no se elimina.' using errcode = '22023';
  end if;
  if o.clave = 'costos' then
    raise exception 'El nivel «%» lo traen las hojas de fábrica: no se elimina. Puedes retirarlo.', o.nombre using errcode = '22023';
  end if;
  v_motivo := public._nivel_motivo_de_uso(o.clave);
  if v_motivo is not null then
    raise exception '%', v_motivo using errcode = '23503', detail = 'nivel_en_uso', hint = 'retirar';
  end if;
  v_ver := 'cotizaciones.nivel.' || o.clave || '.ver';
  v_editar := 'cotizaciones.nivel.' || o.clave || '.editar';
  select coalesce(array_agg(r.id order by r.id), '{}') into v_roles from public.roles r
   where r.id in (select rp.rol_id from public.roles_permisos rp where rp.permiso_clave in (v_ver, v_editar));
  perform 1 from public.roles r where r.id = any (v_roles) order by r.id for update;
  select count(*) into v_concesiones from (select 1 from public.roles_permisos rp where rp.permiso_clave in (v_ver, v_editar) limit 1000) x;
  -- Las concesiones caen con sus permisos (la FK de roles_permisos es `on delete cascade`).
  delete from public.permisos where nivel_clave = o.clave;
  delete from public.cotizaciones_niveles where id = p_id;
  foreach v_rol in array v_roles loop
    perform public._rol_tocar(v_rol);
  end loop;
  perform public.registrar_actividad('nivel.eliminar', 'cotizaciones_niveles', p_id::text, jsonb_build_object('clave', o.clave, 'nombre', o.nombre), null,
                                     jsonb_build_object('concesiones', v_concesiones));
  return jsonb_build_object('lista', public._niveles_lista());
end;
$$;


ALTER FUNCTION "public"."nivel_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nivel_renombrar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.cotizaciones_niveles; v_nombre text; v_version timestamptz;
begin
  perform public.assert_permiso('equipo.roles.gestionar');
  lock table public.cotizaciones_niveles in share row exclusive mode;
  select * into o from public.cotizaciones_niveles x where x.id = p_id for no key update;
  if not found then
    raise exception 'Ese nivel ya no existe.' using errcode = 'PT409';
  end if;
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este nivel mientras lo editabas.');
  if o.clave = 'todos' then
    raise exception 'El nivel «Todos» no se renombra.' using errcode = '22023';
  end if;
  v_nombre := public._nivel_nombre(p_nombre);
  if exists (select 1 from public.cotizaciones_niveles n where n.id <> p_id and lower(btrim(n.nombre)) = lower(v_nombre)) then
    raise exception 'Ya hay un nivel «%».', v_nombre using errcode = '23505', hint = 'nombre';
  end if;
  update public.cotizaciones_niveles set nombre = v_nombre where id = p_id returning actualizado_en into v_version;
  perform public._nivel_permisos_crear(o.clave, v_nombre, false);
  perform public.registrar_actividad('nivel.renombrar', 'cotizaciones_niveles', p_id::text, jsonb_build_object('nombre', o.nombre), jsonb_build_object('clave', o.clave, 'nombre', v_nombre));
  return jsonb_build_object('id', p_id, 'actualizado_en', v_version, 'lista', public._niveles_lista());
end;
$$;


ALTER FUNCTION "public"."nivel_renombrar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nivel_restaurar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.cotizaciones_niveles; v_version timestamptz;
begin
  perform public.assert_permiso('equipo.roles.gestionar');
  select * into o from public.cotizaciones_niveles x where x.id = p_id for no key update;
  if not found then
    raise exception 'Ese nivel ya no existe.' using errcode = 'PT409';
  end if;
  if o.retirado_en is null then
    return jsonb_build_object('id', p_id, 'actualizado_en', o.actualizado_en, 'sin_cambios', true, 'lista', public._niveles_lista());
  end if;
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este nivel mientras lo editabas.');
  update public.cotizaciones_niveles set retirado_en = null where id = p_id returning actualizado_en into v_version;
  perform public.registrar_actividad('nivel.restaurar', 'cotizaciones_niveles', p_id::text, jsonb_build_object('nombre', o.nombre), jsonb_build_object('clave', o.clave));
  return jsonb_build_object('id', p_id, 'actualizado_en', v_version, 'lista', public._niveles_lista());
end;
$$;


ALTER FUNCTION "public"."nivel_restaurar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nivel_retirar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.cotizaciones_niveles; v_version timestamptz;
begin
  perform public.assert_permiso('equipo.roles.gestionar');
  select * into o from public.cotizaciones_niveles x where x.id = p_id for no key update;
  if not found then
    raise exception 'Ese nivel ya no existe.' using errcode = 'PT409';
  end if;
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este nivel mientras lo editabas.');
  if o.clave = 'todos' then
    raise exception 'El nivel «Todos» no se retira.' using errcode = '22023';
  end if;
  update public.cotizaciones_niveles set retirado_en = coalesce(retirado_en, now()) where id = p_id returning actualizado_en into v_version;
  perform public.registrar_actividad('nivel.retirar', 'cotizaciones_niveles', p_id::text, jsonb_build_object('nombre', o.nombre), jsonb_build_object('clave', o.clave));
  return jsonb_build_object('id', p_id, 'actualizado_en', v_version, 'lista', public._niveles_lista());
end;
$$;


ALTER FUNCTION "public"."nivel_retirar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."nivel_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if (new.nombre, new.retirado_en) is distinct from (old.nombre, old.retirado_en) then
    new.actualizado_en := greatest(clock_timestamp(), old.actualizado_en + interval '1 microsecond');
  else
    new.actualizado_en := old.actualizado_en;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."nivel_version"() OWNER TO "postgres";


