ALTER FUNCTION "public"."notificaciones_puerta"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."notificaciones_puerta"() IS 'Puerta de notificaciones (7.01): before insert; descarta en silencio la fila de un destinatario de baja, bloqueado o sin perfil. Cubre a notificar() y a los inserts directos de otras fases.';



CREATE OR REPLACE FUNCTION "public"."notificaciones_purgar"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c_lote constant int := 5000;
  c_lotes constant int := 10;
  v_n int; v_notificaciones int := 0; v_visitados int := 0;
begin
  for i in 1 .. c_lotes loop
    delete from public.notificaciones
    where id = any (array(
      select x.id from public.notificaciones x
      where x.creado_en < now() - interval '90 days' and (x.leida_en is not null or x.accionada_en is not null)
      limit c_lote
    ));
    get diagnostics v_n = row_count;
    v_notificaciones := v_notificaciones + v_n;
    exit when v_n < c_lote;
  end loop;
  for i in 1 .. c_lotes loop
    delete from public.visitados v
    where (v.usuario_id, v.tipo, v.referencia_id) in (
      select x.usuario_id, x.tipo, x.referencia_id from public.visitados x
      where x.visto_en < now() - interval '30 days'
      limit c_lote
    );
    get diagnostics v_n = row_count;
    v_visitados := v_visitados + v_n;
    exit when v_n < c_lote;
  end loop;
  return jsonb_build_object('notificaciones', v_notificaciones, 'visitados', v_visitados);
end;
$$;


ALTER FUNCTION "public"."notificaciones_purgar"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."notificaciones_purgar"() IS 'Purga diaria (7.01): notificaciones leídas o accionadas de más de 90 días y visitados de más de 30, por lotes de 5.000 y hasta 10 por tabla y corrida. Job notificaciones-purgar.';



