CREATE OR REPLACE FUNCTION "public"."origen_apibara_agregar"("p_origen" "uuid", "p_rutas" "text"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; v_n int := 0; v_clave text; v_orden int; v_sufijo int;
begin
  perform public.assert_permiso('origenes.gestionar');
  perform 1 from public.origenes o where o.id = p_origen and o.tipo = 'subasta' for update;
  if not found then raise exception 'Ese origen no es de subasta o ya no existe.' using errcode = 'PT409'; end if;
  if p_rutas is null or cardinality(p_rutas) = 0 then return 0; end if;
  for r in select * from public.origen_apibara_rutas_sin_campo(p_origen) x where x.ruta = any (p_rutas) loop
    v_clave := left('apibara_' || regexp_replace(lower(r.ruta), '[^a-z0-9]+', '_', 'g'), 41);
    v_sufijo := 1;
    while exists (select 1 from public.origenes_campos c where c.origen_id = p_origen and c.clave = v_clave) loop
      v_sufijo := v_sufijo + 1;
      v_clave := left('apibara_' || regexp_replace(lower(r.ruta), '[^a-z0-9]+', '_', 'g'), 38) || '_' || v_sufijo;
    end loop;
    select coalesce(max(c.orden) + 10, 10) into v_orden from public.origenes_campos c where c.origen_id = p_origen;
    insert into public.origenes_campos (origen_id, clave, etiqueta, tipo, grupo, orden, clave_apibara, es_sistema)
    values (p_origen, v_clave, left(r.ruta, 60),
            case r.tipo when 'number' then 'numero' when 'boolean' then 'booleano' else 'texto' end::public.tipo_campo,
            'Otros datos de apibara', v_orden, r.ruta, false);
    v_n := v_n + 1;
  end loop;
  return v_n;
end;
$$;


ALTER FUNCTION "public"."origen_apibara_agregar"("p_origen" "uuid", "p_rutas" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_apibara_completar"("p_origen" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_n int;
begin
  if not exists (select 1 from public.origenes o where o.id = p_origen and o.tipo = 'subasta') then
    return 0;
  end if;
  insert into public.origenes_campos (origen_id, clave, etiqueta, tipo, requerido, grupo, orden, en_tarjeta, filtrable, publico_web, clave_apibara, es_sistema)
  select p_origen, c.clave, c.etiqueta, c.tipo, false, c.grupo, c.orden, c.en_tarjeta, c.filtrable, c.publico_web, c.clave_apibara, c.es_sistema
  from public._apibara_catalogo() c
  where not exists (select 1 from public.origenes_campos x where x.origen_id = p_origen and x.clave = c.clave)
    and (c.clave_apibara is null or not exists (
      select 1 from public.origenes_campos x where x.origen_id = p_origen and x.clave_apibara = c.clave_apibara));
  get diagnostics v_n = row_count;
  return v_n;
end;
$$;


ALTER FUNCTION "public"."origen_apibara_completar"("p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_apibara_rutas_sin_campo"("p_origen" "uuid") RETURNS TABLE("ruta" "text", "tipo" "text", "ejemplo" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_permiso('origenes.gestionar');
  if not exists (select 1 from public.origenes o where o.id = p_origen and o.tipo = 'subasta') then
    return;
  end if;
  return query
  with ultimos as (
    select v.apibara_raw from public.vehiculos v
    where v.origen_id = p_origen and v.eliminado_en is null and v.apibara_raw is not null
    order by v.apibara_sync_en desc nulls last limit 200
  ), hojas as (
    select h.ruta, h.tipo, h.valor from ultimos u cross join lateral public._apibara_hojas(u.apibara_raw) h
  ), conocidas as (
    select c.clave_apibara as ruta from public.origenes_campos c where c.origen_id = p_origen and c.clave_apibara is not null
    union select k.clave_apibara from public._apibara_catalogo() k where k.clave_apibara is not null
  )
  select h.ruta, min(h.tipo), min(left(h.valor #>> '{}', 80))
  from hojas h
  where h.tipo not in ('array', 'null') and not public._apibara_ruta_ignorada(h.ruta)
    and not exists (select 1 from conocidas c where c.ruta = h.ruta)
  group by h.ruta
  order by h.ruta;
end;
$$;


ALTER FUNCTION "public"."origen_apibara_rutas_sin_campo"("p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_campo_crear"("p_origen" "uuid", "p_clave" "text", "p_etiqueta" "text", "p_tipo" "public"."tipo_campo", "p_opciones" "jsonb" DEFAULT '[]'::"jsonb", "p_requerido" boolean DEFAULT false, "p_grupo" "text" DEFAULT NULL::"text", "p_en_tarjeta" boolean DEFAULT false, "p_filtrable" boolean DEFAULT false, "p_publico_web" boolean DEFAULT false, "p_clave_apibara" "text" DEFAULT NULL::"text", "p_valor_defecto" "jsonb" DEFAULT NULL::"jsonb", "p_principal" boolean DEFAULT false, "p_minimo" numeric DEFAULT NULL::numeric, "p_maximo" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_origen public.origenes; v_etiqueta text; v_grupo text := nullif(btrim(p_grupo), '');
  v_apibara text := nullif(btrim(p_clave_apibara), ''); v_id uuid; v_version timestamptz; v_defecto jsonb;
  v_principal boolean := coalesce(p_principal, false); v_desmarcado uuid; v_restriccion text;
begin
  perform public.assert_permiso('origenes.gestionar');
  select * into v_origen from public.origenes o where o.id = p_origen for update;
  if not found then raise exception 'Ese origen ya no existe.' using errcode = 'PT409'; end if;
  if p_clave is null or p_clave !~ '^[a-z][a-z0-9_]{1,40}$' then
    raise exception 'La clave del campo usa minúsculas, números y guion bajo, y empieza con una letra.';
  end if;
  if public._origen_clave_reservada(p_clave) then
    raise exception '«%» ya es un dato común de todos los vehículos: no se crea como campo propio.', p_clave;
  end if;
  v_etiqueta := public._origen_nombre_valido(p_etiqueta, 'el nombre del campo', 60);
  perform public._origen_opciones_validas(coalesce(p_opciones, '[]'::jsonb));
  if p_tipo in ('opcion', 'multi_opcion') and jsonb_array_length(coalesce(p_opciones, '[]'::jsonb)) = 0 then
    raise exception 'Un campo de opciones necesita al menos una opción.';
  end if;
  if p_tipo not in ('opcion', 'multi_opcion') and jsonb_array_length(coalesce(p_opciones, '[]'::jsonb)) > 0 then
    raise exception 'Sólo un campo de opciones lleva opciones.';
  end if;
  if v_apibara is not null and v_origen.tipo <> 'subasta' then
    raise exception 'La clave de apibara sólo se usa en orígenes de subasta.';
  end if;
  if v_grupo is not null and length(v_grupo) > 40 then raise exception 'El nombre del grupo no puede pasar de 40 caracteres.'; end if;
  if v_principal and p_tipo = 'moneda' then
    raise exception 'Un monto no identifica a un vehículo: elige otro campo como principal.' using hint = 'principal';
  end if;
  v_defecto := public._origen_valor_defecto(p_tipo, coalesce(p_opciones, '[]'::jsonb), p_valor_defecto);
  perform public._campo_rango(p_tipo, p_minimo, p_maximo, v_defecto);
  if v_principal then
    v_desmarcado := public._origen_campos_desmarcar_principal(p_origen, null);
  end if;
  begin
    insert into public.origenes_campos (origen_id, clave, etiqueta, tipo, opciones, requerido, grupo, orden, en_tarjeta, filtrable, publico_web, clave_apibara, es_sistema, valor_defecto, principal, minimo, maximo)
    values (p_origen, p_clave, v_etiqueta, p_tipo, coalesce(p_opciones, '[]'::jsonb), coalesce(p_requerido, false), v_grupo,
            coalesce((select max(c.orden) + 10 from public.origenes_campos c where c.origen_id = p_origen), 10),
            coalesce(p_en_tarjeta, false), coalesce(p_filtrable, false), coalesce(p_publico_web, false), v_apibara, false, v_defecto, v_principal, p_minimo, p_maximo)
    returning id, actualizado_en into v_id, v_version;
  exception when unique_violation then
    get stacked diagnostics v_restriccion = constraint_name;
    if v_restriccion = 'origenes_campos_principal_unico' then
      raise exception 'Otra persona marcó otro campo como principal mientras editabas.' using errcode = 'PT409';
    end if;
    raise exception 'Ya hay un campo con la clave «%» en este origen.', p_clave using errcode = '23505';
  end;
  return jsonb_build_object('id', v_id, 'actualizado_en', v_version, 'desmarcado', v_desmarcado);
end;
$_$;


ALTER FUNCTION "public"."origen_campo_crear"("p_origen" "uuid", "p_clave" "text", "p_etiqueta" "text", "p_tipo" "public"."tipo_campo", "p_opciones" "jsonb", "p_requerido" boolean, "p_grupo" "text", "p_en_tarjeta" boolean, "p_filtrable" boolean, "p_publico_web" boolean, "p_clave_apibara" "text", "p_valor_defecto" "jsonb", "p_principal" boolean, "p_minimo" numeric, "p_maximo" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_campo_eliminar"("p_campo" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.origenes_campos; v_con int;
begin
  perform public.assert_permiso('origenes.gestionar');
  select * into c from public.origenes_campos x where x.id = p_campo for update;
  if not found then raise exception 'Ese campo ya no existe.' using errcode = 'PT409'; end if;
  perform public._exigir_version(c.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este campo mientras lo editabas.');
  if c.es_sistema then
    raise exception '«%» es un campo de fábrica: no se elimina. Puedes desactivarlo.', c.etiqueta using errcode = '23503';
  end if;
  v_con := public._origen_vehiculos_con_valor(c.origen_id, c.clave);
  if v_con > 0 then
    raise exception '% % tienen un valor en «%». Desactívalo para conservarlo.',
      v_con, case when v_con = 1 then 'vehículo' else 'vehículos' end, c.etiqueta using errcode = '23503';
  end if;
  delete from public.origenes_campos where id = p_campo;
end;
$$;


ALTER FUNCTION "public"."origen_campo_eliminar"("p_campo" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_campo_guardar"("p_campo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.origenes_campos; v_origen public.origenes; v_clave text; v_nueva timestamptz;
  v_editables constant text[] := array['etiqueta', 'tipo', 'opciones', 'requerido', 'grupo', 'en_tarjeta', 'filtrable', 'publico_web', 'clave_apibara', 'activo', 'valor_defecto', 'principal', 'minimo', 'maximo'];
  v_tipo public.tipo_campo; v_opciones jsonb; v_grupo text; v_apibara text; v_con int; v_orden smallint; v_defecto jsonb;
  v_origen_id uuid; v_activo boolean; v_principal boolean; v_restriccion text;
  v_minimo numeric; v_maximo numeric;
begin
  perform public.assert_permiso('origenes.gestionar');
  if p_cambios is null or jsonb_typeof(p_cambios) <> 'object' then
    raise exception 'Faltan los cambios a guardar.';
  end if;
  for v_clave in select jsonb_object_keys(p_cambios) loop
    if not (v_clave = any (v_editables)) then
      raise exception 'El dato «%» no se cambia desde el layout de campos.', v_clave;
    end if;
    if v_clave in ('etiqueta', 'tipo', 'opciones', 'requerido', 'en_tarjeta', 'filtrable', 'publico_web', 'activo', 'principal') and p_cambios -> v_clave = 'null'::jsonb then
      raise exception 'El dato «%» no puede quedar vacío.', v_clave;
    end if;
  end loop;

  select x.origen_id into v_origen_id from public.origenes_campos x where x.id = p_campo;
  if not found then raise exception 'Ese campo ya no existe.' using errcode = 'PT409'; end if;
  select * into v_origen from public.origenes o where o.id = v_origen_id for no key update;
  select * into c from public.origenes_campos x where x.id = p_campo for update;
  if not found then raise exception 'Ese campo ya no existe.' using errcode = 'PT409'; end if;
  perform public._exigir_version(c.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este campo mientras lo editabas.');

  v_tipo := coalesce((p_cambios ->> 'tipo')::public.tipo_campo, c.tipo);
  if v_tipo is distinct from c.tipo then
    if c.es_sistema then
      raise exception 'El tipo de «%» no cambia: es un campo de fábrica.', c.etiqueta;
    end if;
    v_con := public._origen_vehiculos_con_valor(c.origen_id, c.clave);
    if v_con > 0 then
      raise exception '% % ya tienen un valor en «%»: no se puede cambiar su tipo. Desactívalo y crea otro campo.',
        v_con, case when v_con = 1 then 'vehículo' else 'vehículos' end, c.etiqueta;
    end if;
  end if;

  -- Desactivar el principal lo desmarca; marcar principal un desactivado o un monto es un error de validación.
  v_activo := coalesce((p_cambios ->> 'activo')::boolean, c.activo);
  if not v_activo and coalesce((p_cambios ->> 'principal')::boolean, false) then
    raise exception 'Un campo desactivado no puede ser el principal. Actívalo primero.' using hint = 'principal';
  end if;
  v_principal := v_activo and coalesce((p_cambios ->> 'principal')::boolean, c.principal);
  if v_principal and v_tipo = 'moneda' then
    raise exception 'Un monto no identifica a un vehículo: elige otro campo como principal.' using hint = 'principal';
  end if;

  v_opciones := coalesce(p_cambios -> 'opciones', c.opciones);
  if v_tipo not in ('opcion', 'multi_opcion') then
    v_opciones := '[]'::jsonb;
  else
    perform public._origen_opciones_validas(v_opciones);
  end if;

  if p_cambios ? 'valor_defecto' then
    v_defecto := public._origen_valor_defecto(v_tipo, v_opciones, p_cambios -> 'valor_defecto');
  elsif v_tipo is distinct from c.tipo then
    v_defecto := null;
  else
    begin
      v_defecto := public._origen_valor_defecto(v_tipo, v_opciones, c.valor_defecto);
    exception when invalid_parameter_value then
      v_defecto := null;
    end;
  end if;

  -- El rango: lo que se manda (null = sin límite) o el vigente; si el tipo deja de ser numérico, se va solo, como las opciones.
  v_minimo := public._campo_limite(p_cambios, 'minimo', case when v_tipo in ('numero', 'moneda') then c.minimo end);
  v_maximo := public._campo_limite(p_cambios, 'maximo', case when v_tipo in ('numero', 'moneda') then c.maximo end);
  perform public._campo_rango(v_tipo, v_minimo, v_maximo, v_defecto);

  v_grupo := case when p_cambios ? 'grupo' then nullif(btrim(p_cambios ->> 'grupo'), '') else c.grupo end;
  if v_grupo is not null and length(v_grupo) > 40 then raise exception 'El nombre del grupo no puede pasar de 40 caracteres.'; end if;
  v_apibara := case when p_cambios ? 'clave_apibara' then nullif(btrim(p_cambios ->> 'clave_apibara'), '') else c.clave_apibara end;
  if v_apibara is not null and v_origen.tipo <> 'subasta' then
    raise exception 'La clave de apibara sólo se usa en orígenes de subasta.';
  end if;

  -- Cambiar de grupo lo manda al final del grupo nuevo.
  v_orden := c.orden;
  if v_grupo is distinct from c.grupo then
    select max(x.orden) + 1 into v_orden from public.origenes_campos x
    where x.origen_id = c.origen_id and x.id <> c.id and x.grupo is not distinct from v_grupo;
    v_orden := coalesce(v_orden, (select coalesce(max(x.orden), 0) + 10 from public.origenes_campos x where x.origen_id = c.origen_id));
  end if;

  if v_principal and not c.principal then
    perform public._origen_campos_desmarcar_principal(c.origen_id, c.id);
  end if;
  begin
    update public.origenes_campos x set
      etiqueta = case when p_cambios ? 'etiqueta' then public._origen_nombre_valido(p_cambios ->> 'etiqueta', 'el nombre del campo', 60) else x.etiqueta end,
      tipo = v_tipo,
      opciones = v_opciones,
      requerido = coalesce((p_cambios ->> 'requerido')::boolean, x.requerido),
      grupo = v_grupo,
      en_tarjeta = coalesce((p_cambios ->> 'en_tarjeta')::boolean, x.en_tarjeta),
      filtrable = coalesce((p_cambios ->> 'filtrable')::boolean, x.filtrable),
      publico_web = coalesce((p_cambios ->> 'publico_web')::boolean, x.publico_web),
      clave_apibara = v_apibara,
      activo = v_activo,
      principal = v_principal,
      valor_defecto = v_defecto,
      minimo = v_minimo,
      maximo = v_maximo,
      orden = v_orden
    where x.id = p_campo
    returning x.actualizado_en into v_nueva;
  exception when unique_violation then
    get stacked diagnostics v_restriccion = constraint_name;
    if v_restriccion = 'origenes_campos_principal_unico' then
      raise exception 'Otra persona marcó otro campo como principal mientras editabas.' using errcode = 'PT409';
    end if;
    raise;
  end;
  if v_orden is distinct from c.orden then
    perform public._origen_campos_renumerar(c.origen_id);
  end if;
  return v_nueva;
end;
$$;


ALTER FUNCTION "public"."origen_campo_guardar"("p_campo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_campo_impacto"("p_campo" "uuid", "p_cambios" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.origenes_campos; v_min numeric; v_max numeric; v_fuera int;
begin
  perform public.assert_permiso('origenes.gestionar');
  if p_cambios is not null and jsonb_typeof(p_cambios) <> 'object' then
    raise exception 'Faltan los cambios a medir.' using errcode = '22023';
  end if;
  select * into c from public.origenes_campos x where x.id = p_campo;
  if not found then raise exception 'Ese campo ya no existe.' using errcode = 'PT409'; end if;
  -- Los vehículos del origen fuera del rango propuesto (o del vigente), con tope 50 y uno de más; null si no aplica.
  v_min := public._campo_limite(coalesce(p_cambios, '{}'::jsonb), 'minimo', c.minimo);
  v_max := public._campo_limite(coalesce(p_cambios, '{}'::jsonb), 'maximo', c.maximo);
  if c.tipo in ('numero', 'moneda') and (v_min is not null or v_max is not null) then
    select count(*)::int into v_fuera from (
      select 1 from public.vehiculos v
      where v.origen_id = c.origen_id and public._valor_fuera_de_rango(v.atributos -> c.clave, v_min, v_max) limit 51) q;
  end if;
  return public._campo_impacto(
    array(select v.atributos -> c.clave from public.vehiculos v where v.origen_id = c.origen_id), c.tipo)
    || jsonb_build_object('fuera_de_rango', v_fuera);
end;
$$;


ALTER FUNCTION "public"."origen_campo_impacto"("p_campo" "uuid", "p_cambios" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_campo_mover"("p_campo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_despues_de" "uuid" DEFAULT NULL::"uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.origenes_campos; v_nueva timestamptz;
begin
  perform public.assert_permiso('origenes.gestionar');
  select * into c from public.origenes_campos x where x.id = p_campo;
  if not found then raise exception 'Ese campo ya no existe.' using errcode = 'PT409'; end if;
  -- El orden es del origen entero: se bloquea el origen para que dos reordenamientos vayan en fila.
  perform 1 from public.origenes o where o.id = c.origen_id for update;
  select * into c from public.origenes_campos x where x.id = p_campo for update;
  perform public._exigir_version(c.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este campo mientras lo editabas.');
  if p_despues_de is not null then
    if p_despues_de = p_campo then raise exception 'Un campo no puede ir después de sí mismo.'; end if;
    if not exists (select 1 from public.origenes_campos x where x.id = p_despues_de and x.origen_id = c.origen_id) then
      raise exception 'Ese campo ya no está en este origen. Recarga e intenta de nuevo.' using errcode = 'PT409';
    end if;
  end if;

  update public.origenes_campos x set orden = n.orden_nuevo
  from public._campos_reordenar((
    select jsonb_agg(jsonb_build_object('id', y.id, 'clave', y.clave, 'orden', y.orden))
    from public.origenes_campos y where y.origen_id = c.origen_id), p_campo, p_despues_de) n
  where x.id = n.campo_id and x.orden <> n.orden_nuevo;

  select x.actualizado_en into v_nueva from public.origenes_campos x where x.id = p_campo;
  return v_nueva;
end;
$$;


ALTER FUNCTION "public"."origen_campo_mover"("p_campo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_despues_de" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_campo_validar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.clave_apibara is not null and (select o.tipo from public.origenes o where o.id = new.origen_id) <> 'subasta' then
    raise exception 'La clave de apibara sólo se usa en orígenes de subasta.';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."origen_campo_validar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_crear"("p_clave" "text", "p_nombre" "text", "p_sustantivo" "text", "p_genero" "public"."genero_gramatical", "p_tipo" "public"."tipo_origen", "p_color" "text" DEFAULT NULL::"text", "p_apibara_plataformas" "text"[] DEFAULT NULL::"text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_nombre text; v_sustantivo text; v_color text; v_plataformas text[] := coalesce(p_apibara_plataformas, '{}');
  v_id uuid; v_version timestamptz;
begin
  perform public.assert_permiso('origenes.gestionar');
  v_nombre := public._origen_nombre_valido(p_nombre, 'el nombre del origen', 60);
  v_sustantivo := public._origen_nombre_valido(p_sustantivo, 'el sustantivo de lo que entra', 30);
  if p_clave is null or p_clave !~ '^[a-z][a-z0-9_]{1,30}$' then
    raise exception 'La clave interna del origen usa minúsculas, números y guion bajo, y empieza con una letra.';
  end if;
  v_color := lower(coalesce(p_color, '#465fff'));
  if v_color !~ '^#[0-9a-f]{6}$' then
    raise exception 'El color tiene que ser un valor hexadecimal como #465fff.';
  end if;
  if p_tipo <> 'subasta' and cardinality(v_plataformas) > 0 then
    raise exception 'Las plataformas de apibara sólo se eligen en un origen de subasta.';
  end if;
  if exists (select 1 from unnest(v_plataformas) x where x !~ '^[a-z][a-z0-9_]{1,20}$') then
    raise exception 'Una plataforma de apibara no es válida.';
  end if;
  begin
    insert into public.origenes (clave, nombre, sustantivo, genero, tipo, color, orden, apibara_plataformas)
    values (p_clave, v_nombre, lower(v_sustantivo), p_genero, p_tipo, v_color,
            coalesce((select max(o.orden) + 10 from public.origenes o), 0), v_plataformas)
    returning id, actualizado_en into v_id, v_version;
  exception when unique_violation then
    -- Dos orígenes con el mismo nombre chocan también en la clave que sale de él: el que cuenta es
    -- el nombre. Sólo si el nombre es otro (dos nombres que dan la misma clave) se dice la clave.
    if exists (select 1 from public.origenes o where lower(btrim(o.nombre)) = lower(v_nombre)) then
      raise exception 'Ya existe un origen llamado «%».', v_nombre using errcode = '23505';
    end if;
    raise exception 'Ya existe un origen con un nombre muy parecido a «%». Cámbialo un poco.', v_nombre using errcode = '23505';
  end;
  return jsonb_build_object('id', v_id, 'actualizado_en', v_version);
end;
$_$;


ALTER FUNCTION "public"."origen_crear"("p_clave" "text", "p_nombre" "text", "p_sustantivo" "text", "p_genero" "public"."genero_gramatical", "p_tipo" "public"."tipo_origen", "p_color" "text", "p_apibara_plataformas" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_crear_flujo"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_flujo uuid;
begin
  insert into public.flujos (ambito, origen_id, nombre) values ('vehiculos', new.id, 'Logística ' || new.nombre) returning id into v_flujo;
  insert into public.flujos_reglas (flujo_id, regla, activa)
  select v_flujo, r, true from unnest(array['logistica', 'alerta_demora', 'vitrina_web', 'portal_cliente', 'transporte', 'contenedor', 'gastos', 'pagos', 'esperas']) r;
  if new.tipo = 'subasta' then
    insert into public.flujos_reglas (flujo_id, regla, activa) values (v_flujo, 'aduana', true);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."origen_crear_flujo"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_eliminar"("p_origen" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.origenes; v_vehiculos int; v_cotizaciones int; v_movimientos int; v_formulas int; v_motivos text[] := '{}';
begin
  perform public.assert_permiso('origenes.gestionar');
  select * into v from public.origenes o where o.id = p_origen for update;
  if not found then raise exception 'Ese origen ya no existe.' using errcode = 'PT409'; end if;
  perform public._exigir_version(v.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este origen mientras lo editabas.');

  select count(*) into v_vehiculos from public.vehiculos x where x.origen_id = p_origen;
  select count(*) into v_cotizaciones from public.cotizaciones x where x.origen_id = p_origen;
  select count(*) into v_movimientos from public.historial_fases h join public.fases f on f.id = h.a_fase_id join public.flujos fl on fl.id = f.flujo_id where fl.origen_id = p_origen;
  select count(*) into v_formulas from public.formulas x where x.origen_id = p_origen and x.estado <> 'borrador';
  if v_vehiculos > 0 then v_motivos := v_motivos || (v_vehiculos || case when v_vehiculos = 1 then ' vehículo' else ' vehículos' end); end if;
  if v_cotizaciones > 0 then v_motivos := v_motivos || (v_cotizaciones || case when v_cotizaciones = 1 then ' cotización' else ' cotizaciones' end); end if;
  if v_movimientos > 0 then v_motivos := v_motivos || (v_movimientos || case when v_movimientos = 1 then ' movimiento de fase' else ' movimientos de fase' end); end if;
  if v_formulas > 0 then v_motivos := v_motivos || 'una fórmula publicada'::text; end if;
  if cardinality(v_motivos) > 0 then
    raise exception '«%» tiene %. Desactívalo en vez de eliminarlo.', v.nombre, array_to_string(v_motivos, ', ') using errcode = '23503';
  end if;
  delete from public.origenes where id = p_origen;
end;
$$;


ALTER FUNCTION "public"."origen_eliminar"("p_origen" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_guardar"("p_origen" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text" DEFAULT NULL::"text", "p_sustantivo" "text" DEFAULT NULL::"text", "p_genero" "public"."genero_gramatical" DEFAULT NULL::"public"."genero_gramatical", "p_color" "text" DEFAULT NULL::"text", "p_activo" boolean DEFAULT NULL::boolean, "p_apibara_plataformas" "text"[] DEFAULT NULL::"text"[]) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v public.origenes; v_nombre text; v_color text; v_nueva timestamptz;
begin
  perform public.assert_permiso('origenes.gestionar');
  select * into v from public.origenes o where o.id = p_origen for update;
  if not found then raise exception 'Ese origen ya no existe.' using errcode = 'PT409'; end if;
  perform public._exigir_version(v.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este origen mientras lo editabas.');

  v_nombre := case when p_nombre is null then v.nombre else public._origen_nombre_valido(p_nombre, 'el nombre del origen', 60) end;
  v_color := lower(coalesce(p_color, v.color));
  if v_color !~ '^#[0-9a-f]{6}$' then
    raise exception 'El color tiene que ser un valor hexadecimal como #465fff.';
  end if;
  if p_apibara_plataformas is not null then
    if v.tipo <> 'subasta' and cardinality(p_apibara_plataformas) > 0 then
      raise exception 'Las plataformas de apibara sólo se eligen en un origen de subasta.';
    end if;
    if exists (select 1 from unnest(p_apibara_plataformas) x where x !~ '^[a-z][a-z0-9_]{1,20}$') then
      raise exception 'Una plataforma de apibara no es válida.';
    end if;
  end if;

  begin
    update public.origenes o set
      nombre = v_nombre,
      sustantivo = case when p_sustantivo is null then o.sustantivo else lower(public._origen_nombre_valido(p_sustantivo, 'el sustantivo de lo que entra', 30)) end,
      genero = coalesce(p_genero, o.genero),
      color = v_color,
      activo = coalesce(p_activo, o.activo),
      apibara_plataformas = coalesce(p_apibara_plataformas, o.apibara_plataformas)
    where o.id = p_origen
    returning o.actualizado_en into v_nueva;
  exception when unique_violation then
    raise exception 'Ya existe un origen llamado «%».', v_nombre using errcode = '23505';
  end;

  -- El flujo nace llamándose «Logística <origen>»: si seguía así, acompaña al nombre nuevo.
  if v_nombre <> v.nombre then
    update public.flujos f set nombre = 'Logística ' || v_nombre
    where f.origen_id = p_origen and f.ambito = 'vehiculos' and f.nombre = 'Logística ' || v.nombre;
  end if;
  return v_nueva;
end;
$_$;


ALTER FUNCTION "public"."origen_guardar"("p_origen" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text", "p_sustantivo" "text", "p_genero" "public"."genero_gramatical", "p_color" "text", "p_activo" boolean, "p_apibara_plataformas" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_lead_auditar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and new.actualizado_en is not distinct from old.actualizado_en then
    return null;
  end if;
  insert into public.actividad (accion, actor_id, tabla, registro_id, antes, despues)
  values ('origenes_lead.' || lower(tg_op), (select auth.uid()), 'origenes_lead', coalesce(new.id, old.id)::text,
          case when tg_op in ('UPDATE', 'DELETE') then to_jsonb(old) end,
          case when tg_op in ('INSERT', 'UPDATE') then to_jsonb(new) end);
  return null;
end;
$$;


ALTER FUNCTION "public"."origen_lead_auditar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_lead_crear"("p_id" "uuid", "p_nombre" "text", "p_icono" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_nombre text; v_version timestamptz; v_icono text; v_tope integer := public._origenes_lead_tope();
begin
  perform public.assert_permiso('leads.configurar');
  lock table public.origenes_lead in share row exclusive mode;
  if p_id is null then
    raise exception 'Falta el identificador del intento.' using errcode = '22023';
  end if;
  select o.actualizado_en into v_version from public.origenes_lead o where o.id = p_id;
  if found then
    return jsonb_build_object('id', p_id, 'actualizado_en', v_version, 'repetido', true,
                              'origenes', public._origenes_lead_json());
  end if;
  v_nombre := public._origen_lead_nombre(p_nombre);
  v_icono := public._icono_del_catalogo(p_icono);
  if (select count(*) from (select 1 from public.origenes_lead limit v_tope) t) >= v_tope then
    raise exception 'Ya hay % orígenes del lead, que es el máximo. Elimina uno sin leads o desactiva los que no uses.', v_tope
      using errcode = '22023', hint = 'nombre';
  end if;
  if exists (select 1 from public.origenes_lead o where lower(btrim(o.nombre)) = lower(v_nombre)) then
    raise exception 'Ya hay un origen «%».', v_nombre using errcode = '23505', hint = 'nombre';
  end if;
  insert into public.origenes_lead (id, clave, nombre, icono, orden)
  values (p_id, public._origen_lead_clave(v_nombre), v_nombre, v_icono,
          coalesce((select max(o.orden) + 10 from public.origenes_lead o), 10))
  returning actualizado_en into v_version;
  return jsonb_build_object('id', p_id, 'actualizado_en', v_version, 'repetido', false,
                            'origenes', public._origenes_lead_json());
end;
$$;


ALTER FUNCTION "public"."origen_lead_crear"("p_id" "uuid", "p_nombre" "text", "p_icono" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_lead_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.origenes_lead; v_mensaje text;
begin
  perform public.assert_permiso('leads.configurar');
  lock table public.origenes_lead in share row exclusive mode;
  select * into o from public.origenes_lead x where x.id = p_id for update;
  if not found then
    raise exception 'Ese origen ya no existe.' using errcode = 'PT409';
  end if;
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este origen mientras lo editabas.');
  if o.por_defecto then
    raise exception '«%» es el origen por defecto: quítale la marca o elige otro por defecto antes de eliminarlo.', o.nombre
      using errcode = '22023', hint = 'por_defecto';
  end if;
  v_mensaje := format('«%s» ya tiene leads: no se elimina. Desactívalo para que no se ofrezca a los nuevos.', o.nombre);
  -- Sonda por rango sobre el índice de la FK (ver `…000800`): `= p_id` recorre `leads` entera.
  if exists (select 1 from public.leads l where l.origen_lead_id >= p_id and l.origen_lead_id <= p_id) then
    raise exception '%', v_mensaje using errcode = '23503';
  end if;
  begin
    delete from public.origenes_lead x where x.id = p_id;
  exception when foreign_key_violation then
    raise exception '%', v_mensaje using errcode = '23503';
  end;
  return jsonb_build_object('origenes', public._origenes_lead_json());
end;
$$;


ALTER FUNCTION "public"."origen_lead_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_lead_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  o public.origenes_lead; v_k text; v_nombre text; v_activo boolean; v_icono text; v_defecto boolean;
begin
  perform public.assert_permiso('leads.configurar');
  lock table public.origenes_lead in share row exclusive mode;
  if p_cambios is null or jsonb_typeof(p_cambios) <> 'object' then
    raise exception 'Los cambios de un origen tienen que ser un objeto.' using errcode = '22023';
  end if;
  for v_k in select jsonb_object_keys(p_cambios) loop
    if v_k not in ('nombre', 'activo', 'icono', 'por_defecto') then
      raise exception 'El dato «%» de un origen no se cambia.', v_k using errcode = '22023', hint = v_k;
    end if;
  end loop;
  select * into o from public.origenes_lead x where x.id = p_id for update;
  if not found then
    raise exception 'Ese origen ya no existe.' using errcode = 'PT409';
  end if;
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;

  v_nombre := o.nombre;
  v_activo := o.activo;
  v_icono := o.icono;
  v_defecto := o.por_defecto;
  if p_cambios ? 'nombre' then
    if jsonb_typeof(p_cambios -> 'nombre') <> 'string' then
      raise exception 'Escribe el nombre del origen.' using errcode = '22023', hint = 'nombre';
    end if;
    v_nombre := public._origen_lead_nombre(p_cambios ->> 'nombre');
  end if;
  if p_cambios ? 'activo' then
    if jsonb_typeof(p_cambios -> 'activo') <> 'boolean' then
      raise exception 'Activo es sí o no.' using errcode = '22023', hint = 'activo';
    end if;
    v_activo := (p_cambios ->> 'activo')::boolean;
  end if;
  if p_cambios ? 'icono' then
    if jsonb_typeof(p_cambios -> 'icono') not in ('string', 'null') then
      raise exception 'El icono es una clave del catálogo o nada.' using errcode = '22023', hint = 'icono';
    end if;
    v_icono := public._icono_del_catalogo(p_cambios ->> 'icono');
  end if;
  if p_cambios ? 'por_defecto' then
    if jsonb_typeof(p_cambios -> 'por_defecto') <> 'boolean' then
      raise exception 'Por defecto es sí o no.' using errcode = '22023', hint = 'por_defecto';
    end if;
    v_defecto := (p_cambios ->> 'por_defecto')::boolean;
  end if;

  if (v_nombre, v_activo, v_icono, v_defecto) is not distinct from (o.nombre, o.activo, o.icono, o.por_defecto) then
    return jsonb_build_object('id', p_id, 'actualizado_en', o.actualizado_en, 'sin_cambios', true,
                              'origenes', public._origenes_lead_json());
  end if;
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este origen mientras lo editabas.');
  if v_defecto and not v_activo then
    if o.por_defecto then
      raise exception '«%» es el origen por defecto: quítale la marca o elige otro por defecto antes de desactivarlo.', o.nombre
        using errcode = '22023', hint = 'activo';
    end if;
    raise exception '«%» está desactivado: actívalo antes de elegirlo como origen por defecto.', o.nombre
      using errcode = '22023', hint = 'por_defecto';
  end if;
  if exists (select 1 from public.origenes_lead x where x.id <> p_id and lower(btrim(x.nombre)) = lower(v_nombre)) then
    raise exception 'Ya hay un origen «%».', v_nombre using errcode = '23505', hint = 'nombre';
  end if;
  if v_defecto and not o.por_defecto then
    update public.origenes_lead x set por_defecto = false where x.por_defecto and x.id <> p_id;
  end if;
  update public.origenes_lead x set nombre = v_nombre, activo = v_activo, icono = v_icono, por_defecto = v_defecto where x.id = p_id
  returning x.actualizado_en into o.actualizado_en;
  if v_defecto is distinct from o.por_defecto then
    perform public.registrar_actividad('origenes_lead.por_defecto', 'origenes_lead', p_id::text, null, null,
      jsonb_build_object('nombre', v_nombre, 'por_defecto', v_defecto));
  end if;
  return jsonb_build_object('id', p_id, 'actualizado_en', o.actualizado_en, 'sin_cambios', false,
                            'origenes', public._origenes_lead_json());
end;
$$;


ALTER FUNCTION "public"."origen_lead_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_lead_mover"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_despues_de" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.origenes_lead;
begin
  perform public.assert_permiso('leads.configurar');
  -- El orden es de la lista entera: el candado hace que dos reordenamientos vayan en fila.
  lock table public.origenes_lead in share row exclusive mode;
  select * into o from public.origenes_lead x where x.id = p_id for update;
  if not found then
    raise exception 'Ese origen ya no existe.' using errcode = 'PT409';
  end if;
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este origen mientras lo editabas.');
  if p_despues_de is not null then
    if p_despues_de = p_id then
      raise exception 'Un origen no puede ir después de sí mismo.' using errcode = '22023';
    end if;
    if not exists (select 1 from public.origenes_lead x where x.id = p_despues_de) then
      raise exception 'Ese origen ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
    end if;
  end if;

  update public.origenes_lead x set orden = n.orden_nuevo
  from public._campos_reordenar((
    select jsonb_agg(jsonb_build_object('id', y.id, 'clave', y.clave, 'orden', y.orden)) from public.origenes_lead y),
    p_id, p_despues_de) n
  where x.id = n.campo_id and x.orden <> n.orden_nuevo;

  perform public.registrar_actividad('origenes_lead.movido', 'origenes_lead', p_id::text, null, null,
    jsonb_build_object('nombre', o.nombre, 'despues_de', p_despues_de));
  return jsonb_build_object('id', p_id, 'actualizado_en', (select x.actualizado_en from public.origenes_lead x where x.id = p_id),
                            'origenes', public._origenes_lead_json());
end;
$$;


ALTER FUNCTION "public"."origen_lead_mover"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_despues_de" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_lead_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if (new.nombre, new.activo, new.icono) is distinct from (old.nombre, old.activo, old.icono) then
    new.actualizado_en := greatest(clock_timestamp(), old.actualizado_en + interval '1 microsecond');
  else
    new.actualizado_en := old.actualizado_en;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."origen_lead_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_preconfigurar_campos"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.tipo = 'subasta' then
    insert into public.origenes_campos (origen_id, clave, etiqueta, tipo, requerido, grupo, orden, en_tarjeta, filtrable, publico_web, clave_apibara, es_sistema)
    select new.id, c.clave, c.etiqueta, c.tipo, false, c.grupo, c.orden, c.en_tarjeta, c.filtrable, c.publico_web, c.clave_apibara, c.es_sistema
    from public._apibara_catalogo() c;
  else
    insert into public.origenes_campos (origen_id, clave, etiqueta, tipo, requerido, grupo, orden, en_tarjeta, filtrable, publico_web, es_sistema) values
      (new.id, 'color', 'Color', 'texto', false, 'Vehículo', 10, true, true, true, true),
      (new.id, 'transmision', 'Transmisión', 'opcion', false, 'Vehículo', 20, true, true, true, true),
      (new.id, 'combustible', 'Combustible', 'opcion', false, 'Vehículo', 30, false, true, true, true),
      (new.id, 'motor', 'Motor', 'texto', false, 'Vehículo', 40, false, false, true, true),
      (new.id, 'traccion', 'Tracción', 'opcion', false, 'Vehículo', 50, false, true, true, true),
      (new.id, 'carroceria', 'Carrocería', 'opcion', false, 'Vehículo', 60, false, true, true, true),
      (new.id, 'condicion', 'Condición', 'opcion', false, 'Venta', 70, true, true, true, true),
      (new.id, 'descripcion', 'Descripción comercial', 'texto_largo', false, 'Venta', 80, false, false, true, true);
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."origen_preconfigurar_campos"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."origen_tipo_inmutable"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.tipo is distinct from old.tipo then
    raise exception 'El tipo de un origen no cambia una vez creado. Si te equivocaste y todavía no se usa, elimínalo y créalo de nuevo.';
  end if;
  return new;
end;
$$;


