    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select o.id from public.origenes o
  where exists (select 1 from public.mis_permisos() m where m.clave = p_clave and (m.origen_id is null or m.origen_id = o.id));
$$;


