CREATE OR REPLACE FUNCTION "public"."origenes_resumen"() RETURNS TABLE("origen_id" "uuid", "vehiculos" integer, "cotizaciones" integer, "campos_activos" integer, "categorias" integer, "fases" integer, "formula_publicada" boolean, "concesiones" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_activo();
  if not (public.tiene_permiso('origenes.gestionar') or public.tiene_permiso('flujos.configurar') or public.tiene_permiso('cotizaciones.configurar')) then
    raise exception 'No tienes permiso para ver cómo está configurado cada origen.' using errcode = '42501';
  end if;
  return query
  select o.id,
    (select count(*)::int from public.vehiculos v where v.origen_id = o.id),
    (select count(*)::int from public.cotizaciones q where q.origen_id = o.id),
    (select count(*)::int from public.origenes_campos c where c.origen_id = o.id and c.activo),
    (select count(*)::int from public.categorias k where k.origen_id = o.id),
    (select count(*)::int from public.fases f join public.flujos fl on fl.id = f.flujo_id where fl.origen_id = o.id and f.activa),
    exists (select 1 from public.formulas fo where fo.origen_id = o.id and fo.estado = 'publicada'),
    (select count(*)::int from public.roles_permisos rp where rp.origen_id = o.id)
  from public.origenes o
  order by o.orden, o.nombre;
end;
$$;


ALTER FUNCTION "public"."origenes_resumen"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."otorgar_portal"("p_lead" "uuid", "p_clave" "text", "p_otorgado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  a public.accesos_portal; v_yo uuid := (select auth.uid()); v_clave text; v_codigo text; v_prefijo text;
  v_en timestamptz; v_nombre text; v_intento int := 0; v_listo boolean := false;
begin
  perform public._lead_mio(p_lead, 'leads.portal.gestionar', true);
  select * into a from public.accesos_portal x where x.lead_id = p_lead for update;
  if a.lead_id is null and p_otorgado_en_esperado is not null then
    raise exception 'El acceso cambió mientras lo mirabas. Recarga para ver cómo está.' using errcode = 'PT409';
  end if;
  if a.lead_id is not null and a.otorgado_en is distinct from p_otorgado_en_esperado then
    if a.otorgado_por = v_yo then
      raise exception 'Ya lo otorgaste % desde otra ventana. Recarga para ver el código nuevo.', public._hace(a.otorgado_en)
        using errcode = 'PT409';
    end if;
    select nullif(btrim(p.nombre), '') into v_nombre from public.perfiles p where p.id = a.otorgado_por;
    raise exception 'Ya lo otorgó % %. Recarga para ver el código nuevo.', coalesce(v_nombre, 'otra persona'),
      public._hace(a.otorgado_en) using errcode = 'PT409';
  end if;

  if p_clave is null then
    v_clave := public.codigo_dictable(10);
  else
    perform public._portal_clave_validar(p_clave);
    v_clave := p_clave;
  end if;

  -- El prefijo sale del nombre de la empresa (sin tildes ni signos); el código se cambia siempre.
  v_prefijo := upper(left(regexp_replace(translate((select e.nombre from public.ajustes_empresa e where e.id = 1),
    'ÁÉÍÓÚÜÑáéíóúüñ', 'AEIOUUNaeiouun'), '[^A-Za-z]', '', 'g'), 3));
  if length(v_prefijo) < 2 then v_prefijo := 'CL'; end if;
  -- Siempre posterior al anterior y en milisegundos: así sobrevive a un `Date` de JS en la cookie.
  v_en := greatest(date_trunc('milliseconds', clock_timestamp()), a.otorgado_en + interval '1 millisecond');

  while not v_listo loop
    v_intento := v_intento + 1;
    if v_intento > 20 then
      raise exception 'No pudimos generar un código. Vuelve a intentarlo.' using errcode = 'P0001';
    end if;
    v_codigo := v_prefijo || '-' || public.codigo_dictable(5);
    continue when v_codigo = a.codigo
      or exists (select 1 from public.accesos_portal x where replace(x.codigo, '-', '') = replace(v_codigo, '-', ''));
    begin
      insert into public.accesos_portal as x (lead_id, codigo, clave_hash, otorgado_por, otorgado_en)
      values (p_lead, v_codigo, extensions.crypt(v_clave, extensions.gen_salt('bf', 10)), v_yo, v_en)
      on conflict (lead_id) do update set codigo = excluded.codigo, clave_hash = excluded.clave_hash, habilitado = true,
        debe_cambiar_clave = true, intentos_fallidos = 0, bloqueado_hasta = null, otorgado_por = excluded.otorgado_por,
        otorgado_en = excluded.otorgado_en, revocado_por = null, revocado_en = null;
      v_listo := true;
    exception when unique_violation then
      -- Otro otorgar (de otro lead) se quedó con el mismo código entre la mirada y el insert.
      null;
    end;
  end loop;

  perform public.registrar_actividad(case when a.lead_id is null then 'portal.otorgado' else 'portal.reotorgado' end,
    'accesos_portal', p_lead::text, null, null,
    jsonb_strip_nulls(jsonb_build_object('codigo', v_codigo, 'codigo_anterior', a.codigo)));
  return jsonb_strip_nulls(jsonb_build_object('codigo', v_codigo, 'otorgado_en', v_en,
    'clave', case when p_clave is null then v_clave end));
end;
$$;


ALTER FUNCTION "public"."otorgar_portal"("p_lead" "uuid", "p_clave" "text", "p_otorgado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pago_anular"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_motivo" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.pagos; v_motivo text := btrim(coalesce(p_motivo, '')); v_antes jsonb; v_despues jsonb; v_fase text;
begin
  perform public.assert_permiso('logistica.pagos.confirmar');
  if length(v_motivo) not between 1 and 500 then
    raise exception 'Escribe por qué anulas el pago (hasta 500 caracteres).' using errcode = '22023', hint = 'motivo';
  end if;
  select * into o from public.pagos x where x.id = p_id;
  if not found or o.eliminado_en is not null then
    raise exception 'Ese pago ya no existe.' using errcode = 'PT409';
  end if;
  if not (case when o.vehiculo_id is not null then public.puede_vehiculo(o.vehiculo_id, 'logistica.pagos.ver')
               else public.tiene_permiso('repuestos.costos.ver') end) then
    raise exception 'No encontramos este pago o no tienes acceso.' using errcode = '42501';
  end if;
  if o.vehiculo_id is null then
    raise exception 'Los pagos de un proyecto se anulan en el paso de repuestos.' using errcode = '22023', hint = 'id';
  end if;
  if not o.confirmado then
    raise exception 'Este pago no está confirmado: elimínalo en vez de anularlo.' using errcode = '23514', hint = 'id';
  end if;
  -- C13 · los confirmados vivos del vehículo, en orden de id (la propia incluida). Usa pagos_vehiculo_idx.
  perform 1 from public.pagos x where x.vehiculo_id = o.vehiculo_id and x.confirmado and x.eliminado_en is null order by x.id for update;
  select * into o from public.pagos x where x.id = p_id;
  if o.eliminado_en is not null then
    raise exception 'Ese pago ya no existe.' using errcode = 'PT409';
  end if;
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este pago mientras lo anulabas.');
  v_antes := public._pagos_requisitos_de_fase(o.vehiculo_id);
  update public.pagos x set eliminado_en = now() where x.id = p_id returning * into o;
  v_despues := public._pagos_requisitos_de_fase(o.vehiculo_id);
  if exists (select 1 from jsonb_each(v_antes) a where a.value = 'true'::jsonb and v_despues -> a.key = 'false'::jsonb) then
    select f.nombre into v_fase from public.vehiculos v join public.fases f on f.id = v.fase_id where v.id = o.vehiculo_id;
    raise exception 'La fase «%» pide pagos confirmados: anular este pago la deja sin cumplir.', v_fase using errcode = '23514', hint = 'id';
  end if;
  perform public.registrar_actividad('pago.anulado', 'pagos', p_id::text, null, null,
                                     jsonb_build_object('motivo', v_motivo, 'monto', o.monto, 'moneda', o.moneda, 'monto_base', o.monto_base,
                                                        'confirmado_por', o.confirmado_por));
  return jsonb_build_object('id', p_id, 'actualizado_en', o.actualizado_en, 'anulado_en', o.eliminado_en);
end;
$$;


ALTER FUNCTION "public"."pago_anular"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_motivo" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pago_anular"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_motivo" "text") IS 'Anula un pago confirmado de un vehículo (borrado suave que no vuelve), con motivo y constancia pago.anulado en actividad. Pide logistica.pagos.confirmar y ver el pago; no deja sin cumplir un requisito pagos.confirmado o pagos.umbral_pct de la fase actual (23514). Uno sin confirmar se elimina con pago_eliminar (6.10-2, C12–C14).';



CREATE OR REPLACE FUNCTION "public"."pago_confirmar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.pagos; v_quien text;
begin
  perform public.assert_permiso('logistica.pagos.confirmar');
  select * into o from public.pagos x where x.id = p_id;
  if not found or o.eliminado_en is not null then
    raise exception 'Ese pago ya no existe.' using errcode = 'PT409';
  end if;
  if not (case when o.vehiculo_id is not null then public.puede_vehiculo(o.vehiculo_id, 'logistica.pagos.ver')
               else public.tiene_permiso('repuestos.costos.ver') end) then
    raise exception 'No encontramos este pago o no tienes acceso.' using errcode = '42501';
  end if;
  select * into o from public.pagos x where x.id = p_id for update;
  if o.eliminado_en is not null then
    raise exception 'Ese pago ya no existe.' using errcode = 'PT409';
  end if;
  if o.confirmado then
    select nullif(btrim(pf.nombre), '') into v_quien from public.perfiles pf where pf.id = o.confirmado_por;
    raise exception '% ya confirmó este pago %.', coalesce(v_quien, 'Otra persona'), public._hace(o.confirmado_en) using errcode = 'PT409';
  end if;
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este pago mientras lo confirmabas.');
  update public.pagos x set confirmado = true where x.id = p_id returning * into o;
  perform public.registrar_actividad('pago.confirmado', 'pagos', p_id::text, null, null,
                                     jsonb_build_object('monto', o.monto, 'moneda', o.moneda, 'monto_base', o.monto_base));
  return jsonb_build_object('id', p_id, 'actualizado_en', o.actualizado_en, 'confirmado_por', o.confirmado_por, 'confirmado_en', o.confirmado_en);
end;
$$;


ALTER FUNCTION "public"."pago_confirmar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pago_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.pagos := public._pago_tomar(p_id); v_en timestamptz;
begin
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este pago mientras lo editabas.');
  update public.pagos x set eliminado_en = now() where x.id = p_id returning x.actualizado_en into v_en;
  return jsonb_build_object('id', p_id, 'actualizado_en', v_en);
end;
$$;


ALTER FUNCTION "public"."pago_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pago_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.pagos := public._pago_tomar(p_id); n public.pagos;
begin
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  n := public._pago_de_cambios(o, p_cambios);
  if (n.lead_id, n.concepto, n.moneda, n.monto, n.tipo_cambio_id, n.tipo_cambio_aplicado, n.monto_base, n.metodo, n.fecha, n.comprobante_ruta, n.notas)
     is not distinct from
     (o.lead_id, o.concepto, o.moneda, o.monto, o.tipo_cambio_id, o.tipo_cambio_aplicado, o.monto_base, o.metodo, o.fecha, o.comprobante_ruta, o.notas) then
    return public._pago_respuesta(o, '{"sin_cambios": true}');
  end if;
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este pago mientras lo editabas.');
  update public.pagos x
     set lead_id = n.lead_id, concepto = n.concepto, moneda = n.moneda, monto = n.monto, tipo_cambio_id = n.tipo_cambio_id,
         tipo_cambio_aplicado = n.tipo_cambio_aplicado, monto_base = n.monto_base, metodo = n.metodo, fecha = n.fecha,
         comprobante_ruta = n.comprobante_ruta, notas = n.notas
   where x.id = p_id
  returning * into n;
  return public._pago_respuesta(n, '{"sin_cambios": false}');
end;
$$;


ALTER FUNCTION "public"."pago_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pago_registrar"("p_id" "uuid", "p_vehiculo" "uuid", "p_lead" "uuid", "p_concepto" "text", "p_moneda" "text", "p_monto" numeric, "p_tipo_cambio" "uuid", "p_metodo" "text", "p_fecha" "date", "p_comprobante_ruta" "text", "p_notas" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p public.pagos; c record;
begin
  perform public.assert_activo();
  if p_id is null then
    raise exception 'Falta el id del pago.' using errcode = '23502', hint = 'id';
  end if;
  if p_vehiculo is null then
    raise exception 'Elige el vehículo del pago.' using errcode = '23502', hint = 'vehiculo';
  end if;
  if not public.puede_vehiculo(p_vehiculo, 'logistica.pagos.editar') then
    raise exception 'No tienes el permiso «logistica.pagos.editar».' using errcode = '42501';
  end if;
  select * into p from public.pagos x where x.id = p_id;
  if not found then
    if not public._dinero_regla_activa(p_vehiculo, null, 'pagos') then
      raise exception 'Los pagos están apagados en el flujo de esta unidad.' using errcode = '23514';
    end if;
    perform public._pago_validar(p_vehiculo, p_concepto, p_metodo, p_monto, p_comprobante_ruta);
    c := public._monto_en_base(p_moneda, p_tipo_cambio, p_monto);
    insert into public.pagos (id, vehiculo_id, lead_id, concepto, moneda, monto, tipo_cambio_id, tipo_cambio_aplicado, monto_base, metodo, fecha,
                              comprobante_ruta, notas)
    values (p_id, p_vehiculo, p_lead, regexp_replace(btrim(p_concepto), '\s+', ' ', 'g'), p_moneda, p_monto, c.tipo_cambio_id, c.tipo_cambio_aplicado,
            c.monto_base, nullif(btrim(p_metodo), ''), coalesce(p_fecha, current_date), p_comprobante_ruta, nullif(btrim(p_notas), ''))
    on conflict (id) do nothing
    returning * into p;
    if found then
      return public._pago_respuesta(p, '{"ya_existia": false}');
    end if;
    select * into p from public.pagos x where x.id = p_id;
  end if;
  if p.vehiculo_id is distinct from p_vehiculo then
    raise exception 'Ese id ya es de otro pago.' using errcode = '23505', hint = 'id';
  end if;
  if p.eliminado_en is not null then
    raise exception 'Ese pago ya no existe.' using errcode = 'PT409';
  end if;
  return public._pago_respuesta(p, '{"ya_existia": true}');
end;
$$;


ALTER FUNCTION "public"."pago_registrar"("p_id" "uuid", "p_vehiculo" "uuid", "p_lead" "uuid", "p_concepto" "text", "p_moneda" "text", "p_monto" numeric, "p_tipo_cambio" "uuid", "p_metodo" "text", "p_fecha" "date", "p_comprobante_ruta" "text", "p_notas" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pago_registrar_proyecto"("p_id" "uuid", "p_proyecto" "uuid", "p_concepto" "text", "p_moneda" "text", "p_monto" numeric, "p_tipo_cambio" "uuid", "p_metodo" "text", "p_fecha" "date", "p_comprobante_ruta" "text", "p_notas" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p public.pagos; v_proyecto public.repuestos_proyectos; c record;
begin
  perform public.assert_activo();
  perform public.assert_permiso('repuestos.costos.editar');
  perform public.assert_permiso('repuestos.ver');
  if p_id is null then
    raise exception 'Falta el id del pago.' using errcode = '23502', hint = 'id';
  end if;
  if p_proyecto is null then
    raise exception 'Elige el proyecto del pago.' using errcode = '23502', hint = 'proyecto';
  end if;
  select * into v_proyecto from public.repuestos_proyectos x where x.id = p_proyecto for share;
  if not found or v_proyecto.eliminado_en is not null then
    raise exception 'Este proyecto ya no existe.' using errcode = 'PT409', hint = 'conflicto';
  end if;
  select * into p from public.pagos x where x.id = p_id;
  if not found then
    if v_proyecto.cerrado_en is not null then
      raise exception 'El proyecto está cerrado: reábrelo para registrar pagos.' using errcode = '23514', hint = 'proyecto';
    end if;
    -- 'NaN' > 0 es verdadero en PG y numeric(18,2) lo guarda: se corta antes de validar.
    if p_monto = 'NaN'::numeric then
      raise exception 'El monto de un pago es mayor que cero.' using errcode = '22023', hint = 'monto';
    end if;
    perform public._pago_validar(p_proyecto, p_concepto, p_metodo, p_monto, p_comprobante_ruta);
    -- Los decimales se miran antes de insertar: la columna numeric(18,2) redondearía en silencio.
    if p_monto <> round(p_monto, 2) then
      raise exception 'El monto lleva como mucho dos decimales.' using errcode = '22023', hint = 'monto';
    end if;
    c := public._monto_en_base(p_moneda, p_tipo_cambio, p_monto);
    insert into public.pagos (id, proyecto_repuestos_id, concepto, moneda, monto, tipo_cambio_id, tipo_cambio_aplicado, monto_base, metodo, fecha,
                              comprobante_ruta, notas)
    values (p_id, p_proyecto, regexp_replace(btrim(p_concepto), '\s+', ' ', 'g'), p_moneda, p_monto, c.tipo_cambio_id, c.tipo_cambio_aplicado,
            c.monto_base, nullif(btrim(p_metodo), ''), coalesce(p_fecha, current_date), p_comprobante_ruta, nullif(btrim(p_notas), ''))
    on conflict (id) do nothing
    returning * into p;
    if found then
      return public._pago_respuesta(p, '{"ya_existia": false}');
    end if;
    select * into p from public.pagos x where x.id = p_id;
  end if;
  if p.proyecto_repuestos_id is distinct from p_proyecto then
    raise exception 'Ese id ya es de otro pago.' using errcode = '23505', hint = 'id';
  end if;
  if p.eliminado_en is not null then
    raise exception 'Ese pago ya no existe.' using errcode = 'PT409';
  end if;
  return public._pago_respuesta(p, '{"ya_existia": true}');
end;
$$;


ALTER FUNCTION "public"."pago_registrar_proyecto"("p_id" "uuid", "p_proyecto" "uuid", "p_concepto" "text", "p_moneda" "text", "p_monto" numeric, "p_tipo_cambio" "uuid", "p_metodo" "text", "p_fecha" "date", "p_comprobante_ruta" "text", "p_notas" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pago_registrar_proyecto"("p_id" "uuid", "p_proyecto" "uuid", "p_concepto" "text", "p_moneda" "text", "p_monto" numeric, "p_tipo_cambio" "uuid", "p_metodo" "text", "p_fecha" "date", "p_comprobante_ruta" "text", "p_notas" "text") IS 'Registra un pago del cliente de un proyecto de repuestos (8.13-5). repuestos.costos.editar + repuestos.ver; proyecto vivo y abierto; idempotente por id.';



CREATE OR REPLACE FUNCTION "public"."pago_sellado"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare v_libres constant text[] := array['eliminado_en', 'actualizado_en', 'lead_id'];
begin
  if old.confirmado then
    if old.eliminado_en is not null and new.eliminado_en is distinct from old.eliminado_en then
      raise exception 'Un pago anulado no vuelve.' using errcode = '23514';
    end if;
    if (to_jsonb(new) - v_libres) is distinct from (to_jsonb(old) - v_libres) or (new.lead_id is distinct from old.lead_id and new.lead_id is not null) then
      raise exception 'Un pago confirmado no se edita.' using errcode = '23514';
    end if;
    return new;
  end if;
  if new.confirmado then
    if (select auth.uid()) is null then
      raise exception 'Confirmar un pago pide una sesión.' using errcode = '42501';
    end if;
    new.confirmado_por := (select auth.uid());
    new.confirmado_en := now();
  else
    new.confirmado_por := null;
    new.confirmado_en := null;
  end if;
  return new;
end;
$$;


