CREATE OR REPLACE FUNCTION "public"."pagos_listar"("p_cursor_fecha" "date", "p_cursor_id" "uuid", "p_tope" integer, "p_filtros" "jsonb") RETURNS TABLE("id" "uuid", "vehiculo_id" "uuid", "vehiculo_titulo" "text", "origen_id" "uuid", "concepto" "text", "moneda" "text", "monto" numeric, "tipo_cambio_aplicado" numeric, "monto_base" numeric, "metodo" "text", "fecha" "date", "confirmado" boolean, "confirmado_por" "uuid", "confirmado_en" timestamp with time zone, "comprobante_ruta" "text", "actualizado_en" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  -- TAMANO_DE_PAGINA_POR_DEFECTO (50), máximo 100, más una para saber si hay otra.
  v_n integer := public._acotar_pagina(p_tope, 50, 100) + 1;
  v_yo uuid := (select auth.uid());
  f record;
  v_todos uuid[]; v_algun uuid[];
begin
  perform public.assert_activo();
  select * into f from public._dinero_filtros(p_filtros, array['origen', 'desde', 'hasta', 'sin_confirmar']);
  if (p_cursor_fecha is null) <> (p_cursor_id is null) then
    raise exception 'El cursor de la lista está incompleto.' using errcode = '22023', hint = 'cursor';
  end if;
  v_todos := public.origenes_con_alcance('logistica.pagos.ver', 'todos');
  v_algun := public.origenes_con_alcance('logistica.pagos.ver', 'propios');
  if cardinality(v_algun) = 0 then
    return;
  end if;
  -- pagos_fecha_idx: (fecha desc, id desc) where eliminado_en is null. Con cursor y sin cursor son dos consultas (escala.md): la
  -- condición del cursor queda como condición de índice.
  if p_cursor_fecha is null then
    return query
      select p.id, p.vehiculo_id, v.titulo, v.origen_id, p.concepto, p.moneda::text, p.monto, p.tipo_cambio_aplicado, p.monto_base, p.metodo, p.fecha,
             p.confirmado, p.confirmado_por, p.confirmado_en, p.comprobante_ruta, p.actualizado_en
        from public.pagos p
        join public.vehiculos v on v.id = p.vehiculo_id and v.eliminado_en is null
       where p.eliminado_en is null
         and v.origen_id = any (v_algun)
         and (v.origen_id = any (v_todos) or v.creado_por = v_yo or (v.lead_id is not null and public.en_cartera(v.lead_id)))
         and (f.origen is null or v.origen_id = f.origen)
         and (f.desde is null or p.fecha >= f.desde)
         and (f.hasta is null or p.fecha <= f.hasta)
         and (f.sin_confirmar is not true or not p.confirmado)
       order by p.fecha desc, p.id desc
       limit v_n;
  else
    return query
      select p.id, p.vehiculo_id, v.titulo, v.origen_id, p.concepto, p.moneda::text, p.monto, p.tipo_cambio_aplicado, p.monto_base, p.metodo, p.fecha,
             p.confirmado, p.confirmado_por, p.confirmado_en, p.comprobante_ruta, p.actualizado_en
        from public.pagos p
        join public.vehiculos v on v.id = p.vehiculo_id and v.eliminado_en is null
       where p.eliminado_en is null
         and (p.fecha, p.id) < (p_cursor_fecha, p_cursor_id)
         and v.origen_id = any (v_algun)
         and (v.origen_id = any (v_todos) or v.creado_por = v_yo or (v.lead_id is not null and public.en_cartera(v.lead_id)))
         and (f.origen is null or v.origen_id = f.origen)
         and (f.desde is null or p.fecha >= f.desde)
         and (f.hasta is null or p.fecha <= f.hasta)
         and (f.sin_confirmar is not true or not p.confirmado)
       order by p.fecha desc, p.id desc
       limit v_n;
  end if;
end;
$$;


ALTER FUNCTION "public"."pagos_listar"("p_cursor_fecha" "date", "p_cursor_id" "uuid", "p_tope" integer, "p_filtros" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."pagos_listar"("p_cursor_fecha" "date", "p_cursor_id" "uuid", "p_tope" integer, "p_filtros" "jsonb") IS 'Los pagos de vehículos que quien llama ve (logistica.pagos.ver con su alcance), por cursor (fecha desc, id desc), con filtros origen, desde, hasta y sin_confirmar. Devuelve hasta el tope más una (hay otra página). Sin la clave, vacía. Sin lead, sin notas, sin total (6.10-2, C9).';



CREATE OR REPLACE FUNCTION "public"."papelera_enviar"("p_tipo" "public"."tipo_lote_papelera", "p_ids" "uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_lote uuid; v_id uuid; n int := 0;
begin
  perform public.assert_activo();
  perform public._papelera_solo_cotizaciones(p_tipo);
  if coalesce(array_length(p_ids, 1), 0) = 0 then raise exception 'Nada que enviar.' using errcode = '22023'; end if;
  if array_length(p_ids, 1) > 200 then raise exception 'Máximo 200 por lote.' using errcode = '22023'; end if;
  insert into public.lotes_papelera (tipo, creado_por) values (p_tipo, (select auth.uid())) returning id into v_lote;
  -- Una a una, en orden de id (como la papelera de vehículos), todo o nada: el primer rechazo aborta con su código y su texto. Un id nulo es uno inexistente.
  for v_id in select distinct x from unnest(p_ids) x order by 1 loop
    perform public._cotizacion_a_papelera(v_id, v_lote, false, null);
    n := n + 1;
  end loop;
  update public.lotes_papelera l set resumen = jsonb_build_object('cantidad', n, 'restaurados', 0, 'purgados', 0) where l.id = v_lote;
  perform public._lote_papelera_tocar(v_lote);
  perform public.registrar_actividad('papelera.enviado', 'lotes_papelera', v_lote::text, null, jsonb_build_object('tipo', p_tipo, 'cantidad', n));
  return v_lote;
end;
$$;


ALTER FUNCTION "public"."papelera_enviar"("p_tipo" "public"."tipo_lote_papelera", "p_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."papelera_listar"("p_tipo" "public"."tipo_lote_papelera") RETURNS TABLE("registro_id" "uuid", "titulo" "text", "borrado_en" timestamp with time zone, "borrado_por" "uuid", "lote_id" "uuid", "purga_el" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_dias int;
begin
  perform public.assert_activo();
  perform public._papelera_solo_cotizaciones(p_tipo);
  select papelera_dias into v_dias from public.ajustes_empresa where id = 1;
  return query select c.id, coalesce(c.titulo, 'Cotización #' || c.numero), c.eliminado_en, c.eliminado_por, c.lote_papelera_id, c.eliminado_en + make_interval(days => v_dias)
    from public.cotizaciones c where c.eliminado_en is not null and (c.eliminado_por = (select auth.uid()) or public.tiene_permiso('cotizaciones.papelera.purgar'));
end;
$$;


ALTER FUNCTION "public"."papelera_listar"("p_tipo" "public"."tipo_lote_papelera") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."papelera_purgar"("p_lote" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tipo public.tipo_lote_papelera; r jsonb;
begin
  if (select auth.uid()) is not null and not public.tiene_permiso('cotizaciones.papelera.purgar') then raise exception 'Sin permiso para purgar.' using errcode = '42501'; end if;
  -- Sin candado: un lote de otro tipo da su 22023 sin esperar a nadie.
  select tipo into v_tipo from public.lotes_papelera where id = p_lote and purgado_en is null and restaurado_en is null;
  if not found then return 0; end if;
  perform public._papelera_solo_cotizaciones(v_tipo);
  perform 1 from public.lotes_papelera l where l.id = p_lote and l.purgado_en is null and l.restaurado_en is null for no key update;
  if not found then return 0; end if;
  r := public._papelera_purgar_cotizaciones(p_lote, null);
  return jsonb_array_length(r -> 'purgados');
end;
$$;


ALTER FUNCTION "public"."papelera_purgar"("p_lote" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."papelera_purgar_vencidos"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_dias int; r record; v_resultado jsonb; total int := 0;
begin
  select e.papelera_dias into v_dias from public.ajustes_empresa e where e.id = 1;
  -- Los 50 lotes vencidos más viejos entre los tres tipos (lotes_papelera_pendientes_idx).
  for r in
    select l.id, l.tipo from public.lotes_papelera l
    where l.tipo in ('vehiculos', 'leads', 'cotizaciones') and l.purgado_en is null and l.restaurado_en is null
      and l.creado_en < now() - make_interval(days => v_dias)
      and ((l.tipo = 'vehiculos' and exists (select 1 from public.vehiculos v where v.lote_papelera_id = l.id and v.eliminado_en is not null))
        or (l.tipo = 'leads' and exists (select 1 from public.leads x where x.lote_papelera_id = l.id and x.eliminado_en is not null))
        or (l.tipo = 'cotizaciones' and (select true from public.cotizaciones c where c.lote_papelera_id = l.id and c.eliminado_en is not null limit 1)))
    order by l.creado_en
    limit 50
  loop
    begin
      if r.tipo = 'cotizaciones' then
        perform 1 from public.lotes_papelera l where l.id = r.id and l.purgado_en is null and l.restaurado_en is null for no key update skip locked;
        if found then
          v_resultado := public._papelera_purgar_cotizaciones(r.id, null);
          total := total + jsonb_array_length(v_resultado -> 'purgados');
        end if;
      else
        perform 1 from public.lotes_papelera l where l.id = r.id for update;
        if r.tipo = 'vehiculos' then
          v_resultado := public._papelera_purgar_vehiculos(r.id, null);
        else
          v_resultado := public._papelera_purgar_leads(r.id, null);
        end if;
        total := total + jsonb_array_length(v_resultado -> 'purgados');
      end if;
    exception when others then
      raise warning 'papelera: no se pudo purgar el lote %: %', r.id, sqlerrm;
    end;
  end loop;
  return total;
end;
$$;


ALTER FUNCTION "public"."papelera_purgar_vencidos"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."papelera_restaurar"("p_lote" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_tipo public.tipo_lote_papelera; v_por uuid; v_restaurado timestamptz; r jsonb;
begin
  perform public.assert_activo();
  select tipo, creado_por into v_tipo, v_por from public.lotes_papelera where id = p_lote and purgado_en is null;
  if not found then raise exception 'Lote inexistente o ya purgado.' using errcode = '22023'; end if;
  perform public._papelera_solo_cotizaciones(v_tipo);
  if v_por <> (select auth.uid()) and not public.tiene_permiso('cotizaciones.papelera.purgar') then raise exception 'Sólo quien lo envió (o quien purga) lo restaura.' using errcode = '42501'; end if;
  select l.restaurado_en into v_restaurado from public.lotes_papelera l where l.id = p_lote and l.purgado_en is null for no key update;
  if not found then raise exception 'Lote inexistente o ya purgado.' using errcode = '22023'; end if;
  -- Uno ya restaurado no se vuelve a sellar.
  if v_restaurado is not null then return 0; end if;
  r := public._papelera_restaurar_cotizaciones(p_lote, null);
  -- Todo o nada: el motivo de la primera pendiente (por id) deshace lo restaurado.
  if jsonb_array_length(r -> 'pendientes') > 0 then
    raise exception '%', r -> 'pendientes' -> 0 ->> 'motivo' using errcode = 'PT409';
  end if;
  return jsonb_array_length(r -> 'restaurados');
end;
$$;


ALTER FUNCTION "public"."papelera_restaurar"("p_lote" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."perfil_avatar_coherente"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.avatar_ruta is distinct from old.avatar_ruta then
    new.avatar_miniatura_fallo_en := null;
    -- Cambió el avatar y la miniatura no: era la del anterior.
    if new.avatar_miniatura_ruta is not distinct from old.avatar_miniatura_ruta then
      new.avatar_miniatura_ruta := null;
    end if;
  end if;
  if new.avatar_miniatura_ruta is distinct from old.avatar_miniatura_ruta and new.avatar_miniatura_ruta is not null then
    -- La carpeta es la persona, como el avatar (la policy de Storage sólo deja subir a la propia).
    if split_part(new.avatar_miniatura_ruta, '/', 1) <> new.id::text then
      raise exception 'La miniatura no es de esta persona.' using errcode = '22023', hint = 'avatar_miniatura_ruta';
    end if;
    perform public.storage_gc_rescatar('avatares', new.avatar_miniatura_ruta);
  end if;
  -- La miniatura y su fallo no son algo que la persona edite: si es lo único que cambió (el relleno), la versión del perfil
  -- no se mueve. Si no, quien tenga el perfil abierto recibiría «Tu perfil cambió» sin que nadie lo haya editado.
  if (to_jsonb(new) - array['avatar_miniatura_ruta', 'avatar_miniatura_fallo_en', 'actualizado_en'])
     = (to_jsonb(old) - array['avatar_miniatura_ruta', 'avatar_miniatura_fallo_en', 'actualizado_en']) then
    new.actualizado_en := old.actualizado_en;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."perfil_avatar_coherente"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."perfil_avatar_encolar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if old.avatar_miniatura_ruta is not null and old.avatar_miniatura_ruta is distinct from new.avatar_miniatura_ruta then
    insert into public.cola_gc_storage (bucket, ruta) values ('avatares', old.avatar_miniatura_ruta) on conflict do nothing;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."perfil_avatar_encolar"() OWNER TO "postgres";


