CREATE OR REPLACE FUNCTION "public"."push_abrir"("p_pase" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_notificacion bigint;
  n public.notificaciones;
begin
  -- Limpieza acotada de los pases viejos (por push_pases_creado_en_idx).
  delete from public.push_pases p
   where p.pase in (select q.pase from public.push_pases q where q.creado_en < now() - interval '1 day' order by q.creado_en limit 100);

  update public.push_pases p set usado_en = now()
   where p.pase = p_pase and p.usado_en is null and p.creado_en > now() - interval '10 minutes'
  returning p.notificacion_id into v_notificacion;
  if v_notificacion is null then
    return null;
  end if;

  select * into n from public.notificaciones x where x.id = v_notificacion;
  return jsonb_build_object(
    'titulo', n.titulo,
    'cuerpo', n.cuerpo,
    'ruta', n.ruta,
    'suscripciones', coalesce((
      select jsonb_agg(jsonb_build_object('id', s.id, 'endpoint', s.endpoint, 'claves', s.claves) order by s.creado_en desc, s.id desc)
        from (select t.id, t.endpoint, t.claves, t.creado_en from public.suscripciones_push t where t.usuario_id = n.usuario_id
                 and public._push_endpoint_valido(t.endpoint)
               order by t.creado_en desc, t.id desc limit public._push_tope_por_persona()) s), '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."push_abrir"("p_pase" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."push_abrir"("p_pase" "uuid") IS 'Push web (7.03): canjea el pase (una vez, 10 minutos) y devuelve {titulo, cuerpo, ruta, suscripciones: [{id, endpoint, claves}]} del destinatario, o null. Sólo service_role (la función push).';



CREATE OR REPLACE FUNCTION "public"."push_desuscribir"("p_endpoint" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_activo();
  delete from public.suscripciones_push s where s.endpoint = p_endpoint and s.usuario_id = (select auth.uid());
  return found;
end;
$$;


ALTER FUNCTION "public"."push_desuscribir"("p_endpoint" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."push_desuscribir"("p_endpoint" "text") IS 'Push web (7.03): quita la suscripción propia de ese endpoint; false si no era tuya o no existía. No exige notificaciones.push.';



CREATE OR REPLACE FUNCTION "public"."push_disparar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_url text;
  v_pase uuid;
begin
  -- Fuera del bloque de excepción: con el push apagado no se abre una subtransacción por fila.
  if not exists (select 1 from public.integraciones i where i.clave = 'push_web' and i.activa) then
    return null;
  end if;

  begin
    if not public.usuario_tiene_permiso(new.usuario_id, 'notificaciones.push') then
      return null;
    end if;
    if exists (select 1 from public.preferencias_usuario pu
                where pu.usuario_id = new.usuario_id and pu.clave = 'notificaciones.push' and pu.valor -> new.tipo = 'false'::jsonb) then
      return null;
    end if;
    if not exists (select 1 from public.suscripciones_push s where s.usuario_id = new.usuario_id) then
      return null;
    end if;
    -- Sin la URL del proyecto no se manda nada, sin aviso: los jobs ya avisan de la falta y esto corre por cada notificación.
    v_url := public._url_del_proyecto();
    if v_url is null then
      return null;
    end if;

    insert into public.push_pases (notificacion_id) values (new.id) returning pase into v_pase;
    perform net.http_post(url := v_url || '/functions/v1/push', body := jsonb_build_object('pase', v_pase),
      headers := jsonb_build_object('Content-Type', 'application/json'), timeout_milliseconds := 30000);
  exception when others then
    -- Sólo el código: nada de datos de la persona en el log.
    raise warning 'push_disparar: no se disparó (%)', sqlstate;
  end;
  return null;
end;
$$;


ALTER FUNCTION "public"."push_disparar"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."push_disparar"() IS 'Push web (7.03): after insert en notificaciones; con push_web activa, el permiso notificaciones.push del destinatario, el tipo encendido, una suscripción y url_proyecto, crea un pase y llama a la función push por pg_net. Nunca rompe el insert.';



CREATE OR REPLACE FUNCTION "public"."push_resultado"("p_pase" "uuid", "p_resultados" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_usuario uuid;
  v_enviadas int := 0;
  v_caducadas int := 0;
  v_fallos int := 0;
begin
  if p_resultados is null or jsonb_typeof(p_resultados) <> 'array' or jsonb_array_length(p_resultados) > public._push_tope_por_persona()
     or exists (select 1 from jsonb_array_elements(p_resultados) e
                 where jsonb_typeof(e) <> 'object' or (e ->> 'estado') is null or (e ->> 'estado') not in ('enviada', 'caducada', 'fallo')) then
    raise exception 'Los resultados del push no son válidos.' using errcode = '22023', hint = 'resultados';
  end if;

  -- Una vez por pase, y sólo de uno abierto hace menos de 10 minutos.
  update public.push_pases p set resultado_en = now()
   where p.pase = p_pase and p.usado_en is not null and p.usado_en > now() - interval '10 minutes' and p.resultado_en is null
  returning (select x.usuario_id from public.notificaciones x where x.id = p.notificacion_id) into v_usuario;
  if v_usuario is null then
    return null;
  end if;

  -- Sólo las suscripciones del destinatario del pase: un id ajeno se ignora. Sin count: lo cuenta cada sentencia.
  update public.suscripciones_push s set ultimo_envio_en = now(), fallos = 0
    from jsonb_to_recordset(p_resultados) as r (id uuid, estado text)
   where r.estado = 'enviada' and s.id = r.id and s.usuario_id = v_usuario;
  get diagnostics v_enviadas = row_count;
  update public.suscripciones_push s set fallos = least(s.fallos + 1, 32767)
    from jsonb_to_recordset(p_resultados) as r (id uuid, estado text)
   where r.estado = 'fallo' and s.id = r.id and s.usuario_id = v_usuario;
  get diagnostics v_fallos = row_count;
  delete from public.suscripciones_push s
   using jsonb_to_recordset(p_resultados) as r (id uuid, estado text)
   where r.estado = 'caducada' and s.id = r.id and s.usuario_id = v_usuario;
  get diagnostics v_caducadas = row_count;

  return jsonb_build_object('enviadas', v_enviadas, 'caducadas', v_caducadas, 'fallos', v_fallos);
end;
$$;


ALTER FUNCTION "public"."push_resultado"("p_pase" "uuid", "p_resultados" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."push_resultado"("p_pase" "uuid", "p_resultados" "jsonb") IS 'Push web (7.03): anota lo que pasó con cada suscripción del pase ([{id, estado: enviada|caducada|fallo}], hasta 10): enviada sella ultimo_envio_en, fallo suma uno, caducada (404/410) la borra. Una vez por pase; null si el pase no está abierto o ya tiene resultado. Sólo service_role.';



CREATE OR REPLACE FUNCTION "public"."push_suscribir"("p_endpoint" "text", "p_claves" "jsonb", "p_user_agent" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_yo uuid := (select auth.uid());
  v_id uuid;
begin
  perform public.assert_permiso('notificaciones.push');

  if not public._push_endpoint_valido(p_endpoint) then
    raise exception 'La dirección no es de un servicio de push.' using errcode = '22023', hint = 'endpoint';
  end if;

  if p_claves is null or jsonb_typeof(p_claves) <> 'object'
     or jsonb_typeof(p_claves -> 'p256dh') is distinct from 'string' or jsonb_typeof(p_claves -> 'auth') is distinct from 'string'
     or (p_claves ->> 'p256dh') !~ '^[A-Za-z0-9_-]{16,128}={0,2}$' or (p_claves ->> 'auth') !~ '^[A-Za-z0-9_-]{16,128}={0,2}$' then
    raise exception 'Las claves de la suscripción no son válidas.' using errcode = '22023', hint = 'claves';
  end if;

  -- Serializa las suscripciones de una misma persona: el tope no se pasa con dos a la vez.
  perform pg_advisory_xact_lock(hashtextextended('push_suscribir:' || v_yo::text, 0));

  -- Un endpoint que ya existe (de otra persona o de la misma) pasa a quien suscribe: lo conoce sólo quien usa ese navegador.
  insert into public.suscripciones_push as s (usuario_id, endpoint, claves, user_agent, creado_en)
  values (v_yo, p_endpoint, jsonb_build_object('p256dh', p_claves ->> 'p256dh', 'auth', p_claves ->> 'auth'),
          left(nullif(btrim(p_user_agent), ''), 512), clock_timestamp())
  on conflict (endpoint) do update
    set usuario_id = excluded.usuario_id, claves = excluded.claves, user_agent = excluded.user_agent,
        creado_en = excluded.creado_en, ultimo_envio_en = null, fallos = 0
  returning s.id into v_id;

  -- El tope: se va la menos reciente.
  delete from public.suscripciones_push s
   where s.usuario_id = v_yo
     and s.id not in (select t.id from public.suscripciones_push t where t.usuario_id = v_yo
                       order by t.creado_en desc, t.id desc limit public._push_tope_por_persona());
  return v_id;
end;
$_$;


ALTER FUNCTION "public"."push_suscribir"("p_endpoint" "text", "p_claves" "jsonb", "p_user_agent" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."push_suscribir"("p_endpoint" "text", "p_claves" "jsonb", "p_user_agent" "text") IS 'Push web (7.03): guarda la suscripción de este navegador. Exige notificaciones.push; el endpoint es https de un servicio de push (22023 hint endpoint) y las claves p256dh/auth en base64url (22023 hint claves). Un endpoint que ya existe pasa a quien suscribe; tope de 10 por persona (se borra la menos reciente).';



CREATE OR REPLACE FUNCTION "public"."rbac_asignar_rol"("p_usuario" "uuid", "p_rol" "uuid", "p_principal" boolean DEFAULT false) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_permiso('equipo.usuarios.gestionar');
  perform 1 from public.roles where id = p_rol for share;
  if not public.rol_dominado(p_rol) then raise exception 'No puedes asignar un rol con permisos que no tienes.' using errcode = '42501'; end if;
  perform 1 from public.perfiles where id = p_usuario for update;
  if not found then raise exception 'Esa persona ya no está en el equipo.' using errcode = 'PT409'; end if;
  perform public._exigir_persona_dominada(p_usuario, 'cambiar los roles de');
  insert into public.usuarios_roles (usuario_id, rol_id, es_principal, asignado_por) values (p_usuario, p_rol, p_principal, (select auth.uid()))
  on conflict (usuario_id, rol_id) do update set es_principal = excluded.es_principal;
  if p_principal then update public.usuarios_roles set es_principal = false where usuario_id = p_usuario and rol_id <> p_rol; end if;
  perform public.registrar_actividad('usuario.rol_asignado', 'usuarios_roles', p_usuario::text, null, jsonb_build_object('rol', p_rol));
end;
$$;


ALTER FUNCTION "public"."rbac_asignar_rol"("p_usuario" "uuid", "p_rol" "uuid", "p_principal" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rbac_crear_rol"("p_clave" "text", "p_nombre" "text", "p_color" "text" DEFAULT NULL::"text", "p_descripcion" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_id uuid;
begin
  perform public.assert_permiso('equipo.roles.gestionar');
  begin
    insert into public.roles (clave, nombre, color, descripcion) values (p_clave, p_nombre, p_color, p_descripcion) returning id into v_id;
  exception when unique_violation then
    raise exception 'Ya existe un rol con ese nombre.' using errcode = '23505';
  end;
  perform public.registrar_actividad('rol.creado', 'roles', v_id::text, null, jsonb_build_object('clave', p_clave, 'nombre', p_nombre));
  return v_id;
end;
$$;


ALTER FUNCTION "public"."rbac_crear_rol"("p_clave" "text", "p_nombre" "text", "p_color" "text", "p_descripcion" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rbac_eliminar_rol"("p_rol" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_sistema boolean; v_personas int;
begin
  perform public.assert_permiso('equipo.roles.gestionar');
  perform public._rol_para_editar(p_rol, p_actualizado_en_esperado);
  select es_sistema into v_sistema from public.roles where id = p_rol;
  if v_sistema then raise exception 'Un rol de sistema no se elimina.' using errcode = '42501'; end if;
  if not public.rol_dominado(p_rol) then raise exception 'No puedes eliminar un rol con permisos que no tienes.' using errcode = '42501'; end if;
  select count(*) into v_personas from public.usuarios_roles where rol_id = p_rol;
  if v_personas = 1 then raise exception 'Una persona tiene este rol: quítaselo antes de eliminarlo.' using errcode = '23503'; end if;
  if v_personas > 1 then raise exception '% personas tienen este rol: quítaselo antes de eliminarlo.', v_personas using errcode = '23503'; end if;
  delete from public.roles where id = p_rol;
  perform public.registrar_actividad('rol.eliminado', 'roles', p_rol::text, null, null);
end;
$$;


ALTER FUNCTION "public"."rbac_eliminar_rol"("p_rol" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rbac_guardian"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (select 1 from public.perfiles) and not exists (
    select 1 from public.perfiles p
    where p.activo and not p.bloqueado
      and (p.invitado_en is null or p.invitacion_aceptada_en is not null)
      and exists (
        select 1 from public.usuarios_roles ur join public.roles_permisos rp on rp.rol_id = ur.rol_id
        where ur.usuario_id = p.id and rp.permiso_clave = 'equipo.roles.gestionar' and rp.origen_id is null)
      and exists (
        select 1 from public.usuarios_roles ur join public.roles_permisos rp on rp.rol_id = ur.rol_id
        where ur.usuario_id = p.id and rp.permiso_clave = 'equipo.usuarios.gestionar' and rp.origen_id is null)
  ) then
    raise exception 'Siempre tiene que quedar alguien activo que gestione los roles y las personas del equipo.' using errcode = '23514';
  end if;
  if exists (select 1 from public.roles where clave = 'dueno') and exists (
    select 1 from public.permisos pe
    where pe.modulo = 'equipo'
      and not exists (
        select 1 from public.roles r join public.roles_permisos rp on rp.rol_id = r.id
        where r.clave = 'dueno' and rp.permiso_clave = pe.clave and rp.origen_id is null and rp.alcance = 'todos')
  ) then
    raise exception 'El rol dueño no puede perder los permisos de equipo.' using errcode = '23514';
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."rbac_guardian"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rbac_otorgar"("p_rol" "uuid", "p_clave" "text", "p_actualizado_en_esperado" timestamp with time zone, "p_origen" "uuid" DEFAULT NULL::"uuid", "p_alcance" "public"."alcance_permiso" DEFAULT 'todos'::"public"."alcance_permiso") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_por_origen boolean; v_con_alcance boolean;
begin
  perform public.assert_permiso('equipo.roles.gestionar');
  perform public._rol_para_editar(p_rol, p_actualizado_en_esperado);
  select por_origen, con_alcance into v_por_origen, v_con_alcance from public.permisos where clave = p_clave;
  if not found then raise exception 'Permiso desconocido: %', p_clave using errcode = '22023'; end if;
  if p_origen is not null and not v_por_origen then raise exception 'El permiso % no se acota por origen.', p_clave using errcode = '22023'; end if;
  if p_alcance = 'propios' and not v_con_alcance then raise exception 'El permiso % no distingue entre lo propio y todo.', p_clave using errcode = '22023'; end if;
  if not public.rol_dominado(p_rol) then raise exception 'No puedes editar un rol con permisos que no tienes.' using errcode = '42501'; end if;
  if not public.concesion_dominada(p_clave, p_origen, p_alcance) then raise exception 'No puedes otorgar «%» con ese origen y alcance: no lo tienes.', p_clave using errcode = '42501'; end if;
  insert into public.roles_permisos (rol_id, permiso_clave, origen_id, alcance) values (p_rol, p_clave, p_origen, p_alcance)
  on conflict (rol_id, permiso_clave, origen_id) do update set alcance = excluded.alcance;
  perform public.registrar_actividad('rol.permiso_otorgado', 'roles_permisos', p_rol::text, null, jsonb_build_object('clave', p_clave, 'origen', p_origen, 'alcance', p_alcance));
  return public._rol_tocar(p_rol);
end;
$$;


ALTER FUNCTION "public"."rbac_otorgar"("p_rol" "uuid", "p_clave" "text", "p_actualizado_en_esperado" timestamp with time zone, "p_origen" "uuid", "p_alcance" "public"."alcance_permiso") OWNER TO "postgres";


