CREATE OR REPLACE FUNCTION "public"."recordatorios_notificar"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r record; n int := 0; v_ruta text;
begin
  for r in
    select x.id, x.usuario_id, x.lead_id, x.titulo, x.eliminado_en
    from public.recordatorios x
    where x.notificado_en is null and x.completado_en is null and x.recordar_en <= now()
    order by x.recordar_en, x.id
    limit 200
    for update skip locked
  loop
    if r.eliminado_en is null then
      v_ruta := case
        when r.lead_id is not null and exists (
          select 1 from public.leads_asesores la join public.leads l on l.id = la.lead_id
          where la.lead_id = r.lead_id and la.usuario_id = r.usuario_id and la.revocado_en is null and l.eliminado_en is null
        ) then '/leads/' || r.lead_id
        else '/agenda?recordatorio=' || r.id
      end;
      delete from public.notificaciones
      where usuario_id = r.usuario_id and tipo = 'recordatorio' and referencia_id = r.id and accionada_en is null;
      perform public.notificar(r.usuario_id, 'recordatorio', r.titulo, null, 'recordatorio', r.id, v_ruta, true);
    end if;
    update public.recordatorios set notificado_en = now() where id = r.id;
    n := n + 1;
  end loop;
  return n;
end;
$$;


ALTER FUNCTION "public"."recordatorios_notificar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."registrar_actividad"("p_accion" "text", "p_tabla" "text", "p_registro_id" "text", "p_antes" "jsonb" DEFAULT NULL::"jsonb", "p_despues" "jsonb" DEFAULT NULL::"jsonb", "p_detalle" "jsonb" DEFAULT NULL::"jsonb") RETURNS "void"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  insert into public.actividad (accion, actor_id, tabla, registro_id, antes, despues, detalle)
  values (p_accion, (select auth.uid()), p_tabla, p_registro_id, p_antes, p_despues, p_detalle);
$$;


ALTER FUNCTION "public"."registrar_actividad"("p_accion" "text", "p_tabla" "text", "p_registro_id" "text", "p_antes" "jsonb", "p_despues" "jsonb", "p_detalle" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."registrar_actividad"("p_accion" "text", "p_tabla" "text", "p_registro_id" "text", "p_antes" "jsonb", "p_despues" "jsonb", "p_detalle" "jsonb") IS 'Deja una fila en actividad con el actor de la sesión. Sólo la llaman funciones security definer (corren como su dueño): la app no la ejecuta desde 9.01-2. Una función invocadora que la llame fallaría con 42501: areas/actividad/registrar.sql lo vigila.';



CREATE OR REPLACE FUNCTION "public"."repuesto_compra_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.repuestos_compras; v_en timestamptz;
begin
  perform public.assert_permiso('repuestos.costos.editar');
  perform public.assert_permiso('repuestos.ver');
  select * into o from public.repuestos_compras x where x.id = p_id for update;
  if not found or o.eliminado_en is not null then
    raise exception 'Esta compra ya no existe.' using errcode = 'PT409', hint = 'conflicto';
  end if;
  perform public._repuesto_compra_proyecto(o.proyecto_id);
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió esta compra. Recarga para ver lo nuevo.');
  update public.repuestos_compras x set eliminado_en = now() where x.id = p_id returning x.actualizado_en into v_en;
  return jsonb_build_object('id', p_id, 'actualizado_en', v_en);
end;
$$;


ALTER FUNCTION "public"."repuesto_compra_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repuesto_compra_guardar"("p_id" "uuid", "p_datos" "jsonb", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.repuestos_compras; n public.repuestos_compras; v_proyecto uuid;
begin
  perform public.assert_permiso('repuestos.costos.editar');
  perform public.assert_permiso('repuestos.ver');
  if p_id is null then
    raise exception 'Falta el identificador de la compra.' using errcode = '23502', hint = 'id';
  end if;
  if p_datos is null or jsonb_typeof(p_datos) <> 'object' then
    raise exception 'Los datos de la compra van como un objeto.' using errcode = '22023', hint = 'datos';
  end if;

  if p_actualizado_en_esperado is null then
    begin
      v_proyecto := nullif(btrim(p_datos ->> 'proyecto_id'), '')::uuid;
    exception when invalid_text_representation then
      raise exception 'Ese proyecto no existe.' using errcode = '22023', hint = 'proyecto_id';
    end;
    select * into o from public.repuestos_compras x where x.id = p_id;
    if not found then
      if v_proyecto is null then
        raise exception 'Falta el proyecto de la compra.' using errcode = '23502', hint = 'proyecto_id';
      end if;
      perform public._repuesto_compra_proyecto(v_proyecto);
      o.id := p_id;
      o.proyecto_id := v_proyecto;
      o.fecha := current_date;
      n := public._repuesto_compra_de_datos(o, p_datos, true);
      insert into public.repuestos_compras (id, proyecto_id, item_id, proveedor, moneda, monto, tipo_cambio_id, tipo_cambio_aplicado, monto_base, fecha,
                                            comprobante_ruta, notas, creado_por)
      values (p_id, n.proyecto_id, n.item_id, n.proveedor, n.moneda, n.monto, n.tipo_cambio_id, n.tipo_cambio_aplicado, n.monto_base, n.fecha,
              n.comprobante_ruta, n.notas, (select auth.uid()))
      on conflict (id) do nothing
      returning * into n;
      if found then
        return public._repuesto_compra_respuesta(n, '{"ya_existia": false}');
      end if;
      select * into o from public.repuestos_compras x where x.id = p_id;
    end if;
    -- D3 · un reintento con el mismo id devuelve lo guardado y nunca pisa.
    if o.proyecto_id is distinct from v_proyecto then
      raise exception 'Ese id ya es de otra compra.' using errcode = '23505', hint = 'id';
    end if;
    if o.eliminado_en is not null then
      raise exception 'Esta compra ya no existe.' using errcode = 'PT409', hint = 'conflicto';
    end if;
    return public._repuesto_compra_respuesta(o, '{"ya_existia": true}');
  end if;

  select * into o from public.repuestos_compras x where x.id = p_id for update;
  if not found or o.eliminado_en is not null then
    raise exception 'Esta compra ya no existe.' using errcode = 'PT409', hint = 'conflicto';
  end if;
  perform public._repuesto_compra_proyecto(o.proyecto_id);
  n := public._repuesto_compra_de_datos(o, p_datos, false);
  if (n.item_id, n.proveedor, n.moneda, n.monto, n.tipo_cambio_id, n.tipo_cambio_aplicado, n.monto_base, n.fecha, n.comprobante_ruta, n.notas)
     is not distinct from
     (o.item_id, o.proveedor, o.moneda, o.monto, o.tipo_cambio_id, o.tipo_cambio_aplicado, o.monto_base, o.fecha, o.comprobante_ruta, o.notas) then
    return public._repuesto_compra_respuesta(o, '{"sin_cambios": true}');
  end if;
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió esta compra. Recarga para ver lo nuevo.');
  update public.repuestos_compras x
     set item_id = n.item_id, proveedor = n.proveedor, moneda = n.moneda, monto = n.monto, tipo_cambio_id = n.tipo_cambio_id,
         tipo_cambio_aplicado = n.tipo_cambio_aplicado, monto_base = n.monto_base, fecha = n.fecha, comprobante_ruta = n.comprobante_ruta, notas = n.notas
   where x.id = p_id
  returning * into n;
  return public._repuesto_compra_respuesta(n, '{"sin_cambios": false}');
end;
$$;


ALTER FUNCTION "public"."repuesto_compra_guardar"("p_id" "uuid", "p_datos" "jsonb", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repuesto_compra_restaurar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.repuestos_compras; i public.repuestos_items; v_en timestamptz;
begin
  perform public.assert_permiso('repuestos.costos.editar');
  perform public.assert_permiso('repuestos.ver');
  select * into o from public.repuestos_compras x where x.id = p_id for update;
  if not found then
    raise exception 'Esta compra ya no existe.' using errcode = 'PT409', hint = 'conflicto';
  end if;
  perform public._repuesto_compra_proyecto(o.proyecto_id);
  if o.eliminado_en is null then
    return jsonb_build_object('id', p_id, 'actualizado_en', o.actualizado_en);
  end if;
  perform public._exigir_version(o.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió esta compra. Recarga para ver lo nuevo.');
  if o.item_id is not null then
    select * into i from public.repuestos_items x where x.id = o.item_id for share;
    if not found or i.eliminado_en is not null then
      raise exception 'El ítem de esta compra se eliminó: restáuralo o registra la compra sin ítem.' using errcode = '23514', hint = 'item_id';
    end if;
  end if;
  update public.repuestos_compras x set eliminado_en = null where x.id = p_id returning x.actualizado_en into v_en;
  return jsonb_build_object('id', p_id, 'actualizado_en', v_en);
end;
$$;


ALTER FUNCTION "public"."repuesto_compra_restaurar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repuesto_item_crear"("p_id" "uuid", "p_proyecto" "uuid", "p_datos" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i public.repuestos_items;
  p public.repuestos_proyectos;
  v_datos jsonb := coalesce(p_datos, '{}'::jsonb);
  k text; v_desc text; v_cantidad integer; v_precio numeric; v_moneda text; v_fase uuid; v_flujo uuid;
begin
  perform public.assert_permiso('repuestos.editar');
  if p_id is null then
    raise exception 'Falta el identificador del ítem.' using errcode = '22023', hint = 'id';
  end if;
  if p_proyecto is null then
    raise exception 'Falta el proyecto del ítem.' using errcode = '22023', hint = 'proyecto';
  end if;

  select * into i from public.repuestos_items x where x.id = p_id;
  if found then
    if i.creado_por is distinct from (select auth.uid()) or i.proyecto_id <> p_proyecto then
      raise exception 'Ese identificador ya está en uso. Cierra el formulario y vuelve a abrirlo.' using errcode = '23505', hint = 'id';
    end if;
    return jsonb_build_object('id', i.id, 'actualizado_en', i.actualizado_en, 'fase_id', i.fase_id);
  end if;

  -- Antes de leer su estado: el `for update` de eliminar el proyecto espera a este ítem, o este ítem lo ve eliminado.
  select * into p from public.repuestos_proyectos x where x.id = p_proyecto for share;
  if not found or p.eliminado_en is not null then
    raise exception 'Este proyecto ya no existe.' using errcode = 'PT409', hint = 'conflicto';
  end if;
  if p.cerrado_en is not null then
    raise exception 'El proyecto está cerrado: reábrelo para sumar ítems.' using errcode = '23514', hint = 'proyecto';
  end if;

  if jsonb_typeof(v_datos) <> 'object' then
    raise exception 'Los datos del ítem no son válidos.' using errcode = '22023', hint = 'datos';
  end if;
  for k in select jsonb_object_keys(v_datos) loop
    if k <> all (array['descripcion', 'tipo_pieza_id', 'condicion_id', 'pais_origen_id', 'modo_transporte_id', 'cantidad', 'precio_cliente', 'moneda',
                       'tracking', 'notas']) then
      raise exception 'El dato «%» no es de un ítem.', k using errcode = '22023', hint = k;
    end if;
  end loop;
  v_desc := nullif(btrim(v_datos ->> 'descripcion'), '');
  if v_desc is null or char_length(v_desc) > 500 then
    raise exception 'Escribe qué repuesto es (hasta 500 caracteres).' using errcode = '22023', hint = 'descripcion';
  end if;
  begin
    v_cantidad := coalesce(nullif(btrim(v_datos ->> 'cantidad'), '')::integer, 1);
  exception when invalid_text_representation or numeric_value_out_of_range then
    v_cantidad := 0;
  end;
  if v_cantidad < 1 then
    raise exception 'La cantidad es un número entero desde 1.' using errcode = '22023', hint = 'cantidad';
  end if;
  begin
    v_precio := nullif(btrim(v_datos ->> 'precio_cliente'), '')::numeric(18, 2);
  exception when invalid_text_representation or numeric_value_out_of_range then
    raise exception 'El precio no es un número válido.' using errcode = '22023', hint = 'precio_cliente';
  end;
  if v_precio < 0 then
    raise exception 'El precio no puede ser negativo.' using errcode = '22023', hint = 'precio_cliente';
  end if;
  v_moneda := nullif(upper(btrim(v_datos ->> 'moneda')), '');
  if v_precio is not null and v_moneda is null then
    raise exception 'Elige la moneda del precio.' using errcode = '22023', hint = 'moneda';
  end if;
  if v_moneda is not null and not exists (select 1 from public.monedas m where m.codigo = v_moneda) then
    raise exception 'Esa moneda no existe.' using errcode = '22023', hint = 'moneda';
  end if;

  insert into public.repuestos_items (id, proyecto_id, descripcion, tipo_pieza_id, condicion_id, pais_origen_id, modo_transporte_id, cantidad,
    precio_cliente, moneda, tracking, notas, creado_por)
  values (p_id, p.id, v_desc,
    public._repuesto_catalogo(v_datos, 'tipo_pieza_id', 'tipo_pieza'),
    public._repuesto_catalogo(v_datos, 'condicion_id', 'condicion'),
    public._repuesto_catalogo(v_datos, 'pais_origen_id', 'pais_origen'),
    public._repuesto_catalogo(v_datos, 'modo_transporte_id', 'modo_transporte'),
    v_cantidad, v_precio, v_moneda, nullif(btrim(v_datos ->> 'tracking'), ''), nullif(btrim(v_datos ->> 'notas'), ''), (select auth.uid()))
  returning * into i;

  v_fase := public._repuesto_fase_de_entrada(i.id);
  if v_fase is not null then
    select f.flujo_id into v_flujo from public.fases f where f.id = v_fase;
    update public.repuestos_items x set fase_id = v_fase, fase_desde = now() where x.id = i.id returning * into i;
    insert into public.historial_fases (flujo_id, repuesto_id, de_fase_id, a_fase_id, usuario_id)
    values (v_flujo, i.id, null, v_fase, (select auth.uid()));
  end if;
  return jsonb_build_object('id', i.id, 'actualizado_en', i.actualizado_en, 'fase_id', i.fase_id);
end;
$$;


ALTER FUNCTION "public"."repuesto_item_crear"("p_id" "uuid", "p_proyecto" "uuid", "p_datos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repuesto_item_eliminar"("p_item" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare i public.repuestos_items; v_motivo text;
begin
  perform public.assert_permiso('repuestos.editar');
  select * into i from public.repuestos_items x where x.id = p_item for update;
  if not found or i.eliminado_en is not null
     or exists (select 1 from public.repuestos_proyectos pr where pr.id = i.proyecto_id and pr.eliminado_en is not null) then
    raise exception 'Este ítem ya no existe.' using errcode = 'PT409', hint = 'conflicto';
  end if;
  perform public._exigir_version(i.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este ítem. Recarga para ver lo nuevo.');

  if (select count(*) from (select 1 from public.historial_fases h where h.repuesto_id = i.id limit 2) h2) > 1
     or exists (select 1 from public.historial_fases h where h.repuesto_id = i.id and h.de_fase_id is not null) then
    v_motivo := 'Ya pasó por otra fase.';
  elsif exists (select 1 from public.documentos d where d.repuesto_id = i.id and d.eliminado_en is null) then
    v_motivo := 'Tiene documentos.';
  elsif exists (select 1 from public.repuestos_compras c where c.item_id = i.id and c.eliminado_en is null) then
    v_motivo := 'Tiene compras.';
  elsif exists (select 1 from public.gastos g where g.repuesto_id = i.id and g.eliminado_en is null) then
    v_motivo := 'Tiene gastos.';
  elsif i.stock_cantidad > 0 or i.en_stock_desde is not null
     or exists (select 1 from public.repuestos_stock_movimientos m where m.item_id = i.id) then
    v_motivo := 'Tiene movimientos de stock.';
  end if;
  if v_motivo is not null then
    raise exception '% Pásalo a stock o márcalo perdido.', v_motivo using errcode = '23514', hint = 'en_uso';
  end if;
  update public.repuestos_items x set eliminado_en = now() where x.id = i.id returning * into i;
  return jsonb_build_object('id', i.id, 'eliminado_en', i.eliminado_en);
end;
$$;


ALTER FUNCTION "public"."repuesto_item_eliminar"("p_item" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repuesto_proyecto_cerrar"("p_proyecto" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p public.repuestos_proyectos;
begin
  perform public.assert_permiso('repuestos.editar');
  p := public._repuesto_proyecto_tomar(p_proyecto, p_actualizado_en_esperado);
  if p.cerrado_en is not null then
    raise exception 'Este proyecto ya está cerrado.' using errcode = '23514', hint = 'estado';
  end if;
  update public.repuestos_proyectos x set cerrado_en = now() where x.id = p.id returning * into p;
  return jsonb_build_object('id', p.id, 'actualizado_en', p.actualizado_en, 'cerrado_en', p.cerrado_en);
end;
$$;


ALTER FUNCTION "public"."repuesto_proyecto_cerrar"("p_proyecto" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repuesto_proyecto_crear"("p_id" "uuid", "p_datos" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  p public.repuestos_proyectos;
  v_datos jsonb := coalesce(p_datos, '{}'::jsonb);
  k text;
  v_vehiculo uuid; v_lead uuid;
  v_etiqueta text; v_vin text; v_cliente text; v_telefono text; v_notas text;
begin
  if p_id is null then
    raise exception 'Falta el identificador del proyecto.' using errcode = '22023', hint = 'id';
  end if;
  perform public.assert_permiso('repuestos.editar');

  select * into p from public.repuestos_proyectos x where x.id = p_id;
  if found then
    if p.creado_por is distinct from (select auth.uid()) then
      raise exception 'Ese identificador ya está en uso. Cierra el formulario y vuelve a abrirlo.' using errcode = '23505', hint = 'id';
    end if;
    return jsonb_build_object('id', p.id, 'numero', p.numero, 'actualizado_en', p.actualizado_en);
  end if;

  if jsonb_typeof(v_datos) <> 'object' then
    raise exception 'Los datos del proyecto no son válidos.' using errcode = '22023', hint = 'datos';
  end if;
  for k in select jsonb_object_keys(v_datos) loop
    if k <> all (array['vehiculo_id', 'vehiculo_etiqueta', 'vin', 'lead_id', 'cliente_nombre', 'cliente_telefono', 'notas']) then
      raise exception 'El dato «%» no es de un proyecto.', k using errcode = '22023', hint = k;
    end if;
  end loop;
  begin
    v_vehiculo := nullif(btrim(v_datos ->> 'vehiculo_id'), '')::uuid;
  exception when invalid_text_representation then
    raise exception 'El vehículo no es válido.' using errcode = '22023', hint = 'vehiculo_id';
  end;
  begin
    v_lead := nullif(btrim(v_datos ->> 'lead_id'), '')::uuid;
  exception when invalid_text_representation then
    raise exception 'El lead no es válido.' using errcode = '22023', hint = 'lead_id';
  end;
  v_etiqueta := nullif(btrim(v_datos ->> 'vehiculo_etiqueta'), '');
  v_vin := nullif(btrim(v_datos ->> 'vin'), '');
  v_cliente := nullif(btrim(v_datos ->> 'cliente_nombre'), '');
  v_telefono := nullif(btrim(v_datos ->> 'cliente_telefono'), '');
  v_notas := nullif(btrim(v_datos ->> 'notas'), '');

  if v_vehiculo is not null then
    -- El mismo texto exista o no: no se revela un vehículo que no se ve.
    if not public.puede_vehiculo(v_vehiculo, 'vehiculos.ver') then
      raise exception 'No encontramos este vehículo o no tienes acceso.' using errcode = '42501', hint = 'vehiculo_id';
    end if;
    if v_etiqueta is not null or v_vin is not null then
      raise exception 'Un proyecto de un vehículo toma sus datos del vehículo.' using errcode = '22023', hint = 'vehiculo_etiqueta';
    end if;
  elsif v_etiqueta is null then
    raise exception 'Escribe qué vehículo es.' using errcode = '22023', hint = 'vehiculo_etiqueta';
  end if;

  begin
    insert into public.repuestos_proyectos (id, vehiculo_id, vehiculo_etiqueta, vin, lead_id, cliente_nombre, cliente_telefono, notas, creado_por)
    values (p_id, v_vehiculo, v_etiqueta, v_vin, v_lead, v_cliente, v_telefono, v_notas, (select auth.uid()))
    returning * into p;
  exception when unique_violation then
    raise exception 'Ese vehículo ya tiene un proyecto.' using errcode = '23505', hint = 'vehiculo_id';
  end;
  return jsonb_build_object('id', p.id, 'numero', p.numero, 'actualizado_en', p.actualizado_en);
end;
$$;


ALTER FUNCTION "public"."repuesto_proyecto_crear"("p_id" "uuid", "p_datos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repuesto_proyecto_eliminar"("p_proyecto" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p public.repuestos_proyectos;
begin
  perform public.assert_permiso('repuestos.editar');
  p := public._repuesto_proyecto_tomar(p_proyecto, p_actualizado_en_esperado);
  if exists (select 1 from public.repuestos_items i where i.proyecto_id = p.id and i.eliminado_en is null) then
    raise exception 'Tiene ítems: ciérralo en vez de eliminarlo.' using errcode = '23514', hint = 'en_uso';
  end if;
  if exists (select 1 from public.repuestos_compras c where c.proyecto_id = p.id and c.eliminado_en is null)
     or exists (select 1 from public.pagos g where g.proyecto_repuestos_id = p.id and g.eliminado_en is null)
     or exists (select 1 from public.repuestos_cotizaciones q where q.proyecto_id = p.id) then
    raise exception 'Tiene compras, pagos o cotizaciones: ciérralo en vez de eliminarlo.' using errcode = '23514', hint = 'en_uso';
  end if;
  update public.repuestos_proyectos x set eliminado_en = now() where x.id = p.id returning * into p;
  return jsonb_build_object('id', p.id, 'eliminado_en', p.eliminado_en);
end;
$$;


