CREATE OR REPLACE FUNCTION "public"."repuesto_stock_mover"("p_item" "uuid", "p_unidades" integer, "p_motivo" "text", "p_stock_esperado" integer, "p_nota" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i public.repuestos_items;
  v_nota text := nullif(btrim(p_nota), '');
  v_disponible integer;
begin
  perform public.assert_permiso('repuestos.editar');
  if p_motivo = 'reasignado' then
    raise exception 'Para reasignar usa «Reasignar a un proyecto».' using errcode = '22023', hint = 'motivo';
  end if;
  if p_motivo is null or p_motivo not in ('sobrante', 'vendido', 'devuelto', 'ajuste') then
    raise exception 'Ese motivo no existe.' using errcode = '22023', hint = 'motivo';
  end if;
  if p_unidades is null or p_unidades < 1 then
    raise exception 'La cantidad es un número entero desde 1.' using errcode = '22023', hint = 'cantidad';
  end if;
  if p_stock_esperado is null or p_stock_esperado < 0 then
    raise exception 'Falta el stock que viste.' using errcode = '22023', hint = 'stock_esperado';
  end if;
  if char_length(v_nota) > 500 then
    raise exception 'La nota admite hasta 500 caracteres.' using errcode = '22023', hint = 'nota';
  end if;

  i := public._repuesto_stock_item(p_item);
  if i.stock_cantidad <> p_stock_esperado then
    raise exception 'Otra persona movió el stock de este ítem. Recarga para ver lo nuevo.' using errcode = 'PT409', hint = 'conflicto';
  end if;

  if p_motivo = 'sobrante' then
    -- repuestos_stock_movimientos_item_id_idx: (item_id). Un ítem tiene pocos movimientos.
    select i.cantidad - coalesce(sum(m.cantidad), 0) into v_disponible
      from public.repuestos_stock_movimientos m where m.item_id = i.id and m.motivo = 'sobrante';
    v_disponible := greatest(v_disponible, 0);
    if v_disponible = 0 then
      raise exception 'Este ítem ya pasó todo a stock.' using errcode = '23514', hint = 'cantidad';
    end if;
    if p_unidades > v_disponible then
      raise exception 'Sólo puedes pasar % más de este ítem a stock.', v_disponible using errcode = '23514', hint = 'cantidad';
    end if;
    return public._repuesto_stock_aplicar(i, p_unidades, p_motivo, v_nota);
  end if;

  if p_unidades > i.stock_cantidad then
    raise exception 'Sólo hay % en stock.', i.stock_cantidad using errcode = '23514', hint = 'cantidad';
  end if;
  return public._repuesto_stock_aplicar(i, -p_unidades, p_motivo, v_nota);
end;
$$;


ALTER FUNCTION "public"."repuesto_stock_mover"("p_item" "uuid", "p_unidades" integer, "p_motivo" "text", "p_stock_esperado" integer, "p_nota" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."repuesto_stock_mover"("p_item" "uuid", "p_unidades" integer, "p_motivo" "text", "p_stock_esperado" integer, "p_nota" "text") IS 'Mueve el stock de un ítem de repuestos (8.10-1, C2): sobrante entra con tope; vendido, devuelto y ajuste salen; nunca negativo; PT409 si el stock cambió.';



CREATE OR REPLACE FUNCTION "public"."repuesto_stock_reasignar"("p_item" "uuid", "p_proyecto_destino" "uuid", "p_unidades" integer, "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  i public.repuestos_items;
  n public.repuestos_items;
  p public.repuestos_proyectos;
  v_origen jsonb;
  v_fase uuid; v_flujo uuid;
begin
  perform public.assert_permiso('repuestos.editar');
  if p_id is null then
    raise exception 'Falta el identificador del ítem.' using errcode = '22023', hint = 'id';
  end if;
  if p_proyecto_destino is null then
    raise exception 'Elige el proyecto destino.' using errcode = '22023', hint = 'proyecto';
  end if;
  if p_unidades is null or p_unidades < 1 then
    raise exception 'La cantidad es un número entero desde 1.' using errcode = '22023', hint = 'cantidad';
  end if;

  -- El candado antes de la idempotencia: dos llamadas con el mismo id se ordenan aquí y la segunda ve el ítem de la primera.
  i := public._repuesto_stock_item(p_item);

  select * into n from public.repuestos_items x where x.id = p_id;
  if found then
    if n.creado_por is distinct from (select auth.uid()) or n.proyecto_id <> p_proyecto_destino then
      raise exception 'Ese identificador ya está en uso. Cierra el formulario y vuelve a abrirlo.' using errcode = '23505', hint = 'id';
    end if;
    return jsonb_build_object('id', n.id, 'proyecto_id', n.proyecto_id, 'fase_id', n.fase_id,
      'origen', jsonb_build_object('item_id', i.id, 'stock_cantidad', i.stock_cantidad, 'en_stock_desde', i.en_stock_desde,
        'actualizado_en', i.actualizado_en));
  end if;

  if p_proyecto_destino = i.proyecto_id then
    raise exception 'Elige otro proyecto: el ítem ya es de este.' using errcode = '23514', hint = 'proyecto';
  end if;
  -- Como al crear un ítem: el `for update` de eliminar el proyecto espera, o este lo ve eliminado.
  select * into p from public.repuestos_proyectos x where x.id = p_proyecto_destino for share;
  if not found or p.eliminado_en is not null then
    raise exception 'Ese proyecto ya no existe.' using errcode = 'PT409', hint = 'proyecto';
  end if;
  if p.cerrado_en is not null then
    raise exception 'El proyecto destino está cerrado: reábrelo para sumar ítems.' using errcode = '23514', hint = 'proyecto';
  end if;
  if p_unidades > i.stock_cantidad then
    raise exception 'Sólo hay % en stock.', i.stock_cantidad using errcode = '23514', hint = 'cantidad';
  end if;

  v_origen := public._repuesto_stock_aplicar(i, -p_unidades, 'reasignado', format('Al proyecto #%s.', p.numero)) - 'movimiento_id';

  insert into public.repuestos_items (id, proyecto_id, descripcion, tipo_pieza_id, condicion_id, pais_origen_id, modo_transporte_id, cantidad,
    notas, creado_por)
  values (p_id, p.id, i.descripcion, i.tipo_pieza_id, i.condicion_id, i.pais_origen_id, i.modo_transporte_id, p_unidades,
    format('Reasignado desde el proyecto #%s.', (select pr.numero from public.repuestos_proyectos pr where pr.id = i.proyecto_id)),
    (select auth.uid()))
  returning * into n;

  v_fase := public._repuesto_fase_de_entrada(n.id);
  if v_fase is not null then
    select f.flujo_id into v_flujo from public.fases f where f.id = v_fase;
    update public.repuestos_items x set fase_id = v_fase, fase_desde = now() where x.id = n.id returning * into n;
    insert into public.historial_fases (flujo_id, repuesto_id, de_fase_id, a_fase_id, usuario_id)
    values (v_flujo, n.id, null, v_fase, (select auth.uid()));
  end if;
  return jsonb_build_object('id', n.id, 'proyecto_id', n.proyecto_id, 'fase_id', n.fase_id, 'origen', v_origen);
end;
$$;


ALTER FUNCTION "public"."repuesto_stock_reasignar"("p_item" "uuid", "p_proyecto_destino" "uuid", "p_unidades" integer, "p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."repuesto_stock_reasignar"("p_item" "uuid", "p_proyecto_destino" "uuid", "p_unidades" integer, "p_id" "uuid") IS 'Reasigna stock de un ítem a otro proyecto abierto (8.10-1, C3): todo o nada, idempotente por el id del ítem nuevo.';



CREATE OR REPLACE FUNCTION "public"."repuestos_catalogo_sin_uso"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_en_uso boolean;
begin
  v_en_uso := case old.catalogo
    when 'tipo_pieza' then exists (select 1 from public.repuestos_items i where i.tipo_pieza_id = old.id)
                        or exists (select 1 from public.repuestos_cotizaciones_lineas l where l.tipo_pieza_id = old.id)
    when 'condicion' then exists (select 1 from public.repuestos_items i where i.condicion_id = old.id)
                       or exists (select 1 from public.repuestos_cotizaciones_lineas l where l.condicion_id = old.id)
    when 'pais_origen' then exists (select 1 from public.repuestos_items i where i.pais_origen_id = old.id)
    when 'modo_transporte' then exists (select 1 from public.repuestos_items i where i.modo_transporte_id = old.id)
    else false
  end;
  if v_en_uso then
    raise exception '“%” está en uso: desactívalo para que no se elija más.', old.nombre using errcode = '23514', hint = 'en_uso';
  end if;
  return old;
end;
$$;


ALTER FUNCTION "public"."repuestos_catalogo_sin_uso"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repuestos_cotizacion_aceptar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.repuestos_cotizaciones; v_anulada uuid; v_items integer;
begin
  perform public.assert_permiso('repuestos.cotizar');
  perform public.assert_permiso('repuestos.ver');
  perform public.assert_permiso('repuestos.editar');
  c := public._repuesto_cotizacion_para_cambiar(p_id, p_actualizado_en_esperado);
  if not exists (select 1 from public.repuestos_cotizaciones_lineas l where l.cotizacion_id = p_id)
     or exists (select 1 from public.repuestos_cotizaciones_lineas l where l.cotizacion_id = p_id and l.total is null) then
    raise exception 'Para aceptarla, cada línea necesita su total.' using errcode = '23514', hint = 'lineas';
  end if;

  update public.repuestos_cotizaciones x set estado = 'anulada'
   where x.proyecto_id = c.proyecto_id and x.estado = 'aceptada' and x.id <> p_id
  returning x.id into v_anulada;
  begin
    update public.repuestos_cotizaciones x set estado = 'aceptada', aceptada_en = now() where x.id = p_id returning * into c;
  exception when unique_violation then
    raise exception 'Otra cotización de este proyecto se aceptó recién. Recarga para verla.' using errcode = 'PT409', hint = 'conflicto';
  end;

  -- D2, D11 · el unitario (exacto: el total es unitario × cantidad) a cada ítem vivo, tomados en orden de id como en `guardar`.
  perform 1 from public.repuestos_items x
   where x.id in (select l.item_id from public.repuestos_cotizaciones_lineas l where l.cotizacion_id = p_id) and x.eliminado_en is null
   order by x.id for update;
  update public.repuestos_items x set precio_cliente = l.total / l.cantidad, moneda = c.moneda
    from public.repuestos_cotizaciones_lineas l
   where l.cotizacion_id = p_id and l.item_id = x.id and x.eliminado_en is null;
  get diagnostics v_items = row_count;

  return jsonb_build_object('id', c.id, 'actualizado_en', c.actualizado_en, 'aceptada_en', c.aceptada_en, 'anulada', v_anulada, 'items', v_items);
end;
$$;


ALTER FUNCTION "public"."repuestos_cotizacion_aceptar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repuestos_cotizacion_anular"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare c public.repuestos_cotizaciones;
begin
  perform public.assert_permiso('repuestos.cotizar');
  perform public.assert_permiso('repuestos.ver');
  select * into c from public.repuestos_cotizaciones x where x.id = p_id for update;
  if not found then
    raise exception 'Esta cotización ya no existe.' using errcode = 'PT409', hint = 'conflicto';
  end if;
  perform public._repuesto_cotizacion_proyecto(c.proyecto_id);
  perform public._exigir_version(c.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió esta cotización. Recarga para ver lo nuevo.');
  if c.estado = 'anulada' then
    raise exception 'Esta cotización ya está anulada.' using errcode = '23514', hint = 'estado';
  end if;
  update public.repuestos_cotizaciones x set estado = 'anulada' where x.id = p_id returning * into c;
  return jsonb_build_object('id', c.id, 'actualizado_en', c.actualizado_en, 'estado', c.estado);
end;
$$;


ALTER FUNCTION "public"."repuestos_cotizacion_anular"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repuestos_cotizacion_crear"("p_id" "uuid", "p_proyecto" "uuid", "p_moneda" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.repuestos_cotizaciones; k public.repuestos_cotizador_config; v_moneda text := nullif(upper(btrim(p_moneda)), ''); v_snap jsonb;
begin
  perform public.assert_permiso('repuestos.cotizar');
  perform public.assert_permiso('repuestos.ver');
  if p_id is null then
    raise exception 'Falta el identificador de la cotización.' using errcode = '23502', hint = 'id';
  end if;
  if p_proyecto is null then
    raise exception 'Falta el proyecto de la cotización.' using errcode = '23502', hint = 'proyecto_id';
  end if;
  select * into c from public.repuestos_cotizaciones x where x.id = p_id;
  if not found then
    perform public._repuesto_cotizacion_proyecto(p_proyecto);
    if v_moneda is null or not exists (select 1 from public.monedas m where m.codigo::text = v_moneda and m.activa) then
      raise exception 'Elige una moneda activa.' using errcode = '22023', hint = 'moneda';
    end if;
    select * into k from public.repuestos_cotizador_config x order by x.id desc limit 1;
    if not found then
      raise exception 'Todavía no hay configuración del cotizador: publícala en Configuración › Repuestos.' using errcode = '23514', hint = 'config';
    end if;
    v_snap := jsonb_build_object(
      'version', 1,
      'moneda', v_moneda,
      'config', jsonb_build_object('id', k.id, 'factor_importado', k.factor_importado::text, 'recargo_local', k.recargo_local::text,
                                   'redondeo', k.redondeo::text, 'vigente_desde', k.vigente_desde),
      'tramos', coalesce((select jsonb_agg(jsonb_build_object('costo_min', t.costo_min::text, 'costo_max', t.costo_max::text, 'monto', t.monto::text)
                                           order by t.costo_min)
                            from public.repuestos_tramos_logistica t where t.moneda::text = v_moneda and t.activo), '[]'::jsonb),
      'cajas', coalesce((select jsonb_agg(jsonb_build_object('id', b.id, 'monto', b.monto::text) order by b.monto, b.id)
                           from public.repuestos_cajas b where b.moneda::text = v_moneda and b.activa), '[]'::jsonb));
    insert into public.repuestos_cotizaciones (id, proyecto_id, moneda, estado, config_snapshot, total, creado_por)
    values (p_id, p_proyecto, v_moneda, 'borrador', v_snap, null, (select auth.uid()))
    on conflict (id) do nothing
    returning * into c;
    if found then
      return public._repuesto_cotizacion_respuesta(c, false);
    end if;
    select * into c from public.repuestos_cotizaciones x where x.id = p_id;
  end if;
  -- Un reintento con el mismo id devuelve la que ya está y nunca pisa.
  if c.proyecto_id is distinct from p_proyecto or btrim(c.moneda) is distinct from v_moneda then
    raise exception 'Ese id ya es de otra cotización.' using errcode = '23505', hint = 'id';
  end if;
  return public._repuesto_cotizacion_respuesta(c, true);
end;
$$;


ALTER FUNCTION "public"."repuestos_cotizacion_crear"("p_id" "uuid", "p_proyecto" "uuid", "p_moneda" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repuestos_cotizacion_guardar"("p_id" "uuid", "p_lineas" "jsonb", "p_notas" "text", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c public.repuestos_cotizaciones; l public.repuestos_cotizaciones_lineas;
  v_filas public.repuestos_cotizaciones_lineas[] := '{}'::public.repuestos_cotizaciones_lineas[];
  v_faltas text[] := '{}'::text[]; v_items uuid[] := '{}'::uuid[]; v_vivos uuid[]; v_ids uuid[] := '{}'::uuid[]; v_r jsonb;
  v_notas text := nullif(btrim(p_notas), ''); v_e text; v_m text; v_h text; v_total numeric; v_res jsonb := '[]'::jsonb;
begin
  perform public.assert_permiso('repuestos.cotizar');
  perform public.assert_permiso('repuestos.ver');
  c := public._repuesto_cotizacion_para_cambiar(p_id, p_actualizado_en_esperado);
  if p_lineas is null or jsonb_typeof(p_lineas) <> 'array' then
    raise exception 'Las líneas van como una lista.' using errcode = '22023', hint = 'lineas';
  end if;
  if jsonb_array_length(p_lineas) > 200 then
    raise exception 'Una cotización lleva como mucho 200 líneas.' using errcode = '22023', hint = 'lineas';
  end if;
  if char_length(v_notas) > 2000 then
    raise exception 'Las notas van en 2000 caracteres como mucho.' using errcode = '22023', hint = 'notas';
  end if;

  -- C12–C13 · cada línea validada y calculada; su error dice qué línea es.
  for v_n in 1 .. jsonb_array_length(p_lineas) loop
    begin
      l := public._repuesto_cotizacion_linea_de(p_lineas -> (v_n - 1), p_id, v_n, c.config_snapshot);
      if l.id = any (v_ids) then
        raise exception 'esa línea está repetida.' using errcode = '22023', hint = 'id';
      end if;
      if l.item_id is not null and l.item_id = any (v_items) then
        raise exception 'ese ítem ya está en otra línea.' using errcode = '22023', hint = 'item_id';
      end if;
      v_r := public._repuesto_cotizacion_linea(c.config_snapshot, l.bloque, l.cantidad, l.costo, l.logistica, l.caja);
      if v_r ->> 'falta' = 'no_cabe' then
        raise exception 'el total no cabe: revisa la cantidad y el costo.' using errcode = '22023', hint = 'cantidad';
      end if;
    exception when others then
      get stacked diagnostics v_e = returned_sqlstate, v_m = message_text, v_h = pg_exception_hint;
      raise exception using message = format('Línea %s: %s', v_n, v_m), errcode = v_e, hint = coalesce(v_h, ''),
                            detail = coalesce(nullif(btrim(p_lineas -> (v_n - 1) ->> 'id'), ''), '');
    end;
    l.logistica_sugerida := (v_r ->> 'logistica_sugerida')::numeric;
    l.total := (v_r ->> 'total')::numeric;
    v_ids := v_ids || l.id;
    if l.item_id is not null then
      v_items := v_items || l.item_id;
    end if;
    v_filas := v_filas || l;
    v_faltas := v_faltas || (v_r ->> 'falta');
  end loop;

  -- C12 · los ítems, del mismo proyecto y vivos, tomados `for share` en orden de id (sin cruzarse con `aceptar`) en una sola consulta.
  select coalesce(array_agg(x.id), '{}') into v_vivos
    from (select x.id from public.repuestos_items x
           where x.id = any (v_items) and x.proyecto_id = c.proyecto_id and x.eliminado_en is null
           order by x.id for share) x;
  if cardinality(v_vivos) <> cardinality(v_items) then
    for i in 1 .. cardinality(v_filas) loop
      if v_filas[i].item_id is not null and not (v_filas[i].item_id = any (v_vivos)) then
        raise exception 'Línea %: ese ítem no es de este proyecto.', i using errcode = '22023', hint = 'item_id', detail = v_filas[i].id::text;
      end if;
    end loop;
  end if;

  delete from public.repuestos_cotizaciones_lineas x where x.cotizacion_id = p_id;
  begin
    insert into public.repuestos_cotizaciones_lineas select * from unnest(v_filas);
  exception when unique_violation then
    raise exception 'Una línea tiene el id de otra cotización.' using errcode = '23505', hint = 'id';
  end;

  -- D6 · el total es la suma si todas las líneas tienen total y hay al menos una; si no, nulo.
  if cardinality(v_filas) > 0 and not exists (select 1 from unnest(v_filas) f where f.total is null) then
    select sum(f.total) into v_total from unnest(v_filas) f;
  end if;
  update public.repuestos_cotizaciones x set total = v_total, notas = v_notas where x.id = p_id returning * into c;

  for i in 1 .. cardinality(v_filas) loop
    v_res := v_res || jsonb_build_array(jsonb_build_object('id', v_filas[i].id, 'logistica_sugerida', v_filas[i].logistica_sugerida::text,
                                                           'total', v_filas[i].total::text, 'falta', v_faltas[i]));
  end loop;
  return jsonb_build_object('id', c.id, 'actualizado_en', c.actualizado_en, 'total', c.total::text, 'lineas', v_res);
end;
$$;


ALTER FUNCTION "public"."repuestos_cotizacion_guardar"("p_id" "uuid", "p_lineas" "jsonb", "p_notas" "text", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


