CREATE OR REPLACE FUNCTION "public"."repuestos_imagen_integridad"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  i public.repuestos_items;
  p public.repuestos_proyectos;
  v_patron text := '^' || new.item_id::text || '/[0-9a-f]{64}\.(webp|jpg)$';
begin
  -- El ítem y su proyecto se leen `for share`: eliminar el ítem (`for update`) espera a esta imagen, o esta imagen lo ve eliminado.
  select * into i from public.repuestos_items x where x.id = new.item_id for share;
  if found then
    select * into p from public.repuestos_proyectos x where x.id = i.proyecto_id for share;
  end if;
  if i.id is null or i.eliminado_en is not null or p.id is null or p.eliminado_en is not null then
    raise exception 'Este ítem ya no existe.' using errcode = '23514', hint = 'item';
  end if;
  if p.cerrado_en is not null then
    raise exception 'El proyecto está cerrado: reábrelo para cambiar las imágenes.' using errcode = '23514', hint = 'proyecto';
  end if;
  if new.ruta !~ v_patron then
    raise exception 'La imagen no está en la carpeta de este ítem.' using errcode = '23514', hint = 'ruta';
  end if;

  -- El tope, bajo un candado por ítem: dos imágenes a la vez no pasan de 8. Conteo acotado: nunca recorre más de 8 filas (índice por `item_id`).
  perform pg_advisory_xact_lock(hashtextextended('repuestos_imagenes:' || new.item_id::text, 0));
  if (select count(*) from (select 1 from public.repuestos_items_imagenes m where m.item_id = new.item_id limit 8) t) >= 8 then
    raise exception 'Un ítem lleva hasta 8 imágenes.' using errcode = '23514', hint = 'imagenes';
  end if;

  -- «Deshacer» de quitar: la ruta sale de la cola de limpieza (falla con su mensaje si la limpieza ya la reclamó).
  perform public.storage_gc_rescatar('repuestos', new.ruta);
  if not exists (select 1 from storage.objects o where o.bucket_id = 'repuestos' and o.name = new.ruta) then
    raise exception 'La imagen no terminó de subir. Vuelve a intentarlo.' using errcode = '23514', hint = 'ruta';
  end if;

  new.orden := coalesce((select max(m.orden) + 1 from public.repuestos_items_imagenes m where m.item_id = new.item_id), 0);
  return new;
end;
$_$;


ALTER FUNCTION "public"."repuestos_imagen_integridad"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repuestos_pendientes_de_vehiculo"("p_vehiculo" "uuid", "p_tope" integer DEFAULT NULL::integer) RETURNS TABLE("item_id" "uuid", "descripcion" "text", "proyecto_id" "uuid", "proyecto_numero" bigint, "fase_id" "uuid", "fase_nombre" "text", "requisito_id" "uuid", "fase_destino_id" "uuid", "fase_destino_nombre" "text", "espera_fase_id" "uuid", "espera_fase_nombre" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  v_n integer := public._acotar_pagina(p_tope, 50, 200) + 1;
  v public.vehiculos;
  v_flujo uuid;
  v_ve_flujo boolean;
begin
  perform public.assert_activo();
  select * into v from public.vehiculos x where x.id = p_vehiculo and x.eliminado_en is null;
  if not found then
    return;
  end if;
  v_ve_flujo := public.puede_vehiculo(v.id, 'logistica.ver');
  if not v_ve_flujo and not public.tiene_permiso('repuestos.ver') then
    return;
  end if;
  select fl.id into v_flujo from public.flujos fl where fl.origen_id = v.origen_id and fl.ambito = 'vehiculos';

  return query
    with esperas as (
      select q.id as requisito_id, q.fase_id as destino, q.espera_fase_id
        from public.fases_requisitos q
       where q.tipo = 'espera' and q.espera_ambito = 'hijos'
         and q.fase_id in (
           select t.a_fase_id from public.fases_transiciones t where v.fase_id is not null and t.de_fase_id = v.fase_id
           union
           select fa.id from public.fases fa where v.fase_id is null and fa.flujo_id = v_flujo and fa.es_inicial and fa.activa)
    )
    select i.id, i.descripcion, pr.id, pr.numero, i.fase_id, fi.nombre, e.requisito_id,
           e.destino, case when v_ve_flujo then fd.nombre end,
           e.espera_fase_id, case when v_ve_flujo then fe.nombre end
      from public.repuestos_proyectos pr
      join public.repuestos_items i on i.proyecto_id = pr.id and i.eliminado_en is null and i.en_stock_desde is null
      cross join esperas e
      left join public.fases fi on fi.id = i.fase_id
      left join public.fases fd on fd.id = e.destino
      left join public.fases fe on fe.id = e.espera_fase_id
     where pr.vehiculo_id = v.id and pr.eliminado_en is null
       and public._repuesto_ante_espera(i.id, e.espera_fase_id) = 'pendiente'
     order by i.creado_en, i.id, e.requisito_id
     limit v_n;
end;
$$;


ALTER FUNCTION "public"."repuestos_pendientes_de_vehiculo"("p_vehiculo" "uuid", "p_tope" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."repuestos_pendientes_de_vehiculo"("p_vehiculo" "uuid", "p_tope" integer) IS 'Los ítems de repuestos que las esperas de las fases siguientes de un vehículo aguardan (8.08-1, C11): repuestos.ver o logistica.ver del vehículo.';



CREATE OR REPLACE FUNCTION "public"."repuestos_proyecto_margen"("p_proyecto" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_sin integer; v_monedas jsonb;
begin
  perform public.assert_permiso('repuestos.costos.ver');
  perform public.assert_permiso('repuestos.ver');
  if not exists (select 1 from public.repuestos_proyectos p where p.id = p_proyecto and p.eliminado_en is null) then
    raise exception 'Este proyecto ya no existe.' using errcode = 'PT409', hint = 'conflicto';
  end if;

  -- Los ítems por `repuestos_items_proyecto_id_idx`, con tope: 201 quiere decir «más de 200».
  select count(*)::integer into v_sin
    from (select 1
            from public.repuestos_items i
           where i.proyecto_id = p_proyecto and i.eliminado_en is null and (i.precio_cliente is null or i.moneda is null)
           limit 201) s;

  -- Las compras por `repuestos_compras_proyecto_id_idx`.
  select coalesce(jsonb_agg(jsonb_build_object('moneda', m.moneda, 'precios', m.precios, 'compras', m.compras,
                                               'margen', case when v_sin > 0 then null else m.precios - m.compras end)
                            order by m.moneda), '[]'::jsonb)
    into v_monedas
    from (select coalesce(pr.moneda, co.moneda) as moneda, coalesce(pr.total, 0) as precios, coalesce(co.total, 0) as compras
            from (select i.moneda::text as moneda, sum(i.cantidad * i.precio_cliente) as total
                    from public.repuestos_items i
                   where i.proyecto_id = p_proyecto and i.eliminado_en is null and i.precio_cliente is not null and i.moneda is not null
                   group by i.moneda) pr
            full join (select c.moneda::text as moneda, sum(c.monto) as total
                         from public.repuestos_compras c
                        where c.proyecto_id = p_proyecto and c.eliminado_en is null
                        group by c.moneda) co on co.moneda = pr.moneda) m;

  return jsonb_build_object('sin_precio', v_sin, 'monedas', v_monedas);
end;
$$;


ALTER FUNCTION "public"."repuestos_proyecto_margen"("p_proyecto" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."repuestos_proyectos_listar"("p_cursor" bigint, "p_tamano" integer, "p_q" "text", "p_estado" "text") RETURNS TABLE("id" "uuid", "numero" bigint, "vehiculo_id" "uuid", "vehiculo_titulo" "text", "vehiculo_etiqueta" "text", "vin" "text", "cliente_nombre" "text", "cerrado_en" timestamp with time zone, "items" integer, "pendientes" integer, "en_stock" integer, "terminados" integer, "ultima_actividad" timestamp with time zone, "actualizado_en" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
#variable_conflict use_column
declare
  -- TAMANO_DE_PAGINA_POR_DEFECTO (50), máximo 100, más una para saber si hay otra.
  v_n integer := public._acotar_pagina(p_tamano, 50, 100) + 1;
  v_q text := nullif(btrim(p_q), '');
  v_numero bigint;
  v_patron text;
  v_ids uuid[];
begin
  perform public.assert_activo();
  if p_estado is not null and p_estado not in ('abiertos', 'cerrados') then
    raise exception 'El estado de la lista no es válido.' using errcode = '22023', hint = 'estado';
  end if;
  if not public.tiene_permiso('repuestos.ver') then
    return;
  end if;
  if v_q ~ '^[0-9]{1,18}$' then
    v_numero := v_q::bigint;
  end if;
  if v_q is not null and (v_numero is not null or char_length(v_q) >= 3) then
    v_patron := '%' || replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  end if;

  -- repuestos_proyectos_numero_key: (numero). El cursor queda como condición de índice; estado y texto, como filtro.
  if p_cursor is null then
    select array_agg(x.id order by x.numero desc) into v_ids
    from (
      select p.id, p.numero from public.repuestos_proyectos p
      where p.eliminado_en is null
        and (p_estado is null or (p_estado = 'cerrados') = (p.cerrado_en is not null))
        and (v_patron is null or p.numero = v_numero or p.vehiculo_etiqueta ilike v_patron or p.vin ilike v_patron or p.cliente_nombre ilike v_patron)
      order by p.numero desc
      limit v_n
    ) x;
  else
    select array_agg(x.id order by x.numero desc) into v_ids
    from (
      select p.id, p.numero from public.repuestos_proyectos p
      where p.numero < p_cursor and p.eliminado_en is null
        and (p_estado is null or (p_estado = 'cerrados') = (p.cerrado_en is not null))
        and (v_patron is null or p.numero = v_numero or p.vehiculo_etiqueta ilike v_patron or p.vin ilike v_patron or p.cliente_nombre ilike v_patron)
      order by p.numero desc
      limit v_n
    ) x;
  end if;
  if v_ids is null then
    return;
  end if;

  return query
    select p.id, p.numero, p.vehiculo_id,
           case when p.vehiculo_id is not null and public.puede_vehiculo(p.vehiculo_id, 'vehiculos.ver') then v.titulo end,
           p.vehiculo_etiqueta, p.vin, p.cliente_nombre, p.cerrado_en,
           coalesce(c.items, 0)::integer,
           (coalesce(c.items, 0) - coalesce(c.en_stock, 0) - coalesce(c.terminados, 0))::integer,
           coalesce(c.en_stock, 0)::integer,
           coalesce(c.terminados, 0)::integer,
           greatest(p.actualizado_en, c.ultima),
           p.actualizado_en
      from unnest(v_ids) with ordinality as u(id, n)
      join public.repuestos_proyectos p on p.id = u.id
      left join public.vehiculos v on v.id = p.vehiculo_id
      left join lateral (
        select count(*) as items,
               count(*) filter (where i.en_stock_desde is not null) as en_stock,
               count(*) filter (where i.en_stock_desde is null and f.es_final) as terminados,
               max(i.actualizado_en) as ultima
          from (select i2.fase_id, i2.en_stock_desde, i2.actualizado_en
                  from public.repuestos_items i2
                 where i2.proyecto_id = p.id and i2.eliminado_en is null
                 limit 201) i
          left join public.fases f on f.id = i.fase_id
      ) c on true
     order by u.n;
end;
$_$;


ALTER FUNCTION "public"."repuestos_proyectos_listar"("p_cursor" bigint, "p_tamano" integer, "p_q" "text", "p_estado" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."repuestos_proyectos_listar"("p_cursor" bigint, "p_tamano" integer, "p_q" "text", "p_estado" "text") IS 'La lista de proyectos de repuestos (8.08-1, C9): por cursor sobre numero desc, sólo vivos, con las cuentas de hasta 201 ítems por proyecto; vacía sin repuestos.ver.';



CREATE OR REPLACE FUNCTION "public"."repuestos_stock_listar"("p_cursor_en" timestamp with time zone, "p_cursor_id" "uuid", "p_tamano" integer) RETURNS TABLE("id" "uuid", "descripcion" "text", "stock_cantidad" integer, "en_stock_desde" timestamp with time zone, "proyecto_id" "uuid", "proyecto_numero" bigint, "proyecto_cerrado_en" timestamp with time zone, "vehiculo_id" "uuid", "vehiculo_titulo" "text", "vehiculo_etiqueta" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  -- TAMANO_DE_PAGINA_POR_DEFECTO (50), máximo 100, más una para saber si hay otra.
  v_n integer := public._acotar_pagina(p_tamano, 50, 100) + 1;
  v_ids uuid[];
begin
  perform public.assert_activo();
  if (p_cursor_en is null) <> (p_cursor_id is null) then
    raise exception 'El cursor de la lista no es válido.' using errcode = '22023', hint = 'cursor';
  end if;
  if not public.tiene_permiso('repuestos.ver') then
    return;
  end if;

  -- repuestos_items_en_stock_idx: (en_stock_desde desc, id desc) where en_stock_desde is not null and eliminado_en is null.
  if p_cursor_en is null then
    select array_agg(x.id order by x.en_stock_desde desc, x.id desc) into v_ids
    from (
      select i.id, i.en_stock_desde from public.repuestos_items i
      where i.en_stock_desde is not null and i.eliminado_en is null
      order by i.en_stock_desde desc, i.id desc
      limit v_n
    ) x;
  else
    select array_agg(x.id order by x.en_stock_desde desc, x.id desc) into v_ids
    from (
      select i.id, i.en_stock_desde from public.repuestos_items i
      where i.en_stock_desde is not null and i.eliminado_en is null
        and (i.en_stock_desde, i.id) < (p_cursor_en, p_cursor_id)
      order by i.en_stock_desde desc, i.id desc
      limit v_n
    ) x;
  end if;
  if v_ids is null then
    return;
  end if;

  return query
    select i.id, i.descripcion, i.stock_cantidad, i.en_stock_desde, p.id, p.numero, p.cerrado_en, p.vehiculo_id,
           case when p.vehiculo_id is not null and public.puede_vehiculo(p.vehiculo_id, 'vehiculos.ver') then v.titulo end,
           p.vehiculo_etiqueta
      from unnest(v_ids) with ordinality as u(id, n)
      join public.repuestos_items i on i.id = u.id
      join public.repuestos_proyectos p on p.id = i.proyecto_id
      left join public.vehiculos v on v.id = p.vehiculo_id
     order by u.n;
end;
$$;


ALTER FUNCTION "public"."repuestos_stock_listar"("p_cursor_en" timestamp with time zone, "p_cursor_id" "uuid", "p_tamano" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."repuestos_stock_listar"("p_cursor_en" timestamp with time zone, "p_cursor_id" "uuid", "p_tamano" integer) IS 'El stock de repuestos (8.10-1, C4): ítems vivos en stock por cursor (en_stock_desde desc, id desc), la página más una; vacía sin repuestos.ver.';



CREATE OR REPLACE FUNCTION "public"."requisito_crear"("p_id" "uuid", "p_fase" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_tipo" "public"."tipo_requisito", "p_datos" "jsonb") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.fases_requisitos;
  v_flujo uuid;
  v_ambito public.ambito_flujo;
  v_restriccion text;
begin
  if p_id is null then
    raise exception 'Falta el id del requisito.' using errcode = '22023', hint = 'id';
  end if;
  if p_tipo is null then
    raise exception 'Falta el tipo del requisito.' using errcode = '22023', hint = 'tipo';
  end if;
  perform public._requisito_forma(p_tipo, p_datos, true);
  select flujo_id into v_flujo from public.fases where id = p_fase;
  if v_flujo is null then
    raise exception 'Esta fase ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  perform public._flujo_para_editar(v_flujo, p_actualizado_en_esperado);
  select fl.ambito into v_ambito from public.fases f join public.flujos fl on fl.id = f.flujo_id where f.id = p_fase;
  if not found then
    raise exception 'Esta fase ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;

  v.id := p_id;
  v.fase_id := p_fase;
  v.tipo := p_tipo;
  v.bloqueante := false;
  v.config := '{}'::jsonb;
  v.orden := (select coalesce(max(r.orden), 0) + 10 from public.fases_requisitos r where r.fase_id = p_fase);
  if p_tipo = 'espera' then
    v.espera_ambito := case v_ambito when 'vehiculos' then 'hijos'::public.ambito_espera else 'padre'::public.ambito_espera end;
  end if;
  v := public._requisito_aplicar(v, p_datos);
  perform public._requisito_validar(v, array(select jsonb_object_keys(p_datos)));

  if p_tipo = 'documento' and not exists (select 1 from public.tipos_documento where id = v.tipo_documento_id) then
    raise exception 'Ese tipo de documento no existe.' using errcode = '22023', hint = 'tipo_documento_id';
  end if;
  if p_tipo = 'espera' and not exists (select 1 from public.fases where id = v.espera_fase_id) then
    raise exception 'La fase que espera no existe.' using errcode = '22023', hint = 'espera_fase_id';
  end if;

  begin
    insert into public.fases_requisitos select (v).*;
  exception when unique_violation then
    get stacked diagnostics v_restriccion = constraint_name;
    if v_restriccion = 'fases_requisitos_pkey' then
      raise exception 'Ese requisito ya existe.' using errcode = '23505', hint = 'id';
    end if;
    raise;
  end;
  return public._flujo_tocar(v_flujo);
end $$;


ALTER FUNCTION "public"."requisito_crear"("p_id" "uuid", "p_fase" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_tipo" "public"."tipo_requisito", "p_datos" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."requisito_crear"("p_id" "uuid", "p_fase" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_tipo" "public"."tipo_requisito", "p_datos" "jsonb") IS 'Crea un requisito informativo al final de la fase. Contrato _flujo_para_editar/_flujo_tocar; devuelve la versión del flujo.';



CREATE OR REPLACE FUNCTION "public"."requisito_eliminar"("p_requisito" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_flujo uuid;
begin
  select f.flujo_id into v_flujo from public.fases_requisitos r join public.fases f on f.id = r.fase_id where r.id = p_requisito;
  if v_flujo is null then
    raise exception 'Este requisito ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  perform public._flujo_para_editar(v_flujo, p_actualizado_en_esperado);
  delete from public.fases_requisitos where id = p_requisito;
  if not found then
    raise exception 'Este requisito ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  return public._flujo_tocar(v_flujo);
end $$;


ALTER FUNCTION "public"."requisito_eliminar"("p_requisito" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."requisito_eliminar"("p_requisito" "uuid", "p_actualizado_en_esperado" timestamp with time zone) IS 'Elimina un requisito. Contrato _flujo_para_editar/_flujo_tocar; devuelve la versión del flujo.';



CREATE OR REPLACE FUNCTION "public"."requisito_guardar"("p_requisito" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.fases_requisitos;
  v_flujo uuid;
begin
  perform public._requisito_forma(null, p_cambios, false);
  select f.flujo_id into v_flujo from public.fases_requisitos r join public.fases f on f.id = r.fase_id where r.id = p_requisito;
  if v_flujo is null then
    raise exception 'Este requisito ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  perform public._flujo_para_editar(v_flujo, p_actualizado_en_esperado);
  select * into v from public.fases_requisitos where id = p_requisito for update;
  if not found then
    raise exception 'Este requisito ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  perform public._requisito_forma(v.tipo, p_cambios, false);
  v := public._requisito_aplicar(v, p_cambios);
  perform public._requisito_validar(v, array(select jsonb_object_keys(p_cambios)));

  update public.fases_requisitos
  set bloqueante = v.bloqueante, notas = v.notas, min_archivos = v.min_archivos, max_archivos = v.max_archivos,
      formatos = v.formatos, config = v.config
  where id = p_requisito;
  return public._flujo_tocar(v_flujo);
end $$;


ALTER FUNCTION "public"."requisito_guardar"("p_requisito" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."requisito_guardar"("p_requisito" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") IS 'Guarda notas, archivos, formatos, config.pct o bloqueante de un requisito. Contrato _flujo_para_editar/_flujo_tocar; devuelve la versión del flujo.';



CREATE OR REPLACE FUNCTION "public"."requisito_impacto"("p_requisito" "uuid", "p_tope" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_fase uuid;
  v_flujo uuid;
  v_ambito public.ambito_flujo;
  v_tope int := public._acotar_pagina(p_tope, 50, 100);
  v_ids uuid[];
  v_n int;
begin
  select r.fase_id, f.flujo_id, fl.ambito into v_fase, v_flujo, v_ambito
  from public.fases_requisitos r join public.fases f on f.id = r.fase_id join public.flujos fl on fl.id = f.flujo_id
  where r.id = p_requisito;
  if v_fase is null then
    raise exception 'Este requisito ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  if not public.puede_configurar_flujo(v_flujo) then
    raise exception 'No tienes permiso para configurar este flujo.' using errcode = '42501';
  end if;

  if v_ambito = 'repuestos' then
    -- repuestos_items_fase_id_idx; los de stock cuentan (5.07:D9).
    v_ids := array(select i.id from public.repuestos_items i where i.fase_id = v_fase and i.eliminado_en is null limit 1000);
  else
    -- vehiculos_fase_id_idx
    v_ids := array(select v.id from public.vehiculos v where v.fase_id = v_fase and v.eliminado_en is null limit 1000);
  end if;

  select count(*) into v_n from (
    select 1 from unnest(v_ids) u(id)
    where exists (
      select 1 from public.evaluar_requisitos(
        case when v_ambito = 'repuestos' then null else u.id end,
        case when v_ambito = 'repuestos' then u.id end,
        v_fase) e
      where e.requisito_id = p_requisito and not e.cumplido)
    limit v_tope + 1) q;

  return jsonb_build_object('fuera', least(v_n, v_tope), 'hay_mas', v_n > v_tope, 'revisadas', coalesce(cardinality(v_ids), 0));
end $$;


ALTER FUNCTION "public"."requisito_impacto"("p_requisito" "uuid", "p_tope" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."requisito_impacto"("p_requisito" "uuid", "p_tope" integer) IS 'Cuántas unidades de la fase (a lo sumo 1.000 revisadas) no cumplen el requisito: {fuera, hay_mas, revisadas}, cortado en _acotar_pagina(p_tope, 50, 100). Sólo quien configura el flujo.';



CREATE OR REPLACE FUNCTION "public"."requisito_mover"("p_requisito" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_despues_de" "uuid" DEFAULT NULL::"uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.fases_requisitos;
  v_flujo uuid;
begin
  if p_despues_de is not null and p_despues_de = p_requisito then
    raise exception 'Un requisito no puede ir después de sí mismo.' using errcode = '22023', hint = 'despues_de';
  end if;
  select f.flujo_id into v_flujo from public.fases_requisitos r join public.fases f on f.id = r.fase_id where r.id = p_requisito;
  if v_flujo is null then
    raise exception 'Este requisito ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  perform public._flujo_para_editar(v_flujo, p_actualizado_en_esperado);
  select * into v from public.fases_requisitos where id = p_requisito for update;
  if not found then
    raise exception 'Este requisito ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  if p_despues_de is not null and not exists (select 1 from public.fases_requisitos x where x.id = p_despues_de and x.fase_id = v.fase_id) then
    raise exception 'Ese requisito ya no está en esta fase. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;

  update public.fases_requisitos x set orden = n.nuevo
  from (
    select q.id, (row_number() over (order by q.posicion, q.id) * 10)::smallint as nuevo from (
      select x.id,
        case
          when x.id = p_requisito then (case when p_despues_de is null then -1.0
                                             else (select y.orden from public.fases_requisitos y where y.id = p_despues_de) + 0.5 end)
          else x.orden::numeric
        end as posicion
      from public.fases_requisitos x where x.fase_id = v.fase_id
    ) q
  ) n
  where x.id = n.id and x.orden <> n.nuevo;

  return public._flujo_tocar(v_flujo);
end $$;


ALTER FUNCTION "public"."requisito_mover"("p_requisito" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_despues_de" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."requisito_mover"("p_requisito" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_despues_de" "uuid") IS 'Mueve un requisito (primero o tras p_despues_de) y renumera su fase de 10 en 10. Contrato _flujo_para_editar/_flujo_tocar; devuelve la versión del flujo.';



CREATE OR REPLACE FUNCTION "public"."revisar_flujo"("p_flujo" "uuid") RETURNS TABLE("nivel" "text", "codigo" "text", "mensaje" "text", "fase_id" "uuid")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  v_ambito public.ambito_flujo;
  v_iniciales uuid[];
  v_inicial public.fases;
  v_motivos text[] := array[]::text[];
begin
  if p_flujo is null or not public.puede_configurar_flujo(p_flujo) then
    return;
  end if;

  return query
  with f as (select * from public.fases fa where fa.flujo_id = p_flujo and fa.activa)
  select 'error', 'sin_inicial', 'El flujo no tiene ninguna fase inicial activa.', null::uuid where not exists (select 1 from f where f.es_inicial)
  union all
  select 'aviso', 'sin_salida', 'La fase «' || f.nombre || '» no tiene salida y no es final.', f.id from f where not f.es_final and not exists (select 1 from public.fases_transiciones t where t.de_fase_id = f.id)
  union all
  select 'aviso', 'inalcanzable', 'La fase «' || f.nombre || '» no es inicial y nadie llega a ella.', f.id from f where not f.es_inicial and not exists (select 1 from public.fases_transiciones t where t.a_fase_id = f.id)
  union all
  select 'aviso', 'orden_duplicado', 'Dos fases comparten el orden ' || f.orden || '.', (array_agg(f.id order by f.nombre))[1] from f group by f.orden having count(*) > 1
  union all
  select 'aviso', 'contenedor_inalcanzable', 'La fase «' || f.nombre || '» exige contenedor pero ninguna fase del flujo permite asignarlo.', f.id
    from f where exists (select 1 from public.fases_requisitos q where q.fase_id = f.id and q.clave_dato = 'transporte.contenedor') and not exists (select 1 from f f2 where f2.permite_contenedor)
  union all
  select 'aviso', 'espera_jubilada', 'La fase «' || f.nombre || '» espera a una fase jubilada.', f.id
    from f where exists (select 1 from public.fases_requisitos q join public.fases e on e.id = q.espera_fase_id where q.fase_id = f.id and not e.activa)
  union all
  select 'aviso', 'espera_cruzada', 'Esperas cruzadas: «' || f.nombre || '» y la fase que espera se esperan mutuamente.', f.id
    from f where exists (
      select 1 from public.fases_requisitos a join public.fases_requisitos b on b.fase_id = a.espera_fase_id
      where a.fase_id = f.id and a.tipo = 'espera' and b.tipo = 'espera' and b.espera_fase_id = f.id)
  union all
  select 'info', 'sin_bloqueantes', 'La fase «' || f.nombre || '» sólo tiene requisitos informativos.', f.id
    from f where exists (select 1 from public.fases_requisitos q where q.fase_id = f.id) and not exists (select 1 from public.fases_requisitos q where q.fase_id = f.id and q.bloqueante)
  union all
  -- C3: la lista de la fase, aunque cada entrada traiga la suya (no replica la precedencia de `_puede_mover`).
  select 'aviso', 'rol_sin_personas', 'Sólo pueden mover a «' || f.nombre || '» roles que nadie tiene.', f.id
    from f where exists (select 1 from public.fases_roles fr where fr.fase_id = f.id)
      and not exists (
        select 1 from public.fases_roles fr
          join public.usuarios_roles ur on ur.rol_id = fr.rol_id
          join public.perfiles p on p.id = ur.usuario_id
        where fr.fase_id = f.id and p.activo and not p.bloqueado)
  union all
  -- C4
  select 'aviso', 'rol_sin_personas', 'Sólo pueden usar la salida de «' || d.nombre || '» a «' || h.nombre || '» roles que nadie tiene.', d.id
    from public.fases_transiciones t join f d on d.id = t.de_fase_id join f h on h.id = t.a_fase_id
    where exists (select 1 from public.fases_transiciones_roles tr where tr.transicion_id = t.id)
      and not exists (
        select 1 from public.fases_transiciones_roles tr
          join public.usuarios_roles ur on ur.rol_id = tr.rol_id
          join public.perfiles p on p.id = ur.usuario_id
        where tr.transicion_id = t.id and p.activo and not p.bloqueado)
  union all
  -- C6
  select 'aviso', 'tipo_documento_inactivo', 'La fase «' || f.nombre || '» pide «' || td.nombre || '», que está desactivado.', f.id
    from f join public.fases_requisitos q on q.fase_id = f.id join public.tipos_documento td on td.id = q.tipo_documento_id
    where not td.activo
  union all
  -- C7
  select 'aviso', 'salida_a_jubilada', 'La fase «' || d.nombre || '» tiene una salida a «' || h.nombre || '», que está jubilada.', d.id
    from public.fases_transiciones t join f d on d.id = t.de_fase_id join public.fases h on h.id = t.a_fase_id
    where not h.activa and h.flujo_id = p_flujo;

  -- C5: espejo de `_vehiculo_fase_de_entrada()`, que sólo existe para vehículos.
  select fl.ambito into v_ambito from public.flujos fl where fl.id = p_flujo;
  if v_ambito is distinct from 'vehiculos' then
    return;
  end if;
  select array_agg(fa.id) into v_iniciales from public.fases fa where fa.flujo_id = p_flujo and fa.es_inicial and fa.activa;
  if coalesce(cardinality(v_iniciales), 0) > 1 then
    return query select 'info', 'entrada_no_automatica', 'Hay más de una fase inicial: los vehículos nuevos nacen «Sin fase».', null::uuid;
    return;
  end if;
  if coalesce(cardinality(v_iniciales), 0) = 0 then
    return;
  end if;
  select * into v_inicial from public.fases fa where fa.id = v_iniciales[1];
  if v_inicial.nota_obligatoria then
    v_motivos := array_append(v_motivos, 'una nota');
  end if;
  if exists (select 1 from public.fases_requisitos q where q.fase_id = v_inicial.id and q.bloqueante) then
    v_motivos := array_append(v_motivos, 'requisitos bloqueantes');
  end if;
  if exists (select 1 from public.fases_roles fr where fr.fase_id = v_inicial.id) then
    v_motivos := array_append(v_motivos, 'un rol');
  end if;
  if cardinality(v_motivos) > 0 then
    return query select 'info', 'entrada_no_automatica',
      'Los vehículos nuevos pueden nacer «Sin fase»: la fase inicial «' || v_inicial.nombre || '» pide '
        || case cardinality(v_motivos)
             when 1 then v_motivos[1]
             when 2 then v_motivos[1] || ' y ' || v_motivos[2]
             else v_motivos[1] || ', ' || v_motivos[2] || ' y ' || v_motivos[3]
           end || '.',
      v_inicial.id;
  end if;
end;
$$;


ALTER FUNCTION "public"."revisar_flujo"("p_flujo" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."revisar_flujo"("p_flujo" "uuid") IS 'Revisa la coherencia de un flujo (5.12). Sólo responde a quien lo configura (puede_configurar_flujo); a los demás, cero filas sin error. Códigos: error sin_inicial; aviso sin_salida, inalcanzable, orden_duplicado, contenedor_inalcanzable, espera_jubilada, espera_cruzada, rol_sin_personas, tipo_documento_inactivo, salida_a_jubilada; info sin_bloqueantes, entrada_no_automatica. Avisa, nunca impide guardar.';



CREATE OR REPLACE FUNCTION "public"."revocar_portal"("p_lead" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_codigo text;
begin
  perform public._lead_mio(p_lead, 'leads.portal.gestionar', true);
  update public.accesos_portal x set habilitado = false, revocado_por = (select auth.uid()), revocado_en = now()
  where x.lead_id = p_lead and x.habilitado
  returning x.codigo into v_codigo;
  if v_codigo is not null then
    perform public.registrar_actividad('portal.revocado', 'accesos_portal', p_lead::text, null, null,
      jsonb_build_object('codigo', v_codigo));
  end if;
end;
$$;


ALTER FUNCTION "public"."revocar_portal"("p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rol_dominado"("p_rol" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select not exists (
    select 1 from public.roles_permisos rp
    where rp.rol_id = p_rol
      and not exists (
        select 1 from public.mis_permisos() m
        where m.clave = rp.permiso_clave
          and (m.origen_id is null or m.origen_id = rp.origen_id)
          and (m.alcance = 'todos' or rp.alcance = 'propios')
      )
  );
$$;


ALTER FUNCTION "public"."rol_dominado"("p_rol" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."roles_personas"() RETURNS TABLE("rol_id" "uuid", "personas" integer)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  r record;
begin
  for r in select ro.id from public.roles ro loop
    rol_id := r.id;
    execute format('select count(*)::int from (select 1 from public.usuarios_roles ur where ur.rol_id = %L limit 1001) x', r.id)  -- index: usuarios_roles_rol_idx
      into personas;
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "public"."roles_personas"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seguimiento_actualizar_lead"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.leads set ultimo_seguimiento_en = (select max(ocurrido_en) from public.seguimientos s where s.lead_id = coalesce(new.lead_id, old.lead_id) and s.eliminado_en is null)
  where id = coalesce(new.lead_id, old.lead_id);
  return null;
end;
$$;


ALTER FUNCTION "public"."seguimiento_actualizar_lead"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seguimiento_crear"("p_id" "uuid", "p_lead" "uuid", "p_seguimiento" "jsonb", "p_recordatorio" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  l public.leads;
  s public.seguimientos;
  r public.recordatorios;
  v_tipo uuid;
  v_titulo text;
  v_doc jsonb;
  v_texto text;
  v_visibilidad public.visibilidad_seguimiento := 'privado';
  v_ocurrido timestamptz := now();
  v_recordar timestamptz;
  v_vehiculo uuid;
  v_k text;
begin
  l := public._lead_mio(p_lead);
  if p_id is null then
    raise exception 'Falta el identificador del seguimiento.' using errcode = '22023';
  end if;
  select * into s from public.seguimientos x where x.id = p_id;
  if found then
    if s.usuario_id = (select auth.uid()) and s.lead_id = l.id then
      return jsonb_build_object('resultado', 'repetido', 'seguimiento', public._seguimiento_json(s), 'recordatorio', null);
    end if;
    raise exception 'No pudimos guardar este seguimiento. Vuelve a intentarlo.' using errcode = '22023';
  end if;

  if p_seguimiento is null or jsonb_typeof(p_seguimiento) <> 'object' then
    raise exception 'Escribe un resumen del seguimiento.' using errcode = '22023', hint = 'titulo';
  end if;
  for v_k in select jsonb_object_keys(p_seguimiento) loop
    if v_k not in ('tipo_id', 'titulo', 'detalle', 'visibilidad', 'ocurrido_en', 'vehiculo_id') then
      raise exception 'El dato «%» no es de un seguimiento.', v_k using errcode = '22023', hint = v_k;
    end if;
  end loop;

  begin
    v_tipo := nullif(p_seguimiento ->> 'tipo_id', '')::uuid;
  exception when invalid_text_representation then
    v_tipo := null;
  end;
  if v_tipo is null or not exists (select 1 from public.tipos_seguimiento t where t.id = v_tipo and t.activo) then
    raise exception 'Elige un tipo de seguimiento que esté activo.' using errcode = '22023', hint = 'tipo_id';
  end if;
  v_titulo := public._seguimiento_titulo(p_seguimiento -> 'titulo', 'titulo');
  v_doc := p_seguimiento -> 'detalle';
  v_texto := public._seguimiento_detalle(v_doc);
  if v_texto is null then
    v_doc := null;
  end if;
  if p_seguimiento ? 'visibilidad' then
    v_visibilidad := public._seguimiento_visibilidad(p_seguimiento -> 'visibilidad');
  end if;
  if p_seguimiento ? 'ocurrido_en' and p_seguimiento -> 'ocurrido_en' <> 'null'::jsonb then
    v_ocurrido := public._seguimiento_fecha(p_seguimiento -> 'ocurrido_en');
  end if;
  v_vehiculo := public._vehiculo_para_nota(public._uuid_de(p_seguimiento -> 'vehiculo_id', 'vehiculo_id'));

  if p_recordatorio is not null and p_recordatorio <> 'null'::jsonb then
    if jsonb_typeof(p_recordatorio) <> 'object' then
      raise exception 'Elige cuándo recordarlo.' using errcode = '22023', hint = 'recordatorio.recordar_en';
    end if;
    begin
      v_recordar := (p_recordatorio ->> 'recordar_en')::timestamptz;
    exception when others then
      v_recordar := null;
    end;
    v_recordar := public._recordatorio_cuando(v_recordar, 'recordatorio.recordar_en');
  end if;

  begin
    insert into public.seguimientos (id, lead_id, usuario_id, tipo_id, titulo, detalle_doc, detalle_texto,
                                     visibilidad, ocurrido_en, vehiculo_id, actualizado_en)
    values (p_id, l.id, (select auth.uid()), v_tipo, v_titulo, v_doc, v_texto, v_visibilidad, v_ocurrido, v_vehiculo,
            clock_timestamp())
    returning * into s;
  exception when unique_violation then
    -- El mismo intento llegó dos veces a la vez (doble clic): el otro ya lo guardó.
    select * into s from public.seguimientos x where x.id = p_id;
    if s.usuario_id = (select auth.uid()) and s.lead_id = l.id then
      return jsonb_build_object('resultado', 'repetido', 'seguimiento', public._seguimiento_json(s), 'recordatorio', null);
    end if;
    raise exception 'No pudimos guardar este seguimiento. Vuelve a intentarlo.' using errcode = '22023';
  end;

  -- El recordatorio que nace con el seguimiento lleva su mismo vehículo.
  if v_recordar is not null then
    insert into public.recordatorios (usuario_id, lead_id, vehiculo_id, titulo, recordar_en, actualizado_en)
    values ((select auth.uid()), l.id, v_vehiculo,
            public._recordatorio_titulo(coalesce(nullif(btrim(p_recordatorio ->> 'titulo'), ''), v_titulo), 'recordatorio.titulo'),
            v_recordar, clock_timestamp())
    returning * into r;
  end if;

  perform public.registrar_actividad('lead.seguimiento_creado', 'leads', l.id::text, null, null,
    jsonb_build_object('seguimiento', s.id, 'tipo', s.tipo_id, 'visibilidad', s.visibilidad));
  return jsonb_build_object('resultado', 'creado', 'seguimiento', public._seguimiento_json(s),
    'recordatorio', case when r.id is not null then public._recordatorio_json(r) end);
end;
$$;


ALTER FUNCTION "public"."seguimiento_crear"("p_id" "uuid", "p_lead" "uuid", "p_seguimiento" "jsonb", "p_recordatorio" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seguimiento_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare s public.seguimientos; n public.seguimientos;
begin
  s := public._seguimiento_mio(p_id);
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  if s.eliminado_en is not null then
    return jsonb_build_object('resultado', 'sin_cambios', 'seguimiento', public._seguimiento_json(s));
  end if;
  if s.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._seguimiento_conflicto(s.actualizado_en);
  end if;
  update public.seguimientos x set
    eliminado_en = now(),
    actualizado_en = greatest(clock_timestamp(), s.actualizado_en + interval '1 microsecond')
  where x.id = s.id
  returning * into n;
  perform public.registrar_actividad('lead.seguimiento_eliminado', 'leads', n.lead_id::text, null, null,
    jsonb_build_object('seguimiento', n.id, 'tipo', n.tipo_id, 'visibilidad', n.visibilidad));
  return jsonb_build_object('resultado', 'eliminado', 'seguimiento', public._seguimiento_json(n));
end;
$$;


ALTER FUNCTION "public"."seguimiento_eliminar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seguimiento_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  s public.seguimientos;
  n public.seguimientos;
  v_tipo uuid;
  v_titulo text;
  v_doc jsonb;
  v_texto text;
  v_visibilidad public.visibilidad_seguimiento;
  v_ocurrido timestamptz;
  v_vehiculo uuid;
  v_k text;
begin
  s := public._seguimiento_mio(p_id);
  if s.eliminado_en is not null then
    raise exception 'No encontramos este seguimiento o no tienes acceso.' using errcode = '42501';
  end if;
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  if p_cambios is null or jsonb_typeof(p_cambios) <> 'object' then
    raise exception 'Los cambios de un seguimiento tienen que ser un objeto.' using errcode = '22023';
  end if;
  for v_k in select jsonb_object_keys(p_cambios) loop
    if v_k not in ('tipo_id', 'titulo', 'detalle', 'visibilidad', 'ocurrido_en', 'vehiculo_id') then
      raise exception 'El dato «%» no es de un seguimiento.', v_k using errcode = '22023', hint = v_k;
    end if;
  end loop;

  v_tipo := s.tipo_id;
  v_titulo := s.titulo;
  v_doc := s.detalle_doc;
  v_texto := s.detalle_texto;
  v_visibilidad := s.visibilidad;
  v_ocurrido := s.ocurrido_en;
  v_vehiculo := s.vehiculo_id;

  if p_cambios ? 'tipo_id' then
    begin
      v_tipo := nullif(p_cambios ->> 'tipo_id', '')::uuid;
    exception when invalid_text_representation then
      v_tipo := null;
    end;
    if v_tipo is distinct from s.tipo_id
       and (v_tipo is null or not exists (select 1 from public.tipos_seguimiento t where t.id = v_tipo and t.activo)) then
      raise exception 'Elige un tipo de seguimiento que esté activo.' using errcode = '22023', hint = 'tipo_id';
    end if;
  end if;
  if p_cambios ? 'titulo' then
    v_titulo := public._seguimiento_titulo(p_cambios -> 'titulo', 'titulo');
  end if;
  if p_cambios ? 'detalle' then
    v_doc := p_cambios -> 'detalle';
    v_texto := public._seguimiento_detalle(v_doc);
    if v_texto is null then
      v_doc := null;
    end if;
  end if;
  if p_cambios ? 'visibilidad' then
    v_visibilidad := public._seguimiento_visibilidad(p_cambios -> 'visibilidad');
  end if;
  if p_cambios ? 'ocurrido_en' then
    v_ocurrido := public._seguimiento_fecha(p_cambios -> 'ocurrido_en');
  end if;
  -- El vehículo sólo se mira si cambia: uno que su autor dejó de ver se conserva al editar lo demás.
  if p_cambios ? 'vehiculo_id' then
    v_vehiculo := public._uuid_de(p_cambios -> 'vehiculo_id', 'vehiculo_id');
    if v_vehiculo is distinct from s.vehiculo_id then
      v_vehiculo := public._vehiculo_para_nota(v_vehiculo);
    end if;
  end if;

  if (v_tipo, v_titulo, v_doc, v_texto, v_visibilidad, v_ocurrido, v_vehiculo)
     is not distinct from (s.tipo_id, s.titulo, s.detalle_doc, s.detalle_texto, s.visibilidad, s.ocurrido_en, s.vehiculo_id) then
    return jsonb_build_object('resultado', 'sin_cambios', 'seguimiento', public._seguimiento_json(s));
  end if;
  if s.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._seguimiento_conflicto(s.actualizado_en);
  end if;

  update public.seguimientos x set
    tipo_id = v_tipo, titulo = v_titulo, detalle_doc = v_doc, detalle_texto = v_texto,
    visibilidad = v_visibilidad, ocurrido_en = v_ocurrido, vehiculo_id = v_vehiculo,
    actualizado_en = greatest(clock_timestamp(), s.actualizado_en + interval '1 microsecond')
  where x.id = s.id
  returning * into n;
  perform public.registrar_actividad('lead.seguimiento_editado', 'leads', n.lead_id::text, null, null,
    jsonb_build_object('seguimiento', n.id, 'tipo', n.tipo_id, 'visibilidad', n.visibilidad));
  return jsonb_build_object('resultado', 'guardado', 'seguimiento', public._seguimiento_json(n));
end;
$$;


ALTER FUNCTION "public"."seguimiento_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seguimiento_restaurar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare s public.seguimientos; n public.seguimientos;
begin
  s := public._seguimiento_mio(p_id);
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  if s.eliminado_en is null then
    return jsonb_build_object('resultado', 'sin_cambios', 'seguimiento', public._seguimiento_json(s));
  end if;
  if s.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._seguimiento_conflicto(s.actualizado_en);
  end if;
  update public.seguimientos x set
    eliminado_en = null,
    actualizado_en = greatest(clock_timestamp(), s.actualizado_en + interval '1 microsecond')
  where x.id = s.id
  returning * into n;
  perform public.registrar_actividad('lead.seguimiento_restaurado', 'leads', n.lead_id::text, null, null,
    jsonb_build_object('seguimiento', n.id, 'tipo', n.tipo_id, 'visibilidad', n.visibilidad));
  return jsonb_build_object('resultado', 'restaurado', 'seguimiento', public._seguimiento_json(n));
end;
$$;


ALTER FUNCTION "public"."seguimiento_restaurar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seguimiento_tipo_vigente"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_activo boolean;
begin
  if tg_op = 'UPDATE' and new.tipo_id is not distinct from old.tipo_id then
    return new;
  end if;
  select t.activo into v_activo from public.tipos_seguimiento t where t.id = new.tipo_id for share;
  if not found then
    raise exception 'Ese tipo de seguimiento ya no existe: elige otro.' using errcode = '22023', hint = 'tipo_id';
  end if;
  if not v_activo then
    raise exception 'Ese tipo de seguimiento se desactivó: elige otro.' using errcode = '22023', hint = 'tipo_id';
  end if;
  return new;
end;
$$;


