CREATE OR REPLACE FUNCTION "public"."slugificar"("p" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select trim(both '-' from regexp_replace(
    lower(translate(coalesce(p, ''), 'áéíóúüñÁÉÍÓÚÜÑ', 'aeiouunAEIOUUN')),
    '[^a-z0-9]+', '-', 'g'));
$$;


ALTER FUNCTION "public"."slugificar"("p" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."storage_gc_abrir"("p_pase" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.cola_gc_pases p set usado_en = now()
  where p.pase = p_pase and p.usado_en is null and p.creado_en > now() - interval '10 minutes';
  return found;
end;
$$;


ALTER FUNCTION "public"."storage_gc_abrir"("p_pase" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."storage_gc_confirmar"("p_bucket" "text", "p_rutas" "text"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare n int;
begin
  delete from public.cola_gc_storage c
  where c.bucket = p_bucket and c.ruta = any (p_rutas) and c.reclamado_en is not null;
  get diagnostics n = row_count;
  return n;
end;
$$;


ALTER FUNCTION "public"."storage_gc_confirmar"("p_bucket" "text", "p_rutas" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."storage_gc_correr"() RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_url text := public._url_del_proyecto();
begin
  if v_url is null then
    raise warning 'storage-gc no corrió: falta el secreto url_proyecto en Vault (lo pone scripts/demo/restaurar.sh).';
    return null;
  end if;
  return public.storage_gc_disparar(v_url || '/functions/v1/storage-gc');
end $$;


ALTER FUNCTION "public"."storage_gc_correr"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."storage_gc_correr"() IS 'El job storage-gc: dispara la función con la URL de Vault (url_proyecto). Sin el secreto, avisa y no hace nada.';



CREATE OR REPLACE FUNCTION "public"."storage_gc_disparar"("p_url" "text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_pase uuid; v_pedido bigint;
begin
  if p_url is null or p_url !~ '^https?://[^[:space:]]+/functions/v1/storage-gc$' then
    raise exception 'La dirección de storage-gc no es válida.' using errcode = '22023';
  end if;
  delete from public.cola_gc_pases p where p.creado_en < now() - interval '7 days';
  insert into public.cola_gc_pases default values returning pase into v_pase;
  select net.http_post(url := p_url, body := jsonb_build_object('pase', v_pase),
    headers := jsonb_build_object('Content-Type', 'application/json'), timeout_milliseconds := 60000) into v_pedido;
  return v_pedido;
end;
$_$;


ALTER FUNCTION "public"."storage_gc_disparar"("p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."storage_gc_encolar_huerfanos"("p_bucket" "text", "p_gracia" interval) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_ventana constant int := 10000;
  v_desde text;
  v_ultimo text;
  v_vistos int;
  n int;
begin
  insert into public.cola_gc_barrido (bucket) values (p_bucket) on conflict (bucket) do nothing;
  -- Una pasada a la vez por bucket: dos corridas que se cruzan no examinan la misma ventana.
  select b.ultimo_nombre into v_desde from public.cola_gc_barrido b where b.bucket = p_bucket for update;
  select count(*), max(o.name) into v_vistos, v_ultimo
    from (select o.name from storage.objects o
           where o.bucket_id = p_bucket and o.name > v_desde
           order by o.name limit v_ventana) o;
  if p_bucket = 'vehiculos' then
    insert into public.cola_gc_storage (bucket, ruta, encolado_en)
    select o.bucket_id, o.name, o.created_at
    from storage.objects o
    where o.bucket_id = 'vehiculos' and o.name > v_desde and o.name <= v_ultimo
      and o.created_at < now() - p_gracia
      and not exists (select 1 from public.vehiculos_imagenes i where i.ruta = o.name)
      and not exists (select 1 from public.vehiculos_imagenes i where i.ruta_miniatura = o.name)
      and not exists (select 1 from public.cola_gc_storage c where c.bucket = 'vehiculos' and c.ruta = o.name)
    on conflict do nothing;
  else
    insert into public.cola_gc_storage (bucket, ruta, encolado_en)
    select o.bucket_id, o.name, o.created_at
    from storage.objects o
    where o.bucket_id = p_bucket and o.name > v_desde and o.name <= v_ultimo
      and o.created_at < now() - p_gracia
      and public.storage_refcount(o.bucket_id, o.name) = 0
    on conflict do nothing;
  end if;
  get diagnostics n = row_count;
  -- La ventana no se llenó: se llegó al final del bucket y la próxima pasada empieza otra vuelta.
  update public.cola_gc_barrido
     set ultimo_nombre = case when v_vistos < v_ventana then '' else v_ultimo end,
         vuelta_desde = case when v_vistos < v_ventana then now() else vuelta_desde end,
         actualizado_en = now()
   where bucket = p_bucket;
  return n;
end;
$$;


ALTER FUNCTION "public"."storage_gc_encolar_huerfanos"("p_bucket" "text", "p_gracia" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."storage_gc_pendiente"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v jsonb;
begin
  perform public.assert_activo();
  if not public.tiene_permiso('vehiculos.papelera.purgar') then
    return null;
  end if;
  -- Índice: `cola_gc_storage_edad_idx (encolado_en)`.
  select jsonb_build_object('objetos', least(count(*), 1000), 'hay_mas', count(*) > 1000,
                            'desde', min(q.encolado_en) + public._gracia_de_storage()) into v
  from (select c.encolado_en from public.cola_gc_storage c
         where c.encolado_en < now() - public._gracia_de_storage() - interval '3 hours'
         order by c.encolado_en limit 1001) q;
  return v;
end;
$$;


ALTER FUNCTION "public"."storage_gc_pendiente"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."storage_gc_programar"("p_url" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
begin
  if p_url is null or p_url !~ '^https?://[^[:space:]]+/functions/v1/storage-gc$' then
    raise exception 'La dirección de storage-gc no es válida.' using errcode = '22023';
  end if;
  perform cron.schedule('storage-gc', '17 * * * *', format('select public.storage_gc_disparar(%L)', p_url));
end;
$_$;


ALTER FUNCTION "public"."storage_gc_programar"("p_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."storage_gc_reclamar"("p_max" integer DEFAULT 100) RETURNS TABLE("bucket" "text", "ruta" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  r record;
  v_vencido constant interval := interval '1 hour';
begin
  perform public.storage_gc_encolar_huerfanos('vehiculos', public._gracia_de_storage());
  for r in
    select c.bucket as su_bucket, c.ruta as su_ruta
    from public.cola_gc_storage c
    where c.encolado_en < now() - public._gracia_de_storage()
      and (c.reclamado_en is null or c.reclamado_en < now() - v_vencido)
    order by c.encolado_en
    limit greatest(coalesce(p_max, 0), 0)
  loop
    -- Alguien lo está referenciando ahora mismo: se deja para la próxima pasada.
    if not pg_try_advisory_xact_lock(public._candado_de_objeto(r.su_bucket, r.su_ruta)) then
      continue;
    end if;
    -- Con el candado tomado, toda referencia confirmada ya se ve, y ninguna puede nacer.
    if public.storage_refcount(r.su_bucket, r.su_ruta) > 0 then
      delete from public.cola_gc_storage c where c.bucket = r.su_bucket and c.ruta = r.su_ruta;
    else
      update public.cola_gc_storage c set reclamado_en = now()
      where c.bucket = r.su_bucket and c.ruta = r.su_ruta;
      if found then
        bucket := r.su_bucket;
        ruta := r.su_ruta;
        return next;
      end if;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."storage_gc_reclamar"("p_max" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."storage_gc_rescatar"("p_bucket" "text", "p_ruta" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_reclamado timestamptz; v_estaba boolean := false;
begin
  perform pg_advisory_xact_lock(public._candado_de_objeto(p_bucket, p_ruta));
  select c.reclamado_en, true into v_reclamado, v_estaba
  from public.cola_gc_storage c where c.bucket = p_bucket and c.ruta = p_ruta;
  if not coalesce(v_estaba, false) then
    return;
  end if;
  if v_reclamado is not null then
    raise exception 'Ese archivo se está limpiando. Vuelve a subirlo en un momento.';
  end if;
  delete from public.cola_gc_storage c where c.bucket = p_bucket and c.ruta = p_ruta;
end;
$$;


ALTER FUNCTION "public"."storage_gc_rescatar"("p_bucket" "text", "p_ruta" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."storage_refcount"("p_bucket" "text", "p_ruta" "text") RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  select (
    (select count(*) from public.vehiculos_imagenes where p_bucket = 'vehiculos' and ruta = p_ruta) +
    (select count(*) from public.vehiculos_imagenes where p_bucket = 'vehiculos' and ruta_miniatura = p_ruta) +
    (select count(*) from public.repuestos_items_imagenes where p_bucket = 'repuestos' and ruta = p_ruta) +
    (select count(*) from public.documentos where p_bucket = 'documentos' and ruta = p_ruta and eliminado_en is null) +
    (select count(*) from public.cotizaciones_adjuntos where p_bucket = 'cotizaciones' and ruta = p_ruta) +
    (select count(*) from public.gastos where p_bucket = 'comprobantes' and comprobante_ruta = p_ruta) +
    (select count(*) from public.pagos where p_bucket = 'comprobantes' and comprobante_ruta = p_ruta) +
    (select count(*) from public.repuestos_compras where p_bucket = 'comprobantes' and comprobante_ruta = p_ruta) +
    (select count(*) from public.perfiles where p_bucket = 'avatares' and avatar_ruta = p_ruta) +
    (select count(*) from public.perfiles where p_bucket = 'avatares' and avatar_miniatura_ruta = p_ruta) +
    (select count(*) from public.web_guias where p_bucket = 'web' and portada_ruta = p_ruta) +
    (select count(*) from public.web_guias where p_bucket = 'web' and cuerpo_doc is not null
       and jsonb_path_exists(cuerpo_doc, 'lax $.content[*] ? (@.type == "image").attrs.ruta ? (@ == $r)', jsonb_build_object('r', p_ruta))) +
    (select count(*) from public.web_testimonios where p_bucket = 'web' and foto_ruta = p_ruta) +
    (select count(*) from public.ajustes_empresa where p_bucket = 'marca' and (logo_ruta = p_ruta or logo_oscuro_ruta = p_ruta)) +
    (select count(*) from public.ajustes_empresa e, jsonb_each_text(coalesce(e.iconos, '{}'::jsonb)) i where p_bucket = 'marca' and i.value = p_ruta)
  )::int;
$_$;


ALTER FUNCTION "public"."storage_refcount"("p_bucket" "text", "p_ruta" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tabla_referencia_publicar"("p_tabla" "uuid", "p_filas" "jsonb", "p_nota" "text", "p_version_esperada" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  c_sin_permiso constant text := 'No tienes el permiso «cotizaciones.configurar».';
  v_t public.tablas_referencia; v_anterior int; v_o record; v_pub public.formulas; v_nuevas jsonb; v_vivas jsonb; v_f text; v_id uuid;
  v_formulas jsonb := '[]'::jsonb; v_igual boolean;
begin
  perform public.assert_activo();
  -- Una tabla que no existe, una inactiva y una de un origen ajeno dan el mismo 42501: no se delata ninguna fila.
  select * into v_t from public.tablas_referencia r where r.id = p_tabla;                          -- tablas_referencia_pkey
  if v_t.id is null or not v_t.activa then raise exception '%', c_sin_permiso using errcode = '42501'; end if;
  -- Con origen, el de ese origen; compartida (origen nulo), el de algún origen.
  perform public.assert_permiso('cotizaciones.configurar', v_t.origen_id);
  if p_version_esperada is null then
    raise exception 'Falta la versión de la tabla que tenías.' using errcode = '22023', hint = 'version';
  end if;
  if coalesce(btrim(p_nota), '') = '' then raise exception 'Publicar pide una nota.' using errcode = '22023', hint = 'nota'; end if;

  -- El candado de la tabla: dos publicaciones de la misma tabla van en fila y la segunda ve la versión de la primera.
  select * into v_t from public.tablas_referencia r where r.id = p_tabla for update;
  if not v_t.activa then raise exception '%', c_sin_permiso using errcode = '42501'; end if;
  -- Una compartida cambia los precios de cada origen que la usa: hace falta el permiso de todos ellos (P2), antes de decir nada de la tabla.
  for v_o in select u.origen_id from public._tabla_referencia_usada_en(p_tabla) u where u.formula_id is not null loop
    perform public.assert_permiso('cotizaciones.configurar', v_o.origen_id);
  end loop;
  if v_t.version <> p_version_esperada then
    v_f := public._tabla_referencia_publicada_por(p_tabla);
    raise exception '%.', upper(left(v_f, 1)) || substr(v_f, 2) using errcode = 'PT409';
  end if;
  perform public._tabla_referencia_filas_validas(v_t.columnas, p_filas);

  -- Una celda nula es una celda ausente: así se guarda y así se compara.
  select coalesce(jsonb_agg(jsonb_strip_nulls(f.fila) order by f.n), '[]'::jsonb) into v_nuevas
    from jsonb_array_elements(p_filas) with ordinality f (fila, n);
  -- tablas_referencia_filas_tabla_orden_idx: las vivas activas, en su orden.
  select coalesce(jsonb_agg(jsonb_strip_nulls(x.valores) order by x.orden, x.id), '[]'::jsonb) into v_vivas
    from public.tablas_referencia_filas x where x.tabla_id = p_tabla and x.activa;
  -- Tras revertir una fórmula, su copia congelada vuelve a ser otra: publicar las mismas filas vivas le devuelve la tabla.
  v_igual := v_nuevas = v_vivas and not exists (
    select 1 from public._tabla_referencia_usada_en(p_tabla) u join public.formulas f on f.id = u.formula_id   -- formulas_pkey
     where (f.params -> 'tablas' -> v_t.clave) is distinct from v_nuevas);
  if v_igual then raise exception 'La tabla no cambió.' using errcode = '22023', hint = 'filas'; end if;

  -- Las filas nuevas reemplazan a todas, también a las inactivas: el cálculo y la copia congelada sólo leen las activas, y la historia queda en
  -- las copias congeladas de cada versión de la fórmula.
  delete from public.tablas_referencia_filas x where x.tabla_id = p_tabla;
  insert into public.tablas_referencia_filas (tabla_id, valores, orden)
  select p_tabla, jsonb_strip_nulls(f.fila), (f.n - 1)::smallint from jsonb_array_elements(p_filas) with ordinality f (fila, n);
  v_anterior := v_t.version;
  update public.tablas_referencia r
     set version = r.version + 1, nota = btrim(p_nota), publicado_por = (select auth.uid()), publicado_en = now()
   where r.id = p_tabla
  returning * into v_t;

  -- La N+1 de cada origen que la usa, en orden de origen. La publicada se relee tras el candado del origen (el ⚙ o un revertir pudieron
  -- publicar otra mientras se esperaba): si ya no la usa, se salta; si la usa, con el permiso de ese origen.
  for v_o in select u.origen_id from public._tabla_referencia_usada_en(p_tabla) u loop
    perform pg_advisory_xact_lock(hashtextextended('formulas:' || v_o.origen_id::text, 0));
    select f.* into v_pub from public.formulas f
     where f.id = (select u.formula_id from public._tabla_referencia_usada_en(p_tabla, v_o.origen_id) u);   -- formulas_pkey
    continue when v_pub.id is null;
    perform public.assert_permiso('cotizaciones.configurar', v_o.origen_id);
    v_id := public._publicar_version(
      v_o.origen_id, v_pub.definicion,
      v_pub.params || jsonb_build_object('tablas', coalesce(v_pub.params -> 'tablas', '{}'::jsonb) || jsonb_build_object(v_t.clave, v_nuevas)),
      v_pub.diseno, format('Tabla «%s» versión %s: %s', v_t.nombre, v_t.version, btrim(p_nota)), v_pub.id,
      jsonb_build_object('tabla', v_t.clave, 'version_tabla', v_t.version), true);
    v_formulas := v_formulas || jsonb_build_array(jsonb_build_object(
      'origen_id', v_o.origen_id, 'version', (select f.version from public.formulas f where f.id = v_id)));   -- formulas_pkey
  end loop;

  perform public.registrar_actividad('tabla_referencia.publicada', 'tablas_referencia', p_tabla::text,
    jsonb_build_object('version', v_anterior),
    jsonb_build_object('version', v_t.version, 'nota', v_t.nota, 'filas', jsonb_array_length(v_nuevas), 'formulas', v_formulas));
  return jsonb_build_object('version', v_t.version, 'formulas', v_formulas);
end;
$$;


ALTER FUNCTION "public"."tabla_referencia_publicar"("p_tabla" "uuid", "p_filas" "jsonb", "p_nota" "text", "p_version_esperada" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."tabla_referencia_publicar"("p_tabla" "uuid", "p_filas" "jsonb", "p_nota" "text", "p_version_esperada" integer) IS 'Publicar una tabla de referencia (cotizaciones.configurar de su origen; compartida, de cada origen que la usa): reemplaza sus filas, sube su versión y publica la N+1 de cada fórmula que la usa con la copia congelada, sin tocar el borrador. PT409 si la versión esperada ya no es la vigente; 22023 con el camino en el hint. Devuelve la versión y las N+1, nunca las filas. docs/COTIZADOR.md › «Las tablas congeladas (D5)».';



CREATE OR REPLACE FUNCTION "public"."tablero_cola_web"("p_desde" "date", "p_hasta" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_zona text;
  v_ini timestamptz;
  v_fin timestamptz;
  v jsonb;
begin
  perform public.assert_permiso('web.cola.gestionar');
  select w.zona, w.ini, w.fin into v_zona, v_ini, v_fin from public._tablero_ventana(p_desde, p_hasta) w;

  with del_periodo as materialized (
    -- solicitudes_contacto_web_asignada_idx: rango de asignada_en.
    select s.usuario_id, s.estado, s.es_directa,
           (not s.es_directa and s.usuario_id is not null) as asignada,
           (not s.es_directa and s.usuario_id is not null and s.estado = 'contactada') as contactada,
           case when not s.es_directa and s.usuario_id is not null and s.estado = 'contactada' and s.contactada_en is not null
                then extract(epoch from s.contactada_en - s.asignada_en) / 60 end as minutos
      from public.solicitudes_contacto_web s
     where s.asignada_en >= v_ini and s.asignada_en < v_fin
  ), por_persona as (
    select d.usuario_id, p.nombre, count(*)::int as asignadas, count(*) filter (where d.contactada)::int as contactadas,
           round((percentile_cont(0.5) within group (order by d.minutos))::numeric, 1) as mediana,
           row_number() over (order by count(*) desc, count(*) filter (where d.contactada) desc, p.nombre nulls last, d.usuario_id) as n
      from del_periodo d
      left join public.perfiles p on p.id = d.usuario_id
     where d.asignada
     group by d.usuario_id, p.nombre
  ), totales as (
    select count(*)::int as total,
           count(*) filter (where d.es_directa)::int as directas,
           count(*) filter (where d.asignada)::int as asignadas,
           count(*) filter (where d.contactada)::int as contactadas,
           round((percentile_cont(0.5) within group (order by d.minutos))::numeric, 1) as mediana
      from del_periodo d
  )
  select jsonb_build_object(
           'desde', p_desde, 'hasta', p_hasta, 'zona', v_zona,
           'total', t.total,
           'por_estado', (select jsonb_object_agg(e.estado::text, (select count(*)::int from del_periodo d where d.estado = e.estado))
                            from unnest(enum_range(null::public.estado_solicitud_web)) e (estado)),
           'directas', t.directas, 'asignadas', t.asignadas, 'contactadas', t.contactadas,
           'tasa', case when t.asignadas = 0 then null else round(t.contactadas::numeric / t.asignadas, 4) end,
           'mediana_minutos', t.mediana,
           'por_persona', (select coalesce(jsonb_agg(jsonb_build_object('usuario_id', pp.usuario_id, 'nombre', pp.nombre,
                                                                       'asignadas', pp.asignadas, 'contactadas', pp.contactadas,
                                                                       'tasa', round(pp.contactadas::numeric / pp.asignadas, 4),
                                                                       'mediana_minutos', pp.mediana) order by pp.n), '[]'::jsonb)
                             from por_persona pp where pp.n <= 20),
           'por_persona_hay_mas', exists (select 1 from por_persona pp where pp.n > 20))
    into v
    from totales t;
  return v;
end;
$$;


ALTER FUNCTION "public"."tablero_cola_web"("p_desde" "date", "p_hasta" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."tablero_cola_web"("p_desde" "date", "p_hasta" "date") IS 'Cola web del período (por asignada_en): {desde, hasta, zona, total, por_estado (las cinco claves), directas, asignadas (no directas con persona), contactadas, tasa (nula sin asignadas; sin las directas), mediana_minutos (hasta «Contacté»), por_persona (hasta 20), por_persona_hay_mas}. Pide web.cola.gestionar (9.11, D7–D8).';



CREATE OR REPLACE FUNCTION "public"."tablero_cotizaciones"("p_desde" "date", "p_hasta" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_zona text;
  v_ini timestamptz;
  v_fin timestamptz;
  v jsonb;
begin
  perform public.assert_activo();
  if not public.tiene_permiso('tablero.metricas.ver') then
    raise exception 'No tienes permiso para ver las métricas.' using errcode = '42501';
  end if;
  select w.zona, w.ini, w.fin into v_zona, v_ini, v_fin from public._tablero_ventana(p_desde, p_hasta) w;

  with creadas as materialized (
    -- cotizaciones_listado_idx: rango de creado_en, sin papelera.
    select c.origen_id, (c.creado_en at time zone v_zona)::date as dia, (c.clase = 'final')::int as fin_
      from public.cotizaciones c
     where c.eliminado_en is null and c.creado_en >= v_ini and c.creado_en < v_fin
  ), dias as (
    select d::date as dia from generate_series(p_desde::timestamp, p_hasta::timestamp, interval '1 day') d
  ), por_dia as (
    select d.dia, count(c.dia)::int as creadas, coalesce(sum(c.fin_), 0)::int as finales
      from dias d left join creadas c on c.dia = d.dia
     group by d.dia
  ), por_origen as (
    select g.origen_id, o.nombre, g.creadas, g.finales,
           row_number() over (order by g.creadas desc, g.finales desc, o.nombre, g.origen_id) as n
      from (select c.origen_id, count(*)::int as creadas, sum(c.fin_)::int as finales from creadas c group by c.origen_id) g
      join public.origenes o on o.id = g.origen_id
  )
  select jsonb_build_object(
           'desde', p_desde, 'hasta', p_hasta, 'zona', v_zona,
           'creadas', (select count(*)::int from creadas),
           'finales', (select coalesce(sum(c.fin_), 0)::int from creadas c),
           'por_dia', (select coalesce(jsonb_agg(jsonb_build_object('dia', d.dia, 'creadas', d.creadas, 'finales', d.finales) order by d.dia), '[]'::jsonb)
                         from por_dia d),
           'por_origen', (select coalesce(jsonb_agg(jsonb_build_object('origen_id', o.origen_id, 'nombre', o.nombre,
                                                                      'creadas', o.creadas, 'finales', o.finales) order by o.n), '[]'::jsonb)
                            from por_origen o where o.n <= 10),
           'por_origen_hay_mas', exists (select 1 from por_origen o where o.n > 10))
    into v;
  return v;
end;
$$;


ALTER FUNCTION "public"."tablero_cotizaciones"("p_desde" "date", "p_hasta" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tablero_leads"("p_desde" "date", "p_hasta" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_zona text;
  v_ini timestamptz;
  v_fin timestamptz;
  v jsonb;
begin
  perform public.assert_activo();
  if not public.tiene_permiso('tablero.metricas.ver') then
    raise exception 'No tienes permiso para ver las métricas.' using errcode = '42501';
  end if;
  select w.zona, w.ini, w.fin into v_zona, v_ini, v_fin from public._tablero_ventana(p_desde, p_hasta) w;

  with creados as materialized (
    -- leads_listado_idx: rango de creado_en, sin papelera.
    select l.id, l.origen_lead_id, (l.creado_en at time zone v_zona)::date as dia
      from public.leads l
     where l.eliminado_en is null and l.creado_en >= v_ini and l.creado_en < v_fin
  ), convertidos as materialized (
    -- leads_cliente_desde_idx: rango de cliente_desde, sin papelera.
    select l.id, l.origen_lead_id, (l.cliente_desde at time zone v_zona)::date as dia
      from public.leads l
     where l.eliminado_en is null and l.cliente_desde >= v_ini and l.cliente_desde < v_fin
  ), todos as materialized (
    select c.id, c.origen_lead_id, c.dia, 1 as cr, 0 as cv from creados c
    union all
    select v.id, v.origen_lead_id, v.dia, 0, 1 from convertidos v
  ), dias as (
    select d::date as dia from generate_series(p_desde::timestamp, p_hasta::timestamp, interval '1 day') d
  ), por_dia as (
    select d.dia, coalesce(sum(t.cr), 0)::int as creados, coalesce(sum(t.cv), 0)::int as convertidos
      from dias d left join todos t on t.dia = d.dia
     group by d.dia
  ), por_origen as (
    select g.origen_lead_id, o.nombre, g.creados, g.convertidos,
           row_number() over (order by g.creados desc, g.convertidos desc, o.nombre nulls last, g.origen_lead_id nulls last) as n
      from (select t.origen_lead_id, sum(t.cr)::int as creados, sum(t.cv)::int as convertidos from todos t group by t.origen_lead_id) g
      left join public.origenes_lead o on o.id = g.origen_lead_id
  ), por_asesor as (
    -- El dueño vigente de cada lead por leads_asesores_dueno_unico (una sonda por lead del período). Quien está en una baja en curso no se
    -- queda con el lead: no entra al ranking y su lead cuenta sólo en el total, como uno sin dueño (D7).
    select g.usuario_id, p.nombre, g.creados, g.convertidos,
           row_number() over (order by g.creados desc, g.convertidos desc, p.nombre nulls last, g.usuario_id) as n
      from (select a.usuario_id, sum(t.cr)::int as creados, sum(t.cv)::int as convertidos
              from todos t
              join public.leads_asesores a on a.lead_id = t.id and a.tipo_acceso = 'dueno' and a.revocado_en is null
                                              and a.usuario_id <> all ((select public._bajas_en_curso())::uuid[])
             group by a.usuario_id) g
      left join public.perfiles p on p.id = g.usuario_id
  ), cuentas as (
    select coalesce(sum(t.cr), 0)::int as creados, coalesce(sum(t.cv), 0)::int as convertidos from todos t
  )
  select jsonb_build_object(
           'desde', p_desde, 'hasta', p_hasta, 'zona', v_zona,
           'creados', c.creados, 'convertidos', c.convertidos,
           'tasa', case when c.creados = 0 then null else round(c.convertidos::numeric / c.creados, 4) end,
           'conversion_desde', public._tablero_conversion_desde(),
           'por_dia', (select coalesce(jsonb_agg(jsonb_build_object('dia', d.dia, 'creados', d.creados, 'convertidos', d.convertidos) order by d.dia), '[]'::jsonb)
                         from por_dia d),
           'por_origen', (select coalesce(jsonb_agg(jsonb_build_object('origen_lead_id', o.origen_lead_id, 'nombre', o.nombre,
                                                                      'creados', o.creados, 'convertidos', o.convertidos) order by o.n), '[]'::jsonb)
                            from por_origen o where o.n <= 10),
           'por_origen_hay_mas', exists (select 1 from por_origen o where o.n > 10),
           'por_asesor', (select coalesce(jsonb_agg(jsonb_build_object('usuario_id', a.usuario_id, 'nombre', a.nombre,
                                                                      'creados', a.creados, 'convertidos', a.convertidos) order by a.n), '[]'::jsonb)
                            from por_asesor a where a.n <= 20),
           'por_asesor_hay_mas', exists (select 1 from por_asesor a where a.n > 20))
    into v
    from cuentas c;
  return v;
end;
$$;


ALTER FUNCTION "public"."tablero_leads"("p_desde" "date", "p_hasta" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tablero_margen"("p_desde" "date", "p_hasta" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_origenes uuid[];
  v_zona text;
  v_ini timestamptz;
  v_fin timestamptz;
  v_moneda text;
  v jsonb;
begin
  perform public.assert_permiso('logistica.margen.ver');
  v_origenes := public.origenes_con_alcance('logistica.margen.ver', 'propios');
  select w.zona, w.ini, w.fin into v_zona, v_ini, v_fin from public._tablero_ventana(p_desde, p_hasta) w;
  select e.moneda_base::text into v_moneda from public.ajustes_empresa e where e.id = 1;

  with cohorte as materialized (
    -- pagos_tablero_confirmado_idx: rango de confirmado_en; el pago confirmado posterior, por pagos_vehiculo_idx.
    select p.vehiculo_id, v.origen_id
      from public.pagos p
      join public.vehiculos v on v.id = p.vehiculo_id
     where p.confirmado and p.eliminado_en is null and p.vehiculo_id is not null
       and p.confirmado_en >= v_ini and p.confirmado_en < v_fin
       and v.eliminado_en is null and v.origen_id = any (v_origenes)
       and not exists (select 1 from public.pagos q
                        where q.vehiculo_id = p.vehiculo_id and q.confirmado and q.eliminado_en is null and q.confirmado_en >= v_fin)
     group by p.vehiculo_id, v.origen_id
  ), por_vehiculo as materialized (
    -- Lo mismo que margen_vehiculo: pagos_vehiculo_idx, gastos_vehiculo_idx y cotizaciones_final_por_vehiculo (una final activa por vehículo).
    select c.vehiculo_id, c.origen_id,
           (select sum(p.monto_base) from public.pagos p
             where p.vehiculo_id = c.vehiculo_id and p.confirmado and p.eliminado_en is null) as venta,
           (select coalesce(sum(g.monto_base), 0) from public.gastos g
             where g.vehiculo_id = c.vehiculo_id and g.eliminado_en is null) as real_,
           (select k.total_base from public.cotizaciones k
             where k.vehiculo_id = c.vehiculo_id and k.clase = 'final' and k.estado = 'activa' and k.eliminado_en is null) as cotizado
      from cohorte c
  ), sin_venta as materialized (
    -- pagos_fecha_idx: rango de fecha de los pagos vivos.
    select distinct p.vehiculo_id, v.origen_id
      from public.pagos p
      join public.vehiculos v on v.id = p.vehiculo_id
     where p.eliminado_en is null and not p.confirmado and p.vehiculo_id is not null
       and p.fecha >= p_desde and p.fecha <= p_hasta
       and v.eliminado_en is null and v.origen_id = any (v_origenes)
       and not exists (select 1 from public.pagos q where q.vehiculo_id = p.vehiculo_id and q.confirmado and q.eliminado_en is null)
  ), por_origen as (
    select o.id as origen_id, o.nombre, coalesce(a.vehiculos, 0) as vehiculos, a.venta, a.real_, a.cotizado,
           a.venta - a.real_ as margen, coalesce(s.n, 0) as sin_venta,
           row_number() over (order by a.venta - a.real_ desc nulls last, o.nombre, o.id) as n
      from (select pv.origen_id, count(*)::int as vehiculos, sum(pv.venta) as venta, sum(pv.real_) as real_, sum(pv.cotizado) as cotizado
              from por_vehiculo pv group by pv.origen_id) a
      full join (select sv.origen_id, count(*)::int as n from sin_venta sv group by sv.origen_id) s on s.origen_id = a.origen_id
      join public.origenes o on o.id = coalesce(a.origen_id, s.origen_id)
  )
  select jsonb_build_object(
           'desde', p_desde, 'hasta', p_hasta, 'zona', v_zona, 'moneda', v_moneda,
           'vehiculos', t.vehiculos, 'venta', t.venta, 'real', t.real_, 'cotizado', t.cotizado, 'margen', t.venta - t.real_,
           'sin_venta', (select count(*)::int from sin_venta),
           'por_origen', (select coalesce(jsonb_agg(jsonb_build_object('origen_id', o.origen_id, 'nombre', o.nombre, 'vehiculos', o.vehiculos,
                                                                      'venta', o.venta, 'real', o.real_, 'cotizado', o.cotizado,
                                                                      'margen', o.margen, 'sin_venta', o.sin_venta) order by o.n), '[]'::jsonb)
                            from por_origen o where o.n <= 10),
           'por_origen_hay_mas', exists (select 1 from por_origen o where o.n > 10))
    into v
    from (select count(*)::int as vehiculos, sum(pv.venta) as venta, sum(pv.real_) as real_, sum(pv.cotizado) as cotizado
            from por_vehiculo pv) t;
  return v;
end;
$$;


ALTER FUNCTION "public"."tablero_margen"("p_desde" "date", "p_hasta" "date") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."tablero_margen"("p_desde" "date", "p_hasta" "date") IS 'Margen del período en moneda base: {desde, hasta, zona, moneda, vehiculos, venta, real, cotizado, margen, sin_venta, por_origen (hasta 10), por_origen_hay_mas}. Cohorte: el vehículo cuyo último pago confirmado cae en el período, con todos sus pagos confirmados (el mismo margen que margen_vehiculo; un mes pasado cambia si después se confirma o anula un pago). Nulos sin vehículos, nunca 0; sin_venta = pagos sin confirmar del período y ningún confirmado. Pide logistica.margen.ver y sólo mira sus orígenes (9.11, D1–D9).';



CREATE OR REPLACE FUNCTION "public"."tarea_completar"("p_tarea" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_completada" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.tareas; n public.tareas; yo uuid := (select auth.uid());
begin
  r := public._agenda_tarea_tomar(p_tarea);
  if yo is distinct from r.creado_por and yo is distinct from r.responsable_id then
    raise exception 'Sólo quien creó la tarea o su responsable pueden completarla.' using errcode = '42501';
  end if;
  if p_completada is null then
    raise exception 'Falta decir si la tarea queda completada.' using errcode = '22023', hint = 'completada';
  end if;
  if (r.estado = 'completado') = p_completada then
    return jsonb_build_object('resultado', 'sin_cambios', 'id', r.id, 'actualizado_en', r.actualizado_en);
  end if;
  perform public._exigir_version(r.actualizado_en, p_actualizado_en_esperado, 'Esta tarea cambió mientras la veías. Recarga para seguir desde la última versión.');
  update public.tareas x set
    estado = case when p_completada then 'completado'::public.estado_agenda else 'pendiente'::public.estado_agenda end,
    completada_en = case when p_completada then now() end
  where x.id = r.id
  returning * into n;
  if p_completada then
    perform public._agenda_tarea_accionar(n.id, n.responsable_id);
  end if;
  return jsonb_build_object('resultado', case when p_completada then 'completada' else 'reabierta' end, 'id', n.id, 'actualizado_en', n.actualizado_en);
end;
$$;


ALTER FUNCTION "public"."tarea_completar"("p_tarea" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_completada" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."tarea_completar"("p_tarea" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_completada" boolean) IS 'Completa o reabre una tarea (creador o responsable) con su versión (PT409); completar acciona la tarea_asignada. Responde {resultado, id, actualizado_en} (7.06-1).';



CREATE OR REPLACE FUNCTION "public"."tarea_crear"("p_id" "uuid", "p_datos" "jsonb", "p_conversacion" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.tareas; v public.tareas; yo uuid := (select auth.uid());
begin
  perform public.assert_activo();
  if p_id is null then
    raise exception 'Falta el identificador de la tarea.' using errcode = '22023', hint = 'id';
  end if;
  select * into r from public.tareas x where x.id = p_id;
  if found then
    if r.creado_por = yo then
      return jsonb_build_object('resultado', 'repetido', 'id', r.id, 'actualizado_en', r.actualizado_en);
    end if;
    raise exception 'No pudimos guardar esta tarea. Vuelve a intentarlo.' using errcode = '22023';
  end if;
  v := public._agenda_tarea_datos(v, p_datos);
  v.responsable_id := coalesce(v.responsable_id, yo);
  if v.responsable_id <> yo then
    perform public.assert_permiso('agenda.tareas.asignar');
    if not public._agenda_puede_recibir(v.responsable_id) then
      raise exception 'Esa persona no puede recibir tareas.' using errcode = '23514', hint = 'responsable_id';
    end if;
  end if;
  if p_conversacion is not null then
    if not public.es_miembro(p_conversacion) then
      raise exception 'No estás en esa conversación.' using errcode = '42501', hint = 'conversacion_id';
    end if;
    if not exists (select 1 from public.conversaciones_miembros cm where cm.conversacion_id = p_conversacion and cm.usuario_id = v.responsable_id) then
      raise exception 'Esa persona no está en la conversación de la tarea.' using errcode = '23514', hint = 'responsable_id';
    end if;
  end if;
  begin
    insert into public.tareas (id, titulo, descripcion, vence_en, responsable_id, creado_por, lead_id, vehiculo_id, cotizacion_id, conversacion_id, actualizado_en)
    values (p_id, v.titulo, v.descripcion, v.vence_en, v.responsable_id, yo, v.lead_id, v.vehiculo_id, v.cotizacion_id, p_conversacion, clock_timestamp())
    returning * into r;
  exception when unique_violation then
    select * into r from public.tareas x where x.id = p_id;
    if r.creado_por = yo then
      return jsonb_build_object('resultado', 'repetido', 'id', r.id, 'actualizado_en', r.actualizado_en);
    end if;
    raise exception 'No pudimos guardar esta tarea. Vuelve a intentarlo.' using errcode = '22023';
  end;
  return jsonb_build_object('resultado', 'creado', 'id', r.id, 'actualizado_en', r.actualizado_en);
end;
$$;


ALTER FUNCTION "public"."tarea_crear"("p_id" "uuid", "p_datos" "jsonb", "p_conversacion" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."tarea_crear"("p_id" "uuid", "p_datos" "jsonb", "p_conversacion" "uuid") IS 'Crea una tarea con el id del navegador. Para otro exige agenda.tareas.asignar y que reciba (activo, sin bloqueo, agenda.tareas.recibir); no vence en el pasado; con p_conversacion, los dos son miembros. Responde {resultado, id, actualizado_en} (7.06-1).';



CREATE OR REPLACE FUNCTION "public"."tarea_eliminar"("p_tarea" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.tareas; n public.tareas;
begin
  r := public._agenda_tarea_tomar(p_tarea);
  if r.creado_por is distinct from (select auth.uid()) then
    raise exception 'Sólo quien creó la tarea puede eliminarla.' using errcode = '42501';
  end if;
  perform public._exigir_version(r.actualizado_en, p_actualizado_en_esperado, 'Esta tarea cambió mientras la veías. Recarga para seguir desde la última versión.');
  update public.tareas x set eliminado_en = now() where x.id = r.id returning * into n;
  perform public._agenda_tarea_accionar(n.id, n.responsable_id);
  return jsonb_build_object('resultado', 'eliminada', 'id', n.id, 'actualizado_en', n.actualizado_en);
end;
$$;


ALTER FUNCTION "public"."tarea_eliminar"("p_tarea" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."tarea_eliminar"("p_tarea" "uuid", "p_actualizado_en_esperado" timestamp with time zone) IS 'Elimina una tarea propia (sólo el creador) con su versión (PT409) y acciona la tarea_asignada. Responde {resultado, id, actualizado_en} (7.06-1).';



CREATE OR REPLACE FUNCTION "public"."tarea_guardar"("p_tarea" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_datos" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare r public.tareas; v public.tareas; n public.tareas;
begin
  r := public._agenda_tarea_tomar(p_tarea);
  if r.creado_por is distinct from (select auth.uid()) then
    raise exception 'Sólo quien creó la tarea puede editarla.' using errcode = '42501';
  end if;
  if jsonb_typeof(p_datos) = 'object' and p_datos ? 'responsable_id' then
    raise exception 'Para cambiar el responsable, reasigna la tarea.' using errcode = '22023', hint = 'responsable_id';
  end if;
  v := public._agenda_tarea_datos(r, p_datos);
  if (v.titulo, v.descripcion, v.vence_en, v.lead_id, v.vehiculo_id, v.cotizacion_id)
     is not distinct from (r.titulo, r.descripcion, r.vence_en, r.lead_id, r.vehiculo_id, r.cotizacion_id) then
    return jsonb_build_object('resultado', 'sin_cambios', 'id', r.id, 'actualizado_en', r.actualizado_en);
  end if;
  perform public._exigir_version(r.actualizado_en, p_actualizado_en_esperado, 'Esta tarea cambió mientras la veías. Recarga para seguir desde la última versión.');
  update public.tareas x set
    titulo = v.titulo, descripcion = v.descripcion, vence_en = v.vence_en, lead_id = v.lead_id, vehiculo_id = v.vehiculo_id, cotizacion_id = v.cotizacion_id
  where x.id = r.id
  returning * into n;
  return jsonb_build_object('resultado', 'guardado', 'id', n.id, 'actualizado_en', n.actualizado_en);
end;
$$;


ALTER FUNCTION "public"."tarea_guardar"("p_tarea" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_datos" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."tarea_guardar"("p_tarea" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_datos" "jsonb") IS 'Guarda una tarea propia (sólo el creador) con su versión (PT409); el responsable no cambia aquí. Responde {resultado, id, actualizado_en} (7.06-1).';



CREATE OR REPLACE FUNCTION "public"."tarea_notificar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.responsable_id <> new.creado_por and (tg_op = 'INSERT' or new.responsable_id <> old.responsable_id) then
    perform public.notificar(new.responsable_id, 'tarea_asignada', 'Te asignaron una tarea', new.titulo, 'tarea', new.id, '/agenda?tarea=' || new.id, true);
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."tarea_notificar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tarea_validar"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.responsable_id <> (select auth.uid()) and not public.usuario_tiene_permiso(new.responsable_id, 'agenda.tareas.recibir') then
    raise exception 'Esa persona no puede recibir tareas.' using errcode = '23514';
  end if;
  if new.estado = 'completado' and new.completada_en is null then new.completada_en := now(); end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."tarea_validar"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tiene_permiso"("p_clave" "text", "p_origen" "uuid" DEFAULT NULL::"uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1 from public.mis_permisos() m
    where m.clave = p_clave and (m.origen_id is null or p_origen is null or m.origen_id = p_origen)
  );
$$;


ALTER FUNCTION "public"."tiene_permiso"("p_clave" "text", "p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tipo_cambio_crear"("p_clave" "text", "p_nombre" "text", "p_moneda_de" "text", "p_moneda_a" "text", "p_valor" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_clave text := lower(btrim(coalesce(p_clave, '')));
  v_de text := upper(btrim(coalesce(p_moneda_de, '')));
  v_a text := upper(btrim(coalesce(p_moneda_a, '')));
  v_id uuid;
begin
  perform public.assert_permiso('empresa.tipos_cambio.gestionar');
  if v_clave !~ '^[a-z][a-z0-9_]{1,30}$' then
    raise exception 'La clave va en minúsculas, sin espacios y empieza con una letra.';
  end if;
  if nullif(btrim(p_nombre), '') is null then
    raise exception 'El tipo de cambio necesita un nombre.';
  end if;
  -- NaN es mayor que cualquier número para Postgres: pasaría el `<= 0` y el CHECK de la tabla.
  if p_valor is null or p_valor = 'NaN'::numeric or p_valor <= 0 then
    raise exception 'El valor tiene que ser mayor que cero.';
  end if;
  if v_de = v_a then
    raise exception 'Un tipo de cambio va entre dos monedas distintas.';
  end if;
  if (select count(*) from public.monedas m where m.activa and m.codigo::text in (v_de, v_a)) <> 2 then
    raise exception 'Las dos monedas tienen que estar activas.';
  end if;
  if exists (select 1 from public.tipos_cambio t where t.clave = v_clave) then
    raise exception 'Ya existe un tipo de cambio con la clave «%».', v_clave using errcode = '23505';
  end if;
  insert into public.tipos_cambio (clave, nombre, moneda_de, moneda_a, valor, es_default, orden)
  values (v_clave, btrim(p_nombre), v_de, v_a, p_valor,
          not exists (select 1 from public.tipos_cambio t where t.moneda_de::text = v_de and t.moneda_a::text = v_a and t.es_default),
          (select coalesce(max(t.orden), -1) + 1 from public.tipos_cambio t))
  returning id into v_id;
  return v_id;
end;
$_$;


ALTER FUNCTION "public"."tipo_cambio_crear"("p_clave" "text", "p_nombre" "text", "p_moneda_de" "text", "p_moneda_a" "text", "p_valor" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tipo_cambio_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text" DEFAULT NULL::"text", "p_valor" numeric DEFAULT NULL::numeric, "p_activo" boolean DEFAULT NULL::boolean, "p_es_default" boolean DEFAULT NULL::boolean) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.tipos_cambio;
  v_nueva timestamptz;
begin
  perform public.assert_permiso('empresa.tipos_cambio.gestionar');
  select * into v from public.tipos_cambio t where t.id = p_id for update;
  if not found then
    raise exception 'Ese tipo de cambio ya no existe.' using errcode = 'PT409';
  end if;
  perform public._exigir_version(v.actualizado_en, p_actualizado_en_esperado, 'Otra persona cambió este tipo de cambio mientras lo editabas.');
  if p_valor is not null and (p_valor = 'NaN'::numeric or p_valor <= 0) then
    raise exception 'El valor tiene que ser mayor que cero.';
  end if;
  if v.es_default and p_es_default = false then
    raise exception 'Siempre hay un tipo de cambio por defecto entre dos monedas: marca otro para cambiarlo.';
  end if;
  if coalesce(p_es_default, v.es_default) and not coalesce(p_activo, v.activo) then
    raise exception 'El tipo de cambio por defecto no se desactiva: marca otro por defecto antes.';
  end if;
  if p_activo and not v.activo
     and (select count(*) from public.monedas m where m.activa and m.codigo in (v.moneda_de, v.moneda_a)) <> 2 then
    raise exception 'Para activarlo, las dos monedas tienen que estar activas.';
  end if;
  if p_es_default and not v.es_default then
    update public.tipos_cambio t set es_default = false
    where t.moneda_de = v.moneda_de and t.moneda_a = v.moneda_a and t.es_default and t.id <> v.id;
  end if;
  update public.tipos_cambio t set
    nombre = coalesce(nullif(btrim(p_nombre), ''), t.nombre),
    valor = coalesce(p_valor, t.valor),
    activo = coalesce(p_activo, t.activo),
    es_default = coalesce(p_es_default, t.es_default)
  where t.id = v.id
  returning t.actualizado_en into v_nueva;
  return v_nueva;
end;
$$;


ALTER FUNCTION "public"."tipo_cambio_guardar"("p_id" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_nombre" "text", "p_valor" numeric, "p_activo" boolean, "p_es_default" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."tipo_documento_crear"("p_id" "uuid", "p_flujo" "uuid", "p_datos" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  o public.tipos_documento; t public.tipos_documento; v_tope integer := public._tipos_documento_tope();
begin
  perform public._tipo_documento_exigir_permiso(p_flujo);
  if p_id is null then
    raise exception 'Falta el identificador del intento.' using errcode = '22023';
  end if;
  lock table public.tipos_documento in share row exclusive mode;
  select * into o from public.tipos_documento x where x.id = p_id;
  if found and o.flujo_id is not distinct from p_flujo then
    return jsonb_build_object('id', p_id, 'actualizado_en', o.actualizado_en, 'repetido', true);
  elsif found then
    raise exception 'Ese identificador ya es de otro tipo de documento.' using errcode = '22023';
  end if;
  if p_datos is not null and jsonb_typeof(p_datos) = 'object' and not (p_datos ? 'nombre') then
    raise exception 'Escribe el nombre del tipo de documento.' using errcode = '22023', hint = 'nombre';
  end if;
  t.id := p_id;
  t.flujo_id := p_flujo;
  t.activo := true;
  t.formatos := public._tipos_documento_formatos();
  t.modo_vencimiento := 'ninguno';
  t.visible_portal_permitido := false;
  t := public._tipo_documento_validar(public._tipo_documento_de_jsonb(t, p_datos, true), public._tipos_documento_formatos());
  if (select count(*) from (select 1 from public.tipos_documento x
                            where (p_flujo is null and x.flujo_id is null) or x.flujo_id = p_flujo limit v_tope) q) >= v_tope then
    raise exception 'Ya hay % tipos de documento en esta lista, que es el máximo. Elimina uno sin uso o desactiva los que no uses.', v_tope
      using errcode = '22023', hint = 'nombre';
  end if;
  perform public._tipo_documento_nombre_libre(t.id, t.flujo_id, t.nombre, t.activo);
  begin
    insert into public.tipos_documento (id, flujo_id, nombre, descripcion, activo, orden, visible_portal_permitido, modo_vencimiento,
                                        vigencia_dias, aviso_dias, formatos)
    values (t.id, t.flujo_id, t.nombre, t.descripcion, true,
            coalesce((select max(x.orden) + 10 from public.tipos_documento x
                      where (p_flujo is null and x.flujo_id is null) or x.flujo_id = p_flujo), 10),
            t.visible_portal_permitido, t.modo_vencimiento, t.vigencia_dias, t.aviso_dias, t.formatos)
    returning actualizado_en into t.actualizado_en;
  exception when unique_violation then
    raise exception 'Ya hay un tipo de documento «%».', t.nombre using errcode = '23505', hint = 'nombre';
  end;
  return jsonb_build_object('id', p_id, 'actualizado_en', t.actualizado_en, 'repetido', false);
end;
$$;


