CREATE OR REPLACE FUNCTION "public"."transicion_crear"("p_id" "uuid", "p_flujo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_de" "uuid", "p_a" "uuid", "p_accion" "text", "p_nota_obligatoria" boolean) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_de public.fases;
  v_a public.fases;
  v_accion text;
  v_restriccion text;
begin
  if p_id is null then
    raise exception 'Falta el id de la transición.' using errcode = '22023', hint = 'id';
  end if;
  if p_de is null then
    raise exception 'Elige la fase de origen.' using errcode = '22023', hint = 'de_fase_id';
  end if;
  if p_a is null then
    raise exception 'Elige la fase destino.' using errcode = '22023', hint = 'a_fase_id';
  end if;
  if p_de = p_a then
    raise exception 'Una transición no puede volver a la misma fase.' using errcode = '22023', hint = 'a_fase_id';
  end if;
  v_accion := public._transicion_accion(p_accion);
  perform public._flujo_para_editar(p_flujo, p_actualizado_en_esperado);

  select * into v_de from public.fases where id = p_de;
  select * into v_a from public.fases where id = p_a;
  if v_de.id is null or v_a.id is null then
    raise exception 'Esa fase ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  if v_de.flujo_id <> p_flujo then
    raise exception 'La fase «%» no es de este flujo.', v_de.nombre using errcode = '22023', hint = 'de_fase_id';
  end if;
  if v_a.flujo_id <> p_flujo then
    raise exception 'La fase «%» no es de este flujo.', v_a.nombre using errcode = '22023', hint = 'a_fase_id';
  end if;
  if not v_a.activa then
    raise exception 'La fase «%» está jubilada: no puede ser destino.', v_a.nombre using errcode = '22023', hint = 'a_fase_id';
  end if;

  begin
    insert into public.fases_transiciones (id, flujo_id, de_fase_id, a_fase_id, accion, nota_obligatoria)
    values (p_id, p_flujo, p_de, p_a, v_accion, coalesce(p_nota_obligatoria, false));
  exception when unique_violation then
    get stacked diagnostics v_restriccion = constraint_name;
    perform public._transicion_unico(v_restriccion, v_de.nombre, v_a.nombre);
    raise;
  end;
  return public._flujo_tocar(p_flujo);
end $$;


ALTER FUNCTION "public"."transicion_crear"("p_id" "uuid", "p_flujo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_de" "uuid", "p_a" "uuid", "p_accion" "text", "p_nota_obligatoria" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."transicion_crear"("p_id" "uuid", "p_flujo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_de" "uuid", "p_a" "uuid", "p_accion" "text", "p_nota_obligatoria" boolean) IS 'Crea una transición (5.05). Forma (22023 con hint: id, de_fase_id, a_fase_id, accion) → _flujo_para_editar (42501, PT409) → fase inexistente PT409; de otro flujo o destino jubilado 22023 con hint; (de, a) o id repetidos 23505 con hint. Devuelve la versión nueva del flujo.';



CREATE OR REPLACE FUNCTION "public"."transicion_eliminar"("p_transicion" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_flujo uuid;
begin
  select flujo_id into v_flujo from public.fases_transiciones where id = p_transicion;
  if v_flujo is null then
    raise exception 'Esta transición ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  perform public._flujo_para_editar(v_flujo, p_actualizado_en_esperado);
  delete from public.fases_transiciones where id = p_transicion;
  if not found then
    raise exception 'Esta transición ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  return public._flujo_tocar(v_flujo);
end $$;


ALTER FUNCTION "public"."transicion_eliminar"("p_transicion" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."transicion_eliminar"("p_transicion" "uuid", "p_actualizado_en_esperado" timestamp with time zone) IS 'Elimina una transición y sus roles (5.05). Inexistente → PT409; _flujo_para_editar (42501, PT409). Devuelve la versión nueva del flujo.';



CREATE OR REPLACE FUNCTION "public"."transicion_guardar"("p_transicion" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.fases_transiciones;
  v_flujo uuid;
  v_clave text;
  v_tipo text;
begin
  -- La forma, sin mirar el estado (va antes del permiso).
  if p_cambios is null or jsonb_typeof(p_cambios) <> 'object' then
    raise exception 'Faltan los datos de la transición.' using errcode = '22023';
  end if;
  if p_cambios = '{}'::jsonb then
    raise exception 'No hay cambios para guardar.' using errcode = '22023';
  end if;
  for v_clave, v_tipo in select key, jsonb_typeof(value) from jsonb_each(p_cambios) loop
    if v_clave not in ('accion', 'nota_obligatoria') then
      raise exception 'El dato «%» no se cambia desde una transición.', v_clave using errcode = '22023', hint = v_clave;
    end if;
    -- `nota_obligatoria` es not null: un null cae aquí y no en un 23502 crudo.
    if (v_clave = 'accion' and v_tipo not in ('string', 'null')) or (v_clave = 'nota_obligatoria' and v_tipo <> 'boolean') then
      raise exception 'El dato «%» no tiene el formato esperado.', v_clave using errcode = '22023', hint = v_clave;
    end if;
  end loop;
  if p_cambios ? 'accion' then
    perform public._transicion_accion(p_cambios ->> 'accion');
  end if;

  select flujo_id into v_flujo from public.fases_transiciones where id = p_transicion;
  if v_flujo is null then
    raise exception 'Esta transición ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  perform public._flujo_para_editar(v_flujo, p_actualizado_en_esperado);
  select * into v from public.fases_transiciones where id = p_transicion for no key update;
  if not found then
    raise exception 'Esta transición ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;

  if p_cambios ? 'accion' then
    v.accion := public._transicion_accion(p_cambios ->> 'accion');
  end if;
  if p_cambios ? 'nota_obligatoria' then
    v.nota_obligatoria := (p_cambios ->> 'nota_obligatoria')::boolean;
  end if;
  update public.fases_transiciones t set accion = v.accion, nota_obligatoria = v.nota_obligatoria where t.id = p_transicion;
  return public._flujo_tocar(v_flujo);
end $$;


ALTER FUNCTION "public"."transicion_guardar"("p_transicion" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."transicion_guardar"("p_transicion" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") IS 'Guarda una transición (5.05). Forma: sólo accion (texto o null, hasta 40) y nota_obligatoria (boolean); otra clave o tipo → 22023 con hint. Inexistente → PT409; _flujo_para_editar (42501, PT409). Devuelve la versión nueva del flujo.';



CREATE OR REPLACE FUNCTION "public"."transicion_roles_poner"("p_transicion" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_roles" "uuid"[]) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_flujo uuid;
  v_lista uuid[];
  v_antes uuid[];
begin
  select flujo_id into v_flujo from public.fases_transiciones where id = p_transicion;
  if v_flujo is null then
    raise exception 'Esta transición ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  perform public._flujo_para_editar(v_flujo, p_actualizado_en_esperado);
  if not exists (select 1 from public.fases_transiciones where id = p_transicion) then
    raise exception 'Esta transición ya no existe. Recarga e intenta de nuevo.' using errcode = 'PT409';
  end if;
  v_lista := public._roles_de_lista(p_roles);
  v_antes := array(select rol_id from public.fases_transiciones_roles where transicion_id = p_transicion order by rol_id);

  delete from public.fases_transiciones_roles where transicion_id = p_transicion and rol_id <> all (v_lista);
  insert into public.fases_transiciones_roles (transicion_id, rol_id) select p_transicion, r from unnest(v_lista) r on conflict do nothing;
  if v_antes is distinct from v_lista then
    perform public.registrar_actividad('transicion.roles_cambiados', 'fases_transiciones', p_transicion::text,
      jsonb_build_object('roles', to_jsonb(v_antes)), jsonb_build_object('roles', to_jsonb(v_lista)));
  end if;
  return public._flujo_tocar(v_flujo);
end $$;


ALTER FUNCTION "public"."transicion_roles_poner"("p_transicion" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_roles" "uuid"[]) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."transicion_roles_poner"("p_transicion" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_roles" "uuid"[]) IS 'Pone los roles que pueden mover por una transición (5.05), todo o nada; vacía = manda la lista de la fase destino. Inexistente → PT409; _flujo_para_editar (42501, PT409); la lista por _roles_de_lista (22023, hint roles). Actividad transicion.roles_cambiados {roles} sólo si cambia. Devuelve la versión nueva del flujo.';



CREATE OR REPLACE FUNCTION "public"."transporte_exigido"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_fase uuid; v_nombre text; r record; v_antes boolean; v_despues boolean; v_col text; v_dato text;
begin
  if old.sigue_al_vehiculo then
    return new;
  end if;
  if old.vehiculo_id is not null then
    select v.fase_id into v_fase from public.vehiculos v where v.id = old.vehiculo_id for share;
  else
    select i.fase_id into v_fase from public.repuestos_items i where i.id = old.repuesto_id for share;
  end if;
  if v_fase is null then
    return new;
  end if;
  -- Por fases_requisitos_fase_id_idx.
  for r in
    select distinct q.clave_dato from public.fases_requisitos q
     where q.fase_id = v_fase and q.tipo = 'dato' and q.bloqueante
       and q.clave_dato = any (array['transporte.naviera', 'transporte.contenedor', 'transporte.booking', 'transporte.zarpe', 'transporte.eta',
                                     'transporte.arribo'])
  loop
    -- El mismo criterio que `_requisito_dato_cumplido()`: contenedor y booking vacíos = ''.
    case r.clave_dato
      when 'transporte.naviera' then
        v_antes := old.naviera_id is not null; v_despues := new.naviera_id is not null; v_col := 'naviera_id'; v_dato := 'la naviera';
      when 'transporte.contenedor' then
        v_antes := coalesce(old.contenedor, '') <> ''; v_despues := coalesce(new.contenedor, '') <> ''; v_col := 'contenedor'; v_dato := 'el contenedor';
      when 'transporte.booking' then
        v_antes := coalesce(old.booking, '') <> ''; v_despues := coalesce(new.booking, '') <> ''; v_col := 'booking'; v_dato := 'el booking';
      when 'transporte.zarpe' then
        v_antes := old.zarpe_el is not null; v_despues := new.zarpe_el is not null; v_col := 'zarpe_el'; v_dato := 'el zarpe';
      when 'transporte.eta' then
        v_antes := old.eta_el is not null; v_despues := new.eta_el is not null; v_col := 'eta_el'; v_dato := 'la ETA';
      else
        v_antes := old.arribo_el is not null; v_despues := new.arribo_el is not null; v_col := 'arribo_el'; v_dato := 'el arribo';
    end case;
    if v_antes and not v_despues then
      select f.nombre into v_nombre from public.fases f where f.id = v_fase;
      raise exception 'La fase «%» exige %: no se puede vaciar.', v_nombre, v_dato using errcode = '23514', hint = v_col;
    end if;
  end loop;
  return new;
end;
$$;


ALTER FUNCTION "public"."transporte_exigido"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transporte_grupo"("p_tipo" "text", "p_clave" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_clave text := public._transporte_clave(p_tipo, p_clave);
  r public.transportes; v_n int := 0; v_ocultas boolean := false; v_unidades jsonb := '[]'::jsonb; v_titulo text; v_fase uuid; v_fase_nombre text;
begin
  perform public.assert_activo();
  if not (public.tiene_permiso('logistica.ver') or public.tiene_permiso('repuestos.ver')) then
    raise exception 'No tienes permiso para ver la logística.' using errcode = '42501';
  end if;
  for r in execute format('select t.* from public.transportes t where t.%I = $1 and '
    || '(exists (select 1 from public.vehiculos v where v.id = t.vehiculo_id and v.eliminado_en is null)'
    || ' or exists (select 1 from public.repuestos_items i where i.id = t.repuesto_id and i.eliminado_en is null))'
    || ' order by t.id limit 201', p_tipo) using v_clave
  loop
    v_n := v_n + 1;
    exit when v_n > 200;
    if not public.puede_unidad(r.vehiculo_id, r.repuesto_id, 'logistica.ver', 'repuestos.ver') then
      v_ocultas := true;
      continue;
    end if;
    if r.vehiculo_id is not null then
      select v.titulo, v.fase_id, f.nombre into v_titulo, v_fase, v_fase_nombre
        from public.vehiculos v left join public.fases f on f.id = v.fase_id where v.id = r.vehiculo_id;
    else
      select i.descripcion, i.fase_id, f.nombre into v_titulo, v_fase, v_fase_nombre
        from public.repuestos_items i left join public.fases f on f.id = i.fase_id where i.id = r.repuesto_id;
    end if;
    v_unidades := v_unidades || jsonb_build_object(
      'transporte_id', r.id, 'vehiculo_id', r.vehiculo_id, 'repuesto_id', r.repuesto_id, 'titulo', v_titulo, 'fase_id', v_fase, 'fase', v_fase_nombre,
      'naviera_id', r.naviera_id, 'puerto_origen_id', r.puerto_origen_id, 'puerto_destino_id', r.puerto_destino_id, 'contenedor', r.contenedor,
      'booking', r.booking, 'zarpe_el', r.zarpe_el, 'eta_el', r.eta_el, 'arribo_el', r.arribo_el, 'actualizado_en', r.actualizado_en,
      'editable', public.puede_unidad(r.vehiculo_id, r.repuesto_id, 'logistica.transporte.editar', 'repuestos.editar'));
  end loop;
  return jsonb_build_object('tipo', p_tipo, 'clave', v_clave, 'unidades', v_unidades, 'hay_mas', v_n > 200, 'hay_ocultas', v_ocultas);
end;
$_$;


ALTER FUNCTION "public"."transporte_grupo"("p_tipo" "text", "p_clave" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."transporte_grupo"("p_tipo" "text", "p_clave" "text") IS 'Las unidades de un embarque (p_tipo booking) o contenedor que quien mira ve, hasta 200 (paso 6.07-1): {tipo, clave, unidades, hay_mas, hay_ocultas}. Cada unidad con sus datos de transporte, su versión y editable.';



CREATE OR REPLACE FUNCTION "public"."transporte_grupo_aplicar"("p_tipo" "text", "p_clave" "text", "p_esperadas" "jsonb", "p_cambios" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_clave text := public._transporte_clave(p_tipo, p_clave);
  v_claves constant text[] := array['naviera_id', 'puerto_origen_id', 'puerto_destino_id', 'contenedor', 'booking', 'zarpe_el', 'eta_el', 'arribo_el'];
  v_esperadas uuid[]; v_ids uuid[]; r public.transportes; n public.transportes; u record; k text; v_titulo text;
  v_nueva text := v_clave; v_unidades jsonb := '[]'::jsonb; v_escribio boolean := false;
begin
  perform public.assert_activo();
  -- Sin la clave en ningún origen, 42501 antes de tomar un candado: ni bloquea filas que no puede leer ni distingue un booking que existe de uno que no.
  if not (public.tiene_permiso('logistica.transporte.editar') or public.tiene_permiso('repuestos.editar')) then
    raise exception 'No tienes permiso para editar el transporte.' using errcode = '42501';
  end if;
  -- C16 · {"<transporte_id>": "<actualizado_en>"} de 1 a 200 claves.
  if p_esperadas is null or jsonb_typeof(p_esperadas) <> 'object' then
    raise exception 'Las versiones del grupo van como un objeto.' using errcode = '22023', hint = 'esperadas';
  end if;
  for k in select x from jsonb_object_keys(p_esperadas) x loop
    if not pg_input_is_valid(k, 'uuid') or jsonb_typeof(p_esperadas -> k) <> 'string'
       or not pg_input_is_valid(p_esperadas ->> k, 'timestamptz') then
      raise exception 'Cada versión del grupo es {id: fecha}.' using errcode = '22023', hint = 'esperadas';
    end if;
    v_esperadas := array_append(v_esperadas, k::uuid);
  end loop;
  if coalesce(cardinality(v_esperadas), 0) not between 1 and 200 then
    raise exception 'Un grupo se edita con 1 a 200 unidades.' using errcode = '22023', hint = 'esperadas';
  end if;
  select array_agg(x order by x) into v_esperadas from unnest(v_esperadas) x;
  -- C17 · las filas de la clave en orden de id (por transportes_booking_idx o transportes_contenedor_idx). Una que salió del grupo mientras se esperaba
  -- el candado no cumple al re-evaluarse y no vuelve. Las de una unidad en la papelera no son del grupo (D19).
  execute format('select array_agg(x.id order by x.id) from (select t.id from public.transportes t where t.%I = $1 and '
    || '(exists (select 1 from public.vehiculos v where v.id = t.vehiculo_id and v.eliminado_en is null)'
    || ' or exists (select 1 from public.repuestos_items i where i.id = t.repuesto_id and i.eliminado_en is null))'
    || ' order by t.id limit 201 for update of t) x', p_tipo)
     into v_ids using v_clave;
  if coalesce(cardinality(v_ids), 0) > 200 then
    raise exception 'Un grupo se edita con hasta 200 unidades.' using errcode = '22023', hint = 'grupo';
  end if;
  for r in select * from public.transportes t where t.id = any (v_ids) order by t.id loop
    if not (public.puede_unidad(r.vehiculo_id, r.repuesto_id, 'logistica.ver', 'repuestos.ver')
            and public.puede_unidad(r.vehiculo_id, r.repuesto_id, 'logistica.transporte.editar', 'repuestos.editar')) then
      raise exception 'Hay unidades del grupo que no puedes editar.' using errcode = '42501';
    end if;
  end loop;
  if v_ids is distinct from v_esperadas then
    raise exception 'El grupo cambió mientras lo editabas. Recarga.' using errcode = 'PT409';
  end if;
  for r in select * from public.transportes t where t.id = any (v_ids) order by t.id loop
    if r.actualizado_en is distinct from (p_esperadas ->> r.id::text)::timestamptz then
      select coalesce(v.titulo, i.descripcion) into v_titulo
        from (select 1) uno left join public.vehiculos v on v.id = r.vehiculo_id left join public.repuestos_items i on i.id = r.repuesto_id;
      raise exception 'Otra persona cambió «%» mientras editabas el grupo. Recarga.', v_titulo using errcode = 'PT409';
    end if;
  end loop;
  -- C18 · las unidades de una sola pasada; el bucle ya no toma candados de unidad.
  perform public._transporte_grupo_bloquear(
    (select array_agg(t.vehiculo_id) from public.transportes t where t.id = any (v_ids) and t.vehiculo_id is not null),
    (select array_agg(t.repuesto_id) from public.transportes t where t.id = any (v_ids) and t.repuesto_id is not null));
  for r in select * from public.transportes t where t.id = any (v_ids) order by t.id loop
    n := public._transporte_cambios(r, p_cambios, v_claves);
    if p_cambios ? p_tipo then
      v_nueva := case when p_tipo = 'booking' then n.booking else n.contenedor end;
    end if;
    if (n.naviera_id, n.puerto_origen_id, n.puerto_destino_id, n.contenedor, n.booking, n.zarpe_el, n.eta_el, n.arribo_el)
       is distinct from
       (r.naviera_id, r.puerto_origen_id, r.puerto_destino_id, r.contenedor, r.booking, r.zarpe_el, r.eta_el, r.arribo_el) then
      select * into u from public._transporte_unidad(r.vehiculo_id, r.repuesto_id, false);
      perform public._transporte_validar(u.flujo, u.fase_id, r, n, u.titulo);
      update public.transportes x
         set naviera_id = n.naviera_id, puerto_origen_id = n.puerto_origen_id, puerto_destino_id = n.puerto_destino_id, contenedor = n.contenedor,
             booking = n.booking, zarpe_el = n.zarpe_el, eta_el = n.eta_el, arribo_el = n.arribo_el, actualizado_por = (select auth.uid())
       where x.id = r.id
      returning * into n;
      v_escribio := true;
    end if;
    v_unidades := v_unidades || jsonb_build_object('transporte_id', r.id, 'actualizado_en', n.actualizado_en);
  end loop;
  return jsonb_build_object('tipo', p_tipo, 'clave', v_nueva, 'unidades', v_unidades, 'sin_cambios', not v_escribio);
end;
$_$;


ALTER FUNCTION "public"."transporte_grupo_aplicar"("p_tipo" "text", "p_clave" "text", "p_esperadas" "jsonb", "p_cambios" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."transporte_grupo_aplicar"("p_tipo" "text", "p_clave" "text", "p_esperadas" "jsonb", "p_cambios" "jsonb") IS 'Aplica los mismos cambios (sin notas) a todas las unidades de un embarque o contenedor, todo o nada (paso 6.07-1). p_esperadas = {transporte_id: actualizado_en} de todo el grupo. 42501 si alguna no se puede editar; PT409 si el grupo o una versión cambió. Devuelve {tipo, clave, unidades, sin_cambios}.';



CREATE OR REPLACE FUNCTION "public"."transporte_grupos"("p_tipo" "text", "p_desde" "text", "p_tope" integer, "p_filtros" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  -- TAMANO_DE_PAGINA_POR_DEFECTO (50), máximo 100.
  v_tope integer := public._acotar_pagina(p_tope, 50, 100);
  -- D35 · a lo sumo 2.000 filas de transportes por llamada; cada clave suma al menos 1 (también la que sólo tiene unidades en la papelera).
  v_recorrido constant integer := 2000;
  v_yo uuid := (select auth.uid());
  f record;
  v_todos uuid[]; v_algun uuid[]; v_repuestos boolean;
  v_ge text; v_gt text; v_k text;
  v_filas jsonb; g record;
  v_mirado integer := 0; v_n integer := 0;
  v_grupos jsonb := '[]'::jsonb; v_ultima text; v_siguiente text; v_cortada boolean := false; v_desde uuid;
  v_varios text[];
begin
  perform public.assert_activo();
  -- C17 · el tipo aquí, no con _transporte_clave: esa función lanza con la clave nula y el cursor vacío es válido.
  if p_tipo is null or p_tipo not in ('booking', 'contenedor') then
    raise exception 'El grupo es por booking o por contenedor.' using errcode = '22023', hint = 'tipo';
  end if;
  if not (public.tiene_permiso('logistica.ver') or public.tiene_permiso('repuestos.ver')) then
    raise exception 'No tienes permiso para ver la logística.' using errcode = '42501';
  end if;
  select * into f from public._transporte_grupos_filtros(p_filtros);
  -- D37 · la visibilidad resuelta una vez: los orígenes de logistica.ver (lo de puede_vehiculo) y repuestos.ver (lo de puede_repuesto).
  v_todos := public.origenes_con_alcance('logistica.ver', 'todos');
  v_algun := public.origenes_con_alcance('logistica.ver', 'propios');
  v_repuestos := public.tiene_permiso('repuestos.ver');
  -- C18, C23 · la clave siguiente es min(clave) con clave >= prefijo y clave > la última mirada ('' = desde el principio: ninguna clave es vacía).
  v_ge := coalesce(f.prefijo, '');
  -- D43 · el cursor es el id de una fila de transportes con la última clave (la `siguiente` de la página anterior), no la clave: una clave sólo de
  -- unidades que quien llama no ve nunca sale. Se resuelve aquí, por la PK; si la fila ya no existe o perdió la clave, la lista vuelve a empezar.
  v_gt := '';
  if nullif(btrim(p_desde), '') is not null then
    if not pg_input_is_valid(btrim(p_desde), 'uuid') then
      raise exception 'El cursor de la lista no se entiende.' using errcode = '22023', hint = 'cursor';
    end if;
    v_desde := btrim(p_desde)::uuid;
    select case p_tipo when 'booking' then t.booking else t.contenedor end into v_gt from public.transportes t where t.id = v_desde;
    if v_gt is null then
      raise exception 'La lista cambió: vuelve a empezar.' using errcode = '22023', hint = 'cursor';
    end if;
  end if;
  loop
    -- Una sonda por el índice parcial de su tipo: transportes_booking_idx o transportes_contenedor_idx (clave > x implica not null).
    if p_tipo = 'booking' then
      select min(t.booking) into v_k from public.transportes t where t.booking >= v_ge and t.booking > v_gt;
    else
      select min(t.contenedor) into v_k from public.transportes t where t.contenedor >= v_ge and t.contenedor > v_gt;
    end if;
    -- Índice agotado, o fuera del bloque del prefijo (D39: se compara la forma normalizada, para que una clave vieja sin normalizar no corte).
    exit when v_k is null or (f.prefijo is not null and not starts_with(upper(regexp_replace(v_k, '\s', '', 'g')), f.prefijo));
    -- C19 · las filas de la clave, hasta 201, por el mismo índice; sin las de unidades en la papelera (D19, por las PK).
    if p_tipo = 'booking' then
      select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) into v_filas from (
        select t.vehiculo_id, t.repuesto_id, t.naviera_id, t.puerto_origen_id, t.puerto_destino_id, t.zarpe_el, t.eta_el, t.arribo_el
          from public.transportes t
         where t.booking = v_k
           and (exists (select 1 from public.vehiculos v where v.id = t.vehiculo_id and v.eliminado_en is null)
                or exists (select 1 from public.repuestos_items i where i.id = t.repuesto_id and i.eliminado_en is null))
         limit 201) x;
    else
      select coalesce(jsonb_agg(to_jsonb(x)), '[]'::jsonb) into v_filas from (
        select t.vehiculo_id, t.repuesto_id, t.naviera_id, t.puerto_origen_id, t.puerto_destino_id, t.zarpe_el, t.eta_el, t.arribo_el
          from public.transportes t
         where t.contenedor = v_k
           and (exists (select 1 from public.vehiculos v where v.id = t.vehiculo_id and v.eliminado_en is null)
                or exists (select 1 from public.repuestos_items i where i.id = t.repuesto_id and i.eliminado_en is null))
         limit 201) x;
    end if;
    -- C20–C22 · por grupo, sobre las que se ven: cuántas, si alguna cumple los filtros (D36) y cada dato común o «varios».
    select count(*)::integer as filas,
           count(*) filter (where r.visible)::integer as unidades,
           coalesce(bool_or(not r.visible), false) as ocultas,
           coalesce(bool_or(r.visible
                            and (f.naviera is null or r.naviera_id = f.naviera)
                            and (f.puerto_origen is null or r.puerto_origen_id = f.puerto_origen)
                            and (f.puerto_destino is null or r.puerto_destino_id = f.puerto_destino)
                            and (f.en_transito is null or (r.arribo_el is null) = f.en_transito)), false) as cumple,
           count(distinct coalesce(r.naviera_id::text, '')) filter (where r.visible) as d_naviera, min(r.naviera_id::text) filter (where r.visible) as naviera,
           count(distinct coalesce(r.puerto_origen_id::text, '')) filter (where r.visible) as d_po, min(r.puerto_origen_id::text) filter (where r.visible) as po,
           count(distinct coalesce(r.puerto_destino_id::text, '')) filter (where r.visible) as d_pd, min(r.puerto_destino_id::text) filter (where r.visible) as pd,
           count(distinct coalesce(r.zarpe_el::text, '')) filter (where r.visible) as d_zarpe, min(r.zarpe_el) filter (where r.visible) as zarpe,
           count(distinct coalesce(r.eta_el::text, '')) filter (where r.visible) as d_eta, min(r.eta_el) filter (where r.visible) as eta,
           count(distinct coalesce(r.arribo_el::text, '')) filter (where r.visible) as d_arribo, min(r.arribo_el) filter (where r.visible) as arribo
      into g
      from (select x.*,
                   coalesce(case when x.vehiculo_id is not null
                                 then v.origen_id = any (v_algun)
                                      and (v.origen_id = any (v_todos) or v.creado_por = v_yo or (v.lead_id is not null and public.en_cartera(v.lead_id)))
                                 else v_repuestos end, false) as visible
              from jsonb_to_recordset(v_filas) as x (vehiculo_id uuid, repuesto_id uuid, naviera_id uuid, puerto_origen_id uuid, puerto_destino_id uuid,
                                                     zarpe_el date, eta_el date, arribo_el date)
              left join public.vehiculos v on v.id = x.vehiculo_id) r;
    v_mirado := v_mirado + greatest(g.filas, 1);
    if g.unidades > 0 and g.cumple then
      -- C24 · con la página llena, éste es el que dice que hay otra: la siguiente empieza después del último devuelto.
      if v_n = v_tope then
        v_siguiente := v_ultima;
        exit;
      end if;
      v_varios := array_remove(array[
        case when g.d_naviera > 1 then 'naviera_id' end, case when g.d_po > 1 then 'puerto_origen_id' end,
        case when g.d_pd > 1 then 'puerto_destino_id' end, case when g.d_zarpe > 1 then 'zarpe_el' end,
        case when g.d_eta > 1 then 'eta_el' end, case when g.d_arribo > 1 then 'arribo_el' end], null);
      v_grupos := v_grupos || jsonb_build_object(
        'clave', v_k, 'unidades', least(g.unidades, 200), 'hay_mas', g.filas > 200, 'hay_ocultas', g.ocultas,
        'naviera_id', case when g.d_naviera = 1 then g.naviera::uuid end,
        'puerto_origen_id', case when g.d_po = 1 then g.po::uuid end,
        'puerto_destino_id', case when g.d_pd = 1 then g.pd::uuid end,
        'zarpe_el', case when g.d_zarpe = 1 then g.zarpe end,
        'eta_el', case when g.d_eta = 1 then g.eta end,
        'arribo_el', case when g.d_arribo = 1 then g.arribo end,
        'varios', to_jsonb(v_varios));
      v_n := v_n + 1;
      v_ultima := v_k;
    end if;
    v_gt := v_k;
    -- D35 · el recorrido, mirado al cerrar cada grupo. Con la página llena, no se sabe si hay otra: se sigue desde el último devuelto. Si no, se
    -- sigue desde la última clave mirada y `cortada` le dice a la pantalla que ofrezca «Seguir buscando».
    if v_mirado >= v_recorrido then
      if v_n = v_tope then
        v_siguiente := v_ultima;
      else
        v_siguiente := v_k;
        v_cortada := true;
      end if;
      exit;
    end if;
  end loop;
  -- D43 · `siguiente` sale como el id de una fila con esa clave (por el mismo índice parcial).
  if v_siguiente is not null then
    if p_tipo = 'booking' then
      select t.id::text into v_siguiente from public.transportes t where t.booking = v_siguiente limit 1;
    else
      select t.id::text into v_siguiente from public.transportes t where t.contenedor = v_siguiente limit 1;
    end if;
  end if;
  return jsonb_build_object('tipo', p_tipo, 'grupos', v_grupos, 'siguiente', v_siguiente, 'cortada', v_cortada);
end;
$$;


ALTER FUNCTION "public"."transporte_grupos"("p_tipo" "text", "p_desde" "text", "p_tope" integer, "p_filtros" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."transporte_grupos"("p_tipo" "text", "p_desde" "text", "p_tope" integer, "p_filtros" "jsonb") IS 'Los grupos de transporte (p_tipo booking o contenedor) por cursor sobre la clave, con filtros naviera, puerto_origen, puerto_destino, en_transito y prefijo (6.07-3). Devuelve {tipo, grupos, siguiente, cortada}: por grupo clave, unidades que quien mira ve (hasta 200), hay_mas, hay_ocultas, naviera, puertos y fechas comunes y varios con las que difieren. siguiente es opaco (el id de una fila, D43): se pasa tal cual como p_desde. Mira a lo sumo 2.000 filas por llamada; cortada si paró por eso antes de llenar la página. Pide logistica.ver o repuestos.ver.';



CREATE OR REPLACE FUNCTION "public"."transporte_guardar"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  t public.transportes; n public.transportes; u record; v_hay boolean;
  v_sujeto constant text := 'el transporte de esta unidad';
begin
  perform public.assert_activo();
  if num_nonnulls(p_vehiculo, p_repuesto) <> 1 then
    raise exception 'Una unidad por vez.' using errcode = '22023', hint = 'unidad';
  end if;
  -- C5 · el permiso del origen antes del candado: quien no puede no espera a nadie. Cubre la unidad inexistente o en la papelera.
  if not public.puede_unidad(p_vehiculo, p_repuesto, 'logistica.transporte.editar', 'repuestos.editar') then
    raise exception 'No tienes el permiso «%» de esta unidad.', case when p_vehiculo is not null then 'logistica.transporte.editar' else 'repuestos.editar' end
      using errcode = '42501';
  end if;
  -- C6 · unidad antes que fila, siempre. Por transportes_vehiculo_id_key o transportes_repuesto_id_key.
  select * into u from public._transporte_unidad(p_vehiculo, p_repuesto, true);
  if p_vehiculo is not null then
    select * into t from public.transportes x where x.vehiculo_id = p_vehiculo for update;
  else
    select * into t from public.transportes x where x.repuesto_id = p_repuesto for update;
  end if;
  v_hay := found;
  -- C7 · la esperada nula es crear: si la fila ya existe, PT409 aunque no haya diferencias (D11).
  if v_hay and p_actualizado_en_esperado is null then
    perform public._conflicto_de_edicion('transportes', t.id, t.actualizado_en, v_sujeto);
  end if;
  if not v_hay then
    t.vehiculo_id := p_vehiculo;
    t.repuesto_id := p_repuesto;
    t.sigue_al_vehiculo := false;
  end if;
  n := public._transporte_cambios(t, p_cambios,
    array['naviera_id', 'puerto_origen_id', 'puerto_destino_id', 'contenedor', 'booking', 'zarpe_el', 'eta_el', 'arribo_el', 'notas']);
  if (n.naviera_id, n.puerto_origen_id, n.puerto_destino_id, n.contenedor, n.booking, n.zarpe_el, n.eta_el, n.arribo_el, n.notas)
     is not distinct from
     (t.naviera_id, t.puerto_origen_id, t.puerto_destino_id, t.contenedor, t.booking, t.zarpe_el, t.eta_el, t.arribo_el, t.notas) then
    return jsonb_build_object('id', t.id, 'actualizado_en', t.actualizado_en, 'sin_cambios', true);
  end if;
  -- C8 · la versión.
  if not v_hay and p_actualizado_en_esperado is not null then
    raise exception 'El transporte de esta unidad ya no existe. Recarga.' using errcode = 'PT409';
  end if;
  if v_hay and t.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._conflicto_de_edicion('transportes', t.id, t.actualizado_en, v_sujeto);
  end if;
  -- C9 · validar y escribir.
  perform public._transporte_validar(u.flujo, u.fase_id, t, n, null);
  if not v_hay then
    insert into public.transportes (vehiculo_id, repuesto_id, naviera_id, puerto_origen_id, puerto_destino_id, contenedor, booking, zarpe_el, eta_el,
                                    arribo_el, notas, actualizado_por)
    values (p_vehiculo, p_repuesto, n.naviera_id, n.puerto_origen_id, n.puerto_destino_id, n.contenedor, n.booking, n.zarpe_el, n.eta_el,
            n.arribo_el, n.notas, (select auth.uid()))
    on conflict do nothing
    returning * into n;
    if not found then
      raise exception 'Otra persona cargó el transporte de esta unidad mientras lo editabas. Recarga.' using errcode = 'PT409';
    end if;
  else
    update public.transportes x
       set naviera_id = n.naviera_id, puerto_origen_id = n.puerto_origen_id, puerto_destino_id = n.puerto_destino_id, contenedor = n.contenedor,
           booking = n.booking, zarpe_el = n.zarpe_el, eta_el = n.eta_el, arribo_el = n.arribo_el, notas = n.notas,
           actualizado_por = (select auth.uid())
     where x.id = t.id
    returning * into n;
  end if;
  return jsonb_build_object('id', n.id, 'actualizado_en', n.actualizado_en, 'sin_cambios', false);
end;
$$;


ALTER FUNCTION "public"."transporte_guardar"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."transporte_guardar"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") IS 'Guarda el transporte 1:1 de una unidad (paso 6.07-1). p_cambios: naviera_id, puerto_origen_id, puerto_destino_id, contenedor, booking, zarpe_el, eta_el, arribo_el, notas (null = vaciar). Esperada nula = crear; si ya existe, PT409. Devuelve {id, actualizado_en, sin_cambios}.';



CREATE OR REPLACE FUNCTION "public"."trg_tramo_sin_solape"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare o public.repuestos_tramos_logistica;
begin
  if not new.activo then
    return new;
  end if;
  perform 1 from public.monedas m where m.codigo = new.moneda for no key update;
  select * into o
    from public.repuestos_tramos_logistica t
   where t.moneda = new.moneda and t.activo and t.id <> new.id
     and new.costo_min < coalesce(t.costo_max, 'infinity'::numeric)
     and t.costo_min < coalesce(new.costo_max, 'infinity'::numeric)
   order by t.costo_min
   limit 1;
  if found then
    raise exception 'Ese tramo se cruza con otro de % (%).', btrim(new.moneda),
      case when o.costo_max is null then 'de ' || replace(o.costo_min::text, '.', ',') || ' en adelante'
           else 'de ' || replace(o.costo_min::text, '.', ',') || ' a ' || replace(o.costo_max::text, '.', ',') end
      using errcode = '23P01', hint = 'costo_min';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."trg_tramo_sin_solape"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unidad_llego_a_fase"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_fase" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1 from public.historial_fases h
    where h.a_fase_id = p_fase and h.vehiculo_id is not distinct from p_vehiculo and h.repuesto_id is not distinct from p_repuesto
  ) or exists (
    select 1 from public.fases actual join public.fases destino on destino.id = p_fase
    where actual.id = coalesce((select v.fase_id from public.vehiculos v where v.id = p_vehiculo), (select i.fase_id from public.repuestos_items i where i.id = p_repuesto))
      and actual.flujo_id = destino.flujo_id and not actual.es_final and actual.orden > destino.orden
  );
$$;


ALTER FUNCTION "public"."unidad_llego_a_fase"("p_vehiculo" "uuid", "p_repuesto" "uuid", "p_fase" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."usuario_tiene_permiso"("p_usuario" "uuid", "p_clave" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (select 1 from public.usuarios_roles ur join public.roles_permisos rp on rp.rol_id = ur.rol_id where ur.usuario_id = p_usuario and rp.permiso_clave = p_clave);
$$;


ALTER FUNCTION "public"."usuario_tiene_permiso"("p_usuario" "uuid", "p_clave" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validar_diseno"("p_def" "jsonb", "p_diseno" "jsonb", "p_niveles" "text"[], "p_retirados" "text"[], "p_tonos" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_nodos jsonb;
  v_buckets jsonb;
  v_total_en text;
  v_grupos jsonb;
  v_pos jsonb;
  v_ids text[];
  v_tipos text[];
  v_ops text[];
  v_salidas text[];
  v_sobres boolean[];
  v_pcts text[];
  v_cond jsonb;
  v_req jsonb;
  v_niv jsonb;
  v_ret jsonb;
  v_ton jsonb;
  v_g jsonb;
  v_modos jsonb;
  v_max integer;
  v_items integer := 0;
  v_aux jsonb;
  v_tipos_hoja text[];
begin
  -- §0 la forma.
  perform public._diseno_forma(p_diseno);

  -- §0b el tamaño (4-30): sólo contar, antes que todo lo demás. `donde` es la sección en la que la suma pasa del tope.
  v_max := public._diseno_maximo_de_items();
  for i in 0 .. jsonb_array_length(p_diseno -> 'secciones') - 1 loop
    v_items := v_items + jsonb_array_length(p_diseno -> 'secciones' -> i -> 'items');
    if v_items > v_max then
      perform public._formula_rechazar('demasiados_items', p_diseno -> 'secciones' -> i ->> 'id',
        format('La hoja admite hasta %s ítems y el diseño pasa de ese tope en «%s»: quita alguno.', v_max,
               p_diseno -> 'secciones' -> i ->> 'id'));
    end if;
  end loop;

  -- La fórmula, desarmada una vez: un id, una posición.
  v_nodos := p_def -> 'nodos';
  v_buckets := p_def -> 'buckets';
  v_total_en := p_def ->> 'total_en';
  v_grupos := coalesce(p_def -> 'grupos', '[]'::jsonb);
  select coalesce(jsonb_object_agg(x.value ->> 'id', x.pos), '{}'::jsonb),
         array_agg(x.value ->> 'id' order by x.pos),
         array_agg(x.value ->> 'tipo' order by x.pos),
         array_agg(x.value ->> 'op' order by x.pos),
         array_agg(x.value ->> 'salida' order by x.pos),
         array_agg(coalesce(x.value -> 'sobrescribible' = 'true'::jsonb, false) order by x.pos),
         array_agg(x.value ->> 'pct' order by x.pos),
         coalesce(jsonb_object_agg(x.value ->> 'condicion', true) filter (where x.value ->> 'condicion' is not null), '{}'::jsonb),
         coalesce(jsonb_object_agg(x.value ->> 'requerido_si', true) filter (where x.value ->> 'requerido_si' is not null), '{}'::jsonb)
    into v_pos, v_ids, v_tipos, v_ops, v_salidas, v_sobres, v_pcts, v_cond, v_req
    from jsonb_array_elements(v_nodos) with ordinality as x(value, pos);

  -- Las auxiliares de los textos (4.21-3b-2): una constante auxiliar no pide celda en §5.
  v_aux := public._diseno_auxiliares(p_def);
  v_tipos_hoja := array(select case when t.tipo = 'constante' and v_aux ? t.id then 'constante_auxiliar' else t.tipo end
                          from unnest(v_ids, v_tipos) with ordinality as t(id, tipo, ord)
                         order by t.ord);

  -- El contexto, como conjuntos.
  select coalesce(jsonb_object_agg(x, true), '{}'::jsonb) into v_niv from unnest(p_niveles) x where x is not null;
  select coalesce(jsonb_object_agg(x, true), '{}'::jsonb) into v_ret from unnest(p_retirados) x where x is not null;
  select coalesce(jsonb_object_agg(x, true), '{}'::jsonb) into v_ton from unnest(p_tonos) x where x is not null;

  -- §1 los modos.
  v_modos := p_diseno -> 'cabecera' -> 'modos';
  perform public._diseno_modos(v_modos, v_buckets, coalesce(cardinality(array(select jsonb_object_keys(v_buckets))), 0),
                               v_total_en, v_pos, v_tipos);

  -- §2 a §5 las secciones, la tarjeta, los atajos y la cobertura.
  perform public._diseno_secciones(p_diseno -> 'secciones', p_diseno -> 'tarjeta_total', v_ids, v_tipos_hoja, v_ops, v_salidas, v_sobres, v_pcts,
                                   v_pos, v_cond, v_req, v_niv, v_ret);

  -- §6 el tono de cada grupo de la fórmula está en el catálogo de la empresa.
  for i in 0 .. jsonb_array_length(v_grupos) - 1 loop
    v_g := v_grupos -> i;
    if not coalesce(v_ton ? (v_g ->> 'tono'), false) then
      perform public._formula_rechazar('tono_inexistente', v_g ->> 'id',
        format('El grupo «%s» usa un tono que no está en el catálogo.', v_g ->> 'id'));
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."validar_diseno"("p_def" "jsonb", "p_diseno" "jsonb", "p_niveles" "text"[], "p_retirados" "text"[], "p_tonos" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."validar_formula"("p_def" "jsonb", "p_params" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_nodos jsonb;
  v_n int;
  v_pos jsonb;            -- id → posición (1..n); con un id repetido, la última, como el `pos.set` de TS
  v_ids text[];
  v_tipos text[];
  v_formatos text[];      -- `formato`, o `usd` si no lo trae
  v_sobres boolean[];     -- `sobrescribible: true`
  v_constantes jsonb;     -- el conjunto de ids de los nodos `constante`
  v_total int;            -- el primer nodo con `salida: total`
  v_totales int;
  v_nodo jsonb;
  v_x jsonb;
  v_id text;
  v_tipo text;
  v_ref text;
  v_papel text;
  v_otro text;
  v_refs text[];
  v_papeles text[];
  v_lectores_ref text[] := '{}';   -- cada arista (quien lee → qué lee), en el orden de los nodos y de sus referencias
  v_lectores_de text[] := '{}';
  v_lectores jsonb;                -- id leído → [primer lector, otro lector distinto]
  v_mal boolean;
  i int;
  j int;
  k int;
begin
  -- §0 la forma.
  perform public._formula_forma(p_def, p_params);
  v_nodos := p_def -> 'nodos';
  v_n := jsonb_array_length(v_nodos);

  -- §1 el índice (indexar): un id, un solo nodo.
  select coalesce(jsonb_object_agg(x.value ->> 'id', x.pos order by x.pos), '{}'::jsonb),
         array_agg(x.value ->> 'id' order by x.pos),
         array_agg(x.value ->> 'tipo' order by x.pos),
         array_agg(coalesce(x.value ->> 'formato', 'usd') order by x.pos),
         array_agg(coalesce(x.value -> 'sobrescribible' = 'true'::jsonb, false) order by x.pos),
         coalesce(jsonb_object_agg(x.value ->> 'id', true) filter (where x.value ->> 'tipo' = 'constante'), '{}'::jsonb),
         coalesce(sum(case when x.value ->> 'salida' = 'total' then 1 else 0 end), 0),
         min(x.pos) filter (where x.value ->> 'salida' = 'total')
    into v_pos, v_ids, v_tipos, v_formatos, v_sobres, v_constantes, v_totales, v_total
    from jsonb_array_elements(v_nodos) with ordinality as x(value, pos);
  select d.id into v_id
    from (select x.value ->> 'id' as id, x.pos, min(x.pos) over (partition by x.value ->> 'id') as primera
            from jsonb_array_elements(v_nodos) with ordinality as x(value, pos)) d
   where d.pos > d.primera
   order by d.pos
   limit 1;
  if v_id is not null then
    perform public._formula_rechazar('nodo_duplicado', v_id, format('Hay dos nodos con el id «%s».', v_id));
  end if;

  -- §2 las referencias (revisarReferencias): existen, van hacia atrás y nombran el tipo que corresponde. En el orden de
  -- `referenciasDe()`. De paso se anotan las aristas, que §5 usa para saber quién lee cada nodo.
  for i in 1 .. v_n loop
    v_nodo := v_nodos -> (i - 1);
    v_id := v_ids[i];
    v_tipo := v_tipos[i];
    v_refs := '{}';
    v_papeles := '{}';
    if v_tipo = 'input' then
      if v_nodo ? 'sugerido_de' then v_refs := array_append(v_refs, v_nodo ->> 'sugerido_de'); v_papeles := array_append(v_papeles, 'sugerido_de'); end if;
      if v_nodo ? 'requerido_si' then v_refs := array_append(v_refs, v_nodo ->> 'requerido_si'); v_papeles := array_append(v_papeles, 'requerido_si'); end if;
    elsif v_tipo = 'tabla' then
      -- Los valores de `match`, en el orden de sus claves en jsonb.
      for v_ref in select m.value from jsonb_each_text(v_nodo -> 'match') m loop
        v_refs := array_append(v_refs, v_ref);
        v_papeles := array_append(v_papeles, 'match');
      end loop;
    elsif v_tipo = 'tramo' then
      v_refs := array_append(v_refs, v_nodo ->> 'sobre');
      v_papeles := array_append(v_papeles, 'sobre');
    elsif v_tipo = 'calculo' then
      v_x := v_nodo -> 'de';
      for k in 0 .. jsonb_array_length(v_x) - 1 loop
        v_refs := array_append(v_refs, v_x ->> k);
        v_papeles := array_append(v_papeles, 'de');
      end loop;
      if v_nodo ->> 'op' = 'porcentaje_de' then v_refs := array_append(v_refs, v_nodo ->> 'pct'); v_papeles := array_append(v_papeles, 'pct'); end if;
      if v_nodo ->> 'op' = 'depreciar' then v_refs := array_append(v_refs, v_nodo ->> 'sobre'); v_papeles := array_append(v_papeles, 'sobre'); end if;
    end if;
    -- `condicion` va al final en los tipos que la admiten (la forma ya sacó a los demás).
    if v_tipo in ('input', 'constante', 'tabla', 'tramo', 'calculo') and v_nodo ? 'condicion' then
      v_refs := array_append(v_refs, v_nodo ->> 'condicion');
      v_papeles := array_append(v_papeles, 'condicion');
    end if;

    for k in 1 .. coalesce(array_length(v_refs, 1), 0) loop
      v_ref := v_refs[k];
      v_papel := v_papeles[k];
      v_lectores_ref := array_append(v_lectores_ref, v_ref);
      v_lectores_de := array_append(v_lectores_de, v_id);
      j := (v_pos ->> v_ref)::int;
      if j is null then
        -- Un `match` que no nombra un nodo nombra un campo del vehículo.
        continue when v_papel = 'match';
        perform public._formula_rechazar('referencia_inexistente', v_id,
          format('«%s» usa «%s», que no es un nodo de la fórmula.', v_id, v_ref));
        continue;
      end if;
      if j = i then
        perform public._formula_rechazar('ciclo', v_id, format('«%s» se usa a sí mismo: sería un ciclo.', v_id));
      end if;
      if j > i then
        perform public._formula_rechazar('referencia_hacia_adelante', v_id,
          format('«%s» usa «%s», que está después en la lista: el orden de la lista es el de evaluación y sólo se usa lo anterior.', v_id, v_ref));
      end if;
      if v_papel in ('condicion', 'requerido_si') and v_tipos[j] <> 'bandera' then
        perform public._formula_rechazar('referencia_de_tipo', v_id,
          format('«%s» usa «%s» como %s, y tiene que ser %s.', v_id, v_ref, v_papel, 'una bandera'));
      end if;
      if v_tipos[j] = 'opcion' and v_papel <> 'match' then
        perform public._formula_rechazar('referencia_de_tipo', v_id,
          format('«%s» usa «%s» como %s, y tiene que ser %s.', v_id, v_ref, v_papel,
                 'un número (la variante se nombra en «solo_en» o en un «match»)'));
      end if;
    end loop;
  end loop;

  -- §3 el total (revisarTotal).
  if v_totales <> 1 then
    perform public._formula_rechazar('total_unico', null,
      format('La fórmula necesita exactamente un nodo con salida «total» (hay %s).', v_totales));
  end if;
  if v_total is not null then
    v_nodo := v_nodos -> (v_total - 1);
    v_tipo := v_tipos[v_total];
    -- soloEnDe, condicionDe y sobrescribibleDe: cada uno sólo en los tipos que lo admiten.
    if (v_tipo not in ('tipo_cambio', 'opcion') and v_nodo ? 'solo_en')
       or (v_tipo in ('input', 'constante', 'tabla', 'tramo', 'calculo') and v_nodo ? 'condicion')
       or (v_tipo in ('tabla', 'tramo', 'calculo') and v_sobres[v_total]) then
      perform public._formula_rechazar('total_fijo', v_ids[v_total],
        format('El total «%s» no puede depender de una variante ni de un interruptor, ni sobrescribirse.', v_ids[v_total]));
    end if;
    -- El total es lo que se paga: un tipo de cambio, un campo, una bandera o la variante no lo son.
    if v_tipos[v_total] in ('tipo_cambio', 'campo_vehiculo', 'bandera', 'opcion') then
      perform public._formula_rechazar('total_no_es_monto', v_ids[v_total],
        format('El total «%s» tiene que dar un monto: un input, una constante, una tabla, un tramo o un cálculo.', v_ids[v_total]));
    end if;
  end if;

  -- §4 params (revisarParams): cada constante tiene su valor, y cada clave es una constante.
  for i in 1 .. v_n loop
    if v_tipos[i] = 'constante' and (v_ids[i] = 'tablas' or not p_params ? v_ids[i]) then
      perform public._formula_rechazar('constante_sin_valor', v_ids[i], format('La constante «%s» no tiene valor en params.', v_ids[i]));
    end if;
  end loop;
  for v_ref in select p.key from jsonb_each(p_params) p loop
    continue when v_ref = 'tablas';
    if not v_constantes ? v_ref then
      perform public._formula_rechazar('param_sin_constante', v_ref, format('params.%s no corresponde a ninguna constante.', v_ref));
    end if;
  end loop;

  -- §5 el par porcentaje-monto (revisarPares, decisión d). Quién lee cada nodo: el primero y, si hay, otro distinto.
  select coalesce(jsonb_object_agg(l.ref, jsonb_build_array(l.primero, l.otro)), '{}'::jsonb) into v_lectores
    from (select a.ref, a.primero, (array_agg(a.lector order by a.k) filter (where a.lector <> a.primero))[1] as otro
            from (select u.ref, u.lector, u.k, first_value(u.lector) over (partition by u.ref order by u.k) as primero
                    from unnest(v_lectores_ref, v_lectores_de) with ordinality as u(ref, lector, k)) a
           group by a.ref, a.primero) l;
  for i in 1 .. v_n loop
    continue when v_tipos[i] <> 'calculo';
    v_nodo := v_nodos -> (i - 1);
    continue when v_nodo ->> 'op' <> 'porcentaje_de';
    v_ref := v_nodo ->> 'pct';
    j := (v_pos ->> v_ref)::int;
    -- Un `porcentaje_de` es un monto y su porcentaje tiene formato pct; si se sobrescribe, su porcentaje da un monto y acepta un valor.
    v_mal := v_formatos[i] not in ('usd', 'moneda')
             or (j is not null and (v_formatos[j] <> 'pct'
                                    or (v_sobres[i] and not (v_tipos[j] in ('input', 'constante', 'tabla', 'tramo', 'calculo')
                                                             and (v_tipos[j] in ('input', 'constante', 'tipo_cambio') or v_sobres[j])))));
    if v_mal then
      perform public._formula_rechazar('par_mal_tipado', v_ids[i],
        format('«%s» es un porcentaje de otro monto: tiene que ser un monto y su porcentaje «%s», tener formato pct.', v_ids[i], v_ref));
    end if;
    if v_sobres[i] then
      v_x := v_lectores -> v_ref;
      v_otro := case when v_x ->> 0 = v_ids[i] then v_x ->> 1 else v_x ->> 0 end;
      if v_otro is not null then
        perform public._formula_rechazar('pct_compartido', v_ids[i],
          format('«%s» es el porcentaje de «%s», que se puede sobrescribir: ningún otro nodo lo puede leer (lo lee «%s»).', v_ref, v_ids[i], v_otro));
      end if;
    end if;
  end loop;

  -- §6 los tipos de cambio, los buckets y los grupos; §7 la variante.
  perform public._formula_cambio_y_grupos(v_nodos, v_pos, v_ids, v_tipos, v_formatos, v_total,
                                          p_def -> 'buckets', p_def -> 'total_en', p_def -> 'grupos');
  perform public._formula_variante(v_nodos, v_ids, v_tipos);
  perform public._formula_campos(v_nodos, v_tipos);
end;
$$;


ALTER FUNCTION "public"."validar_formula"("p_def" "jsonb", "p_params" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."validar_formula"("p_def" "jsonb", "p_params" "jsonb") IS 'El candado de la fórmula, espejo de validarFormula() de TS: lanza 22023 con la regla en DETAIL y donde en HINT. docs/COTIZADOR.md › «Las reglas».';



CREATE OR REPLACE FUNCTION "public"."validar_plantilla"("p_plantilla" "jsonb", "p_def" "jsonb", "p_diseno" "jsonb", "p_visibilidad" "jsonb", "p_tonos" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_grupos jsonb; v_pla jsonb; v_ton jsonb; v_k text;
begin
  perform public._plantilla_forma(p_plantilla);
  if p_def is null then return; end if;
  v_grupos := coalesce((select jsonb_object_agg(g ->> 'id', true) from jsonb_array_elements(coalesce(p_def -> 'grupos', '[]'::jsonb)) g), '{}'::jsonb);
  v_pla := coalesce((select jsonb_object_agg(g ->> 'grupo', true) from jsonb_array_elements(p_plantilla -> 'grupos') g), '{}'::jsonb);

  select g ->> 'grupo' into v_k from jsonb_array_elements(p_plantilla -> 'grupos') with ordinality t (g, o) where not v_grupos ? (g ->> 'grupo') order by o limit 1;
  if v_k is not null then perform public._formula_rechazar('grupo_inexistente', v_k, format('El grupo «%s» no es de la fórmula.', v_k)); end if;
  select a.g ->> 'grupo' into v_k from jsonb_array_elements(p_plantilla -> 'grupos') with ordinality a (g, o)
   where exists (select 1 from jsonb_array_elements(p_plantilla -> 'grupos') with ordinality b (g, o) where b.o < a.o and b.g ->> 'grupo' = a.g ->> 'grupo')
   order by a.o limit 1;
  if v_k is not null then perform public._formula_rechazar('grupo_repetido', v_k, format('El grupo «%s» está dos veces.', v_k)); end if;
  select g ->> 'id' into v_k from jsonb_array_elements(coalesce(p_def -> 'grupos', '[]'::jsonb)) with ordinality t (g, o) where not v_pla ? (g ->> 'id') order by o limit 1;
  if v_k is not null then perform public._formula_rechazar('grupo_faltante', v_k, format('Falta el grupo «%s»: la tarjeta lleva todos los grupos de la fórmula.', v_k)); end if;
  if p_tonos is not null then
    select coalesce(jsonb_object_agg(x, true), '{}'::jsonb) into v_ton from unnest(p_tonos) x where x is not null;
    select g ->> 'grupo' into v_k from jsonb_array_elements(p_plantilla -> 'grupos') with ordinality t (g, o) where g ? 'tono' and not v_ton ? (g ->> 'tono') order by o limit 1;
    if v_k is not null then perform public._formula_rechazar('tono_inexistente', v_k, format('El grupo «%s» usa un tono que no está en el catálogo.', v_k)); end if;
  end if;

  perform public._plantilla_nodos(p_plantilla, p_def, p_diseno, p_visibilidad);
end;
$$;


ALTER FUNCTION "public"."validar_plantilla"("p_plantilla" "jsonb", "p_def" "jsonb", "p_diseno" "jsonb", "p_visibilidad" "jsonb", "p_tonos" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_conservar"("p_vehiculo" "uuid", "p_conservar" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v public.vehiculos; v_filas int := 0; c public.vehiculos_conservados;
begin
  perform public.assert_activo();
  if p_conservar is null then
    raise exception 'Falta decir si se conserva o no.' using errcode = '22023';
  end if;
  select * into v from public.vehiculos x where x.id = p_vehiculo and x.eliminado_en is null for update;
  if not found then
    raise exception 'Ese vehículo ya no existe o está en la papelera.' using errcode = 'PT409';
  end if;
  if not public.puede_vehiculo(v.id, 'vehiculos.editar') then
    raise exception 'No tienes permiso para editar este vehículo.' using errcode = '42501';
  end if;
  if not v.importado_apibara then
    raise exception 'Sólo se conserva un vehículo importado de una subasta: los demás no se limpian.' using errcode = '22023';
  end if;
  if p_conservar then
    insert into public.vehiculos_conservados (vehiculo_id, conservado_por) values (v.id, (select auth.uid()))
    on conflict (vehiculo_id) do nothing;
    get diagnostics v_filas = row_count;
  else
    delete from public.vehiculos_conservados x where x.vehiculo_id = v.id;
    get diagnostics v_filas = row_count;
  end if;
  if v_filas > 0 then
    perform public.registrar_actividad(
      case when p_conservar then 'vehiculo.conservado' else 'vehiculo.conservar_quitado' end,
      'vehiculos_conservados', v.id::text, null, null, jsonb_build_object('vehiculo', v.id));
  end if;
  select * into c from public.vehiculos_conservados x where x.vehiculo_id = v.id;
  return jsonb_build_object('conservado', c.vehiculo_id is not null, 'conservado_en', c.conservado_en);
end;
$$;


ALTER FUNCTION "public"."vehiculo_conservar"("p_vehiculo" "uuid", "p_conservar" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_crear"("p_id" "uuid", "p_origen" "uuid", "p_datos" "jsonb", "p_consulta" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v public.vehiculos; v_origen public.origenes; v_fase uuid; v_flujo uuid; v_sub jsonb; c public.apibara_consultas;
begin
  if p_id is null or p_origen is null then
    raise exception 'Faltan el identificador y el origen del vehículo.' using errcode = '22023';
  end if;
  perform public.assert_permiso('vehiculos.crear', p_origen);

  select * into v from public.vehiculos x where x.id = p_id;
  if found then
    if v.creado_por is distinct from (select auth.uid()) or v.origen_id <> p_origen then
      raise exception 'Ese identificador ya está en uso. Cierra el formulario y vuelve a abrirlo.' using errcode = '23505';
    end if;
    return jsonb_build_object('id', v.id, 'numero', v.numero, 'actualizado_en', v.actualizado_en, 'fase_id', v.fase_id);
  end if;

  select * into v_origen from public.origenes o where o.id = p_origen;
  if not found then raise exception 'Ese origen ya no existe.' using errcode = 'PT409'; end if;
  if not v_origen.activo then
    raise exception 'El origen «%» está desactivado: no recibe registros nuevos.', v_origen.nombre using errcode = '23514';
  end if;
  if p_consulta is not null then
    if v_origen.tipo <> 'subasta' then
      raise exception 'Sólo un origen de subasta guarda datos de apibara.' using errcode = '22023';
    end if;
    c := public._apibara_consulta_tomar(p_consulta, p_origen, p_id);
    v_sub := public._vehiculo_subasta_desde(c.raw);
  end if;

  v.id := p_id;
  v.origen_id := p_origen;
  v.atributos := '{}'::jsonb;
  v := public._vehiculo_aplicar(v, p_datos);
  perform public._vehiculo_sin_repetidos(v);

  begin
    insert into public.vehiculos (id, origen_id, categoria_id, titulo, marca, modelo, anio, vin, lote, plataforma, url_origen,
      precio, precio_negociable, acepta_permuta, placado, kilometraje, atributos, creado_por,
      subasta_en, subasta_fin_en, estado_subasta, apibara_sync_en, apibara_raw, importado_apibara)
    values (v.id, v.origen_id, v.categoria_id, v.titulo, v.marca, v.modelo, v.anio, v.vin, v.lote, v.plataforma, v.url_origen,
      v.precio, v.precio_negociable, v.acepta_permuta, v.placado, v.kilometraje, v.atributos, (select auth.uid()),
      (v_sub ->> 'subasta_en')::timestamptz, (v_sub ->> 'subasta_fin_en')::timestamptz,
      (v_sub ->> 'estado_subasta')::public.estado_subasta,
      case when p_consulta is not null then now() end, c.raw, p_consulta is not null)
    returning * into v;
  exception when unique_violation then
    raise exception 'Ya hay un vehículo con ese VIN o ese lote.' using errcode = '23505';
  end;
  if p_consulta is not null then
    update public.apibara_consultas x set vehiculo_id = v.id where x.id = p_consulta;
  end if;

  v_fase := public._vehiculo_fase_de_entrada(v.id, p_origen);
  if v_fase is not null then
    select f.flujo_id into v_flujo from public.fases f where f.id = v_fase;
    update public.vehiculos x set fase_id = v_fase, fase_desde = now() where x.id = v.id returning * into v;
    insert into public.historial_fases (flujo_id, vehiculo_id, de_fase_id, a_fase_id, usuario_id)
    values (v_flujo, v.id, null, v_fase, (select auth.uid()));
  end if;
  return jsonb_build_object('id', v.id, 'numero', v.numero, 'actualizado_en', v.actualizado_en, 'fase_id', v.fase_id);
end;
$$;


ALTER FUNCTION "public"."vehiculo_crear"("p_id" "uuid", "p_origen" "uuid", "p_datos" "jsonb", "p_consulta" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_fase_desde_coherente"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.fase_id is null then
    new.fase_desde := null;
  elsif new.fase_desde is null then
    new.fase_desde := now();
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."vehiculo_fase_desde_coherente"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_foto_eliminar"("p_vehiculo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_foto" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_version timestamptz; f public.vehiculos_imagenes;
begin
  v_version := public._fotos_abrir(p_vehiculo);
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  select * into f from public.vehiculos_imagenes x where x.id = p_foto and x.vehiculo_id = p_vehiculo;
  -- Ya no está: un reintento tras perder la respuesta no es un error.
  if not found then
    return jsonb_build_object('actualizado_en', v_version, 'foto', null);
  end if;
  perform public._fotos_exigir_version(p_vehiculo, v_version, p_actualizado_en_esperado);
  delete from public.vehiculos_imagenes x where x.id = f.id;
  -- `distinct`: una foto de menos de 480 px tiene la completa y la miniatura iguales, o sea un
  -- solo objeto, y un `on conflict do update` no puede tocar dos veces la misma fila.
  insert into public.cola_gc_storage as c (bucket, ruta)
  select distinct 'vehiculos', r from unnest(array[f.ruta, f.ruta_miniatura]) as r
  on conflict (bucket, ruta) do update set encolado_en = now() where c.reclamado_en is null;
  return jsonb_build_object(
    'actualizado_en', public._fotos_cerrar(p_vehiculo, 'vehiculo.foto_eliminada', jsonb_build_object('foto', f.id, 'hash', f.hash)),
    'foto', jsonb_build_object('hash', f.hash, 'ruta', f.ruta, 'ruta_miniatura', f.ruta_miniatura,
      'ancho', f.ancho, 'alto', f.alto, 'bytes', f.bytes, 'orden', f.orden, 'es_portada', f.es_portada));
end;
$$;


ALTER FUNCTION "public"."vehiculo_foto_eliminar"("p_vehiculo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_foto" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_foto_mover"("p_vehiculo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_foto" "uuid", "p_despues_de" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_version timestamptz; v_orden int; v_vecina int; v_destino int;
begin
  v_version := public._fotos_abrir(p_vehiculo);
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  select x.orden into v_orden from public.vehiculos_imagenes x where x.id = p_foto and x.vehiculo_id = p_vehiculo;
  if not found then
    raise exception 'Esa foto ya no está. Recarga para ver cómo quedaron.' using errcode = 'PT409';
  end if;
  if p_despues_de is null then
    v_destino := 1;
  else
    select x.orden into v_vecina from public.vehiculos_imagenes x where x.id = p_despues_de and x.vehiculo_id = p_vehiculo;
    if not found then
      raise exception 'La foto de al lado ya no está. Recarga para ver cómo quedaron.' using errcode = 'PT409';
    end if;
    -- Al sacarla de su lugar, las de atrás se corren uno.
    v_destino := case when v_vecina < v_orden then v_vecina + 1 else v_vecina end;
  end if;
  -- Ya está donde se la quería: un reintento no choca consigo mismo.
  if v_destino = v_orden then
    return jsonb_build_object('actualizado_en', v_version);
  end if;
  perform public._fotos_exigir_version(p_vehiculo, v_version, p_actualizado_en_esperado);

  if v_destino < v_orden then
    update public.vehiculos_imagenes x set orden = x.orden + 1 where x.vehiculo_id = p_vehiculo and x.orden >= v_destino and x.orden < v_orden;
  else
    update public.vehiculos_imagenes x set orden = x.orden - 1 where x.vehiculo_id = p_vehiculo and x.orden > v_orden and x.orden <= v_destino;
  end if;
  update public.vehiculos_imagenes x set orden = v_destino where x.id = p_foto;
  return jsonb_build_object('actualizado_en', public._fotos_cerrar(p_vehiculo, 'vehiculo.foto_movida', jsonb_build_object('foto', p_foto)));
end;
$$;


ALTER FUNCTION "public"."vehiculo_foto_mover"("p_vehiculo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_foto" "uuid", "p_despues_de" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_foto_portada"("p_vehiculo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_foto" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_version timestamptz; v_es boolean;
begin
  v_version := public._fotos_abrir(p_vehiculo);
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  select x.es_portada into v_es from public.vehiculos_imagenes x where x.id = p_foto and x.vehiculo_id = p_vehiculo;
  if not found then
    raise exception 'Esa foto ya no está. Recarga para ver cómo quedaron.' using errcode = 'PT409';
  end if;
  if v_es then
    return jsonb_build_object('actualizado_en', v_version);
  end if;
  perform public._fotos_exigir_version(p_vehiculo, v_version, p_actualizado_en_esperado);
  update public.vehiculos_imagenes x set es_portada = false where x.vehiculo_id = p_vehiculo and x.es_portada;
  update public.vehiculos_imagenes x set es_portada = true where x.id = p_foto;
  return jsonb_build_object('actualizado_en', public._fotos_cerrar(p_vehiculo, 'vehiculo.foto_portada', jsonb_build_object('foto', p_foto)));
end;
$$;


ALTER FUNCTION "public"."vehiculo_foto_portada"("p_vehiculo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_foto" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_fotos_agregar"("p_vehiculo" "uuid", "p_fotos" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  f jsonb; v_version timestamptz; v_hay int; v_hash text; v_orden int; v_id uuid; v_url text;
  v_agregadas text[] := '{}'; v_repetidas text[] := '{}'; v_sin_lugar text[] := '{}';
begin
  v_version := public._fotos_abrir(p_vehiculo);
  if jsonb_typeof(p_fotos) is distinct from 'array' or jsonb_array_length(p_fotos) = 0 then
    raise exception 'No llegó ninguna foto.' using errcode = '22023';
  end if;
  if jsonb_array_length(p_fotos) > 24 then
    raise exception 'Un vehículo admite hasta 24 fotos.' using errcode = '23514';
  end if;
  select count(*) into v_hay from public.vehiculos_imagenes x where x.vehiculo_id = p_vehiculo;

  for f in select * from jsonb_array_elements(p_fotos) loop
    v_hash := f ->> 'hash';
    if v_hash is null or v_hash !~ '^[0-9a-f]{64}$' then
      raise exception 'Una de las fotos llegó incompleta. Vuelve a elegirla.' using errcode = '22023';
    end if;
    v_url := nullif(btrim(f ->> 'origen_url'), '');
    if v_url is not null and (char_length(v_url) > 1000 or v_url !~* '^https?://[^[:space:]]+$') then
      raise exception 'La dirección de origen de una foto no es válida.' using errcode = '22023';
    end if;
    if v_hash = any (v_agregadas) or exists (select 1 from public.vehiculos_imagenes x where x.vehiculo_id = p_vehiculo and x.hash = v_hash) then
      v_repetidas := v_repetidas || v_hash;
      continue;
    end if;
    if v_hay >= 24 then
      v_sin_lugar := v_sin_lugar || v_hash;
      continue;
    end if;
    -- Al final, salvo que traiga su lugar: ahí se le hace sitio.
    v_orden := least(greatest(coalesce((f ->> 'orden')::int, v_hay + 1), 1), v_hay + 1);
    update public.vehiculos_imagenes x set orden = x.orden + 1 where x.vehiculo_id = p_vehiculo and x.orden >= v_orden;
    insert into public.vehiculos_imagenes (vehiculo_id, hash, ruta, ruta_miniatura, ancho, alto, bytes, orden, origen_url)
    values (p_vehiculo, v_hash, f ->> 'ruta', f ->> 'ruta_miniatura', (f ->> 'ancho')::int, (f ->> 'alto')::int, (f ->> 'bytes')::int, v_orden, v_url)
    returning id into v_id;
    if coalesce((f ->> 'es_portada')::boolean, false) then
      update public.vehiculos_imagenes x set es_portada = false where x.vehiculo_id = p_vehiculo and x.es_portada;
      update public.vehiculos_imagenes x set es_portada = true where x.id = v_id;
    end if;
    v_hay := v_hay + 1;
    v_agregadas := v_agregadas || v_hash;
  end loop;

  if cardinality(v_agregadas) > 0 then
    v_version := public._fotos_cerrar(p_vehiculo, 'vehiculo.fotos_agregadas', jsonb_build_object('cantidad', cardinality(v_agregadas)));
  end if;
  return jsonb_build_object('actualizado_en', v_version, 'agregadas', to_jsonb(v_agregadas),
    'repetidas', to_jsonb(v_repetidas), 'sin_lugar', to_jsonb(v_sin_lugar));
end;
$_$;


ALTER FUNCTION "public"."vehiculo_fotos_agregar"("p_vehiculo" "uuid", "p_fotos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_guardar"("p_vehiculo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_datos" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v public.vehiculos; n public.vehiculos;
begin
  perform public.assert_activo();
  select * into v from public.vehiculos x where x.id = p_vehiculo and x.eliminado_en is null for update;
  if not found then
    raise exception 'Ese vehículo ya no existe o está en la papelera.' using errcode = 'PT409';
  end if;
  -- `puede_vehiculo()` y no la condición escrita acá: con `lead_id` nulo, `lead_id in (…)` da nulo,
  -- y un `if` con nulo no levanta (dejaba editar lo ajeno a quien tuviera algún lead en su cartera).
  if not public.puede_vehiculo(v.id, 'vehiculos.editar') then
    raise exception 'No tienes permiso para editar este vehículo.' using errcode = '42501';
  end if;
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;

  n := public._vehiculo_aplicar(v, p_datos);
  -- Guardar lo que ya está guardado no es un conflicto: un reintento tras perder la respuesta no
  -- choca consigo mismo, y quien no cambió nada no pisa a nadie.
  if to_jsonb(n) = to_jsonb(v) then
    return jsonb_build_object('actualizado_en', v.actualizado_en);
  end if;
  if v.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._conflicto_de_edicion('vehiculos', v.id, v.actualizado_en, 'este vehículo');
  end if;
  perform public._vehiculo_sin_repetidos(n);

  begin
    update public.vehiculos x set
      categoria_id = n.categoria_id, titulo = n.titulo, marca = n.marca, modelo = n.modelo, anio = n.anio, vin = n.vin,
      lote = n.lote, plataforma = n.plataforma, url_origen = n.url_origen, precio = n.precio,
      precio_negociable = n.precio_negociable, acepta_permuta = n.acepta_permuta, placado = n.placado,
      kilometraje = n.kilometraje, atributos = n.atributos
    where x.id = v.id
    returning * into n;
  exception when unique_violation then
    raise exception 'Ya hay un vehículo con ese VIN o ese lote.' using errcode = '23505';
  end;
  return jsonb_build_object('actualizado_en', n.actualizado_en);
end;
$$;


ALTER FUNCTION "public"."vehiculo_guardar"("p_vehiculo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_datos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_imagen_integridad"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_patron text := '^' || new.vehiculo_id::text || '/[0-9a-f]{64}\.(webp|jpg)$';
begin
  if new.ruta !~ v_patron or new.ruta_miniatura !~ v_patron then
    raise exception 'La foto no está en la carpeta de este vehículo.' using errcode = '22023';
  end if;
  perform public.storage_gc_rescatar('vehiculos', new.ruta);
  perform public.storage_gc_rescatar('vehiculos', new.ruta_miniatura);
  if (select count(*) from storage.objects o where o.bucket_id = 'vehiculos' and o.name in (new.ruta, new.ruta_miniatura))
     < (case when new.ruta = new.ruta_miniatura then 1 else 2 end) then
    raise exception 'La foto no terminó de subir. Vuelve a intentarlo.';
  end if;
  return new;
end;
$_$;


ALTER FUNCTION "public"."vehiculo_imagen_integridad"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_imagenes_tope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (select count(*) from public.vehiculos_imagenes where vehiculo_id = new.vehiculo_id) >= 24 then
    raise exception 'Un vehículo admite hasta 24 fotos.' using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."vehiculo_imagenes_tope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_interesado_marcar"("p_vehiculo" "uuid", "p_lead" "uuid", "p_nota" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_nota text := nullif(btrim(p_nota), ''); i public.vehiculos_interesados;
begin
  perform public.assert_activo();
  if p_vehiculo is null or not public.puede_vehiculo(p_vehiculo, 'vehiculos.ver') then
    raise exception 'Ese vehículo no existe o no tienes acceso.' using errcode = '42501';
  end if;
  perform public._lead_mio(p_lead, 'leads.editar', true);
  if char_length(v_nota) > 500 then
    raise exception 'La nota no puede pasar de 500 caracteres.' using errcode = '22023', hint = 'nota';
  end if;
  -- Poner, no alternar: la misma nota es `sin_cambios`; otra la reemplaza.
  select * into i from public.vehiculos_interesados x where x.vehiculo_id = p_vehiculo and x.lead_id = p_lead for update;
  if found then
    if i.nota is not distinct from v_nota then
      return jsonb_build_object('resultado', 'sin_cambios', 'nota', i.nota);
    end if;
    update public.vehiculos_interesados x set nota = v_nota where x.vehiculo_id = p_vehiculo and x.lead_id = p_lead;
    return jsonb_build_object('resultado', 'nota_cambiada', 'nota', v_nota);
  end if;
  insert into public.vehiculos_interesados (vehiculo_id, lead_id, usuario_id, nota)
  values (p_vehiculo, p_lead, (select auth.uid()), v_nota)
  on conflict (vehiculo_id, lead_id) do update set nota = excluded.nota;
  return jsonb_build_object('resultado', 'marcado', 'nota', v_nota);
end;
$$;


ALTER FUNCTION "public"."vehiculo_interesado_marcar"("p_vehiculo" "uuid", "p_lead" "uuid", "p_nota" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_interesado_quitar"("p_vehiculo" "uuid", "p_lead" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_nota text;
begin
  perform public.assert_activo();
  if p_vehiculo is null or not public.puede_vehiculo(p_vehiculo, 'vehiculos.ver') then
    raise exception 'Ese vehículo no existe o no tienes acceso.' using errcode = '42501';
  end if;
  perform public._lead_mio(p_lead, 'leads.editar', true);
  delete from public.vehiculos_interesados x where x.vehiculo_id = p_vehiculo and x.lead_id = p_lead
  returning x.nota into v_nota;
  if not found then
    return jsonb_build_object('resultado', 'sin_cambios', 'nota', null);
  end if;
  -- La nota vuelve para que «Deshacer» la reponga.
  return jsonb_build_object('resultado', 'quitado', 'nota', v_nota);
end;
$$;


ALTER FUNCTION "public"."vehiculo_interesado_quitar"("p_vehiculo" "uuid", "p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_interesados"("p_vehiculo" "uuid") RETURNS TABLE("lead_id" "uuid", "lead_nombre" "text", "lead_numero" bigint, "lead_numero_propio" integer, "nota" "text", "creado_en" timestamp with time zone, "por_nombre" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select i.lead_id, l.nombre, g.numero, np.numero, i.nota, i.creado_en, p.nombre
  from public.vehiculos_interesados i
  join public.leads l on l.id = i.lead_id
  left join public.leads_numeros_globales g on g.lead_id = l.id
  left join public.leads_numeros_propios np on np.lead_id = l.id
  left join public.perfiles p on p.id = i.usuario_id
  where i.vehiculo_id = p_vehiculo
  order by i.creado_en desc, i.lead_id
  -- Uno de más: la pantalla dice «Mostrando los 100 más recientes» si los hay (cierre 1).
  limit 101;
$$;


ALTER FUNCTION "public"."vehiculo_interesados"("p_vehiculo" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_limpieza"("p_vehiculo" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v public.vehiculos; a public.ajustes_empresa; c public.vehiculos_conservados; v_nombre text;
begin
  perform public.assert_activo();
  select * into v from public.vehiculos x where x.id = p_vehiculo and x.eliminado_en is null;
  if not found or not public.puede_vehiculo(v.id, 'vehiculos.ver') then
    return null;
  end if;
  if not public._limpieza_aplica(v) then
    return jsonb_build_object('aplica', false);
  end if;
  select * into a from public.ajustes_empresa e where e.id = 1;
  select * into c from public.vehiculos_conservados x where x.vehiculo_id = v.id;
  if found and c.conservado_por is not null then
    select nullif(btrim(p.nombre), '') into v_nombre from public.perfiles p where p.id = c.conservado_por;
  end if;
  return jsonb_build_object(
    'aplica', true,
    'activa', a.limpieza_automatica,
    'dias_gracia', a.limpieza_dias_gracia,
    'fecha', public.limpieza_el(v),
    'conservado', c.vehiculo_id is not null,
    'conservado_por_nombre', v_nombre,
    'conservado_en', c.conservado_en,
    'conservado_por_mi', c.conservado_por is not distinct from (select auth.uid()) and c.vehiculo_id is not null);
end;
$$;


ALTER FUNCTION "public"."vehiculo_limpieza"("p_vehiculo" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_subasta_refrescar"("p_vehiculo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_consulta" "uuid", "p_datos" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v public.vehiculos; n public.vehiculos; v_sub jsonb; c public.apibara_consultas;
begin
  perform public.assert_activo();
  select * into v from public.vehiculos x where x.id = p_vehiculo and x.eliminado_en is null for update;
  if not found then
    raise exception 'Ese vehículo ya no existe o está en la papelera.' using errcode = 'PT409';
  end if;
  if not public.puede_vehiculo(v.id, 'vehiculos.editar') then
    raise exception 'No tienes permiso para editar este vehículo.' using errcode = '42501';
  end if;
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  if not exists (select 1 from public.origenes o where o.id = v.origen_id and o.tipo = 'subasta') then
    raise exception 'Sólo un vehículo de subasta se refresca desde apibara.' using errcode = '22023';
  end if;
  if v.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._conflicto_de_edicion('vehiculos', v.id, v.actualizado_en, 'este vehículo');
  end if;
  if p_consulta is null then
    raise exception 'Falta la consulta a la subasta. Vuelve a consultar.' using errcode = '22023';
  end if;
  c := public._apibara_consulta_tomar(p_consulta, v.origen_id, v.id);
  v_sub := public._vehiculo_subasta_desde(c.raw);

  n := public._vehiculo_aplicar(v, coalesce(p_datos, '{}'::jsonb));
  perform public._vehiculo_sin_repetidos(n);
  begin
    update public.vehiculos x set
      categoria_id = n.categoria_id, titulo = n.titulo, marca = n.marca, modelo = n.modelo, anio = n.anio, vin = n.vin,
      lote = n.lote, plataforma = n.plataforma, url_origen = n.url_origen, precio = n.precio,
      precio_negociable = n.precio_negociable, acepta_permuta = n.acepta_permuta, placado = n.placado,
      kilometraje = n.kilometraje, atributos = n.atributos,
      subasta_en = (v_sub ->> 'subasta_en')::timestamptz, subasta_fin_en = (v_sub ->> 'subasta_fin_en')::timestamptz,
      estado_subasta = (v_sub ->> 'estado_subasta')::public.estado_subasta,
      apibara_sync_en = now(), apibara_raw = c.raw
    where x.id = v.id
    returning * into n;
  exception when unique_violation then
    raise exception 'Ya hay un vehículo con ese VIN o ese lote.' using errcode = '23505';
  end;
  update public.apibara_consultas x set vehiculo_id = v.id where x.id = p_consulta;
  return jsonb_build_object('actualizado_en', n.actualizado_en, 'subasta_en', n.subasta_en,
    'estado_subasta', n.estado_subasta, 'apibara_sync_en', n.apibara_sync_en);
end;
$$;


ALTER FUNCTION "public"."vehiculo_subasta_refrescar"("p_vehiculo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_consulta" "uuid", "p_datos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_validar_atributos"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_anteriores jsonb := '{}'::jsonb; v_campos jsonb;
begin
  if tg_op = 'UPDATE' and old.origen_id = new.origen_id then
    v_anteriores := old.atributos;
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('clave', c.clave, 'etiqueta', c.etiqueta, 'tipo', c.tipo, 'requerido', c.requerido,
                                               'minimo', c.minimo, 'maximo', c.maximo)), '[]'::jsonb)
    into v_campos
  from public.origenes_campos c where c.origen_id = new.origen_id and c.activo;
  perform public._atributos_validar(new.atributos, v_campos, 'Los atributos de un vehículo tienen que ser un objeto.');
  perform public._atributos_rango(new.atributos, v_anteriores, v_campos);
  return new;
end;
$$;


ALTER FUNCTION "public"."vehiculo_validar_atributos"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_vincular"("p_vehiculo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_lead" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v public.vehiculos; v_resultado text; v_lead_de_la_final uuid;
begin
  perform public.assert_activo();
  -- Primero se mira, sin bloquear: lo que no se ve (también la papelera y lo inexistente) da lo mismo.
  if p_vehiculo is null or not public.puede_vehiculo(p_vehiculo, 'vehiculos.ver') then
    raise exception 'Ese vehículo no existe o no tienes acceso.' using errcode = '42501';
  end if;
  if not public.puede_vehiculo(p_vehiculo, 'vehiculos.editar') then
    raise exception 'No tienes permiso para editar este vehículo.' using errcode = '42501';
  end if;
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.' using errcode = '22023';
  end if;
  -- Vincular le da el vehículo a la cartera de ese lead: exige tenerlo en la propia. El lead se bloquea
  -- (y se vuelve a mirar) antes que el vehículo: así la papelera, que bloquea el lead, no lo envía con un
  -- vínculo a medio escribir. Desvincular (p_lead nulo) es una acción sobre el vehículo.
  if p_lead is not null then
    perform public._lead_mio(p_lead, 'leads.editar', true);
  end if;
  select * into v from public.vehiculos x where x.id = p_vehiculo and x.eliminado_en is null for update;
  -- Con el vehículo bloqueado se vuelve a mirar: pudo irse a la papelera, o perderse el lead que daba el acceso.
  if not found or not public.puede_vehiculo(p_vehiculo, 'vehiculos.ver') then
    raise exception 'Ese vehículo no existe o no tienes acceso.' using errcode = '42501';
  end if;
  if not public.puede_vehiculo(p_vehiculo, 'vehiculos.editar') then
    raise exception 'No tienes permiso para editar este vehículo.' using errcode = '42501';
  end if;
  -- Ya está como se pidió: un reintento no choca consigo mismo.
  if v.lead_id is not distinct from p_lead then
    return jsonb_build_object('resultado', 'sin_cambios', 'actualizado_en', v.actualizado_en, 'limpieza_el', public.limpieza_el(v));
  end if;
  if v.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._conflicto_de_edicion('vehiculos', v.id, v.actualizado_en, 'este vehículo');
  end if;
  -- Con una cotización final activa (con lead), el vínculo es el de la final: no se desvincula ni se pasa a otro (P5 a, 4.25-1).
  select c.lead_id into v_lead_de_la_final from public.cotizaciones c
   where c.vehiculo_id = v.id and c.clase = 'final' and c.estado = 'activa' and c.eliminado_en is null and c.lead_id is not null
   limit 1;   -- cotizaciones_final_por_vehiculo
  if v_lead_de_la_final is not null and p_lead is distinct from v_lead_de_la_final then
    raise exception 'Este vehículo tiene una cotización final: su vínculo no cambia. Para cambiarlo, manda la final a la papelera.'
      using errcode = '23514';
  end if;
  -- Reemplazar le quita el vehículo a la cartera del lead actual: sólo quien también lo tiene en la suya
  -- (y puede nombrarlo). Si no, se desvincula primero, desde el vehículo. No se dice cuál es.
  if p_lead is not null and v.lead_id is not null and not public.puede_actuar_lead(v.lead_id, 'leads.editar') then
    raise exception 'Este vehículo ya está vinculado a otro lead. Para cambiarlo, desvincúlalo desde la ficha del vehículo.'
      using errcode = '23514';
  end if;
  v_resultado := case when p_lead is null then 'desvinculado' when v.lead_id is null then 'vinculado' else 'reemplazado' end;
  update public.vehiculos x set lead_id = p_lead where x.id = v.id returning * into v;
  return jsonb_build_object('resultado', v_resultado, 'actualizado_en', v.actualizado_en, 'limpieza_el', public.limpieza_el(v));
end;
$$;


ALTER FUNCTION "public"."vehiculo_vincular"("p_vehiculo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_lead" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_vinculo_historial"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and new.lead_id is distinct from old.lead_id then
    update public.vehiculos_vinculos set hasta = now() where vehiculo_id = new.id and hasta is null;
    if new.lead_id is not null then
      insert into public.vehiculos_vinculos (vehiculo_id, lead_id, usuario_id) values (new.id, new.lead_id, (select auth.uid()));
    end if;
  elsif tg_op = 'INSERT' and new.lead_id is not null then
    insert into public.vehiculos_vinculos (vehiculo_id, lead_id, usuario_id) values (new.id, new.lead_id, (select auth.uid()));
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."vehiculo_vinculo_historial"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_vinculos"("p_vehiculo" "uuid") RETURNS TABLE("lead_id" "uuid", "lead_nombre" "text", "lead_numero" bigint, "lead_numero_propio" integer, "desde" timestamp with time zone, "hasta" timestamp with time zone, "por_nombre" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select k.lead_id, l.nombre, g.numero, np.numero, k.desde, k.hasta, p.nombre
  from public.vehiculos_vinculos k
  left join public.leads l on l.id = k.lead_id
  left join public.leads_numeros_globales g on g.lead_id = l.id
  left join public.leads_numeros_propios np on np.lead_id = l.id
  left join public.perfiles p on p.id = k.usuario_id
  where k.vehiculo_id = p_vehiculo
  -- El vigente primero; después, del más reciente al más viejo.
  order by (k.hasta is not null), k.desde desc, k.id desc
  -- Uno de más: la pantalla dice «Mostrando los 50 más recientes» si los hay (cierre 1).
  limit 51;
$$;


ALTER FUNCTION "public"."vehiculo_vinculos"("p_vehiculo" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_vitrina"("p_vehiculo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_publicado" boolean, "p_precio" numeric, "p_precio_hasta" numeric, "p_nota" "text", "p_destacado" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.vehiculos;
  v_precio numeric := round(p_precio, 2);
  v_hasta numeric := round(p_precio_hasta, 2);
  v_nota text := nullif(btrim(p_nota), '');
  v_destacado boolean := coalesce(p_publicado, false) and coalesce(p_destacado, false);
begin
  perform public.assert_activo();
  select * into v from public.vehiculos x where x.id = p_vehiculo and x.eliminado_en is null for update;
  if not found then
    raise exception 'Ese vehículo ya no existe o está en la papelera.' using errcode = 'PT409';
  end if;
  if not public.puede_vehiculo(v.id, 'vehiculos.ver') or not public.tiene_permiso('vehiculos.vitrina', v.origen_id) then
    raise exception 'No tienes permiso para publicar este vehículo en la web.' using errcode = '42501';
  end if;
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  if p_publicado is null then
    raise exception 'Falta decir si el vehículo se publica o no.' using errcode = '22023';
  end if;
  if v_precio is not null and (v_precio < 0 or v_precio > 999999999999) then
    raise exception 'El precio público tiene que estar entre 0 y 999999999999.' using errcode = '22023', hint = 'precio_web';
  end if;
  if v_hasta is not null and v_precio is null then
    raise exception 'Para poner un precio «hasta» falta el precio público.' using errcode = '22023', hint = 'precio_web_hasta';
  end if;
  if v_hasta is not null and (v_hasta < v_precio or v_hasta > 999999999999) then
    raise exception 'El precio «hasta» no puede ser menor que el precio público.' using errcode = '22023', hint = 'precio_web_hasta';
  end if;
  if char_length(v_nota) > 120 then
    raise exception 'La nota del precio admite hasta 120 caracteres.' using errcode = '22023', hint = 'precio_web_nota';
  end if;

  -- Guardar lo que ya está guardado no es un conflicto (un reintento no choca consigo mismo).
  if v.publicado_web = p_publicado and v.destacado_web = v_destacado and v.precio_web is not distinct from v_precio
     and v.precio_web_hasta is not distinct from v_hasta and v.precio_web_nota is not distinct from v_nota then
    return jsonb_build_object('actualizado_en', v.actualizado_en);
  end if;
  if v.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._conflicto_de_edicion('vehiculos', v.id, v.actualizado_en, 'este vehículo');
  end if;

  update public.vehiculos x
  set publicado_web = p_publicado, destacado_web = v_destacado, precio_web = v_precio, precio_web_hasta = v_hasta, precio_web_nota = v_nota
  where x.id = v.id
  returning * into v;
  perform public.registrar_actividad('vehiculo.vitrina', 'vehiculos', v.id::text, null, null,
    jsonb_build_object('publicado', p_publicado, 'destacado', v_destacado));
  return jsonb_build_object('actualizado_en', v.actualizado_en);
end;
$$;


ALTER FUNCTION "public"."vehiculo_vitrina"("p_vehiculo" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_publicado" boolean, "p_precio" numeric, "p_precio_hasta" numeric, "p_nota" "text", "p_destacado" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculo_vitrina_previa"("p_vehiculo" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'tarjeta', to_jsonb(t) - array['origen_id', 'publicado', 'con_fase', 'fase_publica', 'origen_activo', 'origen_visible', 'web_activa', 'visible'],
    'publicado', t.publicado, 'con_fase', t.con_fase, 'fase_publica', t.fase_publica, 'origen_activo', t.origen_activo,
    'origen_visible', t.origen_visible, 'web_activa', t.web_activa, 'visible', t.visible)
  from interno.vitrina_vehiculos t
  where t.id = p_vehiculo and public.puede_vehiculo(p_vehiculo, 'vehiculos.ver');
$$;


ALTER FUNCTION "public"."vehiculo_vitrina_previa"("p_vehiculo" "uuid") OWNER TO "postgres";


