CREATE OR REPLACE FUNCTION "public"."vehiculos_inventario"("p_origen" "uuid", "p_tamano" integer DEFAULT NULL::integer, "p_filtros" "jsonb" DEFAULT '[]'::"jsonb", "p_cursor_en" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cursor_id" "uuid" DEFAULT NULL::"uuid", "p_hacia_atras" boolean DEFAULT false) RETURNS TABLE("id" "uuid", "numero" bigint, "origen_id" "uuid", "titulo" "text", "marca" "text", "modelo" "text", "anio" smallint, "vin" "text", "lote" "text", "plataforma" "text", "url_origen" "text", "precio" numeric, "precio_negociable" boolean, "acepta_permuta" boolean, "placado" boolean, "kilometraje" integer, "categoria_id" "uuid", "fase_id" "uuid", "atributos" "jsonb", "lead_id" "uuid", "publicado_web" boolean, "destacado_web" boolean, "precio_web" numeric, "precio_web_hasta" numeric, "precio_web_nota" "text", "creado_por" "uuid", "creado_en" timestamp with time zone, "actualizado_en" timestamp with time zone, "limpieza_el" "date", "portada_ruta" "text")
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  -- MAXIMO_DE_PAGINA_DE_VEHICULOS (src/modules/vehiculos/entities/vehiculo.ts), más una para saber si hay otra.
  v_n integer := public._acotar_pagina(p_tamano, 100, 100) + 1;
  v_uid uuid := (select auth.uid());
  v_filtros jsonb := coalesce(p_filtros, '[]'::jsonb);
  v_rutas text; v_sentido text; v_sql text;
begin
  if p_origen is null then
    raise exception 'Falta el origen del inventario.' using errcode = '22023', hint = 'origen';
  end if;
  if (p_cursor_en is null) <> (p_cursor_id is null) then
    raise exception 'El cursor del inventario está incompleto.' using errcode = '22023', hint = 'cursor';
  end if;
  v_sentido := case when p_cursor_en is null then 'primera' when p_hacia_atras then 'anterior' else 'siguiente' end;
  if p_origen = any (public.origenes_con_alcance('vehiculos.ver', 'todos')) then
    v_rutas := 'origen';
  elsif p_origen = any (public.origenes_con_alcance('vehiculos.ver', 'propios')) then
    -- Con más de 5.000 leads en la cartera, lo de hoy: el origen, y la RLS pregunta en_cartera() por fila.
    v_rutas := case when public.leads_cartera_corta() then 'propios' else 'origen' end;
  end if;
  -- Los filtros se validan también sin ruta: un pedido que no vale falla igual para todos.
  v_sql := public._vehiculos_inventario_sql(v_filtros, coalesce(v_rutas, 'origen'), v_sentido);
  if v_rutas is null then
    return;
  end if;
  return query execute v_sql using v_filtros, p_origen, v_n, v_uid, p_cursor_en, p_cursor_id;
end $$;


ALTER FUNCTION "public"."vehiculos_inventario"("p_origen" "uuid", "p_tamano" integer, "p_filtros" "jsonb", "p_cursor_en" timestamp with time zone, "p_cursor_id" "uuid", "p_hacia_atras" boolean) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."vehiculos_inventario"("p_origen" "uuid", "p_tamano" integer, "p_filtros" "jsonb", "p_cursor_en" timestamp with time zone, "p_cursor_id" "uuid", "p_hacia_atras" boolean) IS 'Una página del inventario de un origen, de lo más nuevo a lo más viejo (creado_en desc, id desc), por cursor (hacia atrás, en orden ascendente), con los filtros del layout (Condicion[]) y, por fila, limpieza_el y la portada. Corre como quien la llama: la RLS decide qué se ve; cada ruta (el origen, lo creado, la cartera de mis_leads()) va por su índice con su propio limit. Lo mide supabase/tests/medir-vehiculos-inventario.sql.';



CREATE OR REPLACE FUNCTION "public"."vehiculos_papelera_enviar"("p_vehiculos" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  e record; v_lote uuid; v_version timestamptz; v_mensaje text; v_codigo text; v_titulo text;
  v_enviados jsonb := '[]'::jsonb; v_rechazados jsonb := '[]'::jsonb;
begin
  perform public.assert_activo();
  if jsonb_typeof(p_vehiculos) is distinct from 'array' or jsonb_array_length(p_vehiculos) = 0 then
    raise exception 'No llegó ningún vehículo.' using errcode = '22023';
  end if;
  if jsonb_array_length(p_vehiculos) > 200 then
    raise exception 'Se envían hasta 200 por vez.' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_vehiculos) x
    where jsonb_typeof(x) <> 'object'
       or coalesce(x ->> 'id', '') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       or coalesce(x ->> 'actualizado_en', '2000-01-01') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}') then
    raise exception 'Uno de los vehículos llegó incompleto. Recarga e intenta de nuevo.' using errcode = '22023';
  end if;

  insert into public.lotes_papelera (tipo, creado_por) values ('vehiculos', (select auth.uid())) returning id into v_lote;
  for e in
    select distinct on (x ->> 'id') (x ->> 'id')::uuid as id, x ->> 'actualizado_en' as version
    from jsonb_array_elements(p_vehiculos) x order by x ->> 'id'
  loop
    begin
      v_enviados := v_enviados || public._vehiculo_a_papelera(e.id, e.version::timestamptz, v_lote);
    exception when others then
      get stacked diagnostics v_mensaje = message_text, v_codigo = returned_sqlstate;
      -- Sólo lo que escribimos nosotros llega a la pantalla.
      if v_codigo not in ('PT409', '42501', '23514', 'P0001') then
        v_mensaje := 'No se pudo enviar. Vuelve a intentarlo.';
      end if;
      -- El título, sólo de lo que quien llama ve.
      select x.titulo into v_titulo from public.vehiculos x where x.id = e.id and public.puede_vehiculo(x.id, 'vehiculos.ver');
      v_rechazados := v_rechazados || jsonb_build_object('id', e.id, 'titulo', v_titulo, 'codigo', v_codigo, 'motivo', v_mensaje);
    end;
  end loop;

  if jsonb_array_length(v_enviados) = 0 then
    delete from public.lotes_papelera l where l.id = v_lote;
    return jsonb_build_object('lote', null, 'actualizado_en', null, 'enviados', v_enviados, 'rechazados', v_rechazados);
  end if;
  update public.lotes_papelera l
  set resumen = jsonb_build_object('cantidad', jsonb_array_length(v_enviados), 'restaurados', 0, 'purgados', 0)
  where l.id = v_lote;
  v_version := public._lote_papelera_tocar(v_lote);
  perform public.registrar_actividad('papelera.enviado', 'lotes_papelera', v_lote::text, null, null,
    jsonb_build_object('tipo', 'vehiculos', 'cantidad', jsonb_array_length(v_enviados)));
  return jsonb_build_object('lote', v_lote, 'actualizado_en', v_version, 'enviados', v_enviados, 'rechazados', v_rechazados);
end;
$_$;


ALTER FUNCTION "public"."vehiculos_papelera_enviar"("p_vehiculos" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculos_papelera_listar"("p_antes_en" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_antes_id" "uuid" DEFAULT NULL::"uuid", "p_hacia_atras" boolean DEFAULT false, "p_tope" integer DEFAULT 6, "p_primeros" integer DEFAULT 20) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_dias int; v_todo boolean; v_yo uuid := (select auth.uid()); v_n int := public._acotar_pagina(p_tope, 6, 51);
        v_primeros int := public._acotar_pagina(p_primeros, 20, 200); v_ids uuid[];
begin
  perform public.assert_activo();
  select e.papelera_dias into v_dias from public.ajustes_empresa e where e.id = 1;
  v_todo := public.tiene_permiso('vehiculos.papelera.purgar');
  if p_antes_en is null then
    v_ids := array(select l.id from public.lotes_papelera l
      where l.tipo = 'vehiculos' and l.purgado_en is null and l.restaurado_en is null
        and (v_todo or l.creado_por = v_yo)
        and exists (select 1 from public.vehiculos v where v.lote_papelera_id = l.id and v.eliminado_en is not null)
      order by l.creado_en desc, l.id desc limit v_n);
  elsif not coalesce(p_hacia_atras, false) then
    v_ids := array(select l.id from public.lotes_papelera l
      where l.tipo = 'vehiculos' and l.purgado_en is null and l.restaurado_en is null
        and (v_todo or l.creado_por = v_yo)
        and (l.creado_en, l.id) < (p_antes_en, p_antes_id)
        and exists (select 1 from public.vehiculos v where v.lote_papelera_id = l.id and v.eliminado_en is not null)
      order by l.creado_en desc, l.id desc limit v_n);
  else
    v_ids := array(select l.id from public.lotes_papelera l
      where l.tipo = 'vehiculos' and l.purgado_en is null and l.restaurado_en is null
        and (v_todo or l.creado_por = v_yo)
        and (l.creado_en, l.id) > (p_antes_en, p_antes_id)
        and exists (select 1 from public.vehiculos v where v.lote_papelera_id = l.id and v.eliminado_en is not null)
      order by l.creado_en, l.id limit v_n);
  end if;
  return coalesce((
    select jsonb_agg(public._vehiculos_papelera_lote_json(l, v_dias, v_yo, v_primeros) order by o.ord)
    from unnest(v_ids) with ordinality o (id, ord) join public.lotes_papelera l on l.id = o.id), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."vehiculos_papelera_listar"("p_antes_en" timestamp with time zone, "p_antes_id" "uuid", "p_hacia_atras" boolean, "p_tope" integer, "p_primeros" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculos_papelera_lote"("p_lote" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_dias int; v_todo boolean; v_yo uuid := (select auth.uid()); l public.lotes_papelera;
begin
  perform public.assert_activo();
  select e.papelera_dias into v_dias from public.ajustes_empresa e where e.id = 1;
  v_todo := public.tiene_permiso('vehiculos.papelera.purgar');
  select * into l from public.lotes_papelera x
   where x.id = p_lote and x.tipo = 'vehiculos' and x.purgado_en is null and x.restaurado_en is null
     and (v_todo or x.creado_por = v_yo)
     and exists (select 1 from public.vehiculos y where y.lote_papelera_id = x.id and y.eliminado_en is not null);
  if not found then
    return null;
  end if;
  return public._vehiculos_papelera_lote_json(l, v_dias, v_yo, null);
end;
$$;


ALTER FUNCTION "public"."vehiculos_papelera_lote"("p_lote" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculos_papelera_purgar"("p_lote" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_vehiculos" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare l public.lotes_papelera;
begin
  perform public.assert_activo();
  if not public.tiene_permiso('vehiculos.papelera.purgar') then
    raise exception 'No tienes permiso para purgar la papelera.' using errcode = '42501';
  end if;
  select * into l from public.lotes_papelera x where x.id = p_lote and x.tipo = 'vehiculos' for update;
  if not found then
    raise exception 'Ese lote ya no está en la papelera.' using errcode = 'PT409';
  end if;
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  if l.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._conflicto_de_edicion('lotes_papelera', l.id, l.actualizado_en, 'este lote de la papelera');
  end if;
  return public._papelera_purgar_vehiculos(l.id, p_vehiculos);
end;
$$;


ALTER FUNCTION "public"."vehiculos_papelera_purgar"("p_lote" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_vehiculos" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculos_papelera_restaurar"("p_lote" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_vehiculos" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  l public.lotes_papelera; v public.vehiculos; v_mensaje text; v_campo text; v_quedan int; v_version timestamptz;
  v_restaurados jsonb := '[]'::jsonb; v_pendientes jsonb := '[]'::jsonb;
begin
  perform public.assert_activo();
  select * into l from public.lotes_papelera x where x.id = p_lote and x.tipo = 'vehiculos' for update;
  if not found then
    raise exception 'Ese lote ya no está en la papelera.' using errcode = 'PT409';
  end if;
  if l.creado_por is distinct from (select auth.uid()) and not public.tiene_permiso('vehiculos.papelera.purgar') then
    raise exception 'Sólo lo restaura quien lo envió o quien puede vaciar la papelera.' using errcode = '42501';
  end if;
  if p_actualizado_en_esperado is null then
    raise exception 'Falta la versión que tenías en pantalla. Recarga e intenta de nuevo.';
  end if;
  if l.actualizado_en is distinct from p_actualizado_en_esperado then
    perform public._conflicto_de_edicion('lotes_papelera', l.id, l.actualizado_en, 'este lote de la papelera');
  end if;

  for v in
    select * from public.vehiculos x
    where x.lote_papelera_id = l.id and x.eliminado_en is not null and (p_vehiculos is null or x.id = any (p_vehiculos))
    order by x.id for update
  loop
    begin
      perform public._vehiculo_sin_repetidos(v);
      update public.vehiculos x
      set eliminado_en = null, eliminado_por = null, lote_papelera_id = null, publicado_web = false, destacado_web = false
      where x.id = v.id;
      update public.cotizaciones c set eliminado_en = null, eliminado_por = null, lote_papelera_id = null
      where c.lote_papelera_id = l.id and c.vehiculo_id = v.id;
      v_restaurados := v_restaurados || jsonb_build_object('id', v.id, 'numero', v.numero, 'titulo', v.titulo);
    exception when unique_violation then
      get stacked diagnostics v_mensaje = message_text, v_campo = pg_exception_hint;
      -- El VIN y el lote los dice `_vehiculo_sin_repetidos()`; cualquier otro choque habla en técnico.
      if coalesce(v_campo, '') not in ('vin', 'lote') then
        v_mensaje := 'Choca con otro registro que ya existe.';
      end if;
      v_pendientes := v_pendientes || jsonb_build_object('id', v.id, 'numero', v.numero, 'titulo', v.titulo, 'motivo', v_mensaje);
    end;
  end loop;

  if jsonb_array_length(v_restaurados) = 0 then
    return jsonb_build_object('actualizado_en', l.actualizado_en, 'restaurados', v_restaurados, 'pendientes', v_pendientes, 'quedan',
      (select count(*) from public.vehiculos x where x.lote_papelera_id = l.id and x.eliminado_en is not null));
  end if;
  select count(*) into v_quedan from public.vehiculos x where x.lote_papelera_id = l.id and x.eliminado_en is not null;
  update public.lotes_papelera x
  set resumen = x.resumen || jsonb_build_object('restaurados', coalesce((x.resumen ->> 'restaurados')::int, 0) + jsonb_array_length(v_restaurados)),
      restaurado_en = case when v_quedan = 0 then now() else x.restaurado_en end,
      restaurado_por = case when v_quedan = 0 then (select auth.uid()) else x.restaurado_por end
  where x.id = l.id;
  v_version := public._lote_papelera_tocar(l.id);
  perform public.registrar_actividad('papelera.restaurado', 'lotes_papelera', l.id::text, null, null,
    jsonb_build_object('cantidad', jsonb_array_length(v_restaurados)));
  return jsonb_build_object('actualizado_en', v_version, 'restaurados', v_restaurados, 'pendientes', v_pendientes, 'quedan', v_quedan);
end;
$$;


ALTER FUNCTION "public"."vehiculos_papelera_restaurar"("p_lote" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_vehiculos" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."vehiculos_para_lead"("p_lead" "uuid", "p_texto" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_texto text := nullif(btrim(left(coalesce(p_texto, ''), 60)), '');
  v_numero bigint;
  v_patron text;
begin
  if not public.puede_lead(p_lead, 'leads.ver') then
    return '[]'::jsonb;
  end if;
  if v_texto ~ '^#?[0-9]{1,12}$' then
    v_numero := ltrim(v_texto, '#')::bigint;
  end if;
  v_patron := '%' || replace(replace(replace(coalesce(v_texto, ''), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  return coalesce((
    select jsonb_agg(public._vehiculo_resumen(v) || jsonb_build_object(
             'vinculado_aqui', v.lead_id is not distinct from p_lead,
             'vinculado_a_otro', v.lead_id is not null and v.lead_id <> p_lead,
             'otro_lead', case when v.lead_id is not null and v.lead_id <> p_lead then
                            (select jsonb_build_object('nombre', l.nombre, 'numero', g.numero, 'numero_propio', np.numero)
                              from public.leads l
                              left join public.leads_numeros_globales g on g.lead_id = l.id
                              left join public.leads_numeros_propios np on np.lead_id = l.id
                             where l.id = v.lead_id) end,
             'reemplazable', v.lead_id is not null and v.lead_id <> p_lead and public.puede_actuar_lead(v.lead_id, 'leads.editar'),
             'interesado', exists (select 1 from public.vehiculos_interesados i where i.vehiculo_id = v.id and i.lead_id = p_lead))
           order by v.creado_en desc, v.id desc)
      from (select * from public.vehiculos x
             where v_texto is null
                or x.numero = v_numero
                or x.titulo ilike v_patron or x.vin ilike v_patron or x.lote ilike v_patron
             order by x.creado_en desc, x.id desc
             -- Uno de más: la pantalla dice «Mostrando los primeros 20» y que escribir afina (cierre 1).
             limit 21) v), '[]'::jsonb);
end;
$_$;


ALTER FUNCTION "public"."vehiculos_para_lead"("p_lead" "uuid", "p_texto" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."vehiculos_para_lead"("p_lead" "uuid", "p_texto" "text") IS 'Hasta 20 vehículos que quien mira ve (por título, VIN, lote o #número), con su estado frente al lead. De invocador.';



CREATE OR REPLACE FUNCTION "public"."vehiculos_repetidos"("p_origen" "uuid", "p_claves" "jsonb") RETURNS TABLE("posicion" integer, "vehiculo_id" "uuid", "visible" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare k jsonb; i int := 0; v_id uuid; v_vin text; v_lote text; v_plat text;
begin
  perform public.assert_permiso('vehiculos.crear', p_origen);
  if jsonb_typeof(p_claves) is distinct from 'array' or jsonb_array_length(p_claves) > 100 then
    raise exception 'Las claves a revisar tienen que ser una lista de hasta 100.' using errcode = '22023';
  end if;
  for k in select * from jsonb_array_elements(p_claves) loop
    i := i + 1;
    v_id := null;
    v_vin := nullif(upper(btrim(k ->> 'vin')), '');
    v_lote := nullif(btrim(k ->> 'lote'), '');
    v_plat := nullif(lower(btrim(k ->> 'plataforma')), '');
    if v_vin is not null then
      select x.id into v_id from public.vehiculos x where x.vin = v_vin and x.eliminado_en is null limit 1;
    end if;
    if v_id is null and v_lote is not null then
      select x.id into v_id from public.vehiculos x
      where x.origen_id = p_origen and x.lote = v_lote and x.eliminado_en is null
        and (v_plat is null or x.plataforma is not distinct from v_plat) limit 1;
    end if;
    if v_id is not null then
      posicion := i;
      visible := public.puede_vehiculo(v_id, 'vehiculos.ver');
      vehiculo_id := case when visible then v_id end;
      return next;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."vehiculos_repetidos"("p_origen" "uuid", "p_claves" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verificar_telefono"("p_cc" "text", "p_tel" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform public.assert_permiso('leads.crear');
  return public._lead_verificar(public.normalizar_telefono(
    coalesce(nullif(btrim(p_cc), ''), (select e.telefono_cc from public.ajustes_empresa e where e.id = 1)), p_tel));
end;
$$;


ALTER FUNCTION "public"."verificar_telefono"("p_cc" "text", "p_tel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verificar_telefono_de_lead"("p_lead" "uuid", "p_cc" "text", "p_tel" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare l public.leads; v_tel text; v jsonb;
begin
  perform public.assert_activo();
  if not public.puede_actuar_lead(p_lead, 'leads.editar') then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;
  select * into l from public.leads x where x.id = p_lead and x.eliminado_en is null;
  if not found then
    raise exception 'No encontramos este lead o no tienes acceso.' using errcode = '42501';
  end if;
  v_tel := public.normalizar_telefono(
    coalesce(nullif(btrim(p_cc), ''), (select e.telefono_cc from public.ajustes_empresa e where e.id = 1)), p_tel);
  if v_tel = l.telefono_principal then
    return jsonb_build_object('estado', 'mismo');
  end if;
  v := public._lead_verificar(v_tel, l.id);
  if (v ->> 'estado') = 'libre'
     and exists (select 1 from public.leads_telefonos t where t.lead_id = l.id and t.telefono = v_tel) then
    v := v || jsonb_build_object('es_extra', true);
  end if;
  return v;
end;
$$;


ALTER FUNCTION "public"."verificar_telefono_de_lead"("p_lead" "uuid", "p_cc" "text", "p_tel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."visita_registrar"("p_tipo" "text", "p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_yo constant uuid := (select auth.uid());
  v_corte record;
begin
  if v_yo is null then
    raise exception 'Necesitas iniciar sesión.' using errcode = '42501';
  end if;
  if p_tipo is null or p_tipo not in ('lead', 'vehiculo', 'cotizacion') then
    raise exception 'Ese tipo de visita no existe.' using errcode = '22023', hint = 'tipo';
  end if;
  if p_id is null then
    raise exception 'Falta qué se visitó.' using errcode = '22023', hint = 'id';
  end if;
  -- La fila propia, por la PK (usuario_id, tipo, referencia_id). No mira si la entidad se ve: no revela nada y la lectura la pasa por su RLS.
  insert into public.visitados (usuario_id, tipo, referencia_id, visto_en)
  values (v_yo, p_tipo, p_id, now())
  on conflict (usuario_id, tipo, referencia_id) do update set visto_en = excluded.visto_en;
  -- El tope: la 51.ª más nueva (por `visitados_usuario_visto_idx`, sin offset ni count) y todas las más viejas que ella se van.
  select x.visto_en, x.tipo, x.referencia_id into v_corte
    from (select v.visto_en, v.tipo, v.referencia_id, row_number() over (order by v.visto_en desc, v.tipo desc, v.referencia_id desc) as n
            from public.visitados v
           where v.usuario_id = v_yo
           order by v.visto_en desc, v.tipo desc, v.referencia_id desc
           limit 51) x
   where x.n = 51;
  if found then
    delete from public.visitados v
     where v.usuario_id = v_yo
       and (v.visto_en, v.tipo, v.referencia_id) <= (v_corte.visto_en, v_corte.tipo, v_corte.referencia_id);
  end if;
end $$;


ALTER FUNCTION "public"."visita_registrar"("p_tipo" "text", "p_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."visita_registrar"("p_tipo" "text", "p_id" "uuid") IS 'Registra que quien llama abrió un lead, un vehículo o una cotización (7.12): upsert de su fila de visitados y a lo sumo 50 por persona (se van las más viejas). Invocadora: la RLS de visitados ata todo a (select auth.uid()). Sin sesión, 42501; tipo o id inválidos, 22023 con hint. La llamará <RegistrarVisita> en las fichas (7.13).';



CREATE OR REPLACE FUNCTION "public"."vitrina_del_origen"("p_origen" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select jsonb_build_object(
    'web_activa', exists (select 1 from public.integraciones i where i.clave = 'web_publica' and i.activa),
    'origen_activo', o.activo,
    'origen_visible', o.id = any (w.origenes_visibles),
    'fases_que_publican', coalesce((
      select jsonb_agg(f.id order by f.orden, f.id) from public.fases f join public.flujos fl on fl.id = f.flujo_id
      where fl.origen_id = o.id and fl.ambito = 'vehiculos' and f.publica_web and f.activa), '[]'::jsonb))
  from public.origenes o cross join public.ajustes_web w
  where o.id = p_origen and w.id = 1 and public.tiene_permiso('vehiculos.ver', o.id);
$$;


ALTER FUNCTION "public"."vitrina_del_origen"("p_origen" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."web_ajustes_guardar"("p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_sitio constant text[] := array['nombre_sitio', 'lema', 'whatsapp_respaldo', 'horario', 'redes', 'mostrar_moneda_secundaria',
                                   'origenes_visibles', 'legales', 'seo', 'direccion_publica'];
  v_cola constant text[] := array['cola_activa', 'ttl_contacto_minutos', 'dias_pegajoso', 'max_abiertas_default', 'max_intentos'];
  v_objetos constant text[] := array['redes', 'seo', 'origenes_visibles', 'legales'];
  k text;
  v_valor jsonb;
  w public.ajustes_web;
  n public.ajustes_web;
  v_fila jsonb;
begin
  perform public.assert_activo();
  if jsonb_typeof(p_cambios) is distinct from 'object' then
    raise exception 'Los cambios no tienen un formato válido.' using errcode = '22023', hint = 'cambios';
  end if;
  for k in select jsonb_object_keys(p_cambios) loop
    if not (k = any (v_sitio || v_cola)) then
      raise exception 'No se cambia «%».', k using errcode = '22023', hint = k;
    end if;
  end loop;

  -- C10 · permisos por grupo: web.ajustes.gestionar cubre los dos.
  if exists (select 1 from jsonb_object_keys(p_cambios) c where c = any (v_sitio)) then
    perform public.assert_permiso('web.ajustes.gestionar');
  end if;
  if exists (select 1 from jsonb_object_keys(p_cambios) c where c = any (v_cola))
     and not public.tiene_permiso('web.ajustes.gestionar')
     and not public.tiene_permiso('web.cola.gestionar') then
    raise exception 'No tienes permiso para cambiar la política de la cola.' using errcode = '42501';
  end if;

  select * into w from public.ajustes_web where id = 1 for update;
  perform public._exigir_version(w.actualizado_en, p_actualizado_en_esperado,
    'Alguien cambió los ajustes de la web mientras los veías. Recarga para seguir.');

  -- C11 · cada clave, validada y normalizada, sobre una copia de la fila.
  v_fila := to_jsonb(w);
  for k, v_valor in select e.key, e.value from jsonb_each(p_cambios) e loop
    v_fila := jsonb_set(v_fila, array[k], case
      when k = any (v_objetos) then public._web_ajustes_objeto(k, v_valor, v_fila -> k)
      else public._web_ajustes_valor(k, v_valor) end);
  end loop;
  n := jsonb_populate_record(w, v_fila);
  if n is not distinct from w then
    return w.actualizado_en;
  end if;

  update public.ajustes_web set
    nombre_sitio = n.nombre_sitio, lema = n.lema, whatsapp_respaldo = n.whatsapp_respaldo, horario = n.horario, redes = n.redes,
    mostrar_moneda_secundaria = n.mostrar_moneda_secundaria, origenes_visibles = n.origenes_visibles, legales = n.legales, seo = n.seo,
    direccion_publica = n.direccion_publica, cola_activa = n.cola_activa, ttl_contacto_minutos = n.ttl_contacto_minutos,
    dias_pegajoso = n.dias_pegajoso, max_abiertas_default = n.max_abiertas_default, max_intentos = n.max_intentos,
    actualizado_por = (select auth.uid())
   where id = 1
  returning actualizado_en into w.actualizado_en;
  return w.actualizado_en;
end;
$$;


ALTER FUNCTION "public"."web_ajustes_guardar"("p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."web_ajustes_guardar"("p_actualizado_en_esperado" timestamp with time zone, "p_cambios" "jsonb") IS 'Guarda los ajustes de la web: claves ausentes no cambian. Sitio: web.ajustes.gestionar; política de la cola: web.cola.gestionar o web.ajustes.gestionar. PT409 con versión vieja. Devuelve la versión. 8.01-1.';



