CREATE OR REPLACE FUNCTION "public"."web_revalidar_correr"() RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v public.integraciones;
  v_url text;
  v_secreto text;
  v_etiquetas text[];
  v_puede boolean;
begin
  select * into v from public.integraciones i where i.clave = 'web_publica';
  v_url := nullif(btrim(coalesce(v.config ->> 'revalidar_url', '')), '');
  v_puede := coalesce(v.activa, false) and v_url is not null and v_url ~* '^https://';
  if v_puede then
    v_secreto := nullif(btrim(coalesce(public.integracion_secreto('web_publica'), '')), '');
    v_puede := v_secreto is not null;
  end if;
  if not v_puede then
    -- Lo pendiente se queda; sólo se borran las filas repetidas (todas las que se ven están confirmadas: queda la más vieja de cada etiqueta).
    delete from interno.web_revalidar_pendiente a
    where exists (
      select 1 from interno.web_revalidar_pendiente b where b.etiqueta = a.etiqueta and b.id < a.id
    );
    return null;
  end if;
  -- Borra sólo lo confirmado que ve; lo que otra transacción todavía no confirma queda para el minuto siguiente.
  with enviadas as (
    delete from interno.web_revalidar_pendiente returning etiqueta
  )
  select coalesce(array_agg(distinct e.etiqueta order by e.etiqueta), '{}') into v_etiquetas from enviadas e;
  if cardinality(v_etiquetas) = 0 then
    return null;
  end if;
  return net.http_post(
    url => v_url,
    body => jsonb_build_object('etiquetas', to_jsonb(v_etiquetas)),
    headers => jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_secreto),
    timeout_milliseconds => 5000
  );
end $$;


ALTER FUNCTION "public"."web_revalidar_correr"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."web_revalidar_correr"() IS 'El job web-revalidar: si web_publica está activa, con dirección https:// y secreto, manda las etiquetas pendientes al sitio (secreto sólo en la cabecera) y vacía la cola; si no, no envía ni pierde nada.';



CREATE OR REPLACE FUNCTION "public"."web_testimonio_consentir"("p_testimonio" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_canal" "text", "p_ciudad" boolean, "p_vehiculo" boolean, "p_foto" boolean) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare t public.web_testimonios; v_canal text := btrim(p_canal);
begin
  perform public.assert_permiso('web.contenido.gestionar');
  select * into t from public.web_testimonios where id = p_testimonio for update;
  if not found then
    raise exception 'No encontramos este testimonio.' using errcode = 'P0002';
  end if;
  perform public._exigir_version(t.actualizado_en, p_actualizado_en_esperado,
    'Alguien cambió este testimonio mientras lo veías. Recarga para seguir.');
  if v_canal is null or char_length(v_canal) not between 1 and 80 then
    raise exception 'Escribe por qué canal dio su consentimiento.' using errcode = '22023', hint = 'canal';
  end if;
  if p_ciudad is null or p_vehiculo is null or p_foto is null then
    raise exception 'Di si consintió mostrar la ciudad, el vehículo y la foto.' using errcode = '22023', hint = 'consentimiento';
  end if;
  update public.web_testimonios set
    consent_por = (select auth.uid()), consent_en = now(), consent_canal = v_canal,
    consent_ciudad = p_ciudad, consent_vehiculo = p_vehiculo, consent_foto = p_foto, consent_retirado_en = null
   where id = p_testimonio
  returning actualizado_en into t.actualizado_en;
  return t.actualizado_en;
end;
$$;


ALTER FUNCTION "public"."web_testimonio_consentir"("p_testimonio" "uuid", "p_actualizado_en_esperado" timestamp with time zone, "p_canal" "text", "p_ciudad" boolean, "p_vehiculo" boolean, "p_foto" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."web_testimonio_exigir_consentimiento"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and old.consent_por is not null
     and (new.cliente is distinct from old.cliente or new.texto is distinct from old.texto or new.foto_ruta is distinct from old.foto_ruta) then
    new.consent_por := null;
    new.consent_en := null;
    new.consent_canal := null;
    new.consent_ciudad := false;
    new.consent_vehiculo := false;
    new.consent_foto := false;
    new.consent_retirado_en := null;
    new.publicado := false;
  end if;
  -- La ciudad o el vehículo que cambian no salen con un consentimiento dado para otros.
  if tg_op = 'UPDATE' and new.ciudad is distinct from old.ciudad then
    new.consent_ciudad := false;
  end if;
  if tg_op = 'UPDATE' and new.vehiculo is distinct from old.vehiculo then
    new.consent_vehiculo := false;
  end if;
  if new.publicado
     and (new.consent_por is null or new.consent_en is null or new.consent_canal is null or new.consent_retirado_en is not null) then
    raise exception 'Falta registrar el consentimiento.' using errcode = '22023', hint = 'publicado';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."web_testimonio_exigir_consentimiento"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."web_testimonio_retirar"("p_testimonio" "uuid", "p_actualizado_en_esperado" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare t public.web_testimonios;
begin
  perform public.assert_permiso('web.contenido.gestionar');
  select * into t from public.web_testimonios where id = p_testimonio for update;
  if not found then
    raise exception 'No encontramos este testimonio.' using errcode = 'P0002';
  end if;
  perform public._exigir_version(t.actualizado_en, p_actualizado_en_esperado,
    'Alguien cambió este testimonio mientras lo veías. Recarga para seguir.');
  if t.consent_por is null then
    raise exception 'Este testimonio no tiene un consentimiento registrado.' using errcode = '22023', hint = 'consentimiento';
  end if;
  if t.consent_retirado_en is not null then
    return t.actualizado_en;
  end if;
  update public.web_testimonios set consent_retirado_en = now(), publicado = false
   where id = p_testimonio
  returning actualizado_en into t.actualizado_en;
  return t.actualizado_en;
end;
$$;


ALTER FUNCTION "public"."web_testimonio_retirar"("p_testimonio" "uuid", "p_actualizado_en_esperado" timestamp with time zone) OWNER TO "postgres";


