CREATE OR REPLACE VIEW "public"."estado_cola_web" WITH ("security_invoker"='true') AS
 SELECT "q"."usuario_id",
    "p"."nombre",
    "p"."handle",
    "q"."habilitado",
    "q"."disponible",
    "q"."prioridad",
    "q"."orden",
    COALESCE("q"."max_abiertas", "w"."max_abiertas_default") AS "cupo",
    ( SELECT "count"(*) AS "count"
           FROM "public"."solicitudes_contacto_web" "s"
          WHERE (("s"."usuario_id" = "q"."usuario_id") AND ("s"."estado" = 'asignada'::"public"."estado_solicitud_web") AND (NOT "s"."es_directa"))) AS "abiertas",
    "q"."asignadas_total",
    "q"."contactadas_total",
    "q"."vencidas_total",
        CASE
            WHEN ("q"."asignadas_total" > 0) THEN "round"(((100.0 * ("q"."contactadas_total")::numeric) / ("q"."asignadas_total")::numeric), 1)
            ELSE NULL::numeric
        END AS "tasa_contacto_pct",
    "q"."ultima_asignacion_en"
   FROM (("public"."cola_web_asesores" "q"
     JOIN "public"."perfiles" "p" ON (("p"."id" = "q"."usuario_id")))
     CROSS JOIN "public"."ajustes_web" "w")
  WHERE (("w"."id" = 1) AND "p"."activo" AND "public"."puede_estar_en_la_rueda"("q"."usuario_id"));


ALTER VIEW "public"."estado_cola_web" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."etiquetas_vista" WITH ("security_invoker"='true') AS
 SELECT "id",
    "nombre",
    "color",
    "creado_en",
    "actualizado_en",
    (( SELECT "count"(*) AS "count"
           FROM ( SELECT 1 AS "?column?"
                   FROM ("public"."leads_etiquetas" "le"
                     JOIN "public"."leads" "l" ON (("l"."id" = "le"."lead_id")))
                  WHERE (("le"."etiqueta_id" = "e"."id") AND ("l"."eliminado_en" IS NULL))
                 LIMIT 1001) "q"))::integer AS "leads"
   FROM "public"."etiquetas" "e";


ALTER VIEW "public"."etiquetas_vista" OWNER TO "postgres";


COMMENT ON VIEW "public"."etiquetas_vista" IS 'Las etiquetas de quien mira, con a cuántos de los leads que ve están puestas, hasta 1.001 (la pantalla dice «más de 1.000»).';



CREATE TABLE IF NOT EXISTS "public"."eventos_destinatarios" (
