);


ALTER TABLE "public"."eventos_web" OWNER TO "postgres";


COMMENT ON TABLE "public"."eventos_web" IS 'Eventos anónimos de primera parte. NO guarda IP ni user agent. Se borra a los 12 meses.';



ALTER TABLE "public"."eventos_web" ALTER COLUMN "id" ADD GENERATED ALWAYS AS IDENTITY (
