CREATE TABLE IF NOT EXISTS "public"."fases_roles" (
    "fase_id" "uuid" NOT NULL,
    "rol_id" "uuid" NOT NULL
);


ALTER TABLE "public"."fases_roles" OWNER TO "postgres";


COMMENT ON TABLE "public"."fases_roles" IS 'Roles que pueden mover una unidad HASTA esta fase. Sin filas = cualquiera con flujos.mover del origen. Manda la lista de la transición si existe (fases_transiciones_roles). Se escribe sólo por fase_roles_poner().';



CREATE TABLE IF NOT EXISTS "public"."fases_transiciones" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "flujo_id" "uuid" NOT NULL,
    "de_fase_id" "uuid" NOT NULL,
