    "accion" "text",
    "nota_obligatoria" boolean DEFAULT false NOT NULL,
    CONSTRAINT "fases_transiciones_check" CHECK (("de_fase_id" <> "a_fase_id"))
);


ALTER TABLE "public"."fases_transiciones" OWNER TO "postgres";


COMMENT ON TABLE "public"."fases_transiciones" IS 'Las transiciones permitidas entre dos fases de un flujo, con la acción (el texto del botón) y la nota obligatoria. Se escribe sólo por transicion_crear(), transicion_guardar() y transicion_eliminar().';



CREATE TABLE IF NOT EXISTS "public"."fases_transiciones_roles" (
    "transicion_id" "uuid" NOT NULL,
    "rol_id" "uuid" NOT NULL
);


ALTER TABLE "public"."fases_transiciones_roles" OWNER TO "postgres";


COMMENT ON TABLE "public"."fases_transiciones_roles" IS 'Roles que pueden mover una unidad por esta transición. Si tiene filas, manda sobre la lista de la fase destino (fases_roles); sin filas, manda la de la fase. Se escribe sólo por transicion_roles_poner().';



CREATE TABLE IF NOT EXISTS "public"."flujos_reglas" (
