    "regla" "text" NOT NULL,
    "activa" boolean DEFAULT true NOT NULL,
    CONSTRAINT "flujos_reglas_regla_check" CHECK (("regla" = ANY (ARRAY['logistica'::"text", 'alerta_demora'::"text", 'vitrina_web'::"text", 'portal_cliente'::"text", 'transporte'::"text", 'contenedor'::"text", 'aduana'::"text", 'gastos'::"text", 'pagos'::"text", 'esperas'::"text"])))
);


ALTER TABLE "public"."flujos_reglas" OWNER TO "postgres";


COMMENT ON TABLE "public"."flujos_reglas" IS 'Capacidades del flujo soportadas por el CÓDIGO y encendidas por DATO. Sin fila = apagada. Una regla apagada no se puede marcar en ninguna fase (trigger). Se escribe sólo por flujo_regla_cambiar(); apagar con uso (fases marcadas o, en esperas, requisitos de espera) → 23514.';



CREATE TABLE IF NOT EXISTS "public"."flujos_transporte_oferta" (
    "flujo_id" "uuid" NOT NULL,
    "tipo" "text" NOT NULL,
    "puerto_id" "uuid",
    "naviera_id" "uuid",
    CONSTRAINT "flujos_transporte_oferta_check" CHECK ((("tipo" = 'naviera'::"text") = ("naviera_id" IS NOT NULL))),
    CONSTRAINT "flujos_transporte_oferta_check1" CHECK ((("tipo" <> 'naviera'::"text") = ("puerto_id" IS NOT NULL))),
    CONSTRAINT "flujos_transporte_oferta_tipo_check" CHECK (("tipo" = ANY (ARRAY['puerto_origen'::"text", 'puerto_destino'::"text", 'naviera'::"text"])))
);


ALTER TABLE "public"."flujos_transporte_oferta" OWNER TO "postgres";


COMMENT ON TABLE "public"."flujos_transporte_oferta" IS 'Qué puertos y navieras ofrecen los selectores de un flujo. Lista vacía = todo. Filtra lo ofrecido, nunca invalida lo guardado. Se escribe sólo por flujo_oferta_guardar() (reemplazo todo o nada, con la regla transporte encendida); se lee con flujo_oferta().';



CREATE TABLE IF NOT EXISTS "public"."historial_fases" (
    "id" bigint NOT NULL,
    "flujo_id" "uuid" NOT NULL,
    "vehiculo_id" "uuid",
    "repuesto_id" "uuid",
    "de_fase_id" "uuid",
    "a_fase_id" "uuid" NOT NULL,
