    "usuario_id" "uuid",
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "historial_fases_check" CHECK (("num_nonnulls"("vehiculo_id", "repuesto_id") = 1))
);


ALTER TABLE "public"."historial_fases" OWNER TO "postgres";


COMMENT ON TABLE "public"."historial_fases" IS 'Cada cambio de fase, con su nota interna. Lo escriben cambiar_fase() y, con de_fase_id nulo, vehiculo_crear() cuando el vehículo nace en la fase inicial. «Llegó a una fase» se calcula sobre esta tabla.';



ALTER TABLE "public"."historial_fases" ALTER COLUMN "id" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME "public"."historial_fases_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);



CREATE TABLE IF NOT EXISTS "public"."importaciones_filas" (
