    CONSTRAINT "importaciones_filas_fila_check" CHECK (("fila" > 0)),
    CONSTRAINT "importaciones_filas_motivo_check" CHECK (("char_length"("motivo") <= 500)),
    CONSTRAINT "importaciones_filas_resultado_check" CHECK (("resultado" = ANY (ARRAY['ya_existe'::"text", 'error'::"text"])))
);


ALTER TABLE "public"."importaciones_filas" OWNER TO "postgres";


COMMENT ON TABLE "public"."importaciones_filas" IS 'Las filas de una importación total que no entraron (ya_existe o error), con su campo y su motivo, para «Descargar las rechazadas». Las escriben sólo las RPC de importación; se lee con la regla de importaciones.';



CREATE TABLE IF NOT EXISTS "public"."importaciones_leads" (
    "importacion_id" "uuid" NOT NULL,
    "lead_id" "uuid" NOT NULL,
    "fila" integer NOT NULL,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "importaciones_leads_fila_check" CHECK (("fila" > 0))
);


ALTER TABLE "public"."importaciones_leads" OWNER TO "postgres";


COMMENT ON TABLE "public"."importaciones_leads" IS 'Lo que creó cada importación de leads (para deshacerla). Sin datos del archivo: sólo ids y el número de fila.';



CREATE TABLE IF NOT EXISTS "public"."importaciones_pases" (
    "pase" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "importacion_id" "uuid" NOT NULL,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "usado_en" timestamp with time zone
);


ALTER TABLE "public"."importaciones_pases" OWNER TO "postgres";


COMMENT ON TABLE "public"."importaciones_pases" IS 'Pases de un solo uso de la importación total (9.06): importacion_pase_emitir() o el job importaciones-continuar crean uno, la función importar-csv lo canjea con importacion_abrir() por el id de la importación (vale 10 minutos). Sólo service_role.';



CREATE TABLE IF NOT EXISTS "public"."leads_campos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "clave" "text" NOT NULL,
    "etiqueta" "text" NOT NULL,
    "tipo" "public"."tipo_campo" NOT NULL,
    "opciones" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "requerido" boolean DEFAULT false NOT NULL,
    "valor_defecto" "jsonb",
    "valor_defecto_empresa" "text",
    "grupo" "text",
    "orden" smallint DEFAULT 0 NOT NULL,
    "en_tabla" boolean DEFAULT false NOT NULL,
    "filtrable" boolean DEFAULT false NOT NULL,
    "solo_cartera" boolean DEFAULT false NOT NULL,
    "solo_cartera_pendiente" boolean,
    "es_sistema" boolean DEFAULT false NOT NULL,
    "activo" boolean DEFAULT true NOT NULL,
    "actualizado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    "minimo" numeric,
    "maximo" numeric,
    CONSTRAINT "leads_campos_clave_check" CHECK (("clave" ~ '^[a-z][a-z0-9_]{1,40}$'::"text")),
    CONSTRAINT "leads_campos_defecto_excluyente" CHECK ((("valor_defecto_empresa" IS NULL) OR (("valor_defecto" IS NULL) AND ("tipo" = 'texto'::"public"."tipo_campo")))),
    CONSTRAINT "leads_campos_rango_numerico" CHECK (((("minimo" IS NULL) AND ("maximo" IS NULL)) OR ("tipo" = ANY (ARRAY['numero'::"public"."tipo_campo", 'moneda'::"public"."tipo_campo"])))),
    CONSTRAINT "leads_campos_rango_orden" CHECK ((("minimo" IS NULL) OR ("maximo" IS NULL) OR ("minimo" <= "maximo"))),
    CONSTRAINT "leads_campos_tipo_de_lead" CHECK (("tipo" <> ALL (ARRAY['vin'::"public"."tipo_campo", 'lote'::"public"."tipo_campo"]))),
    CONSTRAINT "leads_campos_valor_defecto_empresa_check" CHECK (("valor_defecto_empresa" = ANY (ARRAY['ciudad'::"text", 'pais'::"text"])))
);


ALTER TABLE "public"."leads_campos" OWNER TO "postgres";


COMMENT ON TABLE "public"."leads_campos" IS 'Layout de campos de los leads: uno por despliegue, igual para prospectos y clientes. Lo que no es columna de leads (nombre, teléfono, tipo y origen) vive en leads.atributos, validado contra esta tabla por trigger. solo_cartera se recorta en la base (atributos_lead): quien ve el lead sin estar en la cartera no lo recibe. Distinta de una etiqueta, que es privada de cada persona.';



COMMENT ON COLUMN "public"."leads_campos"."solo_cartera_pendiente" IS 'A dónde va un cambio de privacidad que se aplica por lotes: true, a privado (solo_cartera sigue en false hasta quitar la clave de leads.atributos_publicos); false, a público (solo_cartera ya es false y se completa la copia). NULL: nada pendiente.';



COMMENT ON COLUMN "public"."leads_campos"."minimo" IS 'Rango (de un campo): el valor más chico que admite un número o un monto; null = sin límite.';



COMMENT ON COLUMN "public"."leads_campos"."maximo" IS 'Rango (de un campo): el valor más grande que admite un número o un monto; null = sin límite.';



CREATE OR REPLACE VIEW "public"."leads_cartera_vista" WITH ("security_invoker"='true') AS
 SELECT "la"."lead_id" AS "id",
    "v"."numero",
    "v"."nombre",
    "v"."telefono_cc",
    "v"."telefono_principal",
    true AS "telefono_visible",
    "v"."tipo_lead_id",
    "v"."origen_lead_id",
    "v"."atributos",
    "v"."creado_por",
    "v"."ultimo_seguimiento_en",
    "la"."lead_creado_en" AS "creado_en",
    "v"."actualizado_en",
    "v"."es_favorito",
    "v"."esta_tachado",
    "v"."dueno_id",
    true AS "en_cartera",
    "v"."etiquetas",
    "v"."numero_propio",
    "v"."numero_propio_de",
    "v"."numero_propio_creador",
    "v"."numero_visible",
    "v"."atributos_publicos",
    "la"."lead_reciente_en" AS "reciente_en"
   FROM ("public"."leads_asesores" "la"
     JOIN "public"."leads_vista" "v" ON (("v"."id" = "la"."lead_id")))
  WHERE (("la"."usuario_id" = ( SELECT "auth"."uid"() AS "uid")) AND ("la"."revocado_en" IS NULL));


ALTER VIEW "public"."leads_cartera_vista" OWNER TO "postgres";


COMMENT ON VIEW "public"."leads_cartera_vista" IS 'leads_vista de los leads que están en la cartera de quien mira («míos»), recorridos por su cartera (leads_asesores_listado_idx por el alta, leads_asesores_reciente_idx por lo reciente) y no por la tabla: cuesta lo que pesa la cartera de quien mira, no cuántos leads hay (cierre 5a-fix-1a). Mismas columnas que leads_vista; id, creado_en y reciente_en salen de la fila de la cartera (lead_creado_en y lead_reciente_en, copias que mantienen triggers) y en_cartera y telefono_visible son verdaderas por construcción. security_invoker: la regla de visibilidad (la policy de leads) se aplica igual. Lo que no es «míos» se lee de leads_vista.';



CREATE TABLE IF NOT EXISTS "public"."leads_contadores" (
    "usuario_id" "uuid" NOT NULL,
    "ultimo" integer DEFAULT 0 NOT NULL,
    CONSTRAINT "leads_contadores_ultimo_check" CHECK (("ultimo" >= 0))
);


ALTER TABLE "public"."leads_contadores" OWNER TO "postgres";


COMMENT ON TABLE "public"."leads_contadores" IS 'Último número propio asignado a cada creador. Tabla y no sequence: un rollback deshace el incremento y no deja un hueco, y el candado del renglón ordena a quienes crean a la vez. Nadie la lee ni la escribe más que el trigger de leads.';



ALTER TABLE "public"."leads" ALTER COLUMN "numero" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME "public"."leads_numero_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);



CREATE TABLE IF NOT EXISTS "public"."leads_telefonos" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
