);


ALTER TABLE "public"."limpieza_avisos" OWNER TO "postgres";


COMMENT ON TABLE "public"."limpieza_avisos" IS 'Un vehículo ya avisado antes de la limpieza automática (limpieza_avisar): se avisa una vez. fecha = el día de limpieza que se avisó. Interna: sólo service_role.';



CREATE TABLE IF NOT EXISTS "public"."limpieza_corridas" (
