);


ALTER TABLE "public"."limpieza_corridas" OWNER TO "postgres";


COMMENT ON TABLE "public"."limpieza_corridas" IS 'Una fila por noche (la de verdad; las parciales son de pruebas, acotadas a unos orígenes): cuántos vehículos movió la limpieza, cuántos dejó y por qué ancla, y cuántos quedaron para la noche siguiente. Sólo service_role y limpieza_ultima().';



CREATE TABLE IF NOT EXISTS "public"."mensajes" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "conversacion_id" "uuid" NOT NULL,
    "autor_id" "uuid" NOT NULL,
    "tipo" "public"."tipo_mensaje" DEFAULT 'texto'::"public"."tipo_mensaje" NOT NULL,
    "cuerpo" "text",
    "evento_id" "uuid",
    "tarea_id" "uuid",
    "vehiculo_id" "uuid",
    "lead_id" "uuid",
    "cotizacion_id" "uuid",
    "responde_a_id" "uuid",
    "editado_en" timestamp with time zone,
    "eliminado_en" timestamp with time zone,
    "creado_en" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "mensajes_check" CHECK (((("tipo" = 'texto'::"public"."tipo_mensaje") AND (("cuerpo" IS NOT NULL) OR ("eliminado_en" IS NOT NULL))) OR (("tipo" = 'evento'::"public"."tipo_mensaje") AND ("evento_id" IS NOT NULL)) OR (("tipo" = 'tarea'::"public"."tipo_mensaje") AND ("tarea_id" IS NOT NULL)) OR ("tipo" = ANY (ARRAY['vehiculo'::"public"."tipo_mensaje", 'lead'::"public"."tipo_mensaje", 'cotizacion'::"public"."tipo_mensaje"])))),
    CONSTRAINT "mensajes_eliminado_sin_cuerpo" CHECK ((("eliminado_en" IS NULL) OR ("cuerpo" IS NULL)))
);


ALTER TABLE "public"."mensajes" OWNER TO "postgres";


COMMENT ON TABLE "public"."mensajes" IS 'Mensajes. Una ficha (evento/tarea/vehículo/lead/cotización) NO amplía el alcance del lector: se hidrata bajo su propia RLS y muestra un placeholder si no accede.';



