);


ALTER TABLE "public"."mensajes_menciones" OWNER TO "postgres";


COMMENT ON TABLE "public"."mensajes_menciones" IS 'Menciones por # dentro del texto. Sin FK: la mención sobrevive a la purga y se pinta como «eliminado».';



