CREATE OR REPLACE VIEW "public"."recordatorios_vista" WITH ("security_invoker"='true') AS
 SELECT "r"."id",
    "r"."titulo",
    "r"."recordar_en",
    "r"."notificado_en",
    "r"."completado_en",
    "r"."creado_en",
    "r"."actualizado_en",
    "l"."id" AS "lead_id",
    "l"."nombre" AS "lead_nombre",
    ( SELECT "g"."numero"
           FROM "public"."leads_numeros_globales" "g"
          WHERE ("g"."lead_id" = "r"."lead_id")) AS "lead_numero",
    ( SELECT "np"."numero"
           FROM "public"."leads_numeros_propios" "np"
          WHERE ("np"."lead_id" = "r"."lead_id")) AS "lead_numero_propio",
    "v"."id" AS "vehiculo_id",
    "v"."titulo" AS "vehiculo_titulo",
    "v"."numero" AS "vehiculo_numero",
    (("r"."vehiculo_id" IS NOT NULL) AND ("v"."id" IS NULL)) AS "vehiculo_oculto"
   FROM (("public"."recordatorios" "r"
     LEFT JOIN "public"."leads" "l" ON (("l"."id" = "r"."lead_id")))
     LEFT JOIN "public"."vehiculos" "v" ON (("v"."id" = "r"."vehiculo_id")));


ALTER VIEW "public"."recordatorios_vista" OWNER TO "postgres";


