    CONSTRAINT "visitados_tipo_check" CHECK (("tipo" = ANY (ARRAY['lead'::"text", 'vehiculo'::"text", 'cotizacion'::"text", 'evento'::"text", 'tarea'::"text", 'proyecto_repuestos'::"text"])))
);


