  ('cotizaciones', 'cotizaciones', false, 26214400, '{application/pdf,image/jpeg,image/png,image/webp,application/vnd.openxmlformats-officedocument.wordprocessingml.document}'),
  ('documentos', 'documentos', false, 26214400, '{application/pdf,image/jpeg,image/png,image/webp,video/mp4,application/msword,application/vnd.openxmlformats-officedocument.wordprocessingml.document}'),
  ('importaciones', 'importaciones', false, 52428800, '{text/csv,text/plain}'),
  ('marca', 'marca', true, 2097152, '{image/png,image/jpeg,image/webp,image/svg+xml}'),
