set session_replication_role = origin;

-- Los secretos de Vault que nacen al azar (32 bytes, una sola vez)
do $$
begin
  if not exists (select 1 from vault.secrets s where s.name = 'cotizacion:abierta') then
    perform vault.create_secret(new_secret => encode(extensions.gen_random_bytes(32), 'hex'), new_name => 'cotizacion:abierta',
                                new_description => 'Clave que firma la hoja abierta de cotizar (4.13-3a)');
  end if;
end $$;
do $$
begin
  if not exists (select 1 from vault.secrets s where s.name = 'portal:sal') then
    perform vault.create_secret(new_secret => encode(extensions.gen_random_bytes(32), 'hex'), new_name => 'portal:sal',
                                new_description => 'Sal de la huella del límite por IP del portal (8.07-1): la IP no se guarda');
  end if;
end $$;

